window.S34A_TOPICS = [{"id":"s34a-4","tg":4,"name":"Umgang mit Menschen","color":"var(--stack-blue)","meta":{"relevanz":"Hoch","schriftlich":"16 Fragen · 16/100 Punkte","muendlich":"Schwerpunkt (ca. 30%)"},"merksaetze":[],"blocks":[{"n":1,"title":"Grundlagen & Bedeutung","subtitle":"2 Konzepte · 18 Prüfungsfragen","cards":[{"h":"Begriff „Umgang mit Menschen“","b":"Angemessenes Verhalten beim Einwirken auf andere unter Beachtung ihrer Persönlichkeit und Bedürfnisse","detail":{"titel":"Begriff: Umgang mit Menschen","kat":"Grundlagen · Begriff","katCls":"mensch","merksatz":"„Umgang mit Menschen“ ist das nach Gesellschaftsnormen angemessene Verhalten beim Einwirken auf andere Menschen unter Beachtung ihrer Persönlichkeit und Bedürfnisse. Es ist das wichtigste „Werkzeug“ der Sicherheitskraft.","funktion":["Definition: angemessenes, an Gesellschaftsnormen orientiertes Verhalten beim Einwirken auf andere – immer mit Blick auf deren Persönlichkeit und Bedürfnisse.","Anwendungsfelder im Dienst: Auskunft erteilen, Besucher- und Kundenkontakte, Kontrolle Verdächtiger, Anordnungen treffen, Konflikte zwischen Dritten schlichten.","Kernkompetenz: situations- und personengerecht aus einer breiten Palette die passende Verhaltensweise auswählen können."],"schutzziel":"Konflikte, Gewalt und Straftaten durch richtiges Verhalten von vornherein vermeiden.","kennwerte":[{"l":"Definition","v":"angemessenes Einwirken auf Menschen"},{"l":"Maßstab","v":"Persönlichkeit + Bedürfnisse beachten"},{"l":"Felder","v":"Auskunft · Kontrolle · Konflikt · Kunde"}],"begriffe":["Einwirken = bewusst auf das Verhalten oder Erleben eines anderen Menschen Einfluss nehmen.","Gesellschaftsnormen = die in einer Gesellschaft anerkannten Regeln für angemessenes Verhalten."],"abgrenzung":["Die Haltung „so bin ich halt“ ist fehl am Platz: Gefragt ist Anpassungsfähigkeit, nicht ein starrer eigener Stil.","Umgang mit Menschen ist mehr als Höflichkeit – es ist gezieltes, situationsgerechtes Verhalten."],"praxis":["Ob Einlasskontrolle, Streife oder Beschwerde: Der Ton und das Verhalten der Wachperson entscheiden oft über Einsicht oder Eskalation.","Wer Persönlichkeit und Bedürfnisse des Gegenübers beachtet, erreicht sein Ziel meist ohne Zwang."]},"visual":null},{"h":"Bedeutung für den SMA","b":"Richtiges Verhalten verhindert Konflikte, Gewalt- und Straftaten; passende Verhaltensweise wählen statt „so bin ich halt“","detail":{"titel":"Bedeutung für den SMA","kat":"Grundlagen · Bedeutung","katCls":"mensch","merksatz":"Für die Sicherheitskraft (SMA = Sicherheitsmitarbeiter) ist der gute Umgang mit Menschen das ENTSCHEIDENDE Mittel: Durch richtiges Verhalten lassen sich viele Konflikte, Gewalt- und Straftaten von vornherein verhindern.","funktion":["Wirkung: Richtiges Verhalten beugt Konflikten, Gewalt und Straftaten vor – oft wirksamer als jede Zwangsmaßnahme.","Anforderung: Der SMA soll sich auf Situation und Person einstellen und aus einer breiten Palette die angemessene Verhaltensweise wählen.","Grundlage: Um Verhalten zu verstehen und zu beeinflussen, muss man seinen Ursprung kennen – die Bedürfnisse des Menschen."],"schutzziel":"Sicherheit primär durch Kommunikation und Verhalten herstellen, nicht durch Eskalation.","kennwerte":[{"l":"SMA","v":"Sicherheitsmitarbeiter"},{"l":"Nutzen","v":"verhindert Konflikte/Gewalt/Straftaten"},{"l":"Können","v":"passende Verhaltensweise wählen"}],"begriffe":["SMA = Sicherheitsmitarbeiter (auch: Wach- und Sicherheitskraft).","Palette an Verhaltensweisen = die Bandbreite möglicher Reaktionen, aus der situationsgerecht gewählt wird."],"abgrenzung":["„So bin ich halt“ ist als Haltung untauglich – professionell heißt, das eigene Verhalten bewusst zu steuern.","Deeskalation und Prävention durch Verhalten gehen dem Einsatz von Zwangsmitteln vor."],"praxis":["Eine freundlich-bestimmte Ansage an der Tür verhindert oft die Eskalation, die ein barscher Befehl auslösen würde.","Wer Menschen ernst nimmt, erreicht Kooperation – und muss seltener zu rechtlichen Mitteln greifen."]},"visual":null}],"quiz":[{"q":"Was zeichnet professionelle Wachpersonen aus?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Voreingenommenheit","c":false},{"t":"Teamfähigkeit","c":true},{"t":"Einfühlungsvermögen","c":true},{"t":"Dominantes Auftreten","c":false}]},{"q":"Wann verhalten sich Wachpersonen professionell?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wenn sie autoritär auftreten und entsprechend handeln","c":false},{"t":"Wenn sie grundsätzlich auf ihrem Standpunkt beharren","c":false},{"t":"Wenn sie rechthaberisch auftreten","c":false},{"t":"Wenn sie kundenorientiert und angemessen handeln","c":true}]},{"q":"Was ist für das Bewachungsgewerbe Psychologie?","a":"Die Lehre vom (sichtbaren) Verhalten und (nicht sichtbarem) Erleben der Menschen. Psychologen erforschen, warum eine bestimmte Person in einer bestimmten Situation ein bestimmtes Verhalten anzeigt – und welche inneren und äußeren Vorgänge dabei ablaufen. Die Bedeutung für das Bewachungsgewerbe, liegt darin Fehlurteile zu vermeiden und mögliche Gefahrensituationen vorausschauen zu können • Verhalten ist das, was sichtbar und hörbar ist: Gestik, Mimik, Sprechen, Weinen usw. • Erleben ist alles, was unsichtbar bleibt: Denken, Wahrnehmen, Gefühle, Triebe usw.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Umgang mit Menschen?","a":"Beim Umgang mit Menschen ist es sinnvoll Grundzüge menschlichen Verhaltens, Reaktionen, Emotionen und andere Faktoren zu kennen. Im Umgang mit Menschen können Gefahren erkannt werden bevor diese entstehen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre Menschenkenntnis und wie kann man sich","a":"diese aneignen? Menschenkenntnis ist wie ich andere Menschen einschätze, man erlangt diese durch Erfahrung und Umgang mit Menschen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind Vorurteile und wie entstehen Vorurteile?","a":"Vorurteile ist ungeprüfte Meinungen die man anderen Menschen oder Sachen gegenüber hat, diese entstehen durch eigene Erfahrung, durch Verallgemeinerung durch andere und auch durch Medien; Vorurteile können in bestimmten Situationen aber auch positiv sein (Schutzwirkung).","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind Bedürfnisse, erklären nach der Bedürfnispyramide?","a":"Bedürfnisse sind der Ausgangs- und Zielpunkt unseres gesamten Strebens und Handelns - Grundbedürfnis, Hunger, Durst, Schlaf, Selbsterhaltung (Sexualität wollen die Prüfer/IHK Dortmund nicht hören) - Sicherheitsbedürfnis, Wohnung, soziale Absicherung, Arbeit - Sozialbedürfnis, Kontakt zu anderen Menschen, Vereinen - Soziale Anerkennung (Ich Anerkennung), Selbstachtung, Wertschätzung durch andere - Selbstverwirklichung, Selbstentfaltung… Hier am besten an Robinson Crusoe denken!!!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Aggression bzw. eine Aggressionsverschiebung?","a":"Ist ein Verhalten, das darauf abzielt, andere Menschen und deren Interessen zu verletzen oder zu zerstören, entweder körperlich oder verbal Aggressionsverschiebung - gegen andere Dinge oder Menschen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist Panik, nenne die 4 Panikarten.","a":"Panik entsteht wenn durch überraschendes Auftreten ein Zustand von Furcht und Schrecken unter Menschen auftritt und zu unkontrolliertem Handeln führt. - Panikstimmung, etwas wird oder könnte gleich geschehen - Panikereignis, es ist etwas geschehen (Knall, Feuer, Gasgeruch...) - Paniksturm, der Überlebensinstinkt wird aktiv, vernunftlose Fluchtreaktion - Panikstarre, man kann sich nicht mehr bewegen oder klar denken (man Erstarrt)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist ein Flaschenhalseffekt, wie entwickelt sich Staudruck?","a":"Wenn eine größere Gruppe auf eine Fluchttür zustürmt und es zu einen Stau kommt; Menschentraube bildet einen sogenannten Flaschenhals Staudruck ist wenn es kein vorkommen mehr zu Flucht gibt.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Unterscheidung informelle Gruppe, formelle Gruppe.","a":"- Informelle Gruppe, Zusammenschluss von Menschen; keine Einwirkung von außen - formelle Gruppe, Zusammenschluss von Menschen, Von außen gesteuert (geformt); z.B. Kursteilnehmer einer Bildungsmaßnahme","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine Menschenmenge, was ist eine Menschenmasse?","a":"Eine Menschenmenge ist ein Zusammentreffen von Menschen, die sich grundsätzlich nicht persönlich kennt aber räumlich verbunden ist; Schaulustige, Demonstrationen, Rockkonzert, Veranstaltung... Eine Menschenmasse ist eine Menge die zielgerichtet in eine Richtung gelenkt wird; Lautsprecherdurchsage (Bitte verlassen sie den Bühnenbereich…), Bewegung wie tanzen, klatschen...","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine akute Masse?","a":"Gerät eine Menschenmasse durch einen Auslöser wie Angst, eine Explosion, ein Feuer in Bewegung, spricht man von einer akuten Masse. In der Folge kann es leicht zu einer Panik kommen. Menschen gehen zielgerichtet nach einer Bombendrohung zum Ausgang des Stadions; Plötzlich schreit jemand laut: „Gas“…","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet „Interkulturelle Kompetenz“ ? (ist die Fähigkeit mit Menschen aus","a":"anderen Kulturkreisen umzugehen und angemessen zu kommunizieren) Hier kann es schnell zu gravierenden Missverständnissen und Konflikten kommen (unterschiedliche Bedeutung/Interpretation von Körpersprache und Worten). - kulturelle und religiöse Unterschiede respektieren - Sprachtempo und Lautstärke anpassen - Wenn nötig, Sprachmittler einschalten","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie unter dem „ersten Eindruck“?","a":"ist das erste Bild, was ich mir über einen anderen Menschen mache entsteht in den ersten Sekunden (~ 5-20 Sekunden) ergibt sich aus dem Verhalten des Gegenübers (Aussehen, Auftreten -Mimik/Gestik-, Kleidung) ergibt sich aus eigenen Erfahrungswerten (Menschenkenntnis) und Vorurteilen Ist für Wachpersonen relevant in Bezug auf das weitere Verfahren (Kommunikation, Eigensicherung, etc.)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist Psychologie ?","a":"Ist die erfahrungsbasierte Wissenschaft über das Erleben und Verhalten von Menschen. Sie beschäftigt sich unter anderem mit der Persönlichkeit des Menschen.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was versteht man unter dem sogenannten „HALO-Effekt“?","a":"Ist der sogenannte „Heiligenschein-Effekt“ Menschen mit positiverer „schönerer“ Ausstrahlung werden auch besser behandelt Diesen Menschen wird zum Teil auch ein höherer Intellekt unterstellt","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist Kommunikation ?","a":"wechselseitiger Austausch von Informationen oder Botschaften Kommunikativer Grundsatz: „Man kann nicht, nicht kommunizieren“(bedeutet: eine Kommunikation findet zwischen den Menschen immer statt.Gewollt oder ungewollt, durch Worte, Verhalten, Bilder oder unbewusste Taten)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter dem Begriff „Diversität“?","a":"Ist die Freiheit und das Recht des einzelnen sich in seiner Persönlichkeit und seinem Wesen frei zu entfalten (Weltanschauung, Religion, Sexualleben, etc.) zeitgleich ist es die Pflicht des Gegenübers, diese Freiheit zu tolerieren Diese Freiheit findet ihre Grenzen dann, wenn man die Rechte (Rechtsgüter) eines anderen verletzt Basiert auf der Menschenwürde (Art. 1 GG) und auf der freien Entfaltung der Persönlichkeit (Art. 2 Abs. 1 GG)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wie entsteht eine Panik und in welchen Formen drückt sie sich aus?","a":"Eine Panik entsteht bei einer realen oder angenommenen Gefahr für Leib oder Leben Panikstarre (Menschen erstarren vor Angst) Paniksturm (Menschen rennen fluchtartig los, ohne auf ihr Umfeld zu achten) Trichtereffekt / Flaschenhalseffekt (es wollen mehr Menschen durch eine Verengung als durchpassen)","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[]},{"n":2,"title":"Bedürfnisse & Motive","subtitle":"3 Konzepte · 5 Prüfungsfragen","cards":[{"h":"Bedürfnis-Pyramide (Maslow)","b":"Defizit- vs. Wachstumsbedürfnisse, stufenweise Befriedigung; Grund-, Sicherheits-, Sozial-, Anerkennungs-, Selbstverwirklichungsbedürfnis","detail":{"titel":"Bedürfnis-Pyramide (Maslow)","kat":"Bedürfnisse · Maslow","katCls":"mensch","merksatz":"Abraham Maslow ordnet die menschlichen Bedürfnisse in fünf Stufen: 1) physiologische Grundbedürfnisse, 2) Sicherheit, 3) soziale Bedürfnisse, 4) Anerkennung, 5) Selbstverwirklichung. Erst wenn eine Stufe weitgehend befriedigt ist, rückt die nächste in den Vordergrund.","funktion":["Fünf Stufen (von unten): physiologische Grund-/Existenzbedürfnisse → Sicherheit → soziale Bedürfnisse → Anerkennung → Selbstverwirklichung.","Stufenlogik: Eine höhere Stufe wird erst wichtig, wenn die darunterliegende weitgehend befriedigt ist.","Zwei Klassen: stillbare Defizitbedürfnisse (Stufe 1–4) und das unstillbare Wachstumsbedürfnis (Selbstverwirklichung)."],"schutzziel":"Verstehen, welches unbefriedigte Bedürfnis ein Verhalten antreibt – und so die Reaktion einschätzen.","kennwerte":[{"l":"Stufe 1","v":"physiologische Grundbedürfnisse"},{"l":"Stufe 2–4","v":"Sicherheit · Soziales · Anerkennung"},{"l":"Stufe 5","v":"Selbstverwirklichung (unstillbar)"}],"begriffe":["Physiologische Grundbedürfnisse = Existenzbedürfnisse wie Nahrung, Wärme, Schlaf, Gesundheit.","Defizitbedürfnisse = stillbare Bedürfnisse (Stufe 1–4); Wachstumsbedürfnis = unstillbare Selbstverwirklichung."],"abgrenzung":["Sicherheit, soziale Kontakte oder Anerkennung sind NICHT die physiologischen Grundbedürfnisse – das sind nur die Existenzbedürfnisse der untersten Stufe.","Selbstverwirklichung ist nie „endgültig erreicht“ – sie ist als Wachstumsbedürfnis unstillbar."],"praxis":["Wer auf welcher Stufe steht, lässt Verhalten erwarten: Ein Hungernder denkt nicht an Status, sondern ans Essen.","Im Dienst hilft die Frage: Welches unbefriedigte Bedürfnis treibt diese Person gerade an?"]},"visual":null},{"h":"Motive (primär/sekundär)","b":"Beweggründe des Handelns; angeborene vs. erworbene Motive; erlauben Rückschluss auf Verhalten","detail":{"titel":"Motive (primär & sekundär)","kat":"Bedürfnisse · Motive","katCls":"mensch","merksatz":"Motive sind die Beweggründe für unser Handeln – die konkreten Ziele unserer Bedürfnisse. Man unterscheidet primäre (angeborene) Motive wie Essen, Sex, Geltung von sekundären (erworbenen) Motiven wie Macht, Luxus oder Sucht. Wer die Motive kennt, kann Verhalten vorhersehen.","funktion":["Motiv = Beweggrund des Handelns bzw. das konkrete Ziel hinter einem Bedürfnis; geprägt von der Persönlichkeit.","Primäre Motive (angeboren): z. B. Essen, Sex, Geltung.","Sekundäre Motive (erworben): z. B. materielle Mittel, Macht, Luxus, Sucht."],"schutzziel":"Aus den Beweggründen einer Person Rückschlüsse auf ihr künftiges Verhalten ziehen.","kennwerte":[{"l":"Motiv","v":"Beweggrund / Ziel eines Bedürfnisses"},{"l":"Primär","v":"angeboren: Essen, Sex, Geltung"},{"l":"Sekundär","v":"erworben: Macht, Luxus, Sucht"}],"begriffe":["Primäre Motive = angeborene Beweggründe (überlebens- und arterhaltungsnah).","Sekundäre Motive = im Laufe des Lebens erworbene Beweggründe."],"abgrenzung":["Motiv (konkreter Beweggrund) ist nicht dasselbe wie Bedürfnis (allgemeiner Mangelzustand) – das Motiv ist das konkrete Ziel des Bedürfnisses.","Primär = angeboren, sekundär = erworben: Sucht und Machtstreben sind sekundär, nicht angeboren."],"praxis":["Randalierer, die Aufmerksamkeit suchen, handeln aus dem Motiv Geltung/Anerkennung – das hilft, ihr Verhalten einzuordnen.","Wer das Motiv hinter einer Handlung erkennt (z. B. Sucht beim Beschaffungsdiebstahl), kann passender reagieren."]},"visual":null},{"h":"Motivation & Motivationsmittel","b":"Wirkung hoher Motivation; positive Motivationsmittel (Lob, Anerkennung, Ziele) stärken Selbstwertgefühl","detail":{"titel":"Motivation & Motivationsmittel","kat":"Bedürfnisse · Motivation","katCls":"mensch","merksatz":"Motivation ist der Antrieb, ein Ziel zu verfolgen. Hohe Motivation steigert Aufmerksamkeit, Wahrnehmung, Leistungsbereitschaft und Ausstrahlung. Motivationsmittel sind u. a. Anerkennung, Ziele setzen, Druck, Anteilnahme und Interesse – positive Mittel stärken das Selbstwertgefühl.","funktion":["Wirkung hoher Motivation: erhöhte Aufmerksamkeit, gesteigerte Wahrnehmung, mehr Leistungsbereitschaft, bessere Einstellung auf kritische Lagen, positivere Ausstrahlung, mehr Selbstvertrauen.","Motivationsmittel: Anerkennung (Lob, Belohnung), Ziele setzen (Erfolge, Prüfungen, Prämien), Druck (Zeit-/Leistungsdruck), Anteilnahme (Zuwendung), Interesse zeigen (Fragen, aktives Zuhören, Rat).","Folge: Positive Motivationsmittel stärken das Selbstwertgefühl; reiner Druck wirkt nur kurzfristig."],"schutzziel":"Sich selbst und andere zu zielgerichtetem, aufmerksamem Verhalten bewegen.","kennwerte":[{"l":"Motivation","v":"Antrieb, ein Ziel zu verfolgen"},{"l":"Positive Mittel","v":"Anerkennung, Interesse, Ziele"},{"l":"Effekt","v":"stärkt Selbstwertgefühl + Wahrnehmung"}],"begriffe":["Motivation = die Gesamtheit der Beweggründe, die zu einer Handlung antreiben.","Motivationsmittel = Werkzeuge, mit denen Motivation gefördert wird (Lob, Ziele, Interesse …)."],"abgrenzung":["Druck ist ein Motivationsmittel, aber ein kurzfristiges – nachhaltig motivieren positive Mittel (Anerkennung, Interesse).","Motivation (Antrieb) ist nicht das Motiv selbst (der Beweggrund) – Motivation ist die Aktivierung hin zum Ziel."],"praxis":["Ein motiviertes Team nimmt mehr wahr und ist aufmerksamer – im Sicherheitsdienst ein echter Sicherheitsfaktor.","Lob und ehrliches Interesse motivieren Kollegen nachhaltiger als ständiger Zeitdruck."]},"visual":null}],"quiz":[{"q":"Was sind physiologische Grundbedürfnisse?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Anerkennung","c":false},{"t":"Selbstverwirklichung","c":false},{"t":"Sicherheit und Wohlbefinden","c":false},{"t":"Soziale Kontakte","c":false},{"t":"Grund- und Existenzbedürfnisse","c":true}]},{"q":"Eine Gruppe von Randalierern möchte durch ihr Verhalten Aufmerksamkeit in der Öffentlichkeit erzeugen. Welche Motive kommen hierfür in Betracht?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sicherheitsbedürfnisse","c":false},{"t":"Streben nach Anerkennung","c":true},{"t":"Soziale Zugehörigkeit","c":true},{"t":"Physiologische Grundbedürfnisse","c":false}]},{"q":"Was sind Bedürfnisse, erklären nach der Bedürfnispyramide?","a":"Bedürfnisse sind der Ausgangs- und Zielpunkt unseres gesamten Strebens und Handelns - Grundbedürfnis, Hunger, Durst, Schlaf, Selbsterhaltung (Sexualität wollen die Prüfer/IHK Dortmund nicht hören) - Sicherheitsbedürfnis, Wohnung, soziale Absicherung, Arbeit - Sozialbedürfnis, Kontakt zu anderen Menschen, Vereinen - Soziale Anerkennung (Ich Anerkennung), Selbstachtung, Wertschätzung durch andere - Selbstverwirklichung, Selbstentfaltung… Hier am besten an Robinson Crusoe denken!!!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie unter der Bedürfnispyramidenach Maslow?","a":"Selbstverwirklichung (eigene Persönlichkeit und Potenzial ausbauen) Individualbedürfnisse (Anerkennung, Wertschätzung, etc.) Soziale Bedürfnisse (Beziehungen, Freundschaften, soziale Zugehörigkeit) Sicherheitsbedürfnisse (Sicherung der Grundbedürfnisse für die Zukunft) Grundbedürfnisse (Hunger, Durst, Schlafen, etc.) Bauen aufeinander auf","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was sind Motive?","a":"Beweggründe des Handelns (Man hat Hunger und man isst) Motive Motivation Verhalten","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie in der Kommunikation unter dem „Eisbergmodell“?","a":"Sachebene> beinhalten Fakten, Informationen, Sachverhalte> stellt etwa 20% der zwischenmenschlichen Kommunikation dar Beziehungsebene> beinhaltet Gefühle, Motive, Vorurteile> stellt etwa 80% der zwischenmenschlichen Kommunikation dar Beide Ebenen spielen in der Kommunikation zusammen. Die Beziehungsebene hat immer Einfluss auf die Sachebene. (kann ich den anderen besser leiden, ist die Kommunikation positiver, als bei einem Partner den ich nicht Leiden kann.)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche drei Motive prägen die menschliche Persönlichkeit?","a":"Verstand> Denken, Wissen, Fantasie Gefühl> Liebe, Hass, Neid Trieb> Hunger, Selbsterhaltung, Sexualtrieb Der Mensch kann durch dasEinwirken auf einzelne oder mehrere Motive in seinem Verhalten manipuliert werden.","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[]},{"n":3,"title":"Persönlichkeit & Selbstbild","subtitle":"4 Konzepte · 23 Prüfungsfragen","cards":[{"h":"Persönlichkeitsaufbau (Plato/Aristoteles)","b":"Drei Schichten: Verstand, Gefühl, Trieb","detail":{"titel":"Persönlichkeitsaufbau nach Platon und Aristoteles","kat":"Persönlichkeit · Aufbau","katCls":"mensch","merksatz":"Die Persönlichkeit wird klassisch in drei Schichten gedacht: Verstand (Denken, Vernunft), Gefühl (Emotionen) und Trieb (Grundbedürfnisse, Instinkte). Reifes Verhalten heißt: der Verstand steuert Gefühl und Trieb – nicht umgekehrt.","funktion":["Verstand: die vernünftige, denkende Ebene – wägt ab, plant, kontrolliert.","Gefühl: die emotionale Ebene – Freude, Angst, Wut, Sympathie; färbt jede Begegnung.","Trieb: die instinktive Ebene – Grundbedürfnisse wie Hunger, Selbsterhaltung, Aggression."],"schutzziel":"Verstehen, warum Menschen (und man selbst) unter Druck unvernünftig reagieren – und wie man mit dem Verstand gegensteuert.","kennwerte":[{"l":"Drei Schichten","v":"Verstand · Gefühl · Trieb"},{"l":"Reife","v":"Verstand steuert Gefühl + Trieb"},{"l":"Herkunft","v":"Antike: Platon und Aristoteles"}],"begriffe":["Trieb = angeborener innerer Antrieb, der auf die Befriedigung eines Grundbedürfnisses zielt.","Persönlichkeit = das für einen Menschen typische, recht beständige Muster aus Denken, Fühlen und Verhalten."],"abgrenzung":["Triebe und Gefühle sind nicht schlecht – problematisch wird es erst, wenn sie den Verstand überlagern (z. B. Wut, die das Denken ausschaltet).","Bei betrunkenen oder stark erregten Personen übernehmen Gefühl und Trieb – der Verstand tritt zurück."],"praxis":["Wer im Dienst provoziert wird, spürt den Trieb (zurückschlagen) und das Gefühl (Wut) – die Vernunft muss die Führung behalten.","Wer den Aufbau kennt, nimmt Angriffe weniger persönlich und bleibt steuerungsfähig."]},"visual":null},{"h":"Selbstwertgefühl","b":"Schwach / stark-positiv / stark-negativ; Merkmale potentielles Opfer, Führungspersönlichkeit, potentieller Täter","detail":{"titel":"Selbstwertgefühl","kat":"Persönlichkeit · Selbstwert","katCls":"mensch","merksatz":"Das Selbstwertgefühl ist das Ergebnis einer Selbstbewertung – wie ein Mensch sich selbst in der Auseinandersetzung mit sich und seinem Umfeld einschätzt. Es ist nicht angeboren, sondern entsteht und verändert sich lebenslang.","funktion":["Schwaches Selbstwertgefühl: unsicher, leicht zu verunsichern – Merkmale eines potentiellen Opfers.","Stark-positives Selbstwertgefühl: sicher, gelassen, durchsetzungsfähig, ohne andere abzuwerten – Merkmale einer Führungspersönlichkeit.","Stark-negatives (überzogenes) Selbstwertgefühl: muss sich über andere erheben, neigt zu Abwertung und Gewalt – Merkmale eines potentiellen Täters."],"schutzziel":"Menschen und sich selbst besser einschätzen, Opfer- und Tätermuster früh erkennen und sicher auftreten.","kennwerte":[{"l":"Definition","v":"Ergebnis einer Selbstbewertung"},{"l":"Schwach","v":"potentielles Opfer"},{"l":"Stark-positiv","v":"Führungspersönlichkeit"},{"l":"Stark-negativ","v":"potentieller Täter"}],"begriffe":["Selbstwertgefühl = die gefühlsmäßige Bewertung der eigenen Person.","Es hängt auch von der Wertschätzung anderer ab – nicht allein von der Erziehung."],"abgrenzung":["Prüfungsfalle: Das Selbstwertgefühl ist NICHT unabhängig von der Wertschätzung anderer und wird NICHT allein durch Erziehung geprägt.","Lautes, dominantes Auftreten ist kein Zeichen von Stärke, sondern oft von einem überzogenen, instabilen Selbstwert."],"praxis":["Ein sicher und ruhig auftretender Mitarbeiter wirkt weniger als Opfer – Täter suchen sich eher Unsichere aus.","Erkennt man beim Gegenüber ein stark-negatives Selbstwertgefühl (Imponiergehabe), gilt: Gesicht wahren lassen, nicht bloßstellen."]},"visual":null},{"h":"Selbstbild & Fremdbild","b":"Eigen- vs. Fremdwahrnehmung; Annäherung durch Feedback und Fragen; Konflikte bei zu großer Abweichung","detail":{"titel":"Selbstbild und Fremdbild","kat":"Persönlichkeit · Selbst- und Fremdbild","katCls":"mensch","merksatz":"Das Selbstbild ist, wie ich mich selbst sehe; das Fremdbild, wie andere mich sehen. Beide weichen fast immer voneinander ab. Je größer die Abweichung, desto höher die Konfliktgefahr – Feedback und Nachfragen bringen beide näher zusammen.","funktion":["Selbstbild: die eigene Wahrnehmung der eigenen Person (Stärken, Schwächen, Wirkung).","Fremdbild: das Bild, das andere von einem haben – oft anders als das Selbstbild.","Annäherung: durch ehrliches Feedback und gezieltes Nachfragen werden die blinden Flecken kleiner."],"schutzziel":"Die eigene Wirkung realistisch einschätzen, Konflikte durch Selbstüberschätzung vermeiden und an sich arbeiten können.","kennwerte":[{"l":"Selbstbild","v":"wie ich mich sehe"},{"l":"Fremdbild","v":"wie andere mich sehen"},{"l":"Annäherung","v":"Feedback + Nachfragen"},{"l":"Große Abweichung","v":"hohe Konfliktgefahr"}],"begriffe":["Selbstkritik = eigene Fehler und Schwächen erkennen, sich mit ihnen auseinandersetzen und sich bewusst machen, dass sie das eigene Verhalten beeinflussen.","Blinder Fleck = Anteile der eigenen Wirkung, die man selbst nicht sieht, andere aber schon."],"abgrenzung":["Selbstkritisch ist NICHT, wer Schwächen erkennt, aber ignoriert oder durch Imponiergehabe ausgleicht – sondern wer sich mit ihnen auseinandersetzt.","Ein realistisches Selbstbild ist nicht dasselbe wie ein schlechtes – es geht um Ehrlichkeit, nicht um Selbstabwertung."],"praxis":["Wer sich für immer sachlich hält, aber von Kollegen als schroff erlebt wird, hat eine Selbst-/Fremdbild-Lücke – Feedback hilft.","Im Team Rückmeldungen einholen verkleinert blinde Flecken und beugt Konflikten vor."]},"visual":null},{"h":"Grundsätzliche Begegnung mit Menschen","b":"Aufrechte Haltung, Höflichkeit, Distanz, Blickkontakt, Grenzen setzen, Selbstbeherrschung","detail":{"titel":"Grundsätzliche Begegnung mit Menschen","kat":"Persönlichkeit · Auftreten","katCls":"mensch","merksatz":"Professionelles Auftreten heißt: aufrechte, offene Haltung, Höflichkeit und Respekt, angemessene Distanz, ruhiger Blickkontakt, klare Grenzen – und vor allem Selbstbeherrschung. Kundenorientiert und angemessen, nie autoritär oder rechthaberisch.","funktion":["Haltung und Höflichkeit: aufrecht, offen, freundlich – das erleichtert Kontakt und Zusammenarbeit.","Distanz und Blickkontakt: ausreichenden Abstand halten, ruhigen (nicht starrenden) Blickkontakt suchen.","Grenzen und Selbstbeherrschung: klare Grenzen setzen, Beleidigungen nicht persönlich nehmen, beherrscht bleiben."],"schutzziel":"Von Anfang an eine sachliche, respektvolle Ebene herstellen – das verhindert die meisten Konflikte.","kennwerte":[{"l":"Haltung","v":"aufrecht · offen · höflich"},{"l":"Distanz","v":"Abstand + ruhiger Blickkontakt"},{"l":"Grenzen","v":"klar, aber respektvoll"},{"l":"Kern","v":"Selbstbeherrschung"}],"begriffe":["Höflichkeit = Form des Respekts, die Zusammenarbeit erleichtert und schneller Kontakt schafft – kein Zeichen von Schwäche.","Professionell = kundenorientiert und angemessen handeln, nicht autoritär, rechthaberisch oder dominant."],"abgrenzung":["Höflich sein heißt NICHT schwach sein – wer höflich auftritt, hat oft mehr Durchsetzungskraft, nicht weniger.","Professionell ist nicht, wer autoritär auftritt oder stur auf seinem Standpunkt beharrt, sondern wer angemessen und kundenorientiert handelt."],"praxis":["Eine freundlich-bestimmte Begrüßung an der Einlasskontrolle nimmt vielen Konflikten von vornherein die Spitze.","Abstand halten schützt zugleich vor Überraschungsangriffen (Eigensicherung) und wirkt deeskalierend."]},"visual":null}],"quiz":[{"q":"Welche Ansichten zum Selbstwertgefühl sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Das Selbstwertgefühl ist unabhängig von der Wertschätzung anderer","c":false},{"t":"Das Selbstwertgefühl wird allein durch die Erziehung geprägt","c":false},{"t":"Das Selbstwertgefühl ist eine Selbstbewertung in der Auseinandersetzung mit sich selbst und dem Umfeld","c":true},{"t":"Das Selbstwertgefühl ist das Ergebnis einer Selbstbewertung","c":true}]},{"q":"Zur Selbstwahrnehmung gehört die Selbstkritik. Wer ist selbstkritisch?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wer eigene Fehler und Schwächen dadurch ausgleicht, dass er Überlegenheit im Auftreten demonstriert","c":false},{"t":"Wer eigene Fehler und Schwächen zwar erkennt, aber ignoriert","c":false},{"t":"Wer eigene Fehler und Schwächen erkennt und sich mit ihnen auseinandersetzt","c":true},{"t":"Wer eigene Fehler und Schwächen wahrnimmt und sich bewusst macht, dass sie eigenes Verhalten beeinflussen","c":true}]},{"q":"Ist höfliches Verhalten zeitgemäß?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Ja, wer höflich ist, erleichtert die Zusammenarbeit in der Gruppe","c":true},{"t":"Nein, wer höflich ist, zeigt, dass er kein Durchsetzungsvermögen besitzt","c":false},{"t":"Ja, wer höflich ist, kann schneller Kontakt zu anderen Personen herstellen","c":true},{"t":"Nein, wer höflich ist, wird als Schwächling angesehen, ausgenutzt und ausgelacht","c":false}]},{"q":"Wann verhalten sich Wachpersonen professionell?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wenn sie autoritär auftreten und entsprechend handeln","c":false},{"t":"Wenn sie grundsätzlich auf ihrem Standpunkt beharren","c":false},{"t":"Wenn sie rechthaberisch auftreten","c":false},{"t":"Wenn sie kundenorientiert und angemessen handeln","c":true}]},{"q":"Ein neuer Mitarbeiter fragt, wie er sich bei den Arbeitskollegen Respekt und Ansehen verschaffen kann. Welche Ratschläge sind hilfreich?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Zeigen, dass er alles besser kann und weiß","c":false},{"t":"Zuverlässig und hilfsbereit sein","c":true},{"t":"Einsichtig sein, auch mal Fehler zugeben können","c":true},{"t":"Streng, kompromisslos und unnachgiebig sein","c":false}]},{"q":"Was ist für das Bewachungsgewerbe Psychologie?","a":"Die Lehre vom (sichtbaren) Verhalten und (nicht sichtbarem) Erleben der Menschen. Psychologen erforschen, warum eine bestimmte Person in einer bestimmten Situation ein bestimmtes Verhalten anzeigt – und welche inneren und äußeren Vorgänge dabei ablaufen. Die Bedeutung für das Bewachungsgewerbe, liegt darin Fehlurteile zu vermeiden und mögliche Gefahrensituationen vorausschauen zu können • Verhalten ist das, was sichtbar und hörbar ist: Gestik, Mimik, Sprechen, Weinen usw. • Erleben ist alles, was unsichtbar bleibt: Denken, Wahrnehmen, Gefühle, Triebe usw.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre den Aufbau der Person nach Plato/Aristoteles (Waage/Dreieck)","a":"Der Verstand regelt das Gleichgewicht zwischen Gefühlen und Trieben; Beispiel Love - Parade (Überlebenstrieb übernimmt, Verstand setzt aus!)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere Das 4 Ohr Prinzip nach Schulz von Thun.","a":"Wie nimmt man die gesendete Botschaft auf. - Sachohr, der sachliche Inhalt wurde verstanden - Beziehungsohr, wie spricht der Sender, mit Respekt oder Verachtung - Appellohr, bewirkt der Sender beim Empfänger etwas - Offenbarungsohr, der Empfänger hört was der Sender von sich preisgibt Beispiel: Ihr Beifahrer sagt kurz nachdem die Ampel auf Grün gesprungen ist „Grüner wird es nicht“. Dies ist die Nachricht - Sachinhalt (Fakten): Die Ampel ist grün - Selbstkundgabe (wie ich mich fühle, was ich darüber denke): Ich habe es eilig - Beziehung(wie ich zum Empfänger stehe): Nichts kannst du, immer muss man dir alles sagen - Appell (Aufforderung): Fahr los!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet „Interkulturelle Kompetenz“ ? (ist die Fähigkeit mit Menschen aus","a":"anderen Kulturkreisen umzugehen und angemessen zu kommunizieren) Hier kann es schnell zu gravierenden Missverständnissen und Konflikten kommen (unterschiedliche Bedeutung/Interpretation von Körpersprache und Worten). - kulturelle und religiöse Unterschiede respektieren - Sprachtempo und Lautstärke anpassen - Wenn nötig, Sprachmittler einschalten","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche drei Motive prägen die menschliche Persönlichkeit?","a":"Verstand> Denken, Wissen, Fantasie Gefühl> Liebe, Hass, Neid Trieb> Hunger, Selbsterhaltung, Sexualtrieb Der Mensch kann durch dasEinwirken auf einzelne oder mehrere Motive in seinem Verhalten manipuliert werden.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Definition für Selbstwertgefühl?","a":"Das Gefühl vom Wert des eigenen Selbst (Selbstbewusstsein, Selbstsicherheit, Selbstvertrauen). Entsteht aus der Wahrnehmung und Beurteilung der eigenen Person; Es ist damit das Ergebnis des Selbstbildes, das ein Mensch von sich hat; Die Einschätzung der eigenen Person bestimmte Situationen meistern zu können. Eine realistische Selbsteinschätzung führt zu einem angemessenen Selbstvertrauen und damit zu angemessenem Verhalten und Handeln","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erklären Sie uns das Johari Window Modell.","a":"Das Johari Fenster verdeutlicht modellhaft, welche Bereiche beim Selbst- und Fremdbild sichtbar und welche unsichtbar sind Es gibt vier Felder - Öffentlich, alles was ein Mensch von sich preisgibt, Erscheinungsbild, körperliche Reaktion - Geheim, was man weiß und kennt, was man anderen verbirgt - Blinder Fleck, was selber aussendet was einen aber nicht bewusst ist, Verhaltensweisen - Unbekannt, ist was man selber und der andere nicht bekannt ist","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Umgang mit Menschen?","a":"Beim Umgang mit Menschen ist es sinnvoll Grundzüge menschlichen Verhaltens, Reaktionen, Emotionen und andere Faktoren zu kennen. Im Umgang mit Menschen können Gefahren erkannt werden bevor diese entstehen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre Menschenkenntnis und wie kann man sich","a":"diese aneignen? Menschenkenntnis ist wie ich andere Menschen einschätze, man erlangt diese durch Erfahrung und Umgang mit Menschen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind Vorurteile und wie entstehen Vorurteile?","a":"Vorurteile ist ungeprüfte Meinungen die man anderen Menschen oder Sachen gegenüber hat, diese entstehen durch eigene Erfahrung, durch Verallgemeinerung durch andere und auch durch Medien; Vorurteile können in bestimmten Situationen aber auch positiv sein (Schutzwirkung).","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind Bedürfnisse, erklären nach der Bedürfnispyramide?","a":"Bedürfnisse sind der Ausgangs- und Zielpunkt unseres gesamten Strebens und Handelns - Grundbedürfnis, Hunger, Durst, Schlaf, Selbsterhaltung (Sexualität wollen die Prüfer/IHK Dortmund nicht hören) - Sicherheitsbedürfnis, Wohnung, soziale Absicherung, Arbeit - Sozialbedürfnis, Kontakt zu anderen Menschen, Vereinen - Soziale Anerkennung (Ich Anerkennung), Selbstachtung, Wertschätzung durch andere - Selbstverwirklichung, Selbstentfaltung… Hier am besten an Robinson Crusoe denken!!!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Aggression bzw. eine Aggressionsverschiebung?","a":"Ist ein Verhalten, das darauf abzielt, andere Menschen und deren Interessen zu verletzen oder zu zerstören, entweder körperlich oder verbal Aggressionsverschiebung - gegen andere Dinge oder Menschen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist Panik, nenne die 4 Panikarten.","a":"Panik entsteht wenn durch überraschendes Auftreten ein Zustand von Furcht und Schrecken unter Menschen auftritt und zu unkontrolliertem Handeln führt. - Panikstimmung, etwas wird oder könnte gleich geschehen - Panikereignis, es ist etwas geschehen (Knall, Feuer, Gasgeruch...) - Paniksturm, der Überlebensinstinkt wird aktiv, vernunftlose Fluchtreaktion - Panikstarre, man kann sich nicht mehr bewegen oder klar denken (man Erstarrt)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist ein Flaschenhalseffekt, wie entwickelt sich Staudruck?","a":"Wenn eine größere Gruppe auf eine Fluchttür zustürmt und es zu einen Stau kommt; Menschentraube bildet einen sogenannten Flaschenhals Staudruck ist wenn es kein vorkommen mehr zu Flucht gibt.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Unterscheidung informelle Gruppe, formelle Gruppe.","a":"- Informelle Gruppe, Zusammenschluss von Menschen; keine Einwirkung von außen - formelle Gruppe, Zusammenschluss von Menschen, Von außen gesteuert (geformt); z.B. Kursteilnehmer einer Bildungsmaßnahme","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine Menschenmenge, was ist eine Menschenmasse?","a":"Eine Menschenmenge ist ein Zusammentreffen von Menschen, die sich grundsätzlich nicht persönlich kennt aber räumlich verbunden ist; Schaulustige, Demonstrationen, Rockkonzert, Veranstaltung... Eine Menschenmasse ist eine Menge die zielgerichtet in eine Richtung gelenkt wird; Lautsprecherdurchsage (Bitte verlassen sie den Bühnenbereich…), Bewegung wie tanzen, klatschen...","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine akute Masse?","a":"Gerät eine Menschenmasse durch einen Auslöser wie Angst, eine Explosion, ein Feuer in Bewegung, spricht man von einer akuten Masse. In der Folge kann es leicht zu einer Panik kommen. Menschen gehen zielgerichtet nach einer Bombendrohung zum Ausgang des Stadions; Plötzlich schreit jemand laut: „Gas“…","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie unter dem „ersten Eindruck“?","a":"ist das erste Bild, was ich mir über einen anderen Menschen mache entsteht in den ersten Sekunden (~ 5-20 Sekunden) ergibt sich aus dem Verhalten des Gegenübers (Aussehen, Auftreten -Mimik/Gestik-, Kleidung) ergibt sich aus eigenen Erfahrungswerten (Menschenkenntnis) und Vorurteilen Ist für Wachpersonen relevant in Bezug auf das weitere Verfahren (Kommunikation, Eigensicherung, etc.)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist Psychologie ?","a":"Ist die erfahrungsbasierte Wissenschaft über das Erleben und Verhalten von Menschen. Sie beschäftigt sich unter anderem mit der Persönlichkeit des Menschen.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was versteht man unter dem sogenannten „HALO-Effekt“?","a":"Ist der sogenannte „Heiligenschein-Effekt“ Menschen mit positiverer „schönerer“ Ausstrahlung werden auch besser behandelt Diesen Menschen wird zum Teil auch ein höherer Intellekt unterstellt","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist Kommunikation ?","a":"wechselseitiger Austausch von Informationen oder Botschaften Kommunikativer Grundsatz: „Man kann nicht, nicht kommunizieren“(bedeutet: eine Kommunikation findet zwischen den Menschen immer statt.Gewollt oder ungewollt, durch Worte, Verhalten, Bilder oder unbewusste Taten)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter dem Begriff „Diversität“?","a":"Ist die Freiheit und das Recht des einzelnen sich in seiner Persönlichkeit und seinem Wesen frei zu entfalten (Weltanschauung, Religion, Sexualleben, etc.) zeitgleich ist es die Pflicht des Gegenübers, diese Freiheit zu tolerieren Diese Freiheit findet ihre Grenzen dann, wenn man die Rechte (Rechtsgüter) eines anderen verletzt Basiert auf der Menschenwürde (Art. 1 GG) und auf der freien Entfaltung der Persönlichkeit (Art. 2 Abs. 1 GG)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wie entsteht eine Panik und in welchen Formen drückt sie sich aus?","a":"Eine Panik entsteht bei einer realen oder angenommenen Gefahr für Leib oder Leben Panikstarre (Menschen erstarren vor Angst) Paniksturm (Menschen rennen fluchtartig los, ohne auf ihr Umfeld zu achten) Trichtereffekt / Flaschenhalseffekt (es wollen mehr Menschen durch eine Verengung als durchpassen)","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[{"scenario":"Zwei neue Kollegen machen Türdienst. Der eine wirkt unsicher, vermeidet Blickkontakt und murmelt seine Ansagen. Der andere steht aufrecht, hält ruhigen Blickkontakt und spricht freundlich-klar. Erfahrungsgemäß wird einer von beiden deutlich häufiger angepöbelt und in Konflikte verwickelt.","frage":"Welcher – und was steckt dahinter?","loesung":"Der unsichere Kollege wird häufiger angegangen. Ein schwaches Selbstwertgefühl zeigt sich nach außen (unsicheres Auftreten, kein Blickkontakt) und macht zum potentiellen Opfer – Täter suchen sich gezielt Unsichere. Ein stark-positives Selbstwertgefühl (ruhig, sicher, ohne andere abzuwerten) wirkt wie ein natürlicher Schutz und entspricht einer Führungspersönlichkeit. Denkschlüssel: Dein Auftreten sendet ein Signal – Sicherheit, nicht Lautstärke, schreckt Provokateure ab; lautes Imponieren wäre dagegen ein Zeichen von überzogenem, instabilem Selbstwert."},{"scenario":"Ein Mitarbeiter hält sich selbst für immer ruhig und freundlich. In der Auswertung sagen ihm aber gleich mehrere Gäste und Kollegen, er wirke an der Tür schroff und von oben herab. Er reagiert empört: Die anderen hätten doch alle keine Ahnung.","frage":"Was läuft hier schief – und wie sollte er reagieren?","loesung":"Sein Selbstbild (ruhig, freundlich) weicht stark vom Fremdbild (schroff) ab. Diese Lücke ist normal, aber je größer sie ist, desto höher die Konfliktgefahr. Statt das Feedback als Angriff abzuwehren und damit den blinden Fleck zu zementieren, sollte er es ernst nehmen, nachfragen und sein Auftreten anpassen – das ist gelebte Selbstkritik. Denkschlüssel: Nicht das Selbstbild entscheidet über die Wirkung, sondern das Fremdbild – wer Rückmeldung zulässt, verkleinert seinen blinden Fleck."}]},{"n":4,"title":"Wahrnehmung & Vorurteile","subtitle":"5 Konzepte · 9 Prüfungsfragen","cards":[{"h":"Wahrnehmung","b":"Aufnahme von Reizen/Informationen inkl. Intuition; Einflussfaktoren","detail":{"titel":"Wahrnehmung","kat":"Wahrnehmung · Grundlagen","katCls":"mensch","merksatz":"Wahrnehmung ist die Aufnahme und Verarbeitung von Reizen und Informationen über unsere Sinne – einschließlich der Intuition (‚Bauchgefühl'). Sie ist immer subjektiv: Jeder Mensch nimmt dieselbe Situation etwas anders wahr.","funktion":["Ablauf in drei Schritten: Reiz über die Sinne aufnehmen → im Gehirn verarbeiten → deuten und interpretieren. Erst die Deutung macht aus einem Reiz eine ‚Information'.","Wahrnehmung ist immer subjektiv und unvollständig: Erwartung, Erfahrung, Stimmung und Interesse färben das Bild ein.","Positiv beeinflusst wird sie durch Interesse und Aufmerksamkeit – negativ durch Angst, Stress und Überforderung.","Auch die Intuition (‚Bauchgefühl') gehört zur Wahrnehmung: ein ernstzunehmender Hinweis, aber kein Beweis – immer mit den Fakten abgleichen."],"schutzziel":"Situationen und Personen realistisch einschätzen – Gefahren erkennen, ohne sich selbst zu täuschen.","kennwerte":[{"l":"Ablauf","v":"aufnehmen → verarbeiten → deuten"},{"l":"positiv","v":"Interesse · Aufmerksamkeit"},{"l":"negativ","v":"Angst · Stress · Überforderung"},{"l":"Merkmal","v":"immer subjektiv"}],"begriffe":["Reiz = ein Signal aus der Umwelt (Geräusch, Bild, Geruch …), das ein Sinnesorgan anspricht.","Intuition = unmittelbares ‚Bauchgefühl' ohne bewusstes Nachdenken – schnell, aber nicht immer zutreffend."],"abgrenzung":["Wahrnehmen ≠ die Wahrheit erkennen: Wir nehmen nicht die Wirklichkeit ‚an sich' wahr, sondern unser gedeutetes Bild von ihr.","Reiz (das Signal) ≠ Information (die gedeutete Bedeutung)."],"praxis":["Unter Stress – etwa bei einem Alarm – verengt sich die Wahrnehmung, man übersieht Dinge am Rand. Bewusst durchatmen und systematisch schauen.","Was dich interessiert, nimmst du schärfer wahr – deshalb gezielt auf sicherheitsrelevante Details achten."]},"visual":null},{"h":"Selektive Wahrnehmung","b":"Bewusste/unbewusste Auswahl von Informationen; Wahrnehmungsmerkmale bei Personen","detail":{"titel":"Selektive Wahrnehmung","kat":"Wahrnehmung · Auswahl","katCls":"mensch","merksatz":"Aus der Flut an Reizen wählt das Gehirn ständig aus – bewusst und unbewusst. Wir nehmen nur einen Bruchteil wahr, und zwar vor allem das, was wir erwarten oder worauf wir gerade achten.","funktion":["Notwendige Filterfunktion: Das Gehirn kann unmöglich alles verarbeiten, also blendet es das meiste aus – nützlich, aber fehleranfällig.","Gefahr ‚Tunnelblick': Wer auf eine Sache fixiert ist, übersieht alles andere – im Dienst riskant, weil einem das Wesentliche entgeht.","Die Erwartung steuert die Auswahl: Wer ‚nichts erwartet', sieht oft auch nichts; wer auf das Falsche fixiert ist, übersieht das Richtige.","Bei Personen achtet man systematisch auf Wahrnehmungsmerkmale: Größe, Statur, Kleidung, Auffälligkeiten, Verhalten und Sprache."],"schutzziel":"Bewusst breit und vollständig wahrnehmen statt nur das Erwartete – damit nichts Wichtiges übersehen wird.","kennwerte":[{"l":"Prinzip","v":"Gehirn filtert ständig"},{"l":"Risiko","v":"Tunnelblick / blinder Fleck"},{"l":"Personenmerkmale","v":"Größe · Kleidung · Verhalten"}],"begriffe":["Selektion = Auswahl: das Gehirn lässt nur einen Teil der Reize ‚durch'.","Tunnelblick = die Wahrnehmung verengt sich auf einen Punkt, das Umfeld wird ausgeblendet."],"abgrenzung":["Selektive Wahrnehmung ist kein böser Wille, sondern ein natürlicher Filter – man muss ihn nur kennen und bewusst gegensteuern."],"praxis":["Bei einer Personenbeschreibung systematisch von oben nach unten vorgehen (Kopf → Kleidung → Schuhe → Besonderheiten), damit nichts vergessen wird.","Wer sich auf einen vermeintlich ‚Verdächtigen' einschießt, dem kann der echte Täter entgehen – bewusst auch das Umfeld scannen."]},"visual":null},{"h":"Vorurteile","b":"Sinn (Schutzinstinkt) und Ursachen (Andersartigkeit); positiv wie negativ; stets hinterfragen","detail":{"titel":"Vorurteile","kat":"Wahrnehmung · Vorurteile","katCls":"mensch","merksatz":"Ein Vorurteil ist ein vorgefertigtes Urteil über Personen oder Gruppen, das man ohne eigene Prüfung übernimmt. Es hat einen ursprünglichen Schutz-Sinn, verzerrt aber die Wahrnehmung – darum muss man es stets hinterfragen.","funktion":["Ursprünglicher Sinn: Vorurteile dienen dem Schutzinstinkt – Fremdes und Andersartiges wird blitzschnell als mögliche Gefahr eingestuft (uralter Reflex).","Ursache: Andersartigkeit (Aussehen, Herkunft, Kleidung, Verhalten) löst Vorurteile aus – sie können positiv wie negativ sein.","Wirkung: Vorurteile steuern unbewusst das Verhalten und können Konflikte mit (schutzbedürftigen) Personen erst auslösen.","Pflicht der Wachperson: eigene Vorurteile erkennen und bewusst hinterfragen – nach Fakten urteilen statt nach Schublade und jedem mit Respekt und Toleranz begegnen."],"schutzziel":"Faire, sachliche Einschätzung statt Diskriminierung – und das Vermeiden vorurteilsbedingter Konflikte.","kennwerte":[{"l":"Definition","v":"Urteil ohne Prüfung"},{"l":"Ursache","v":"Andersartigkeit / Fremdes"},{"l":"Sinn (urspr.)","v":"Schutzinstinkt"},{"l":"Pflicht","v":"erkennen + hinterfragen"}],"begriffe":["Vorurteil = eine feste Meinung über jemanden, die schon vor dem eigentlichen Kennenlernen besteht.","Stereotyp = ein vereinfachtes, verallgemeinerndes Bild über eine ganze Gruppe.","Toleranz = Andersartigkeit aushalten und respektieren, ohne sie abzuwerten."],"abgrenzung":["Vorurteil ≠ Erfahrung: Erfahrung beruht auf geprüften, wiederholten Beobachtungen – ein Vorurteil übernimmt ein Urteil ungeprüft.","Auch ein positives Vorurteil ist ein Vorurteil (z. B. ‚gut gekleidet = harmlos') – und gerade das wird im Dienst gefährlich."],"praxis":["Der teuer gekleidete Gast ist nicht automatisch harmlos, der ungepflegte nicht automatisch verdächtig – nach Verhalten urteilen, nicht nach Aussehen.","Personen mit seelischer Behinderung oder in einer Ausnahmesituation mit Respekt und Toleranz begegnen, statt sie abzustempeln."]},"visual":null},{"h":"Psychologie","b":"Lehre von Erleben und Verhalten; Grundlagenwissen für SMA","detail":{"titel":"Psychologie","kat":"Wahrnehmung · Psychologie","katCls":"mensch","merksatz":"Psychologie ist die Lehre vom Erleben und Verhalten des Menschen. Für die Sicherheitskraft liefert sie das Grundlagenwissen, um Reaktionen wie Angst, Stress oder Aggression zu verstehen und angemessen darauf zu reagieren.","funktion":["Definition: die Wissenschaft vom Erleben (innen: Fühlen, Denken, Wahrnehmen) und vom Verhalten (außen: das sichtbare Handeln) des Menschen.","Nutzen für den SMA: Verhalten einordnen statt nur reagieren – warum wird jemand aggressiv, ängstlich oder panisch?","Wichtige Effekte: erster Eindruck, Erwartungshaltung und Projektion (eigene Gefühle unbewusst auf andere übertragen).","Grenze: Die Wachperson ist kein Psychologe und kein Therapeut – sie nutzt Grundlagen zur Deeskalation, stellt aber keine ‚Diagnosen'."],"schutzziel":"Das Verhalten von Menschen verstehen und einordnen, um angemessen und deeskalierend zu reagieren.","kennwerte":[{"l":"Definition","v":"Lehre von Erleben + Verhalten"},{"l":"Erleben","v":"innen: Fühlen / Denken"},{"l":"Verhalten","v":"außen: sichtbares Handeln"},{"l":"Nutzen","v":"Reaktionen verstehen"}],"begriffe":["Erleben = das innere, nicht direkt sichtbare Geschehen: Gedanken, Gefühle, Wahrnehmungen.","Verhalten = das von außen beobachtbare Handeln eines Menschen.","Projektion = eigene (oft unangenehme) Gefühle unbewusst einem anderen zuschreiben."],"abgrenzung":["Erleben (innen, verborgen) ≠ Verhalten (außen, sichtbar) – wir sehen nur das Verhalten und schließen daraus auf das Erleben.","Grundlagenwissen ≠ Therapie: Der SMA deeskaliert, er behandelt nicht."],"praxis":["Wer versteht, dass hinter Aggression oft Angst oder Hilflosigkeit steckt, reagiert ruhiger und treffsicherer.","Die eigene Stimmung färbt ab: Bist du angespannt, deutest du neutrales Verhalten schnell als ‚feindlich' – das ist Projektion."]},"visual":null},{"h":"Menschenkenntnis","b":"Fähigkeit, Menschen einzuschätzen; Aneignung durch Erfahrung, Beobachtung, Erkenntnis","detail":{"titel":"Menschenkenntnis","kat":"Wahrnehmung · Menschenkenntnis","katCls":"mensch","merksatz":"Menschenkenntnis ist die Fähigkeit, andere Menschen und ihr wahrscheinliches Verhalten realistisch einzuschätzen. Sie ist nicht angeboren, sondern wächst durch Erfahrung, Beobachtung und Erkenntnis.","funktion":["Definition: die Fähigkeit, Menschen, ihre Stimmungen und ihr voraussichtliches Verhalten treffend einzuschätzen.","Erwerb: durch Erfahrung (viele Begegnungen), durch genaues Beobachten und durch ehrliche Erkenntnis – also aus Fehleinschätzungen lernen.","Nutzen im Dienst: Stimmungen früh erkennen, eine Eskalation kommen sehen und Menschen passend ansprechen.","Haltung: demütig bleiben – Menschenkenntnis liefert Wahrscheinlichkeiten, keinen Röntgenblick; erster Eindruck und Vorurteil dürfen sie nicht ersetzen."],"schutzziel":"Menschen und Situationen früh und treffend einschätzen, um Gefahren rechtzeitig zu erkennen.","kennwerte":[{"l":"Definition","v":"Menschen treffend einschätzen"},{"l":"Erwerb","v":"Erfahrung · Beobachtung · Erkenntnis"},{"l":"Grenze","v":"Wahrscheinlichkeit, kein Beweis"}],"begriffe":["Menschenkenntnis = erfahrungsbasierte Fähigkeit, das Verhalten und Erleben anderer einzuschätzen.","Erkenntnis = das bewusste Lernen aus Beobachtung und Erfahrung, auch aus eigenen Fehlern."],"abgrenzung":["Menschenkenntnis ≠ Vorurteil: Sie prüft und korrigiert sich laufend, während ein Vorurteil starr bleibt.","Menschenkenntnis ≠ erster Eindruck: Der erste Eindruck ist nur ein Startpunkt, den man überprüfen muss."],"praxis":["Erfahrene Türsteher ‚lesen' eine Gruppe oft Sekunden vor dem Streit – das ist trainierte Beobachtung, kein Zauber.","Bleib offen für Korrektur: Wer sich für unfehlbar hält, liegt am Ende öfter daneben."]},"visual":null}],"quiz":[{"q":"Wodurch kann die Wahrnehmung negativ beeinflusst werden?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Durch Aufmerksamkeit","c":false},{"t":"Durch Interesse","c":false},{"t":"Durch Angst","c":true},{"t":"Durch Stress","c":true}]},{"q":"Wodurch kann die Wahrnehmung positiv beeinflusst werden?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Durch Überforderung","c":false},{"t":"Durch Interesse","c":true},{"t":"Durch Frustration","c":false},{"t":"Durch Aufmerksamkeit","c":true}]},{"q":"Wie können Konflikte mit schutzbedürftigen Personen entstehen?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wenn bei eigenem Fehlverhalten eine Entschuldigung angeboten wird","c":false},{"t":"Wenn Vorurteile das Verhalten der Beteiligten beeinflussen","c":true},{"t":"Wenn vorhandene Ängste das Verhalten der Beteiligten steuern","c":true},{"t":"Wenn sich die schutzbedürftige Person ernst genommen und respektiert fühlt","c":false}]},{"q":"Was soll eine Wachperson bei der Befragung einer Person mit seelischer Behinderung beachten?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Ihr signalisieren, dass sie nicht ernst genommen werden kann","c":false},{"t":"Ihr mit Respekt und Toleranz begegnen","c":true},{"t":"Es als Verrücktheit verstehen und sie auffordern, sich zusammenzureißen","c":false},{"t":"Ihr die objektive Wahrnehmungsfähigkeit absprechen","c":false}]},{"q":"Was ist Wahrnehmung?","a":"Wahrnehmung ist wie ich meine Umwelt (Informationen) durch die Sinne aufnehme Sehen, Hören, Riechen,...","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Definition für Selbstwertgefühl?","a":"Das Gefühl vom Wert des eigenen Selbst (Selbstbewusstsein, Selbstsicherheit, Selbstvertrauen). Entsteht aus der Wahrnehmung und Beurteilung der eigenen Person; Es ist damit das Ergebnis des Selbstbildes, das ein Mensch von sich hat; Die Einschätzung der eigenen Person bestimmte Situationen meistern zu können. Eine realistische Selbsteinschätzung führt zu einem angemessenen Selbstvertrauen und damit zu angemessenem Verhalten und Handeln","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind Vorurteile und wie entstehen Vorurteile?","a":"Vorurteile ist ungeprüfte Meinungen die man anderen Menschen oder Sachen gegenüber hat, diese entstehen durch eigene Erfahrung, durch Verallgemeinerung durch andere und auch durch Medien; Vorurteile können in bestimmten Situationen aber auch positiv sein (Schutzwirkung).","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie in der Kommunikation unter dem „Eisbergmodell“?","a":"Sachebene> beinhalten Fakten, Informationen, Sachverhalte> stellt etwa 20% der zwischenmenschlichen Kommunikation dar Beziehungsebene> beinhaltet Gefühle, Motive, Vorurteile> stellt etwa 80% der zwischenmenschlichen Kommunikation dar Beide Ebenen spielen in der Kommunikation zusammen. Die Beziehungsebene hat immer Einfluss auf die Sachebene. (kann ich den anderen besser leiden, ist die Kommunikation positiver, als bei einem Partner den ich nicht Leiden kann.)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter dem „ersten Eindruck“?","a":"ist das erste Bild, was ich mir über einen anderen Menschen mache entsteht in den ersten Sekunden (~ 5-20 Sekunden) ergibt sich aus dem Verhalten des Gegenübers (Aussehen, Auftreten -Mimik/Gestik-, Kleidung) ergibt sich aus eigenen Erfahrungswerten (Menschenkenntnis) und Vorurteilen Ist für Wachpersonen relevant in Bezug auf das weitere Verfahren (Kommunikation, Eigensicherung, etc.)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was sind Vorurteile und woher kommen sie?","a":"„nicht Fakten basierte“ Meinung über andere wird gern als „ungeprüfte Übernahme Meinungen Dritter“ definiert es gibt positive und negative Vorurteile Vorurteile werden geprägt durch:- eigene Erfahrungen, Familie, Freunde/Bekannte, Medien, soziale Netzwerke","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist für das Bewachungsgewerbe Psychologie?","a":"Die Lehre vom (sichtbaren) Verhalten und (nicht sichtbarem) Erleben der Menschen. Psychologen erforschen, warum eine bestimmte Person in einer bestimmten Situation ein bestimmtes Verhalten anzeigt – und welche inneren und äußeren Vorgänge dabei ablaufen. Die Bedeutung für das Bewachungsgewerbe, liegt darin Fehlurteile zu vermeiden und mögliche Gefahrensituationen vorausschauen zu können • Verhalten ist das, was sichtbar und hörbar ist: Gestik, Mimik, Sprechen, Weinen usw. • Erleben ist alles, was unsichtbar bleibt: Denken, Wahrnehmen, Gefühle, Triebe usw.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist Psychologie ?","a":"Ist die erfahrungsbasierte Wissenschaft über das Erleben und Verhalten von Menschen. Sie beschäftigt sich unter anderem mit der Persönlichkeit des Menschen.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Erkläre Menschenkenntnis und wie kann man sich","a":"diese aneignen? Menschenkenntnis ist wie ich andere Menschen einschätze, man erlangt diese durch Erfahrung und Umgang mit Menschen","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[{"scenario":"Beim Schichtbeginn wird dir ein Mann mit roter Kappe als ‚verdächtig' gemeldet. Du behältst ihn die ganze Zeit im Auge. Währenddessen steckt eine unauffällige Person ein paar Meter weiter seelenruhig Ware ein und verlässt den Laden.","frage":"Welcher Wahrnehmungseffekt hat hier zugeschlagen – und wie vermeidest du ihn?","loesung":"Selektive Wahrnehmung mit Tunnelblick: Durch die Fixierung auf den ‚roten Kappen-Mann' hat dein Gehirn alles andere ausgeblendet – der echte Täter blieb unbemerkt. Denkschlüssel: Eine Vorabmeldung ist ein Hinweis, kein Scheuklappen-Befehl. Beobachte gezielt, aber halte den Blick bewusst breit und scanne immer wieder das gesamte Umfeld."},{"scenario":"Zwei Personen betreten das Objekt: eine elegant gekleidete Frau und ein junger Mann in zerschlissener Kleidung mit Kapuze. Du kontrollierst nur den jungen Mann genauer und winkst die Frau ohne Blick durch. Später stellt sich heraus, dass die Frau unberechtigt Firmenunterlagen mitgenommen hat.","frage":"Welcher Fehler liegt vor – und welche Pflicht hast du als Wachperson?","loesung":"Ein Vorurteil nach Aussehen, hier sogar ein positives: ‚gepflegt = harmlos', ‚zerschlissen = verdächtig'. Genau das hat den Blick verzerrt und die eigentliche Tat ermöglicht. Denkschlüssel: nach Verhalten urteilen, nicht nach Kleidung oder Herkunft. Eigene Vorurteile erkennen und bewusst hinterfragen, jedem mit Respekt und Toleranz begegnen und gleiche Maßstäbe anlegen."}]},{"n":5,"title":"Erster Eindruck & Auftreten","subtitle":"3 Konzepte · 15 Prüfungsfragen","cards":[{"h":"Erster Eindruck","b":"Entsteht in 10–30 Sek.; starkes Vorurteil, stetig hinterfragen; Bewertungsmerkmale","detail":{"titel":"Erster Eindruck","kat":"Erster Eindruck · Grundlagen","katCls":"mensch","merksatz":"Der erste Eindruck entsteht unbewusst in Bruchteilen einer Sekunde. Er ist ein starkes, gefühlsmäßiges Vorurteil – kein rationales Gesamturteil über den Charakter – und muss deshalb bewusst hinterfragt werden.","funktion":["Er entsteht blitzschnell und unbewusst, nicht rational – und erfasst NICHT den wahren Charakter eines Menschen.","Er wirkt wie ein Vorurteil: er färbt den weiteren Umgang und kann sogar Erinnerungen wecken (das Gegenüber erinnert an jemanden).","Bewertet wird nach äußeren Merkmalen: Kleidung, Körperhaltung, Mimik, Stimme, Auftreten.","Man bekommt nur EINEN ersten Eindruck – er lässt sich kaum korrigieren; deshalb zählt das eigene Auftreten ab der ersten Sekunde."],"schutzziel":"Andere fair einschätzen (den ersten Eindruck hinterfragen) und selbst von der ersten Sekunde an sicher und professionell wirken.","kennwerte":[{"l":"Entstehung","v":"unbewusst, in Sekunden"},{"l":"Charakter","v":"erfasst ihn NICHT"},{"l":"Wesen","v":"starkes Vorurteil"},{"l":"Pflicht","v":"bewusst hinterfragen"}],"begriffe":["Erster Eindruck = das sofortige, unbewusste Gesamtbild, das wir uns in den ersten Sekunden von einer Person machen.","Halo-Effekt = ein auffälliges Merkmal (z. B. ein gepflegtes Äußeres) überstrahlt das Gesamturteil."],"abgrenzung":["Prüfungsfalle: Der erste Eindruck ist NICHT immer richtig (auch nicht bei guter Menschenkenntnis) und KEIN rationaler Vorgang.","Erster Eindruck ≠ Menschenkenntnis: Der erste Eindruck ist nur der Startpunkt, die Menschenkenntnis prüft nach."],"praxis":["Für dich gilt: Du hast nur eine Chance auf den ersten Eindruck – Haltung, Blick und Gruß in den ersten Sekunden zählen.","Beim Gegenüber: den ersten Eindruck zur Kenntnis nehmen, aber nicht zum Urteil machen – sonst übersieht man Wichtiges."]},"visual":null},{"h":"Repräsentation","b":"SMA vertritt Auftraggeber und Firma; gepflegtes, sicheres Auftreten, Gleichbehandlung","detail":{"titel":"Repräsentation","kat":"Erster Eindruck · Repräsentation","katCls":"mensch","merksatz":"Die Sicherheitskraft repräsentiert nach außen den Auftraggeber UND das eigene Sicherheitsunternehmen. Ihr Auftreten fällt immer auf beide zurück – deshalb gepflegt, sicher und freundlich auftreten und alle Menschen gleich behandeln.","funktion":["Doppelte Repräsentation: Die Wachperson steht nach außen für den Auftraggeber (z. B. das Kaufhaus) und zugleich für die eigene Firma.","Visitenkarte: gepflegtes Erscheinungsbild, korrekte und saubere Dienstkleidung, sicheres und höfliches Auftreten.","Gleichbehandlung: alle Kunden und Besucher fair und gleich behandeln – keine Bevorzugung, keine Diskriminierung.","Außenwirkung: Unhöflichkeit oder Fehler beschädigen sofort den Ruf von Auftraggeber UND Sicherheitsunternehmen."],"schutzziel":"Das Vertrauen in Auftraggeber und Sicherheitsunternehmen wahren und durch professionelles Auftreten Konflikte vermeiden.","kennwerte":[{"l":"Vertritt","v":"Auftraggeber + eigene Firma"},{"l":"Erscheinungsbild","v":"gepflegt, korrekt"},{"l":"Grundsatz","v":"Gleichbehandlung"},{"l":"Wirkung","v":"fällt auf beide zurück"}],"begriffe":["Repräsentieren = eine Person oder Organisation nach außen vertreten und in der Öffentlichkeit verkörpern.","Auftraggeber = das Unternehmen, das die Sicherheitsdienstleistung in Auftrag gegeben hat."],"abgrenzung":["Die Wachperson tritt nicht als Privatperson auf, sondern als Vertreter – die eigene ‚schlechte Tagesform' darf das Auftreten nicht bestimmen.","Repräsentation heißt nicht ‚wichtig tun': gepflegt und freundlich, nicht überheblich oder dominant."],"praxis":["Eine fleckige Uniform oder eine pampige Ansage fällt sofort auf das Kaufhaus UND die Sicherheitsfirma zurück.","Stammgast und Laufkundschaft gleich behandeln – Gleichbehandlung schützt zugleich vor Diskriminierungsvorwürfen."]},"visual":null},{"h":"Verhalten (inneres/äußeres)","b":"Mimik/Gestik vs. Gefühle/Denken; jedes Verhalten ist Kommunikation","detail":{"titel":"Inneres und äußeres Verhalten","kat":"Erster Eindruck · Verhalten","katCls":"mensch","merksatz":"Äußeres Verhalten ist alles von außen Sichtbare (Mimik, Gestik, Körperhaltung, Sprache); inneres Verhalten sind die nicht sichtbaren Gefühle und Gedanken. Entscheidend: Man kann sich nicht ‚nicht verhalten' – jedes Verhalten wirkt und teilt etwas mit.","funktion":["Äußeres Verhalten: sichtbar und hörbar – Mimik, Gestik, Körperhaltung, Tonfall und Worte.","Inneres Verhalten: verborgen – Gefühle, Gedanken und Einstellungen; vom äußeren schließen wir auf das innere.","Grundsatz: Jedes Verhalten ist Kommunikation – auch Schweigen, Wegschauen oder die Körperhaltung senden eine Botschaft.","Konsequenz: Die Wachperson sendet ununterbrochen Signale – bewusstes, kontrolliertes Auftreten ist daher Pflicht."],"schutzziel":"Die eigene Außenwirkung bewusst steuern und das Verhalten anderer richtig deuten.","kennwerte":[{"l":"Äußeres","v":"Mimik · Gestik · Haltung · Sprache"},{"l":"Inneres","v":"Gefühle · Gedanken (verborgen)"},{"l":"Grundsatz","v":"jedes Verhalten wirkt"},{"l":"Schluss","v":"von außen auf innen"}],"begriffe":["Äußeres Verhalten = das von anderen wahrnehmbare Handeln: Mimik, Gestik, Körperhaltung, Sprache.","Inneres Verhalten = die nicht direkt sichtbaren Vorgänge: Gefühle, Gedanken, Bewertungen."],"abgrenzung":["Inneres Verhalten (verborgen) ≠ äußeres Verhalten (sichtbar) – andere sehen nur das Äußere und deuten daraus das Innere, oft falsch.","Auch ‚nichts tun' ist Verhalten: Wegsehen oder verschränkte Arme senden eine klare Botschaft."],"praxis":["Verschränkte Arme und ein genervter Blick wirken abweisend – selbst wenn es freundlich gemeint war.","Wer innere Anspannung nicht nach außen zeigt, sondern ruhige Körpersprache hält, deeskaliert allein durchs Auftreten."]},"visual":null}],"quiz":[{"q":"Welche Aussagen über den ersten Eindruck sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Er ist immer richtig, wenn der Beobachter eine gute Menschenkenntnis besitzt","c":false},{"t":"Er entsteht unbewusst in Bruchteilen einer Sekunde","c":true},{"t":"Er ist ein rationaler Vorgang und vermittelt einen Gesamteindruck über den Charakter einer Person","c":false},{"t":"Er kann Erinnerungen wecken und so den Umgang mit dem Gegenüber beeinflussen","c":true}]},{"q":"Erster Eindruck, Erklärung und wie entsteht er?","a":"Der erste Eindruck entseht in ca. 10 - 30 Sekunden und gibt mir eine erste Einschätzung der Person.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Ist der erst Eindruck immer richtig?","a":"Nein, er ist nicht immer richtig, kann aber durch den zweiten Eindruck korrigiert werden. (Der „Erste“ Eindruck ist aber unumstößlich!)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie unter dem „ersten Eindruck“?","a":"ist das erste Bild, was ich mir über einen anderen Menschen mache entsteht in den ersten Sekunden (~ 5-20 Sekunden) ergibt sich aus dem Verhalten des Gegenübers (Aussehen, Auftreten -Mimik/Gestik-, Kleidung) ergibt sich aus eigenen Erfahrungswerten (Menschenkenntnis) und Vorurteilen Ist für Wachpersonen relevant in Bezug auf das weitere Verfahren (Kommunikation, Eigensicherung, etc.)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist für das Bewachungsgewerbe Psychologie?","a":"Die Lehre vom (sichtbaren) Verhalten und (nicht sichtbarem) Erleben der Menschen. Psychologen erforschen, warum eine bestimmte Person in einer bestimmten Situation ein bestimmtes Verhalten anzeigt – und welche inneren und äußeren Vorgänge dabei ablaufen. Die Bedeutung für das Bewachungsgewerbe, liegt darin Fehlurteile zu vermeiden und mögliche Gefahrensituationen vorausschauen zu können • Verhalten ist das, was sichtbar und hörbar ist: Gestik, Mimik, Sprechen, Weinen usw. • Erleben ist alles, was unsichtbar bleibt: Denken, Wahrnehmen, Gefühle, Triebe usw.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Umgang mit Menschen?","a":"Beim Umgang mit Menschen ist es sinnvoll Grundzüge menschlichen Verhaltens, Reaktionen, Emotionen und andere Faktoren zu kennen. Im Umgang mit Menschen können Gefahren erkannt werden bevor diese entstehen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind Motive?","a":"Beweggründe des Handelns (Man hat Hunger und man isst) Motive Motivation Verhalten","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Definition für Selbstwertgefühl?","a":"Das Gefühl vom Wert des eigenen Selbst (Selbstbewusstsein, Selbstsicherheit, Selbstvertrauen). Entsteht aus der Wahrnehmung und Beurteilung der eigenen Person; Es ist damit das Ergebnis des Selbstbildes, das ein Mensch von sich hat; Die Einschätzung der eigenen Person bestimmte Situationen meistern zu können. Eine realistische Selbsteinschätzung führt zu einem angemessenen Selbstvertrauen und damit zu angemessenem Verhalten und Handeln","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erklären Sie uns das Johari Window Modell.","a":"Das Johari Fenster verdeutlicht modellhaft, welche Bereiche beim Selbst- und Fremdbild sichtbar und welche unsichtbar sind Es gibt vier Felder - Öffentlich, alles was ein Mensch von sich preisgibt, Erscheinungsbild, körperliche Reaktion - Geheim, was man weiß und kennt, was man anderen verbirgt - Blinder Fleck, was selber aussendet was einen aber nicht bewusst ist, Verhaltensweisen - Unbekannt, ist was man selber und der andere nicht bekannt ist","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Aggression bzw. eine Aggressionsverschiebung?","a":"Ist ein Verhalten, das darauf abzielt, andere Menschen und deren Interessen zu verletzen oder zu zerstören, entweder körperlich oder verbal Aggressionsverschiebung - gegen andere Dinge oder Menschen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was charakterisiert eine Gruppe, verhalten in Gruppen?","a":"Eine Gruppe hat ein gemeinsames Ziel, man kennt sich untereinander. Das Verhalten in einer Gruppe ist geregelt, es gibt eine Rangfolge.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Verhaltensempfehlung bei Jugendlichen?","a":"Respektvoll behandeln, ernst nehmen, Grenzen zeigen, als Vorbild auftreten.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Verhaltensempfehlung bei Betrunkenen oder Drogensüchtigen?","a":"Respektvoll behandeln, ernst nehmen, auf Sachebene kommunizieren, Eigensicherung","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist Psychologie ?","a":"Ist die erfahrungsbasierte Wissenschaft über das Erleben und Verhalten von Menschen. Sie beschäftigt sich unter anderem mit der Persönlichkeit des Menschen.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche drei Motive prägen die menschliche Persönlichkeit?","a":"Verstand> Denken, Wissen, Fantasie Gefühl> Liebe, Hass, Neid Trieb> Hunger, Selbsterhaltung, Sexualtrieb Der Mensch kann durch dasEinwirken auf einzelne oder mehrere Motive in seinem Verhalten manipuliert werden.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist Kommunikation ?","a":"wechselseitiger Austausch von Informationen oder Botschaften Kommunikativer Grundsatz: „Man kann nicht, nicht kommunizieren“(bedeutet: eine Kommunikation findet zwischen den Menschen immer statt.Gewollt oder ungewollt, durch Worte, Verhalten, Bilder oder unbewusste Taten)","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[{"scenario":"Ein Besucher kommt mürrisch und wortkarg an die Info und vermeidet Blickkontakt. Du stufst ihn sofort als ‚unsympathisch und schwierig' ein und fertigst ihn knapp ab. Tatsächlich war er nur stark verunsichert und suchte dringend Hilfe wegen eines Notfalls im Gebäude.","frage":"Welcher Effekt hat dich getäuscht – und wie hättest du es besser gemacht?","loesung":"Der erste Eindruck: Er entsteht unbewusst in Sekunden und ist ein starkes Vorurteil – er erfasst NICHT den wahren Charakter. Hier hat das Blitzurteil ‚schwierig' den Blick verstellt. Denkschlüssel: den ersten Eindruck zur Kenntnis nehmen, aber bewusst hinterfragen und jedem zunächst freundlich und offen begegnen – sonst übersieht man, was wirklich los ist."},{"scenario":"Wachmann M hat privaten Ärger und steht in offener, fleckiger Uniform an der Kundeninfo eines Kaufhauses. Auf eine harmlose Frage reagiert er patzig und genervt. Der Kunde beschwert sich anschließend lautstark – beim Kaufhaus und beim Sicherheitsdienst.","frage":"Welche Pflicht hat M verletzt – und worauf kommt es an?","loesung":"M repräsentiert nach außen zugleich den Auftraggeber (das Kaufhaus) und sein eigenes Sicherheitsunternehmen. Sein Erscheinungsbild und sein Ton fallen auf beide zurück und beschädigen deren Ruf. Denkschlüssel: Im Dienst ist man nie Privatperson – gepflegtes Erscheinungsbild, freundliches und sicheres Auftreten, Gleichbehandlung aller; privater Ärger darf das Auftreten nicht bestimmen."}]},{"n":6,"title":"Kommunikation","subtitle":"7 Konzepte · 17 Prüfungsfragen","cards":[{"h":"Kommunikationsbegriff","b":"Wechselseitiger Austausch von Botschaften Sender↔Empfänger; löst immer Reaktion aus","detail":{"titel":"Kommunikationsbegriff","kat":"Kommunikation · Grundlagen","katCls":"mensch","merksatz":"Kommunikation ist der wechselseitige Austausch von Botschaften zwischen einem Sender und einem Empfänger. Sie löst beim Empfänger immer eine Reaktion aus – auch Schweigen ist eine Antwort.","funktion":["Grundmodell: Ein Sender verschlüsselt eine Botschaft (kodiert), sendet sie über einen Kanal; der Empfänger entschlüsselt sie (dekodiert).","Wechselseitig: Sender und Empfänger wechseln ständig die Rollen – Kommunikation ist keine Einbahnstraße.","Sie löst immer eine Reaktion aus: Jede Botschaft wirkt, eine ‚neutrale' Kommunikation gibt es nicht.","Missverständnisse entstehen, wenn Kodieren und Dekodieren auseinanderlaufen – Rückfragen und Wiederholen beugen vor."],"schutzziel":"Botschaften so austauschen, dass sie ankommen wie gemeint – die Grundlage jeder Konfliktvermeidung.","kennwerte":[{"l":"Modell","v":"Sender → Botschaft → Empfänger"},{"l":"Merkmal","v":"wechselseitig"},{"l":"Wirkung","v":"löst immer Reaktion aus"},{"l":"Risiko","v":"Kodieren ≠ Dekodieren"}],"begriffe":["Sender = wer eine Botschaft aussendet; Empfänger = wer sie aufnimmt und deutet.","Kodieren/Dekodieren = die Botschaft in Worte/Zeichen fassen bzw. sie wieder entschlüsseln."],"abgrenzung":["Kommunikation ist nicht nur Sprache: Tonfall, Körper und Situation gehören dazu (mehr dazu bei den Kommunikationsarten).","Senden ≠ Ankommen: Erst wenn der Empfänger es richtig dekodiert, ist die Kommunikation gelungen."],"praxis":["Im Dienst sicherstellen, dass eine Anweisung verstanden wurde – kurz wiederholen lassen statt blind annehmen.","Auch Wegsehen oder Schweigen sendet eine Botschaft – das Gegenüber reagiert immer darauf."]},"visual":null},{"h":"Interkulturelle Kompetenz","b":"Effektiv und angemessen in interkulturellen Situationen reagieren; Missverständnisse vermeiden","detail":{"titel":"Interkulturelle Kompetenz","kat":"Kommunikation · Interkulturell","katCls":"mensch","merksatz":"Interkulturelle Kompetenz ist die Fähigkeit, in Situationen mit Menschen aus anderen Kulturen angemessen und wirksam zu handeln. Ziel ist es, kulturbedingte Missverständnisse zu erkennen und Eskalationen zu vermeiden.","funktion":["Bewusstsein: Gesten, Blickkontakt, Nähe und Begrüßung bedeuten in Kulturen Unterschiedliches – nicht alles ist gemeint wie bei uns.","Haltung: Respekt und Toleranz; eigene Werte transparent machen, ohne zu belehren.","Eskalationsgefahr: wenn sich mehrere gegen eine Minderheit verbünden oder Ungeduld entsteht, weil Informationen nicht sofort verstanden werden.","Bei Geflüchteten: Fragen stellen, aktiv zuhören, einfache klare Sprache; Ordnungsregeln nicht stur ‚in jedem Fall' durchdrücken."],"schutzziel":"Mit Menschen aller Herkunft fair und deeskalierend umgehen – Verständigung statt Konflikt.","kennwerte":[{"l":"Definition","v":"angemessen handeln über Kulturen"},{"l":"Haltung","v":"Respekt · Toleranz"},{"l":"Eskaliert","v":"Mehrheit gegen Minderheit / Ungeduld"},{"l":"Geflüchtete","v":"fragen · aktiv zuhören"}],"begriffe":["Interkulturelle Kompetenz = kulturelle Unterschiede kennen und im Umgang berücksichtigen.","Kulturelle Prägung = erlernte Werte, Normen und Ausdrucksformen einer Gruppe."],"abgrenzung":["Interkulturelle Kompetenz ≠ alles gutheißen: Regeln gelten weiter, sie werden nur respektvoll und verständlich vermittelt.","Eine andere Geste (z. B. fehlender Blickkontakt) ist nicht automatisch Respektlosigkeit – sie kann kulturell bedingt sein."],"praxis":["Bei Sprachbarrieren: kurze Sätze, ruhiger Ton, ggf. zeigen statt nur reden.","Nicht zulassen, dass sich eine Gruppe gegen eine einzelne Person zusammenrottet – früh trennen und beruhigen."]},"visual":null},{"h":"Eisbergmodell","b":"Beziehungsebene ~80% vs. Sachebene ~20%; gute Beziehungsebene sichert Sachbotschaft","detail":{"titel":"Eisbergmodell","kat":"Kommunikation · Eisbergmodell","katCls":"mensch","merksatz":"Das Eisbergmodell teilt jede Botschaft in eine sichtbare Sachebene (~20 %) und eine verborgene Beziehungsebene (~80 %). Die Beziehungsebene entscheidet, ob die Sachbotschaft überhaupt ankommt.","funktion":["Sachebene (~20 %): die reine Information, das ‚Was' – über der Wasseroberfläche, sichtbar.","Beziehungsebene (~80 %): Gefühle, Stimmung, das ‚Wie' und ‚Wie wir zueinander stehen' – unter Wasser, verborgen, aber dominant.","Ist die Beziehungsebene gestört (Wut, Misstrauen), blockiert sie die Sachebene – die beste Information kommt nicht durch.","Deshalb zuerst die Beziehungsebene bedienen (Wertschätzung, ruhiger Ton), dann die Sache klären."],"schutzziel":"Botschaften durchbringen, indem zuerst die Beziehung stimmt – Konflikte entstehen meist auf der Beziehungsebene.","kennwerte":[{"l":"Sachebene","v":"~20 % · das Was"},{"l":"Beziehungsebene","v":"~80 % · das Wie"},{"l":"Regel","v":"Beziehung trägt die Sache"},{"l":"Bild","v":"Eisberg unter Wasser"}],"begriffe":["Sachebene = der reine Informationsgehalt einer Nachricht.","Beziehungsebene = wie die Gesprächspartner zueinander stehen und sich behandelt fühlen."],"abgrenzung":["Eisbergmodell ≠ ‚Gefühle sind unwichtig': Im Gegenteil – die unsichtbaren 80 % steuern, ob die sichtbaren 20 % wirken.","Sachlich ‚recht haben' nützt wenig, wenn die Beziehungsebene zerstört ist – dann hört keiner mehr zu."],"praxis":["Einen wütenden Kunden erst ankommen lassen (‚Ich sehe, dass Sie verärgert sind'), dann zur Sache – sonst prallt jede Information ab.","Ein gereizter Ton transportiert mehr als der Inhalt – auf das eigene ‚Wie' achten."]},"visual":null},{"h":"Kommunikationsarten (4)","b":"verbal 10%, nonverbal 50%, paraverbal 30%, extraverbal 10%","detail":{"titel":"Kommunikationsarten","kat":"Kommunikation · Arten","katCls":"mensch","merksatz":"Eine Botschaft wirkt über mehrere Kanäle: verbal (Worte), nonverbal (Körpersprache), paraverbal (Stimme/Tonfall) und extraverbal (Umfeld/Erscheinung). Der Wortanteil ist dabei am kleinsten – Körper und Stimme wirken am stärksten.","funktion":["Verbal (~10 %): die reinen Worte, der gesprochene Inhalt.","Nonverbal (~50 %): Mimik, Gestik, Körperhaltung, Blick – der stärkste Kanal.","Paraverbal (~30 %): wie etwas klingt – Tonfall, Lautstärke, Tempo, Betonung.","Extraverbal (~10 %): Rahmen und Erscheinung – Kleidung, Ort, Situation."],"schutzziel":"Bewusst auf allen Kanälen stimmig wirken – Worte, Körper und Stimme dürfen sich nicht widersprechen.","kennwerte":[{"l":"Verbal","v":"~10 % · Worte"},{"l":"Nonverbal","v":"~50 % · Körper"},{"l":"Paraverbal","v":"~30 % · Stimme"},{"l":"Extraverbal","v":"~10 % · Umfeld"}],"begriffe":["Nonverbale Kommunikation = Verständigung ohne Worte über Mimik, Gestik, Haltung.","Paraverbale Kommunikation = der stimmliche Anteil: Ton, Lautstärke, Tempo, Melodie."],"abgrenzung":["Verbale Kommunikation nutzt Sprache – sie hat einen GERINGEREN Informationsanteil als die nonverbale, nicht umgekehrt.","Widersprechen sich Wort und Körper, glaubt das Gegenüber dem Körper (nonverbal) und der Stimme (paraverbal)."],"praxis":["Ruhige Stimme und offene Haltung beruhigen oft mehr als die besten Argumente.","Gesten helfen über Sprachgrenzen hinweg – sie ermöglichen in fast allen Kulturen Verständigung."]},"visual":null},{"h":"4 Seiten einer Nachricht (Schulz v. Thun)","b":"Sach-, Beziehungs-, Appell-, Offenbarungsseite","detail":{"titel":"Vier Seiten einer Nachricht (Schulz von Thun)","kat":"Kommunikation · Vier-Seiten-Modell","katCls":"mensch","merksatz":"Nach Schulz von Thun enthält jede Nachricht vier Botschaften zugleich: eine Sachseite, eine Selbstoffenbarung, eine Beziehungsseite und einen Appell. Sender und Empfänger können auf unterschiedlichen ‚Ohren' hören – das erzeugt Missverständnisse.","funktion":["Sachseite: die reine Information (worüber ich informiere).","Selbstoffenbarung: was ich von mir preisgebe (was in mir vorgeht).","Beziehungsseite: was ich von dir halte und wie wir zueinander stehen.","Appell: wozu ich dich veranlassen will (was du tun sollst)."],"schutzziel":"Botschaften vollständig verstehen und gezielt senden – und erkennen, auf welcher Seite ein Konflikt entsteht.","kennwerte":[{"l":"Sachseite","v":"die Information"},{"l":"Selbstoffenbarung","v":"was ich preisgebe"},{"l":"Beziehungsseite","v":"wie wir zueinander stehen"},{"l":"Appell","v":"was du tun sollst"}],"begriffe":["Vier-Seiten-Modell (Kommunikationsquadrat) = jede Nachricht hat vier gleichzeitige Botschaften.","Vier-Ohren-Modell = der Empfänger kann auf jedem der vier ‚Ohren' hören und so anders verstehen."],"abgrenzung":["Die vier Seiten sind Sach-, Beziehungs-, Selbstoffenbarungs- und Appellseite – ‚erster Eindruck' oder ‚Frustration' gehören NICHT dazu.","Ein Konflikt auf der Beziehungsseite lässt sich nicht auf der Sachseite lösen – man muss die richtige Ebene ansprechen."],"praxis":["‚Die Tür ist offen' kann Sachinfo ODER Appell (‚mach sie zu!') sein – im Zweifel nachfragen, was gemeint ist.","Wer auf dem ‚Beziehungsohr' überempfindlich hört, fühlt sich schnell angegriffen – das bewusst entschärfen."]},"visual":null},{"h":"Fehlerquellen der Kommunikation","b":"Fehler beim Senden/Empfangen; Empfang sicherstellen (nachfragen, wiederholen)","detail":{"titel":"Fehlerquellen der Kommunikation","kat":"Kommunikation · Fehlerquellen","katCls":"mensch","merksatz":"Fehler entstehen beim Senden (unklar, missverständlich kodiert) und beim Empfangen (überhört, falsch gedeutet). Wichtigste Gegenmaßnahme: den Empfang sicherstellen – nachfragen und wichtige Inhalte wiederholen lassen.","funktion":["Sendefehler: undeutlich, zu kompliziert, widersprüchlich oder ‚zwischen den Zeilen' formuliert.","Empfangsfehler: unaufmerksam, vorschnell gedeutet, durch Gefühle oder Vorurteile verzerrt.","Störungen: Lärm, Hektik, Stress, schlechte Funkverbindung – der Kanal selbst stört.","Gegenmittel: kurze klare Sätze, nachfragen, wichtige Aussagen wiederholen lassen (Empfang bestätigen)."],"schutzziel":"Missverständnisse vermeiden, bevor sie zu Konflikten werden – sicherstellen, dass die Botschaft ankommt.","kennwerte":[{"l":"Sendefehler","v":"unklar kodiert"},{"l":"Empfangsfehler","v":"falsch dekodiert"},{"l":"Störung","v":"Lärm · Stress · Kanal"},{"l":"Gegenmittel","v":"nachfragen · wiederholen"}],"begriffe":["Sendefehler = die Botschaft wird unklar oder missverständlich formuliert.","Empfangsfehler = die Botschaft wird unaufmerksam oder verzerrt aufgenommen."],"abgrenzung":["Missverständnisse vermeidet man NICHT, indem man auf unterschiedlichen Ebenen redet oder aus Höflichkeit so tut, als habe man alles verstanden.","Mehr Lautstärke behebt keinen Sendefehler – Klarheit und Rückfrage tun es."],"praxis":["Sender lässt wichtige Informationen vom Empfänger wiederholen, um Missverständnisse auszuschließen.","Empfänger fragt aktiv nach, wenn er etwas nicht vollständig verstanden hat – statt zu raten."]},"visual":null},{"h":"Kommunikationsfaktoren","b":"Sprache, Ausdruck/Betonung, Tempo/Pausen, Sprachmelodie, Mimik/Gestik, Körperhaltung, Abstand, Begrüßung","detail":{"titel":"Kommunikationsfaktoren","kat":"Kommunikation · Faktoren","katCls":"mensch","merksatz":"Über die Wirkung entscheiden viele Stellschrauben: Sprache und Wortwahl, Ausdruck und Betonung, Tempo und Pausen, Sprachmelodie, Mimik und Gestik, Körperhaltung, Abstand und Begrüßung. Wertschätzung und aktives Zuhören wirken positiv, Du-Vorwürfe und autoritäres Auftreten negativ.","funktion":["Stimme/Sprache: deutlich und klar sprechen, kurze Sätze, ruhiges Tempo, sinnvolle Pausen, angenehme Sprachmelodie.","Körper: offene Mimik und Gestik, zugewandte Haltung, angemessener Abstand, freundliche Begrüßung.","Positiv: aktives Zuhören und signalisierte Wertschätzung verbessern die verbale Kommunikation.","Negativ: Du-Vorwürfe, Besserwisserei und autoritärer ‚Wissensvorsprung' blockieren das Gespräch."],"schutzziel":"Bewusst die Faktoren wählen, die ein Gespräch tragen – und die meiden, die es blockieren.","kennwerte":[{"l":"Stimme","v":"klar · ruhig · Pausen"},{"l":"Körper","v":"offen · zugewandt · Abstand"},{"l":"Positiv","v":"Wertschätzung · aktiv zuhören"},{"l":"Negativ","v":"Du-Vorwurf · autoritär"}],"begriffe":["Sprachmelodie = das Auf und Ab der Stimme, das einer Aussage Bedeutung und Stimmung gibt.","Ich-Botschaft = aus der eigenen Sicht formulieren statt mit anklagendem ‚Du' (‚Ich brauche…' statt ‚Sie müssen…')."],"abgrenzung":["Positiv wirkt aktives Zuhören und Wertschätzung – NICHT, den eigenen Wissensvorsprung autoritär auszuspielen oder Du-Vorwürfe zu machen.","Ein professionelles Telefongespräch heißt: deutlich und klar, kurze Sätze, Störgeräusche vermeiden – nicht laut, schnell oder eintönig."],"praxis":["Eine freundliche Begrüßung und ruhiger Tonfall stellen sofort die Weichen für ein gutes Gespräch.","Statt ‚Sie haben das falsch gemacht' (Du-Vorwurf) lieber sachlich aus der Ich-Perspektive formulieren."]},"visual":null}],"quiz":[{"q":"Die Kommunikation hat den Informationsaustausch zwischen Sender und Empfänger zum Gegenstand. Wie lassen sich Missverständnisse vermeiden?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Indem der Sender wichtige Informationen durch den Empfänger wiederholen lässt","c":true},{"t":"Indem Sender und Empfänger auf unterschiedlichen Ebenen kommunizieren","c":false},{"t":"Indem der Empfänger nachfragt, wenn er eine Information nicht vollständig wahrgenommen hat","c":true},{"t":"Indem der Empfänger aus Höflichkeit den Sender glauben lässt, er habe alles verstanden","c":false}]},{"q":"Wann kann beim Umgang mit Gruppen aus unterschiedlichen Kulturen die Situation eskalieren?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wenn die Beteiligten miteinander reden und Interesse an einer Lösung zeigen","c":false},{"t":"Wenn sich mehrere Personen gegen eine Minderheit verbünden","c":true},{"t":"Wenn ein Gesprächspartner ungeduldig wird, weil seine Informationen nicht sofort verstanden werden","c":true},{"t":"Wenn durch verbale und nonverbale Kommunikation versucht wird, die Situation zu beruhigen","c":false}]},{"q":"Welche Aussagen über menschliche Gefühle sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Gesprächsführung kann erschwert sein, wenn die Beziehung durch Gefühle wie Wut gestört wird","c":true},{"t":"Im beruflichen Umfeld sind Gefühle wie Ärger und Enttäuschung positiv und mit Vernunft jederzeit steuerbar","c":false},{"t":"Die Kommunikation kann durch Gefühle, die sich auf der Beziehungsebene ausdrücken, beeinflusst werden","c":true},{"t":"Überzeugendes Auftreten ist nur mit sachlichen und rationalen Argumenten möglich, Gefühle sind störend","c":false}]},{"q":"Welche Aussagen zur verbalen Kommunikation sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sie verwendet zum Informationsaustausch Sprache","c":true},{"t":"Als Gespräch wird im Allgemeinen die verbale Kommunikation von Personen untereinander bezeichnet","c":true},{"t":"Sie nutzt zum Informationsaustausch Gesten, Blickkontakte und Mienenspiel","c":false},{"t":"Sie hat einen wesentlich höheren Informationsanteil als die nonverbale Kommunikation","c":false}]},{"q":"Was bewirken Gesten als Ausdrucksmittel der nonverbalen Kommunikation am ehesten?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sie ermöglichen in allen Kulturen Verständigung","c":true},{"t":"Sie verbessern die Verständlichkeit des Gesagten","c":true},{"t":"Sie verfälschen das Gesagte","c":false},{"t":"Sie stören die Kommunikation und lenken den Zuhörer ab","c":false}]},{"q":"Welche Aspekte sind den Kommunikationsebenen des Vier-Seiten-Modells (Kommunikationsquadrat) zuzuordnen?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Appell","c":true},{"t":"Beziehung","c":true},{"t":"Erster Eindruck","c":false},{"t":"Frustration","c":false}]},{"q":"Was kann die verbale Kommunikation positiv beeinflussen?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Aktives Zuhören","c":true},{"t":"Wissensvorsprung autoritär einsetzen","c":false},{"t":"Du-Formulierungen verwenden","c":false},{"t":"Wertschätzung signalisieren","c":true}]},{"q":"Was ist Kommunikation?","a":"Kommunikation ist der Austausch von Botschaften zwischen Sender und Empfänger, Verbal und Nonverbal. Sachebene","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Auf welchen Ebenen kommunizieren wir?","a":"Auf der Sach- und Gefühlsebene. Gefühlsebene","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist Kommunikation ?","a":"wechselseitiger Austausch von Informationen oder Botschaften Kommunikativer Grundsatz: „Man kann nicht, nicht kommunizieren“(bedeutet: eine Kommunikation findet zwischen den Menschen immer statt.Gewollt oder ungewollt, durch Worte, Verhalten, Bilder oder unbewusste Taten)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was bedeutet „Interkulturelle Kompetenz“ ? (ist die Fähigkeit mit Menschen aus","a":"anderen Kulturkreisen umzugehen und angemessen zu kommunizieren) Hier kann es schnell zu gravierenden Missverständnissen und Konflikten kommen (unterschiedliche Bedeutung/Interpretation von Körpersprache und Worten). - kulturelle und religiöse Unterschiede respektieren - Sprachtempo und Lautstärke anpassen - Wenn nötig, Sprachmittler einschalten","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie unter der sogenannten „interkulturellen Kompetenz“ ?","a":"Ist die Fähigkeit auf unterschiedliche kulturelle Kreise einzugehen und mit diesen möglichst konfliktfrei umzugehen Kulturelle Unterschiede:> Sprache, Mimik, Gestik, Glaube, Kleidung, Esskultur, Ehrkultur (Geschlechter, Alter, sozialer Stand) Die interkulturelle Kompetenz muss die Grundrechte stets berücksichtigen.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Verhaltensempfehlung bei Betrunkenen oder Drogensüchtigen?","a":"Respektvoll behandeln, ernst nehmen, auf Sachebene kommunizieren, Eigensicherung","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wichtige Schutzabstände (Distanzzonen)?","a":"- Intimdistanz, ca. 45cm (Frau, Kind, Familie) - Erweiterter Nahbereich, ca. 45 - 120 cm (Freunde, Bekannte) - Gesellschaftlicher Bereich, 120 - 360 cm (Kollegen, Bekannte) - Öffentlicher Bereich, ab 360 cm (Unbekannte) Die Distanz zum Gesprächspartner spielt in der Kommunikation eine nicht unbedeutende Rolle. Insbesondere bei Konflikten kann eine Verletzung der Distanzzonen (Eindringen in unser Territorium) eskalierend wirken.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie in der Kommunikation unter dem „Eisbergmodell“?","a":"Sachebene> beinhalten Fakten, Informationen, Sachverhalte> stellt etwa 20% der zwischenmenschlichen Kommunikation dar Beziehungsebene> beinhaltet Gefühle, Motive, Vorurteile> stellt etwa 80% der zwischenmenschlichen Kommunikation dar Beide Ebenen spielen in der Kommunikation zusammen. Die Beziehungsebene hat immer Einfluss auf die Sachebene. (kann ich den anderen besser leiden, ist die Kommunikation positiver, als bei einem Partner den ich nicht Leiden kann.)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie in der Kommunikation unter dem „Eisbergmodell“?","a":"bildliche Darstellung","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter dem „ersten Eindruck“?","a":"ist das erste Bild, was ich mir über einen anderen Menschen mache entsteht in den ersten Sekunden (~ 5-20 Sekunden) ergibt sich aus dem Verhalten des Gegenübers (Aussehen, Auftreten -Mimik/Gestik-, Kleidung) ergibt sich aus eigenen Erfahrungswerten (Menschenkenntnis) und Vorurteilen Ist für Wachpersonen relevant in Bezug auf das weitere Verfahren (Kommunikation, Eigensicherung, etc.)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter dem Vierseitenmodell nach Schulz von Thun?","a":"Beschreibt, dass jede Nachricht aus 4 Teilen (Seiten, Ebenen) besteht (sowohl bei Sender als auch beim Empfänger). Appellebene > veranlasst den Empfänger etwas zu tun oder zu unterlassen Sachebene > Übermittlung der Information Beziehungsebene\t> stellt die Beziehung zwischen Sender und Empfänger dar Offenbarungsebene\t> Sender gibt Informationen über sich","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Bennen Sie die Kommunikationsmittel mit % Angabe","a":"- Verbal 10% (das gesprochene Wort) - Extraverbal 10% (das äußere Erscheinungsbild) - Paraverbal 30% (der Ausdruck der Worte, laut, leise,...) - Nonverbal 50% (Körpersprache, Mimik)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Deeskalation?","a":"Deeskalation ist das Entspannen der unterschiedlichen Konflikte, indem man mit Kommunikationsmitteln, z.B. Gesten (Nonverbal) und beruhigenden Worten (rhetorische Deeskalation/Verbal) auf seinen Gegenüber eingeht.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Aggression bzw. eine Aggressionsverschiebung?","a":"Ist ein Verhalten, das darauf abzielt, andere Menschen und deren Interessen zu verletzen oder zu zerstören, entweder körperlich oder verbal Aggressionsverschiebung - gegen andere Dinge oder Menschen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Kommunikationsarten kennen Sie?","a":"Verbale Kommunikation> das gesprochen oder geschriebene Wort Nonverbale Kommunikation> Mimik, Gestik und Körperhaltung/Körpersprache Paraverbale Kommunikation> Tonlage, Aussprache, Sprachmelodie, Sprechpausen Extraverbale Kommunikation> Aussehen, Kleidung, Schmuck, Ort","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Nennen Sie die 4 Seiten/Ebenen einer Nachricht.","a":"- Sachseite - Beziehungsseite - Appellseite - Offenbarungsseite","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere Das 4 Ohr Prinzip nach Schulz von Thun.","a":"Wie nimmt man die gesendete Botschaft auf. - Sachohr, der sachliche Inhalt wurde verstanden - Beziehungsohr, wie spricht der Sender, mit Respekt oder Verachtung - Appellohr, bewirkt der Sender beim Empfänger etwas - Offenbarungsohr, der Empfänger hört was der Sender von sich preisgibt Beispiel: Ihr Beifahrer sagt kurz nachdem die Ampel auf Grün gesprungen ist „Grüner wird es nicht“. Dies ist die Nachricht - Sachinhalt (Fakten): Die Ampel ist grün - Selbstkundgabe (wie ich mich fühle, was ich darüber denke): Ich habe es eilig - Beziehung(wie ich zum Empfänger stehe): Nichts kannst du, immer muss man dir alles sagen - Appell (Aufforderung): Fahr los!","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[{"scenario":"Ein aufgebrachter Kunde beschwert sich lautstark. Du sagst ruhig: „Ich verstehe, dass Sie verärgert sind“, hältst Blickkontakt und fasst sein Anliegen in eigenen Worten zusammen.","frage":"Welche Kommunikationstechnik wendest du an und warum wirkt sie?","loesung":"Aktives Zuhören: Zuwendung, Blickkontakt, bestätigendes Wiederholen. Es bedient die Beziehungsebene (Eisbergmodell ~80%), nimmt Druck aus der Situation und macht die Sachebene überhaupt erst zugänglich."},{"scenario":"Du sagst zu einem wartenden Besucher sachlich: ‚Der Termin ist erst in einer Stunde.' Er fährt sofort hoch: ‚Wollen Sie mich loswerden?!' – obwohl du nur informieren wolltest.","frage":"Auf welcher Seite der Nachricht ist das Missverständnis entstanden – und wie löst du es?","loesung":"Du hast auf der Sachseite gesendet (reine Information), er hat auf dem Beziehungsohr gehört (‚Du bist unerwünscht'). Nach Schulz von Thun trägt jede Nachricht vier Seiten zugleich. Denkschlüssel: das Missverständnis auf der richtigen Ebene klären – erst die Beziehung beruhigen (‚Sie sind willkommen, ich sage nur Bescheid'), dann die Sachinfo wiederholen."}]},{"n":7,"title":"Frustration, Aggression & Konflikte","subtitle":"5 Konzepte · 10 Prüfungsfragen","cards":[{"h":"Frustration","b":"Negatives Gefühl bei Zielblockade; Folgen (Aggression u.a.); Umgang mit eigener/fremder Frustration","detail":{"titel":"Frustration","kat":"Konflikte · Frustration","katCls":"mensch","merksatz":"Frustration ist das negative Gefühl, das entsteht, wenn ein Ziel oder Bedürfnis blockiert wird – eine Enttäuschung. Sie kann verschiedene Folgen auslösen: Aggression, aber auch Resignation oder Rückzug.","funktion":["Entstehung: Ein angestrebtes Ziel wird versperrt oder blockiert → Enttäuschung, Ärger, Frust.","Mögliche Folgen: Aggression, Resignation, Rückzug, Ersatzhandlungen, auch Depression – nicht zwangsläufig Gewalt.","Frustrationstoleranz: die Fähigkeit, Enttäuschungen über einen längeren Zeitraum auszuhalten, ohne die Fassung zu verlieren.","Umgang: eigene Frustration erkennen und steuern; bei anderen Frust als häufige Ursache von Aggression verstehen."],"schutzziel":"Frust – den eigenen wie den fremden – früh erkennen, damit er nicht in Aggression umschlägt.","kennwerte":[{"l":"Auslöser","v":"blockiertes Ziel"},{"l":"Folgen","v":"Aggression · Resignation · Depression"},{"l":"Toleranz","v":"Enttäuschung aushalten"},{"l":"Gegenmittel","v":"erkennen + steuern"}],"begriffe":["Frustration = Enttäuschung durch ein blockiertes Ziel oder Bedürfnis.","Frustrationstoleranz = die Fähigkeit, über längere Zeit mit Enttäuschungen umzugehen, ohne die Fassung zu verlieren."],"abgrenzung":["Frustration führt NICHT zwangsläufig zu Aggression – sie kann auch in Resignation oder Rückzug münden.","Frustrationstoleranz ist NICHT die Fähigkeit, Frust gezielt in Aggression umzuwandeln – das ist das Gegenteil."],"praxis":["Ein abgewiesener Gast ist frustriert (Ziel blockiert) – wer das versteht, reagiert ruhiger statt persönlich gekränkt.","Eigene Frustration am Schichtende bewusst wahrnehmen, statt sie an Kollegen oder Kunden auszulassen."]},"visual":null},{"h":"Aggression","b":"Absicht zu verletzen/zerstören; Ursachen; Autoaggression; richtiger Umgang","detail":{"titel":"Aggression","kat":"Konflikte · Aggression","katCls":"mensch","merksatz":"Aggression ist ein Verhalten, das darauf gerichtet ist, jemanden oder etwas zu schädigen, zu verletzen oder zu zerstören – verbal (Beleidigung, Drohung) oder brachial (Gewalt). Sie ist nicht zwangsläufig die Folge von Frustration.","funktion":["Definition: zielgerichtetes Schädigen, Verletzen oder Zerstören von Personen, Sachen oder Tieren.","Formen: verbal (beleidigen, drohen) und brachial/körperlich (schlagen, zerstören).","Ursachen: Frustration, Angst, Nachahmung, Alkohol und Drogen, Gruppendruck – nicht nur Frust.","Autoaggression: Aggression, die sich gegen die eigene Person richtet."],"schutzziel":"Aggression früh erkennen, ihre Ursache verstehen und ruhig und sichernd darauf reagieren.","kennwerte":[{"l":"Definition","v":"schädigen · verletzen · zerstören"},{"l":"Formen","v":"verbal · brachial"},{"l":"Ursachen","v":"Frust · Angst · Alkohol · Gruppe"},{"l":"Autoaggression","v":"gegen sich selbst"}],"begriffe":["Aggression = auf Schädigung gerichtetes Verhalten gegen Personen, Sachen oder Tiere.","Autoaggression = gegen die eigene Person gerichtete Aggression."],"abgrenzung":["Aggression ist NICHT immer die Folge von Frustration und entlädt sich NICHT stets unbeabsichtigt – sie ist zielgerichtet.","Bei Betrunkenen überlagern Gefühle das klare Denken und die Aggressionsschwelle sinkt – die Hemmschwelle steigt NICHT."],"praxis":["Bei aggressivem Verhalten Sicherheitsabstand wahren und nicht mit Gegenaggression antworten.","Hinter Aggression steckt oft Angst oder Hilflosigkeit – dieses Wissen hilft, ruhig zu bleiben."]},"visual":null},{"h":"Aggressionsverschiebung","b":"Versetzte/indirekte Aggression gegen Ersatzobjekt, wenn Verursacher unerreichbar","detail":{"titel":"Aggressionsverschiebung","kat":"Konflikte · Verschiebung","katCls":"mensch","merksatz":"Aggressionsverschiebung ist versetzte, indirekte Aggression: Wenn der eigentliche Verursacher unerreichbar oder zu mächtig ist, richtet sich die aufgestaute Aggression gegen ein erreichbares Ersatzobjekt (Sündenbock).","funktion":["Mechanismus: Der wahre Auslöser (Chef, Behörde, Situation) ist unangreifbar → die Aggression sucht sich ein schwächeres, erreichbares Ziel.","Ersatzobjekt: oft Unbeteiligte – Kollegen, Familie, Gegenstände oder eben die Wachperson.","Erkennen: Die Heftigkeit passt nicht zum Anlass; man wird angegriffen, obwohl man nichts getan hat.","Umgang: nicht persönlich nehmen, deeskalieren und dem Gegenüber einen gesichtswahrenden Ausweg lassen."],"schutzziel":"Verstehen, warum man scheinbar grundlos angegriffen wird – und ruhig statt gekränkt reagieren.","kennwerte":[{"l":"Mechanismus","v":"Ziel unerreichbar → Ersatz"},{"l":"Ersatzobjekt","v":"Sündenbock / Unbeteiligte"},{"l":"Erkennen","v":"Heftigkeit ≠ Anlass"},{"l":"Umgang","v":"nicht persönlich nehmen"}],"begriffe":["Aggressionsverschiebung = Aggression, die sich auf ein Ersatzobjekt statt auf den eigentlichen Verursacher richtet.","Sündenbock = unbeteiligte Person, an der stellvertretend Aggression abgeladen wird."],"abgrenzung":["Der Angriff gilt meist nicht dir persönlich – du bist nur das erreichbare Ersatzobjekt.","Aggressionsverschiebung ≠ direkte Aggression: Der eigentliche Auslöser ist ein anderer."],"praxis":["Ein Gast, der gerade privat Ärger hatte, lädt seinen Frust bei dir ab – ruhig bleiben, nicht zurückschießen.","Wer das Muster erkennt, nimmt Beschimpfungen im Dienst nicht persönlich und bleibt handlungsfähig."]},"visual":null},{"h":"Konflikt & Konfliktarten","b":"Widerstrebende Interessen; geistige/körperliche Ursachen","detail":{"titel":"Konflikt & Konfliktarten","kat":"Konflikte · Arten","katCls":"mensch","merksatz":"Ein Konflikt entsteht, wenn widerstrebende Interessen, Ziele oder Bedürfnisse aufeinandertreffen. Die Ursachen können geistig-seelisch (Meinungen, Werte, Gefühle) oder körperlich-materiell (Raum, Sachen, Ressourcen) sein.","funktion":["Definition: der Zusammenprall unvereinbarer Interessen, Ziele, Werte oder Bedürfnisse.","Arten nach Ursache: geistig-seelisch (Meinungen, Überzeugungen, Gefühle) und körperlich-materiell (Platz, Besitz, Ressourcen).","Ebenen: innere Konflikte (in einer Person) und äußere Konflikte (zwischen Personen oder Gruppen).","Eskalationsgefahr: ungelöste Konflikte führen über Frust und Aggression bis hin zu Gewalt."],"schutzziel":"Konflikte früh erkennen und einordnen, um sie zu entschärfen, bevor sie eskalieren.","kennwerte":[{"l":"Definition","v":"widerstrebende Interessen"},{"l":"Ursachen","v":"geistig · körperlich/materiell"},{"l":"Ebenen","v":"innen · zwischen Personen"},{"l":"Risiko","v":"Eskalation zu Gewalt"}],"begriffe":["Konflikt = Zusammenprall unvereinbarer Interessen, Ziele oder Bedürfnisse.","Interessenkonflikt = zwei Parteien wollen Unvereinbares (z. B. denselben Platz)."],"abgrenzung":["Ein Konflikt ist nicht von vornherein ‚schlecht' – erst ungelöst und eskaliert wird er gefährlich.","Sachkonflikt (um Dinge) ≠ Beziehungskonflikt (um Wertschätzung) – beide brauchen unterschiedliche Lösungen."],"praxis":["Erkennen, ob es wirklich um die Sache geht oder um Anerkennung (Beziehungsebene) – das bestimmt die Lösung.","Früh und sachlich eingreifen, bevor aus einem Konflikt Aggression wird."]},"visual":null},{"h":"Konfliktlösung","b":"Prävention, Kompromiss, Austragung, Verschiebung","detail":{"titel":"Konfliktlösung","kat":"Konflikte · Lösung","katCls":"mensch","merksatz":"Konflikte lassen sich auf mehreren Wegen handhaben: Prävention (vorbeugen), Kompromiss (beide geben nach), Austragung (offen klären) und Verschiebung (vertagen). Unterstützend wirken Diplomatie und geduldiges Zuhören.","funktion":["Prävention: Konflikte von vornherein vermeiden – neutral bleiben, Gemeinsamkeiten betonen, zuhören.","Kompromiss: eine Lösung finden, mit der beide Seiten leben können (beide geben etwas nach).","Austragung: den Konflikt offen und sachlich klären, statt ihn schwelen zu lassen.","Verschiebung: vertagen, wenn eine sofortige Lösung nicht möglich ist – bewusst, nicht als Verdrängen."],"schutzziel":"Konflikte deeskalierend und fair lösen, statt sie durch Rechthaberei zu verschärfen.","kennwerte":[{"l":"Prävention","v":"vorbeugen"},{"l":"Kompromiss","v":"beide geben nach"},{"l":"Austragung","v":"offen klären"},{"l":"Unterstützt durch","v":"Diplomatie + Zuhören"}],"begriffe":["Kompromiss = Einigung, bei der beide Seiten nachgeben und so beide gewinnen.","Deeskalation = das schrittweise Abbauen von Spannung durch Kommunikation."],"abgrenzung":["Konflikte vermeidet man durch Neutralität und Zuhören – NICHT, indem man jemanden vor Unbeteiligten zur Rede stellt oder Argumente ins Lächerliche zieht.","Konfliktlösung wird gefördert durch Diplomatie und geduldiges Zuhören – NICHT durch Besserwisserei oder Geschwätzigkeit."],"praxis":["Bei Streit zwischen zwei Gästen: beide getrennt anhören, Gemeinsamkeiten suchen und auf einen Kompromiss hinwirken.","Lässt sich etwas nicht sofort lösen, sachlich vertagen statt es eskalieren zu lassen."]},"visual":null}],"quiz":[{"q":"Was kann Frustration auslösen?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Gelassenheit","c":false},{"t":"Aggression","c":true},{"t":"Depression","c":true},{"t":"Zufriedenheit","c":false}]},{"q":"Was ist Frustrationstoleranz?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Fähigkeit, Frustrationen gezielt in Aggressionen und normabweichendes Verhalten umzuwandeln","c":false},{"t":"Die Fähigkeit, über einen längeren Zeitraum mit Enttäuschungen umzugehen, ohne die Fassung zu verlieren","c":true},{"t":"Die Fähigkeit, Gleichgültigkeit beim Gegenüber auszulösen und dessen Streben nach Macht zu unterdrücken","c":false},{"t":"Die Fähigkeit, soziale Ungerechtigkeiten durch Streben nach Macht und Geltung auszugleichen","c":false}]},{"q":"Welche Aussagen beschreiben, was Aggression ist?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Ein Verhalten, das immer die Folge von Frustrationen ist und sich z. B. gegen Personen, Sachen oder Tiere richtet","c":false},{"t":"Ein Verhalten, das sich stets unbeabsichtigt entlädt, z. B. gegen Personen, Sachen oder Tiere","c":false},{"t":"Ein Verhalten, das darauf gerichtet ist, z. B. Personen, Sachen oder Tiere zu beschädigen, zu verletzen oder zu zerstören","c":true},{"t":"Aggression ist verbal oder brachial, z. B. in Form einer Beleidigung oder feindseliger Gewalt","c":true}]},{"q":"Was trifft häufig auf betrunkene Personen zu?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Gefühle überlagern das klare Denken","c":true},{"t":"Die Hemmschwelle steigt","c":false},{"t":"Der Verstand kontrolliert die Gefühle","c":false},{"t":"Die Aggressionsschwelle sinkt","c":true}]},{"q":"Wie können Konflikte vermieden werden?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Im Umgang mit anderen neutral sein und Gemeinsamkeiten deutlich machen","c":true},{"t":"Eine Person, die sich falsch verhält, vor Unbeteiligten zur Rede stellen","c":false},{"t":"Im Gespräch dem anderen zuhören und die Angelegenheit sachlich erörtern","c":true},{"t":"Argumenten des Gesprächspartners sofort widersprechen und diese ins Lächerliche ziehen","c":false}]},{"q":"Was kann die Lösung von Konflikten unterstützen?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Diplomatisches Geschick","c":true},{"t":"Besserwisserei","c":false},{"t":"Ausdauernde Geschwätzigkeit","c":false},{"t":"Geduldiges Zuhören","c":true}]},{"q":"Was bedeutet Frustration bzw. Frustrationstoleranz?","a":"Frustration ist das nicht erreichen eines angestrebten Zieles; z.B. Nichtbestehen der mündlichen IHK Prüfung. Jeder Mensch hat eine andere Ebene wie er Frustration aushalten oder verarbeiten kann","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Aggression bzw. eine Aggressionsverschiebung?","a":"Ist ein Verhalten, das darauf abzielt, andere Menschen und deren Interessen zu verletzen oder zu zerstören, entweder körperlich oder verbal Aggressionsverschiebung - gegen andere Dinge oder Menschen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nenne die Formen der Aggression und wie geht ein Sicherheitsmitarbeiter richtig","a":"damit um? Innere und äußere Aggressionen - Ruhe bewahren - nicht provozieren lassen - die Eigensicherung beachten","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie unter einer Aggressionsverschiebung ?","a":"Ist die Verschiebung einer Aggression vom Auslöser auf eine andere Person, Sache oder Tier","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist ein Konflikt/Konfliktarten und wie lässt sich dieser entschärfen?","a":"- Ein Konflikt entsteht aus zwei gegenseitigen Meinungen die aufeinanderprallen - Konfliktprävention, vorbeugende Maßnahmen treffen - Konfliktaustragung, Konflikt auf eine positive Ebene führen - Kompromiss, einen gemeinsamen Nenner finden Man kann auch einen Konflikt mit sich selber haben; z.B. Stehe ich heute auf oder bleibe ich liegen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Deeskalation?","a":"Deeskalation ist das Entspannen der unterschiedlichen Konflikte, indem man mit Kommunikationsmitteln, z.B. Gesten (Nonverbal) und beruhigenden Worten (rhetorische Deeskalation/Verbal) auf seinen Gegenüber eingeht.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet „Interkulturelle Kompetenz“ ? (ist die Fähigkeit mit Menschen aus","a":"anderen Kulturkreisen umzugehen und angemessen zu kommunizieren) Hier kann es schnell zu gravierenden Missverständnissen und Konflikten kommen (unterschiedliche Bedeutung/Interpretation von Körpersprache und Worten). - kulturelle und religiöse Unterschiede respektieren - Sprachtempo und Lautstärke anpassen - Wenn nötig, Sprachmittler einschalten","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wichtige Schutzabstände (Distanzzonen)?","a":"- Intimdistanz, ca. 45cm (Frau, Kind, Familie) - Erweiterter Nahbereich, ca. 45 - 120 cm (Freunde, Bekannte) - Gesellschaftlicher Bereich, 120 - 360 cm (Kollegen, Bekannte) - Öffentlicher Bereich, ab 360 cm (Unbekannte) Die Distanz zum Gesprächspartner spielt in der Kommunikation eine nicht unbedeutende Rolle. Insbesondere bei Konflikten kann eine Verletzung der Distanzzonen (Eindringen in unser Territorium) eskalierend wirken.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie unter der sogenannten „interkulturellen Kompetenz“ ?","a":"Ist die Fähigkeit auf unterschiedliche kulturelle Kreise einzugehen und mit diesen möglichst konfliktfrei umzugehen Kulturelle Unterschiede:> Sprache, Mimik, Gestik, Glaube, Kleidung, Esskultur, Ehrkultur (Geschlechter, Alter, sozialer Stand) Die interkulturelle Kompetenz muss die Grundrechte stets berücksichtigen.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wie entsteht eine Eskalation (Eskalationstreppe)?","a":"Zwei Standpunkte prallen aufeinander und schaukeln sich bis zur Eskalation spiral- förmig hoch. An der obersten Stufe läge dann die Gewalt/Eskalation","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[{"scenario":"Ein Gast wird am Einlass abgewiesen, weil er sichtbar zu betrunken ist. Er ballt die Fäuste, wird laut und beschimpft dich – obwohl du ruhig und sachlich geblieben bist.","frage":"Was läuft hier psychologisch ab, und wie reagierst du richtig?","loesung":"Die Zurückweisung blockiert sein Ziel → Frustration → Aggression, die sich gegen dich als Ersatzobjekt richtet (Aggressionsverschiebung). Richtig: Sicherheitsabstand wahren, deeskalierend sprechen, nicht persönlich nehmen, keine Gegenaggression. Ziel ist Abbau der Spannung, nicht „Rechthaben“."},{"scenario":"Zwei Stammgäste geraten an der Bar über einen Sitzplatz aneinander, die Stimmung kippt – beide wollen recht haben.","frage":"Wie gehst du als Wachperson an die Konfliktlösung heran?","loesung":"Es ist ein Interessenkonflikt um denselben Platz. Statt Partei zu ergreifen: ruhig dazwischengehen, beide getrennt anhören, Gemeinsamkeiten betonen und auf einen Kompromiss hinwirken. Denkschlüssel: Konflikte löst man durch neutrales Zuhören, Diplomatie und Deeskalation – nicht durch Lautwerden, Rechthaberei oder das Einbeziehen Außenstehender."}]},{"n":8,"title":"Gesprächsführung","subtitle":"4 Konzepte · 3 Prüfungsfragen","cards":[{"h":"Aktives Zuhören","b":"Aufnahmebereite Zuwendung; Blickkontakt, Nicken, klärende Fragen, bestätigendes Wiederholen","detail":{"titel":"Aktives Zuhören","kat":"Gesprächsführung · Aktives Zuhören","katCls":"mensch","merksatz":"Aktives Zuhören ist die aufnahmebereite, zugewandte Form des Zuhörens: durch Blickkontakt, Nicken, klärende Fragen und bestätigendes Wiederholen signalisiert man Wertschätzung und baut Vertrauen auf.","funktion":["Zuwendung zeigen: Blickkontakt, offene Haltung und Nicken – ganz beim Gegenüber sein.","Rückmelden: das Gehörte in eigenen Worten zusammenfassen (paraphrasieren) und mit klärenden Fragen nachhaken.","Zweck: Wertschätzung signalisieren und Vertrauen aufbauen – NICHT manipulieren oder kontrollieren.","Wirkung: nimmt Druck aus Konflikten – der andere fühlt sich verstanden (Beziehungsebene)."],"schutzziel":"Vertrauen aufbauen, deeskalieren und den Gesprächspartner wirklich verstehen.","kennwerte":[{"l":"Mittel","v":"Blickkontakt · Nicken · Nachfragen"},{"l":"Technik","v":"bestätigendes Wiederholen"},{"l":"Zweck","v":"Wertschätzung + Vertrauen"},{"l":"Nicht","v":"Manipulation / Kontrolle"}],"begriffe":["Aktives Zuhören = zugewandtes Zuhören mit sichtbarer Rückmeldung an den Sprecher.","Paraphrasieren = das Gehörte mit eigenen Worten wiedergeben, um Verständnis zu zeigen und zu prüfen."],"abgrenzung":["Aktives Zuhören dient NICHT der Manipulation oder Kontrolle, sondern Wertschätzung und Vertrauen.","Zuhören ≠ nur schweigen: aktiv heißt zuwenden, nachfragen und zurückmelden."],"praxis":["‚Verstehe ich Sie richtig, dass …?' zeigt Zuwendung und klärt zugleich.","Beim Wütenden erst zuhören und zusammenfassen, dann zur Sache kommen."]},"visual":null},{"h":"Gesprächsphasen","b":"Vorbereitung, Eröffnung, Hauptteil, Ende, Nachbereitung","detail":{"titel":"Gesprächsphasen","kat":"Gesprächsführung · Phasen","katCls":"mensch","merksatz":"Ein Gespräch verläuft in Phasen: Vorbereitung, Eröffnung, Hauptteil, Abschluss und Nachbereitung. Wer die Phasen kennt, führt zielgerichtet statt planlos.","funktion":["Vorbereitung: Ziel, Anlass und Rahmen klären – wer, was, wo und wozu.","Eröffnung: Kontakt herstellen, freundlich begrüßen, eine angenehme Atmosphäre schaffen (Beziehungsebene).","Hauptteil: das Anliegen klären – zuhören, Fragen stellen, zur Sache kommen.","Abschluss und Nachbereitung: Ergebnisse kurz zusammenfassen, Vereinbarungen festhalten und danach reflektieren."],"schutzziel":"Gespräche zielgerichtet und ergebnisorientiert führen, statt sie im Streit oder Leerlauf enden zu lassen.","kennwerte":[{"l":"5 Phasen","v":"Vorbereitung → Eröffnung → Hauptteil → Abschluss → Nachbereitung"},{"l":"Eröffnung","v":"Kontakt + Beziehung"},{"l":"Hauptteil","v":"Anliegen + Sache"},{"l":"Abschluss","v":"zusammenfassen"}],"begriffe":["Gesprächsphasen = der typische Ablauf eines Gesprächs in aufeinanderfolgenden Abschnitten.","Nachbereitung = das Reflektieren und Festhalten von Ergebnissen nach dem Gespräch."],"abgrenzung":["Eröffnung ≠ sofort zur Sache: erst Kontakt und Beziehung, dann der Inhalt.","Abschluss ≠ einfach abbrechen: am Ende die Ergebnisse kurz zusammenfassen."],"praxis":["Ein Mitarbeitergespräch unter vier Augen führen, vorher einladen, am Ende die Ergebnisse zusammenfassen.","Eine freundliche Eröffnung entscheidet oft schon, ob der Hauptteil sachlich bleibt."]},"visual":null},{"h":"Fragearten – offene Fragen","b":"Meinungs-, Denkanstoß-, Wissens-, Reiz-, Problem-, Auswirkungs-, Nutzen-, Entscheidungsfrage","detail":{"titel":"Offene Fragen","kat":"Gesprächsführung · Offene Fragen","katCls":"mensch","merksatz":"Offene Fragen lassen sich nicht mit Ja oder Nein beantworten – sie öffnen das Gespräch, bringen Informationen und regen zum Nachdenken an. Beispiele sind Meinungs-, Wissens-, Problem- und Entscheidungsfragen.","funktion":["Wesen: beginnen oft mit einem W (Wer, Was, Wie, Warum) und verlangen eine ausführliche Antwort.","Nutzen: bringen viele Informationen, zeigen Interesse und öffnen das Gespräch.","Arten: Meinungs-, Denkanstoß-, Wissens-, Reiz-, Problem-, Auswirkungs-, Nutzen- und Entscheidungsfrage.","Einsatz: am Anfang und im Hauptteil, um zu verstehen und Informationen zu sammeln."],"schutzziel":"Im Gespräch Informationen gewinnen und das Gegenüber öffnen, statt es zu verschließen.","kennwerte":[{"l":"Antwort","v":"ausführlich, nicht Ja/Nein"},{"l":"Beginn","v":"oft W-Frage"},{"l":"Nutzen","v":"Informationen + Öffnung"},{"l":"Beispiele","v":"Meinungs- · Wissens- · Problemfrage"}],"begriffe":["Offene Frage = eine Frage, die nicht mit einem einfachen Ja oder Nein beantwortet werden kann.","Reizfrage = eine bewusst provozierende offene Frage, die eine Reaktion herauslocken soll."],"abgrenzung":["Offene Frage ≠ geschlossene Frage: offen verlangt eine ausführliche Antwort, geschlossen nur ein kurzes Ja/Nein.","Eine offene Frage ist ergebnisoffen – sie legt die Antwort NICHT nahe (anders als die Suggestivfrage)."],"praxis":["‚Was ist genau passiert?' bringt mehr als ‚War es Person X?'","Zu Beginn einer Befragung mit offenen Fragen arbeiten, um ein vollständiges Bild zu bekommen."]},"visual":null},{"h":"Fragearten – geschlossene Fragen","b":"Suggestiv-, Ketten-, Alternativ-, Gegenfrage, rhetorische Frage","detail":{"titel":"Geschlossene Fragen","kat":"Gesprächsführung · Geschlossene Fragen","katCls":"mensch","merksatz":"Geschlossene Fragen lassen nur kurze Antworten zu (oft Ja oder Nein). Sie eignen sich für klare Fakten und für den Gesprächsabschluss. Vorsicht bei der Suggestivfrage – sie legt die Antwort bereits nahe.","funktion":["Wesen: kurze, eindeutige Antworten (Ja/Nein, eine Zahl); sie schließen das Gespräch eher.","Nutzen: Fakten klären, Entscheidungen herbeiführen und zum Abschluss kommen.","Arten: Suggestiv-, Ketten-, Alternativ-, Gegenfrage und rhetorische Frage.","Suggestivfrage: legt die gewünschte Antwort nahe (z. B. ‚Sie machen doch sicher Überstunden?') – im neutralen Gespräch unfair."],"schutzziel":"Gezielt Fakten klären und Gespräche steuern – und manipulative Suggestivfragen erkennen und vermeiden.","kennwerte":[{"l":"Antwort","v":"kurz · oft Ja/Nein"},{"l":"Nutzen","v":"Fakten + Abschluss"},{"l":"Arten","v":"Suggestiv · Alternativ · Ketten · rhetorisch"},{"l":"Falle","v":"Suggestivfrage"}],"begriffe":["Geschlossene Frage = eine Frage, die nur eine kurze, oft mit Ja oder Nein gegebene Antwort zulässt.","Suggestivfrage = eine Frage, die die erwünschte Antwort bereits in sich trägt und so das Gegenüber lenkt."],"abgrenzung":["Geschlossene Frage ≠ offene Frage: kurze Antwort statt ausführlicher.","Suggestivfrage ≠ neutrale Frage: Beispiel ‚Es macht Ihnen doch sicher nichts aus, Überstunden zu machen?' legt die Antwort nahe."],"praxis":["‚Haben Sie die Tür abgeschlossen?' klärt einen Fakt eindeutig.","Bei einer neutralen Befragung Suggestivfragen vermeiden und sachlich-klar formulieren."]},"visual":null}],"quiz":[{"q":"Wozu dient das sogenannte aktive Zuhören?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Es soll ermöglichen, den Gesprächspartner zu manipulieren","c":false},{"t":"Es soll dem Gesprächspartner Wertschätzung signalisieren","c":true},{"t":"Es soll Vertrauen zum Gesprächspartner aufbauen","c":true},{"t":"Es soll die Kontrolle über den Gesprächspartner ermöglichen","c":false}]},{"q":"Wann verläuft ein Gespräch erfolgreich?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wenn dem Gesprächspartner Respekt entgegengebracht und ihm aufmerksam zugehört wird","c":true},{"t":"Wenn dem Gesprächspartner immer wieder Vorhaltungen gemacht werden","c":false},{"t":"Wenn durch dominantes Auftreten signalisiert wird, dass er sich in der schwächeren Position befindet","c":false},{"t":"Wenn versucht wird, die Lage des Gesprächspartners zu verstehen, um seine Meinung nachvollziehen zu können","c":true}]},{"q":"Welche Frage ist eine Suggestivfrage?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Was für Erfahrungen haben Sie mit der Tabellenkalkulation?","c":false},{"t":"Würden Sie mit Ihrer großen Erfahrung neue Kollegen in ihre Arbeitsaufgaben einweisen?","c":false},{"t":"Möchten Sie lieber in der Früh- oder in der Nachtschicht arbeiten?","c":false},{"t":"Es macht Ihnen doch sicherlich nichts aus, Überstunden zu machen?","c":true}]},{"q":"Was sollten Wachpersonen während einer Befragung beachten?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Mit Nachdruck Antworten einfordern und mit der Haltung eines ‚Siegers' auftreten","c":false},{"t":"Zum Schein Versprechungen machen und dadurch eine Atmosphäre des Vertrauens schaffen","c":false},{"t":"Neutralität im Gespräch wahren und ohne Voreingenommenheit dem Befragten gegenübertreten","c":true},{"t":"Sachliche, präzise und klar formulierte Fragen stellen","c":true}]},{"q":"Was bedeutet aktives Zuhören?","a":"Indem man sein Gegenüber eine offene Körpersprache/Mimik vermittelt, hört aufmerksam zu, lässt sein Gegenüber ausreden, stellt selber Gegenfragen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Fragearten gibt es?","a":"offene Fragen> geben dem Gefragten keine Grenzen bei der Antwort (W - Fragen) geschlossene Fragen> lassen nur „Ja“ oder „Nein“ als Antwort zu Suggestivfragen> zielen beim Gefragten auf eine bestimmte Antwort ab rhetorische Fragen> sie erwartet keine Antwort","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was bedeutet Deeskalation?","a":"Deeskalation ist das Entspannen der unterschiedlichen Konflikte, indem man mit Kommunikationsmitteln, z.B. Gesten (Nonverbal) und beruhigenden Worten (rhetorische Deeskalation/Verbal) auf seinen Gegenüber eingeht.","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[{"scenario":"Ein aufgebrachter Mieter kommt zur Pforte. Du fällst sofort mit ‚Was wollen Sie?' und der Sachfrage ins Haus, ohne ihn ankommen zu lassen. Das Gespräch eskaliert sofort.","frage":"Welche Gesprächsphase hast du übersprungen – und warum ist sie wichtig?","loesung":"Du hast die Eröffnungsphase übersprungen, die erst die Beziehung herstellt (begrüßen, ankommen lassen, Anliegen aufnehmen). Ein Gespräch hat Phasen: Vorbereitung, Eröffnung, Hauptteil, Ende, Nachbereitung. Denkschlüssel: erst Kontakt und Beziehung, dann zur Sache – wer die Eröffnung überspringt, verliert das Gegenüber sofort."},{"scenario":"Bei einer Befragung nach einem Vorfall fragst du: ‚Sie haben den Mann doch sicher schlagen sehen, oder?' Der Zeuge stimmt zu, obwohl er sich gar nicht sicher ist.","frage":"Welchen Fragetyp hast du benutzt und warum ist er hier problematisch?","loesung":"Das ist eine Suggestivfrage – sie legt die Antwort schon in den Mund und verfälscht die Aussage. Für neutrale Befragungen eignen sich offene Fragen (‚Was haben Sie gesehen?'). Denkschlüssel: sachlich und ohne Vorgabe fragen, offene statt suggestiver Fragen – sonst sind die Antworten wertlos."}]},{"n":9,"title":"Distanz, Deeskalation & Personengruppen","subtitle":"5 Konzepte · 8 Prüfungsfragen","cards":[{"h":"Distanzzonen (Edward Hall)","b":"Intim-, persönliche, soziale, öffentliche Zone","detail":{"titel":"Distanzzonen nach Edward Hall","kat":"Distanz · Distanzzonen","katCls":"mensch","merksatz":"Der Anthropologe Edward Hall beschrieb vier Distanzzonen, die jeder Mensch unbewusst um sich hat: Intim-, persönliche, soziale und öffentliche Distanz. Wer ungefragt in eine zu nahe Zone eindringt, löst Stress und Abwehr aus.","funktion":["Intimdistanz (bis ca. 0,5 m): nur für sehr vertraute Personen – Eindringen wird als Bedrohung erlebt.","Persönliche Distanz (ca. 0,5–1,5 m): für Freunde und Bekannte, vertraute Gespräche.","Soziale Distanz (ca. 1,5–4 m): für Fremde, geschäftliche und dienstliche Kontakte – hier arbeitet die Wachperson.","Öffentliche Distanz (ab ca. 4 m): gegenüber größeren Gruppen, beim Sprechen vor Publikum."],"schutzziel":"Den Wohlfühlabstand anderer respektieren, dadurch Stress vermeiden – und die eigene Sicherheit durch genug Abstand wahren.","kennwerte":[{"l":"Intim","v":"bis ca. 0,5 m"},{"l":"Persönlich","v":"ca. 0,5–1,5 m"},{"l":"Sozial","v":"ca. 1,5–4 m"},{"l":"Öffentlich","v":"ab ca. 4 m"}],"begriffe":["Distanzzone = der unbewusst beanspruchte Raum um eine Person, abhängig von der Beziehung zum Gegenüber.","Proxemik = die Lehre vom räumlichen Verhalten des Menschen (geht auf Edward Hall zurück)."],"abgrenzung":["Die Grenzen sind kulturabhängig – in manchen Kulturen steht man näher, in anderen weiter; die Zentimeterwerte sind nur Richtwerte.","Zu große Distanz wirkt abweisend, zu kleine bedrohlich – im Dienst ist meist die soziale Zone richtig."],"praxis":["Ungefragtes Eindringen in die Intimdistanz (dicht herantreten) eskaliert fast jede Situation.","Wer respektvollen Abstand hält, signalisiert Sicherheit und nimmt dem Gegenüber das Bedrohungsgefühl."]},"visual":null},{"h":"Sicherheitsabstand","b":"Mind. 1,50 m; „so nah wie nötig, so weit wie möglich“; Eigensicherung","detail":{"titel":"Sicherheitsabstand","kat":"Distanz · Sicherheitsabstand","katCls":"mensch","merksatz":"Im Dienst gilt ein Mindestabstand von etwa 1,50 m – ‚so nah wie nötig, so weit wie möglich'. Der Abstand schützt vor Überraschungsangriffen (Eigensicherung) und wirkt zugleich deeskalierend.","funktion":["Richtwert: mindestens ca. 1,50 m (etwa eine Armlänge plus Reserve) zu unbekannten oder aufgebrachten Personen.","Eigensicherung: genug Abstand verschafft Reaktionszeit bei plötzlichen Angriffen (Schlag, Tritt, Waffe).","Deeskalation: Abstand nimmt Druck aus der Situation – aufgedrängte Nähe wird als Bedrohung erlebt.","Fluchtweg: immer so stehen, dass ein Rückzug möglich ist; sich nicht in die Enge treiben lassen."],"schutzziel":"Die eigene körperliche Unversehrtheit sichern und gleichzeitig die Situation beruhigen.","kennwerte":[{"l":"Richtwert","v":"mind. ca. 1,50 m"},{"l":"Merksatz","v":"so nah wie nötig, so weit wie möglich"},{"l":"Zweck 1","v":"Eigensicherung / Reaktionszeit"},{"l":"Zweck 2","v":"Deeskalation"}],"begriffe":["Sicherheitsabstand = der Mindestabstand, der Reaktionszeit verschafft und Angriffe erschwert.","Eigensicherung = alle Maßnahmen, mit denen sich die Wachperson selbst vor Schaden schützt."],"abgrenzung":["Sicherheitsabstand ist kein ‚Wegrennen': Man bleibt handlungsfähig und präsent, hält aber Distanz.","Bei akuter Bedrohung kann der nötige Abstand größer sein als 1,50 m – der Wert ist Mindestmaß, nicht Obergrenze."],"praxis":["Immer leicht seitlich und außerhalb der Reichweite stehen – nie frontal und dicht vor einer aggressiven Person.","Hände sichtbar und frei halten, Rückzugsweg im Blick – das ist gelebte Eigensicherung."]},"visual":null},{"h":"Deeskalation","b":"Stufenweiser Abbau von Konflikten mit Kommunikation; Deeskalationsregeln","detail":{"titel":"Deeskalation","kat":"Distanz · Deeskalation","katCls":"mensch","merksatz":"Deeskalation ist der stufenweise Abbau eines Konflikts mit den Mitteln der Kommunikation. Ziel ist, gewaltauslösende Faktoren zu vermindern und die Sichtweise auf das Geschehen zu verändern – nicht zu ‚gewinnen'.","funktion":["Ruhe bewahren: ruhig, sachlich, selbstbeherrscht bleiben; Provokationen und Beleidigungen nicht persönlich nehmen.","Verständnis zeigen: aktiv zuhören, die Person ernst nehmen und zur Ruhe kommen lassen.","Abstand und offene Körpersprache: Sicherheitsabstand halten, keine Drohgebärden, ruhiger Blickkontakt.","Gewaltauslösende Faktoren vermindern: Zuschauer reduzieren, Gesicht wahren lassen, keine Enge erzeugen."],"schutzziel":"Konflikte ohne Gewalt lösen und die eigene wie die fremde Sicherheit wahren.","kennwerte":[{"l":"Definition","v":"stufenweiser Abbau per Kommunikation"},{"l":"Haltung","v":"ruhig · sachlich · beherrscht"},{"l":"Hebel","v":"gewaltauslösende Faktoren vermindern"},{"l":"Tabu","v":"laut werden, drohen, bloßstellen"}],"begriffe":["Deeskalation = Maßnahmen, die eine Konfliktsituation entschärfen und eine Eskalation verhindern.","Gewaltauslösende Faktoren = Umstände wie Enge, Publikum, Gesichtsverlust oder Provokation, die Aggression fördern."],"abgrenzung":["Deeskalation gelingt NICHT durch lautes Auftreten, autoritäres Beenden oder das Einbeziehen Außenstehender.","Sie wird gefördert durch Verminderung gewaltauslösender Faktoren und eine veränderte Sichtweise auf aggressives Verhalten – nicht durch ‚Durchsetzung des Hausrechts mit Gewalt'."],"praxis":["Einen wütenden Gast zur Ruhe kommen lassen und Verständnis zeigen wirkt stärker als jede Drohung.","Beleidigungen nicht persönlich nehmen und Abstand halten – so bleibt man selbst ruhig und steuerungsfähig."]},"visual":null},{"h":"Personengruppen","b":"Männer/Frauen, Senioren, Jugendliche, Flüchtlinge, Betrunkene, Beeinträchtigte, Querulanten – Merkmale & Umgang","detail":{"titel":"Umgang mit Personengruppen","kat":"Distanz · Personengruppen","katCls":"mensch","merksatz":"Verschiedene Personengruppen haben typische Merkmale, auf die man sich einstellen muss – ohne in pauschale Vorurteile zu verfallen. Grundhaltung immer: Respekt, Ruhe und Gleichbehandlung.","funktion":["Jugendliche: geringere soziale Unter- und Einordnungsbereitschaft, Vorliebe zur Gruppenbildung – ruhig, klar, nicht vor der Gruppe bloßstellen.","Betrunkene: Gefühle überlagern das Denken, Hemm- und Aggressionsschwelle sinken – viel Abstand, einfache klare Ansagen.","Senioren und Menschen mit Beeinträchtigung: mit Respekt und Geduld begegnen, Hilfe anbieten, nicht bevormunden.","Geflüchtete und andere Kulturen: Fragen stellen und aktiv zuhören, eigene Werte transparent machen ohne zu belehren."],"schutzziel":"Jeder Gruppe angemessen und sicher begegnen und Konflikte aus Fehleinschätzung vermeiden.","kennwerte":[{"l":"Jugendliche","v":"Gruppenbildung · wenig Einordnung"},{"l":"Betrunkene","v":"Hemm-/Aggressionsschwelle sinkt"},{"l":"Beeinträchtigte","v":"Respekt · Geduld · Hilfe"},{"l":"Grundregel","v":"Respekt + Gleichbehandlung"}],"begriffe":["Schutzbedürftige Person = Person, die wegen Alter, Beeinträchtigung oder Lage besonderen Schutz und Rücksicht braucht.","Vorurteil = vorgefertigtes Urteil über eine Gruppe, das den fairen Umgang stört."],"abgrenzung":["Typische Merkmale sind eine Orientierung, kein Freibrief für Pauschalurteile – jede Person bleibt ein Einzelfall.","Einer Person die Wahrnehmung oder Würde abzusprechen ist falsch – Respekt und Toleranz sind Pflicht, gerade bei seelischer Beeinträchtigung."],"praxis":["Bei betrunkenen Personen besonders viel Abstand halten und mit Überraschungen rechnen.","Jugendliche nicht vor der Gruppe vorführen – das provoziert Imponierverhalten und Eskalation."]},"visual":null},{"h":"Querulanten-Techniken","b":"Schallplatte mit Sprung; Vernebelungstechnik","detail":{"titel":"Querulanten und Gesprächstechniken","kat":"Distanz · Querulanten","katCls":"mensch","merksatz":"Querulanten sind streit- und beschwerdefreudige Personen, die hartnäckig auf ihrem Standpunkt beharren. Zwei bewährte Techniken: die ‚Schallplatte mit Sprung' und die ‚Vernebelungstechnik'.","funktion":["Querulant: beharrt unbeirrbar, sucht den Streit, lässt sich auf Sachargumente kaum ein.","Schallplatte mit Sprung: die eigene, klare Kernaussage ruhig und freundlich immer wieder wiederholen, ohne auf Nebenschauplätze einzugehen.","Vernebelungstechnik: einem Vorwurf teilweise zustimmen (‚Da mögen Sie recht haben'), ohne die eigene Linie aufzugeben – das nimmt dem Angriff den Wind aus den Segeln.","Grundhaltung: ruhig und freundlich-bestimmt, sich nicht provozieren lassen, das Gesicht wahren lassen."],"schutzziel":"Endlosdiskussionen und Eskalation vermeiden und freundlich-bestimmt bei der Sache bleiben.","kennwerte":[{"l":"Querulant","v":"beharrlich · streitfreudig"},{"l":"Technik 1","v":"Schallplatte mit Sprung (wiederholen)"},{"l":"Technik 2","v":"Vernebelung (teils zustimmen)"},{"l":"Haltung","v":"ruhig, freundlich-bestimmt"}],"begriffe":["Schallplatte mit Sprung = das ruhige, beharrliche Wiederholen der eigenen Kernbotschaft wie eine hängende Schallplatte.","Vernebelungstechnik = einem Teil der Kritik scheinbar zustimmen, um sie zu entschärfen, ohne in der Sache nachzugeben."],"abgrenzung":["Beide Techniken sind kein ‚Recht geben': Man bleibt in der Sache fest und nur im Ton ruhig.","Mit einem Querulanten ausführlich zu diskutieren oder laut zu werden verstärkt den Konflikt – genau das ist der Fehler."],"praxis":["‚Ich verstehe Ihren Ärger – die Kontrolle ist trotzdem nötig.' ruhig wiederholt bringt mehr als jedes Gegenargument.","Bei einem sturen Vorwurf teilweise zustimmen und ruhig bei der eigenen Linie bleiben."]},"visual":null}],"quiz":[{"q":"Wie lässt sich ein Konflikt am leichtesten deeskalieren?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Laut werden und sich so Gehör und Respekt verschaffen","c":false},{"t":"Den Konflikt autoritär beenden","c":false},{"t":"Ruhig bleiben und Provokationen überhören","c":true},{"t":"Außenstehende einbeziehen","c":false}]},{"q":"Was ist im Umgang mit einer wütenden Person hilfreich, um deeskalierend zu wirken?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Situation nur auf der Beziehungsebene zu Ende bringen; die Sachebene ist nicht hilfreich","c":false},{"t":"Die andere Person zur Ruhe kommen lassen und Verständnis zeigen","c":true},{"t":"Selbstbeherrscht sein und mit Emotionen offen umgehen","c":true},{"t":"Wenn die Person beleidigend wird, laut werden und mit Folgen drohen","c":false}]},{"q":"Wachpersonen sollen auch in schwierigen Situationen Ruhe bewahren. Was kann dazu beitragen?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Bei Aggression mit Gegenaggression reagieren","c":false},{"t":"Beleidigungen im Dienst nicht persönlich nehmen","c":true},{"t":"Den eigenen Standpunkt stets lautstark vertreten","c":false},{"t":"Ausreichend Abstand zum Gegenüber halten","c":true}]},{"q":"Wodurch wird Deeskalation gefördert?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Durch die Verminderung gewaltauslösender Faktoren","c":true},{"t":"Durch die konsequente Durchsetzung des Hausrechts","c":false},{"t":"Durch das Eindämmen des freien Willens des Gegenübers","c":false},{"t":"Durch die Veränderung der Sichtweise auf aggressives Verhalten","c":true}]},{"q":"Was ist bei Jugendlichen oft zu beobachten?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sie gehen Diskussionen gerne aus dem Weg","c":false},{"t":"Sie wollen wie Erwachsene behandelt werden und kopieren deshalb deren Verhalten","c":false},{"t":"Sie verfügen über eine geringere soziale Unter- und Einordnungsbereitschaft als Erwachsene","c":true},{"t":"Sie zeigen eine deutliche Vorliebe zur Gruppenbildung","c":true}]},{"q":"Welche Maßnahmen der Eigensicherung sind geeignet, um sich vor Überraschungsmomenten zu schützen?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sich mit Verteidigungsmitteln wie Hieb- oder Schusswaffen ausrüsten","c":false},{"t":"Sich körperlich fit halten","c":false},{"t":"Immer mit unvorhersehbaren Ereignissen rechnen","c":true},{"t":"Selbst in einer vertrauten Umgebung auf Veränderungen achten","c":true}]},{"q":"Wichtige Schutzabstände (Distanzzonen)?","a":"- Intimdistanz, ca. 45cm (Frau, Kind, Familie) - Erweiterter Nahbereich, ca. 45 - 120 cm (Freunde, Bekannte) - Gesellschaftlicher Bereich, 120 - 360 cm (Kollegen, Bekannte) - Öffentlicher Bereich, ab 360 cm (Unbekannte) Die Distanz zum Gesprächspartner spielt in der Kommunikation eine nicht unbedeutende Rolle. Insbesondere bei Konflikten kann eine Verletzung der Distanzzonen (Eindringen in unser Territorium) eskalierend wirken.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Deeskalation?","a":"Deeskalation ist das Entspannen der unterschiedlichen Konflikte, indem man mit Kommunikationsmitteln, z.B. Gesten (Nonverbal) und beruhigenden Worten (rhetorische Deeskalation/Verbal) auf seinen Gegenüber eingeht.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nenne die Formen der Aggression und wie geht ein Sicherheitsmitarbeiter richtig","a":"damit um? Innere und äußere Aggressionen - Ruhe bewahren - nicht provozieren lassen - die Eigensicherung beachten","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was muss man bei Personenkontrollen beachten?","a":"- Man darf die Person abtasten aber nicht durchsuchen - Durchsuchen von Taschen ist nicht erlaubt, nur reinschauen - Eigensicherung durch Arbeitskollegen veranlassen - Umfeld ständig beobachten - Ein gesundes Misstrauen - Einem Verdächtigen niemals den Rücken zuwenden","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Verhaltensempfehlung bei Jugendlichen?","a":"Respektvoll behandeln, ernst nehmen, Grenzen zeigen, als Vorbild auftreten.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Verhaltensempfehlung bei Betrunkenen oder Drogensüchtigen?","a":"Respektvoll behandeln, ernst nehmen, auf Sachebene kommunizieren, Eigensicherung","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine L-Stellung und was bedeutet eigentlich Eigensicherung?","a":"Die L-Stellung bietet eine doppelte Eigensicherung wo der Arbeitskollege Schnell von der Seite eingreifen kann, bzw. ein anderes Umfeld beobachten kann.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie unter dem „ersten Eindruck“?","a":"ist das erste Bild, was ich mir über einen anderen Menschen mache entsteht in den ersten Sekunden (~ 5-20 Sekunden) ergibt sich aus dem Verhalten des Gegenübers (Aussehen, Auftreten -Mimik/Gestik-, Kleidung) ergibt sich aus eigenen Erfahrungswerten (Menschenkenntnis) und Vorurteilen Ist für Wachpersonen relevant in Bezug auf das weitere Verfahren (Kommunikation, Eigensicherung, etc.)","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[{"scenario":"Bei einer Kontrolle tritt ein gereizter Mann immer näher an dich heran, bis er fast auf Tuchfühlung ist. Du fühlst dich sichtlich bedrängt.","frage":"Was passiert hier mit den Distanzzonen – und wie reagierst du?","loesung":"Er dringt in deine Intimzone ein; das erzeugt Stress und Bedrohungsgefühl (Distanzzonen nach Hall: Intim-, persönliche, soziale, öffentliche Zone). Denkschlüssel: bewusst Sicherheitsabstand herstellen (mind. ca. 1,50 m, ‚so nah wie nötig, so weit wie möglich'), ruhig einen Schritt zurück und seitlich versetzt stehen – das schützt (Eigensicherung) und deeskaliert zugleich."},{"scenario":"Ein Besucher wiederholt bei jeder Antwort stur denselben Vorwurf und lässt sich auf kein Argument ein. Deine Geduld schwindet.","frage":"Wie gehst du mit diesem Verhalten deeskalierend um?","loesung":"Typisches Querulanten-Verhalten – sachliche Argumente laufen ins Leere. Hilfreich ist die ‚Schallplatte mit Sprung' (die eigene Kernaussage ruhig und gleichbleibend wiederholen) und Provokationen zu überhören. Denkschlüssel: ruhig bleiben, nicht auf jede Provokation eingehen, Grenzen freundlich-bestimmt halten – Deeskalation heißt Spannung abbauen, nicht gewinnen."}]},{"n":10,"title":"Stress & Personenmehrheiten","subtitle":"5 Konzepte · 10 Prüfungsfragen","cards":[{"h":"Stress (Eustress/Disstress)","b":"Stressoren und Stresswirkungen; Umgang mit Stress als SMA","detail":{"titel":"Stress: Eustress und Disstress","kat":"Stress · Grundlagen","katCls":"mensch","merksatz":"Stress ist die Reaktion des Körpers auf Anforderungen (Stressoren). Man unterscheidet Eustress (positiver, antreibender Stress) und Disstress (negativer, belastender Stress). Die Körperreaktion ist dieselbe – entscheidend ist die Bewertung.","funktion":["Stressoren: Auslöser von Stress – z. B. Lärm, Hitze, Zeitdruck, Überforderung, Konflikte, Gefahr.","Eustress (positiv): antreibend und motivierend – z. B. Vorfreude, angestrebte Beförderung, erfolgreiches Bewerbungsgespräch.","Disstress (negativ): belastend und lähmend – z. B. Überforderung bei neuer Tätigkeit, Arbeit bei Lärm und Hitze, Angst.","Stresswirkungen: körperlich (Herzschlag, Anspannung) und seelisch (Gereiztheit, Angst); Dauerstress macht krank."],"schutzziel":"Eigenen Stress erkennen und steuern, um im Dienst leistungs- und reaktionsfähig zu bleiben.","kennwerte":[{"l":"Eustress","v":"positiv, antreibend"},{"l":"Disstress","v":"negativ, belastend"},{"l":"Stressoren","v":"Lärm · Hitze · Druck · Angst"},{"l":"Schlüssel","v":"die Bewertung entscheidet"}],"begriffe":["Stressor = ein Reiz oder Umstand, der eine Stressreaktion auslöst.","Eustress = positiv erlebter, motivierender Stress; Disstress = negativ erlebter, belastender Stress."],"abgrenzung":["Positiver Stress entsteht z. B. durch eine angestrebte Beförderung oder ein erfolgreiches Bewerbungsgespräch – nicht durch Angst.","Negativer Stress entsteht z. B. durch Überforderung bei neuer Tätigkeit oder Arbeit bei Lärm und Hitze – nicht durch leichte Routinetätigkeit."],"praxis":["Wer den eigenen Stress kennt, kann gegensteuern (Pausen, Atmung, gute Vorbereitung) und bleibt im Ernstfall handlungsfähig.","Dauerstress (Disstress) macht auf Dauer krank und fehleranfällig – im Dienst ein echtes Sicherheitsrisiko."]},"visual":null},{"h":"Gruppe & Team","b":"Merkmale; Eigen-/Fremd-/formelle/informelle/Bezugsgruppe; Umgang mit Gruppen","detail":{"titel":"Gruppe und Team","kat":"Personenmehrheiten · Gruppe","katCls":"mensch","merksatz":"Eine Gruppe ist eine überschaubare Zahl von Personen mit gemeinsamem Ziel, Wir-Gefühl und festen Rollen. Ein Team ist eine besonders eng zusammenarbeitende Gruppe. Man unterscheidet u. a. Eigen-, Fremd-, formelle, informelle und Bezugsgruppe.","funktion":["Gruppe: mehrere Personen mit gemeinsamem Ziel, Wir-Gefühl, festen Rollen und Regeln, direktem Kontakt.","Eigengruppe / Fremdgruppe: die Gruppe, der man selbst angehört – gegenüber Gruppen, denen man nicht angehört.","Formelle / informelle Gruppe: bewusst gebildet mit festen Regeln (z. B. Team) – gegenüber spontan aus Sympathie entstandenen.","Bezugsgruppe: die Gruppe, an deren Werten und Normen man sich orientiert."],"schutzziel":"Gruppendynamik verstehen, mit Gruppen souverän umgehen und im eigenen Team zuverlässig arbeiten.","kennwerte":[{"l":"Gruppe","v":"gemeinsames Ziel + Wir-Gefühl"},{"l":"Team","v":"eng zusammenarbeitende Gruppe"},{"l":"Eigen/Fremd","v":"zugehörig vs. nicht"},{"l":"Bezugsgruppe","v":"Orientierung an Werten"}],"begriffe":["Gruppe = überschaubare Zahl von Personen mit gemeinsamem Ziel, Wir-Gefühl und festen Rollen.","Bezugsgruppe = Gruppe, an deren Normen und Werten sich eine Person orientiert."],"abgrenzung":["Eine Gruppe ist nicht dasselbe wie eine Menge: Die Gruppe hat ein gemeinsames Ziel und Wir-Gefühl, die Menge nicht.","In der Gruppe verhält man sich oft anders als allein – Gruppendruck kann zu Handlungen verleiten, die man sonst unterlässt."],"praxis":["Bei einer Gruppe Jugendlicher den Wortführer ruhig und ohne Bloßstellen ansprechen – die Gruppe orientiert sich an ihm.","Im eigenen Team zählen Verlässlichkeit und klare Absprachen – Sicherheit ist Teamarbeit."]},"visual":null},{"h":"Menge","b":"Räumlich verbunden, kein gemeinsames Ziel; Handlungsempfehlungen","detail":{"titel":"Menge (Menschenmenge)","kat":"Personenmehrheiten · Menge","katCls":"mensch","merksatz":"Eine Menge ist eine räumlich verbundene Ansammlung vieler Menschen OHNE gemeinsames Ziel – z. B. Passanten in der Fußgängerzone oder Wartende. Sie ist zunächst ungefährlich, kann aber in eine Masse umschlagen.","funktion":["Merkmal: viele Menschen am selben Ort, doch jeder verfolgt sein eigenes Ziel; kein Wir-Gefühl.","Anonymität: in der Menge ist der Einzelne anonym – das kann die Hemmschwelle senken.","Gefahr: bei einem auslösenden Ereignis (Gerücht, Engpass, Panik) wird aus der Menge schnell eine (akute) Masse.","Handlungsempfehlung: Überblick behalten, Engpässe und Fluchtwege im Auge halten, früh und ruhig lenken."],"schutzziel":"Menschenmengen sicher beobachten und lenken und gefährliche Entwicklungen früh erkennen.","kennwerte":[{"l":"Menge","v":"räumlich verbunden, KEIN Ziel"},{"l":"Wir-Gefühl","v":"fehlt"},{"l":"Risiko","v":"kann zur Masse umschlagen"},{"l":"Taktik","v":"Überblick + Engpässe sichern"}],"begriffe":["Menge = räumlich verbundene Ansammlung vieler Menschen ohne gemeinsames Ziel.","Anonymität = das Untertauchen des Einzelnen in der Vielzahl – senkt die Hemmschwelle."],"abgrenzung":["Die Menge hat – anders als die Gruppe – KEIN gemeinsames Ziel und kein Wir-Gefühl.","Noch ist die Menge ungefährlich; gefährlich wird erst die (akute) Masse."],"praxis":["Vor einem Geschäft in der Fußgängerzone: viele Menschen, aber jeder für sich – eine typische Menge.","Engpässe wie Türen und Treppen früh entzerren, bevor Druck und Gedränge entstehen."]},"visual":null},{"h":"Masse & akute Masse","b":"„Masse steht, akute Masse geht“; Entstehung aus Menge; akute Masse bei Panik","detail":{"titel":"Masse und akute Masse","kat":"Personenmehrheiten · Masse","katCls":"mensch","merksatz":"Eine Masse entsteht aus einer Menge, wenn ein gemeinsames Gefühl oder Ziel hinzukommt. Merksatz: ‚Die Masse steht, die akute Masse geht.' Die akute Masse ist in Bewegung und besonders gefährlich (z. B. bei Panik).","funktion":["Masse: viele Menschen mit einem gemeinsamen Gefühl oder Ziel; der Einzelne geht im Kollektiv unter (Anonymität, Enthemmung).","‚Masse steht': die passive Masse verharrt – z. B. Zuschauer, die gebannt auf etwas starren.","‚akute Masse geht': die akute Masse ist in Bewegung und handelt – z. B. flüchtende oder randalierende Menge; hochgefährlich.","Verhalten in der Masse: Einzelne lassen sich zu Handlungen verleiten, die sie sonst unterlassen würden."],"schutzziel":"Das Umschlagen von Menge zu (akuter) Masse früh erkennen und gefährliche Massendynamik vermeiden.","kennwerte":[{"l":"Entstehung","v":"Menge + gemeinsames Gefühl/Ziel"},{"l":"Masse steht","v":"passiv, verharrend"},{"l":"akute Masse geht","v":"in Bewegung, gefährlich"},{"l":"Einzelner","v":"anonym, enthemmt"}],"begriffe":["Masse = große Menschenansammlung mit gemeinsamem Gefühl oder Ziel, in der der Einzelne anonym wird.","Akute Masse = eine in Bewegung geratene, aktiv handelnde Masse (z. B. bei Flucht oder Panik)."],"abgrenzung":["Merksatz ‚Masse steht, akute Masse geht': Die akute, bewegte Masse ist die gefährliche Form.","In der Anonymität der Masse lässt sich der Einzelne zu Handlungen verleiten, die er als Einzelperson unterlassen würde."],"praxis":["Eine gaffende Menschentraube (Masse steht) kann bei einem Alarm sofort zur flüchtenden akuten Masse werden.","Früh lenken und Wege offen halten – ist die akute Masse erst in Bewegung, ist sie kaum noch steuerbar."]},"visual":null},{"h":"Katastrophe & Panik","b":"Schadensereignis; Panikbegriffe: Panikstimmung, -ereignis, Paniksturm, Panikstarre","detail":{"titel":"Katastrophe und Panik","kat":"Personenmehrheiten · Panik","katCls":"mensch","merksatz":"Eine Katastrophe ist ein großes Schadensereignis. In Menschenmengen droht dabei Panik. Wichtige Panikbegriffe: Panikstimmung, Panikereignis, Paniksturm und Panikstarre.","funktion":["Panikstimmung: latente Angst und Anspannung in der Menge – die ‚Zündschnur' liegt bereit.","Panikereignis: der auslösende Moment (z. B. Feuer, Knall, Gerücht), der die Panik entzündet.","Paniksturm: kopflose, ungebremste Massenflucht – Menschen werden überrannt; höchste Gefahr.","Panikstarre: das Gegenteil – die Person erstarrt vor Angst und ist handlungsunfähig."],"schutzziel":"Panik früh erkennen, beruhigend einwirken und durch klare Führung den Schaden begrenzen.","kennwerte":[{"l":"Panikstimmung","v":"latente Angst (Vorstufe)"},{"l":"Panikereignis","v":"der Auslöser"},{"l":"Paniksturm","v":"kopflose Massenflucht"},{"l":"Panikstarre","v":"Erstarren, handlungsunfähig"}],"begriffe":["Panik = plötzliche, übermächtige Angst, die vernünftiges Handeln ausschaltet.","Katastrophe = großes Schadensereignis mit erheblicher Gefahr für Menschen und Sachen."],"abgrenzung":["Panik kann sich gegensätzlich äußern: als Paniksturm (kopflose Flucht) ODER als Panikstarre (Erstarren).","Beherrschtes Vorgehen und gezielte Suche nach Rettungswegen sind KEINE Folgen der Panik, sondern ihr Gegenteil."],"praxis":["Ruhige, laute und klare Ansagen sowie sichtbare Führung wirken der Panik entgegen.","Fluchtwege früh öffnen und freihalten – im Paniksturm zählt jeder freie Ausgang."]},"visual":null}],"quiz":[{"q":"In welchen Fällen kann negativer Stress ausgelöst werden?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wenn ein Mitarbeiter bei der Ausübung neuer Tätigkeiten überfordert ist","c":true},{"t":"Wenn leichte Büroarbeiten ohne hohe Anforderungen verrichtet werden","c":false},{"t":"Wenn in Räumen bei hohen Temperaturen und Lärm gearbeitet werden muss","c":true},{"t":"Wenn routinemäßig eine Tätigkeit mit viel Erfahrung ausgeübt wird","c":false}]},{"q":"In welchen Fällen wird Stress positiv empfunden?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wenn er durch eine angestrebte Beförderung ausgelöst wird","c":true},{"t":"Wenn er durch ein erfolgreiches Bewerbungsgespräch ausgelöst wird","c":true},{"t":"Wenn er durch Angst ausgelöst wird","c":false},{"t":"Wenn er durch eine besonders schwierige Aufgabe ausgelöst wird","c":false}]},{"q":"Verhalten sich Personen in Menschenmengen anders, als sie es als Einzelpersonen tun?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Ja, weil die Anonymität innerhalb der Menge Schutz vor Verfolgung bietet","c":true},{"t":"Nein, sie verhalten sich in einer Menge genauso wie als Einzelperson","c":false},{"t":"Ja, durch überzogene Darstellung von Feindbildern können Aggressionen entstehen","c":true},{"t":"Nein, Personen in Menschenmengen werden durch die Massendynamik besänftigt","c":false}]},{"q":"Welche Aussage über das Verhalten einer Einzelperson in Gruppen, Mengen oder Massen ist richtig?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"In der Gruppe, Menge oder Masse fühlt sich die Einzelperson unterlegen und hält sich zurück","c":false},{"t":"Das Verhalten in einer Gruppe ist unberechenbar; sie unterwirft sich spontanen Gruppenregeln und passt sich stets an","c":false},{"t":"Eine Person verhält sich immer gleich, egal ob allein oder in Gruppe, Menge oder Masse","c":false},{"t":"In der Anonymität von Gruppe, Menge oder Masse lassen sich Einzelpersonen oft zu Handlungen verleiten, die sie sonst unterlassen würden","c":true}]},{"q":"Welches Verhalten kann durch eine Panik hervorgerufen werden?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Paniksturm","c":true},{"t":"Beherrschtes Vorgehen","c":false},{"t":"Panikstarre","c":true},{"t":"Gezielte Suche nach Rettungsmöglichkeiten","c":false}]},{"q":"Nennen Sie die Stressarten.","a":"- Eustress, positiver Stress - Distress, negativer Stress","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Stressarten kennen Sie?","a":"Positiver Stress =\tEustress (gedankliche Ableitung aus Euphorie) Negativer Stress\t=\tDistress (gedankliche Ableitung aus „dissen“[ärgern]) Stressarten können je nach stressualer Belastung wechseln !","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist ein Flaschenhalseffekt, wie entwickelt sich Staudruck?","a":"Wenn eine größere Gruppe auf eine Fluchttür zustürmt und es zu einen Stau kommt; Menschentraube bildet einen sogenannten Flaschenhals Staudruck ist wenn es kein vorkommen mehr zu Flucht gibt.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was charakterisiert eine Gruppe, verhalten in Gruppen?","a":"Eine Gruppe hat ein gemeinsames Ziel, man kennt sich untereinander. Das Verhalten in einer Gruppe ist geregelt, es gibt eine Rangfolge.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Unterscheidung informelle Gruppe, formelle Gruppe.","a":"- Informelle Gruppe, Zusammenschluss von Menschen; keine Einwirkung von außen - formelle Gruppe, Zusammenschluss von Menschen, Von außen gesteuert (geformt); z.B. Kursteilnehmer einer Bildungsmaßnahme","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine Menschenmenge, was ist eine Menschenmasse?","a":"Eine Menschenmenge ist ein Zusammentreffen von Menschen, die sich grundsätzlich nicht persönlich kennt aber räumlich verbunden ist; Schaulustige, Demonstrationen, Rockkonzert, Veranstaltung... Eine Menschenmasse ist eine Menge die zielgerichtet in eine Richtung gelenkt wird; Lautsprecherdurchsage (Bitte verlassen sie den Bühnenbereich…), Bewegung wie tanzen, klatschen...","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine akute Masse?","a":"Gerät eine Menschenmasse durch einen Auslöser wie Angst, eine Explosion, ein Feuer in Bewegung, spricht man von einer akuten Masse. In der Folge kann es leicht zu einer Panik kommen. Menschen gehen zielgerichtet nach einer Bombendrohung zum Ausgang des Stadions; Plötzlich schreit jemand laut: „Gas“…","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine Katastrophe?","a":"Eine Katastrophe ist ein plötzlich unerwartetes Ereignis, welches ein gemeinschaftliches Handeln erfordert.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist Panik, nenne die 4 Panikarten.","a":"Panik entsteht wenn durch überraschendes Auftreten ein Zustand von Furcht und Schrecken unter Menschen auftritt und zu unkontrolliertem Handeln führt. - Panikstimmung, etwas wird oder könnte gleich geschehen - Panikereignis, es ist etwas geschehen (Knall, Feuer, Gasgeruch...) - Paniksturm, der Überlebensinstinkt wird aktiv, vernunftlose Fluchtreaktion - Panikstarre, man kann sich nicht mehr bewegen oder klar denken (man Erstarrt)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie entsteht eine Panik und in welchen Formen drückt sie sich aus?","a":"Eine Panik entsteht bei einer realen oder angenommenen Gefahr für Leib oder Leben Panikstarre (Menschen erstarren vor Angst) Paniksturm (Menschen rennen fluchtartig los, ohne auf ihr Umfeld zu achten) Trichtereffekt / Flaschenhalseffekt (es wollen mehr Menschen durch eine Verengung als durchpassen)","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[{"scenario":"Auf einer Großveranstaltung entsteht an einem Engpass plötzlich Gedränge. Einzelne rufen, die Menge beginnt sich unkontrolliert in eine Richtung zu schieben.","frage":"Wie nennt man diesen Zustand und was ist deine erste Priorität?","loesung":"Aus der Menge ist eine akute Masse geworden – „Masse steht, akute Masse geht“. Bei Panikgefahr (Staudruck, Flaschenhals) zählt zuerst, Engpässe zu öffnen, Fluchtwege freizuhalten und ruhig zu lenken. Keine zusätzliche Reizverstärkung durch Schreien."},{"scenario":"Bei einem Alarm bleibt eine Person wie erstarrt stehen, reagiert nicht auf Ansprache und bewegt sich nicht Richtung Ausgang.","frage":"Wie nennt man diese Reaktion und wie gehst du damit um?","loesung":"Das ist eine Panikstarre – eine mögliche Panikreaktion neben dem kopflosen Paniksturm. Denkschlüssel: die Person direkt, einfach und bestimmt ansprechen, behutsam führen und klare, kurze Anweisungen geben – Erstarrte brauchen Führung von außen, nicht noch mehr Reizüberflutung."}]}],"cardCount":43,"quizCount":160},{"id":"s34a-0","tg":0,"name":"Recht der öffentlichen Sicherheit und Ordnung","color":"var(--stack-mint)","meta":{"relevanz":"Hoch","schriftlich":"4 Fragen · 8/100 Punkte","muendlich":"Schwerpunkt"},"merksaetze":[],"blocks":[{"n":1,"title":"Grundbegriffe des Rechts","subtitle":"4 Konzepte · 33 Prüfungsfragen","cards":[{"h":"Staatsaufbau","b":"Staatsgebiet, Staatsvolk, Staatsmacht (Staatsgewalt)","detail":{"titel":"Staatsaufbau","kat":"ROSO · Staat","katCls":"recht","merksatz":"Ein Staat besteht aus drei Elementen: Staatsgebiet, Staatsvolk und Staatsmacht (Staatsgewalt). Die Staatsmacht ist die Ausübung hoheitlicher Macht innerhalb des Staatsgebiets durch die Organe des Staates.","funktion":["Staatsgebiet: das räumlich abgegrenzte Territorium, auf dem der Staat herrscht.","Staatsvolk: die Gesamtheit der Menschen, die dem Staat angehören (Staatsangehörige).","Staatsmacht (Staatsgewalt): die Ausübung hoheitlicher Macht innerhalb des Staatsgebiets durch Organe und Institutionen.","Aus dieser Staatsmacht leitet sich später das staatliche Gewaltmonopol ab."],"schutzziel":"Verstehen, worauf staatliche Macht beruht – die Grundlage für Gewaltmonopol, Zuständigkeiten und die Rolle privater Sicherheit.","kennwerte":[{"l":"Element 1","v":"Staatsgebiet"},{"l":"Element 2","v":"Staatsvolk"},{"l":"Element 3","v":"Staatsmacht / Staatsgewalt"},{"l":"Folge","v":"staatliches Gewaltmonopol"}],"begriffe":["Staatsgewalt = hoheitliche Macht, ausgeübt durch staatliche Organe.","Hoheitlich = mit staatlicher Befehls- und Zwangsgewalt ausgestattet."],"abgrenzung":["Staatsvolk ≠ alle Anwesenden: Touristen unterliegen der Staatsmacht, gehören aber nicht zum Staatsvolk.","Staatsmacht ist an Recht gebunden (Rechtsstaat) – sie ist nicht willkürlich."],"praxis":["Die Staatsmacht üben Organe wie Polizei, Behörden und Gerichte aus – nicht private Sicherheitsdienste.","Innerhalb des Staatsgebiets gilt deutsches Recht – auch für jede Bewachungsaufgabe."]},"visual":null},{"h":"Recht & Rechtsnorm","b":"Recht = Gesamtheit aller Rechtsnormen („Spielregeln“); Rechtsnorm = einzelne Regelung","detail":{"titel":"Recht & Rechtsnorm","kat":"ROSO · Grundbegriffe","katCls":"recht","merksatz":"Recht ist die Gesamtheit aller Rechtsnormen, die das Zusammenleben verbindlich regeln – einfach: alle ‚Spielregeln' in Deutschland. Eine einzelne Rechtsnorm ist eine einzelne Spielregel für einen bestimmten Bereich.","funktion":["Recht: die Gesamtheit aller verbindlichen Regeln des Zusammenlebens (‚alle Spielregeln').","Rechtsnorm: die sprachliche Form einer einzelnen, vom Staat aufgestellten Regelung (‚eine Spielregel').","Beispiele für Rechtsnormen: Grundgesetz, BGB, StGB, GewO.","Verbindlich: an die Regeln sind sowohl die Bürger als auch der Staat gebunden."],"schutzziel":"Klarheit, was ‚Recht' überhaupt ist – die Voraussetzung, um einzelne Vorschriften einzuordnen und richtig anzuwenden.","kennwerte":[{"l":"Recht","v":"Gesamtheit aller Rechtsnormen"},{"l":"Rechtsnorm","v":"einzelne Regelung"},{"l":"Bild","v":"die ‚Spielregeln'"},{"l":"Beispiele","v":"GG, BGB, StGB, GewO"}],"begriffe":["Rechtsnorm = die sprachlich gefasste, vom Staat gesetzte Einzelregel.","Verbindlich = für alle geltend und notfalls staatlich durchsetzbar."],"abgrenzung":["Recht ≠ einzelne Norm: Recht ist die Summe, die Norm der Einzelfall.","Recht ≠ Moral: Recht ist staatlich gesetzt und erzwingbar, Moral nicht."],"praxis":["Für die Sicherheitsarbeit zählt vor allem, welche Rechtsnorm in welcher Situation gilt (z. B. StGB bei Straftaten, BGB beim Hausrecht).","Wer die Normarten kennt, erkennt schnell, ob eine Vorschrift ein Gesetz, eine Verordnung oder eine Satzung ist."]},"visual":null},{"h":"Rangordnung der Rechtsnormen","b":"Grundgesetz > Gesetze > Verordnungen > Satzungen > Urteile > Gewohnheitsrecht","detail":{"titel":"Rangordnung der Rechtsnormen","kat":"ROSO · Normenhierarchie","katCls":"recht","merksatz":"Rechtsnormen stehen in einer festen Rangordnung: Grundgesetz > Gesetze > Verordnungen > Satzungen > Urteile > Gewohnheitsrecht. Das Grundgesetz ist das höchste Gesetz – alle anderen Normen müssen mit ihm vereinbar sein.","funktion":["Grundgesetz: höchste Norm; alle anderen müssen mit ihm übereinstimmen.","Gesetze: vom Parlament (Bundestag + Bundesrat) erlassen; enden auf ‚-gesetz', ‚Gesetzbuch' oder ‚-ordnung' (z. B. WaffG, BGB, GewO).","Verordnungen: unterhalb der Gesetze, durch Ermächtigung von Regierungs- und Verwaltungsorganen erlassen; enden auf ‚-verordnung' oder heißen ‚Vorschrift' (z. B. BewachV, DGUV Vorschrift 23).","Satzungen, Urteile, Gewohnheitsrecht: Satzungen von Stellen mit Satzungshoheit (Gemeinden); Urteile hoher Gerichte wirken wie eine Norm; Gewohnheitsrecht ist ungeschrieben und am schwächsten."],"schutzziel":"Normen richtig einordnen – höherrangiges Recht bricht niederrangiges, und das Grundgesetz steht über allem.","kennwerte":[{"l":"1. Rang","v":"Grundgesetz"},{"l":"dann","v":"Gesetze → Verordnungen"},{"l":"dann","v":"Satzungen → Urteile"},{"l":"schwächste","v":"Gewohnheitsrecht"}],"begriffe":["Verordnung = von der Verwaltung aufgrund gesetzlicher Ermächtigung erlassene Norm.","Satzung = Regelung einer Körperschaft mit Satzungshoheit (z. B. einer Gemeinde).","Gewohnheitsrecht = ungeschriebenes Recht durch lange Übung und allgemeine Rechtsüberzeugung."],"abgrenzung":["Gesetz ≠ Verordnung: Ein Gesetz beschließt das Parlament, eine Verordnung erlässt die Verwaltung.","Prüfungsrelevant: StPO und GewO sind Gesetze; BewachV und DGUV Vorschrift 23 sind Verordnungen."],"praxis":["Die Bewachungsverordnung (BewachV) ist eine Verordnung, kein Gesetz – sie konkretisiert das § 34a-Gewerberecht.","Widerspricht eine Satzung einem Gesetz, gilt das Gesetz – höherrangiges Recht setzt sich durch."]},"visual":null},{"h":"Anwendungsregeln","b":"Bundesrecht bricht Landesrecht; neues bricht altes; spezielles bricht allgemeines Recht","detail":{"titel":"Anwendungsregeln","kat":"ROSO · Normenkollision","katCls":"recht","merksatz":"Widersprechen sich Normen, gelten drei Regeln: ‚Bundesrecht bricht Landesrecht', ‚neues Recht bricht altes Recht' und ‚spezielles Recht bricht allgemeines Recht'.","funktion":["Bundesrecht bricht Landesrecht (Art. 31 GG): ein Landesgesetz weicht, wenn der Bund dieselbe Sache regelt (z. B. BDSG vor Landesdatenschutzgesetz).","Neues Recht bricht altes Recht: widersprechen sich zwei Gesetze, gilt das jüngere (z. B. Cannabisgesetz vor älterer Regelung).","Spezielles Recht bricht allgemeines Recht: die genauere Norm verdrängt die allgemeine (z. B. ein Verkehrszeichen vor der allgemeinen Regel ‚rechts vor links').","Diese Kollisionsregeln sorgen dafür, dass immer eindeutig ist, welche Norm gilt."],"schutzziel":"Bei widersprüchlichen Vorschriften eindeutig bestimmen, welche Norm Vorrang hat.","kennwerte":[{"l":"Regel 1","v":"Bundesrecht bricht Landesrecht"},{"l":"Regel 2","v":"neues bricht altes Recht"},{"l":"Regel 3","v":"spezielles bricht allgemeines"},{"l":"Grundlage","v":"Art. 31 GG (Vorrang Bund)"}],"begriffe":["Normenkollision = Widerspruch zwischen zwei Rechtsnormen.","Lex specialis = die speziellere Norm geht der allgemeinen vor."],"abgrenzung":["Die Regeln greifen nur bei echtem Widerspruch – ergänzen sich Normen, gelten sie nebeneinander.","Der Vorrang des Bundesrechts (Art. 31 GG) betrifft das Verhältnis Bund–Land, nicht alt–neu."],"praxis":["Im Datenschutz geht das bundesweite BDSG dem Landesdatenschutzgesetz vor.","Eine spezielle Vorschrift (z. B. die BewachV) ist beim § 34a-Thema genauer als die allgemeine GewO."]},"visual":null}],"quiz":[{"q":"Welche Rechtsvorschriften sind als Gesetze eingestuft?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Strafprozessordnung","c":true},{"t":"Die Bewachungsverordnung","c":false},{"t":"Die Unfallverhütungsvorschrift DGUV Vorschrift 23","c":false},{"t":"Die Gewerbeordnung","c":true}]},{"q":"Wie setzt sich ein Staat zusammen?","a":"Aus dem Staatsvolk, Staatsgebiet und der Staatgewalt.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"In welche Bereiche / Kategorien teilen sich die Grundrechte und warum?","a":"Menschenrechte= gilt für alle Menschen, im Staatsgebiet der Bundesrepublik Deutschland Bürgerrechte= gilt nur für deutsche Staatsangehörige, im Staatsgebiet der Bundesrepublik Deutschland","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist Recht?","a":"Recht ist Gesamtheit aller Normen (Gesetze, Verordnungen etc.), die ein friedliches Zusammenleben der Menschen zwischen Staat/Bürger und Bürger/Bürger regelt.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was besagt das Prinzip der Rechtsordnung ?","a":"Unterscheidung in Öffentliches und privates Recht.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welches Prinzip herrscht im öffentlichen - und privaten Recht?","a":"Im öffentlichen Recht: Staat gegen Bürger (Über-Unterordnungsprinzip) und im privaten Recht: Bürger gegen Bürger (Gleichstellungsprinzip)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie Rechtsquellen – Öffentliches/Privates Recht","a":"Öffentliches Recht: Staatsrecht, Strafrecht, Sozialrecht Privates Recht: Bürgerliches Recht, Arbeitsrecht, Handelsrecht","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist mit Hierarchie der Gesetze gemeint?","a":"Das Grundgesetzt geht allen anderen Gesetzten vor, danach kommen die allgemeinen Rechtsnormen wie StGB, BGB; dann Verordnungen, Satzungen und das sogenannte Gewohnheitsrecht.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wer ist im öffentlichen Recht, wer im privaten Recht zuständig?","a":"Im öffentlichen Recht der Staat (Polizei) und im privaten Recht Sicherheits- unternehmen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Rechte hat die Polizei und welche die privaten Sicherheits-","a":"mitarbeiter? Die Polizei hat Hoheitliche Rechte und die privaten die sogenannten Jedermannsrechte, bzw. Ausnahmerechte, sowie die übertragenen Besitzschutz- Rechte (gegen Verbotene Eigenmacht).","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wer hat das Gewaltmonopol? Was sind hoheitliche Aufgaben?","a":"Der Staat hat das Gewaltmonopol, es gibt aber Ausnahmen damit sich der Bürger z.B. gegen Angriffe wehren kann (Jedermannsrechte; Ausnahmerechte). Hoheitliche Aufgaben: z.B. Durchsuchen, Sicherstellen, Vernehmen (DSV)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre das PPP Modell? Was ist eine sogenannte Beleihung?","a":"Public-private-Partnership = Zusammenarbeit zwischen Polizei und Sicherheitsunternehmen zur Stärkung der öffentlichen Sicherheit. Hoheitliche Rechte können beliehen werden für die Arbeit an Flughafen, Atomkraftwerken und Bundeswehrflächen (z.B. LSichG, UzwG)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nenne alle Jedermannsrechte/Ausnahmerechte aus dem BGB/StGB, StPO","a":"BGB - Notwehr - Angriffsnotstand BGB - Verteidigungsnotstand BGB - Selbsthilfe BGB - Selbsthilfe des Besitzers BGB - Selbsthilfe des Besitzdieners BGB StGB - Notwehr - Rechtfertigender Notstand - Entschuldigender Notstand StPO - Vorläufige Festnahme","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wozu brauchen wir diese Jedermannsrechte/Ausnahmerechte?","a":"Sie erlauben dem Bürger unter bestimmten Voraussetzungen gegen das Gewaltmonopol zu verstoßen wenn Polizei (Staatsgewalt) nicht erreichbar ist","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Unterschied Rechtfertigungsgrund und Jedermannsrechte?","a":"Rechtfertigungsgründe werde auch Jedermannsrechte genannt. Sie erlauben es jedermann, in bestimmten Situationen einen Straftatbestand zu verletzen, ohne dafür bestraft zu werden; (Verhältnismäßigkeit beachten !!); Ausnahme: Der Entschuldigende Notstand. Dieser \"entschuldigt\" die Handlung, rechtfertigt sie aber nicht; z.B. das Brett des Karneades.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"In welches Grundrecht darf niemals eingegriffen werden?","a":"Artikel 1 In die Würde des Menschen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wo sind die Grundrechte Verankert? Nennen Sie 5 Grundrechte.","a":"Grundrechte sind im Grundgesetz Art. 1 – 19 verankert. - Würde des Menschen - Unverletzlichkeit der Wohnung - Eigentum - Meinungsfreiheit - Berufsfreiheit","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Worin besteht die praktische Bedeutung der Grundrechte für die","a":"Tätigkeit des Sicherheitsmitarbeiters? Die Grundrechte dürfen nicht verletzt werden, dürfen aber in Ausnahmefällen durch Gesetze eingeschränkt werden; z.B. § 127 (1) StPO","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie unterscheiden sich Menschenrecht von den Bürgerrechtern?","a":"Menschenrechte stehen allen Menschen zu, Bürgerrechte stehen allen Deutschen Staatsbürgern zu.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie bitte jeweils drei Beispiele.","a":"Menschenrechte: - Art. 1: Die Menschenwürde ist unantastbar - Art. 2: Recht auf freie Entfaltung der Person, Recht auf Leben, Recht auf körperliche Unversehrtheit, Recht auf Freiheit - Art. 3: Alle Menschen sind gleich - Art. 4: Freiheit des Glaubens Bürgerrechte: - Art. 8: Versammlungsfreiheit - Art. 9: Vereinigungsfreiheit und Koalitionsfreiheit - Art.11: Recht auf Freizügigkeit im gesamten Bundesgebiet - Art. 12: Recht auf freie Wahl von Beruf, Arbeitsplatz und Ausbildungsstätte - Art. 38 Abs. 1: Die Wahlrechtsgrundsätze","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre die horizontale und vertikale Gewaltenteilung ?","a":"Legislative - Erlass von Gesetzten Judikative - Rechtsprechung Horizontale Exekutive - ausführende Gewalt Gewaltenteilung Es gibt Sie damit Sie sich gegenseitig Kontrollieren, damit keiner die alleinige Gewalt ausüben kann (Polizeistaat) Wertigkeit: Legislative = Bundesrecht bricht Landesrecht. Judikative = Ein Landgericht ist dem Amtsgericht überstellt. Exekutive = Staatsanwaltschaft steht über der Polizei Vertikale Gewaltenteilung = Machtaufteilung in Bund, Länder, Kommunen (Föderalismus) verhindert eine Machtkonzentration und beugt staatlicher Willkür vor","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nenne die 5 Verfassungsprinzipien, Artikel 20 GG","a":"- Rechtsstaatsprinzip (Keine Strafe ohne Gesetz) - Demokratie (Alle Macht geht vom Volke aus) - Sozialstaatsprinzip (Augleich zwischen Arm und Reich) - Bundesstaatsprinzip (Föderalismus) - Republik (Staatsoberhaupt wird auf Zeit gewählt)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Notwehr?","a":"Notwehr ist die Verteidigung die erforderlich und geboten ist, einen gegenwärtigen rechtswidrigen Angriff von sich oder einen Anderen abzuwehren.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Rechtsgüter schützt die Notwehr?","a":"Alle Rechtsgüter ( Leben, Leib, Freiheit, Ehre, Eigentum)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Rechtswidrig?","a":"Der Angreifer hat keinen Rechtfertigungsgrund für sein Handeln.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Angriff?","a":"Beeinträchtigung notwehrfähiger Rechtsgüter durch einen Menschen (Leben, Freiheit, Eigentum,...)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was muss bei Kindern, bzw. schuldunfähigen beachtet werden?","a":"Schuldunfähige (Betrunkener, geistig Verwirrte) können für Ihr Vergehen nicht bestraft werden, müssen aber Schadensersatz (BGB) leisten. Wer das siebente, aber nicht das zehnte Lebensjahr vollendet hat, ist für den Schaden, den er bei einem Unfall mit einem Kraftfahrzeug, einer Schienenbahn oder einer Schwebebahn einem anderen zufügt, nicht verantwortlich. Dies gilt nicht, wenn er die Verletzung vorsätzlich herbeigeführt hat. Unter 7 Jahren haften die Erziehungsberechtigen wenn Ihnen die Vernachlässigung der erforderlichen Sorgfaltspflicht nachgewissen werden kann. Kinder unter 14 Jahren können nicht bestraft werden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Benennen Sie die drei Staatsgewalten der horizontalen Gewaltenteilung!","a":"Legislative = gesetzgebende Gewaltwie:\tBundestag (+ Bundesrat); Landtag Exekutive = ausführende / vollziehende Gewaltwie:\tPolizei; Staatsanwaltschaft; Bundespräsident Judikative = richterliche / rechtsprechende Gewaltwie: Richter (an Bundes- & Landesgericht)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Artikel im Grundgesetz beinhalten die Grundrechte?","a":"Die Artikel 1 bis 19","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Das deutsche Rechtssystem teilt sich in zwei Rechtsgebiete, welche sind das und warum sind sie geteilt?","a":"Öffentliches Recht- hier stehen sich Staat und Bürger gegenüber- der Staat ist hier dem Bürger übergeordnet- es gilt das Über-/Unterordnungsprinzip (Subordinationsprinzip) Privates /Ziviles Recht- hier stehen sich Bürger und Bürger gegenüber- Bürger sind zueinander gleichgestellt- es gilt das Gleichordnungsprinzip (Koordinationsprinzip)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Aufgabe haben die Grundrechte?","a":"Sie sollen die Bürger vor staatlicher Willkür schützen. Sie sollen in Drittwirkung die Bürger untereinander schützen. Sie benennen eindeutig verschiedene geschützte Rechtsgüterwie: Leben, Gesundheit, Freiheit, Eigentum","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wer darf in der BRD Gesetze erlassen und welche spezielle Reglung trifft das Grundgesetz diesbezüglich??","a":"Nur der Bund (durch den Bundestag + Bundesrat) und die Bundesländer (durch den jeweiligen Landtag) dürfen Gesetze erlassen! Bundesrecht bricht Landesrecht (Artikel 31 GG)- ein Landesgesetz muss also weichen wenn die gleichen Dinge durch ein Bundesgesetz geregelt werden","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was bedeutet das Gewaltmonopol in Deutschland und wer ist Inhaber von diesem?","a":"Bedeutet, dass nur der Staat darf im rechtlichen Rahmen Gewalt anwenden. Nur der Staat ist Inhaber des GewaltmonopolsDie sogenannten Ausnahmerechte (Rechtfertigungsgründe/Jedermannsrechte) erteilen dem Bürger im Rahmen einer Ausnahme die Möglichkeit Gewalt anzuwenden.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter einer Beleihung?","a":"Teile der hoheitlichen Rechte können auf private befristet übertragen werdenwie:\tprivate Sicherheitsdienstleister; TÜV; GTÜ; Bezirksschornsteinfeger Erfolgt in der privaten Sicherheit zum Beispiel im Rahmen einerPPP = Public-Private-Partnerschip(öffentlich-private-Zusammenarbeit)","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[]},{"n":2,"title":"Staatsaufbau & Verfassung","subtitle":"5 Konzepte · 7 Prüfungsfragen","cards":[{"h":"5 Verfassungsprinzipien (Art. 20 GG)","b":"Republik, Demokratie, Sozialstaat, Bundesstaat, Rechtsstaat; Merksatz Bundes(4)-Republik(1)…","detail":{"titel":"Die fünf Verfassungsprinzipien (Art. 20 GG)","kat":"ROSO · Verfassung","katCls":"recht","merksatz":"Artikel 20 GG benennt fünf Verfassungsprinzipien: Republik, Demokratie, Sozialstaat, Bundesstaat und Rechtsstaat. Merksatz: ‚Die Bundes(4)-Republik(1) Deutschland ist ein demokratischer(2) und sozialer(3) Rechtsstaat(5).'","funktion":["Republik: die Volksvertreter werden nur auf Zeit gewählt – kein Monarch auf Lebenszeit.","Demokratie: alle Staatsgewalt geht vom Volke aus.","Sozialstaat: der Staat ist verpflichtet, soziale Gerechtigkeit und Sicherheit zu schaffen.","Bundesstaat: der föderale Aufbau (siehe Föderalismus); Rechtsstaat: Bindung von Staat und Bürger an Recht und Gesetz."],"schutzziel":"Die Grundpfeiler der Staatsordnung kennen – sie sind durch die Ewigkeitsklausel besonders geschützt.","kennwerte":[{"l":"Verankert in","v":"Art. 20 GG"},{"l":"Merksatz","v":"Bundes(4)-Republik(1) · demokratisch(2) · sozial(3) · Rechtsstaat(5)"},{"l":"Anzahl","v":"5 Prinzipien"},{"l":"Schutz","v":"Ewigkeitsklausel (Art. 79 GG)"}],"begriffe":["Verfassungsprinzip = ein tragender Grundsatz der Staatsordnung.","Republik = Staatsform mit auf Zeit gewählten Vertretern (kein Monarch)."],"abgrenzung":["Deutschland ist KEINE ‚Volksrepublik' und kein sozialistischer Einheitsstaat, sondern ein demokratischer und sozialer, föderalistisch organisierter Bundesstaat.","Sozialstaat (soziale Sicherheit) ≠ Sozialismus (Staatswirtschaft) – das wird gern verwechselt."],"praxis":["In der Prüfung wird gefragt, ‚was Deutschland ist' – Antwort: demokratischer und sozialer Bundesstaat (föderalistisch).","Der Merksatz mit den Ziffern hilft, alle fünf Prinzipien sicher aufzuzählen."]},"visual":null},{"h":"Rechtsstaatsprinzip","b":"Staat und Organe an geltendes Recht gebunden","detail":{"titel":"Rechtsstaatsprinzip","kat":"ROSO · Rechtsstaat","katCls":"recht","merksatz":"Ein Rechtsstaat verpflichtet sich und seine Organe, bei der Ausübung staatlicher Gewalt geltendes Recht einzuhalten. Das gesamte Staatshandeln ist an Recht und Gesetz gebunden – es gibt keine Strafe und keinen Eingriff ohne gesetzliche Grundlage.","funktion":["Bindung an das Recht: Staat und alle Organe dürfen nur auf gesetzlicher Grundlage handeln.","Schutz vor Willkür: keine Strafe ohne Gesetz, kein Eingriff ohne Rechtsgrundlage, kein erzwungenes Geständnis durch Folter.","Verhältnismäßigkeit: jede staatliche Maßnahme muss geeignet, erforderlich und angemessen sein – das mildeste Mittel ist zu wählen.","Beispiel: die Polizei darf ohne gesetzliche Grundlage (Durchsuchungsbeschluss oder Gefahr im Verzug) nicht in eine Privatwohnung eindringen."],"schutzziel":"Den Bürger vor staatlicher Willkür schützen – der Staat selbst ist an das Recht gebunden.","kennwerte":[{"l":"Kern","v":"Staat an Recht und Gesetz gebunden"},{"l":"Folge","v":"keine Strafe/kein Eingriff ohne Gesetz"},{"l":"Verhältnismäßigkeit","v":"geeignet · erforderlich · angemessen"},{"l":"Mittel","v":"stets das mildeste wählen"}],"begriffe":["Rechtsstaat = Staat, dessen gesamtes Handeln an Recht und Gesetz gebunden ist.","Verhältnismäßigkeit = die Maßnahme muss geeignet, erforderlich (mildestes Mittel) und angemessen sein."],"abgrenzung":["Der Grundsatz der Verhältnismäßigkeit gilt NICHT nur für die Staatsgewalt – auch private Sicherheitskräfte müssen das mildeste Mittel wählen.","Eine Maßnahme ist nur so lange zulässig, bis ihr Zweck erreicht ist – danach ist sie zu beenden."],"praxis":["Auch du als SMA musst verhältnismäßig handeln: das mildeste geeignete Mittel, nur so lange wie nötig.","Eine Strafe ohne gesetzliche Grundlage oder ein durch Folter erzwungenes Geständnis verstößt klar gegen die Rechtsordnung."]},"visual":null},{"h":"Verhinderung von Machtmissbrauch","b":"Rechtsstaatsprinzip, Gewaltenteilung, Grundrechte","detail":{"titel":"Verhinderung von Machtmissbrauch","kat":"ROSO · Machtkontrolle","katCls":"recht","merksatz":"Damit der Staat seine Macht nicht missbraucht, sorgen drei Sicherungen vor: das Rechtsstaatsprinzip, die horizontale und vertikale Gewaltenteilung sowie die Festlegung von Grundrechten.","funktion":["Rechtsstaatsprinzip: der Staat bindet sich selbst an Recht und Gesetz.","Gewaltenteilung: die Staatsgewalt wird horizontal (Legislative, Exekutive, Judikative) und vertikal (Bund, Länder, Kommunen) aufgeteilt.","Grundrechte: sie schützen den Bürger vor staatlicher Willkür (Art. 1–19 GG).","Zusammenwirken: keine Stelle hat die gesamte Macht – die Gewalten kontrollieren sich gegenseitig."],"schutzziel":"Machtkonzentration und Willkür verhindern – die Macht wird verteilt und kontrolliert.","kennwerte":[{"l":"Sicherung 1","v":"Rechtsstaatsprinzip"},{"l":"Sicherung 2","v":"horizontale + vertikale Gewaltenteilung"},{"l":"Sicherung 3","v":"Grundrechte"},{"l":"Ziel","v":"keine Machtkonzentration"}],"begriffe":["Gewaltenteilung = Aufteilung der Staatsgewalt auf verschiedene Träger, die sich gegenseitig kontrollieren.","Willkür = Handeln ohne sachlichen Grund und ohne Rechtsbindung."],"abgrenzung":["Die drei Sicherungen ergänzen sich – sie ersetzen einander nicht.","Gewaltenteilung meint NICHT, dass ‚nicht jeder Polizist alle Rechte ausüben darf', sondern die Teilung der Staatsgewalt in Legislative, Exekutive und Judikative."],"praxis":["Dass die Polizei dich nicht ohne Grund festhalten darf, ist gelebte Machtkontrolle (Rechtsstaat + Grundrechte).","Die gegenseitige Kontrolle zeigt sich z. B., wenn das Bundesverfassungsgericht ein Gesetz prüft."]},"visual":null},{"h":"Horizontale Gewaltenteilung","b":"Legislative, Exekutive, Judikative – unabhängig, gegenseitige Kontrolle","detail":{"titel":"Horizontale Gewaltenteilung","kat":"ROSO · Gewaltenteilung","katCls":"recht","merksatz":"Die horizontale (‚waagerechte') Gewaltenteilung teilt die Staatsgewalt in drei unabhängige Bereiche: Legislative (Gesetzgebung), Exekutive (ausführende Gewalt) und Judikative (Rechtsprechung). Sie handeln unabhängig und kontrollieren sich gegenseitig.","funktion":["Legislative – Gesetzgebung: erarbeitet und erlässt Gesetze; dazu zählen Bundestag, Bundesrat und die Länderparlamente.","Exekutive – ausführende Gewalt: sorgt für die Einhaltung der Gesetze; dazu zählen Bundespräsident, Bundeskanzler und Regierung, Behörden und Ämter sowie die Staatsanwaltschaft.","Judikative – Rechtsprechung: entscheidet Rechtsstreitigkeiten; dazu zählen die Richter und Gerichte.","Gegenseitige Kontrolle: z. B. überprüft das Bundesverfassungsgericht (Judikative) die Gesetze (Legislative)."],"schutzziel":"Machtkonzentration verhindern, indem Gesetzgebung, Verwaltung und Rechtsprechung getrennt sind und sich kontrollieren.","kennwerte":[{"l":"Legislative","v":"Gesetzgebung · Bundestag/Bundesrat"},{"l":"Exekutive","v":"Verwaltung · Polizei/Behörden/StA"},{"l":"Judikative","v":"Rechtsprechung · Richter/Gerichte"},{"l":"Prinzip","v":"unabhängig + gegenseitige Kontrolle"}],"begriffe":["Legislative = die gesetzgebende Gewalt (Bundestag, Bundesrat, Länderparlamente).","Exekutive = die ausführende Gewalt (Regierung, Behörden, Polizei, Staatsanwaltschaft).","Judikative = die rechtsprechende Gewalt (Richter und Gerichte)."],"abgrenzung":["Die Polizei und die Staatsanwaltschaft gehören zur Exekutive – NICHT zur Judikative.","Im Bereich der Judikative arbeiten Richter – Justizvollzugs- oder Polizeibeamte gehören NICHT dazu."],"praxis":["Du als SMA arbeitest in keiner der drei Gewalten – du bist Privatperson mit Jedermannsrechten.","Die Polizei ist Teil der Exekutive; ein Strafurteil spricht dagegen die Judikative (das Gericht)."]},"visual":null},{"h":"Vertikale Gewaltenteilung & Föderalismus","b":"Bund, Länder, Kommunen; Aufteilung der Zuständigkeiten","detail":{"titel":"Vertikale Gewaltenteilung & Föderalismus","kat":"ROSO · Föderalismus","katCls":"recht","merksatz":"Die vertikale (‚senkrechte') Gewaltenteilung verteilt die Staatsgewalt auf drei Ebenen: Bund, Länder und Kommunen. Das ist der Föderalismus: teilsouveräne Gliedstaaten (Bundesländer) bilden gemeinsam einen Bundesstaat.","funktion":["Bund: zuständig z. B. für Außenpolitik und Steuerwesen.","Länder: zuständig z. B. für Polizeirecht und Bildung.","Kommunen (Gemeinden/Städte): zuständig z. B. für Müllabfuhr und den Bau von Schwimmbädern.","Föderalismus: die teilsouveränen Bundesländer haben eigene Gesetzgebungskompetenz; Zuständigkeiten sind auf die drei Ebenen verteilt."],"schutzziel":"Macht auch ‚in der Höhe' verteilen – nicht alles wird zentral entschieden, sondern auf passender Ebene.","kennwerte":[{"l":"Ebene 1","v":"Bund (z. B. Außenpolitik, Steuern)"},{"l":"Ebene 2","v":"Länder (z. B. Polizei, Bildung)"},{"l":"Ebene 3","v":"Kommunen (z. B. Müll, Schwimmbäder)"},{"l":"Begriff","v":"Föderalismus · vertikal = senkrecht"}],"begriffe":["Föderalismus = Staatsaufbau aus teilsouveränen Gliedstaaten, die einen Bundesstaat bilden.","Teilsouveränität = die Bundesländer haben eigene, begrenzte Hoheitsrechte (z. B. Gesetzgebung)."],"abgrenzung":["Vertikal (Bund–Länder–Kommunen) ≠ horizontal (Legislative–Exekutive–Judikative) – das wird oft verwechselt.","Die Polizei ist deshalb grundsätzlich Ländersache; ‚ausschließlich Sache des Bundes' ist falsch."],"praxis":["Dass die Polizei Ländersache ist, erklärt die unterschiedlichen Polizeigesetze der Bundesländer.","Für dein Bundesland gilt das jeweilige Landes(polizei)recht – ein Beispiel gelebten Föderalismus."]},"visual":null}],"quiz":[{"q":"Beenden Sie den Satz korrekt. Deutschland ist…","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"…eine sozialdemokratische Volksrepublik","c":false},{"t":"…ein demokratischer und sozialer Staat","c":true},{"t":"…ein demokratischer und sozialistischer Einheitsstaat","c":false},{"t":"…ein föderalistisch organisierter Bundesstaat","c":true}]},{"q":"In welche drei „Gewalten“ teilt sich unser Staat laut Grundgesetz auf?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Legislative, Exekutive, Judikative","c":true},{"t":"Judikative, Legislative, Richtersprechung","c":false},{"t":"Gericht, Staatsanwaltschaft, Polizei","c":false},{"t":"Staat, Volk, Medien","c":false}]},{"q":"Erklären Sie den Begriff „Gewaltenteilung“!","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Es gibt 3 Gewalten: Gericht, Staatsanwalt, Polizei","c":false},{"t":"Die Gewalten sind geteilt, das heißt nicht jeder Polizist darf alle Polizeirechte ausüben","c":false},{"t":"Die 3 Gewalten sind: Legislative, Exekutive, Judikative","c":true},{"t":"Die Gewalten kontrollieren sich gegenseitig","c":true}]},{"q":"Welche Institutionen zählen zur gesetzgebenden Gewalt?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Staatsanwaltschaft","c":false},{"t":"Die Regierungen der Bundesländer","c":false},{"t":"Der Bundesrat","c":true},{"t":"Der Bundestag","c":true}]},{"q":"Wer ist im Bereich der Judikative beschäftigt?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Richter","c":true},{"t":"Justizvollzugsbeamte","c":false},{"t":"Polizeivollzugsbeamte","c":false},{"t":"Sachbearbeiter der Gewerbebehörde","c":false}]},{"q":"Welche Aussagen zum Grundsatz der Verhältnismäßigkeit sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Eine Maßnahme ist nur so lange zulässig, bis ihr Zweck erreicht ist","c":true},{"t":"Dieser Grundsatz muss nur von der Staatsgewalt beachtet werden","c":false},{"t":"Es darf jedes Mittel eingesetzt werden, um den gewünschten Erfolg zu erreichen","c":false},{"t":"Sind mehrere Mittel verfügbar, ist das mildeste Mittel zu wählen","c":true}]},{"q":"Was verstößt gegen die Rechtsordnung der Bundesrepublik Deutschland?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Sicherstellung von Gegenständen zu Beweiszwecken durch die Polizei","c":false},{"t":"Die Bestrafung einer Person mit einer mehrjährigen Freiheitsstrafe ohne gesetzliche Grundlage","c":true},{"t":"Die Verweigerung einer Bewachungserlaubnis aufgrund Unzuverlässigkeit des Antragstellers","c":false},{"t":"Die Erzwingung eines Geständnisses durch Anwendung von Folter, z. B. durch Schläge","c":true}]},{"q":"Welche Aussagen zur Polizei in Deutschland sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Polizei ist zuständig für die Aufrechterhaltung der Betriebssicherheit in Unternehmen","c":false},{"t":"Die Polizei ist grundsätzlich Sache der Bundesländer","c":true},{"t":"Die Polizei ist ausschließlich Sache des Bundes","c":false},{"t":"Die Polizei ist von Amts wegen zur Strafverfolgung und Entgegennahme von Strafanzeigen verpflichtet","c":true}]},{"q":"Definiere den Begriff Ewigkeitsklausel","a":"Bedeutet, dass die Artikel 1 und 20 (Verfassungsprinzipien) nicht verändert werden dürfen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nenne die 5 Verfassungsprinzipien, Artikel 20 GG","a":"- Rechtsstaatsprinzip (Keine Strafe ohne Gesetz) - Demokratie (Alle Macht geht vom Volke aus) - Sozialstaatsprinzip (Augleich zwischen Arm und Reich) - Bundesstaatsprinzip (Föderalismus) - Republik (Staatsoberhaupt wird auf Zeit gewählt)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was haben der Artikel 1 und Artikel 20 des GG gemeinsam?","a":"Sie sind durch die sogenannte Ewigkeitsklausel (Artikel 79 GG) geschütztund somit unveränderbar","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Erkläre die horizontale und vertikale Gewaltenteilung ?","a":"Legislative - Erlass von Gesetzten Judikative - Rechtsprechung Horizontale Exekutive - ausführende Gewalt Gewaltenteilung Es gibt Sie damit Sie sich gegenseitig Kontrollieren, damit keiner die alleinige Gewalt ausüben kann (Polizeistaat) Wertigkeit: Legislative = Bundesrecht bricht Landesrecht. Judikative = Ein Landgericht ist dem Amtsgericht überstellt. Exekutive = Staatsanwaltschaft steht über der Polizei Vertikale Gewaltenteilung = Machtaufteilung in Bund, Länder, Kommunen (Föderalismus) verhindert eine Machtkonzentration und beugt staatlicher Willkür vor","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Benennen Sie die drei Staatsgewalten der horizontalen Gewaltenteilung!","a":"Legislative = gesetzgebende Gewaltwie:\tBundestag (+ Bundesrat); Landtag Exekutive = ausführende / vollziehende Gewaltwie:\tPolizei; Staatsanwaltschaft; Bundespräsident Judikative = richterliche / rechtsprechende Gewaltwie: Richter (an Bundes- & Landesgericht)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter dem Begriff Föderalismus?","a":"Form der Staatsorganisation = stellt bei uns (BRD) den strukturellen Aufbau in der sogenannten „vertikalen Gewaltenteilung“ dar. Teilsouveränität der Bundesländer = Gesetzgebungskompetenz Vertikale Verwaltungs- / Staatsstruktur durchBund > Bundesländer > Landkreise > Kommunen (Gemeinden/Städte)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was versteht man unter: „Föderalismus“ ?","a":"Zusammenschluss mehrerer Bundesländer zu einem Bundesstaat mit dem Ziel der Machtaufteilung zwischen dem Bund, den 16 Bundesländern; z.B. Polizei sowie der Kommunen (Amtsgerichte u.a.)","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[]},{"n":3,"title":"Grundrechte","subtitle":"5 Konzepte · 15 Prüfungsfragen","cards":[{"h":"Grundrechte (Art. 1–19 GG)","b":"Schutz vor staatlicher Willkür und vor anderen Bürgern (Drittwirkung)","detail":{"titel":"Das Grundgesetz & die Grundrechte","kat":"ROSO · Grundrechte","katCls":"recht","merksatz":"Das Grundgesetz (GG) ist die Verfassung der Bundesrepublik Deutschland und das höchste nationale Gesetz – alle anderen Rechtsnormen müssen mit ihm vereinbar sein. Die Grundrechte stehen in den Artikeln 1–19 GG und schützen den Bürger vor staatlicher Willkür und vor Eingriffen anderer Bürger.","funktion":["Das GG enthält die Grundrechte, die Verfassungsprinzipien und die Struktur des Staates.","Grundrechte = Artikel 1–19 GG; das Grundgesetz hat insgesamt 146 Artikel.","Grundrechte sind Schutzrechte: In sie darf nur aufgrund eines Gesetzes eingegriffen werden.","Nicht jedes Grundrecht ist einschränkbar – die Menschenwürde (Art. 1) ist unantastbar."],"schutzziel":"Den Rahmen kennen, in dem jede Sicherheitstätigkeit steht – die Grundrechte sind die oberste Schranke staatlichen und privaten Handelns.","kennwerte":[{"l":"Rang","v":"höchstes nationales Gesetz"},{"l":"Grundrechte","v":"Art. 1–19 GG"},{"l":"Artikel gesamt","v":"146"},{"l":"Eingriff","v":"nur aufgrund eines Gesetzes"}],"begriffe":["Verfassung = die rechtliche Grundordnung des Staates.","Schutzrecht = Recht, das den Bürger gegen Eingriffe schützt."],"abgrenzung":["Gleichheit vor dem Gesetz und Unverletzlichkeit der Wohnung sind Grundrechte – ein ‚Recht auf Strafverfolgung' oder ‚das bürgerliche Recht' sind keine.","Das GG gilt nicht nur für deutsche Staatsbürger und setzt die Länderverfassungen nicht außer Kraft."],"praxis":["Greift die Polizei in Art. 13 (Wohnung) ein, braucht sie eine gesetzliche Grundlage – Durchsuchungsbefehl oder Gefahr im Verzug.","Das Strafrecht stellt Grundrechtsverletzungen unter Strafe und schützt so die Grundrechte."]},"visual":null},{"h":"Grundgesetz","b":"Verfassung der BRD, höchstes nationales Gesetz","detail":{"titel":"Die Menschenwürde (Art. 1 GG)","kat":"ROSO · Grundrechte","katCls":"recht","merksatz":"Artikel 1 GG: Die Würde des Menschen ist unantastbar. Sie gilt für jeden Menschen, der sich im Geltungsbereich des GG aufhält – auch für minderjährige Kinder, Straftäter und Ausländer. Der Staat ist verpflichtet, sie zu achten und zu schützen.","funktion":["Geschützt ist jeder Mensch im Geltungsbereich des GG – unabhängig von Herkunft, Alter oder Vorstrafen.","Der Staat hat eine doppelte Pflicht: die Menschenwürde zu achten UND aktiv zu schützen.","Die Menschenwürde ist unantastbar – in sie darf nicht eingegriffen werden.","Sie ist das oberste Grundrecht und Maßstab für alle anderen."],"schutzziel":"Verstehen, dass jeder Mensch – auch der Ladendieb oder der aggressive Gast – eine unantastbare Würde hat, die im Einsatz zu respektieren ist.","kennwerte":[{"l":"Artikel","v":"Art. 1 GG"},{"l":"Status","v":"unantastbar"},{"l":"Gilt für","v":"jeden Menschen im Geltungsbereich"},{"l":"Staatspflicht","v":"achten und schützen"}],"begriffe":["Unantastbar = darf unter keinen Umständen verletzt werden.","Geltungsbereich = das Staatsgebiet der Bundesrepublik."],"abgrenzung":["Die Menschenwürde schützt KEINE juristischen Personen (Firmen) und nicht ‚die Menschheit' als Ganzes, sondern den einzelnen Menschen.","Sie ist nicht auf Leben und körperliche Unversehrtheit beschränkt – sie umfasst die ganze Würde des Menschen."],"praxis":["Auch ein festgehaltener Tatverdächtiger wird mit Respekt behandelt – Folter oder Erniedrigung sind absolut verboten.","Eine Durchsuchung oder Kontrolle muss so erfolgen, dass die Würde der Person gewahrt bleibt."]},"visual":null},{"h":"Grundrechte & Strafrecht","b":"Strafrecht schützt Grundrechte, indem es Verletzungen unter Strafe stellt","detail":{"titel":"Menschenrechte und Bürgerrechte","kat":"ROSO · Grundrechte","katCls":"recht","merksatz":"Die Grundrechte werden in Menschenrechte und Bürgerrechte eingeteilt. Menschenrechte gelten für alle Menschen, die sich in Deutschland aufhalten (‚Jeder…', ‚Alle Menschen…'). Bürgerrechte gelten nur für deutsche Staatsbürger (‚Alle Deutschen…').","funktion":["Menschenrechte: für alle Menschen in Deutschland, auch Flüchtlinge und Touristen – sie sind Abwehrrechte gegen staatliche Willkür.","Bürgerrechte (Deutschen-Rechte): nur für deutsche Staatsbürger.","Erkennungszeichen: Menschenrechte starten mit ‚Jeder/Alle Menschen', Bürgerrechte mit ‚Alle Deutschen'.","Typische Bürgerrechte: Berufsfreiheit (Art. 12), Versammlungsfreiheit (Art. 8), Vereinsfreiheit (Art. 9), Freizügigkeit (Art. 11)."],"schutzziel":"Sicher unterscheiden können, welches Recht für alle gilt und welches nur für Deutsche – eine der häufigsten Prüfungsfragen im Themengebiet.","kennwerte":[{"l":"Menschenrechte","v":"alle Menschen in Deutschland"},{"l":"Bürgerrechte","v":"nur deutsche Staatsbürger"},{"l":"Merkmal MR","v":"‚Jeder / Alle Menschen'"},{"l":"Merkmal BR","v":"‚Alle Deutschen'"}],"begriffe":["Abwehrrecht = Recht, sich gegen Eingriffe des Staates zu wehren.","Bürgerrecht = Grundrecht, das an die deutsche Staatsangehörigkeit gebunden ist."],"abgrenzung":["Menschenrechte gelten NICHT weltweit für Deutsche im Ausland – sie gelten für Menschen IN Deutschland.","Die Berufsfreiheit ist ein Bürgerrecht; die Unverletzlichkeit der Wohnung und die körperliche Unversehrtheit sind Menschenrechte."],"praxis":["Ein Tourist genießt die Menschenrechte (z. B. Menschenwürde, Recht auf Leben) wie jeder Deutsche.","Die Versammlungs- und Vereinsfreiheit sind als Bürgerrechte an Deutsche geknüpft."]},"visual":null},{"h":"Ewigkeitsklausel","b":"Art. 1 und 20 GG unveränderbar","detail":{"titel":"Der Gleichheitsgrundsatz (Art. 3 GG)","kat":"ROSO · Grundrechte","katCls":"recht","merksatz":"Artikel 3 GG: Alle Menschen sind vor dem Gesetz gleich. Männer und Frauen sind gleichberechtigt. Niemand darf wegen Geschlecht, Herkunft, Glauben oder Behinderung benachteiligt oder bevorzugt werden.","funktion":["Alle Menschen sind vor dem Gesetz gleich – ein Menschenrecht.","Männer und Frauen sind gleichberechtigt.","Die Gleichberechtigung darf nicht durch einfache Gesetze ausgehebelt werden.","Der Staat muss die tatsächliche Durchsetzung der Gleichberechtigung fördern."],"schutzziel":"Gleichbehandlung als bindenden Maßstab verstehen – auch bei Einlass- und Personenkontrollen.","kennwerte":[{"l":"Artikel","v":"Art. 3 GG"},{"l":"Kernsatz","v":"alle gleich vor dem Gesetz"},{"l":"Geschlechter","v":"Mann und Frau gleichberechtigt"},{"l":"Status","v":"Menschenrecht"}],"begriffe":["Gleichheitsgrundsatz = Verbot sachwidriger Ungleichbehandlung.","Gleichberechtigung = gleiche Rechte für Mann und Frau."],"abgrenzung":["Die Gleichberechtigung von Mann und Frau kann NICHT durch Gesetze eingeschränkt werden.","Ein generelles Nachtarbeitsverbot nur für Frauen ist mit dem Gleichheitsgrundsatz NICHT vereinbar."],"praxis":["Eine Einlasskontrolle darf nicht willkürlich nach Herkunft oder Geschlecht selektieren.","Hausrecht und Auswahlkriterien müssen sachlich begründet und gleich angewandt werden."]},"visual":null},{"h":"Menschen- vs. Bürgerrechte","b":"Menschenrechte für alle, Bürgerrechte nur für deutsche Staatsbürger","detail":{"titel":"Recht auf Leben & Freiheit der Person","kat":"ROSO · Grundrechte","katCls":"recht","merksatz":"Das Recht auf Leben (Art. 2 GG) ist ein Menschenrecht: Es gilt für alle Menschen in Deutschland. In dieses Recht und in die Freiheit der Person darf nur aufgrund eines Gesetzes eingegriffen werden – zum Beispiel durch Notwehr (§ 32 StGB) oder die StPO.","funktion":["Recht auf Leben: Menschenrecht für alle auf dem Staatsgebiet der Bundesrepublik.","Eingriff in das Recht auf Leben ist aufgrund eines Gesetzes möglich, z. B. durch Notwehr gemäß § 32 StGB.","Freiheit der Person: in der Regel ist die körperliche Bewegungsfreiheit jeder natürlichen Person geschützt.","Eingriffe in die Freiheit sind nur aufgrund eines Gesetzes zulässig, z. B. der Strafprozessordnung."],"schutzziel":"Verstehen, dass selbst die höchsten Rechtsgüter unter klaren gesetzlichen Voraussetzungen eingeschränkt werden dürfen – nicht durch Willkür.","kennwerte":[{"l":"Recht auf Leben","v":"Art. 2 GG · Menschenrecht"},{"l":"Eingriff Leben","v":"nur per Gesetz, z. B. § 32 StGB"},{"l":"Freiheit","v":"körperliche Bewegungsfreiheit"},{"l":"Eingriff Freiheit","v":"nur per Gesetz, z. B. StPO"}],"begriffe":["Notwehr (§ 32 StGB) = erlaubte Verteidigung gegen einen gegenwärtigen rechtswidrigen Angriff.","Freiheitsentziehung = Eingriff in die körperliche Bewegungsfreiheit."],"abgrenzung":["Eingriffe in die Freiheit der Person dürfen NICHT nur durch Hoheitsträger erfolgen – auch ein Bürger darf festnehmen (§ 127 StPO).","Das Recht auf Leben ist kein Bürgerrecht – es steht allen Menschen zu, nicht nur Deutschen."],"praxis":["Eine vorläufige Festnahme greift in die Freiheit der Person ein – sie braucht die gesetzliche Grundlage des § 127 StPO.","Wer in Notwehr handelt, greift gerechtfertigt in Rechtsgüter des Angreifers ein."]},"visual":null}],"quiz":[{"q":"Welche Aussagen zur Menschenwürde sind gemäß Art. 1 Grundgesetz richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Geschützt sind ebenso juristische Personen und die Menschheit","c":false},{"t":"Durch die Menschenwürde sind nur die höchsten Grundrechte Recht auf Leben und Recht auf körperliche Unversehrtheit geschützt","c":false},{"t":"Geschützt ist jeder Mensch, der sich im Geltungsbereich des GG aufhält, z. B. minderjährige Kinder, Straftäter und Ausländer","c":true},{"t":"Der Staat ist verpflichtet, die Menschenwürde zu achten und zu schützen","c":true}]},{"q":"Welche Aussagen zum Grundrecht auf Leben sind gemäß Grundgesetz richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"In dieses Grundrecht darf nicht eingegriffen werden, weil es eines der höchsten Rechtsgüter des Menschen ist","c":false},{"t":"In das Grundrecht auf Leben kann aufgrund eines Gesetzes eingegriffen werden, z. B. durch Notwehr gemäß § 32 StGB","c":true},{"t":"Das Recht auf Leben ist ein Bürgerrecht und steht deshalb nur deutschen Staatsbürgern zu","c":false},{"t":"Es ist ein Menschenrecht, das für alle Menschen gilt, die sich auf dem Staatsgebiet der BRD aufhalten","c":true}]},{"q":"Im Grundgesetz steht, dass die Freiheit der Person unverletzlich ist. Welche Aussagen dazu sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Dieses Grundrecht erlaubt es jeder Person, jeden beliebigen Ort in Deutschland aufzusuchen","c":false},{"t":"In der Regel ist bei jeder natürlichen Person deren körperliche Bewegungsfreiheit geschützt","c":true},{"t":"Eingriffe in die Freiheit der Person dürfen nur durch Hoheitsträger wie die Polizei vorgenommen werden","c":false},{"t":"Eingriffe in die Freiheit der Person sind nur aufgrund eines Gesetzes zulässig, z. B. der StPO","c":true}]},{"q":"Was besagen die Gleichheitsgrundsätze gemäß Art. 3 Grundgesetz?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Gleichberechtigung zwischen Mann und Frau kann durch Gesetze eingeschränkt werden","c":false},{"t":"Ein generelles Nachtarbeitsverbot für Frauen ist mit den Gleichheitsgrundsätzen vereinbar","c":false},{"t":"Alle Menschen sind vor dem Gesetz gleich","c":true},{"t":"Männer und Frauen sind gleichberechtigt","c":true}]},{"q":"Welche Aussagen zum Grundgesetz sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Das Grundgesetz enthält die Grundrechte und legt die Struktur des Staates fest","c":true},{"t":"Das Grundgesetz ist nur für das öffentliche Recht verbindlich und gilt ausschließlich für deutsche Staatsbürger","c":false},{"t":"Das Grundgesetz ist die einzig gültige Verfassung der BRD und setzt die Länderverfassungen der 16 Bundesländer außer Kraft","c":false},{"t":"Das Grundgesetz ist die Verfassung für die Bundesrepublik Deutschland","c":true}]},{"q":"Welches Grundrecht des Grundgesetzes ist ein Bürgerrecht?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Berufsfreiheit","c":true},{"t":"Unverletzlichkeit der Wohnung","c":false},{"t":"Recht auf körperliche Unversehrtheit","c":false},{"t":"Freiheit der Person","c":false}]},{"q":"Welche Grundrechte des Grundgesetzes sind Bürgerrechte?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Schutz der Menschenwürde","c":false},{"t":"Freie Berufswahl","c":true},{"t":"Gleichheit vor dem Gesetz","c":false},{"t":"Versammlungsfreiheit","c":true}]},{"q":"Welche nachfolgenden Aussagen zu den Grundrechten im deutschen Grundgesetz (GG) sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Menschenrechte sind Grundrechte. Sie gelten für alle Menschen, die sich in Deutschland aufhalten, also auch für Flüchtlinge und Touristen","c":true},{"t":"Jeder kann sich auf die Gleichbehandlung vor dem Gesetz berufen","c":true},{"t":"Die Grundrechte des deutschen GG gelten weltweit für alle Deutschen, auch wenn sie sich im Ausland aufhalten","c":false},{"t":"Alle Grundrechte können durch Gesetze oder Rechtsverordnungen eingeschränkt werden","c":false}]},{"q":"Welche Aussagen zu den Menschenrechten sind gemäß Grundgesetz richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sie gelten für alle Menschen in Deutschland, unabhängig von ihrer Staatsangehörigkeit","c":true},{"t":"Sie sind Abwehrrechte gegen staatliche Willkürmaßnahmen","c":true},{"t":"Sie gelten weltweit für Bürger mit deutscher Staatsangehörigkeit","c":false}]},{"q":"Welche Aussagen zu den Menschenrechten sind gemäß Grundgesetz richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sie gelten für alle Menschen in Deutschland, unabhängig von ihrer Staatsangehörigkeit","c":true},{"t":"Sie gelten weltweit für Bürger mit deutscher Staatsangehörigkeit","c":false},{"t":"Sie sind Abwehrrechte gegen staatliche Willkürmaßnahmen","c":true}]},{"q":"Welche der folgenden Rechte ist ein Grundrecht?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Recht auf Strafverfolgung","c":false},{"t":"Gleichheit vor dem Gesetz","c":true},{"t":"Bürgerliches Recht","c":false},{"t":"Unverletzlichkeit der Wohnung","c":true}]},{"q":"Definiere den Begriff Ewigkeitsklausel","a":"Bedeutet, dass die Artikel 1 und 20 (Verfassungsprinzipien) nicht verändert werden dürfen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"In welches Grundrecht darf niemals eingegriffen werden?","a":"Artikel 1 In die Würde des Menschen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wo sind die Grundrechte Verankert? Nennen Sie 5 Grundrechte.","a":"Grundrechte sind im Grundgesetz Art. 1 – 19 verankert. - Würde des Menschen - Unverletzlichkeit der Wohnung - Eigentum - Meinungsfreiheit - Berufsfreiheit","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Worin besteht die praktische Bedeutung der Grundrechte für die","a":"Tätigkeit des Sicherheitsmitarbeiters? Die Grundrechte dürfen nicht verletzt werden, dürfen aber in Ausnahmefällen durch Gesetze eingeschränkt werden; z.B. § 127 (1) StPO","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Artikel im Grundgesetz beinhalten die Grundrechte?","a":"Die Artikel 1 bis 19","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"In welche Bereiche / Kategorien teilen sich die Grundrechte und warum?","a":"Menschenrechte= gilt für alle Menschen, im Staatsgebiet der Bundesrepublik Deutschland Bürgerrechte= gilt nur für deutsche Staatsangehörige, im Staatsgebiet der Bundesrepublik Deutschland","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was haben der Artikel 1 und Artikel 20 des GG gemeinsam?","a":"Sie sind durch die sogenannte Ewigkeitsklausel (Artikel 79 GG) geschütztund somit unveränderbar","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Aufgabe haben die Grundrechte?","a":"Sie sollen die Bürger vor staatlicher Willkür schützen. Sie sollen in Drittwirkung die Bürger untereinander schützen. Sie benennen eindeutig verschiedene geschützte Rechtsgüterwie: Leben, Gesundheit, Freiheit, Eigentum","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist mit Hierarchie der Gesetze gemeint?","a":"Das Grundgesetzt geht allen anderen Gesetzten vor, danach kommen die allgemeinen Rechtsnormen wie StGB, BGB; dann Verordnungen, Satzungen und das sogenannte Gewohnheitsrecht.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wovor schütz das Grundgesetz?","a":"Es schützt den Bürger vor der Willkür des Staates und vor anderen Bürgern, sogenannte Drittwirkung","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Stehen im Grundgesetzt Artikel oder Paragraphen?","a":"Dort stehen Artikel.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wer darf in der BRD Gesetze erlassen und welche spezielle Reglung trifft das Grundgesetz diesbezüglich??","a":"Nur der Bund (durch den Bundestag + Bundesrat) und die Bundesländer (durch den jeweiligen Landtag) dürfen Gesetze erlassen! Bundesrecht bricht Landesrecht (Artikel 31 GG)- ein Landesgesetz muss also weichen wenn die gleichen Dinge durch ein Bundesgesetz geregelt werden","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Nennen Sie Rechtsquellen – Öffentliches/Privates Recht","a":"Öffentliches Recht: Staatsrecht, Strafrecht, Sozialrecht Privates Recht: Bürgerliches Recht, Arbeitsrecht, Handelsrecht","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie unterscheiden sich Menschenrecht von den Bürgerrechtern?","a":"Menschenrechte stehen allen Menschen zu, Bürgerrechte stehen allen Deutschen Staatsbürgern zu.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie bitte jeweils drei Beispiele.","a":"Menschenrechte: - Art. 1: Die Menschenwürde ist unantastbar - Art. 2: Recht auf freie Entfaltung der Person, Recht auf Leben, Recht auf körperliche Unversehrtheit, Recht auf Freiheit - Art. 3: Alle Menschen sind gleich - Art. 4: Freiheit des Glaubens Bürgerrechte: - Art. 8: Versammlungsfreiheit - Art. 9: Vereinigungsfreiheit und Koalitionsfreiheit - Art.11: Recht auf Freizügigkeit im gesamten Bundesgebiet - Art. 12: Recht auf freie Wahl von Beruf, Arbeitsplatz und Ausbildungsstätte - Art. 38 Abs. 1: Die Wahlrechtsgrundsätze","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[]},{"n":4,"title":"Öffentliches & privates Recht","subtitle":"3 Konzepte · 8 Prüfungsfragen","cards":[{"h":"Prinzip der Rechtsordnung","b":"Unterscheidung öffentliches / privates Recht","detail":{"titel":"Die Zweiteilung der Rechtsordnung","kat":"ROSO · Rechtsgebiete","katCls":"recht","merksatz":"Die deutsche Rechtsordnung teilt sich in zwei große Gebiete: öffentliches Recht und privates Recht. Das öffentliche Recht regelt das Verhältnis Staat–Bürger nach dem Über- und Unterordnungsprinzip (Subordinationsprinzip); das private Recht regelt das Verhältnis Bürger–Bürger nach dem Koordinationsprinzip.","funktion":["Öffentliches Recht: Staat gegen Bürger – der Staat ist übergeordnet (Subordinationsprinzip).","Privates Recht (Zivilrecht, bürgerliches Recht): Bürger gegen Bürger – beide Parteien sind gleichgeordnet (Koordinationsprinzip).","Im Zivilprozess unterscheidet man Kläger und Beklagten; das Strafgericht verhängt Geld- oder Freiheitsstrafen.","Diese Einteilung hat hohe Prüfungsrelevanz und ist Grundlage für BGB, StGB und StPO."],"schutzziel":"Jede Situation richtig einordnen können: Geht es um Staat–Bürger (öffentlich) oder Bürger–Bürger (privat)?","kennwerte":[{"l":"Gebiet 1","v":"öffentliches Recht"},{"l":"Gebiet 2","v":"privates Recht (Zivilrecht)"},{"l":"Öffentlich","v":"Über-/Unterordnung (Subordination)"},{"l":"Privat","v":"Gleichordnung (Koordination)"}],"begriffe":["Subordinationsprinzip = Über- und Unterordnung zwischen Staat und Bürger.","Koordinationsprinzip = Gleichordnung zwischen Bürger und Bürger."],"abgrenzung":["Die Rechtsordnung wird in privates und öffentliches Recht eingeteilt – ‚Bürgerrechte' oder ‚Hoheitsrecht' sind keine eigenen Hauptgebiete.","Im öffentlichen Recht sind Staat und Bürger NICHT gleichberechtigt – der Staat ist übergeordnet."],"praxis":["Eine Strafe oder ein Bußgeld kommt aus dem öffentlichen Recht (Staat handelt hoheitlich).","Ein Streit um Schadensersatz zwischen zwei Personen ist privates Recht."]},"visual":null},{"h":"Subordination vs. Koordination","b":"Öff. Recht „Staat gegen Bürger“ (Über-/Unterordnung); priv. Recht „Bürger gegen Bürger“ (Gleichstellung)","detail":{"titel":"Das Privatrecht (Bürgerliches Recht)","kat":"ROSO · Rechtsgebiete","katCls":"recht","merksatz":"Das Privatrecht – auch bürgerliches Recht oder Zivilrecht genannt – regelt die Rechtsbeziehungen der Bürger untereinander. Dazu gehören u. a. das Sachenrecht und das Schikaneverbot. Streitigkeiten entscheidet ein Zivilgericht zwischen Kläger und Beklagtem.","funktion":["Das Privatrecht regelt die Verhältnisse zwischen Bürgern.","Es regelt die Folgen, wenn ein Bürger von einem anderen Schadensersatz fordert.","Zum Privatrecht gehören u. a. das Sachenrecht und das Schikaneverbot.","Es gilt das Koordinationsprinzip – die Parteien sind gleichgeordnet."],"schutzziel":"Das Zivilrecht vom öffentlichen Recht abgrenzen und typische Inhalte erkennen.","kennwerte":[{"l":"Andere Namen","v":"Zivilrecht, bürgerliches Recht"},{"l":"Regelt","v":"Bürger ↔ Bürger"},{"l":"Beispiele","v":"Sachenrecht, Schikaneverbot"},{"l":"Verfahren","v":"Kläger gegen Beklagten"}],"begriffe":["Sachenrecht = Regeln über Eigentum und Besitz an Sachen.","Schikaneverbot = Verbot, ein Recht nur zum Schaden anderer auszuüben."],"abgrenzung":["Das Privatrecht regelt NICHT das Verhältnis Bürger–Staat und NICHT die Folgen einer Straftat (das ist öffentliches Recht / Strafrecht).","Schadensersatz ist privates Recht; eine Strafe ist öffentliches Recht."],"praxis":["Beschädigt ein Gast Inventar, kann der Betreiber zivilrechtlich Schadensersatz verlangen.","Übertragene Besitz- und Selbsthilferechte (z. B. Hausrecht) stammen aus dem Privatrecht."]},"visual":null},{"h":"Rechtsquellen","b":"Öff.: Staats-, Straf-, Sozialrecht; priv.: Bürgerl., Arbeits-, Handelsrecht","detail":{"titel":"Strafrecht als öffentliches Recht","kat":"ROSO · Rechtsgebiete","katCls":"recht","merksatz":"Das Strafrecht zählt zum öffentlichen Recht: Der Staat verfolgt und bestraft Straftaten. Im Strafrecht geregelt sind unter anderem die Stellung des Strafantrags und die Schuldunfähigkeit des Kindes.","funktion":["Das Strafrecht gehört zum öffentlichen Recht – der Staat steht dem Bürger übergeordnet gegenüber.","Geregelt ist u. a. die Stellung des Strafantrags.","Geregelt ist u. a. die Schuldunfähigkeit des Kindes (strafunmündig unter 14).","Der Staat (Staatsanwaltschaft, Gericht) betreibt die Strafverfolgung."],"schutzziel":"Das Strafrecht eindeutig dem öffentlichen Recht zuordnen und seine typischen Regelungen von privatrechtlichen trennen.","kennwerte":[{"l":"Zugehörigkeit","v":"öffentliches Recht"},{"l":"Akteur","v":"Staat verfolgt und bestraft"},{"l":"Beispiel 1","v":"Stellung des Strafantrags"},{"l":"Beispiel 2","v":"Schuldunfähigkeit des Kindes"}],"begriffe":["Strafantrag = Erklärung des Verletzten, dass die Verfolgung einer Tat gewünscht ist.","Schuldunfähigkeit des Kindes = wer noch nicht 14 ist, handelt schuldlos."],"abgrenzung":["NICHT im Strafrecht geregelt: der Angriffsnotstand (§ 904 BGB), Besitzschutzrechte und die Pflicht zum Schadensersatz – das ist BGB (privat).","Die Strafe ist eine öffentlich-rechtliche Sanktion, kein zivilrechtlicher Ausgleich."],"praxis":["Erstattet ein Geschädigter Strafanzeige und stellt Strafantrag, läuft das im öffentlichen Recht.","Ein 12-Jähriger kann nicht bestraft werden (Schuldunfähigkeit) – zivilrechtliche Haftung ist davon getrennt."]},"visual":null},{"h":"Staatsanwaltschaft & Opportunitätsprinzip","b":"Behörde der Rechtspflege; leitet das Ermittlungsverfahren und erhebt Anklage. Opportunitätsprinzip = Einstellung bei geringer Schuld nach Ermessen","detail":{"titel":"Die Staatsanwaltschaft & das Opportunitätsprinzip","kat":"ROSO · Justiz","katCls":"recht","merksatz":"Die Staatsanwaltschaft ist Teil der Rechtspflege und als Behörde für die Strafverfolgung zuständig. Ihr obliegen die Leitung des Ermittlungsverfahrens und die Erhebung der Anklage beim Strafgericht. Das Opportunitätsprinzip erlaubt ihr, ein Verfahren bei geringer Schuld nach Ermessen einzustellen.","funktion":["Die Staatsanwaltschaft ist Teil der Rechtspflege und Behörde der Strafverfolgung.","Sie leitet und lenkt das Ermittlungsverfahren.","Sie erhebt die Anklage beim Strafgericht.","Opportunitätsprinzip: Einstellung des Strafverfahrens bei geringer Schuld nach Ermessensgebrauch."],"schutzziel":"Die Rolle der Staatsanwaltschaft im Strafverfahren kennen und vom Gericht und der Polizei abgrenzen.","kennwerte":[{"l":"Einordnung","v":"Teil der Rechtspflege"},{"l":"Aufgabe 1","v":"Leitung des Ermittlungsverfahrens"},{"l":"Aufgabe 2","v":"Erhebung der Anklage"},{"l":"Opportunität","v":"Einstellung bei geringer Schuld"}],"begriffe":["Ermittlungsverfahren = die staatsanwaltschaftliche Untersuchung vor der Anklage.","Opportunitätsprinzip = Verfolgung/Einstellung nach pflichtgemäßem Ermessen."],"abgrenzung":["Die Staatsanwaltschaft erlässt KEINE Haftbefehle – das macht der Richter.","Sie ist NICHT für zivilrechtliche Ermittlungen und NICHT als ‚oberste Polizeibehörde' zuständig."],"praxis":["Nach einer Anzeige leitet die Staatsanwaltschaft das Ermittlungsverfahren und entscheidet über Anklage oder Einstellung.","Bei Bagatellen kann das Verfahren nach dem Opportunitätsprinzip eingestellt werden."]},"visual":null},{"h":"Zuständigkeit der Polizei","b":"Grundsätzlich im öffentlichen Bereich; im privaten Bereich nur mit Durchsuchungsbefehl oder bei Gefahr im Verzug","detail":{"titel":"Die Polizei – Zuständigkeitsbereich","kat":"ROSO · Justiz","katCls":"recht","merksatz":"Die Polizei ist grundsätzlich im öffentlichen Bereich zuständig. Im privaten Bereich darf sie nur unter besonderen Voraussetzungen tätig werden – etwa mit einem Durchsuchungsbefehl oder bei Gefahr im Verzug. Sie ist grundsätzlich Sache der Bundesländer.","funktion":["Grundsätzlich ist die Polizei im öffentlichen Bereich zuständig.","Im privaten Bereich nur mit Durchsuchungsbefehl oder bei Gefahr im Verzug.","Die Polizei ist grundsätzlich Sache der Bundesländer.","Sie ist von Amts wegen zur Strafverfolgung und Entgegennahme von Anzeigen verpflichtet."],"schutzziel":"Verstehen, wo die staatliche Polizei agiert – und damit die Grenze zur privaten Sicherheit klar ziehen.","kennwerte":[{"l":"Grundsatz","v":"öffentlicher Bereich"},{"l":"Privat","v":"nur mit Beschluss / Gefahr im Verzug"},{"l":"Träger","v":"grundsätzlich Ländersache"},{"l":"Pflicht","v":"Strafverfolgung von Amts wegen"}],"begriffe":["Gefahr im Verzug = sofortiges Handeln nötig, kein Zeitaufschub für einen Beschluss.","Durchsuchungsbefehl = richterliche Anordnung zur Durchsuchung."],"abgrenzung":["Die Polizei ist NICHT ‚immer in allen Bereichen' und NICHT ‚nur im öffentlichen Bereich' zuständig – im Privaten gilt: mit Beschluss oder bei Gefahr im Verzug.","Die Polizei ist NICHT ausschließlich Sache des Bundes – sie ist grundsätzlich Ländersache."],"praxis":["Ohne Durchsuchungsbeschluss darf die Polizei eine Privatwohnung nur bei Gefahr im Verzug betreten.","Im öffentlichen Verkehrsraum agiert die Polizei, private Sicherheit nur auf privatrechtlicher Grundlage."]},"visual":null}],"quiz":[{"q":"In welche Rechtsgebiete wird die deutsche Rechtsordnung grundsätzlich eingeteilt?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Bürgerrechte","c":false},{"t":"Privates Recht","c":true},{"t":"Öffentliches Recht","c":true},{"t":"Hoheitsrecht","c":false}]},{"q":"Was kennzeichnet das öffentliche Recht?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Das Prinzip der Über- und Unterordnung zwischen Staat und Bürger","c":true},{"t":"Das Prinzip der Über- und Unterordnung zwischen Bürger und Bürger","c":false},{"t":"Das Prinzip der Gleichordnung zwischen Staat und Bürger","c":false},{"t":"Das Prinzip der Gleichordnung zwischen Bürger und Bürger","c":false}]},{"q":"Was regelt das Privatrecht (bürgerliches Recht)?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Es regelt Verhältnisse zwischen Bürgern","c":true},{"t":"Es regelt das rechtliche Verhältnis zwischen Bürger und Staat","c":false},{"t":"Es regelt die Folgen, wenn ein Bürger eine Straftat begeht","c":false},{"t":"Es regelt die Folgen, wenn ein Bürger von einem anderen Schadensersatz fordert","c":true}]},{"q":"Wie ist das rechtliche Verhältnis zwischen Staat und Bürger im Öffentlichen Recht?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Beide Seiten sind gleichberechtigt","c":false},{"t":"Der Bürger hat keine Rechte","c":false},{"t":"Der Staat ist übergeordnet","c":true},{"t":"Es kommt auf den Einzelfall an","c":false}]},{"q":"Was ist im Strafrecht, das zum öffentlichen Recht zählt, geregelt?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Der Angriffsnotstand","c":false},{"t":"Die Anwendung von Besitzschutzrechten","c":false},{"t":"Die Stellung des Strafantrages","c":true},{"t":"Die Pflicht zum Schadensersatz","c":false},{"t":"Die Schuldunfähigkeit des Kindes","c":true}]},{"q":"Welche Aufgabe hat die Staatsanwaltschaft?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Der Staatsanwaltschaft obliegen die Ermittlungen in zivilrechtlichen Angelegenheiten, insbesondere bei unerlaubten Handlungen","c":false},{"t":"Die Staatsanwaltschaft ist Teil der Rechtspflege und als Behörde für die Strafverfolgung zuständig","c":true},{"t":"Die Staatsanwaltschaft ist als oberste Polizeibehörde zuständig für die Verfolgung von Straftaten und Schadensersatzpflichten","c":false},{"t":"Der Staatsanwaltschaft obliegen die Leitung des Ermittlungsverfahrens sowie die Erhebung der Anklage beim Strafgericht","c":true}]},{"q":"Welche Aufgaben hat die Staatsanwaltschaft?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Leitung des Strafverfahrens","c":false},{"t":"Erlass von Haftbefehlen","c":false},{"t":"Lenkung des Ermittlungsverfahrens","c":true},{"t":"Erhebung der Anklage","c":true}]},{"q":"In welchem Bereich ist die Polizei zuständig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Grundsätzlich im öffentlichen Bereich","c":true},{"t":"Im privaten Bereich z. B. mit Durchsuchungsbefehl oder bei Gefahr im Verzug","c":true},{"t":"Immer in allen Bereichen","c":false},{"t":"Nur im öffentlichen Bereich","c":false}]},{"q":"Was ermöglicht das „Opportunitätsprinzip“?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Einstellung des Strafverfahrens bei geringer Schuld nach Ermessensgebrauch durch die Staatsanwaltschaft","c":true},{"t":"Verbindliche Vorladung von Zeugen durch die Staatsanwaltschaft im Gerichtsverfahren","c":false},{"t":"Eröffnung des Hauptverfahrens ohne Teilnahme der Staatsanwaltschaft auf dem Privatklageweg","c":false},{"t":"Besondere Einstellung des Strafverfahrens durch die Staatsanwaltschaft bei Tötungsdelikten","c":false}]},{"q":"Was besagt das Prinzip der Rechtsordnung ?","a":"Unterscheidung in Öffentliches und privates Recht.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welches Prinzip herrscht im öffentlichen - und privaten Recht?","a":"Im öffentlichen Recht: Staat gegen Bürger (Über-Unterordnungsprinzip) und im privaten Recht: Bürger gegen Bürger (Gleichstellungsprinzip)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Definiere den Begriff Ewigkeitsklausel","a":"Bedeutet, dass die Artikel 1 und 20 (Verfassungsprinzipien) nicht verändert werden dürfen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nenne die 5 Verfassungsprinzipien, Artikel 20 GG","a":"- Rechtsstaatsprinzip (Keine Strafe ohne Gesetz) - Demokratie (Alle Macht geht vom Volke aus) - Sozialstaatsprinzip (Augleich zwischen Arm und Reich) - Bundesstaatsprinzip (Föderalismus) - Republik (Staatsoberhaupt wird auf Zeit gewählt)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Das deutsche Rechtssystem teilt sich in zwei Rechtsgebiete, welche sind das und warum sind sie geteilt?","a":"Öffentliches Recht- hier stehen sich Staat und Bürger gegenüber- der Staat ist hier dem Bürger übergeordnet- es gilt das Über-/Unterordnungsprinzip (Subordinationsprinzip) Privates /Ziviles Recht- hier stehen sich Bürger und Bürger gegenüber- Bürger sind zueinander gleichgestellt- es gilt das Gleichordnungsprinzip (Koordinationsprinzip)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wer ist im öffentlichen Recht, wer im privaten Recht zuständig?","a":"Im öffentlichen Recht der Staat (Polizei) und im privaten Recht Sicherheits- unternehmen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre das PPP Modell? Was ist eine sogenannte Beleihung?","a":"Public-private-Partnership = Zusammenarbeit zwischen Polizei und Sicherheitsunternehmen zur Stärkung der öffentlichen Sicherheit. Hoheitliche Rechte können beliehen werden für die Arbeit an Flughafen, Atomkraftwerken und Bundeswehrflächen (z.B. LSichG, UzwG)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie Rechtsquellen – Öffentliches/Privates Recht","a":"Öffentliches Recht: Staatsrecht, Strafrecht, Sozialrecht Privates Recht: Bürgerliches Recht, Arbeitsrecht, Handelsrecht","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[]},{"n":5,"title":"Gewaltmonopol & Rechte der SMA","subtitle":"8 Konzepte · 22 Prüfungsfragen","cards":[{"h":"Gewaltmonopol des Staates","b":"Nur Staat darf physische Gewalt auf Grundlage einer Rechtsnorm ausüben","detail":{"titel":"Das staatliche Gewaltmonopol","kat":"ROSO · Gewaltmonopol","katCls":"recht","merksatz":"Das Gewaltmonopol liegt allein beim Staat: Grundsätzlich dürfen nur staatliche Organe wie die Polizei Gewalt anwenden. Gewalt bedeutet die Ausübung von unmittelbarem, physischem Zwang. Die Anwendung staatlicher Gewalt ist nur unter engen gesetzlichen Voraussetzungen zulässig – niemals willkürlich.","funktion":["Monopol bedeutet ‚allein' – nur der Staat darf grundsätzlich Gewalt anwenden.","Gewalt = unmittelbarer, physischer Zwang: Einwirkung auf Personen oder Sachen mit körperlicher Gewalt.","Staatliche Gewalt ist nur unter engen gesetzlichen Voraussetzungen zulässig.","Ausnahmen für den Bürger sind die Rechtfertigungsgründe / Jedermannsrechte."],"schutzziel":"Das Fundament des Themengebiets verstehen: Warum private Sicherheit grundsätzlich keine Zwangsbefugnisse hat.","kennwerte":[{"l":"Monopol","v":"allein der Staat"},{"l":"Gewalt","v":"unmittelbarer physischer Zwang"},{"l":"Voraussetzung","v":"enge gesetzliche Grenzen"},{"l":"Ausnahme","v":"Rechtfertigungsgründe / Jedermannsrechte"}],"begriffe":["Gewaltmonopol = das alleinige Recht des Staates, Zwang auszuüben.","Physischer Zwang = körperliche Einwirkung, auch mit Waffen oder Werkzeugen."],"abgrenzung":["Der Staat darf NICHT willkürlich Gewalt anwenden – nur unter gesetzlichen Voraussetzungen.","Der Bürger darf NICHT ‚in keiner Situation' Gewalt anwenden – die Jedermannsrechte sind die Ausnahme."],"praxis":["Eine körperliche Durchsuchung ohne Zustimmung ist physischer Zwang – grundsätzlich dem Staat vorbehalten.","Ist der Staat nicht vor Ort, darf der Bürger ausnahmsweise über die Rechtfertigungsgründe handeln."]},"visual":null},{"h":"Hoheitliche Rechte","b":"Beschlagnahme, Durchsuchung, Zwangspfändung – nur staatliche Stellen","detail":{"titel":"Hoheitliche Rechte","kat":"ROSO · Gewaltmonopol","katCls":"recht","merksatz":"Hoheitliche Rechte sind Rechte, die nur der Staat hat. Auf sie können z. B. Polizei, Zoll und Staatsanwaltschaft zurückgreifen – etwa für die Durchsuchung einer Wohnung oder die Sicherstellung und Beschlagnahme von Beweismitteln. Private Sicherheitsmitarbeiter haben keine hoheitlichen Rechte.","funktion":["Hoheitliche Rechte stehen nur dem Staat zu (Polizei, Zoll, Staatsanwaltschaft).","Beispiele: Wohnungsdurchsuchung durch Polizei, Sicherstellung/Beschlagnahme durch den Staatsanwalt.","Sicherheitsmitarbeiter haben KEINE hoheitlichen Rechte – auch nicht ‚in Notfällen' oder ‚regelmäßig im Dienst'.","Grundsätzlich können private Unternehmen keine hoheitlichen Aufgaben erfüllen."],"schutzziel":"Klar trennen, was hoheitlich (nur Staat) und was jedermann erlaubt ist – die häufigste Verwechslung im Themengebiet.","kennwerte":[{"l":"Inhaber","v":"nur der Staat"},{"l":"Typische Träger","v":"Polizei, Zoll, Staatsanwalt"},{"l":"Beispiele","v":"Durchsuchung, Beschlagnahme"},{"l":"SMA","v":"keine hoheitlichen Rechte"}],"begriffe":["Hoheitlich = mit staatlicher Befehls- und Zwangsgewalt ausgestattet.","Beschlagnahme = behördliche Sicherstellung von Beweismitteln."],"abgrenzung":["Die freiwillige Kontrolle eines Rucksacks mit Einwilligung ist KEIN hoheitliches Recht.","Die freiwillige Befragung eines Täters durch eine Wachperson ist KEIN hoheitliches Handeln."],"praxis":["Eine Wachperson darf nicht gegen den Willen durchsuchen – das wäre hoheitlicher Zwang.","Eine Beschlagnahme von ‚Diebesgut' steht dem SMA nicht zu – nur dem Staat."]},"visual":null},{"h":"SMA haben KEINE hoheitlichen Rechte","b":"Keine Beamten/Polizisten; nur Jedermanns- und Selbsthilferechte","detail":{"titel":"Beleihung hoheitlicher Rechte","kat":"ROSO · Private Sicherheit","katCls":"recht","merksatz":"Bei der Beleihung überträgt der Staat per Gesetz einen Teil seiner hoheitlichen Macht auf ein privates Unternehmen. Bekanntes Beispiel sind die Sicherheitskontrollen am Flughafen: Private Firmen führen sie durch, die Aufsicht und das Sagen bleiben aber beim Staat (Bundespolizei).","funktion":["Beleihung = Übertragung hoheitlicher Rechte auf private Unternehmen durch Gesetz.","Beispiel: Luftsicherheitskontrollen am Flughafen durch private Firmen.","Die Aufsicht bleibt beim Staat – die private Firma erledigt nur die Aufgabe.","Beliehene handeln auf Basis ‚gesetzlich übertragener Rechte aufgrund einer Beleihung'."],"schutzziel":"Die einzige Konstellation kennen, in der private Sicherheit ausnahmsweise hoheitlich tätig werden darf.","kennwerte":[{"l":"Beleihung","v":"Übertragung hoheitlicher Rechte"},{"l":"Grundlage","v":"Gesetz"},{"l":"Beispiel","v":"Luftsicherheit am Flughafen"},{"l":"Aufsicht","v":"bleibt beim Staat"}],"begriffe":["Beleihung = gesetzliche Übertragung hoheitlicher Befugnisse auf Private.","Beliehener = privates Unternehmen, das hoheitliche Aufgaben wahrnimmt."],"abgrenzung":["Ohne Beleihung haben SMA keine hoheitlichen Rechte – die Beleihung ist die gesetzliche Ausnahme.","Beleihung (mit Rechteübertragung) ist NICHT dasselbe wie Public Private Partnership (ohne Rechteübertragung)."],"praxis":["Die Fluggastkontrolle führt eine private Firma durch – die Bundespolizei hat die Aufsicht.","Antwortoption in der Prüfung: ‚gesetzlich übertragene Rechte aufgrund einer Beleihung'."]},"visual":null},{"h":"Die 8 Rechtfertigungsgründe","b":"6 Jedermannsrechte (Notwehr §32/§227, §34, §228, §904, §127 StPO) + 2 übertragbare Selbsthilferechte (§229, §859)","detail":{"titel":"Public Private Partnership (PPP)","kat":"ROSO · Private Sicherheit","katCls":"recht","merksatz":"Bei der Public Private Partnership arbeiten private Sicherheitsfirmen und öffentliche Behörden (z. B. Polizei, Ordnungsamt) partnerschaftlich zusammen – aber OHNE Übertragung hoheitlicher Rechte. Es geht meist nur um Informations- und Erfahrungsaustausch und Hilfeleistung.","funktion":["PPP = partnerschaftliche Zusammenarbeit von Behörden und privaten Sicherheitsdiensten.","Es werden KEINE hoheitlichen Rechte übertragen – anders als bei der Beleihung.","Typisch: gegenseitiger Informations- und Erfahrungsaustausch, Hilfeleistung.","PPP-Kooperationen sind regional sehr unterschiedlich und uneinheitlich geregelt."],"schutzziel":"PPP klar von der Beleihung trennen: Zusammenarbeit ja, Hoheitsrechte nein.","kennwerte":[{"l":"PPP","v":"Zusammenarbeit Staat + Private"},{"l":"Hoheitsrechte","v":"werden NICHT übertragen"},{"l":"Inhalt","v":"Info-/Erfahrungsaustausch, Hilfe"},{"l":"Regelung","v":"regional uneinheitlich"}],"begriffe":["Public Private Partnership = Kooperation zwischen öffentlicher Hand und Privaten.","Kooperation = Zusammenarbeit ohne Übertragung von Befugnissen."],"abgrenzung":["Bei der PPP wird die Polizei NICHT durch private Sicherheitsdienste ersetzt.","PPP verleiht KEINE besonderen hoheitlichen Befugnisse ohne staatliche Aufsicht."],"praxis":["Bei einem Großevent sitzen Firma, Ordnungsamt und Polizei zusammen und tauschen Lageinfos aus – PPP.","Denkbar sind Verkehrslenkung im Einzelfall sowie Hilfeleistung bei Sach- und Personenfahndungen."]},"visual":null},{"h":"Jedermannsrechte","b":"Rechte für jeden in Ausnahmesituationen, wenn staatliche Hilfe fehlt","detail":{"titel":"Jedermannsrechte & Rechtfertigungsgründe","kat":"ROSO · Private Sicherheit","katCls":"recht","merksatz":"Jedermannsrechte sind Rechte, die JEDER Bürger hat: Notwehr und Nothilfe (§ 32 StGB), der rechtfertigende Notstand, das vorläufige Festnahmerecht (§ 127 StPO) und die allgemeine Selbsthilfe (§ 229 BGB). Rechtfertigungsgründe können unerlaubtes bzw. strafbares Handeln rechtfertigen.","funktion":["Jedermannsrechte stehen jedem Bürger zu – auf sie stützt sich auch der SMA.","Dazu zählen: Notwehr/Nothilfe (§ 32 StGB), rechtfertigender Notstand, vorläufige Festnahme (§ 127 StPO), allgemeine Selbsthilfe (§ 229 BGB).","Rechtfertigungsgründe rechtfertigen unerlaubtes/strafbares Handeln (sie ‚entschuldigen' nicht).","Das Hausrecht ist KEIN Jedermannsrecht – es gehört dem Hausrechtsinhaber."],"schutzziel":"Die rechtliche Grundlage des Einschreitens kennen: Worauf darf sich ein Sicherheitsmitarbeiter tatsächlich berufen?","kennwerte":[{"l":"Jedermannsrechte","v":"für jeden Bürger"},{"l":"Beispiele","v":"Notwehr, Notstand, § 127 StPO, § 229 BGB"},{"l":"Funktion","v":"rechtfertigen strafbares/unerlaubtes Handeln"},{"l":"Kein Jedermannsrecht","v":"Hausrecht"}],"begriffe":["Notwehr (§ 32 StGB) = Verteidigung gegen einen gegenwärtigen rechtswidrigen Angriff.","Vorläufige Festnahme (§ 127 StPO) = Festhalten eines auf frischer Tat Betroffenen."],"abgrenzung":["Das Hausrecht besitzt nicht ‚jedermann', sondern der Hausrechtsinhaber – es kann jedoch übertragen werden.","Rechtfertigungsgründe ‚entschuldigen' nicht ordnungswidriges oder verbotenes Handeln – sie rechtfertigen es."],"praxis":["Greift ein Gast einen anderen an, darf der SMA über die Nothilfe (§ 32 StGB) einschreiten.","Ertappt ein SMA einen Dieb auf frischer Tat, kann er ihn nach § 127 StPO vorläufig festnehmen."]},"visual":null},{"h":"Übertragbare Selbsthilferechte","b":"Vom Auftraggeber übertragen zum Schutz von Eigentum/Besitz","detail":{"titel":"Rechtsgrundlagen der privaten Sicherheit","kat":"ROSO · Private Sicherheit","katCls":"recht","merksatz":"Private Sicherheitsmitarbeiter werden auf der Grundlage von Jedermannsrechten und Rechtfertigungsgründen sowie vertraglich übertragenen Besitz- und Selbsthilferechten tätig – stets auf privatrechtlicher Basis. Hoheitliche Rechte oder bloße Anweisungen des Auftraggebers begründen KEINE Eingriffsbefugnisse.","funktion":["Grundlage 1: Jedermannsrechte und Rechtfertigungsgründe.","Grundlage 2: vom Auftraggeber vertraglich übertragene Besitz- und Selbsthilferechte (Besitzdienerrechte).","Tätigkeit auf privatrechtlichem Auftragsverhältnis – auch bei Kontrollgängen im öffentlichen Verkehrsraum.","KEINE hoheitlichen Rechte; bloße Anweisungen des Auftraggebers sind keine Eingriffsbefugnis."],"schutzziel":"Die rechtliche Basis der täglichen Arbeit sauber benennen können – und gegen ‚Polizei-Befugnisse' abgrenzen.","kennwerte":[{"l":"Basis 1","v":"Jedermannsrechte / Rechtfertigungsgründe"},{"l":"Basis 2","v":"übertragene Besitz-/Selbsthilferechte"},{"l":"Verhältnis","v":"privatrechtlicher Auftrag"},{"l":"Nicht","v":"hoheitliche Rechte"}],"begriffe":["Besitzdiener = wer den Besitz für einen anderen ausübt (z. B. der SMA für den Auftraggeber).","Selbsthilferecht = Recht, einen Anspruch im Rahmen des Gesetzes selbst zu sichern."],"abgrenzung":["SMA dürfen bei Kontrollgängen im öffentlichen Verkehrsraum NICHT wie die Polizei Platzverweise erteilen oder Bußgelder kassieren.","Eine Anweisung des Auftraggebers schafft keine zusätzlichen Eingriffsrechte gegenüber Dritten."],"praxis":["In Erfüllung des Auftrags nimmt der SMA übertragene Besitz- und Selbsthilferechte wahr.","In Ausnahmesituationen greifen die Notwehr- und Notstandsrechte."]},"visual":null},{"h":"Staatliche Beleihung (PPP)","b":"Einzelne hoheitliche Befugnisse an SMA, z.B. Flughafen, kritische Infrastruktur, Citystreife","detail":{"titel":"Polizei vs. privater Sicherheitsdienst","kat":"ROSO · Private Sicherheit","katCls":"recht","merksatz":"Der entscheidende Unterschied: Gewerbliche Sicherheitsdienste haben KEINE besonderen Eingriffsbefugnisse. Ohne Einverständnis des Betroffenen dürfen sie z. B. keine Durchsuchung oder Beschlagnahme durchführen. Auch eine bestandene IHK-Sachkundeprüfung verleiht keine hoheitlichen Befugnisse.","funktion":["Gewerbliche Sicherheitsdienste haben keine besonderen Eingriffsbefugnisse.","Ohne Einverständnis keine Durchsuchung und keine Beschlagnahme.","Die bestandene Sachkundeprüfung § 34a verleiht KEINE hoheitlichen Befugnisse.","Die Polizei dagegen hat als Staatsorgan hoheitliche Befugnisse."],"schutzziel":"Die Grenze zwischen Polizei (hoheitlich) und privater Sicherheit (Jedermanns-/Vertragsrechte) sicher ziehen.","kennwerte":[{"l":"Sicherheitsdienst","v":"keine Eingriffsbefugnisse"},{"l":"Durchsuchung","v":"nur mit Einverständnis"},{"l":"Sachkundeprüfung","v":"verleiht keine Hoheitsrechte"},{"l":"Polizei","v":"hoheitliche Befugnisse"}],"begriffe":["Eingriffsbefugnis = gesetzliche Erlaubnis, in Rechte Dritter einzugreifen.","Hausrechtsbereich mit öffentlichem Verkehr = z. B. Bahnhofshalle, Einkaufszentrum."],"abgrenzung":["Auch in Hausrechtsbereichen mit öffentlichem Verkehr hat der SMA KEINE hoheitlichen Befugnisse – selbst mit IHK-Prüfung.","Sicherheitsdienste dürfen NICHT ‚nur auf privatem Gelände' und die Polizei NICHT ‚nur im öffentlichen Verkehrsraum' tätig werden – diese Aufteilung ist falsch."],"praxis":["Will der SMA eine Tasche kontrollieren, braucht er das Einverständnis – sonst nicht zulässig.","Bei Widerstand bleibt nur: Jedermannsrechte nutzen und die Polizei rufen."]},"visual":null},{"h":"Abgrenzung Polizei / Bewachungsgewerbe","b":"Polizei = hoheitlich, dem Staat verpflichtet; SMA = Jedermannsrechte, dem Auftraggeber verpflichtet","detail":{"titel":"Befugnisse in der Praxis: der Kaufhausdetektiv","kat":"ROSO · Private Sicherheit","katCls":"recht","merksatz":"Ein Kaufhausdetektiv darf einen auf frischer Tat betroffenen Straftäter, dessen Identität unbekannt ist, bis zum Eintreffen der gerufenen Polizei festhalten (§ 127 StPO). Weitergehende Maßnahmen wie Durchsuchung oder Fesseln stehen ihm grundsätzlich nicht zu.","funktion":["Erlaubt: Festnahme eines auf frischer Tat Betroffenen mit unbekannter Identität bis zur Polizei (§ 127 StPO).","Nicht erlaubt: Durchsuchung der mitgeführten Tasche eines Tatverdächtigen.","Nicht erlaubt: Fesseln des Ladendiebes ‚zur Gewaltprävention'.","Nicht erlaubt: vorläufige Festnahme nur, um ein Hausverbot zu erteilen."],"schutzziel":"Das Gelernte am häufigsten Praxisfall anwenden: Was geht – und was geht zu weit?","kennwerte":[{"l":"Erlaubt","v":"Festnahme nach § 127 StPO"},{"l":"Voraussetzung","v":"frische Tat + unbekannte Identität"},{"l":"Dauer","v":"bis die Polizei eintrifft"},{"l":"Verboten","v":"Durchsuchung, Fesseln, Festnahme für Hausverbot"}],"begriffe":["Auf frischer Tat = während oder unmittelbar nach der Tat betroffen.","Festnahmegrund = Fluchtverdacht oder ungeklärte Identität."],"abgrenzung":["Eine Durchsuchung ist hoheitlicher Zwang – sie steht dem Detektiv nicht zu (nur Einwilligung oder Polizei).","Eine Festnahme ‚zur Erteilung eines Hausverbots' ist unzulässig – das Festnahmerecht dient der Strafverfolgung."],"praxis":["Dieb auf frischer Tat, Name unbekannt, will flüchten: Festhalten nach § 127 StPO und Polizei rufen.","Die Tasche darf nur mit Einwilligung kontrolliert werden – sonst auf die Polizei warten."]},"visual":null}],"quiz":[{"q":"Welche Aussagen zum staatlichen Gewaltmonopol sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Anwendung von Gewalt ist grundsätzlich nur den staatlichen Organen erlaubt","c":true},{"t":"Der Staat darf zur Aufrechterhaltung der öffentlichen Sicherheit und Ordnung willkürlich Gewalt anwenden","c":false},{"t":"Der Bürger darf in keiner Situation Gewalt anwenden","c":false},{"t":"Die Anwendung staatlicher Gewalt ist nur unter engen gesetzlichen Voraussetzungen zulässig","c":true}]},{"q":"Erklären Sie den Begriff „Gewaltmonopol“!","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Der Staat hat das Gewaltmonopol, kann seine Rechte aber voll auf Private übertragen","c":false},{"t":"Gewaltmonopol bedeutet, nur der Chef der Wachfirma hat das Sagen","c":false},{"t":"Private können im Rahmen der Jedermannsrechte gegen das Gewaltmonopol des Staates ausnahmsweise verstoßen","c":true}]},{"q":"Was sind hoheitliche Rechte?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Durchsuchung der Wohnung eines Tatverdächtigen zum Zwecke seiner Ergreifung durch Polizeibeamte","c":true},{"t":"Die Befragung eines auf frischer Tat betroffenen Täters auf freiwilliger Basis durch eine Wachperson, z. B. nach einem Ladendiebstahl","c":false},{"t":"Die Kontrolle eines Rucksacks bei einem Stadionbesucher durch eine Wachperson, mit Einwilligung des Betroffenen","c":false},{"t":"Die Sicherstellung und Beschlagnahme von Beweismitteln beim Beschuldigten durch einen Staatsanwalt","c":true}]},{"q":"Erklären Sie den Begriff „hoheitliche Rechte“","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Hoheitliche Rechte sind Rechte, die der Staat hat","c":true},{"t":"Hoheitliche Rechte können von Sicherheitsmitarbeitern regelmäßig im Dienst angewendet werden","c":false},{"t":"Hoheitliche Rechte stehen privaten Sicherheitsmitarbeitern in Notfällen zu","c":false}]},{"q":"Welche generellen Unterschiede gibt es zwischen dem Tätigwerden der Polizei und gewerblicher Sicherheitsdienste? Gewerbliche Sicherheitsdienste…","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"…haben keine besonderen Eingriffsbefugnisse und dürfen ohne Einverständnis des Betroffenen z. B. keine Durchsuchung oder Beschlagnahme durchführen","c":true},{"t":"…verfügen in Hausrechtsbereichen mit tatsächlich öffentlichem Verkehr über hoheitliche Befugnisse, wenn die Bediensteten die IHK-Sachkundeprüfung § 34a GewO mit Erfolg bestanden haben","c":false},{"t":"…dürfen Zwangsmittel nur im Rahmen der Verfolgung von schweren Straftaten und bei Gefahr im Verzug einsetzen","c":false},{"t":"…dürfen ausschließlich auf privatem Gelände, die Polizei hingegen nur im öffentlichen Verkehrsraum tätig werden","c":false}]},{"q":"Welche generellen Unterschiede gibt es zwischen dem Tätigwerden der Polizei und gewerblicher Sicherheitsdienste? Gewerbliche Sicherheitsdienste…","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"…dürfen ausschließlich auf privatem Gelände, die Polizei hingegen nur im öffentlichen Verkehrsraum tätig werden","c":false},{"t":"…verfügen in Hausrechtsbereichen mit tatsächlich öffentlichem Verkehr über hoheitliche Befugnisse, wenn die Bediensteten die IHK-Sachkundeprüfung § 34a GewO mit Erfolg bestanden haben","c":false},{"t":"…dürfen Zwangsmittel nur im Rahmen der Verfolgung von schweren Straftaten und bei Gefahr im Verzug einsetzen","c":false},{"t":"…haben keine besonderen Eingriffsbefugnisse und dürfen ohne Einverständnis des Betroffenen z. B. keine Durchsuchung oder Beschlagnahme durchführen","c":true}]},{"q":"Welche „hoheitlichen“ Aufgaben können von Mitarbeitern eines privaten Sicherheitsunternehmens erfüllt werden? Es können…","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"…diejenigen hoheitlichen Aufgaben erfüllt werden, welche für den Eigenschutz notwendig sind, um Individualrechtsgüter zu schützen","c":false},{"t":"…hoheitliche Aufgaben erfüllt werden, die vom Auftraggeber verlangt und vertraglich vereinbart werden","c":false},{"t":"…nur hoheitliche Aufgaben im Rahmen der „vorläufigen Festnahme“ gemäß § 127 (1) Strafprozessordnung erfüllt werden","c":false},{"t":"…grundsätzlich keine hoheitlichen Aufgaben von Mitarbeitern eines privaten Sicherheitsunternehmens erfüllt werden","c":true}]},{"q":"Im deutschen Rechtssystem sind Rechtfertigungsgründe verankert. Was sind deren Sinn und Zweck?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sie können strafbares Handeln rechtfertigen","c":true},{"t":"Sie können ordnungswidriges Handeln entschuldigen","c":false},{"t":"Sie können verbotenes Handeln entschuldigen","c":false},{"t":"Sie können unerlaubtes Handeln rechtfertigen","c":true}]},{"q":"Im deutschen Rechtssystem sind Rechtfertigungsgründe verankert. Was ist deren Sinn und Zweck?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sie können verbotenes Handeln entschuldigen","c":false},{"t":"Sie können unerlaubtes Handeln rechtfertigen","c":true},{"t":"Sie können strafbares Handeln rechtfertigen","c":true},{"t":"Sie können ordnungswidriges Handeln entschuldigen","c":false}]},{"q":"Im deutschen Rechtssystem sind Rechtfertigungsgründe verankert. Was ist deren Sinn und Zweck?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sie können unerlaubtes Handeln rechtfertigen","c":true},{"t":"Sie können strafbares Handeln rechtfertigen","c":true},{"t":"Sie können ordnungswidriges Handeln entschuldigen","c":false},{"t":"Sie können verbotenes Handeln entschuldigen","c":false}]},{"q":"Der Bewachungsgewerbetreibende und seine Beschäftigten dürfen bei der Durchführung von Bewachungsaufgaben gegenüber Dritten bestimmte Rechte eigenverantwortlich ausüben. Um welche Rechte handelt es sich?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Beschlagnahme von Diebesgut","c":false},{"t":"Gesetzlich übertragene Rechte aufgrund einer Beleihung","c":true},{"t":"Verkehrsregelung nach Verkehrsunfällen","c":false},{"t":"Notwehr- und Notstandsrechte","c":true}]},{"q":"Der Bewachungsgewerbetreibende und seine Sicherheitsmitarbeiter dürfen bei der Durchführung von Bewachungsaufgaben gegenüber Dritten bestimmte Rechte eigenverantwortlich ausüben. Welche Rechte sind dies?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Gesetzlich übertragene Rechte aufgrund einer Beleihung","c":true},{"t":"Notwehr- und Notstandsrechte","c":true},{"t":"Beschlagnahme von Diebesgut","c":false},{"t":"Verkehrsregelung nach Verkehrsunfällen","c":false}]},{"q":"Welche Rechte haben SMA gegenüber anderen Bürgern bei der Durchführung von Bewachungsaufgaben?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"In Ausnahmesituationen die Notwehr- und Notstandsrechte","c":true},{"t":"In Gefahrensituationen die Befugnisse eines Bediensteten von Sicherheitsbehörden","c":false},{"t":"In Erfüllung des Auftrages die vom Auftraggeber vertraglich übertragenen Besitz- und Selbsthilferechte","c":true}]},{"q":"Auf Grund welcher rechtlichen Grundlagen werden private Sicherheitsmitarbeiter tätig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Jedermannsrechte, Rechtfertigungsgründe","c":true},{"t":"Besitzdienerrechte","c":true},{"t":"Anweisungen des Auftraggebers","c":false},{"t":"Hoheitliche Rechte","c":false}]},{"q":"Welche Rechte dürfen Sicherheitsmitarbeiter (SMA), die Kontrollgänge im öffentlichen Verkehrsraum durchführen, in eigener Verantwortung ausüben?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sie dürfen bei Ordnungswidrigkeiten eingreifen und z. B. Bußgeldbescheinigungen ausstellen und Bußgelder entgegennehmen","c":false},{"t":"Sie dürfen aufgrund eines privatrechtlichen Auftragsverhältnisses tätig werden und z. B. Notwehr- und Notstandsrechte sowie übertragene Selbsthilferechte wahrnehmen","c":true},{"t":"Sie dürfen zur Abwehr von Gefahren für die öffentliche Sicherheit und Ordnung wie Polizeibeamte tätig werden und z. B. Platzverweise erteilen","c":false}]},{"q":"In Notsituationen kann sich jeder Bürger mittels der sogenannten Jedermannsrechte gegen eine Rechtsgutverletzung zur Wehr setzen. Welche nachfolgenden Rechte besitzt nicht „Jedermann“?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Rechtfertigender Notstand","c":false},{"t":"Recht auf Notwehr- und Nothilfe","c":false},{"t":"Vorläufiges Festnahmerecht durch Jedermann","c":false},{"t":"Allgemeines Selbsthilferecht","c":false},{"t":"Hausrecht","c":true}]},{"q":"Welche der beschriebenen Handlungen darf ein Kaufhausdetektiv durchführen?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Festnahme eines auf frischer Tat betroffenen Straftäters, dessen Identität unbekannt ist, bis zum Eintreffen der gerufenen Polizei","c":true},{"t":"Vorläufige Festnahme eines bekannten Straftäters, nach wiederholter Begehung von Straftaten, um ein Hausverbot zu erteilen","c":false},{"t":"Durchsuchung der mitgeführten Tasche eines Tatverdächtigen, falls sich darin die gestohlene Ware befindet","c":false},{"t":"Fesseln eines Ladendiebes mit Handfesseln, falls dies im Rahmen der Gewaltprävention notwendig ist","c":false}]},{"q":"Welche Aussage in Bezug auf sogenannte Public-Private-Partnership-Kooperationen („PPP-Kooperationen“) ist richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Private Sicherheitsdienste, die eine sogenannte „PPP-Kooperation“ eingehen, verfügen über besondere hoheitliche Befugnisse ohne die Aufsicht staatlicher Behörden","c":false},{"t":"„PPP-Kooperationen“ zwischen privaten Sicherheitsunternehmen und Behörden (z. B. der Polizei) sind uneinheitlich und regional sehr unterschiedlich geregelt","c":true},{"t":"„PPP-Kooperationen“ zwischen Polizei und privaten Sicherheitsdiensten sind eine staatliche Maßnahme, bei welcher die Polizei durch Sicherheitsdienste ersetzt wird","c":false},{"t":"„PPP-Kooperationen“ zwischen Polizei und privaten Sicherheitsdiensten beinhalten meistens lediglich einen gegenseitigen Informations- und Erfahrungsaustausch","c":true}]},{"q":"Erklären Sie den Begriff „Public Private Partnership“","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Eine Zusammenarbeit von staatlichen und privaten Stellen","c":true},{"t":"Ein privater Sicherheitsmitarbeiter kann z. B. bei einer Veranstaltung dem Ordnungsamt helfen, wenn das so vereinbart wurde","c":true},{"t":"Der Staat und eine private Wachfirma gründen einen Verein, dessen Mitarbeiter Hilfsbeamte sind","c":false},{"t":"Sicherheitsmitarbeitern einer privaten Wachfirma werden hoheitliche Rechte eines Polizisten übertragen","c":false}]},{"q":"Welche Kooperationsmöglichkeit ist im Rahmen einer Public-Private-Partnership-Vereinbarung zwischen der Polizei und einem privaten Sicherheitsdienst denkbar?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Verkehrslenkung und Verkehrsregelung im Einzelfall, z. B. bei Großveranstaltungen","c":true},{"t":"Gemeinschaftliche und arbeitsteilige Strafverfolgung, z. B. Verhaftung von Straftätern","c":false},{"t":"Hilfeleistung und Informationsaustausch, z. B. bei Sach- und Personenfahndungen","c":true},{"t":"Verkehrsüberwachung mit repressiven und präventiven Maßnahmen, z. B. durch Verkehrskontrollen","c":false}]},{"q":"Wer hat das Gewaltmonopol? Was sind hoheitliche Aufgaben?","a":"Der Staat hat das Gewaltmonopol, es gibt aber Ausnahmen damit sich der Bürger z.B. gegen Angriffe wehren kann (Jedermannsrechte; Ausnahmerechte). Hoheitliche Aufgaben: z.B. Durchsuchen, Sicherstellen, Vernehmen (DSV)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wozu brauchen wir diese Jedermannsrechte/Ausnahmerechte?","a":"Sie erlauben dem Bürger unter bestimmten Voraussetzungen gegen das Gewaltmonopol zu verstoßen wenn Polizei (Staatsgewalt) nicht erreichbar ist","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet das Gewaltmonopol in Deutschland und wer ist Inhaber von diesem?","a":"Bedeutet, dass nur der Staat darf im rechtlichen Rahmen Gewalt anwenden. Nur der Staat ist Inhaber des GewaltmonopolsDie sogenannten Ausnahmerechte (Rechtfertigungsgründe/Jedermannsrechte) erteilen dem Bürger im Rahmen einer Ausnahme die Möglichkeit Gewalt anzuwenden.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Rechte hat die Polizei und welche die privaten Sicherheits-","a":"mitarbeiter? Die Polizei hat Hoheitliche Rechte und die privaten die sogenannten Jedermannsrechte, bzw. Ausnahmerechte, sowie die übertragenen Besitzschutz- Rechte (gegen Verbotene Eigenmacht).","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre das PPP Modell? Was ist eine sogenannte Beleihung?","a":"Public-private-Partnership = Zusammenarbeit zwischen Polizei und Sicherheitsunternehmen zur Stärkung der öffentlichen Sicherheit. Hoheitliche Rechte können beliehen werden für die Arbeit an Flughafen, Atomkraftwerken und Bundeswehrflächen (z.B. LSichG, UzwG)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie unter einer Beleihung?","a":"Teile der hoheitlichen Rechte können auf private befristet übertragen werdenwie:\tprivate Sicherheitsdienstleister; TÜV; GTÜ; Bezirksschornsteinfeger Erfolgt in der privaten Sicherheit zum Beispiel im Rahmen einerPPP = Public-Private-Partnerschip(öffentlich-private-Zusammenarbeit)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Nenne alle Jedermannsrechte/Ausnahmerechte aus dem BGB/StGB, StPO","a":"BGB - Notwehr - Angriffsnotstand BGB - Verteidigungsnotstand BGB - Selbsthilfe BGB - Selbsthilfe des Besitzers BGB - Selbsthilfe des Besitzdieners BGB StGB - Notwehr - Rechtfertigender Notstand - Entschuldigender Notstand StPO - Vorläufige Festnahme","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Unterschied Rechtfertigungsgrund und Jedermannsrechte?","a":"Rechtfertigungsgründe werde auch Jedermannsrechte genannt. Sie erlauben es jedermann, in bestimmten Situationen einen Straftatbestand zu verletzen, ohne dafür bestraft zu werden; (Verhältnismäßigkeit beachten !!); Ausnahme: Der Entschuldigende Notstand. Dieser \"entschuldigt\" die Handlung, rechtfertigt sie aber nicht; z.B. das Brett des Karneades.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wo sind die Grundrechte Verankert? Nennen Sie 5 Grundrechte.","a":"Grundrechte sind im Grundgesetz Art. 1 – 19 verankert. - Würde des Menschen - Unverletzlichkeit der Wohnung - Eigentum - Meinungsfreiheit - Berufsfreiheit","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Worin besteht die praktische Bedeutung der Grundrechte für die","a":"Tätigkeit des Sicherheitsmitarbeiters? Die Grundrechte dürfen nicht verletzt werden, dürfen aber in Ausnahmefällen durch Gesetze eingeschränkt werden; z.B. § 127 (1) StPO","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie unterscheiden sich Menschenrecht von den Bürgerrechtern?","a":"Menschenrechte stehen allen Menschen zu, Bürgerrechte stehen allen Deutschen Staatsbürgern zu.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie bitte jeweils drei Beispiele.","a":"Menschenrechte: - Art. 1: Die Menschenwürde ist unantastbar - Art. 2: Recht auf freie Entfaltung der Person, Recht auf Leben, Recht auf körperliche Unversehrtheit, Recht auf Freiheit - Art. 3: Alle Menschen sind gleich - Art. 4: Freiheit des Glaubens Bürgerrechte: - Art. 8: Versammlungsfreiheit - Art. 9: Vereinigungsfreiheit und Koalitionsfreiheit - Art.11: Recht auf Freizügigkeit im gesamten Bundesgebiet - Art. 12: Recht auf freie Wahl von Beruf, Arbeitsplatz und Ausbildungsstätte - Art. 38 Abs. 1: Die Wahlrechtsgrundsätze","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre die horizontale und vertikale Gewaltenteilung ?","a":"Legislative - Erlass von Gesetzten Judikative - Rechtsprechung Horizontale Exekutive - ausführende Gewalt Gewaltenteilung Es gibt Sie damit Sie sich gegenseitig Kontrollieren, damit keiner die alleinige Gewalt ausüben kann (Polizeistaat) Wertigkeit: Legislative = Bundesrecht bricht Landesrecht. Judikative = Ein Landgericht ist dem Amtsgericht überstellt. Exekutive = Staatsanwaltschaft steht über der Polizei Vertikale Gewaltenteilung = Machtaufteilung in Bund, Länder, Kommunen (Föderalismus) verhindert eine Machtkonzentration und beugt staatlicher Willkür vor","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nenne die 5 Verfassungsprinzipien, Artikel 20 GG","a":"- Rechtsstaatsprinzip (Keine Strafe ohne Gesetz) - Demokratie (Alle Macht geht vom Volke aus) - Sozialstaatsprinzip (Augleich zwischen Arm und Reich) - Bundesstaatsprinzip (Föderalismus) - Republik (Staatsoberhaupt wird auf Zeit gewählt)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Rechtswidrig?","a":"Der Angreifer hat keinen Rechtfertigungsgrund für sein Handeln.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Artikel im Grundgesetz beinhalten die Grundrechte?","a":"Die Artikel 1 bis 19","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"In welche Bereiche / Kategorien teilen sich die Grundrechte und warum?","a":"Menschenrechte= gilt für alle Menschen, im Staatsgebiet der Bundesrepublik Deutschland Bürgerrechte= gilt nur für deutsche Staatsangehörige, im Staatsgebiet der Bundesrepublik Deutschland","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was haben der Artikel 1 und Artikel 20 des GG gemeinsam?","a":"Sie sind durch die sogenannte Ewigkeitsklausel (Artikel 79 GG) geschütztund somit unveränderbar","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Aufgabe haben die Grundrechte?","a":"Sie sollen die Bürger vor staatlicher Willkür schützen. Sie sollen in Drittwirkung die Bürger untereinander schützen. Sie benennen eindeutig verschiedene geschützte Rechtsgüterwie: Leben, Gesundheit, Freiheit, Eigentum","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was versteht man unter: „Föderalismus“ ?","a":"Zusammenschluss mehrerer Bundesländer zu einem Bundesstaat mit dem Ziel der Machtaufteilung zwischen dem Bund, den 16 Bundesländern; z.B. Polizei sowie der Kommunen (Amtsgerichte u.a.)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wer ist im öffentlichen Recht, wer im privaten Recht zuständig?","a":"Im öffentlichen Recht der Staat (Polizei) und im privaten Recht Sicherheits- unternehmen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Benennen Sie die drei Staatsgewalten der horizontalen Gewaltenteilung!","a":"Legislative = gesetzgebende Gewaltwie:\tBundestag (+ Bundesrat); Landtag Exekutive = ausführende / vollziehende Gewaltwie:\tPolizei; Staatsanwaltschaft; Bundespräsident Judikative = richterliche / rechtsprechende Gewaltwie: Richter (an Bundes- & Landesgericht)","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[{"scenario":"Du arbeitest als SMA in einem Einkaufszentrum. Ein Ladendieb wird auf frischer Tat ertappt und will fliehen. Ein Kollege meint, du dürftest ihn „festnehmen und durchsuchen wie die Polizei“.","frage":"Welche Rechte hast du wirklich – und welche nicht?","loesung":"SMA haben KEINE hoheitlichen Rechte (keine Durchsuchung, keine Beschlagnahme). Du hast nur Jedermannsrechte – hier die vorläufige Festnahme nach §127 StPO bei frischer Tat und Fluchtverdacht. Durchsuchen darf nur die Polizei."}]}],"cardCount":27,"quizCount":134},{"id":"s34a-1","tg":1,"name":"Gewerberecht (GewO / BewachV)","color":"var(--stack-green)","meta":{"relevanz":"Mittel","schriftlich":"4 Fragen · 4/100 Punkte","muendlich":"Schwerpunkt"},"merksaetze":[],"blocks":[{"n":1,"title":"Erlaubnis & Voraussetzungen","subtitle":"5 Konzepte · 17 Prüfungsfragen","cards":[{"h":"Gewerbeerlaubnis §34a GewO","b":"Voraussetzungen: Zuverlässigkeit, geordnete Vermögensverhältnisse, Sachkunde, Haftpflicht","detail":null,"visual":null},{"h":"Zuverlässigkeit","b":"Führungszeugnis, Stellungnahme der Polizei, ggf. Verfassungsschutz-Abfrage","detail":null,"visual":null},{"h":"Mindestvoraussetzungen SMA","b":"Zuverlässigkeit, 18 Jahre, notwendige Befähigung (U40 oder SKP), persönliche Eignung","detail":null,"visual":null},{"h":"Vorstrafen / Ausschluss","b":"Drogen-, Waffendelikte, KV, Diebstahl etc.; Freiheitsstrafe oder ≥90 Tagessätze","detail":null,"visual":null},{"h":"Befreiung von Unterrichtung/Sachkunde","b":"Stichtage 1996/2003; bestimmte Berufsgruppen (Meister, FfSuS, Polizei)","detail":null,"visual":null}],"quiz":[{"q":"Nenne die Voraussetzungen um im Sicherheitsdienst zu arbeiten.","a":"- 18 Jahre alt, Nachweis der Zuverlässigkeit, - Unterrichtungsnachweis gem. § 34a GewO (40 Std. Unterrichtung) oder bestandene IHK Sachkundeprüfung, Eignung für die jeweilige Aufgabe (gefordert durch die Berufsgenossenschaft/ DGUV Vorschrift 23)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Vorraussetzungen um sich selbständig machen zu können?","a":"- Sachkundeprüfung §34a, 18 Jahre, Nachweis der Zuverlässigkeit (liegt nicht vor wenn Antragsteller Mitglied in verbotenem Verein ist oder war und seit der Beendigung der Mitglied- schaft zehn Jahre noch nicht verstrichen sind, in den letzten fünf Jahren vor Stellung des Antrags wegen Versuchs oder Vollendung einer der nachstehend aufgeführten Straftaten zu einer Freiheitsstrafe, Jugendstrafe, Geldstrafe von mindestens 90 Tagessätzen oder mindestens zweimal zu einer geringeren Geldstrafe rechtskräftig verurteilt worden ist – siehe§ 34a Nr. 1 Abs. 4 - !) - Haftpflichtversicherung, - geregelte Vermögensverhältnisse (Neu seit 01.12.2016 ! – vorher Nachweis von finanziellen Mitteln und Sicherheiten für ca. 6 Monate)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was genau besagt §34a der GewO?","a":"Wer gewerbemäßig fremdes Leben oder Eigentum bewachen will, benötigt die Erlaubnis der zuständigen Behörde.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie die Definition des Bewachungsgewerbes?","a":"gewerbsmäßig fremdes Leben und Eigentum bewachen „Wer gewerbsmäßig Leben und Eigentum fremder Personen bewachen will.“(siehe §34a Abs. 1 Satz 1 GewO)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was zählt zum öffentlichen Verkehrsraum* im Sinne des §34a GewO?","a":"Öffentlicher Verkehrsraum- öffentliche Straßen, Wege, Plätze- alles, was für jedermann öffentlich zugänglich ist Private Hausrechtsbereiche mit tatsächlichem öffentlichem Verkehr- Einkaufszentren, Ladenpassagen (Mall), etc.- Flughäfen, Gerichte, Krankenhäuser, etc.- private Parkanlagen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was wird bei der Zuverlässigkeit gem. §34a GewO geprüft?","a":"Kein Mitglied einer verfassungswidrigen Partei (Sperrfrist 10 Jahre) Kein Mitglied eines verbotenen Vereines (Sperrfrist 10 Jahre) Kein Mitglied oder Unterstützer einer verfassungsfeindlichen Organisation (Sperrfrist 5 Jahre) Keine rechtskräftige Verurteilung (Sperrfrist 5 Jahre)\t- Freiheitsstrafe\t- Geldstrafe ab 90 Tagessätze oder zwei mal geringer (innerhalb der 5 Jahre)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was bedeutet eigentlich Zuverlässigkeit?","a":"- keine relevanten Eintrage im „behördlichen“ (unbeschränkte Auskunft des BZR) Führungszeugnis, sowie eine Stellungnahme der für den Wohnort zuständigen Landespolizei; zentrale Polizeidienststelle oder zuständiges LKA. Darüber hinaus Erkenntnisabfrage beim Verfassungsschutz für Personen die beauftragt werden bei der Bewachung von: Flüchtlingsunterkünften, Großveranstaltungen, Objekten mit einem besonderen Schutzbedürfnis für die Allgemeinheit!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was wird für die Erlaubnis eines Bewachungsgewerbes benötigt?","a":"Mindestens 18. Lebensjahr vollendet Sachkundeprüfung Zuverlässigkeit geordnete Vermögensverhältnisse (z.B.: keine Vollstreckungen oder Insolvenzen offen) (Betriebs-) Haftpflichtversicherung","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wann muss der Gewerbetreibende seine Wachperson bei der Gewerbebehörde anmelden?","a":"Rechtzeitig vor der ersten Beschäftigung Warum?Da die Wachperson erst durch die Gewerbebehörde - geprüft (Zuverlässigkeitsprüfung) und - freigegeben werden muss (schriftlich an Gewerbetreibenden mit Vergabe einer Bewacher-ID)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Vorstrafen führen zum Ausschluss im Sicherheitsdienst?","a":"Drogen-, Waffendelikte; Straftaten mit Körperverletzung, Freiheitsberaubung, des Diebstahls, der Unterschlagung, Erpressung, Betrug, Hehlerei, Urkundenfälschung, Land-, Hausfriedensbruchs etc. / Freiheitsstrafe oder Geldstrafe (mind. 90 Tagessätze oder 2 x geringere Geldstrafe)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wer ist von der Unterrichtung, wer von der Sachkundeprüfung befreit?","a":"- Personen die am 31.03.1996 in einem Bewachungsgewerbe tätig waren. (Stichtag: 01.04.1996/Unterrichtung) - Personen die am 01.01.2003 mindestens 3 Jahre ohne Unterbrechungen, befugt in einem Bewachungsgewerbe tätig waren/Sachkunde, Meister -, Fachkraft -, Servicekraft für Schutz und Sicherheit, Feldjäger Bundeswehr mittlerer Polizei- und Justizvollzugsdienstdienst (Befreiung von Unterrichtung und Sachkundeprüfung gemäß BewachV)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Ist die Sachkundeprüfung bei der IHK öffentlich?","a":"Nein.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Unterschied Tätigkeitsfelder Unterrichtung/Sachkunde?","a":"Bei der Unterrichtung (40 Std.) darf man z.B. - Bewachungen in privaten Bereichen ausführen, Objekt /Werkschutz (Streifengänge in befriedetem Bereich) - Geld- und Werttransport, Revierfahrer - Zugangskontrollen mit Zutrittsverweigerung zum (Fußball -) Stadion - Tätigkeit als Museumswächter - Personenschützer - Bewachungspersonal bei Veranstaltungen in sog. Wellenbrechern etc. Die Sachkundeprüfung ist vorgeschrieben… - für Tätigkeiten bei denen häufiger berufliche Konfliktsituationen auftreten können und daher fundierte Rechtskenntnisse und ausgeprägte Fähigkeiten im Umgang mit Menschen erforderlich sind!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wer benötigt einen Nachweis der Sachkundeprüfung?","a":"Personen die ein Bewachungsgewerbe selbständig ausüben wollen sowie mit der Leitung des Gewerbebetriebs beauftragte Personen und… - Kontrollgänge im öffentlichen Verkehrsraum, in privaten Hausrechtsbereichen mit tatsächlich öffentlichem Personenverkehr - Kaufhausdetektiv (Schutz vor Ladendiebstahl) - Bewachung im „Einlassbereich“ von gastgewerblichen Diskotheken - Bewachung in leitender Funktion in Asyl-, bzw. Flüchtlingsunterkünften - Bewachung in leitender Funktion bei „zugangsgeschützten“ Großveranstaltungen (ab ca. 5000 Personen)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Besteht eine Pflicht den Ausweis sichtbar zu tragen?","a":"Nein, das Mitführen genügt; Bei sachkunderelevanten Tätigkeiten ist ein Kennschild mit Name oder Kennnummer sowie Name des Gewerbetreibenden sichtbar zu tragen (Ausnahme: Ladendetektiv)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Tätigkeiten dürfen Sie mit der Sachkundeprüfung ausüben?","a":"Kontrollgänge im öffentlichen Verkehrsraum* (#Citystreifen) Schutz vor Ladendieben (#Ladendetektiv) Einlassbereiche gastgewerblicher Diskotheken (#Türsteher) in leitender Funktion bei zugangsgeschützten Großveranstaltungen in leitender Funktion in Asyl-/ Aufnahmeeinrichtungen Die Sachkundeprüfung erlaubt auch die Eröffnung eines Gewerbes („selbstständig machen“)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wer ist gemäß Bewachungsverordnung von der (IHK) Unterricht und der Sachkundeprüfung befreit?","a":"Polizei (mindestens abgeschlossene Laufbahnprüfung mittlerer Dienst) Feldjäger der Bundeswehr Justizvollzugsbeamte Zollbeamte des bewaffneten Dienstes Fachkraft für Schutz und Sicherheit Meister für Schutz und Sicherheit","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[{"scenario":"Bei einer Kontrolle durch das Ordnungsamt wird ein Mitarbeiter ohne sichtbares Namensschild und ohne Dienstausweis angetroffen.","frage":"Gegen welche Pflichten aus der BewachV wird hier verstoßen?","loesung":"Verstoß gegen die Ausweispflicht (§18 BewachV: Dienstausweis mitführen) und die Kennzeichnungspflicht (sichtbares Schild mit Name/Kennnummer + Firma bei sachkundepflichtigen Tätigkeiten – außer Ladendetektiv). Beides ist bußgeldbewehrt."}]},{"n":2,"title":"Tätigkeitsfelder","subtitle":"5 Konzepte · 20 Prüfungsfragen","cards":[{"h":"Sachkundepflichtige Tätigkeiten","b":"Unternehmer, Citystreife, Ladendetektiv, Disko-Einlass, Flüchtlingsunterkunft (leitend), Großveranstaltung (leitend)","detail":null,"visual":null},{"h":"Unterrichtung vs. Sachkunde","b":"40-Std-Unterrichtung vs. SKP für konfliktträchtige Tätigkeiten","detail":null,"visual":null},{"h":"Rechtliche Räume","b":"Öff. Verkehrsraum; Hausrechtbereich mit öff. Verkehr; gewerbl./staatl. mit Einlasskontrolle; privater Hausrechtbereich","detail":null,"visual":null},{"h":"Citystreife","b":"Kontrollgänge im öff. Verkehrsraum oder Hausrechtbereich mit öff. Verkehr","detail":null,"visual":null},{"h":"Schutz vor Ladendieben","b":"Konfliktträchtig; Risiko fehlerhafter vorläufiger Festnahme","detail":null,"visual":null}],"quiz":[{"q":"Unterschied Tätigkeitsfelder Unterrichtung/Sachkunde?","a":"Bei der Unterrichtung (40 Std.) darf man z.B. - Bewachungen in privaten Bereichen ausführen, Objekt /Werkschutz (Streifengänge in befriedetem Bereich) - Geld- und Werttransport, Revierfahrer - Zugangskontrollen mit Zutrittsverweigerung zum (Fußball -) Stadion - Tätigkeit als Museumswächter - Personenschützer - Bewachungspersonal bei Veranstaltungen in sog. Wellenbrechern etc. Die Sachkundeprüfung ist vorgeschrieben… - für Tätigkeiten bei denen häufiger berufliche Konfliktsituationen auftreten können und daher fundierte Rechtskenntnisse und ausgeprägte Fähigkeiten im Umgang mit Menschen erforderlich sind!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Bewachung im Sinne der Gewerbeordnung ist… ?","a":"Derjenige der gewerbsmäßig Leben oder Eigentum fremder Personen bewacht; gefordert ist eine „aktive Obhutstätigkeit“ (Bewachungstätigkeit hat gewisse Dauer oder Durchführung wiederkehrender Kontrollen; Einsatz von Sicherheitstechnik).","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was machen Citystreifen?","a":"Kontrollgänge… - im öffentlichen Verkehrsraum oder - in privaten Hausrechtbereichen mit tatsächlich öffentlichem Personenverkehr.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Besteht eine Pflicht den Ausweis sichtbar zu tragen?","a":"Nein, das Mitführen genügt; Bei sachkunderelevanten Tätigkeiten ist ein Kennschild mit Name oder Kennnummer sowie Name des Gewerbetreibenden sichtbar zu tragen (Ausnahme: Ladendetektiv)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Tätigkeiten dürfen Sie mit der Sachkundeprüfung ausüben?","a":"Kontrollgänge im öffentlichen Verkehrsraum* (#Citystreifen) Schutz vor Ladendieben (#Ladendetektiv) Einlassbereiche gastgewerblicher Diskotheken (#Türsteher) in leitender Funktion bei zugangsgeschützten Großveranstaltungen in leitender Funktion in Asyl-/ Aufnahmeeinrichtungen Die Sachkundeprüfung erlaubt auch die Eröffnung eines Gewerbes („selbstständig machen“)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wann ist durch Wachpersonen ein Kennschild sichtbar zu tragen, und was muss es beinhalten?","a":"Bei Kontrollgängen im öffentlichen Verkehrsraum Bei zugangsgeschützten Großveranstaltungen für alle Bei Asyl-/Aufnahmeeinrichtungen für alle Einlasstätigkeiten an gastgewerblichen Diskotheken Muss beinhalten:- Name der Wachperson oder individuelle Kennnummer- Name / Bezeichnung des Gewerbetreibenden / Gewerbebetriebes","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Nenne die Voraussetzungen um im Sicherheitsdienst zu arbeiten.","a":"- 18 Jahre alt, Nachweis der Zuverlässigkeit, - Unterrichtungsnachweis gem. § 34a GewO (40 Std. Unterrichtung) oder bestandene IHK Sachkundeprüfung, Eignung für die jeweilige Aufgabe (gefordert durch die Berufsgenossenschaft/ DGUV Vorschrift 23)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Vorraussetzungen um sich selbständig machen zu können?","a":"- Sachkundeprüfung §34a, 18 Jahre, Nachweis der Zuverlässigkeit (liegt nicht vor wenn Antragsteller Mitglied in verbotenem Verein ist oder war und seit der Beendigung der Mitglied- schaft zehn Jahre noch nicht verstrichen sind, in den letzten fünf Jahren vor Stellung des Antrags wegen Versuchs oder Vollendung einer der nachstehend aufgeführten Straftaten zu einer Freiheitsstrafe, Jugendstrafe, Geldstrafe von mindestens 90 Tagessätzen oder mindestens zweimal zu einer geringeren Geldstrafe rechtskräftig verurteilt worden ist – siehe§ 34a Nr. 1 Abs. 4 - !) - Haftpflichtversicherung, - geregelte Vermögensverhältnisse (Neu seit 01.12.2016 ! – vorher Nachweis von finanziellen Mitteln und Sicherheiten für ca. 6 Monate)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wer ist von der Unterrichtung, wer von der Sachkundeprüfung befreit?","a":"- Personen die am 31.03.1996 in einem Bewachungsgewerbe tätig waren. (Stichtag: 01.04.1996/Unterrichtung) - Personen die am 01.01.2003 mindestens 3 Jahre ohne Unterbrechungen, befugt in einem Bewachungsgewerbe tätig waren/Sachkunde, Meister -, Fachkraft -, Servicekraft für Schutz und Sicherheit, Feldjäger Bundeswehr mittlerer Polizei- und Justizvollzugsdienstdienst (Befreiung von Unterrichtung und Sachkundeprüfung gemäß BewachV)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Ist die Sachkundeprüfung bei der IHK öffentlich?","a":"Nein.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wer benötigt einen Nachweis der Sachkundeprüfung?","a":"Personen die ein Bewachungsgewerbe selbständig ausüben wollen sowie mit der Leitung des Gewerbebetriebs beauftragte Personen und… - Kontrollgänge im öffentlichen Verkehrsraum, in privaten Hausrechtsbereichen mit tatsächlich öffentlichem Personenverkehr - Kaufhausdetektiv (Schutz vor Ladendiebstahl) - Bewachung im „Einlassbereich“ von gastgewerblichen Diskotheken - Bewachung in leitender Funktion in Asyl-, bzw. Flüchtlingsunterkünften - Bewachung in leitender Funktion bei „zugangsgeschützten“ Großveranstaltungen (ab ca. 5000 Personen)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was wird für die Erlaubnis eines Bewachungsgewerbes benötigt?","a":"Mindestens 18. Lebensjahr vollendet Sachkundeprüfung Zuverlässigkeit geordnete Vermögensverhältnisse (z.B.: keine Vollstreckungen oder Insolvenzen offen) (Betriebs-) Haftpflichtversicherung","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wer ist gemäß Bewachungsverordnung von der (IHK) Unterricht und der Sachkundeprüfung befreit?","a":"Polizei (mindestens abgeschlossene Laufbahnprüfung mittlerer Dienst) Feldjäger der Bundeswehr Justizvollzugsbeamte Zollbeamte des bewaffneten Dienstes Fachkraft für Schutz und Sicherheit Meister für Schutz und Sicherheit","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist ein Sonderzugangsrecht gem. BDSG?","a":"Es sagt aus, dass die zuständige Aufsichtsbehörde während der üblichen Betriebs- und Geschäftzeiten ein Sonderzugangsrecht zu Grundstücken und Geschäftsräumen des zu überprüfenden Unternehmens hat und dort Prüfungen bezügliches der Einhaltung des Datenschutzes durchführen kann.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet eigentlich Zuverlässigkeit?","a":"- keine relevanten Eintrage im „behördlichen“ (unbeschränkte Auskunft des BZR) Führungszeugnis, sowie eine Stellungnahme der für den Wohnort zuständigen Landespolizei; zentrale Polizeidienststelle oder zuständiges LKA. Darüber hinaus Erkenntnisabfrage beim Verfassungsschutz für Personen die beauftragt werden bei der Bewachung von: Flüchtlingsunterkünften, Großveranstaltungen, Objekten mit einem besonderen Schutzbedürfnis für die Allgemeinheit!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere aus der BewachV , Datenschutz","a":"Die in der Ausübung des Dienstes bekannt gewordenen Geschäfts- und Betriebs- geheimnisse Dritter, auch nach ihrem Ausscheiden nicht unbefugt zu offenbaren.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Gesetze wurden zum Datenschutz erlassen?","a":"Bundesdatenschutzgesetz und Landesdatenschutzgesetz","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Ab wann benötigt ein Unternehmen einen Datenschutzbeauftragten?","a":"Bei der automatisierten Verarbeitung (Lohnbüro) von persönlichen Daten und mehr als 9 Personen – geändert durch die DSGVO !","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist mit technischen und organisatorische Maßnahmen gem.","a":"BDSG gemeint? - Zutrittskontrolle = den unbefugten Zutritt zu Datenverarbeitungs- anlagen zu verwehren. - Zugangskontrollen = die unbefugte Nutzung von Datenverabeitungs- systemen ist zu verhindern. - Zugriffkontrollen = Zugriff, unbefugte Verarbeitung, Nutzung, Speichern, verändern ist zu verhindern. - Weitergabekontrolle = der befugte Zugriff bei Übertragung, Transport und Speicherung auf Datenträger ist zu gewährleisten - Eingabekontrolle = kontrollierte Nutzung von Datenverarbeitungs- systemen - Auftragskontrolle = bei vorliegendem Auftrag zur Datenverarbeitung ist den Weisungen des Auftraggebers Rechnung zu tragen. - Verfügbarkeitskontrollen = die Datenträger sind vor Verlust oder Zerstörung zu schützen. - Beispiel für eine Zutrittskontrolle !","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Beauftragter für den Datenschutz; Aufgaben:","a":"- Einhaltung des Datenschutzes - Überwachung der ordnungsgemäßen Anwendung der Datenverarbeitungsprogramme - Überwachung der technischen und organisatorischen Maßnahmen im Datenschutz - Schulung des Personals die mit der Datenverarbeitung betraut sind","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[]},{"n":3,"title":"Pflichten nach BewachV","subtitle":"7 Konzepte · 18 Prüfungsfragen","cards":[{"h":"BewachV-Grundlagen","b":"Bewachungsverordnung & GewO; Geltung für Gewerbetreibende und Beschäftigte; Auskunft/Nachschau §29 GewO","detail":null,"visual":null},{"h":"Dienstausweis §18 BewachV","b":"6 Merkmale: Firmenname+Anschrift, Name SMA, Unterschriften, Bewacherreg-IDs; muss sich von Behördenausweis unterscheiden","detail":null,"visual":null},{"h":"Kennzeichnungspflicht §18","b":"Sichtbares Kennschild (Name/Kennnummer + Firma) bei sachkundepfl. Tätigkeiten, außer Ladendetektiv","detail":null,"visual":null},{"h":"Dienstkleidung §19","b":"Nicht behördenähnlich; in befriedetem Besitztum tragen; Ausnahme Ladendetektiv","detail":null,"visual":null},{"h":"Haftungssummen BewachV","b":"Personen 1 Mio, Sach 250.000, Abhandenkommen 15.000, Vermögen 12.500 €","detail":null,"visual":null},{"h":"Bewacherregister","b":"Seit 01.06.2019; Registrierung von Gewerbetreibenden und Personal","detail":null,"visual":null},{"h":"Dienstanweisung BewachV","b":"Pflichtinhalte der Dienstanweisung; Waffen nur nach Absprache, keine hoheitlichen Befugnisse","detail":null,"visual":null}],"quiz":[{"q":"In welchen Verordnungen/Gesetzen ist das private Bewachungsgewerbe geregelt?","a":"Bewachungsverordnung und Gewerbeordnung","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was besagt die Bewachungsverordnung und für wen gelten diese Vorschriften?","a":"Regelt die allgemeinen Pflichten für den Gewerbetreibenden und auch für dessen Beschäftigte","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Bewachung im Sinne der Gewerbeordnung ist… ?","a":"Derjenige der gewerbsmäßig Leben oder Eigentum fremder Personen bewacht; gefordert ist eine „aktive Obhutstätigkeit“ (Bewachungstätigkeit hat gewisse Dauer oder Durchführung wiederkehrender Kontrollen; Einsatz von Sicherheitstechnik).","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Auskunft und Nachschau gem. § 29 GewO?","a":"Gewerbetreibende haben den Beauftragten der zuständigen öffentlichen Stelle auf Verlangen, die für die Überwachungdes Geschäftsbetriebes erforderlichen Auskünfte unentgeltlich zu erteilen; Zu den üblichen Geschäftszeiten","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wer ist gemäß Bewachungsverordnung von der (IHK) Unterricht und der Sachkundeprüfung befreit?","a":"Polizei (mindestens abgeschlossene Laufbahnprüfung mittlerer Dienst) Feldjäger der Bundeswehr Justizvollzugsbeamte Zollbeamte des bewaffneten Dienstes Fachkraft für Schutz und Sicherheit Meister für Schutz und Sicherheit","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Erläutere aus der BewachV , Dienstausweis","a":"Im Dienstausweis muss der Firmenname, Firmenanschrift, Name und Vorname des Mitarbeiters, Bewacherregister-Identifikationsnummer von Gewerbetreibenden und Mitarbeiter sowie Unterschriften des Gewerbetreibende und des Mitarbeiters vermerkt sein. Der Ausweis muss so beschaffen sein, dass er sich von amtlichen Ausweisen deutlich unterscheidet.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was muss der Bewacherausweis (Dienstausweis) mindestens beinhalten?","a":"Name und Vorname der Wachperson Name und Anschrift des Gewerbebetriebes Bewacher ID (Bewacherregisteridentifikationsnummer)\t- Wachperson\t- Gewerbebetrieb Unterschrift der Gewerbetreibenden Unterschrift der Wachperson","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Besteht eine Pflicht den Ausweis sichtbar zu tragen?","a":"Nein, das Mitführen genügt; Bei sachkunderelevanten Tätigkeiten ist ein Kennschild mit Name oder Kennnummer sowie Name des Gewerbetreibenden sichtbar zu tragen (Ausnahme: Ladendetektiv)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wann ist durch Wachpersonen ein Kennschild sichtbar zu tragen, und was muss es beinhalten?","a":"Bei Kontrollgängen im öffentlichen Verkehrsraum Bei zugangsgeschützten Großveranstaltungen für alle Bei Asyl-/Aufnahmeeinrichtungen für alle Einlasstätigkeiten an gastgewerblichen Diskotheken Muss beinhalten:- Name der Wachperson oder individuelle Kennnummer- Name / Bezeichnung des Gewerbetreibenden / Gewerbebetriebes","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Erläutere aus der BewachV, Dienstkleidung","a":"Dienstkleidung muss beim Betreten des eingefriedeten Besitztums getragen werden. Sie darf nicht mit Uniformen der behördlichen Vollzugorgane verwechselt werden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was müssen Wachpersonen beim Tragen von Dienstkleidung gem. BewachV beachten?","a":"Dienstkleidung muss sich von Uniformen der Vollzugsorgane (Polizei, Ordnungsamt, etc.) und Streitkräften (Bundeswehr) unterscheiden.(betrifft auch das Verwendungsverbot von Amtsabzeichen, wie Landeswappen, etc.) Beim Betreten von befriedetem Besitztum, im Dienst, ist Dienstkleidung zu tragen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Vorraussetzungen um sich selbständig machen zu können?","a":"- Sachkundeprüfung §34a, 18 Jahre, Nachweis der Zuverlässigkeit (liegt nicht vor wenn Antragsteller Mitglied in verbotenem Verein ist oder war und seit der Beendigung der Mitglied- schaft zehn Jahre noch nicht verstrichen sind, in den letzten fünf Jahren vor Stellung des Antrags wegen Versuchs oder Vollendung einer der nachstehend aufgeführten Straftaten zu einer Freiheitsstrafe, Jugendstrafe, Geldstrafe von mindestens 90 Tagessätzen oder mindestens zweimal zu einer geringeren Geldstrafe rechtskräftig verurteilt worden ist – siehe§ 34a Nr. 1 Abs. 4 - !) - Haftpflichtversicherung, - geregelte Vermögensverhältnisse (Neu seit 01.12.2016 ! – vorher Nachweis von finanziellen Mitteln und Sicherheiten für ca. 6 Monate)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere aus der BewachV, Haftungssummen","a":"Personenschäden: 1.000.000,00 € Sachschäden: 250.000,00 € Abhandenkommen bewachter Sachen: 15.000,00 € Vermögensschäden: 12.500,00 € Bei Waffengebrauch: pauschal 1.000.000,00 für Personen- und Sachschäden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was wird für die Erlaubnis eines Bewachungsgewerbes benötigt?","a":"Mindestens 18. Lebensjahr vollendet Sachkundeprüfung Zuverlässigkeit geordnete Vermögensverhältnisse (z.B.: keine Vollstreckungen oder Insolvenzen offen) (Betriebs-) Haftpflichtversicherung","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wann wurde das Bewacher Register eingeführt?","a":"Seit 01.Juni.2019.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Verpflichtung hat die Wachperson in Bezug auf ihren Bewacherausweis?","a":"Sie muss den Bewacherausweis zu jedem Dienst mit sich führen Ebenso ist das Identifikationsdokument* mitzuführen, mit welchem sich die Wachperson im Bewacherregister identifiziert hat.\t* Personalausweis oder Reisepass oder Aufenthaltstitel Beide Dokumente sind bei einer Kontrolle den zuständigen Behörden vorzuzeigen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Erläutere aus der BewachV , Dienstanweisung","a":"- Führen von Schuss- Hieb- und Stosswaffen Reizstoffsprühgeräte nur in Absprache mit dem Gewerbetreibenden, - Rechte und Befugnisse (keine hoheitlichen Befugnisse) - Anzeigepflicht bei Gebrauch von Waffen o.ä. an Gewerbetreibenden und Polizei Der Gewerbetreibende hat der Wachperson einen Abdruck der Dienstanweisung sowie der DGUV Vorschrift 23 gegen Empfangsbescheinigung auszuhändigen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was muss der Gewerbetreibende gem. BewachV mindestens in die Dienstanweisung aufnehmen?","a":"Wachpersonen haben nicht die Befugnisse von Polizeibeamten oder anderen Behörden Schusswaffen, Hieb- & Stoßwaffen sowie Reizstoffsprühgeräte dürfen nur mit Genehmigung des Gewerbetreibenden im Dienst geführt werden Gebrauch von Waffen ist unverzüglich der zuständigen Polizeidienststelle und dem Gewerbetreibenden zu melden Die Regelung zur Wahrung von Geschäftsgeheimnissen wird separat getroffen.","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[]}],"cardCount":17,"quizCount":55},{"id":"s34a-2","tg":2,"name":"Datenschutzrecht","color":"var(--stack-yellow)","meta":{"relevanz":"Niedrig","schriftlich":"4 Fragen · 4/100 Punkte","muendlich":"—"},"merksaetze":[],"blocks":[{"n":1,"title":"Grundlagen","subtitle":"6 Konzepte · 28 Prüfungsfragen","cards":[{"h":"Informationelle Selbstbestimmung","b":"Art. 1+2 GG; Volkszählungsurteil 1983; Art. 8 EU-Grundrechtecharta","detail":null,"visual":null},{"h":"Rechtsnormen","b":"DSGVO (EU), BDSG (national), LDSG (Länder)","detail":null,"visual":null},{"h":"Personenbezogene Daten (pbD)","b":"Daten zu identifizierter/identifizierbarer natürlicher Person","detail":null,"visual":null},{"h":"Bestimmte vs. bestimmbare Person","b":"Direkt erkennbar vs. über Zusatzangaben ermittelbar","detail":null,"visual":null},{"h":"Natürliche vs. juristische Personen","b":"Alle Menschen vs. Firmen, Vereine, Gesellschaften","detail":null,"visual":null},{"h":"Öffentliche vs. nicht-öffentliche Stellen","b":"Behörden/Ämter/Gerichte vs. private Personen/Unternehmen","detail":null,"visual":null}],"quiz":[{"q":"Was bedeutet Informationelle Selbstbestimmung?","a":"Jeder hat das Recht grundsätzlich selbst zu entscheiden welche Daten er von sich Preis geben will.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was versteht man unter personenbezogenen Daten?","a":"Informationen über eine Person, mit denen diese identifiziert werden kann(Daten können einzeln oder gesammelt der Identifizierung dienen) allgemeine personenbezogene Daten- Name, Geburtsdatum, Wohnort, Körpermerkmale, Geschlecht, Sprachmuster/-merkmale, Geburtsort, Steuernummer, Bankverbindung besondere personenbezogene Daten- Gesundheitsdaten, sexuelle Orientierung, Gewerkschaftszugehörigkeit, Religion, Weltanschauung, biometrische / genetische Daten, ethnische Herkunft","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was versteht man unter dem „verarbeiten“ personenbezogener Daten!","a":"Grundsätzlich alles, was man mit pbD machen kann\t- speichern\t- erfassen\t- löschen\t- weitergeben\t- bereitstellen\t- verändern","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Straftaten (Paragrafen) im StGB schützen personenbezogene Daten?","a":"Verletzung der Vertraulichkeit des Wortes (§201 StGB) Verletzung des höchstpersönlichen Lebensbereiches durch Bildaufnahmen (§201a StGB) Verletzung des Briefgeheimnisses (§202 StGB) Ausspähen von Daten (§202a StGB) Lediglich für die schriftliche Prüfung relevant","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Ab wann benötigt der Unternehmer einen Datenschutzbeauftragten?","a":"Wenn mehr als 20 Beschäftigte dauerhaft mit der Verarbeitung personenbezogener Daten betraut sind.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was sind natürliche und was sind juristische Personen im BDSG?","a":"Natürliche Personen sind alle Personen. Juristische Personen sind Firmen (GmbH o.ä.), Gesellschaften, Vereine.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind öffentliche und was sind nicht öffentliche Stellen?","a":"Öffentliche Stellen: Behörden, Ämter, Gerichte Nicht öffentliche Stellen: alle juristische und natürlichen Personen; z.B. ein privates Sicherheitsunternehmen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind personenbezogene Daten?","a":"Alle Daten die dazu führen, das ich eine bestimmte Persondirekt identifizieren kann (Name, Personalausweisnummer,...)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine bestimmte und was ist eine bestimmbare Person?","a":"Bestimmt ist eine Person, wenn aus den Angaben auf einen einzelnen Menschen geschlossen werden kann. Bestimmbar ist eine Person, wenn über zusätzliche Angaben ein Bezug zur Person herstellbar ist (Kontonummern, Personalausweisnummer, KFZ-Kennzeichen,...).","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet eigentlich Zuverlässigkeit?","a":"- keine relevanten Eintrage im „behördlichen“ (unbeschränkte Auskunft des BZR) Führungszeugnis, sowie eine Stellungnahme der für den Wohnort zuständigen Landespolizei; zentrale Polizeidienststelle oder zuständiges LKA. Darüber hinaus Erkenntnisabfrage beim Verfassungsschutz für Personen die beauftragt werden bei der Bewachung von: Flüchtlingsunterkünften, Großveranstaltungen, Objekten mit einem besonderen Schutzbedürfnis für die Allgemeinheit!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wer ist von der Unterrichtung, wer von der Sachkundeprüfung befreit?","a":"- Personen die am 31.03.1996 in einem Bewachungsgewerbe tätig waren. (Stichtag: 01.04.1996/Unterrichtung) - Personen die am 01.01.2003 mindestens 3 Jahre ohne Unterbrechungen, befugt in einem Bewachungsgewerbe tätig waren/Sachkunde, Meister -, Fachkraft -, Servicekraft für Schutz und Sicherheit, Feldjäger Bundeswehr mittlerer Polizei- und Justizvollzugsdienstdienst (Befreiung von Unterrichtung und Sachkundeprüfung gemäß BewachV)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Unterschied Tätigkeitsfelder Unterrichtung/Sachkunde?","a":"Bei der Unterrichtung (40 Std.) darf man z.B. - Bewachungen in privaten Bereichen ausführen, Objekt /Werkschutz (Streifengänge in befriedetem Bereich) - Geld- und Werttransport, Revierfahrer - Zugangskontrollen mit Zutrittsverweigerung zum (Fußball -) Stadion - Tätigkeit als Museumswächter - Personenschützer - Bewachungspersonal bei Veranstaltungen in sog. Wellenbrechern etc. Die Sachkundeprüfung ist vorgeschrieben… - für Tätigkeiten bei denen häufiger berufliche Konfliktsituationen auftreten können und daher fundierte Rechtskenntnisse und ausgeprägte Fähigkeiten im Umgang mit Menschen erforderlich sind!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Bewachung im Sinne der Gewerbeordnung ist… ?","a":"Derjenige der gewerbsmäßig Leben oder Eigentum fremder Personen bewacht; gefordert ist eine „aktive Obhutstätigkeit“ (Bewachungstätigkeit hat gewisse Dauer oder Durchführung wiederkehrender Kontrollen; Einsatz von Sicherheitstechnik).","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wer benötigt einen Nachweis der Sachkundeprüfung?","a":"Personen die ein Bewachungsgewerbe selbständig ausüben wollen sowie mit der Leitung des Gewerbebetriebs beauftragte Personen und… - Kontrollgänge im öffentlichen Verkehrsraum, in privaten Hausrechtsbereichen mit tatsächlich öffentlichem Personenverkehr - Kaufhausdetektiv (Schutz vor Ladendiebstahl) - Bewachung im „Einlassbereich“ von gastgewerblichen Diskotheken - Bewachung in leitender Funktion in Asyl-, bzw. Flüchtlingsunterkünften - Bewachung in leitender Funktion bei „zugangsgeschützten“ Großveranstaltungen (ab ca. 5000 Personen)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was machen Citystreifen?","a":"Kontrollgänge… - im öffentlichen Verkehrsraum oder - in privaten Hausrechtbereichen mit tatsächlich öffentlichem Personenverkehr.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere aus der BewachV, Haftungssummen","a":"Personenschäden: 1.000.000,00 € Sachschäden: 250.000,00 € Abhandenkommen bewachter Sachen: 15.000,00 € Vermögensschäden: 12.500,00 € Bei Waffengebrauch: pauschal 1.000.000,00 für Personen- und Sachschäden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Ab wann benötigt ein Unternehmen einen Datenschutzbeauftragten?","a":"Bei der automatisierten Verarbeitung (Lohnbüro) von persönlichen Daten und mehr als 9 Personen – geändert durch die DSGVO !","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie die Definition des Bewachungsgewerbes?","a":"gewerbsmäßig fremdes Leben und Eigentum bewachen „Wer gewerbsmäßig Leben und Eigentum fremder Personen bewachen will.“(siehe §34a Abs. 1 Satz 1 GewO)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was muss der Gewerbetreibende gem. BewachV mindestens in die Dienstanweisung aufnehmen?","a":"Wachpersonen haben nicht die Befugnisse von Polizeibeamten oder anderen Behörden Schusswaffen, Hieb- & Stoßwaffen sowie Reizstoffsprühgeräte dürfen nur mit Genehmigung des Gewerbetreibenden im Dienst geführt werden Gebrauch von Waffen ist unverzüglich der zuständigen Polizeidienststelle und dem Gewerbetreibenden zu melden Die Regelung zur Wahrung von Geschäftsgeheimnissen wird separat getroffen.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wann ist durch Wachpersonen ein Kennschild sichtbar zu tragen, und was muss es beinhalten?","a":"Bei Kontrollgängen im öffentlichen Verkehrsraum Bei zugangsgeschützten Großveranstaltungen für alle Bei Asyl-/Aufnahmeeinrichtungen für alle Einlasstätigkeiten an gastgewerblichen Diskotheken Muss beinhalten:- Name der Wachperson oder individuelle Kennnummer- Name / Bezeichnung des Gewerbetreibenden / Gewerbebetriebes","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was müssen Wachpersonen beim Tragen von Dienstkleidung gem. BewachV beachten?","a":"Dienstkleidung muss sich von Uniformen der Vollzugsorgane (Polizei, Ordnungsamt, etc.) und Streitkräften (Bundeswehr) unterscheiden.(betrifft auch das Verwendungsverbot von Amtsabzeichen, wie Landeswappen, etc.) Beim Betreten von befriedetem Besitztum, im Dienst, ist Dienstkleidung zu tragen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Vorraussetzungen um sich selbständig machen zu können?","a":"- Sachkundeprüfung §34a, 18 Jahre, Nachweis der Zuverlässigkeit (liegt nicht vor wenn Antragsteller Mitglied in verbotenem Verein ist oder war und seit der Beendigung der Mitglied- schaft zehn Jahre noch nicht verstrichen sind, in den letzten fünf Jahren vor Stellung des Antrags wegen Versuchs oder Vollendung einer der nachstehend aufgeführten Straftaten zu einer Freiheitsstrafe, Jugendstrafe, Geldstrafe von mindestens 90 Tagessätzen oder mindestens zweimal zu einer geringeren Geldstrafe rechtskräftig verurteilt worden ist – siehe§ 34a Nr. 1 Abs. 4 - !) - Haftpflichtversicherung, - geregelte Vermögensverhältnisse (Neu seit 01.12.2016 ! – vorher Nachweis von finanziellen Mitteln und Sicherheiten für ca. 6 Monate)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Auskunft und Nachschau gem. § 29 GewO?","a":"Gewerbetreibende haben den Beauftragten der zuständigen öffentlichen Stelle auf Verlangen, die für die Überwachungdes Geschäftsbetriebes erforderlichen Auskünfte unentgeltlich zu erteilen; Zu den üblichen Geschäftszeiten","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere aus der BewachV , Datenschutz","a":"Die in der Ausübung des Dienstes bekannt gewordenen Geschäfts- und Betriebs- geheimnisse Dritter, auch nach ihrem Ausscheiden nicht unbefugt zu offenbaren.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere aus der BewachV, Dienstkleidung","a":"Dienstkleidung muss beim Betreten des eingefriedeten Besitztums getragen werden. Sie darf nicht mit Uniformen der behördlichen Vollzugorgane verwechselt werden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wann darf man Video überwachen?","a":"a) öffentlicher Bereich b) privater Hausrechtsbereich - a) Zu Verkehrslenkungszwecken oder Prävention (öffentlicher Bereich/Behörde) - b) privater Hausrechtsbereich, wenn darauf hingewiesen wird (z.B. Hinweisschild o.a.) und Kameras sichtbar ist, Zur Wahrung des Hausrechts, z.B. Verhinderung und Aufklärung von Straftaten… Die erhobenen Daten sind unverzüglich zu löschen wenn sie ihren Zweck nicht mehr erfüllen. Sogenannte Diebesfallen (versteckte Kameras) nur mit Zustimmung des Betriebsrates und Unterschrift (im Arbeitsvertrag) des Beschäftigten","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Tätigkeiten dürfen Sie mit der Sachkundeprüfung ausüben?","a":"Kontrollgänge im öffentlichen Verkehrsraum* (#Citystreifen) Schutz vor Ladendieben (#Ladendetektiv) Einlassbereiche gastgewerblicher Diskotheken (#Türsteher) in leitender Funktion bei zugangsgeschützten Großveranstaltungen in leitender Funktion in Asyl-/ Aufnahmeeinrichtungen Die Sachkundeprüfung erlaubt auch die Eröffnung eines Gewerbes („selbstständig machen“)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was zählt zum öffentlichen Verkehrsraum* im Sinne des §34a GewO?","a":"Öffentlicher Verkehrsraum- öffentliche Straßen, Wege, Plätze- alles, was für jedermann öffentlich zugänglich ist Private Hausrechtsbereiche mit tatsächlichem öffentlichem Verkehr- Einkaufszentren, Ladenpassagen (Mall), etc.- Flughäfen, Gerichte, Krankenhäuser, etc.- private Parkanlagen","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[]},{"n":2,"title":"Besondere Daten & Verarbeitung","subtitle":"5 Konzepte · 20 Prüfungsfragen","cards":[{"h":"Besondere Kategorien (Art. 9 DSGVO)","b":"Herkunft, politische Meinung, Religion, Gesundheit, Sexualleben, Biometrie etc.","detail":null,"visual":null},{"h":"Verarbeiten & Erheben von Daten","b":"Speichern, ändern, übermitteln, sperren, löschen; Erhebung bei Einwilligung oder Gesetz","detail":null,"visual":null},{"h":"Rechte des Betroffenen","b":"Auskunft, Berichtigung, Löschung, Sperrung, Schadensersatz","detail":null,"visual":null},{"h":"Datenschutzbeauftragter","b":"Ab automatisierter Verarbeitung & mehr als 9 Personen; Aufgaben","detail":null,"visual":null},{"h":"Technische/organisatorische Maßnahmen","b":"Zutritts-, Zugangs-, Zugriffs-, Weitergabe-, Eingabe-, Auftrags-, Verfügbarkeitskontrolle","detail":null,"visual":null}],"quiz":[{"q":"Was versteht man unter personenbezogenen Daten?","a":"Informationen über eine Person, mit denen diese identifiziert werden kann(Daten können einzeln oder gesammelt der Identifizierung dienen) allgemeine personenbezogene Daten- Name, Geburtsdatum, Wohnort, Körpermerkmale, Geschlecht, Sprachmuster/-merkmale, Geburtsort, Steuernummer, Bankverbindung besondere personenbezogene Daten- Gesundheitsdaten, sexuelle Orientierung, Gewerkschaftszugehörigkeit, Religion, Weltanschauung, biometrische / genetische Daten, ethnische Herkunft","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Auf welchem Recht beruht der Datenschutz in Deutschland?","a":"Auf dem Recht der informationellen Selbstbestimmung> bedeutet jeder hat das zu entscheiden ob und welche Daten wann und wie lange über jemanden gespeichert werden> außer bei entsprechenden gesetzlichen Bestimmungen (z.B.: Strafverfolgung) Das Recht stützt sich hier auf folgende Grundrechte:> Artikel 1 GG – Recht auf Menschenwürde> Artikel 2 GG – Recht auf freie Entfaltung der Persönlichkeit","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Auf welche Rechtsgrundlagen beruht der Datenschutz in Deutschland?","a":"DSG-VO = Datenschutzgrundverordnung (EU) BDSG = Bundesdatenschutzgesetz (D) LDSG = Landesdatenschutzgesetze (Bundesländer)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was versteht man unter dem „verarbeiten“ personenbezogener Daten!","a":"Grundsätzlich alles, was man mit pbD machen kann\t- speichern\t- erfassen\t- löschen\t- weitergeben\t- bereitstellen\t- verändern","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Straftaten (Paragrafen) im StGB schützen personenbezogene Daten?","a":"Verletzung der Vertraulichkeit des Wortes (§201 StGB) Verletzung des höchstpersönlichen Lebensbereiches durch Bildaufnahmen (§201a StGB) Verletzung des Briefgeheimnisses (§202 StGB) Ausspähen von Daten (§202a StGB) Lediglich für die schriftliche Prüfung relevant","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Ab wann benötigt der Unternehmer einen Datenschutzbeauftragten?","a":"Wenn mehr als 20 Beschäftigte dauerhaft mit der Verarbeitung personenbezogener Daten betraut sind.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Erläutere aus der BewachV , Datenschutz","a":"Die in der Ausübung des Dienstes bekannt gewordenen Geschäfts- und Betriebs- geheimnisse Dritter, auch nach ihrem Ausscheiden nicht unbefugt zu offenbaren.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Gesetze wurden zum Datenschutz erlassen?","a":"Bundesdatenschutzgesetz und Landesdatenschutzgesetz","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Informationelle Selbstbestimmung?","a":"Jeder hat das Recht grundsätzlich selbst zu entscheiden welche Daten er von sich Preis geben will.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind personenbezogene Daten?","a":"Alle Daten die dazu führen, das ich eine bestimmte Persondirekt identifizieren kann (Name, Personalausweisnummer,...)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet verarbeiten von Daten und wann darf man","a":"Daten erheben? Verarbeiten von Daten: speichern, ändern, übermitteln, sperren, löschen Daten erheben: Ist das gezieltes Beschaffen von Daten; bei Einwilligung § 4 BDSG oder durch Gesetz §§ 28, 29 BDSG","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Ab wann benötigt ein Unternehmen einen Datenschutzbeauftragten?","a":"Bei der automatisierten Verarbeitung (Lohnbüro) von persönlichen Daten und mehr als 9 Personen – geändert durch die DSGVO !","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wann darf man Video überwachen?","a":"a) öffentlicher Bereich b) privater Hausrechtsbereich - a) Zu Verkehrslenkungszwecken oder Prävention (öffentlicher Bereich/Behörde) - b) privater Hausrechtsbereich, wenn darauf hingewiesen wird (z.B. Hinweisschild o.a.) und Kameras sichtbar ist, Zur Wahrung des Hausrechts, z.B. Verhinderung und Aufklärung von Straftaten… Die erhobenen Daten sind unverzüglich zu löschen wenn sie ihren Zweck nicht mehr erfüllen. Sogenannte Diebesfallen (versteckte Kameras) nur mit Zustimmung des Betriebsrates und Unterschrift (im Arbeitsvertrag) des Beschäftigten","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nenne die Rechte des Betroffenen gemäß BDSG","a":"Auskunft über, seine gespeicherten Daten, deren Herkunft, Zweck der gespeicherten Daten, Weitergabe an Dritte. Er kann seine Daten berichtigen, löschen oder sperren lassen. Recht auf Schadensersatz bei unzulässiger und unrichtiger Erhebung, Verarbeitung und Nutzung","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist mit technischen und organisatorische Maßnahmen gem.","a":"BDSG gemeint? - Zutrittskontrolle = den unbefugten Zutritt zu Datenverarbeitungs- anlagen zu verwehren. - Zugangskontrollen = die unbefugte Nutzung von Datenverabeitungs- systemen ist zu verhindern. - Zugriffkontrollen = Zugriff, unbefugte Verarbeitung, Nutzung, Speichern, verändern ist zu verhindern. - Weitergabekontrolle = der befugte Zugriff bei Übertragung, Transport und Speicherung auf Datenträger ist zu gewährleisten - Eingabekontrolle = kontrollierte Nutzung von Datenverarbeitungs- systemen - Auftragskontrolle = bei vorliegendem Auftrag zur Datenverarbeitung ist den Weisungen des Auftraggebers Rechnung zu tragen. - Verfügbarkeitskontrollen = die Datenträger sind vor Verlust oder Zerstörung zu schützen. - Beispiel für eine Zutrittskontrolle !","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist ein Sonderzugangsrecht gem. BDSG?","a":"Es sagt aus, dass die zuständige Aufsichtsbehörde während der üblichen Betriebs- und Geschäftzeiten ein Sonderzugangsrecht zu Grundstücken und Geschäftsräumen des zu überprüfenden Unternehmens hat und dort Prüfungen bezügliches der Einhaltung des Datenschutzes durchführen kann.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Beauftragter für den Datenschutz; Aufgaben:","a":"- Einhaltung des Datenschutzes - Überwachung der ordnungsgemäßen Anwendung der Datenverarbeitungsprogramme - Überwachung der technischen und organisatorischen Maßnahmen im Datenschutz - Schulung des Personals die mit der Datenverarbeitung betraut sind","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was muss frühestmöglich bei einer Videoüberwachung öffentlich zugänglicher Räume erfolgen!","a":"Es muss angekündigt werden durch ein Schild:\tWer zeichnet auf? Wie lange wird aufgezeichnet? Warum wird aufgezeichnet (Rechtsgrundlage)? Wo und bei wem bekomme ich Auskunft über die Aufzeichnung?","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was bedeutet eigentlich Zuverlässigkeit?","a":"- keine relevanten Eintrage im „behördlichen“ (unbeschränkte Auskunft des BZR) Führungszeugnis, sowie eine Stellungnahme der für den Wohnort zuständigen Landespolizei; zentrale Polizeidienststelle oder zuständiges LKA. Darüber hinaus Erkenntnisabfrage beim Verfassungsschutz für Personen die beauftragt werden bei der Bewachung von: Flüchtlingsunterkünften, Großveranstaltungen, Objekten mit einem besonderen Schutzbedürfnis für die Allgemeinheit!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Auskunft und Nachschau gem. § 29 GewO?","a":"Gewerbetreibende haben den Beauftragten der zuständigen öffentlichen Stelle auf Verlangen, die für die Überwachungdes Geschäftsbetriebes erforderlichen Auskünfte unentgeltlich zu erteilen; Zu den üblichen Geschäftszeiten","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[]},{"n":3,"title":"Videoüberwachung","subtitle":"3 Konzepte · 5 Prüfungsfragen","cards":[{"h":"Videoüberwachung §4 BDSG","b":"Wann erlaubt: berechtigtes Interesse, Hausrecht; Hinweisschild, nicht versteckt, Löschung nach Zweck","detail":null,"visual":null},{"h":"Pflicht-Videoüberwachung §6 UVV","b":"Kassenräume Banken, Zugänge Spielhallen/Casinos, bestimmte Industrieanlagen","detail":null,"visual":null},{"h":"Verbotene Videoüberwachung","b":"Umkleide, Toilette, Dusche, Pausenraum","detail":null,"visual":null}],"quiz":[{"q":"Was muss frühestmöglich bei einer Videoüberwachung öffentlich zugänglicher Räume erfolgen!","a":"Es muss angekündigt werden durch ein Schild:\tWer zeichnet auf? Wie lange wird aufgezeichnet? Warum wird aufgezeichnet (Rechtsgrundlage)? Wo und bei wem bekomme ich Auskunft über die Aufzeichnung?","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Nennen Sie Bereiche wo keine Videoüberwachung öffentlich zugänglicher Räume erfolgen darf!","a":"Zum Beispiel: Umkleidekabinen Toiletten Duschen Pausenräume","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was bedeutet Auskunft und Nachschau gem. § 29 GewO?","a":"Gewerbetreibende haben den Beauftragten der zuständigen öffentlichen Stelle auf Verlangen, die für die Überwachungdes Geschäftsbetriebes erforderlichen Auskünfte unentgeltlich zu erteilen; Zu den üblichen Geschäftszeiten","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wann darf man Video überwachen?","a":"a) öffentlicher Bereich b) privater Hausrechtsbereich - a) Zu Verkehrslenkungszwecken oder Prävention (öffentlicher Bereich/Behörde) - b) privater Hausrechtsbereich, wenn darauf hingewiesen wird (z.B. Hinweisschild o.a.) und Kameras sichtbar ist, Zur Wahrung des Hausrechts, z.B. Verhinderung und Aufklärung von Straftaten… Die erhobenen Daten sind unverzüglich zu löschen wenn sie ihren Zweck nicht mehr erfüllen. Sogenannte Diebesfallen (versteckte Kameras) nur mit Zustimmung des Betriebsrates und Unterschrift (im Arbeitsvertrag) des Beschäftigten","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Beauftragter für den Datenschutz; Aufgaben:","a":"- Einhaltung des Datenschutzes - Überwachung der ordnungsgemäßen Anwendung der Datenverarbeitungsprogramme - Überwachung der technischen und organisatorischen Maßnahmen im Datenschutz - Schulung des Personals die mit der Datenverarbeitung betraut sind","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[{"scenario":"Ein Auftraggeber möchte die Videoüberwachung auf die Umkleidekabinen und den Pausenraum der Mitarbeiter ausweiten, „zur Sicherheit“.","frage":"Ist das zulässig? Begründe.","loesung":"Nein. Umkleide, Toilette, Dusche und Pausenraum sind tabu – dort überwiegt das Persönlichkeitsrecht. Zulässige Videoüberwachung braucht berechtigtes Interesse, Hinweisschild, darf nicht versteckt sein und unterliegt Löschfristen nach Zweckerfüllung."}]}],"cardCount":14,"quizCount":53},{"id":"s34a-3","tg":3,"name":"Bürgerliches Recht / Straf- und Verfahrensrecht (BGB, StGB, StPO)","color":"var(--stack-orange)","meta":{"relevanz":"sehr hoch","schriftlich":"BGB 4 + Strafrecht 12 Fragen · 24/100 Punkte","muendlich":"Schwerpunkt"},"merksaetze":[],"blocks":[{"n":1,"title":"BGB – Grundlagen","subtitle":"7 Konzepte · 56 Prüfungsfragen","cards":[{"h":"Rechtsfähigkeit","b":"Ab Vollendung der Geburt","detail":{"titel":"Rechtsfähigkeit","kat":"BGB · Person","katCls":"bgb","merksatz":"Rechtsfähig ist, wer Träger von Rechten und Pflichten sein kann – beim Menschen ab der vollendeten Geburt bis zum Tod.","funktion":["Rechtsfähigkeit der natürlichen Person: beginnt mit der Vollendung der Geburt (§ 1 BGB) und endet mit dem Tod.","Natürliche Person = der Mensch. Juristische Person = ein rechtlich verselbstständigtes Gebilde (GmbH, AG, eingetragener Verein), das ebenfalls Träger von Rechten und Pflichten ist.","Abzugrenzen von der Geschäftsfähigkeit (wer wirksam Verträge schließen kann) und der Deliktsfähigkeit (wer für Schäden haftet)."],"schutzziel":"Festlegen, wer überhaupt Rechte haben und Pflichten tragen kann – die Grundvoraussetzung jeder rechtlichen Beziehung.","kennwerte":[{"l":"Beginn","v":"Vollendung der Geburt (§ 1 BGB)"},{"l":"Ende","v":"Tod der Person"},{"l":"Juristische Person","v":"GmbH, AG, e. V."}],"begriffe":["Natürliche Person = der einzelne Mensch.","Juristische Person = Vereinigung oder Einrichtung mit eigener Rechtsfähigkeit (z. B. GmbH, Verein).","Geschäftsfähigkeit = die Fähigkeit, wirksam Rechtsgeschäfte (Verträge) abzuschließen."],"abgrenzung":["Rechtsfähigkeit (Rechte haben können) ist nicht dasselbe wie Geschäftsfähigkeit (Verträge schließen können) – ein Neugeborenes ist rechtsfähig, aber nicht geschäftsfähig.","Auch eine GmbH ist rechtsfähig (juristische Person), obwohl sie kein Mensch ist."],"praxis":["Dein Arbeitgeber ist oft eine juristische Person (z. B. eine GmbH) – Vertragspartner deines Auftrags ist die Firma, nicht eine einzelne Person.","Auch ein Kind ist rechtsfähig und kann z. B. Eigentümer einer Sache sein – das ist bei Schadensfragen relevant."]},"visual":null},{"h":"Anspruch","b":"Recht, von einem anderen ein Handeln oder Unterlassen zu fordern","detail":{"titel":"Anspruch","kat":"BGB · Grundbegriff","katCls":"bgb","merksatz":"Ein Anspruch ist das Recht, von einem anderen ein Tun oder Unterlassen zu verlangen (§ 194 BGB).","funktion":["Definition: das Recht, von einem anderen ein Handeln oder ein Unterlassen zu fordern.","Anspruchsgrundlage: die Vorschrift, aus der sich der Anspruch ergibt (z. B. § 823 BGB für Schadensersatz, § 985 BGB für Herausgabe).","Durchsetzung: Wird der Anspruch nicht freiwillig erfüllt, kann er gerichtlich (Klage) durchgesetzt werden."],"schutzziel":"Dem Berechtigten ein durchsetzbares Mittel geben, um vom anderen das zu bekommen, was ihm rechtlich zusteht.","kennwerte":[{"l":"Definition","v":"Tun oder Unterlassen fordern (§ 194)"},{"l":"Beispiele","v":"Herausgabe, Schadensersatz, Zahlung"},{"l":"Grundlage","v":"die jeweilige Anspruchsnorm"}],"begriffe":["Anspruchsgrundlage = die Rechtsnorm, die den Anspruch trägt.","Gläubiger = wer den Anspruch hat; Schuldner = wer ihn erfüllen muss."],"abgrenzung":["Ein Anspruch richtet sich gegen eine bestimmte Person (z. B. Herausgabe vom Besitzer). Das Eigentum dagegen wirkt gegen jedermann.","Der Anspruch ist die Befugnis, ein Verhalten zu fordern – nicht das Recht selbst."],"praxis":["Der Geschädigte hat gegen den Schädiger einen Anspruch auf Schadensersatz – die Grundlage, warum jemand für angerichteten Schaden zahlen muss.","Der Eigentümer hat gegen den, der seine Sache hat, einen Herausgabeanspruch (§ 985 BGB)."]},"visual":null},{"h":"Eigentümer / Besitzer / Besitzdiener","b":"Rechtliche vs. tatsächliche Gewalt; weisungsgebundener Besitzdiener","detail":{"titel":"Eigentümer / Besitzer / Besitzdiener","kat":"BGB · Sachenrecht","katCls":"bgb","merksatz":"Eigentum ist die rechtliche Macht über eine Sache, Besitz die tatsächliche – und der Besitzdiener übt den Besitz nur für einen anderen aus.","funktion":["Eigentümer: hat die rechtliche Herrschaft über die Sache (§ 903 BGB) – ihm ‚gehört‘ sie.","Besitzer: hat die tatsächliche Herrschaft über die Sache (§ 854 BGB) – er hat sie ‚in der Hand‘, auch wenn sie ihm nicht gehört (z. B. Mieter, Entleiher).","Besitzdiener: übt die tatsächliche Gewalt für einen anderen aus und ist dabei dessen Weisungen unterworfen (§ 855 BGB) – z. B. der Angestellte mit dem Firmenfahrzeug."],"schutzziel":"Klar trennen, wem eine Sache rechtlich gehört, wer sie tatsächlich innehat und wer sie nur für einen anderen hält – wichtig für Herausgabe, Selbsthilfe und Haftung.","kennwerte":[{"l":"Eigentümer","v":"rechtliche Gewalt (§ 903)"},{"l":"Besitzer","v":"tatsächliche Gewalt (§ 854)"},{"l":"Besitzdiener","v":"Gewalt für einen anderen, weisungsgebunden (§ 855)"}],"begriffe":["Unmittelbarer Besitzer = wer die Sache selbst in der Hand hat; mittelbarer Besitzer = wer sie über einen anderen besitzt (z. B. der Vermieter über den Mieter).","Besitzdiener = z. B. Kassierer, Lagerarbeiter, Wachmann – übt Besitz für den Arbeitgeber aus."],"abgrenzung":["Eigentum (gehört mir) und Besitz (habe ich) fallen oft auseinander: Der Mieter besitzt die Wohnung, der Vermieter ist Eigentümer.","Der Besitzdiener ist KEIN Besitzer – er hat keine eigenen Besitzrechte, sondern handelt nur für den Besitzherrn (wichtig für die Selbsthilferechte)."],"praxis":["Als Wachmann bist du meist Besitzdiener: Du übst die tatsächliche Gewalt über das Objekt für den Auftraggeber aus, nach dessen Weisungen.","Diese Einordnung entscheidet, welche Selbsthilferechte du hast (§ 860 BGB für den Besitzdiener)."]},"visual":null},{"h":"Sache & Tiere","b":"Sachen = körperliche Gegenstände; Tiere keine Sachen, aber §90a","detail":{"titel":"Sache & Tiere","kat":"BGB · Sachenrecht","katCls":"bgb","merksatz":"Sachen sind körperliche Gegenstände (§ 90 BGB) – Tiere sind keine Sachen, werden aber rechtlich wie Sachen behandelt (§ 90a BGB).","funktion":["Sache (§ 90 BGB): nur körperliche Gegenstände – fest, flüssig oder gasförmig. Rechte, Forderungen oder Daten sind keine Sachen.","Bewegliche Sachen (Mobilien) und unbewegliche Sachen (Grundstücke, Immobilien).","Tiere (§ 90a BGB): sind keine Sachen, aber es gelten die für Sachen geltenden Vorschriften entsprechend, soweit nichts anderes bestimmt ist."],"schutzziel":"Klären, worauf sich Eigentum und Besitz überhaupt beziehen können – und Tieren eine rechtliche Sonderstellung geben.","kennwerte":[{"l":"Sache (§ 90)","v":"körperlicher Gegenstand"},{"l":"Arten","v":"beweglich · unbeweglich"},{"l":"Tiere (§ 90a)","v":"keine Sachen, aber wie Sachen behandelt"}],"begriffe":["Bewegliche Sache = transportabler Gegenstand (Auto, Handy, Bargeld).","Unbewegliche Sache = Grundstück und fest damit verbundene Bestandteile (Gebäude).","§ 90a BGB stellt klar: Tiere sind keine Sachen, werden aber rechtlich überwiegend so behandelt."],"abgrenzung":["Körperliche Gegenstände sind Sachen – unkörperliche Dinge (eine Forderung, ein Patent, digitale Daten) sind KEINE Sachen im Sinne des § 90 BGB.","Tiere sind ausdrücklich keine Sachen (§ 90a), werden aber bei Eigentum, Besitz und Schadensersatz wie Sachen behandelt."],"praxis":["Für Diebstahl (§ 242 StGB) und Sachbeschädigung (§ 303 StGB) muss es um eine Sache gehen – Daten ‚stehlen‘ ist deshalb kein Diebstahl im klassischen Sinn.","Verletzt jemand bei einem Vorfall einen Diensthund, greifen über § 90a die Sachvorschriften (Schadensersatz)."]},"visual":null},{"h":"Schadensersatz §823 BGB","b":"Wer vorsätzlich/fahrlässig Rechtsgüter verletzt, ist zum Ersatz verpflichtet","detail":{"titel":"Schadensersatz § 823 BGB","kat":"BGB · Haftung","katCls":"bgb","merksatz":"Wer vorsätzlich oder fahrlässig ein geschütztes Rechtsgut eines anderen widerrechtlich verletzt, muss den Schaden ersetzen (§ 823 BGB).","funktion":["Geschützte Rechtsgüter (§ 823 Abs. 1 BGB): Leben, Körper, Gesundheit, Freiheit, Eigentum und sonstige Rechte.","Voraussetzungen: eine widerrechtliche Verletzung, ein Verschulden (Vorsatz oder Fahrlässigkeit) und ein dadurch verursachter Schaden.","Folge: Verpflichtung zum Ersatz des entstandenen Schadens."],"schutzziel":"Den Geschädigten so stellen, wie er ohne die Schädigung stünde – und schuldhaftes Verhalten mit Ersatzpflicht belegen.","kennwerte":[{"l":"Geschützt","v":"Leben, Körper, Gesundheit, Freiheit, Eigentum"},{"l":"Verschulden","v":"Vorsatz oder Fahrlässigkeit"},{"l":"Folge","v":"Schadensersatzpflicht"}],"begriffe":["Unerlaubte Handlung = die schuldhafte, widerrechtliche Rechtsgutverletzung (§§ 823 ff. BGB).","Vorsatz = Wissen und Wollen der Verletzung; Fahrlässigkeit = Außerachtlassen der im Verkehr erforderlichen Sorgfalt.","Verbotene Eigenmacht (§ 858 BGB) kann zugleich eine unerlaubte Handlung sein."],"abgrenzung":["Schadensersatz (BGB) ist zivilrechtlicher Ausgleich zwischen den Beteiligten – die Strafe (StGB) ist die staatliche Reaktion. Ein Vorfall kann beides auslösen.","Ohne Verschulden (weder Vorsatz noch Fahrlässigkeit) gibt es nach § 823 grundsätzlich keinen Schadensersatz."],"praxis":["Wenn du als Wachkraft jemanden bei einer Maßnahme rechtswidrig und schuldhaft verletzt, kann das eine Schadensersatzpflicht auslösen – ein Grund, sich an die Befugnisse zu halten.","Beschädigt jemand das bewachte Objekt vorsätzlich oder fahrlässig, haftet er dem Eigentümer aus § 823 BGB."]},"visual":null},{"h":"Schadensersatz-/Strafmündigkeit","b":"Schadensersatzpflichtig ab 7, strafbar ab 14 Jahren","detail":{"titel":"Schadensersatz- & Strafmündigkeit","kat":"BGB & StGB · Alter","katCls":"bgb","merksatz":"Für Schäden haftet man ab 7, strafbar ist man ab 14 – Kinder darunter sind weder deliktsfähig noch strafmündig.","funktion":["Deliktsfähigkeit (zivilrechtlich): Wer das 7. Lebensjahr noch nicht vollendet hat, ist nicht verantwortlich (§ 828 Abs. 1 BGB). Von 7 bis 17 nur bei entsprechender Einsichtsfähigkeit.","Strafmündigkeit (strafrechtlich): Schuldunfähig ist, wer bei der Tat noch nicht 14 Jahre alt ist (§ 19 StGB). Jugendliche (14–17) nach Jugendstrafrecht.","Im Straßenverkehr gilt für die Haftung von Kindern eine Sonderregel (erst ab 10 Jahren, § 828 Abs. 2 BGB)."],"schutzziel":"Kinder und Jugendliche entsprechend ihrer Einsichtsfähigkeit vor Verantwortung schützen, der sie noch nicht gewachsen sind.","kennwerte":[{"l":"Deliktsfähig (BGB)","v":"ab 7 Jahren (§ 828)"},{"l":"Strafmündig (StGB)","v":"ab 14 Jahren (§ 19)"},{"l":"Verkehr (Kinder)","v":"Haftung erst ab 10 (§ 828 II)"}],"begriffe":["Deliktsfähigkeit = die zivilrechtliche Verantwortlichkeit für Schäden.","Strafmündigkeit = die strafrechtliche Schuldfähigkeit ab 14 Jahren.","Jugendlicher = 14 bis 17 Jahre; Heranwachsender = 18 bis 20 Jahre."],"abgrenzung":["Deliktsfähigkeit (Schadensersatz, ab 7) und Strafmündigkeit (Strafe, ab 14) sind zwei verschiedene Altersgrenzen – nicht verwechseln.","Auch wenn ein 12-Jähriger nicht bestraft werden kann (§ 19 StGB), kann er zivilrechtlich für einen Schaden haften (ab 7, § 828)."],"praxis":["Erwischst du einen 12-jährigen Ladendieb, ist er strafrechtlich nicht verantwortlich (unter 14) – einbezogen werden die Eltern; zivilrechtlich kann aber Ersatz in Betracht kommen.","Für die Praxis heißt das: Alter klären, ruhig bleiben, Eltern und Polizei einbeziehen – nicht wie einen Erwachsenen behandeln."]},"visual":null},{"h":"Schikaneverbot","b":"Ausübung eines Rechts unzulässig, wenn nur zur Schädigung anderer (§226 BGB)","detail":{"titel":"Schikaneverbot § 226 BGB","kat":"BGB · Schranke","katCls":"bgb","merksatz":"Ein Recht auszuüben ist verboten, wenn es nur dazu dienen kann, einem anderen zu schaden (§ 226 BGB).","funktion":["Schikaneverbot: Die Ausübung eines Rechts ist unzulässig, wenn sie nur den Zweck haben kann, einem anderen Schaden zuzufügen.","Es begrenzt jedes Recht: Auch wer formal im Recht ist, darf es nicht aus reiner Bosheit als Mittel einsetzen.","Verwandt: das allgemeine Verbot unzulässiger Rechtsausübung nach Treu und Glauben (§ 242 BGB)."],"schutzziel":"Den Missbrauch von Rechten verhindern – ein Recht ist zur Wahrung eigener Interessen da, nicht zum reinen Schaden anderer.","kennwerte":[{"l":"Grundsatz","v":"kein Recht nur zum Schaden (§ 226)"},{"l":"Voraussetzung","v":"einziger Zweck ist Schädigung"},{"l":"Verwandt","v":"Treu und Glauben (§ 242)"}],"begriffe":["Schikane = die Ausübung eines Rechts allein zu dem Zweck, einen anderen zu schädigen.","Rechtsmissbrauch = formal bestehendes Recht wird zweckwidrig eingesetzt."],"abgrenzung":["Das Schikaneverbot greift nur, wenn die Schädigung der EINZIGE mögliche Zweck ist – verfolgt man auch ein eigenes berechtigtes Interesse, ist die Rechtsausübung erlaubt.","Es ist eine Schranke der Rechtsausübung, kein eigener Anspruch."],"praxis":["Auch dein Hausrecht und deine Befugnisse dürfen nicht schikanös eingesetzt werden – Maßnahmen müssen einem sachlichen Zweck (Sicherheit, Ordnung) dienen, nicht der Schikane einzelner.","Wer eine Person ohne sachlichen Grund nur drangsaliert, überschreitet die Grenze der zulässigen Rechtsausübung."]},"visual":null}],"quiz":[{"q":"Welche Rechte hat der Eigentümer gemäß BGB?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Er darf sein Eigentum unter Beachtung gültiger Rechtsnormen benutzen oder verbrauchen","c":true},{"t":"Er darf sein Eigentum uneingeschränkt nutzen. Gesetze oder Rechte anderer, z. B. von Nachbarn, muss er nicht beachten","c":false},{"t":"Er darf sein Eigentum im Rahmen gesetzlicher Bestimmungen verkaufen oder verschenken","c":true},{"t":"Er darf sein Eigentum mit allen Mitteln gegen unbefugte Eingriffe schützen und verteidigen","c":false}]},{"q":"Welche Aussagen zum Besitz bzw. Besitzer sind gemäß BGB richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Der Besitzer kann eine Sache soweit nutzen, wie es ihm der Eigentümer erlaubt hat","c":true},{"t":"Der Besitzer kann mit dem Besitz nach Belieben umgehen","c":false},{"t":"Der Besitz ist gegenüber unbefugten Eingriffen in gleicher Weise geschützt wie das Eigentum","c":true},{"t":"Unter Besitz versteht man allgemein nur bewegliche Sachen","c":false}]},{"q":"Was regelt das BGB?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Rechtsbeziehungen der Bürger untereinander","c":true},{"t":"Die Rechtsbeziehungen zwischen Bürgern und Behörden, z. B. zum Gewerbeamt","c":false},{"t":"Unter anderem das Sachenrecht und das Schikaneverbot","c":true},{"t":"Die Rechtsbeziehungen zwischen dem Bürger und dem Staat","c":false}]},{"q":"Welche Aussagen zum Besitzdiener sind gemäß § 855 BGB richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Besitzdiener ist, wer im Umgang mit einer Sache den Weisungen des Besitzers folgen muss und die Weisungen erfüllt, z. B. im Umgang mit Dienstfahrzeugen","c":true},{"t":"Ein Besitzdiener begeht verbotene Eigenmacht, wenn er im Umgang mit einer Sache nach eigenem Willen verfährt und dabei das Weisungsrecht des Besitzers missachtet","c":true},{"t":"Der weisungsberechtigte Besitzer muss zugleich auch der Eigentümer der Sache sein, die er dem Besitzdiener überlässt","c":false},{"t":"Besitzdiener haben an den vom Besitzer übernommenen Sachen unmittelbaren Besitz","c":false}]},{"q":"In welchen Fällen ist der Handelnde gemäß BGB in der Regel zum Schadensersatz verpflichtet?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Im Falle eines Verteidigungsnotstandes","c":false},{"t":"Im Falle einer unerlaubten Handlung","c":true},{"t":"Im Falle der Notwehr","c":false},{"t":"Im Falle von verbotener Eigenmacht, wenn durch diese ein Schaden entstanden ist","c":true}]},{"q":"Ab welchem Zeitpunkt ist der Mensch im Sinne des BGB Rechtsfähig?","a":"Ab Vollendung seiner Geburtbedeutet: ab diesem Zeitpunkt darf der Mensch die Rechte aus dem deutschen Rechtssystem (z.B.: Rechtsgüter gem. GG) in Anspruch nehmen, er hat aber auch die damit verbundenen Pflichten.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Selbsthilfe §229 BGB, Vorraussetzungen.","a":"Durchsetzung eines privatrechtlichen Anspruchs, notfalls mit Gewaltanwendung. - rechtlich einklagbarer Anspruch (z.B. Schadensersatz, Herausgabeanspruch) - obrigkeitliche Hilfe nicht rechtzeitig erreichbar - ohne sofortiges Eingreifen wird der Anspruch vereitelt oder wesentlich erschwert","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine Unerlaubte Handlung im BGB","a":"Unerlaubte Handlungen sind widerrechtliche Eingriffe in die Rechte einer Person (Freiheit, Gesundheit, Eigentum,...), die einen Anspruch auf Schadensersatz nach § 823 BGB fordern","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Kann aus einer verbotene Eigenmacht eine Unerlaubte Handlung","a":"werden und wenn ja, wie? Die verbotene Eigenmacht ist eine gegen fremden Besitz gerichtete Handlung, (z.B. Besitzstörung) durch einen Anspruch auf Schadenersatz wird die verbotene Eigenmacht zur unerlaubten Handlung (Fußball zerstört Scheibe)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was versteht man unter einem Anspruch?","a":"Es ist das Recht, von einem anderen etwas (Handeln oder Unterlassen) zu fordern Derjenige von dem ich dies fordern kann nennt sich Verpflichteter(er ist rechtlich verpflichtet, meinen Anspruch zu erfüllen)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Rechtfertigungsgründe gibt es im BGB?","a":"Notwehr/ Nothilfe > bei Angriff durch Menschen Verteidigungs-Notstand > bei Gefahr durch Sache oder Tier Angriffs-Notstand > bei Einwirken auf das Eigentum eines Dritten (zur Verteidigung vor Gefahr) Allgemeine Selbsthilfe > zur Sicherung eines (Rechts-)Anspruches Selbsthilfe des Besitzers / > zur Verteidigung (Schutz) seines Besitzes(Besitzdieners)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter der allgemeinen Selbsthilfe gem. §229 BGB?","a":"Ich kann damit einen gefährdeten Anspruch sichern wenn obrigkeitliche Hilfe nicht rechtzeitig zu bekommen ist die Sicherung erfolgt durch die Festnahme des Verpflichteten bis zum Eintreffen der obrigkeitlichen Hilfe (z.B.: Polizei) leistet der Verpflichtete Widerstand, kann dieser beseitigt werden ich kann Sachen wegnehmen, beschädigen oder zerstören.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist der Unterschied zwischen einer natürlichen und einer juristischen Person?","a":"Natürliche Person\t> sind Menschen Juristische Person\t> sind Unternehmen und/oder Verbände, Vereine, etc.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Erkläre §904 BGB Angriffsnotstand.","a":"Wen man in die Sache (Zaunlatte) einer unbeteiligten fremden Person eingreift um damit die gegenwärtige Gefahr abzuwenden. Der Besitzer muss dieses dulden, kann aber Schadenersatz verlangen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was darf der Besitzer einer Sache, was darf er nicht?","a":"Der Besitzer darf mit der Sache nicht alles machen, was er möchte, sondern nur das, was der Eigentümer ihm (z.B. vertraglich) erlaubt hat; z.B. Mietvertrag (Mieter hat Wohn/Hausrecht; darf aber nicht untervermieten)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere die Selbsthilfe des Besitzers §859 BGB","a":"Der Besitzer darf sich mit Besitzwehr und Besitzkehr gegen verbotene Eigenmacht wehren; (z.B. unbefugtes Zelten auf einer Wiese)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläute die Selbsthilfe des Besitzdieners §860 BGB","a":"Der Besitzdiener kann sich wie der Besitzer gegen die verbotene Eigenmacht mit Besitzwehr und Besitzkehr wehren, soweit ihm diese Rechte übertragen worden sind.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet eigentlich Verbotene Eigenmacht.","a":"Wer dem Besitzer eine Sache wegnimmt oder im Besitz stört, handelt widerrechtlich.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Unterschied Eigentümer, Besitzer, Besitzdiener?","a":"- Der Eigentümer hat die rechtliche Gewalt. - Der Besitzer hat die tatsächliche Gewalt. - Der Besitzdiener übt für den Besitzer die tatsächliche Gewalt aus, ist aber weisungsgebunden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Unterschied zwischen Diebstahl und Unterschlagung?","a":"Beim Diebstahl muss man sich erst das fremde Rechtsgut aneignen, bei der Unterschlagung ist man bereits Besitzer des fremden Rechtsgut.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist ein Besitzdiener?","a":"Ist Inhaber der tatsächlichen Gewalt (meist zeitlich begrenzt) Ist dem Besitzer gegenüber weisungsgebunden (meist durch Arbeitsvertrag) Hat die rechtlichen Befugnisse wie Besitzer im Sinne der Selbsthilfe (Selbsthilfe des Besitzdieners) Der Besitzdiener ist nicht der Besitzer","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter der verbotenen Eigenmacht?","a":"Besitzstörung oder Besitzentzug muss widerrechtlich erfolgen ohne Willen des Besitzers","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist der Unterschied zwischen einem Eigentümer und einem Besitzer?","a":"Eigentümer-hat die rechtliche Gewalt an einer Sache Besitzer-hat die tatsächliche Gewalt an einer Sache Eigentümer kann auch gleichzeitig der Besitzer sein","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter dem sogenannten (Angriffs-) Notstand gem. §904 BGB?","a":"Eigentum eines unbeteiligten Dritten Wegnehmen odernutzen (also „drauf einwirken“) Um mich oder einen anderen mit diesem Eigentum vor einer Gefahr zu schützen(folglich durch Notwehr oder (Verteidigungs-)Notstand) Dem Eigentümer bin ich zum Ersatz, des entstandenen Schaden(s) verpflichtet","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter der Selbsthilfe des Besitzers gem. § 859 BGB?","a":"Es muss eine verbotene Eigenmacht vorliegen\t> Besitzstörung / Besitzentzug, widerrechtlich und ohne Willen des Besitzers Ich darf mich dagegen mit Gewalt verteidigen (auf frischer Tat) Entzogenen Besitz darf ich mit Gewalt wieder abnehmen Gegen Besitzstörung die Besitzwehr Gegen Besitzentzug die Besitzkehr","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was können Sie mir zum Hausrecht sagen?","a":"Ist ein Recht, welches dem Eigentümer/Besitzer eines befriedeten Besitztums zusteht„es gestattet dem Rechtsinhaber zu entscheiden wer den Bereich betreten darf oder verlassen muss oder wie sich Gäste / Besucher darin zu benehmen haben“ Er hat das Hausrecht über seinen Hausrechtsbereich (Wohnung, Diskothek, etc.) Das Hausrecht kann auf andere übertragen werden (z.B.: Diskothekenbetreiber an Sicherheitsdienst) Das Hausrecht ist ein RECHTSGUT–es kann mit entsprechenden Rechtfertigungsgründen verteidigt werden","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Erkläre §228 BGB Verteidigungsnotstand.","a":"Wer eine fremde Sache von der eine drohende Gefahr ausgeht, beschädigt oder zerstört, handelt nicht widerrechtlich. (Verhältnismäßigkeit beachten !)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre den Unterschied Angriff und Gefahr.","a":"Ein Angriff geht von einen Menschen (auf ein geschütztes Rechtsgut) aus und die Gefahr von einer Sache/Situation.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Handlungen erlaubt die allgemeine Selbsthilfe nach","a":"§229 BGB? Eine Sache darf weggenommen, beschädigt oder zerstört werden; z.B. Fahrradschloss aufbrechen; Man darf die Person festnehmen (bei Fluchtverdacht). Man darf den Widerstand des Täters mit verhältnismäßiger Gewalt brechen die dieser dulden muss.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Definiere den Begriff \"Dinglicher Arrest\"","a":"Im Falle der Wegnahme von Sachen ist der dingliche Arrest zu beantragen; dies macht die Polizei.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre den Begriff Kausalität.","a":"Kausalität ist die Beziehung zwischen Ursache und Wirkung, betrifft also die Abfolge aufeinander bezogener Ereignisse.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §242 Diebstahl, Tatbestandsmerkmale (genaue Bezeichnung)","a":"Wegnahme einer fremden beweglichen Sache mit rechtswidriger Zueignungsabsicht (Stehlabsicht für sich selber oder Dritten).","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie wird ein einfacher Diebstahl zum besonders schweren","a":"Fall des Diebstahls gem. §243 StGB, Nenne alle Tatbestandsmerkmale. - In einen Geschäftsraum o.ä. einbrechen, einsteigen oder sich verborgen halten, - sich mit falschem Schlüssel Zutritt verschafft. - Eine Sache stiehlt die durch eine besondere Schutzvorrichtung gesichert ist, - Wer gewerbsmäßig stielt, Kirchendiebstahl, Museums-, Ausstellungsdiebstahl, - die Hilflosigkeit oder Unglücksfall anderer ausnutzt oder Handfeuerwaffen stehlen. In den Fällen des Absatzes 1 Satz 2 Nr. 1 bis 6 ist ein besonders schwerer Fall ausgeschlossen, wenn sich die Tat auf eine geringwertige Sache bezieht.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Diebstahl einer geringwertigen Sache gem. §248 StGB.","a":"Wird nur auf Antrag verfolgt, es sei denn es liegt ein besonderes öffentliches Interesse vor, Geringwertigkeit von ca. 50€.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §249 StGB Raub, Tatbestandsmerkmale.","a":"Der Täter will einer anderen Person durch Gewalt oder Anwendung von Drohungen mit gegenwärtiger Gefahr für Leib und Leben eine fremde bewegliche Sache wegnehmen; Erst hauen, dann klauen!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §303 StGB Sachbeschädigung, Tatbestandsmerkmale.","a":"Wer rechtswidrig eine fremde Sache beschädigt, zerstört, das Erscheinungs- bild unerheblich oder vorübergehend verändert begeht Sachbeschädigung.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine Tierhalterhaftung (Gefährdungshaftung) gem. §833 BGB?","a":"Wird durch ein Tier ein Mensch getötet, der Körper, Gesundheit eines Menschen verletzt oder eine Sache beschädigt, so ist derjenige, der das Tier hält verpflichtet den daraus entstandenen Schaden zu ersetzten.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine Sache, sind Tiere Sachen?","a":"Sachen sind nur körperliche Gegenstände (feste, flüssige, gasförmige) Tiere sind keine Sache, werden aber für Sachen geltende Gesetzte als dieses anzusehen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Ist die Polizei Ländersache?","a":"Polizei ist Ländersache, es gibt aber auch noch Bundespolizei, Bundeskriminalamt.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind Rechte und Pflichte eines Zeugen gem. der StPO.","a":"Der Zeuge muss vor Gericht erscheinen, zur Sache aussagen, er kann aber die Aussage verweigern wen er sich selbst belastet oder ein Familienangehörigen. 76 Zeugnis- bzw. Auskunftsverweigerungsrecht, was besagt dieses? Wen er sich selbst oder ein Familienangehörigen dadurch belastet, hat das Recht diese zu verweigern. Fallbeispiel: a) Jemand bricht mit einem Stemmeisen den Kofferraum eines PKW auf um zu stehlen, b) Jemand bricht mit einem Stemmeisen in eine Wohnung ein um zu stehlen ? Wo ist der Unterschied ? Der Unterschied ist zum einen der Tatbestand und zum anderen das Strafmaß Bei a) liegt ein Besonders schwerer Fall des Diebstahls gem. § 243 StGB Nr. 2 vor (eine Sache stiehlt, die durch ein verschlossenes Behältnis oder eine andere Schutzvorrichtung gegen Wegnahme besonders gesichert ist). Bei b) liegt ein Wohnungseinbruchsdiebstahl gemäß § 244 StGB vor (einen Diebstahl begeht, bei dem er zur Ausführung der Tat in eine Wohnung einbricht, einsteigt, mit einem falschen Schlüssel oder einem anderen nicht zur ordnungsmäßigen Öffnung bestimmten Werkzeug eindringt oder sich in der Wohnung verborgen hält)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was können Sie mir zum Thema Sachen sagen?","a":"Sachen sind körperliche Gegenstände Sachen können beweglich oder unbeweglich sein Tiere sind keine Sachen – sie werden durch besondere Gesetze geschützt-für sie werden jedoch die gleichen Rechtsvorschriften wie für Sachen genommen, wenn die speziellen Gesetze für Tier nicht greifen (z.B.: Notstand nach §228 BGB)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter dem (Verteidigungs-) Notstand gem. §228 BGB?","a":"Verteidigung gegen eine Gefahr durch Sache (oder Tier) Durch Beschädigung oder Zerstörung dieser Sache (von der die Gefahr ausgeht) rechtfertigt eine unerlaubte Handlung und befreit somit von Schadensersatz AUSSER !!!=Ich habe die Gefahr selbst verschuldet","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Warum ist ein Tierhalter nicht nach § 823 BGB (Schadensersatzpflicht), schadensersatzpflichtig?","a":"weil er eine „ausgelagerte“ Haftung hat die „Haftung des Tierhalters“ gem. § 833 BGB","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Pflichten ergeben sich bei einer Fundsache?","a":"Anzeigepflicht Verwahrpflicht Abgabepflicht","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wann ist ein Diebstahl ein Diebstahl (Tatbestände)?","a":"Eine fremde bewegliche Sache einem anderen wegnehmen (Wegnahmeabsicht) um sie sich oder einem Dritten rechtswidrig zueignen (Zueignungsabsicht)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist der Unterschied zwischen Diebstahl und Unterschlagung ?","a":"Diebstahl- „Wegnahmeabsicht“ und (rechtswidrige) „Zueignungsabsicht“ müssen vorliegen Unterschlagung- hier „fehlt die Wegnahmeabsicht“- es muss lediglich die (rechtswirdrige) „Zueignungsabsicht“ zu der fremden beweglichen Sache vorliegen- der Täter hat die Sache bereits","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist der besonders schwere Fall des Diebstahls ?","a":"Ein Diebstahl gem. §242 StGB + durch einbrechen mit falschem Schlüssel oder Werkzeug in Geschäftsräume, Lagerhallen, befriedetes Besitztum aus einem verschlossenen Behältnis gewerbsmäßig Hilflose Person bestehlen Aus Religionsgebäuden (Sachen zur Religionsausübung) Aus Museen, etc. (Sachen von bedeutendem Wert für Kunst, Geschichte, etc.) das stehlen erlaubnispflichtiger Waffen (!!! Nicht verwechseln mit dem „Diebstahl mit Waffen (§244 StGB)“ !!!)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist Diebstahl geringwertiger Sachen?","a":"Diebstahl von Sachen bis 50,00 € Wert","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was versteht man unter dem Straftatbestand der Hehlerei?","a":"Ein anderer hat eine Sache durch ein Vermögensdelikt rechtswidrig erlangt (Diebstahl, Raub, Unterschlagung, etc.) Der Hehler (Täter) kauft diese Sachen, verkauft sie oder, setzt sie ab oder hilft dabei oder erwirbt sie für sich selbst oder einen Dritten ! Der Stehler (z.B.: Dieb) ist nicht der Hehler !","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was genau steht im §823 BGB Schadensersatzplicht?","a":"Wer vorsätzlich oder fahrlässig das Leben, den Körper, die Gesundheit, die Freiheit, das Eigentum oder ein sonstiges Recht eines anderen widerrechtlich verletzt, ist zum Ersatz des daraus entstandenen Schadens verpflichtet.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"In welche Teile ist das StGB unterteilt?","a":"In den allgemeinen Teil (Voraussetzung der Strafbarkeit) und den besonderen Teil (Tatbestand der Straftat)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist ein Versuch und wann ist ein Versuch strafbar?","a":"Ein Versuch ist die Verwirklichung der Vorstellung von der Tat durch unmittelbares ansetzten (Zigarettenautomat aufbrechen) Jedes Verbrechen ist im Versuch strafbar. Beim Vergehen ist der Versuch nur strafbar, wenn durch ein Gesetz bestimmt ist; z.B. Diebstahl","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie die 3 echten Unterlassungsdelikte und was sind unechte","a":"Unterlassungsdelikte? „Echte“ Unterlassungsdelikte stehen echt im Gesetz (Text/Tatbestand); Es sind Straftaten die auf Unterlassung beruhen; Merke: keine Garantenpflicht! (Nichtanzeige von Straftaten, unterlassene Hilfeleistung, Hausfriedensbruch (2te Begehungsart = Verweilen trotz Aufforderung) „Unechte“ Unterlassungsdelikte liegen vor wen jemand rechtlich dazu verpflichtet ist (Garantenstellung) und es unterlässt eine strafbare Handlung abzuwenden, diese werden im §13 StGB zusammengefasst; z.B. nicht Salzstreuen, keine Fahrzeugkontrolle durchführen, Unterschied liegt in der Bestrafung! Garant wird bei Unterlassen wie Täter bestraft; z.B. Ladendetektiv lässt absichtlich Bekannten mit Diebesgut flüchten (§ 242,13 StGB, Diebstahl durch Unterlassen !)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Ab wann ist ein Kind Schadenersatzpflichtig bzw. Strafbar?","a":"Ein Kind ist ab den 7ten Lebensjahr Schadenersatzpflichtig. Ein Kind ist ab den 14ten Lebensjahr Strafbar.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Ab welchem Alter ist der Mensch gemäß BGB schadensersatzpflichtig?","a":"Ab dem vollendeten siebenten Lebensjahr-also mit seinem „7. Geburtstag“","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wann ist der Versuch einer Straftat strafbar?","a":"Vergehen- nur strafbar, wenn es das Gesetz (der jeweilige Paragraph) ausdrücklich bestimmt Verbrechen- der Versuch ist immer strafbar","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was muss für eine strafbare Handlung erfüllt sein ?","a":"Tatbestandsmäßigkeit Rechtswidrigkeit Schuldfähigkeit Wenn nur einer der drei Punkte nicht erfüllt ist, ist es keinestrafbare Handlung und folglich keine Straftat","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wer kann sich einem Missbrauch von Ausweispapieren strafbar machen?","a":"Den Ausweis eines anderen zur Täuschung im Rechtsverkehr nutzen / gebrauchen Wer einem anderen zur Täuschung im Rechtsverkehr seinen Ausweis überlässt Täuschung im Rechtsverkehr = rechtlichen Vorteil verschaffen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Tatbestandsmerkmale hat die Nötigung?","a":"Einen anderen Menschen durch Anwendung von Gewalt oder Androhung von Gewalt oder empfindliches Übel zu einem Tun, Dulden oder Unterlassen nötigen !!! Der Versuch ist strafbar !!!","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist ein sogenanntes Schikaneverbot?","a":"Die Ausübung eines Rechtes ist dann unzulässig, wenn sie nur den Zweck haben kann, einem anderen einen Schaden zuzufügen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie unter Schikaneverbot gem. BGB?","a":"ein Recht ausnutzen nur um jemand anderen einen Schaden zuzufügen","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[]},{"n":2,"title":"BGB – Besitzschutz & Selbsthilfe","subtitle":"6 Konzepte · 14 Prüfungsfragen","cards":[{"h":"Verbotene Eigenmacht","b":"Wegnahme/Störung des Besitzes; widerrechtlich","detail":{"titel":"Verbotene Eigenmacht","kat":"BGB · Besitzschutz","katCls":"bgb","merksatz":"Verbotene Eigenmacht ist jede widerrechtliche Störung oder Entziehung des Besitzes ohne den Willen des Besitzers (§ 858 BGB) – sie ist der Auslöser aller Selbsthilferechte.","funktion":["Zwei Formen: Besitzentziehung (dem Besitzer wird die Sache ganz weggenommen) und Besitzstörung (der Besitz wird beeinträchtigt, ohne ganz entzogen zu werden).","Widerrechtlich und ohne Willen des Besitzers: Es fehlt eine Erlaubnis des Besitzers oder des Gesetzes.","Folge: Der Besitzer und sein Besitzdiener dürfen sich mit Selbsthilfe wehren; außerdem kann verbotene Eigenmacht eine unerlaubte Handlung (§ 823) sein."],"schutzziel":"Den Besitz – also die tatsächliche Sachherrschaft – gegen eigenmächtige Eingriffe schützen, unabhängig davon, wem die Sache gehört.","kennwerte":[{"l":"Form 1","v":"Besitzentziehung – Wegnahme"},{"l":"Form 2","v":"Besitzstörung – Beeinträchtigung"},{"l":"Merkmal","v":"widerrechtlich, ohne Willen des Besitzers (§ 858)"}],"begriffe":["Besitzentziehung = der Besitzer verliert die tatsächliche Gewalt über die Sache ganz (z. B. Diebstahl).","Besitzstörung = der Besitz wird beeinträchtigt, aber nicht ganz entzogen (z. B. unbefugtes Betreten, Blockieren der Einfahrt).","Fehlerhafter Besitz = der durch verbotene Eigenmacht erlangte Besitz."],"abgrenzung":["Verbotene Eigenmacht schützt den BESITZ (das Haben), nicht das Eigentum – auch ein Dieb ‚besitzt‘; die Selbsthilferechte hat aber der rechtmäßige Besitzer.","Hoheitliche Eingriffe (z. B. eine Beschlagnahme nach der StPO) sind keine verbotene Eigenmacht – sie sind durch Gesetz erlaubt."],"praxis":["Wer unbefugt das bewachte Gelände betritt oder eine Sache wegnimmt, begeht verbotene Eigenmacht – die rechtliche Grundlage, auf der deine Selbsthilferechte aufbauen.","Erkennst du die Form (Entziehung oder Störung), weißt du, ob Besitzwehr oder Besitzkehr in Betracht kommt."]},"visual":null},{"h":"Selbsthilfe des Besitzers §859","b":"Besitzwehr & Besitzkehr; frische Tat (~30 Min.)","detail":{"titel":"Selbsthilfe des Besitzers § 859 BGB","kat":"BGB · Besitzschutz","katCls":"bgb","merksatz":"Der Besitzer darf sich verbotener Eigenmacht mit Gewalt erwehren (Besitzwehr) und eine frisch entzogene Sache sofort zurückholen (Besitzkehr) – § 859 BGB.","funktion":["Besitzwehr (§ 859 Abs. 1): Der Besitzer darf sich verbotener Eigenmacht mit Gewalt erwehren – also die laufende Störung oder Entziehung abwehren.","Besitzkehr (§ 859 Abs. 2/3): Wird eine bewegliche Sache durch verbotene Eigenmacht entzogen, darf der Besitzer sie dem auf frischer Tat betroffenen oder verfolgten Täter mit Gewalt wieder abnehmen.","Voraussetzung der Besitzkehr: ‚auf frischer Tat‘ – sofort, in unmittelbarem zeitlichen Zusammenhang (Faustregel etwa 30 Minuten bzw. solange der Täter verfolgt wird)."],"schutzziel":"Dem Besitzer ein sofortiges, eigenes Abwehr- und Rückholrecht geben, ohne erst die Polizei abwarten zu müssen.","kennwerte":[{"l":"Besitzwehr","v":"laufende Eigenmacht mit Gewalt abwehren (Abs. 1)"},{"l":"Besitzkehr","v":"frisch entzogene Sache zurückholen (Abs. 2/3)"},{"l":"Frische Tat","v":"sofort / auf frischer Tat betroffen oder verfolgt"}],"begriffe":["Besitzwehr = Abwehr der noch andauernden verbotenen Eigenmacht.","Besitzkehr = Wiederbeschaffung der gerade entzogenen Sache vom frisch betroffenen Täter.","Auf frischer Tat = unmittelbar bei oder direkt nach der Tat, solange noch ein enger zeitlicher und örtlicher Zusammenhang besteht."],"abgrenzung":["Besitzwehr richtet sich gegen die NOCH laufende Eigenmacht; Besitzkehr setzt ein, wenn die Sache bereits entzogen ist, der Täter aber noch frisch betroffen oder verfolgt wird.","Ist die frische Tat vorbei (Täter entkommen, längere Zeit vergangen), gibt es keine Besitzkehr mehr – dann bleibt nur die allgemeine Selbsthilfe (§ 229) oder die Polizei."],"praxis":["Du darfst einen Dieb, der gerade Ware mitnimmt, stoppen (Besitzwehr) und ihm die soeben entwendete Sache wieder abnehmen (Besitzkehr) – mit angemessenem, erforderlichem Zwang.","Wichtig: nur die soeben entzogene Sache, nur mit erforderlicher Gewalt, nur auf frischer Tat."]},"visual":null},{"h":"Selbsthilfe des Besitzdieners §860","b":"Übertragenes Selbsthilferecht – wichtig für SMA","detail":{"titel":"Selbsthilfe des Besitzdieners § 860 BGB","kat":"BGB · Besitzschutz","katCls":"bgb","merksatz":"Der Besitzdiener darf die Selbsthilferechte des Besitzers (Besitzwehr und Besitzkehr) ausüben – § 860 BGB macht die Wachperson zum ‚verlängerten Arm‘ des Besitzers.","funktion":["Der Besitzdiener (z. B. die Wachperson) darf die dem Besitzer nach § 859 zustehende Gewalt ausüben – Besitzwehr und Besitzkehr.","Er handelt dabei für den Besitzherrn (Auftraggeber), nicht für sich selbst.","Das ist die zentrale zivilrechtliche Grundlage für das Einschreiten der Wachperson gegen Störer und Diebe."],"schutzziel":"Dem Besitzdiener erlauben, den Besitz des Besitzherrn aktiv zu verteidigen, obwohl er selbst kein Besitzer ist.","kennwerte":[{"l":"Berechtigter","v":"Besitzdiener (z. B. Wachperson)"},{"l":"Rechte","v":"Besitzwehr & Besitzkehr (über § 859)"},{"l":"Für wen","v":"für den Besitzherrn / Auftraggeber"}],"begriffe":["Besitzdiener = wer die Sachherrschaft für einen anderen weisungsgebunden ausübt (§ 855).","Besitzherr = derjenige, für den der Besitzdiener den Besitz ausübt."],"abgrenzung":["§ 860 gibt dem Besitzdiener KEINE eigenen, weitergehenden Rechte – er darf nur das, was auch der Besitzer nach § 859 dürfte (Besitzwehr/Besitzkehr, auf frischer Tat).","Anders als die allgemeine Selbsthilfe (§ 229) ist § 860 an den Besitz und die frische Tat gebunden."],"praxis":["Als Wachperson stützt du dein Einschreiten gegen Besitzstörungen und Entziehungen auf §§ 859, 860 BGB – du verteidigst den Besitz des Auftraggebers.","Du darfst dabei nur erforderliche, angemessene Gewalt einsetzen und nur die frisch betroffene Lage bereinigen."]},"visual":null},{"h":"Allgemeine Selbsthilfe §229","b":"4 Voraussetzungen; einklagbarer Anspruch, Fluchtverdacht, keine obrigkeitliche Hilfe","detail":{"titel":"Allgemeine Selbsthilfe § 229 BGB","kat":"BGB · Selbsthilfe","katCls":"bgb","merksatz":"Wer einen einklagbaren Anspruch hat und keine rechtzeitige obrigkeitliche Hilfe bekommt, darf zur Sicherung notfalls selbst eingreifen – die allgemeine Selbsthilfe nach § 229 BGB.","funktion":["Vier Voraussetzungen: (1) ein einklagbarer, nicht verjährter Anspruch, (2) obrigkeitliche (staatliche) Hilfe ist nicht rechtzeitig zu erlangen, (3) ohne sofortiges Eingreifen droht die Vereitelung oder wesentliche Erschwerung der Anspruchsdurchsetzung, (4) Fluchtverdacht bzw. Gefahr für die Durchsetzung.","Erlaubte Handlungen: eine Sache wegnehmen, zerstören oder beschädigen; einen fluchtverdächtigen Verpflichteten festnehmen; den Widerstand eines zur Duldung Verpflichteten brechen.","Pflicht bei Irrtum (§ 231): Wer irrtümlich Selbsthilfe übt, ist zum Schadensersatz verpflichtet – auch ohne Verschulden."],"schutzziel":"Den Berechtigten in Eilfällen davor schützen, dass sein Anspruch verloren geht, weil der Staat nicht rechtzeitig helfen kann.","kennwerte":[{"l":"Voraussetzung 1","v":"einklagbarer, nicht verjährter Anspruch"},{"l":"Voraussetzung 2","v":"keine rechtzeitige obrigkeitliche Hilfe"},{"l":"Voraussetzung 3/4","v":"Vereitelungsgefahr · Fluchtverdacht"}],"begriffe":["Obrigkeitliche Hilfe = Hilfe durch staatliche Stellen, vor allem die Polizei.","Einklagbarer Anspruch = ein Anspruch, den man notfalls vor Gericht durchsetzen könnte.","Festnahme zur Selbsthilfe = vorläufiges Festhalten des fluchtverdächtigen Verpflichteten, mit anschließender Übergabe an die Polizei."],"abgrenzung":["Anders als die Besitzkehr (§ 859) setzt § 229 keinen Besitz und keine frische Tat voraus – aber es muss ein einklagbarer Anspruch bestehen und staatliche Hilfe darf nicht rechtzeitig kommen.","§ 229 erlaubt nur die SICHERUNG des Anspruchs, nicht seine endgültige Durchsetzung (kein ‚Selbst-Recht-Verschaffen‘)."],"praxis":["Klassiker: Du erkennst dein gestohlenes Diensteigentum bei einem Unbekannten, der es gerade mitnehmen will. Verweigert er die Personalien und will sich entfernen, darfst du ihn bis zur Polizei festhalten (§ 229).","Aber: Du darfst ihn nicht durchsuchen und nicht ‚bestrafen‘ – nur den Anspruch sichern und die Polizei rufen."]},"visual":null},{"h":"Grenzen der Selbsthilfe §230","b":"Nur bis zur Gefahrenabwehr; dinglicher Arrest","detail":{"titel":"Grenzen der Selbsthilfe § 230 BGB","kat":"BGB · Selbsthilfe","katCls":"bgb","merksatz":"Selbsthilfe darf nie weiter gehen, als zur Abwehr der Gefahr nötig ist (§ 230 BGB) – danach ist sofort staatliche Hilfe einzuschalten.","funktion":["Grenze: Die Selbsthilfe darf nicht weiter gehen, als zur Abwendung der Gefahr erforderlich ist (§ 230 Abs. 1) – also kein Übermaß.","Folgepflichten: Bei einer Wegnahme von Sachen ist der dingliche Arrest zu beantragen; bei einer Festnahme ist der Festgenommene unverzüglich der zuständigen Behörde (Polizei) zuzuführen.","Verzögerung verboten: Die staatliche Hilfe ist ohne schuldhaftes Zögern in Anspruch zu nehmen."],"schutzziel":"Verhindern, dass aus erlaubter Selbsthilfe Selbstjustiz wird – Selbsthilfe ist nur Überbrückung bis zum Eingreifen des Staates.","kennwerte":[{"l":"Maß","v":"nur so weit wie zur Gefahrenabwehr nötig"},{"l":"Nach Festnahme","v":"unverzüglich der Polizei zuführen"},{"l":"Nach Wegnahme","v":"dinglichen Arrest beantragen"}],"begriffe":["Dinglicher Arrest = gerichtliche Sicherung eines Anspruchs durch Beschlagnahme von Vermögen.","Unverzüglich = ohne schuldhaftes Zögern (so schnell wie zumutbar)."],"abgrenzung":["§ 229 erlaubt das Eingreifen, § 230 begrenzt es: nur so viel wie nötig und nur als Überbrückung bis zur staatlichen Hilfe.","Wer über das Erforderliche hinausgeht (z. B. den Festgehaltenen länger als nötig festhält), überschreitet die Grenze und macht sich angreifbar (Schadensersatz, ggf. Freiheitsberaubung)."],"praxis":["Hast du jemanden nach § 229 festgehalten, musst du sofort die Polizei rufen und ihn ihr übergeben – nicht ‚verhören‘, nicht länger festhalten als nötig.","Maßnahmen immer auf das Erforderliche beschränken: das mildeste geeignete Mittel, sofort beenden, sobald die Gefahr weg ist."]},"visual":null},{"h":"Fundrecht","b":"Anzeige §965, Verwahrung §966, Finderlohn §971 (5%/3%), Eigentum §973; SMA als Fremdfirma kein Finderlohn","detail":{"titel":"Fundrecht §§ 965 ff. BGB","kat":"BGB · Fundrecht","katCls":"bgb","merksatz":"Wer eine verlorene Sache findet, muss sie anzeigen und verwahren (§§ 965, 966) – nach sechs Monaten kann er Eigentum erwerben (§ 973) und hat Anspruch auf Finderlohn (§ 971).","funktion":["Anzeigepflicht (§ 965): Der Finder muss den Fund dem Verlierer/Eigentümer oder der zuständigen Behörde anzeigen (Bagatellgrenze: bei einem Wert unter 10 Euro keine Anzeigepflicht).","Verwahrungspflicht (§ 966): Der Finder muss die Sache sorgfältig verwahren.","Eigentumserwerb (§ 973): Nach Ablauf von sechs Monaten seit Anzeige erwirbt der Finder grundsätzlich das Eigentum, wenn sich kein Berechtigter meldet.","Finderlohn (§ 971): bis 500 Euro Sachwert 5 %, von dem Mehrwert darüber 3 %."],"schutzziel":"Einen fairen Ausgleich schaffen zwischen dem Eigentümer (er soll seine Sache zurückbekommen) und dem ehrlichen Finder (er soll belohnt werden).","kennwerte":[{"l":"Anzeige/Verwahrung","v":"§ 965 / § 966"},{"l":"Finderlohn","v":"5 % bis 500 €, darüber 3 % (§ 971)"},{"l":"Eigentum","v":"nach 6 Monaten (§ 973)"}],"begriffe":["Fund = das Entdecken UND An-sich-Nehmen einer verlorenen Sache.","Verlorene Sache = besitzlos, aber nicht herrenlos (sie hat noch einen Eigentümer).","Finderlohn = die gesetzliche Belohnung des ehrlichen Finders."],"abgrenzung":["Eine verlorene Sache (noch ein Eigentümer) ist etwas anderes als eine herrenlose Sache (aufgegebenes Eigentum) – nur Verlorenes unterliegt dem Fundrecht.","Wichtig für die Praxis: Wer im Dienst (als Angestellter einer Fremdfirma) auf fremdem Gelände etwas findet, hat in der Regel keinen Finderlohnanspruch – der Fund fällt dem Betrieb bzw. der zuständigen Stelle zu."],"praxis":["Findest du im Dienst eine Sache, gibst du sie an die Fundstelle des Auftraggebers bzw. die zuständige Stelle – nicht behalten, nicht ‚liegen lassen‘.","Einen eigenen Finderlohn kannst du als Wachperson auf fremdem Gelände regelmäßig nicht beanspruchen."]},"visual":null}],"quiz":[{"q":"Wann liegt verbotene Eigenmacht gemäß BGB vor?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wenn bei einer Person ohne ihre Zustimmung aufgrund der StPO eine Tatwaffe beschlagnahmt wird","c":false},{"t":"Wenn eine Person ohne ihre Zustimmung in ihrem Besitz widerrechtlich gestört wird","c":true},{"t":"Wenn einer Person ohne ihre Zustimmung widerrechtlich Besitz entzogen wird","c":true},{"t":"Wenn eine Person ohne ihre Zustimmung widerrechtlich festgehalten wird","c":false}]},{"q":"Was ist verbotene Eigenmacht gemäß BGB?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Person C betritt unberechtigt einen Veranstaltungsraum","c":true},{"t":"Person E nimmt zur Sicherung eines Anspruchs den Schuldner F fest","c":false},{"t":"Person A schlägt grundlos Person B zu Boden","c":false},{"t":"Person D überschreitet mit ihrem Pkw die zulässige Höchstgeschwindigkeit","c":false}]},{"q":"Welche Selbsthilferechte haben der Besitzer und der Besitzdiener gemäß BGB, wenn verbotene Eigenmacht vorliegt?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sie dürfen bei einer Besitzentziehung auch noch Tage später die Besitzkehr durchführen","c":false},{"t":"Sie dürfen sich einer Besitzentziehung mit Gewalt erwehren","c":true},{"t":"Sie dürfen sich der verbotenen Eigenmacht erst dann mit Gewalt erwehren, wenn Hilfe durch die Polizei nicht rechtzeitig zu erwarten ist","c":false},{"t":"Sie dürfen sich einer Besitzstörung mit Gewalt erwehren","c":true}]},{"q":"Gemäß §§ 855 und 860 BGB darf der Besitzdiener die Rechte ausüben, die dem Besitzer zustehen. Auf welche Fälle trifft dies zu?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Er darf sich mit Gewalt einer Besitzstörung erwehren, die gegen den Besitzer gerichtet ist","c":true},{"t":"Er darf zur Durchsetzung eines Anspruchs zugunsten des Besitzers den Täter festnehmen, wenn er der Flucht verdächtig ist","c":false},{"t":"Er darf eine gegen den Besitz des Besitzherrn gerichtete gegenwärtige Gefahr abwenden","c":false},{"t":"Er darf eine dem Besitzer weggenommene Sache dem auf frischer Tat betroffenen oder verfolgten Täter notfalls mit Gewalt abnehmen","c":true}]},{"q":"Damit die allgemeine Selbsthilfe gemäß § 229 BGB zulässig ist, müssen bestimmte Voraussetzungen erfüllt sein. Welche gehören dazu?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Der Täter muss auf frischer Tat verfolgt werden","c":false},{"t":"Obrigkeitliche Hilfe kann nicht rechtzeitig erlangt werden","c":true},{"t":"Es muss ein gegenwärtiger und rechtswidriger Angriff vorliegen","c":false},{"t":"Ohne sofortiges Einschreiten besteht die Gefahr, dass die Anspruchsverwirklichung vereitelt oder wesentlich erschwert wird","c":true}]},{"q":"Kaufhausdetektiv K beobachtet, wie ein Kunde beim Ausparken einen anderen Pkw beschädigt. Der Täter besichtigt die Schäden und will unerkannt wegfahren. Das beschädigte Fahrzeug ist Eigentum des Kaufhauses. K verhindert die Weiterfahrt, nimmt den Widerstand leistenden Täter fest und übergibt ihn der Polizei. Die Selbsthilferechte sind auf K übertragen. Hat sich K gemäß BGB richtig verhalten?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Ja, K durfte sein Einschreiten auf die allgemeine Selbsthilfe gemäß § 229 BGB stützen","c":true},{"t":"Ja, K durfte sein Einschreiten auf den Verteidigungsnotstand gemäß § 228 BGB stützen","c":false},{"t":"Nein, K darf eine Festnahme nur bei Vorliegen einer Straftat nach § 127 Abs. 1 StPO durchführen","c":false},{"t":"Ja, K durfte sein Einschreiten auf die Selbsthilferechte des Besitzdieners gemäß §§ 859, 860 BGB stützen, weil der Kunde eine Besitzstörung beging","c":false}]},{"q":"Kinder §19 StGB, Welche 3 Eingriffsrechte habe ich?","a":"Man darf Sie festnehmen (Allgemeine Selbsthilfe, § 229 BGB), Diebesgut abnehmen (Besitzkehr, § 860 BGB), gegenwärtigen rechtswidrigen Angriff auf Eigentum abwehren (Notwehr, § 32 StGB).","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere die Selbsthilfe des Besitzers §859 BGB","a":"Der Besitzer darf sich mit Besitzwehr und Besitzkehr gegen verbotene Eigenmacht wehren; (z.B. unbefugtes Zelten auf einer Wiese)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläute die Selbsthilfe des Besitzdieners §860 BGB","a":"Der Besitzdiener kann sich wie der Besitzer gegen die verbotene Eigenmacht mit Besitzwehr und Besitzkehr wehren, soweit ihm diese Rechte übertragen worden sind.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet eigentlich Verbotene Eigenmacht.","a":"Wer dem Besitzer eine Sache wegnimmt oder im Besitz stört, handelt widerrechtlich.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie handelt man auf Besitzstörung und Besitzentzug?","a":"Mit Besitzwehr und Besitzkehr.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Definition \"Auf frischer Tat\" in Bezug auf die verbotene Eigenmacht.","a":"Wenn der Besitz durch verbotene Eigenmacht entzogen wurde darf er sich nur in einem engen zeitlichen Abstand wehren.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Kann aus einer verbotene Eigenmacht eine Unerlaubte Handlung","a":"werden und wenn ja, wie? Die verbotene Eigenmacht ist eine gegen fremden Besitz gerichtete Handlung, (z.B. Besitzstörung) durch einen Anspruch auf Schadenersatz wird die verbotene Eigenmacht zur unerlaubten Handlung (Fußball zerstört Scheibe)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie unter der verbotenen Eigenmacht?","a":"Besitzstörung oder Besitzentzug muss widerrechtlich erfolgen ohne Willen des Besitzers","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter der Selbsthilfe des Besitzers gem. § 859 BGB?","a":"Es muss eine verbotene Eigenmacht vorliegen\t> Besitzstörung / Besitzentzug, widerrechtlich und ohne Willen des Besitzers Ich darf mich dagegen mit Gewalt verteidigen (auf frischer Tat) Entzogenen Besitz darf ich mit Gewalt wieder abnehmen Gegen Besitzstörung die Besitzwehr Gegen Besitzentzug die Besitzkehr","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Selbsthilfe §229 BGB, Vorraussetzungen.","a":"Durchsetzung eines privatrechtlichen Anspruchs, notfalls mit Gewaltanwendung. - rechtlich einklagbarer Anspruch (z.B. Schadensersatz, Herausgabeanspruch) - obrigkeitliche Hilfe nicht rechtzeitig erreichbar - ohne sofortiges Eingreifen wird der Anspruch vereitelt oder wesentlich erschwert","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Handlungen erlaubt die allgemeine Selbsthilfe nach","a":"§229 BGB? Eine Sache darf weggenommen, beschädigt oder zerstört werden; z.B. Fahrradschloss aufbrechen; Man darf die Person festnehmen (bei Fluchtverdacht). Man darf den Widerstand des Täters mit verhältnismäßiger Gewalt brechen die dieser dulden muss.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie unter der allgemeinen Selbsthilfe gem. §229 BGB?","a":"Ich kann damit einen gefährdeten Anspruch sichern wenn obrigkeitliche Hilfe nicht rechtzeitig zu bekommen ist die Sicherung erfolgt durch die Festnahme des Verpflichteten bis zum Eintreffen der obrigkeitlichen Hilfe (z.B.: Polizei) leistet der Verpflichtete Widerstand, kann dieser beseitigt werden ich kann Sachen wegnehmen, beschädigen oder zerstören.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Nenne die Grenzen der Selbsthilfe gemäß § 230 BGB","a":"Die Selbsthilfe darf nicht weiter gehen als bis zur Abwendung der Gefahr; (bis Polizei vor Ort ist oder Personalien bekannt sind)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Pflichten ergeben sich bei einer Fundsache?","a":"Anzeigepflicht Verwahrpflicht Abgabepflicht","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[]},{"n":3,"title":"Rechtfertigungsgründe (Notwehr & Notstände)","subtitle":"10 Konzepte · 25 Prüfungsfragen","cards":[{"h":"Notwehr §227 BGB / §32 StGB","b":"Verteidigung gegen gegenwärtigen rechtswidrigen Angriff; 3 Gesetze (§227 BGB/§32 StGB/§15 OWiG)","detail":{"titel":"Notwehr § 227 BGB / § 32 StGB","kat":"Notwehr · Überblick","katCls":"recht","merksatz":"Notwehr ist die Verteidigung, die erforderlich ist, um einen gegenwärtigen rechtswidrigen Angriff von sich oder einem anderen abzuwenden – wer in Notwehr handelt, handelt nicht rechtswidrig.","funktion":["Dreifach geregelt: § 227 BGB (zivilrechtlich – keine Schadensersatzpflicht), § 32 StGB (strafrechtlich – keine Strafe) und § 15 OWiG (Ordnungswidrigkeiten). Inhaltlich identisch.","Aufbau: Es braucht eine Notwehrlage (gegenwärtiger rechtswidriger Angriff) und eine Notwehrhandlung (erforderliche Verteidigung).","Wirkung: Die Tat ist gerechtfertigt – also weder rechtswidrig noch strafbar; es entsteht keine Schadensersatzpflicht gegenüber dem Angreifer."],"schutzziel":"Dem Angegriffenen erlauben, sich (oder andere) sofort und wirksam gegen Unrecht zu verteidigen, ohne dafür bestraft zu werden oder zu haften.","kennwerte":[{"l":"§ 227 BGB","v":"keine Schadensersatzpflicht"},{"l":"§ 32 StGB","v":"keine Strafe"},{"l":"Aufbau","v":"Notwehrlage + Notwehrhandlung"}],"begriffe":["Rechtfertigungsgrund = ein Umstand, der eine an sich verbotene Handlung erlaubt macht.","Jedermannsrecht = ein Recht, das jeder hat (nicht nur Behörden) – Notwehr ist das wichtigste."],"abgrenzung":["Notwehr (gegen einen menschlichen Angriff) ist abzugrenzen vom Notstand (Gefahr durch Sachen, Tiere oder allgemeine Lagen).","Das Recht ist in BGB, StGB und OWiG gleich – nur die Rechtsfolge unterscheidet sich (keine Haftung / keine Strafe / keine Geldbuße)."],"praxis":["Notwehr und Nothilfe sind die wichtigsten Jedermannsrechte, auf die du dich als Wachperson stützt – du hast sie wie jeder Bürger, nicht als Sonderbefugnis.","Wer die Voraussetzungen kennt, kann im Ernstfall richtig und straffrei handeln – und Überschreitungen vermeiden."]},"visual":null},{"h":"Notwehrlage","b":"Gegenwärtig, rechtswidrig, Angriff","detail":{"titel":"Notwehrlage","kat":"Notwehr · Lage","katCls":"recht","merksatz":"Eine Notwehrlage ist ein gegenwärtiger, rechtswidriger Angriff – fehlt eines dieser drei Merkmale, gibt es keine Notwehr.","funktion":["Angriff: eine von einem Menschen ausgehende Bedrohung eines Rechtsguts (durch Tun, ausnahmsweise Unterlassen).","Gegenwärtig: der Angriff steht unmittelbar bevor, hat begonnen oder dauert noch an – nicht vorbei und nicht bloß zukünftig.","Rechtswidrig: der Angriff ist nicht seinerseits durch ein Recht gedeckt (wer rechtmäßig handelt, ‚greift‘ nicht im Sinne der Notwehr an)."],"schutzziel":"Genau festlegen, WANN man sich verteidigen darf – nur gegen einen echten, laufenden, unrechtmäßigen Angriff.","kennwerte":[{"l":"Merkmal 1","v":"Angriff (von einem Menschen)"},{"l":"Merkmal 2","v":"gegenwärtig (bevorstehend/andauernd)"},{"l":"Merkmal 3","v":"rechtswidrig"}],"begriffe":["Gegenwärtig = unmittelbar bevorstehend, gerade stattfindend oder noch fortdauernd.","Drohende Gefahr (künftig) ist NICHT gegenwärtig – gegen sie gibt es noch keine Notwehr.","Rechtswidriger Angriff = ein Angriff, den der Angegriffene nicht dulden muss."],"abgrenzung":["Ein bereits beendeter Angriff begründet keine Notwehr mehr – die Reaktion wäre Vergeltung.","Ein rechtmäßiger ‚Angriff‘ (z. B. eine rechtmäßige Festnahme) ist kein Angriff im Notwehrsinn – dagegen gibt es keine Notwehr."],"praxis":["Prüfe immer zuerst: Läuft der Angriff JETZT? Nur dann darfst du dich wehren. Ein ‚Er hat mich vorhin geschubst‘ rechtfertigt keinen Schlag hinterher.","Auch der Angriff eines Kindes oder einer verwirrten Person ist rechtswidrig und damit notwehrfähig – aber die Verteidigung muss besonders zurückhaltend bleiben."]},"visual":null},{"h":"Notwehrhandlung","b":"Erforderlich, mildestes geeignetes Mittel, gegen den Angreifer","detail":{"titel":"Notwehrhandlung","kat":"Notwehr · Handlung","katCls":"recht","merksatz":"Die Notwehrhandlung muss erforderlich sein: das mildeste geeignete Mittel, das den Angriff sofort und sicher beendet – und sie richtet sich nur gegen den Angreifer.","funktion":["Erforderlich: geeignet, den Angriff sofort zu beenden, und das mildeste unter mehreren gleich geeigneten Mitteln.","Gegen den Angreifer: die Verteidigung darf sich nur gegen den Angreifer und seine Rechtsgüter richten, nicht gegen Unbeteiligte.","Keine generelle Androhungspflicht: Der Angegriffene darf den Angriff sofort beenden; er muss z. B. nicht stets den Einsatz eines Mittels vorher androhen, wenn dadurch die Verteidigung unsicher würde."],"schutzziel":"Wirksame Verteidigung erlauben, aber Übermaß verhindern – nur so viel Gegenwehr wie nötig.","kennwerte":[{"l":"Erforderlich","v":"geeignet + mildestes Mittel"},{"l":"Ziel","v":"nur gegen den Angreifer"},{"l":"Maß","v":"so viel wie nötig, nicht mehr"}],"begriffe":["Erforderlichkeit = das mildeste unter den geeigneten Verteidigungsmitteln.","Geeignet = in der Lage, den Angriff sofort zu beenden oder abzuschwächen.","Schutzwehr (abwehren) vor Trutzwehr (aktiv gegenangreifen) – zuerst das Mildere, wenn es genügt."],"abgrenzung":["Anders als beim Notstand (§ 34) ist bei der Notwehr keine umfassende Güterabwägung nötig – aber das Mittel muss erforderlich sein und darf nicht krass außer Verhältnis stehen.","Die Verteidigung gegen Kinder, erkennbar Betrunkene oder Verwirrte muss besonders zurückhaltend sein (eingeschränktes Notwehrrecht)."],"praxis":["Stehen mehrere Mittel zur Wahl, nimm das mildeste, das sicher wirkt – erst festhalten/abdrängen, bevor härtere Mittel.","Sobald der Angriff beendet ist, ist sofort Schluss – jedes weitere Zuschlagen ist keine Notwehr mehr."]},"visual":null},{"h":"Notwehrfähige Rechtsgüter","b":"Leben, Leib, Freiheit, Ehre, Eigentum","detail":{"titel":"Notwehrfähige Rechtsgüter","kat":"Notwehr · Rechtsgüter","katCls":"recht","merksatz":"Mit Notwehr darf man fast alle Individualrechtsgüter verteidigen – Leben, Leib, Freiheit, Ehre und Eigentum –, aber keine reinen Allgemeininteressen.","funktion":["Notwehrfähig sind individuelle Rechtsgüter: Leben, Gesundheit/körperliche Unversehrtheit (Leib), Freiheit, Ehre, Eigentum und Besitz, Hausrecht.","Nicht notwehrfähig sind reine Rechtsgüter der Allgemeinheit (z. B. ‚die öffentliche Ordnung‘) – deren Schutz ist Sache des Staates.","Die Verteidigung muss zum bedrohten Rechtsgut passen (Erforderlichkeit) – für eine bloße Beleidigung darf man nicht zuschlagen."],"schutzziel":"Klären, WAS man verteidigen darf – die eigenen und fremden Individualrechtsgüter, nicht abstrakte Allgemeininteressen.","kennwerte":[{"l":"Geschützt","v":"Leben, Leib, Freiheit, Ehre, Eigentum"},{"l":"Auch","v":"Besitz, Hausrecht"},{"l":"Nicht","v":"reine Allgemeininteressen"}],"begriffe":["Individualrechtsgut = ein Rechtsgut einer einzelnen Person (Leben, Eigentum, Ehre …).","Allgemeinrechtsgut = ein Rechtsgut der Allgemeinheit (öffentliche Ordnung) – nicht notwehrfähig."],"abgrenzung":["Auch die Ehre ist notwehrfähig – aber gegen eine Beleidigung ist körperliche Gewalt regelmäßig nicht erforderlich (nur das mildeste geeignete Mittel).","Den Schutz reiner Allgemeininteressen (z. B. Durchsetzung von Verkehrsregeln) übernimmt der Staat, nicht die Notwehr."],"praxis":["Du darfst das Eigentum und den Besitz des Auftraggebers mit Notwehr verteidigen (z. B. gegen einen Dieb) – das ist im Objektschutz zentral.","Bei reinen Worten (Beleidigung) ist Zurückhaltung geboten: verbale Deeskalation statt Gewalt."]},"visual":null},{"h":"Nothilfe","b":"Notwehr zugunsten eines anderen","detail":{"titel":"Nothilfe","kat":"Notwehr · Nothilfe","katCls":"recht","merksatz":"Nothilfe ist Notwehr zugunsten eines anderen – man darf einen Dritten gegen einen gegenwärtigen rechtswidrigen Angriff verteidigen.","funktion":["Nothilfe = die Verteidigung eines ANDEREN gegen einen gegenwärtigen rechtswidrigen Angriff (in § 32 StGB und § 227 BGB mitgeregelt: ‚von sich oder einem anderen abzuwenden‘).","Es gelten dieselben Voraussetzungen wie bei der Notwehr: Notwehrlage + erforderliche, mildeste geeignete Handlung gegen den Angreifer.","Grenze: Nothilfe gegen den Willen des Angegriffenen ist grundsätzlich nicht zulässig (aufgedrängte Nothilfe)."],"schutzziel":"Auch denjenigen schützen, der sich nicht selbst wehren kann – jeder darf einem Angegriffenen beistehen.","kennwerte":[{"l":"Definition","v":"Notwehr für einen anderen"},{"l":"Voraussetzungen","v":"wie Notwehr (Lage + erforderliche Handlung)"},{"l":"Grenze","v":"nicht gegen den Willen des Betroffenen"}],"begriffe":["Nothilfe = Hilfe zur Verteidigung eines Dritten in dessen Notwehrlage.","Aufgedrängte Nothilfe = unerwünschtes Eingreifen gegen den Willen des Betroffenen – unzulässig."],"abgrenzung":["Nothilfe (Verteidigung gegen einen menschlichen Angriff für einen anderen) ist nicht die unterlassene Hilfeleistung (§ 323c StGB) – diese betrifft Hilfe bei Unglücksfällen.","Auch die Nothilfe braucht eine echte Notwehrlage – ist der Angriff vorbei, ist die ‚Hilfe‘ Vergeltung."],"praxis":["Siehst du, wie eine Person angegriffen wird, darfst du eingreifen und sie verteidigen (Nothilfe) – mit denselben Grenzen wie bei der eigenen Notwehr.","Oft ist die sicherste Nothilfe: Polizei rufen, Angriff beobachten, nur so weit eingreifen wie erforderlich und vertretbar."]},"visual":null},{"h":"Putativnotwehr & Notwehrüberschreitung","b":"Irrtümliche Notwehrlage; Überschreitung aus Furcht/Verwirrung/Schrecken §33","detail":{"titel":"Putativnotwehr & Notwehrüberschreitung","kat":"Notwehr · Irrtum/Exzess","katCls":"recht","merksatz":"Wer eine Notwehrlage nur irrtümlich annimmt, handelt in Putativnotwehr; wer aus Furcht, Schrecken oder Verwirrung zu weit geht, überschreitet die Notwehr (§ 33 StGB) – und wird dann oft nicht bestraft.","funktion":["Putativnotwehr (Erlaubnistatbestandsirrtum): Der Handelnde nimmt irrtümlich eine Notwehrlage an, die in Wirklichkeit nicht besteht – behandelt wird das wie ein Tatumstandsirrtum (kein Vorsatz, allenfalls Fahrlässigkeit).","Notwehrüberschreitung (Notwehrexzess, § 33 StGB): Der Verteidiger überschreitet die erforderlichen Grenzen der Notwehr aus Verwirrung, Furcht oder Schrecken – dann wird er nicht bestraft.","Wichtig: Beim Exzess (§ 33) besteht eine echte Notwehrlage; bei der Putativnotwehr wird sie nur irrig angenommen."],"schutzziel":"Den menschlich verständlichen Fehlern in einer Stresssituation Rechnung tragen – nicht jede Fehlreaktion in Todesangst soll bestraft werden.","kennwerte":[{"l":"Putativnotwehr","v":"Lage irrtümlich angenommen"},{"l":"Exzess (§ 33)","v":"Grenzen aus Furcht/Schrecken/Verwirrung überschritten"},{"l":"Folge","v":"oft keine Bestrafung"}],"begriffe":["Putativnotwehr = ‚Scheinnotwehr‘: der Verteidiger glaubt an einen Angriff, der nicht existiert.","Notwehrexzess = Überschreiten des erforderlichen Maßes der Verteidigung.","Asthenische Affekte = Furcht, Schrecken, Verwirrung (die § 33 StGB privilegiert)."],"abgrenzung":["Putativnotwehr: Es gibt KEINE echte Notwehrlage, der Täter bildet sie sich nur ein. Notwehrexzess: Es gibt eine echte Lage, aber die Verteidigung geht zu weit.","§ 33 privilegiert nur die ‚schwachen‘ Affekte (Furcht, Schrecken, Verwirrung) – nicht Wut oder Rachsucht."],"praxis":["Gerade nachts und unter Stress kann man eine Lage falsch einschätzen – deshalb: Ruhe bewahren, genau hinsehen, im Zweifel deeskalieren und nicht ‚auf Verdacht‘ zuschlagen.","Wer aus echter Angst überreagiert, wird oft nicht bestraft (§ 33) – das ist aber kein Freibrief, sondern eine Ausnahme."]},"visual":null},{"h":"Defensiver Notstand §228","b":"Gefahr durch fremde Sache/Tier; Verhältnismäßigkeit","detail":{"titel":"Defensiver Notstand § 228 BGB","kat":"Notstand · § 228 BGB","katCls":"recht","merksatz":"Beim defensiven Notstand (§ 228 BGB) wehrt man eine Gefahr ab, die von einer fremden SACHE (oder einem Tier) ausgeht – indem man genau diese Sache beschädigt oder zerstört.","funktion":["Lage: Eine Gefahr droht durch eine fremde Sache (oder ein Tier) – die Gefahr geht von DIESER Sache aus.","Handlung: Man beschädigt oder zerstört die gefahrbringende Sache selbst, um die Gefahr abzuwenden.","Grenze: Die Beschädigung darf nicht außer Verhältnis zur Gefahr stehen (Verhältnismäßigkeit). Wer die Gefahr selbst verschuldet hat, kann ersatzpflichtig sein."],"schutzziel":"Erlauben, sich gegen eine von einer Sache ausgehende Gefahr zu wehren, indem man auf genau diese Sache einwirkt.","kennwerte":[{"l":"Gefahr geht aus von","v":"der fremden Sache/dem Tier selbst"},{"l":"Einwirkung auf","v":"dieselbe gefährliche Sache"},{"l":"Grenze","v":"Verhältnismäßigkeit (§ 228)"}],"begriffe":["Defensiver Notstand = Verteidigungsnotstand: Abwehr durch Einwirkung auf die GEFAHRENQUELLE selbst.","Gefahr = ein Zustand, der bei ungehindertem Ablauf zu einem Schaden führt."],"abgrenzung":["Defensiver Notstand (§ 228): die Gefahr geht von der Sache aus, auf die man einwirkt. Aggressiver Notstand (§ 904): man wirkt auf eine UNBETEILIGTE fremde Sache ein.","Notwehr (§ 227) richtet sich gegen einen MENSCHEN; § 228 gegen eine SACHE oder ein Tier."],"praxis":["Greift ein fremder Hund dich an, darfst du ihn abwehren und notfalls verletzen – die Gefahr geht vom Tier selbst aus (§ 228).","Die Abwehr muss verhältnismäßig bleiben: nur so weit, wie zur Gefahrenabwehr nötig."]},"visual":null},{"h":"Aggressiver Notstand §904","b":"Einwirkung auf fremde Sache zur Gefahrenabwehr; Schadensersatzpflicht","detail":{"titel":"Aggressiver Notstand § 904 BGB","kat":"Notstand · § 904 BGB","katCls":"recht","merksatz":"Beim aggressiven Notstand (§ 904 BGB) wirkt man auf eine UNBETEILIGTE fremde Sache ein, um eine Gefahr abzuwenden – muss den Schaden aber in der Regel ersetzen.","funktion":["Lage: Eine gegenwärtige Gefahr droht – aber NICHT von der Sache, auf die man einwirkt (die Sache ist unbeteiligt).","Handlung: Man beschädigt oder benutzt eine fremde, unbeteiligte Sache, weil der drohende Schaden unverhältnismäßig größer ist als der an der Sache angerichtete.","Folge: Der Eigentümer muss die Einwirkung dulden – aber der Notstandshandelnde (bzw. der Begünstigte) muss den Schaden ersetzen."],"schutzziel":"Im echten Notfall erlauben, fremdes (unbeteiligtes) Eigentum zur Rettung eines höheren Gutes einzusetzen – gegen Ersatz.","kennwerte":[{"l":"Gefahr geht aus von","v":"NICHT der betroffenen Sache (unbeteiligt)"},{"l":"Voraussetzung","v":"drohender Schaden unverhältnismäßig größer"},{"l":"Folge","v":"Duldungspflicht, aber Schadensersatz"}],"begriffe":["Aggressiver Notstand = Angriffsnotstand: Einwirkung auf eine UNBETEILIGTE fremde Sache.","Aufopferung = der Eigentümer muss den Eingriff dulden, erhält dafür aber Schadensersatz."],"abgrenzung":["Aggressiver Notstand (§ 904): die Sache ist UNBETEILIGT – Ersatzpflicht. Defensiver Notstand (§ 228): die Gefahr geht von der Sache selbst aus – regelmäßig keine Ersatzpflicht.","Anders als bei der Notwehr gibt es hier keinen Angreifer – nur eine Gefahr und eine unbeteiligte Sache."],"praxis":["Klassiker: Um einen Verletzten zu retten, schlägst du die Scheibe eines fremden Autos ein, um an einen Verbandskasten zu kommen – erlaubt nach § 904, aber der Schaden ist zu ersetzen.","Nur im echten Notfall und nur, wenn das gerettete Gut den Sachschaden deutlich überwiegt."]},"visual":null},{"h":"Rechtfertigender Notstand §34 StGB","b":"Güterabwägung; kleinere Straftat zur Abwendung größeren Übels","detail":{"titel":"Rechtfertigender Notstand § 34 StGB","kat":"Notstand · § 34 StGB","katCls":"recht","merksatz":"Der rechtfertigende Notstand (§ 34 StGB) erlaubt eine an sich strafbare Tat, wenn sie das einzige Mittel ist, um eine Gefahr abzuwenden, und das geschützte Interesse das beeinträchtigte WESENTLICH überwiegt.","funktion":["Notstandslage: eine gegenwärtige, nicht anders abwendbare Gefahr für ein Rechtsgut (Leben, Leib, Freiheit, Eigentum, …).","Notstandshandlung: Die Tat muss erforderlich sein (kein milderes Mittel) und es muss eine Interessenabwägung erfolgen.","Wesentliches Überwiegen: Das geschützte Interesse muss das beeinträchtigte wesentlich überwiegen – nur dann ist die Tat gerechtfertigt (nicht rechtswidrig)."],"schutzziel":"In einer echten Konfliktlage das Handeln zur Rettung des höherwertigen Gutes erlauben – das Recht ‚opfert‘ das geringere Interesse.","kennwerte":[{"l":"Lage","v":"gegenwärtige, nicht anders abwendbare Gefahr"},{"l":"Handlung","v":"erforderlich + Interessenabwägung"},{"l":"Kern","v":"geschütztes Interesse überwiegt WESENTLICH"}],"begriffe":["Güterabwägung = das Abwägen der widerstreitenden Interessen (welches Gut wiegt schwerer?).","Rechtfertigend = die Tat ist nicht rechtswidrig (im Gegensatz zu ‚entschuldigend‘)."],"abgrenzung":["§ 34 (rechtfertigend) verlangt ein WESENTLICHES Überwiegen des geschützten Guts – dann ist die Tat erlaubt. § 35 (entschuldigend) verlangt das nicht, entschuldigt aber nur.","Anders als Notwehr (gegen einen Angreifer) wirkt § 34 in jeder Gefahrenlage, auch ohne Angreifer – aber mit strenger Abwägung."],"praxis":["Beispiel: Du überschreitest mit einem Schwerverletzten im Auto die zulässige Geschwindigkeit, um sein Leben zu retten – das Leben überwiegt den Verkehrsverstoß (§ 34).","In der Praxis selten und heikel: Im Zweifel die mildere, rechtmäßige Handlung wählen und Hilfe rufen."]},"visual":null},{"h":"Entschuldigender Notstand §35 StGB","b":"Nur Leib/Leben/Freiheit, nahestehende Person; entschuldigt statt rechtfertigt","detail":{"titel":"Entschuldigender Notstand § 35 StGB","kat":"Notstand · § 35 StGB","katCls":"recht","merksatz":"Der entschuldigende Notstand (§ 35 StGB) entschuldigt eine Tat, die zur Abwehr einer gegenwärtigen Gefahr für Leben, Leib oder Freiheit einer nahestehenden Person begangen wird – die Tat bleibt rechtswidrig, aber der Täter wird nicht bestraft.","funktion":["Eng begrenzte Rechtsgüter: nur Gefahr für Leben, Leib oder Freiheit – nicht für Eigentum oder Ehre.","Personenkreis: Die Gefahr muss den Täter selbst, einen Angehörigen oder eine andere ihm nahestehende Person betreffen.","Wirkung: Die Tat bleibt rechtswidrig, der Täter handelt aber ohne Schuld – er wird entschuldigt (nicht gerechtfertigt)."],"schutzziel":"Dem Täter Nachsicht gewähren, der in einer ausweglosen Lebensgefahr für sich oder einen Nahestehenden ‚nicht anders konnte‘ – ohne die Tat zu billigen.","kennwerte":[{"l":"Nur für","v":"Leben, Leib, Freiheit"},{"l":"Personen","v":"selbst, Angehörige, Nahestehende"},{"l":"Wirkung","v":"entschuldigt (rechtswidrig, aber schuldlos)"}],"begriffe":["Entschuldigend = die Tat bleibt rechtswidrig, aber der Täter wird nicht bestraft (keine Schuld).","Nahestehende Person = Angehörige oder Personen in einem ähnlichen engen Verhältnis."],"abgrenzung":["§ 34 (rechtfertigend) macht die Tat ERLAUBT (nicht rechtswidrig); § 35 (entschuldigend) lässt die Tat rechtswidrig, nimmt aber die Schuld.","§ 35 schützt nur Leben, Leib und Freiheit – nicht Eigentum; und nur den Täter und ihm nahestehende Personen."],"praxis":["Sehr selten in der Wachpraxis – wichtig ist vor allem der Unterschied zu § 34: Bei § 35 wird die Tat nicht erlaubt, sondern nur entschuldigt.","Im Ernstfall zählt: deeskalieren, Hilfe rufen, eigene und fremde Gefahr nicht verschärfen."]},"visual":null}],"quiz":[{"q":"Welche Aussage zur Verteidigungshandlung bei der Notwehr ist richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Der Angegriffene muss in allen Notwehrsituationen auf die Verteidigung verzichten, wenn er dem Angriff ausweichen kann","c":false},{"t":"Der Angegriffene darf den Angriff sofort beenden. Deshalb ist es z. B. nicht erforderlich, den Einsatz einer Schusswaffe anzudrohen","c":true},{"t":"Der Angegriffene darf sich erst dann verteidigen, wenn es ihm nicht möglich ist, fremde Hilfe zu holen","c":false},{"t":"Der Angegriffene darf die Verteidigungshandlung nur gegen den Angreifer und dessen Rechtsgüter richten","c":true}]},{"q":"A wird von B grundlos angegriffen und verteidigt sich. Die Verteidigung muss erforderlich sein. Was bedeutet dies für A?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"A muss bei der Wahl des Verteidigungsmittels eine Rechtsgutabwägung vornehmen","c":false},{"t":"A muss beachten, dass das Mittel geeignet ist, den Angriff sofort zu beenden oder abzuschwächen","c":true},{"t":"A muss das mildeste Mittel wählen, wenn ihm mehrere geeignete Mittel zur Verfügung stehen","c":true},{"t":"A muss beachten, dass die Verteidigung gegenüber Kindern und Geisteskranken unzulässig ist","c":false}]},{"q":"Was unterscheidet die Notwehr gemäß § 32 StGB von der Notwehr gemäß § 227 BGB?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Eine Tat, die durch Notwehr gemäß § 32 StGB geboten ist, ist nicht rechtswidrig – es erfolgt in der Regel keine Bestrafung","c":true},{"t":"Eine Tat, die durch Notwehr gemäß § 227 BGB geboten ist, ist nicht widerrechtlich – die Schadensersatzpflicht ist grundsätzlich ausgeschlossen","c":true},{"t":"Die Notwehr nach § 32 StGB schützt eigene und fremde Rechtsgüter, die nach § 227 BGB nur eigene","c":false},{"t":"Der Angriff nach § 32 StGB muss schuldhaft sein, der Angriff nach § 227 BGB muss rechtswidrig sein","c":false}]},{"q":"Wann befindet sich eine Person in einer Notwehrlage im Sinne der Notwehr gemäß § 227 BGB?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wenn die Person von herabstürzenden Dachziegeln getroffen und verletzt wird","c":false},{"t":"Wenn die Person grundlos von einer geistig verwirrten Person mit einer Eisenstange geschlagen wird","c":true},{"t":"Wenn die Person von einem zehnjährigen Kind rechtswidrig und gegenwärtig angegriffen wird","c":true},{"t":"Wenn die Person von einem herrenlosen Tier angefallen wird","c":false}]},{"q":"Bei einer Behältniskontrolle stellt eine Wachperson fest, dass ein Betriebsangehöriger firmeneigene Geräte unbefugt mitnehmen will. Welche Aussagen zur Notwehr gemäß BGB sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Wachperson darf nach ihrem Ermessen entscheiden, ob sie die Geräte abnimmt oder den Preis als Bargeld entgegennimmt","c":false},{"t":"Die Wachperson darf keine Notwehrhandlung vornehmen, weil der Angriff auf das Gerät nicht gegenwärtig ist","c":false},{"t":"Das Firmeneigentum kann durch Notwehr verteidigt werden; der Betriebsangehörige muss die Geräte herausgeben","c":true},{"t":"Nimmt die Wachperson die Geräte ab, handelt es sich um Notwehr in Form der Nothilfe, denn die Geräte sind nicht ihr Eigentum","c":true}]},{"q":"Welche Aussagen zum Grundsatz der Verhältnismäßigkeit sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Eine Maßnahme ist nur so lange zulässig, bis ihr Zweck erreicht ist","c":true},{"t":"Dieser Grundsatz muss nur von der Staatsgewalt beachtet werden","c":false},{"t":"Sind mehrere Mittel verfügbar, ist das mildeste Mittel zu wählen","c":true},{"t":"Es darf jedes Mittel eingesetzt werden, um den gewünschten Erfolg zu erreichen","c":false}]},{"q":"Welche Aussagen zum Verteidigungsnotstand gemäß § 228 BGB sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Notstandshandlung ist unzulässig, wenn der Notstandshandelnde die Gefahr selbst verursacht hat","c":false},{"t":"Die Handlung muss zur Abwendung der Gefahr erforderlich sein; die Beschädigung der Sache darf nicht außer Verhältnis zur Gefahr stehen","c":true},{"t":"Beim Verteidigungsnotstand kann die drohende Gefahr von Sachen, Tieren, Witterungsverhältnissen oder Menschen ausgehen","c":false},{"t":"Der Verteidigungsnotstand erlaubt die Beschädigung oder Zerstörung einer fremden Sache, um eine durch sie drohende Gefahr abzuwenden","c":true}]},{"q":"Wie unterscheiden sich die Notwehr und der Verteidigungsnotstand gemäß BGB?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Bei der Notwehr droht eine Gefahr, die von einer Sache ausgeht","c":false},{"t":"Bei der Notwehr geht ein Angriff von einem Menschen aus","c":true},{"t":"Beim Verteidigungsnotstand geht ein Angriff von einem Menschen aus","c":false},{"t":"Beim Verteidigungsnotstand droht eine Gefahr, die von einer Sache ausgeht","c":true}]},{"q":"Welche Aussagen zum Angriffsnotstand gemäß § 904 BGB sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Notstandsfähig sind nur eigene Rechtsgüter wie Leib und Leben","c":false},{"t":"Einen durch die Notstandshandlung verursachten Schaden muss in der Regel die Person ersetzen, die die Notstandshandlung vorgenommen hat","c":true},{"t":"Der Notstandshandelnde wirkt auf eine fremde Sache ein, von der die Gefahr nicht ausgeht","c":true},{"t":"Die Notstandshandlung ist nur zulässig, wenn die Gefahr erfolgreich abgewendet wird","c":false}]},{"q":"Welche Voraussetzungen müssen für den rechtfertigenden Notstand gemäß § 34 StGB vorliegen?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Es besteht eine gegenwärtige, nicht anders abwendbare Gefahr für ein Rechtsgut","c":true},{"t":"Die Tat muss erforderlich sein – es darf kein milderes Mittel zur Gefahrenabwehr geben","c":true},{"t":"Das geschützte Interesse muss das beeinträchtigte Interesse wesentlich überwiegen","c":true},{"t":"Die Gefahr muss zwingend von einem menschlichen Angreifer ausgehen","c":false}]},{"q":"Wie unterscheidet sich der entschuldigende Notstand (§ 35 StGB) vom rechtfertigenden Notstand (§ 34 StGB)?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Beim § 35 bleibt die Tat rechtswidrig, der Täter wird aber nicht bestraft (entschuldigt)","c":true},{"t":"§ 35 schützt nur Leben, Leib oder Freiheit – nicht das Eigentum","c":true},{"t":"Die Gefahr muss den Täter selbst, einen Angehörigen oder eine nahestehende Person betreffen","c":true},{"t":"Beim § 35 wird die Tat wie beim § 34 gerechtfertigt und ist damit erlaubt","c":false}]},{"q":"Darf man jemanden fesseln bei einer Vorläufigen Festnahme?","a":"Nein; (Ausnahme in Notwehr !)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Kinder §19 StGB, Welche 3 Eingriffsrechte habe ich?","a":"Man darf Sie festnehmen (Allgemeine Selbsthilfe, § 229 BGB), Diebesgut abnehmen (Besitzkehr, § 860 BGB), gegenwärtigen rechtswidrigen Angriff auf Eigentum abwehren (Notwehr, § 32 StGB).","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §132 StGB Amtsanmaßung, Tatbestandsmerkmale.","a":"Wer sich als Inhaber eines öffentliches Amtes ausgibt oder danach handelt, ohne diese innezuhaben.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §226 StGB Schwere Körperverletzung, Tatbestandsmerkmale.","a":"Sie qualifiziert sich durch Verlust des Gehörs, Motorik, Sprachvermögen, Sehvermögen, wichtiges Körperglied, Siechtum; Offizialdelikt, Verbrechen ! Eine weitere ist die Körperverletzung mit Todesfolge § 227 StGB","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Rechtfertigungsgründe gibt es im BGB?","a":"Notwehr/ Nothilfe > bei Angriff durch Menschen Verteidigungs-Notstand > bei Gefahr durch Sache oder Tier Angriffs-Notstand > bei Einwirken auf das Eigentum eines Dritten (zur Verteidigung vor Gefahr) Allgemeine Selbsthilfe > zur Sicherung eines (Rechts-)Anspruches Selbsthilfe des Besitzers / > zur Verteidigung (Schutz) seines Besitzes(Besitzdieners)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Erklären Sie mir die Notwehr gem. §227 BGB?","a":"Ein gegenwärtiger und rechtswidriger Angriff muss vorliegen\t-gegenwärtig = unmittelbar bevorstehend oder andauernd\t-Angriff = erfolgt immer durch menschliches Handeln Ich darf mich oder einen anderen mit den erforderlichen Mitteln verteidigen Der Angriff ist hier auf jedes Rechtsgut gemeint!\twie: Leben, Gesundheit, Ehre, Eigentum, Besitz, etc. rechtfertigt unerlaubtes Handeln und befreit somit von Schadensersatz","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter dem sogenannten (Angriffs-) Notstand gem. §904 BGB?","a":"Eigentum eines unbeteiligten Dritten Wegnehmen odernutzen (also „drauf einwirken“) Um mich oder einen anderen mit diesem Eigentum vor einer Gefahr zu schützen(folglich durch Notwehr oder (Verteidigungs-)Notstand) Dem Eigentümer bin ich zum Ersatz, des entstandenen Schaden(s) verpflichtet","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Nenne alle Jedermannsrechte/Ausnahmerechte aus dem BGB/StGB, StPO","a":"BGB - Notwehr - Angriffsnotstand BGB - Verteidigungsnotstand BGB - Selbsthilfe BGB - Selbsthilfe des Besitzers BGB - Selbsthilfe des Besitzdieners BGB StGB - Notwehr - Rechtfertigender Notstand - Entschuldigender Notstand StPO - Vorläufige Festnahme","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Notwehr?","a":"Notwehr ist die Verteidigung die erforderlich und geboten ist, einen gegenwärtigen rechtswidrigen Angriff von sich oder einen Anderen abzuwehren.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Rechtsgüter schützt die Notwehr?","a":"Alle Rechtsgüter ( Leben, Leib, Freiheit, Ehre, Eigentum)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist Nothilfe?","a":"Wenn man jemand anderen in Notwehr hilft.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Verteidigung bei der Notwehr?","a":"Sie muss sich gegen den Angreifer richten und zur sofortigen und endgültigen Abwehr des Angriffs führen, der Verteidigungswille muss im Vordergrund stehen Erforderlich heißt, die Verteidigung muss notwendig und geeignet sein, den Angriff sofort zu beenden; dass es kein milderes Mittel geben darf, welches den gleichen Erfolg mit vergleichbarem Aufwand erzielen kann (mildestes Mittel)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Angriff?","a":"Beeinträchtigung notwehrfähiger Rechtsgüter durch einen Menschen (Leben, Freiheit, Eigentum,...)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist Putativnotwehr, bzw. Erlaubnistatbestandsirrtum und was ist","a":"Notwehrüberschreitung? Putativnotwehr: Der Handelnde nimmt irrtümlich eine Notwehrsituation an. (Kann wegen „Fahrlässigkeit“ bestraft werden/Vorsatz entfällt) Notwehrüberschreitung: Wenn der Handelnde aus Furcht, Verwirrung oder Schrecken die Notwehr überzieht; z.B. Nachtreten, Nachschlagen aus Todesangst","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre §904 BGB Angriffsnotstand.","a":"Wen man in die Sache (Zaunlatte) einer unbeteiligten fremden Person eingreift um damit die gegenwärtige Gefahr abzuwenden. Der Besitzer muss dieses dulden, kann aber Schadenersatz verlangen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre drohende Gefahr und gegenwärtige Gefahr","a":"bei den Notständen. - drohende Gefahr: mit dem Eintritt der Gefahr ist in nächster Zeit zu rechnen (z.B. Sturm; Schild könnte jemanden verletzen) - bei der gegenwärtigen Gefahr steht die Gefahr unmittelbar bevor; (daher auch § 904 BGB Angreifender Notstand anwendbar)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Vorrausetzung §34 StGB Rechtfertigender Notstand?","a":"Die Gefahr für (irgendein) Rechtsgut (Leib, Leben, Eigentum ...) muss gegenwärtig und nicht anders abwendbar sein und erlaubt eine kleine Straftat, um ein größeres Übel abzuwenden; (Bsp. Scheibe einschlagen/Kind im Auto bei 40 Grad Hitze; Gartenzaun des Nachbarn überfahren/zerstören – siehe Frage 13","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §249 StGB Raub, Tatbestandsmerkmale.","a":"Der Täter will einer anderen Person durch Gewalt oder Anwendung von Drohungen mit gegenwärtiger Gefahr für Leib und Leben eine fremde bewegliche Sache wegnehmen; Erst hauen, dann klauen!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §252 StGB Räuberischer Diebstahl, Tatbestandsmerkmale.","a":"Der Täter will durch Gewaltausübung oder Anwendung von Drohungen mit gegenwärtiger Gefahr auf Leib und Leben des Besitzt des Diebesgut erhalten; Erst klauen, dann hauen!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Gegenwärtig?","a":"Gegenwärtig bedeutet, das der Angriff unmittelbar bevor steht, noch Andauert und noch nicht Beendet ist.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre §228 BGB Verteidigungsnotstand.","a":"Wer eine fremde Sache von der eine drohende Gefahr ausgeht, beschädigt oder zerstört, handelt nicht widerrechtlich. (Verhältnismäßigkeit beachten !)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was können Sie mir zum Thema Sachen sagen?","a":"Sachen sind körperliche Gegenstände Sachen können beweglich oder unbeweglich sein Tiere sind keine Sachen – sie werden durch besondere Gesetze geschützt-für sie werden jedoch die gleichen Rechtsvorschriften wie für Sachen genommen, wenn die speziellen Gesetze für Tier nicht greifen (z.B.: Notstand nach §228 BGB)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter dem (Verteidigungs-) Notstand gem. §228 BGB?","a":"Verteidigung gegen eine Gefahr durch Sache (oder Tier) Durch Beschädigung oder Zerstörung dieser Sache (von der die Gefahr ausgeht) rechtfertigt eine unerlaubte Handlung und befreit somit von Schadensersatz AUSSER !!!=Ich habe die Gefahr selbst verschuldet","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was bedeutet beim §34 StGB der Begriff Güterabwägung?","a":"Das Rechtsgut was zur Abwendung der Gefahr beschädigt wird (Autoscheibe) darf im Wesentlichen nicht höher sein als der Schaden der bei Nicht-Handlung eingetreten wäre (Tod des Kindes; Leben ist höherwertiger!)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §35 StGB Entschuldigender Notstand/Unterschiede","a":"zu §34 Rechtfertigender Notstand (Einschränkungen) Beim Entschuldigen Notstand ist die Abwendung der Gefahr nur für Leib, Leben, Freiheit oder eine nahestehende Person (z.B. Kind, Ehefrau) möglich, Beim Rechtfertigen Notstand ist die Abwehr der Gefahr für \"jedes\" Rechtsgut möglich; also auch Eigentum; Beispiel: Ihr Haus brennt (Eigentum) um dieses löschen zu können überfahren Sie den Gartenzaun Ihres Nachbarn ; (Tatbestand = Sachbeschädigung; Rechtfertigungsgrund: § 34 StGB / keine Straftat)","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[{"scenario":"Ein Angreifer schlägt unvermittelt auf einen Gast ein. Du gehst dazwischen und setzt nur so viel Kraft ein, wie nötig, um den Angriff zu stoppen.","frage":"Auf welchen Rechtfertigungsgrund stützt sich dein Handeln?","loesung":"Nothilfe – Notwehr zugunsten eines anderen (§227 BGB / §32 StGB). Voraussetzungen: gegenwärtiger, rechtswidriger Angriff; deine Verteidigung muss erforderlich und das mildeste geeignete Mittel sein. Überschreitest du aus Furcht/Schrecken, greift ggf. §33 StGB."}]},{"n":4,"title":"Strafrecht – Allgemeiner Teil","subtitle":"11 Konzepte · 70 Prüfungsfragen","cards":[{"h":"Keine Strafe ohne Gesetz §1","b":"Rückwirkungsverbot, Bestimmtheitsgrundsatz","detail":{"titel":"Keine Strafe ohne Gesetz (§ 1 StGB)","kat":"Strafrecht AT · § 1 StGB","katCls":"stgb","merksatz":"‚Keine Strafe ohne Gesetz‘ (§ 1 StGB, Art. 103 II GG): Bestraft werden darf nur, wer einen Tatbestand erfüllt, der schon VOR der Tat gesetzlich bestimmt war. Das schützt vor staatlicher Willkür.","funktion":["Gesetzlichkeitsprinzip: Eine Tat ist nur strafbar, wenn die Strafbarkeit gesetzlich bestimmt war, bevor die Tat begangen wurde.","Rückwirkungsverbot: Strafgesetze dürfen NICHT rückwirkend erlassen oder verschärft angewendet werden.","Bestimmtheitsgebot: Der Bürger muss aus dem Gesetz erkennen können, was strafbar ist – kein ‚Gummi-Tatbestand‘."],"schutzziel":"Den Bürger vor willkürlicher Bestrafung schützen – der Staat darf nur strafen, was vorher klar im Gesetz stand.","kennwerte":[{"l":"Rechtsquelle","v":"§ 1 StGB & Art. 103 II GG"},{"l":"Kern","v":"Tatbestand muss VOR der Tat bestehen"},{"l":"Verbot","v":"keine Rückwirkung zulasten des Täters"}],"begriffe":["Tatbestand = die gesetzliche Beschreibung des strafbaren Verhaltens (z. B. ‚wer eine fremde bewegliche Sache wegnimmt …‘).","Willkür = staatliches Handeln ohne gesetzliche Grundlage."],"abgrenzung":["Der Grundsatz gilt nicht nur für das StGB, sondern für ALLE Strafgesetze (auch im Nebenstrafrecht, z. B. WaffG, BtMG).","Er verbietet Bestrafung ohne Gesetz – nicht aber, dass der Gesetzgeber für die Zukunft neue Straftatbestände schafft."],"praxis":["Für die Wachpraxis heißt das: Du darfst niemanden ‚bestrafen‘ – Strafe verhängt nur der Staat (Gericht), und nur aufgrund eines Gesetzes.","Wenn ein Verhalten ärgerlich, aber nicht ausdrücklich strafbar ist, ist es eben keine Straftat – egal wie unsympathisch es wirkt."]},"visual":null},{"h":"Dreistufiger Deliktaufbau","b":"Tatbestand, Rechtswidrigkeit, Schuld","detail":{"titel":"Dreistufiger Deliktaufbau","kat":"Strafrecht AT · Aufbau","katCls":"stgb","merksatz":"Eine Straftat ist eine Handlung, die drei Stufen erfüllt: tatbestandsmäßig, rechtswidrig und schuldhaft. Fehlt eine Stufe, liegt keine strafbare Tat vor.","funktion":["1. Tatbestandsmäßigkeit: Das Verhalten erfüllt genau die gesetzliche Beschreibung einer Straftat (objektiv + subjektiv).","2. Rechtswidrigkeit: Es liegt kein Rechtfertigungsgrund vor (z. B. Notwehr, § 904, Einwilligung).","3. Schuld: Dem Täter ist die Tat persönlich vorwerfbar (schuldfähig, kein Entschuldigungsgrund)."],"schutzziel":"Strafbarkeit Schritt für Schritt prüfen – nur wer alle drei Stufen erfüllt, hat eine Straftat begangen.","kennwerte":[{"l":"Stufe 1","v":"Tatbestand – passt das Verhalten ins Gesetz?"},{"l":"Stufe 2","v":"Rechtswidrigkeit – kein Rechtfertigungsgrund?"},{"l":"Stufe 3","v":"Schuld – persönlich vorwerfbar?"}],"begriffe":["Handlung = ein vom Willen beherrschtes (oder beherrschbares) menschliches Verhalten – keine Handlung sind z. B. Reflexe oder Bewegungen im Schlaf.","Vorwerfbarkeit = man hätte sich rechtmäßig verhalten können und sollen."],"abgrenzung":["Reihenfolge zählt: Erst Tatbestand, dann Rechtswidrigkeit, dann Schuld. Entfällt eine frühere Stufe, kommt man zur nächsten gar nicht.","Notwehr (§ 32) entfällt auf Stufe 2 (Rechtswidrigkeit); Schuldunfähigkeit (§ 20) oder § 35 auf Stufe 3 (Schuld)."],"praxis":["In der Wachpraxis brauchst du keine Gutachten zu schreiben – aber das Schema hilft, eine Lage einzuordnen: Liegt überhaupt eine Straftat vor (Tatbestand)? Gibt es einen Rechtfertigungsgrund (Notwehr)?","Beispiel: Wer in Notwehr handelt, erfüllt zwar einen Tatbestand (z. B. Körperverletzung), ist aber gerechtfertigt – also nicht strafbar."]},"visual":null},{"h":"Objektiver/subjektiver Tatbestand","b":"Äußere Tathandlung vs. Vorsatz/Absicht","detail":{"titel":"Objektiver & subjektiver Tatbestand","kat":"Strafrecht AT · Tatbestand","katCls":"stgb","merksatz":"Die erste Stufe (Tatbestand) hat zwei Seiten: den OBJEKTIVEN Tatbestand (was äußerlich geschah) und den SUBJEKTIVEN Tatbestand (was im Kopf des Täters vorging – meist Vorsatz).","funktion":["Objektiver Tatbestand: die äußeren Merkmale der Tat – Täter, Handlung, Tatobjekt, Erfolg (z. B. ‚fremde bewegliche Sache wegnehmen‘).","Subjektiver Tatbestand: die innere Seite – der Vorsatz (Wissen und Wollen der Tat), bei manchen Delikten zusätzliche Absichten (z. B. Zueignungsabsicht beim Diebstahl).","Beide müssen erfüllt sein: Wer den äußeren Ablauf verwirklicht, aber ohne Vorsatz handelt, erfüllt den Tatbestand eines Vorsatzdelikts nicht."],"schutzziel":"Trennen, WAS passiert ist (objektiv), von dem, was der Täter WOLLTE (subjektiv) – beides gehört zur Tatbestandsprüfung.","kennwerte":[{"l":"Objektiv","v":"die äußere Tat (Handlung, Erfolg, Objekt)"},{"l":"Subjektiv","v":"der Vorsatz (Wissen + Wollen)"},{"l":"Beim Diebstahl","v":"+ Zueignungsabsicht (subjektiv)"}],"begriffe":["Vorsatz = der Täter weiß, was er tut, und will es (dazu gleich mehr).","Tatbestandsmerkmal = ein einzelnes Element der gesetzlichen Beschreibung (z. B. ‚fremd‘, ‚beweglich‘, ‚Sache‘)."],"abgrenzung":["Objektiv erfüllt, subjektiv nicht: Wer versehentlich einen fremden Schirm mitnimmt, nimmt zwar äußerlich eine fremde Sache weg (objektiv), hat aber keinen Zueignungsvorsatz (subjektiv) – kein Diebstahl.","Der subjektive Tatbestand entscheidet oft über Vorsatz- gegen Fahrlässigkeitsdelikt."],"praxis":["Wichtig für die Bewertung einer Lage: Hat die Person bewusst und gewollt gehandelt – oder war es ein Versehen? Das macht den Unterschied zwischen Diebstahl und ‚aus Versehen mitgenommen‘.","Bei der späteren Anzeige zählt, was du beobachtet hast (objektiv) – die innere Seite klärt die Justiz."]},"visual":null},{"h":"Vorsatz / Fahrlässigkeit / Absicht","b":"Wissen & Wollen; Sorgfaltspflichtverletzung; besondere Zweckverfolgung","detail":{"titel":"Vorsatz, Fahrlässigkeit & Absicht","kat":"Strafrecht AT · Innere Tatseite","katCls":"stgb","merksatz":"Vorsatz heißt: Der Täter WEISS und WILL die Tat. Fahrlässigkeit heißt: Er lässt die gebotene Sorgfalt außer Acht. Fahrlässige Taten sind nur strafbar, wenn das Gesetz es ausdrücklich anordnet.","funktion":["Vorsatz = Wissen UND Wollen der Tatbestandsverwirklichung. Grundregel: Strafbar ist grundsätzlich nur vorsätzliches Handeln (§ 15 StGB).","Fahrlässigkeit = Außerachtlassen der erforderlichen Sorgfalt, obwohl der Erfolg objektiv vorhersehbar und vermeidbar war – und der Täter es nach seinen Fähigkeiten hätte erkennen können.","Absicht = die stärkste Vorsatzform: Es kommt dem Täter gerade darauf an (zielgerichtetes Wollen, z. B. Zueignungsabsicht beim Diebstahl)."],"schutzziel":"Die innere Einstellung des Täters bewerten – sie entscheidet über Strafbarkeit und Strafmaß.","kennwerte":[{"l":"Vorsatz","v":"Wissen + Wollen (§ 15)"},{"l":"Fahrlässigkeit","v":"Sorgfalt außer Acht; nur strafbar, wenn ausdrücklich"},{"l":"Absicht","v":"es kommt dem Täter gerade darauf an"}],"begriffe":["Bedingter Vorsatz (dolus eventualis) = der Täter hält den Erfolg für möglich und nimmt ihn billigend in Kauf.","Bewusste Fahrlässigkeit = der Täter hält den Erfolg für möglich, vertraut aber pflichtwidrig darauf, dass er ausbleibt."],"abgrenzung":["Vorsatz gegen Fahrlässigkeit: Beim bedingten Vorsatz nimmt der Täter den Erfolg in Kauf; bei der bewussten Fahrlässigkeit hofft er, dass nichts passiert.","Vorsatzdelikt ist die Regel; ein Fahrlässigkeitsdelikt gibt es nur, wenn das Gesetz es ausdrücklich nennt (z. B. fahrlässige Körperverletzung § 229, fahrlässige Tötung § 222). Eine fahrlässige Sachbeschädigung gibt es z. B. NICHT."],"praxis":["Praxisrelevanz: Eine fahrlässig zerstörte Sache ist nicht strafbar (keine fahrlässige Sachbeschädigung) – eine vorsätzlich zerstörte schon (§ 303).","Wer ‚nur aus Versehen‘ etwas beschädigt, begeht meist keine Straftat – aber zivilrechtlich kann Schadensersatz fällig werden."]},"visual":null},{"h":"Schuldunfähigkeit §§19,20","b":"Kinder unter 14; seelische Störungen","detail":{"titel":"Schuldunfähigkeit (§§ 19, 20 StGB)","kat":"Strafrecht AT · Schuld","katCls":"stgb","merksatz":"Ohne Schuld keine Strafe. Schuldunfähig ist, wer wegen seines Alters (Kind unter 14, § 19) oder einer seelischen Störung (§ 20) das Unrecht der Tat nicht einsehen oder nicht danach handeln kann.","funktion":["§ 19 – Kinder: Wer bei der Tat noch nicht 14 Jahre alt ist, ist schuldUNfähig – also nie strafbar (unabhängig von der Tat).","§ 20 – seelische Störungen: Schuldunfähig ist auch, wer wegen krankhafter seelischer Störung oder tiefgreifender Bewusstseinsstörung das Unrecht nicht einsehen oder nicht danach handeln kann (z. B. schwerer Rausch).","Folge: Die Tat kann tatbestandsmäßig und rechtswidrig sein – aber ohne Schuld gibt es keine Strafe."],"schutzziel":"Niemanden bestrafen, der für sein Handeln nicht verantwortlich gemacht werden kann.","kennwerte":[{"l":"§ 19","v":"Kind unter 14 = schuldunfähig"},{"l":"ab 14","v":"bedingt strafmündig (Jugendstrafrecht)"},{"l":"§ 20","v":"schuldunfähig bei seelischer Störung"}],"begriffe":["Strafmündigkeit = die Fähigkeit, strafrechtlich verantwortlich zu sein – beginnt mit 14 Jahren.","Einsichts- und Steuerungsfähigkeit = das Unrecht erkennen UND sein Verhalten danach ausrichten können."],"abgrenzung":["§ 19 (Alter) wirkt absolut: unter 14 immer schuldunfähig. § 20 (seelische Störung) muss im Einzelfall festgestellt werden.","Verminderte Schuldfähigkeit (§ 21) ist nicht dasselbe wie Schuldunfähigkeit – die Strafe kann dann nur gemildert werden.","Nicht verwechseln mit der Deliktsfähigkeit im BGB (Schadensersatz ab 7, § 828): zivil- und strafrechtliche Grenzen sind verschieden."],"praxis":["Für die Praxis wichtig: Ein Kind unter 14 begeht NIE eine Straftat – eine vorläufige Festnahme nach § 127 StPO (die einen Straftatverdacht voraussetzt) scheidet aus.","Bei offensichtlich stark berauschten oder psychisch auffälligen Personen sind besondere Vorsicht und Deeskalation geboten – und im Zweifel die Polizei."]},"visual":null},{"h":"Vergehen & Verbrechen §12","b":"Einteilung nach Mindeststrafmaß; Verbrechen ab 1 Jahr","detail":{"titel":"Vergehen & Verbrechen (§ 12 StGB)","kat":"Strafrecht AT · § 12 StGB","katCls":"stgb","merksatz":"§ 12 teilt Straftaten nach ihrer Mindeststrafe ein: VERBRECHEN sind mit mindestens 1 Jahr Freiheitsstrafe bedroht (z. B. Raub, Mord); VERGEHEN mit weniger oder mit Geldstrafe (z. B. Diebstahl, Beleidigung).","funktion":["Verbrechen (§ 12 I): im Mindestmaß mit Freiheitsstrafe von einem Jahr oder mehr bedroht – z. B. Raub (§ 249), Mord (§ 211), Meineid (§ 154).","Vergehen (§ 12 II): geringere Mindeststrafe oder Geldstrafe – z. B. Diebstahl (§ 242), Körperverletzung (§ 223), Beleidigung (§ 185).","Maßgeblich ist die GESETZLICHE Mindeststrafe der Grundnorm – nicht die im Einzelfall verhängte Strafe und nicht Schärfungen oder Milderungen."],"schutzziel":"Straftaten nach Schwere ordnen – das hat Folgen u. a. für die Versuchsstrafbarkeit.","kennwerte":[{"l":"Verbrechen","v":"Mindeststrafe ≥ 1 Jahr Freiheitsstrafe"},{"l":"Vergehen","v":"< 1 Jahr oder Geldstrafe"},{"l":"Maßstab","v":"gesetzliche Mindeststrafe, nicht der Einzelfall"}],"begriffe":["Mindeststrafe = die untere Grenze des gesetzlichen Strafrahmens einer Norm.","Freiheitsstrafe = Strafe durch Freiheitsentzug; die Geldstrafe wird in Tagessätzen bemessen."],"abgrenzung":["Beim Verbrechen ist der VERSUCH immer strafbar; beim Vergehen nur, wenn das Gesetz es ausdrücklich anordnet (wichtiger Merksatz!).","Die Einordnung richtet sich nach der Grundnorm: Ein ‚besonders schwerer Fall‘ oder ein minder schwerer Fall ändert die Einstufung nicht."],"praxis":["Faustregel zum Merken: Raub ist ein Verbrechen, Diebstahl nur ein Vergehen – obwohl beide mit Wegnahme zu tun haben (Raub = Diebstahl + Gewalt/Drohung).","Für die Wachpraxis ist die Unterscheidung v. a. zum Verständnis wichtig; die rechtliche Würdigung trifft die Justiz."]},"visual":null},{"h":"Versuch §§22,23","b":"Unmittelbares Ansetzen; Verbrechen immer, Vergehen nur wenn bestimmt","detail":{"titel":"Versuch (§§ 22, 23 StGB)","kat":"Strafrecht AT · Versuch","katCls":"stgb","merksatz":"Ein Versuch liegt vor, wenn der Täter nach seiner Vorstellung von der Tat unmittelbar zur Verwirklichung ansetzt, der Erfolg aber ausbleibt. Beim Verbrechen ist der Versuch immer strafbar, beim Vergehen nur, wenn das Gesetz es ausdrücklich anordnet.","funktion":["Versuchsbeginn: Der Täter setzt nach seinem Tatplan unmittelbar zur Tatbestandsverwirklichung an (§ 22) – mehr als bloße Vorbereitung, aber der Erfolg tritt nicht ein.","Strafbarkeit: Beim Verbrechen ist der Versuch stets strafbar; beim Vergehen nur, wenn es das Gesetz ausdrücklich bestimmt (§ 23 I).","Rücktritt (§ 24): Wer freiwillig die weitere Ausführung aufgibt oder den Erfolg verhindert, wird wegen Versuchs nicht bestraft."],"schutzziel":"Schon das ernsthafte Ansetzen zur Tat erfassen – aber dem Täter durch den Rücktritt eine ‚goldene Brücke‘ zurück bauen.","kennwerte":[{"l":"Versuch","v":"unmittelbares Ansetzen, Erfolg bleibt aus"},{"l":"Verbrechen","v":"Versuch immer strafbar"},{"l":"Vergehen","v":"nur strafbar, wenn ausdrücklich"}],"begriffe":["Vorbereitung = Handlungen im Vorfeld (z. B. Werkzeug besorgen) – meist noch straflos.","Rücktritt = freiwilliges Aufgeben der Tat oder Verhindern des Erfolgs (§ 24) → Straflosigkeit des Versuchs."],"abgrenzung":["Vorbereitung gegen Versuch: Das Auskundschaften eines Objekts ist Vorbereitung; das Aufbrechen der Tür ist bereits unmittelbares Ansetzen (Versuch).","Versuch gegen Vollendung: Vollendet ist die Tat erst, wenn alle Tatbestandsmerkmale (einschließlich Erfolg) erfüllt sind."],"praxis":["Beispiel aus der Türsteher-Praxis: Wer ausholt und zuschlägt, aber verfehlt, begeht eine versuchte Körperverletzung (Vergehen – Versuch hier ausdrücklich strafbar, § 223 II).","Auch die versuchte Nötigung ist strafbar – wer mit Schlägen droht, um Einlass zu erzwingen, und scheitert, hat es versucht."]},"visual":null},{"h":"Täterschaft & Teilnahme","b":"Allein-/Mit-/mittelbarer Täter; Anstiftung, Beihilfe","detail":{"titel":"Täterschaft & Teilnahme","kat":"Strafrecht AT · Beteiligung","katCls":"stgb","merksatz":"Nicht jeder Beteiligte ist Täter. TÄTER begeht die Tat selbst (oder durch einen anderen oder gemeinschaftlich); TEILNEHMER sind der Anstifter (§ 26) und der Gehilfe (§ 27) – sie fördern eine fremde Tat.","funktion":["Täterschaft (§ 25): Täter ist, wer die Tat selbst begeht (unmittelbar), durch einen anderen begeht (mittelbar) oder gemeinschaftlich mit anderen (Mittäter).","Anstiftung (§ 26): Wer einen anderen vorsätzlich zu dessen vorsätzlicher Tat bestimmt – er weckt den Tatentschluss. Strafe wie der Täter.","Beihilfe (§ 27): Wer einem anderen zu dessen Tat vorsätzlich Hilfe leistet (z. B. Werkzeug, Schmierestehen). Die Strafe wird gemildert."],"schutzziel":"Die Rolle jedes Beteiligten richtig einordnen – wer steuert die Tat, wer stiftet an, wer hilft nur?","kennwerte":[{"l":"Täter (§ 25)","v":"begeht die Tat – selbst/mittelbar/gemeinschaftlich"},{"l":"Anstifter (§ 26)","v":"weckt den Tatentschluss – Strafe wie Täter"},{"l":"Gehilfe (§ 27)","v":"unterstützt die Tat – Strafe gemildert"}],"begriffe":["Akzessorietät = Anstiftung und Beihilfe setzen eine vorsätzliche, rechtswidrige Haupttat voraus (ohne Haupttat keine Teilnahme).","Mittäter = mehrere führen die Tat arbeitsteilig gemeinsam aus; jeder muss sich den Beitrag der anderen zurechnen lassen."],"abgrenzung":["Täter gegen Gehilfe: Der Täter beherrscht das Geschehen (Tatherrschaft); der Gehilfe leistet nur einen unterstützenden Beitrag.","Anstifter gegen Gehilfe: Der Anstifter ruft den Tatentschluss erst hervor; der Gehilfe hilft bei einer schon beschlossenen Tat."],"praxis":["Beispiel: Wer beim Ladendiebstahl ‚Schmiere steht‘, ist meist Gehilfe (Beihilfe). Wer den Diebstahl plant und einen anderen losschickt, kann Anstifter oder Mittäter sein.","Für die Anzeige wichtig: Beobachte und beschreibe, WER was getan hat – die rechtliche Einordnung der Rolle trifft die Justiz."]},"visual":null},{"h":"Unterlassungsdelikte","b":"Echte (§323c, §138, §123) vs. unechte (§13, Garantenstellung)","detail":{"titel":"Unterlassungsdelikte","kat":"Strafrecht AT · Unterlassen","katCls":"stgb","merksatz":"Strafbar ist nicht nur aktives Tun, sondern auch das pflichtwidrige UNTERLASSEN. Man unterscheidet echte Unterlassungsdelikte (das bloße Nichthandeln ist strafbar, z. B. unterlassene Hilfeleistung § 323c) und unechte (Nichtverhindern eines Erfolgs trotz Garantenpflicht, § 13).","funktion":["Echtes Unterlassungsdelikt: Das Gesetz bestraft schon das bloße Nichthandeln – z. B. § 323c (unterlassene Hilfeleistung): Wer bei einem Unglücksfall nicht hilft, obwohl es möglich und zumutbar ist.","Unechtes Unterlassungsdelikt (§ 13): Wer einen Erfolg (z. B. Schaden, Verletzung) nicht abwendet, obwohl er als ‚Garant‘ dafür einstehen muss, wird bestraft wie ein aktiver Täter.","Voraussetzung des Unterlassens: Das Handeln muss möglich, erforderlich und zumutbar gewesen sein."],"schutzziel":"Auch das Nichtstun erfassen, wenn jemand zum Handeln verpflichtet war – Untätigkeit kann so schwer wiegen wie aktives Tun.","kennwerte":[{"l":"Echtes U.-Delikt","v":"bloßes Nichthandeln strafbar (§ 323c)"},{"l":"Unechtes U.-Delikt","v":"Erfolg nicht abgewendet trotz Garantenpflicht (§ 13)"},{"l":"Grenze","v":"Handeln muss möglich & zumutbar sein"}],"begriffe":["Unterlassene Hilfeleistung (§ 323c) = bei Unglücksfällen oder Gefahr nicht helfen, obwohl möglich und zumutbar (gilt für JEDEN).","Garantenstellung = die besondere Pflicht, einen Erfolg abzuwenden (dazu die nächste Karte)."],"abgrenzung":["Echtes Unterlassungsdelikt (§ 323c) trifft JEDEN, der zumutbar helfen könnte. Unechtes (§ 13) trifft nur den GARANTEN, der für die Abwendung einstehen muss.","Tun gegen Unterlassen: Wer aktiv schädigt, begeht ein Begehungsdelikt; wer pflichtwidrig nicht eingreift, ein Unterlassungsdelikt."],"praxis":["Für jeden Bürger gilt § 323c: Bei einem Unfall musst du im Rahmen des Zumutbaren helfen (Notruf absetzen!) – sonst machst du dich strafbar.","Als Wachkraft mit Bewachungsvertrag kann zusätzlich § 13 greifen: Wer eine Gefahr im bewachten Objekt sehenden Auges ignoriert, haftet wie ein aktiver Täter."]},"visual":null},{"h":"Garantenstellung","b":"Durch Vertrag, Gesetz, Ingerenz; Garant wird wie Täter bestraft","detail":{"titel":"Garantenstellung (§ 13 StGB)","kat":"Strafrecht AT · Garant","katCls":"stgb","merksatz":"Ein Garant ist verpflichtet, einen Erfolg ABZUWENDEN. Nur wer eine Garantenstellung hat, macht sich beim unechten Unterlassungsdelikt strafbar – z. B. aus Gesetz, Vertrag, vorangegangenem gefährlichem Tun oder enger Lebensbeziehung.","funktion":["Beschützergaranten: müssen ein bestimmtes Rechtsgut schützen – z. B. Eltern für ihr Kind, Bademeister für die Badegäste.","Überwachergaranten: müssen eine Gefahrenquelle beherrschen – z. B. Hundehalter für seinen Hund, Wachdienst für das bewachte Objekt (aus Vertrag).","Entstehung: Garantenpflichten ergeben sich u. a. aus Gesetz, Vertrag (!), enger Gemeinschaft oder vorangegangenem gefährlichem Tun (Ingerenz)."],"schutzziel":"Festlegen, WER ausnahmsweise für das Nichtverhindern eines Erfolgs einstehen muss – nicht jeder, sondern nur der besonders Verpflichtete.","kennwerte":[{"l":"Beschützergarant","v":"schützt ein Rechtsgut (Eltern, Bademeister)"},{"l":"Überwachergarant","v":"beherrscht eine Gefahrenquelle (Hundehalter, Wachdienst)"},{"l":"Quellen","v":"Gesetz · Vertrag · enge Beziehung · Ingerenz"}],"begriffe":["Ingerenz = aus vorangegangenem gefährlichem Tun entsteht die Pflicht, den drohenden Erfolg abzuwenden.","Einstehenmüssen = die rechtliche Pflicht, den Erfolg wie ein aktiver Täter zu verhindern (§ 13)."],"abgrenzung":["Garant gegen Jedermann: Der Garant (§ 13) muss den ERFOLG abwenden; jeden Bürger trifft nur die allgemeine Hilfspflicht (§ 323c).","Wichtig: Ein Türsteher hat NICHT automatisch eine Garantenstellung für fremde Passanten auf der Straße – sein Vertrag bezieht sich auf das Objekt, nicht auf die ganze Umgebung."],"praxis":["Der Bewachungsvertrag begründet eine Garantenstellung für das bewachte Objekt: Wer eine erkannte Gefahr (Brand, Einbruch) sehenden Auges ignoriert, haftet wie ein aktiver Täter.","Aber Augenmaß: Außerhalb des Auftrags (z. B. eine Schlägerei auf der anderen Straßenseite) bist du als Wachkraft kein Garant – es bleibt die allgemeine Hilfspflicht (§ 323c) und Nothilfe."]},"visual":null},{"h":"Kausalität","b":"Beziehung zwischen Ursache und Wirkung","detail":{"titel":"Kausalität","kat":"Strafrecht AT · Ursache & Erfolg","katCls":"stgb","merksatz":"Kausalität ist der Ursachenzusammenhang zwischen Handlung und Erfolg. Faustformel (conditio sine qua non): Eine Handlung ist ursächlich, wenn sie nicht weggedacht werden kann, ohne dass der Erfolg entfiele.","funktion":["Bedingungstheorie (conditio sine qua non): Ursächlich ist jede Bedingung, die nicht hinweggedacht werden kann, ohne dass der konkrete Erfolg entfiele.","Erfolgsdelikte brauchen Kausalität: Ohne Ursachenzusammenhang zwischen Handlung und Erfolg ist der (vollendete) Tatbestand nicht erfüllt.","Auch beim Unterlassen wird gefragt: Hätte die gebotene Handlung den Erfolg (mit an Sicherheit grenzender Wahrscheinlichkeit) verhindert?"],"schutzziel":"Den Erfolg nur dem zurechnen, dessen Handeln (oder pflichtwidriges Unterlassen) ihn tatsächlich verursacht hat.","kennwerte":[{"l":"Faustformel","v":"Handlung nicht wegdenkbar, ohne dass Erfolg entfällt"},{"l":"Nötig bei","v":"Erfolgsdelikten (z. B. Körperverletzung, Tötung)"},{"l":"Beim Unterlassen","v":"hätte Handeln den Erfolg verhindert?"}],"begriffe":["Erfolgsdelikt = Delikt, das einen bestimmten Erfolg voraussetzt (z. B. Verletzung, Tod, Sachschaden).","conditio sine qua non = ‚Bedingung, ohne die nicht‘ – die Grundformel der Kausalitätsprüfung."],"abgrenzung":["Kausalität (hat die Handlung den Erfolg verursacht?) ist etwas anderes als Vorsatz (wollte der Täter ihn?) – beides wird getrennt geprüft.","Reine Tätigkeitsdelikte (z. B. Hausfriedensbruch) brauchen keinen Erfolg – dort spielt Kausalität keine Rolle."],"praxis":["Für die Praxis selten in Reinform – aber wichtig fürs Verständnis: Ein Schaden muss tatsächlich AUF die Handlung zurückgehen, sonst keine vollendete Tat.","Beispiel: Stürzt jemand aus einem völlig unabhängigen Grund, ist ein leichter Rempler nicht ursächlich für eine schwere Verletzung."]},"visual":null}],"quiz":[{"q":"Was bedeutet der Grundsatz ‚Keine Strafe ohne Gesetz‘ gemäß StGB?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Der Grundsatz umfasst auch, dass Strafgesetze rückwirkend erlassen und angewendet werden können","c":false},{"t":"Dieser im Grundgesetz verankerte Grundsatz dient der Einschränkung staatlicher Willkür","c":true},{"t":"Der Grundsatz gilt nur für die Straftatbestände, die im StGB beschrieben werden","c":false},{"t":"Eine Person darf nur bestraft werden, wenn ihr Verhalten einen gesetzlich umschriebenen Tatbestand erfüllt","c":true}]},{"q":"Die Straftat ist eine tatbestandsmäßige, rechtswidrige und schuldhafte Handlung. Wobei handelt es sich um eine schuldhafte menschliche Handlung?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wenn ein 12-jähriger Schüler gewollt einen anderen mittels einer Ohrfeige körperlich misshandelt","c":false},{"t":"Wenn eine Person in rechtswidriger Zueignungsabsicht eine fremde bewegliche Sache wegnimmt","c":true},{"t":"Wenn sich eine Person im Zustand der Bewusstlosigkeit bewegt und dabei eine andere verletzt","c":false},{"t":"Wenn eine Person bei einem Unglücksfall keine Hilfe leistet, obwohl dies möglich und zumutbar wäre","c":true}]},{"q":"Welche Aussagen zum objektiven und subjektiven Tatbestand sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Der objektive Tatbestand umfasst die äußeren Merkmale der Tat (z. B. Handlung, Tatobjekt, Erfolg)","c":true},{"t":"Zum subjektiven Tatbestand gehört bei Vorsatzdelikten der Vorsatz – das Wissen und Wollen der Tat","c":true},{"t":"Beim Diebstahl gehört die Zueignungsabsicht zum subjektiven Tatbestand","c":true},{"t":"Wer den äußeren Ablauf verwirklicht, erfüllt den Tatbestand eines Vorsatzdelikts auch ohne Vorsatz","c":false}]},{"q":"Welche Aussagen zur Fahrlässigkeit im strafrechtlichen Sinne sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Fahrlässiges Handeln ist nur bei Unterlassungsdelikten strafbar","c":false},{"t":"Die fahrlässige Begehung einer Straftat ist nur in den gesetzlich ausdrücklich genannten Fällen strafbar","c":true},{"t":"Bei allen Begehungsdelikten ist die fahrlässige Erfüllung des Tatbestandes mit Strafe bedroht","c":false},{"t":"Fahrlässigkeit liegt vor, wenn der Täter bei objektiver Vorhersehbarkeit und Vermeidbarkeit nach seinen individuellen Fähigkeiten die erforderliche Sorgfalt außer Acht lässt","c":true}]},{"q":"Welche Aussagen zur Schuldunfähigkeit gemäß §§ 19, 20 StGB sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wer bei der Tat noch nicht 14 Jahre alt ist, ist schuldunfähig und damit nicht strafbar","c":true},{"t":"Eine krankhafte seelische Störung kann die Schuldfähigkeit entfallen lassen (§ 20)","c":true},{"t":"Ein schuldunfähiges Kind unter 14 kann nicht als Straftäter nach § 127 StPO vorläufig festgenommen werden","c":true},{"t":"Die Strafmündigkeit beginnt bereits mit dem vollendeten 7. Lebensjahr","c":false}]},{"q":"Was sind Verbrechen gemäß StGB?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Diebstahl mit Waffen","c":false},{"t":"Meineid","c":true},{"t":"Raub","c":true},{"t":"Gefährliche Körperverletzung","c":false}]},{"q":"Welche Aussage trifft auf Vergehen im Sinne des StGB zu?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Bei Vergehen ist der Versuch stets strafbar","c":false},{"t":"Bei Vergehen ist die Strafverfolgung erst möglich, wenn ein Strafantrag gestellt wurde","c":false},{"t":"Bei Vergehen ist der Versuch nur strafbar, wenn er durch das Gesetz ausdrücklich mit Strafe bedroht ist","c":true},{"t":"Bei Vergehen ist nur Vorsatz oder Unterlassen strafbar","c":false}]},{"q":"Welche Aussagen zu Täterschaft und Teilnahme sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Täter ist, wer die Tat selbst, durch einen anderen oder gemeinschaftlich mit anderen begeht (§ 25)","c":true},{"t":"Der Anstifter (§ 26) bestimmt einen anderen vorsätzlich zu dessen Tat und wird wie der Täter bestraft","c":true},{"t":"Beim Gehilfen (§ 27) wird die Strafe gemildert","c":true},{"t":"Anstiftung und Beihilfe sind auch ohne eine vorsätzliche Haupttat strafbar","c":false}]},{"q":"Welche Aussagen zu den Unterlassungsdelikten sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Beim echten Unterlassungsdelikt ist schon das bloße Nichthandeln strafbar (z. B. unterlassene Hilfeleistung, § 323c)","c":true},{"t":"Beim unechten Unterlassungsdelikt (§ 13) wird das Nichtabwenden eines Erfolgs durch einen Garanten wie aktives Tun bestraft","c":true},{"t":"Eine Strafbarkeit wegen Unterlassens setzt voraus, dass das Handeln möglich und zumutbar war","c":true},{"t":"Unterlassene Hilfeleistung nach § 323c trifft nur Personen mit einer Garantenstellung","c":false}]},{"q":"Türsteher T sieht, wie auf der anderen Straßenseite eine Person von zwei Jugendlichen verprügelt wird. Wie handelt T rechtlich korrekt?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"T verlässt seinen Arbeitsplatz und hilft der angegriffenen Person in Nothilfe","c":true},{"t":"T übersieht den Vorfall mit Absicht, da er seinen Arbeitsplatz nicht verlassen darf","c":false},{"t":"T verständigt telefonisch die Polizei, während er sich weiter um die Einlasskontrolle kümmert","c":true},{"t":"T muss der Person helfen, sonst verletzt er seine Garantenstellung","c":false}]},{"q":"Welche Aussagen zur Kausalität im Strafrecht sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Eine Handlung ist ursächlich, wenn sie nicht hinweggedacht werden kann, ohne dass der Erfolg entfiele (conditio sine qua non)","c":true},{"t":"Erfolgsdelikte setzen einen Ursachenzusammenhang zwischen Handlung und Erfolg voraus","c":true},{"t":"Kausalität und Vorsatz sind dasselbe und müssen nicht getrennt geprüft werden","c":false},{"t":"Bei reinen Tätigkeitsdelikten kommt es auf den Eintritt eines Erfolgs nicht an","c":true}]},{"q":"Erkläre die Vorläufige Festnahme gem. §127 (1) StPO, 5 Merkmale:","a":"Grundvoraussetzung = Vorliegen einer frischen Tat (Straftat) und Betroffen oder Verfolgt und Identität nicht sofort feststellbar oder Fluchtverdacht (keine Anwendung bei Kindern möglich !)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §35 StGB Entschuldigender Notstand/Unterschiede","a":"zu §34 Rechtfertigender Notstand (Einschränkungen) Beim Entschuldigen Notstand ist die Abwendung der Gefahr nur für Leib, Leben, Freiheit oder eine nahestehende Person (z.B. Kind, Ehefrau) möglich, Beim Rechtfertigen Notstand ist die Abwehr der Gefahr für \"jedes\" Rechtsgut möglich; also auch Eigentum; Beispiel: Ihr Haus brennt (Eigentum) um dieses löschen zu können überfahren Sie den Gartenzaun Ihres Nachbarn ; (Tatbestand = Sachbeschädigung; Rechtfertigungsgrund: § 34 StGB / keine Straftat)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind Rechtfertigungsgründe und wo finde ich diese?","a":"Rechtfertigungsgründe sind erlaubte Handlungen, die durch Gesetze gerechtfertigt sind. BGB, StGB, StPO","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet fahrlässig, wann werden fahrlässige Taten bestraft?","a":"Fahrlässigkeit ist wenn man die notwendige Sorgfaltspflicht vernachlässigt, bestraft wird man nur, wenn es ausdrücklich im Gesetzt mit Strafe bedroht wird; z.B. (§ 229 StGB „fahrlässige Körperverletzung“)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist ein Versuch und wann ist ein Versuch strafbar?","a":"Ein Versuch ist die Verwirklichung der Vorstellung von der Tat durch unmittelbares ansetzten (Zigarettenautomat aufbrechen) Jedes Verbrechen ist im Versuch strafbar. Beim Vergehen ist der Versuch nur strafbar, wenn durch ein Gesetz bestimmt ist; z.B. Diebstahl","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Unterschied Vergehen und Verbrechen?","a":"Der Unterschied liegt im Strafmaß. - Vergehen: Mindestfreiheitsstrafe unter einen Jahr oder Geldstrafe - Verbrechen: Mindestfreiheitsstrafe über einen Jahr","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie die 3 echten Unterlassungsdelikte und was sind unechte","a":"Unterlassungsdelikte? „Echte“ Unterlassungsdelikte stehen echt im Gesetz (Text/Tatbestand); Es sind Straftaten die auf Unterlassung beruhen; Merke: keine Garantenpflicht! (Nichtanzeige von Straftaten, unterlassene Hilfeleistung, Hausfriedensbruch (2te Begehungsart = Verweilen trotz Aufforderung) „Unechte“ Unterlassungsdelikte liegen vor wen jemand rechtlich dazu verpflichtet ist (Garantenstellung) und es unterlässt eine strafbare Handlung abzuwenden, diese werden im §13 StGB zusammengefasst; z.B. nicht Salzstreuen, keine Fahrzeugkontrolle durchführen, Unterschied liegt in der Bestrafung! Garant wird bei Unterlassen wie Täter bestraft; z.B. Ladendetektiv lässt absichtlich Bekannten mit Diebesgut flüchten (§ 242,13 StGB, Diebstahl durch Unterlassen !)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie wird man ein Garant?","a":"- Durch Vertrag (Bewachungsauftrag) - Gesetz (Eheleute) - Selbst geschaffener Gefahren (Öffnen eines Schachtes; INGERENZ)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was besagt §229 StGB fahrlässige Köperverletzung?","a":"Wenn man durch Fahrlässigkeit eine körperliche Schädigung bei einer anderen Person verursacht. Merke: Es gibt keine fahrlässige, gefährliche, schwere Körperverletzung; Entweder es ist mit Vorsatz oder Fahrlässig geschehen; (Möglichkeiten der Fahrlässigkeit: Fahrlässige KV, § 229 StGB oder Fahrlässige Tötung, § 222 StGB)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine Sache, sind Tiere Sachen?","a":"Sachen sind nur körperliche Gegenstände (feste, flüssige, gasförmige) Tiere sind keine Sache, werden aber für Sachen geltende Gesetzte als dieses anzusehen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was können Sie mir zum Thema Sachen sagen?","a":"Sachen sind körperliche Gegenstände Sachen können beweglich oder unbeweglich sein Tiere sind keine Sachen – sie werden durch besondere Gesetze geschützt-für sie werden jedoch die gleichen Rechtsvorschriften wie für Sachen genommen, wenn die speziellen Gesetze für Tier nicht greifen (z.B.: Notstand nach §228 BGB)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist der Unterschied zwischen Vergehen und Verbrechen?","a":"Vergehen- Freiheitstrafe ab unter einem Jahr, nach oben offen\toder- Geldstrafe Verbrechen- Freiheitsstrafe ab einem Jahr, nach oben offen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wann ist der Versuch einer Straftat strafbar?","a":"Vergehen- nur strafbar, wenn es das Gesetz (der jeweilige Paragraph) ausdrücklich bestimmt Verbrechen- der Versuch ist immer strafbar","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was muss für eine strafbare Handlung erfüllt sein ?","a":"Tatbestandsmäßigkeit Rechtswidrigkeit Schuldfähigkeit Wenn nur einer der drei Punkte nicht erfüllt ist, ist es keinestrafbare Handlung und folglich keine Straftat","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was verstehen Sie unter einem Diebstahl mit Waffe?","a":"Diebstahl im Sinne des § 242 StGB + Täter führt eine Waffe* oder gefährliches Werkzeug* mit sich * Alles, was laut Waffengesetz als Waffe definiert ist, + andere Gegenstände wie Baseballschläger etc.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Aufbau/Element der Straftat (3 Säulen)","a":"Tatbestand, Rechtswidrigkeit, Schuld + Verfahrensvoraussetzungen (z.B. Strafantrag)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"In welche Teile ist das StGB unterteilt?","a":"In den allgemeinen Teil (Voraussetzung der Strafbarkeit) und den besonderen Teil (Tatbestand der Straftat)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie kann man eine Straftat begehen?","a":"Indem man durch eine tatbestandmäßige, rechtswidrige und schuldhafte Handlung gegen eine Rechtsnorm verstößt.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Begehen durch Unterlassen gem. §13 StGB?","a":"Wenn man es unterlässt einen Erfolg abzuwenden der zumTatbestand einer Straftat gehört; (rechtliche Verpflichtung gefordert !)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §123 StGB Hausfriedensbruch, Tatbestandsmerkmale (genau)","a":"Widerrechtliches eindringen in Wohnung, Geschäftsraum, befriedetes Besitztum..., abgeschlossene Räume die zum öffentlichen Verkehr bestimmt sind (Busse, Bahn), eindringt oder darin Aufhält und sich nach Aufforderung nicht entfernt, wird bestraft; Absolutes Antragsdelikt","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §132 StGB Amtsanmaßung, Tatbestandsmerkmale.","a":"Wer sich als Inhaber eines öffentliches Amtes ausgibt oder danach handelt, ohne diese innezuhaben.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §138 StGB Nichtanzeige geplanter Straftaten,","a":"Tatbestandsmerkmale. Fallbeispiel: Bombendrohung in Asylheim Wer vor der Tatausübung von einer Straftat erfährt und es unterlässt bei der Behörde rechtzeitig eine Anzeige zu machen; (echtes Unterlassungsdelikt)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §223 StGB Körperverletzung, Tatbestandmerkmale","a":"(genaue Bezeichnung) Wer einer anderen Person körperlich misshandelt oder an der Gesundheit schädigt, relatives Antragsdelikt, Vergehen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie wird eine einfache Körperverletzung zur gefährlichen","a":"Körperverletzung §224 StGB, nenne alle Tatbestandsmerkmale. Sie qualifiziert sich durch beibringen von Gift, Waffe oder gefährliches Werkzeug, gemeinschaftlich, hinterlistiger Überfall oder einer das Leben gefährdende Behandlung; Offizialdelikt, Vergehen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §226 StGB Schwere Körperverletzung, Tatbestandsmerkmale.","a":"Sie qualifiziert sich durch Verlust des Gehörs, Motorik, Sprachvermögen, Sehvermögen, wichtiges Körperglied, Siechtum; Offizialdelikt, Verbrechen ! Eine weitere ist die Körperverletzung mit Todesfolge § 227 StGB","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §239 StGB Freiheitsberaubung, Tatbestandsmerkmale.","a":"Wer einen anderen Menschen einsperrt oder auf einer anderen Weise die Freiheit raubt; K.O. Tropfen etc.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §240 StGB Nötigung, Tatbestandsmerkmale.","a":"Wer einen anderen Menschen rechtswidrig mit Gewalt oder durch Drohung mit einem empfindlichen Übel zu einer Handlung, Duldung oder Unterlassen nötigt.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §242 Diebstahl, Tatbestandsmerkmale (genaue Bezeichnung)","a":"Wegnahme einer fremden beweglichen Sache mit rechtswidriger Zueignungsabsicht (Stehlabsicht für sich selber oder Dritten).","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie wird ein einfacher Diebstahl zum besonders schweren","a":"Fall des Diebstahls gem. §243 StGB, Nenne alle Tatbestandsmerkmale. - In einen Geschäftsraum o.ä. einbrechen, einsteigen oder sich verborgen halten, - sich mit falschem Schlüssel Zutritt verschafft. - Eine Sache stiehlt die durch eine besondere Schutzvorrichtung gesichert ist, - Wer gewerbsmäßig stielt, Kirchendiebstahl, Museums-, Ausstellungsdiebstahl, - die Hilflosigkeit oder Unglücksfall anderer ausnutzt oder Handfeuerwaffen stehlen. In den Fällen des Absatzes 1 Satz 2 Nr. 1 bis 6 ist ein besonders schwerer Fall ausgeschlossen, wenn sich die Tat auf eine geringwertige Sache bezieht.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Bandendiebstahl, Tatbestandsmerkmale.","a":"Der Täter begeht den Diebstahl als Mitglied einer Bande; mind. 3 Personen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §249 StGB Raub, Tatbestandsmerkmale.","a":"Der Täter will einer anderen Person durch Gewalt oder Anwendung von Drohungen mit gegenwärtiger Gefahr für Leib und Leben eine fremde bewegliche Sache wegnehmen; Erst hauen, dann klauen!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §252 StGB Räuberischer Diebstahl, Tatbestandsmerkmale.","a":"Der Täter will durch Gewaltausübung oder Anwendung von Drohungen mit gegenwärtiger Gefahr auf Leib und Leben des Besitzt des Diebesgut erhalten; Erst klauen, dann hauen!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §263 StGB Betrug, Tatbestandsmerkmale.","a":"Betrug ist die Erregung eines Irrtums durch Täuschungshandlung, mit der Absicht sich einen Vermögensvorteil zu verschaffen und ein vermögensnachteil für den anderen im Kauf nimmt.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere $265a StGB Erschleichen von Leistungen, Tatbestandsmerkmale.","a":"Wer die Leistung eines Automaten, Telekommunikationsnetzes, Beförderung durch öffentliche Verkehrsmittel, Zutritt zu Veranstaltungen oder Einrichtungen erschleicht mit der Absicht das Entgelt nicht zu entrichten.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §267 Urkundenfälschung, Tatbestandsmerkmale.","a":"Wer falsche Urkunden herstellt oder echte Urkunden verfälscht wird erst dann bestraft wenn sie in den Rechtsverkehr einbringt.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §303 StGB Sachbeschädigung, Tatbestandsmerkmale.","a":"Wer rechtswidrig eine fremde Sache beschädigt, zerstört, das Erscheinungs- bild unerheblich oder vorübergehend verändert begeht Sachbeschädigung.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere § 323c StGB Unterlassene Hilfeleistung, Tatbestandsmerkmale.","a":"Wer bei Unglücksfällen, gemeiner Gefahr oder Not nicht Hilfe leistet, obwohl dieses erforderlich und ihm den Umständen nach zuzumuten ist ohne erhebliche eigene Gefahr und ohne Verletzung anderer wichtigen Pflichten möglich ist. (echtes Unterlassungsdelikt)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind Rechte und Pflichte eines Zeugen gem. der StPO.","a":"Der Zeuge muss vor Gericht erscheinen, zur Sache aussagen, er kann aber die Aussage verweigern wen er sich selbst belastet oder ein Familienangehörigen. 76 Zeugnis- bzw. Auskunftsverweigerungsrecht, was besagt dieses? Wen er sich selbst oder ein Familienangehörigen dadurch belastet, hat das Recht diese zu verweigern. Fallbeispiel: a) Jemand bricht mit einem Stemmeisen den Kofferraum eines PKW auf um zu stehlen, b) Jemand bricht mit einem Stemmeisen in eine Wohnung ein um zu stehlen ? Wo ist der Unterschied ? Der Unterschied ist zum einen der Tatbestand und zum anderen das Strafmaß Bei a) liegt ein Besonders schwerer Fall des Diebstahls gem. § 243 StGB Nr. 2 vor (eine Sache stiehlt, die durch ein verschlossenes Behältnis oder eine andere Schutzvorrichtung gegen Wegnahme besonders gesichert ist). Bei b) liegt ein Wohnungseinbruchsdiebstahl gemäß § 244 StGB vor (einen Diebstahl begeht, bei dem er zur Ausführung der Tat in eine Wohnung einbricht, einsteigt, mit einem falschen Schlüssel oder einem anderen nicht zur ordnungsmäßigen Öffnung bestimmten Werkzeug eindringt oder sich in der Wohnung verborgen hält)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie unter dem (Verteidigungs-) Notstand gem. §228 BGB?","a":"Verteidigung gegen eine Gefahr durch Sache (oder Tier) Durch Beschädigung oder Zerstörung dieser Sache (von der die Gefahr ausgeht) rechtfertigt eine unerlaubte Handlung und befreit somit von Schadensersatz AUSSER !!!=Ich habe die Gefahr selbst verschuldet","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Ab welchem Alter ist ein Mensch gem. StGB  schuldfähig?","a":"Ab dem vollendeten 14. Lebensjahr","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wann ist ein Diebstahl ein Diebstahl (Tatbestände)?","a":"Eine fremde bewegliche Sache einem anderen wegnehmen (Wegnahmeabsicht) um sie sich oder einem Dritten rechtswidrig zueignen (Zueignungsabsicht)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Benennen Sie die Tatbestandsmerkmale der Körperverletzung nach § 223 StGB !","a":"Einen anderen Menschen Körperlich misshandeln\toder an der Gesundheit schädigen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was versteht man unter dem Straftatbestand der Begünstigung?","a":"Ein anderer hat eine rechtswidrige Tat begangen Der Täter (der Begünstigung) hilft dem Vortäter In der Absicht, die Vorteile seiner Tat zu sichern (Jens will 30.000,00 € aus einem Raub bei Pierre verstecken, Pierre weiß woher das Geldkommt und versteckt das Geld für Jens.)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was versteht man unter dem Straftatbestand der Hehlerei?","a":"Ein anderer hat eine Sache durch ein Vermögensdelikt rechtswidrig erlangt (Diebstahl, Raub, Unterschlagung, etc.) Der Hehler (Täter) kauft diese Sachen, verkauft sie oder, setzt sie ab oder hilft dabei oder erwirbt sie für sich selbst oder einen Dritten ! Der Stehler (z.B.: Dieb) ist nicht der Hehler !","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Tatbestandsmerkmale hat die Nötigung?","a":"Einen anderen Menschen durch Anwendung von Gewalt oder Androhung von Gewalt oder empfindliches Übel zu einem Tun, Dulden oder Unterlassen nötigen !!! Der Versuch ist strafbar !!!","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was bedeutet vorsätzlich?","a":"Mit wissen und wollen eine widerrechtliche Handlung begeht.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was genau steht im §823 BGB Schadensersatzplicht?","a":"Wer vorsätzlich oder fahrlässig das Leben, den Körper, die Gesundheit, die Freiheit, das Eigentum oder ein sonstiges Recht eines anderen widerrechtlich verletzt, ist zum Ersatz des daraus entstandenen Schadens verpflichtet.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was verstehen Sie unter einer unerlaubten Handlung?","a":"Widerrechtlich Vorsätzlich oderfahrlässig Verletzung fremder Rechtsgüter (Leben, Leib, Freiheit und alle anderen) Wenn die unerlaubte Handlung zu einem Schaden führt, führt sie ebenfalls zu Schadensersatzpflicht","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist der Unterschied zwischen Vorsatz und Fahrlässigkeit ?","a":"Vorsatz- absichtliches Handeln- mit „Wissen und Wollen“ Fahrlässigkeit- unabsichtliches Handeln („ausversehen“)- „die nötige Sorgfalt außer Acht lassen“","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Körperverletzungsdelikte sind für die private Sicherheit relevant ?","a":"„einfache“ Körperverletzung Gefährliche Körperverletzung Schwere Körperverletzung Fahrlässige Körperverletzung","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wie kann ich eine Sachbeschädigung begehen?","a":"NUR vorsätzlich !!!!!!!!! Eine Sachbeschädigung kann nicht fahrlässig begangen werden","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Kinder §19 StGB, Welche 3 Eingriffsrechte habe ich?","a":"Man darf Sie festnehmen (Allgemeine Selbsthilfe, § 229 BGB), Diebesgut abnehmen (Besitzkehr, § 860 BGB), gegenwärtigen rechtswidrigen Angriff auf Eigentum abwehren (Notwehr, § 32 StGB).","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nenne Deliktarten.","a":"- Offizialdelikte, - Antragsdelikte - Begehungsdelikte, - Unterlassungsdelikte - Vergehen, Verbrechen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist ein Offizialdelikt, Was ist ein Antragsdelikt?","a":"Grundsätzlich sind alle Straftaten Offizialdelikte. Alle Verbrechen sind Offizial- delikte, aber auch Antragsdelikte wenn ein öffentliches Interesse besteht; (sogenannte „relative“ Antragsdelikte) Antragsdelikte sind Straftaten die einen Strafantrag erfordern; sogenannte Bagatellstraftaten (Diebstahl unter 50 €, einfache Körperverletzung, Sachbeschädigung) muss vom Betroffenen innerhalb von 3 Monaten erfolgen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre den Begriff Wohnungseinbruchdiebstahl","a":"Wer bei einem Diebstahl in eine Wohnung einbricht, einsteigt, mit falschen Schlüssel, Werkzeug oder sich in der Wohnung verborgen hält. Wird nach § 244 StGB bestraft; Seit 22.07.2017 VERBRECHEN!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Handlungen erlaubt die allgemeine Selbsthilfe nach","a":"§229 BGB? Eine Sache darf weggenommen, beschädigt oder zerstört werden; z.B. Fahrradschloss aufbrechen; Man darf die Person festnehmen (bei Fluchtverdacht). Man darf den Widerstand des Täters mit verhältnismäßiger Gewalt brechen die dieser dulden muss.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Täterschaft und Teilnahme, Wer ist Täter und wer Teilnehmer?","a":"Täter ist wer als Alleintäter, Mittäter oder Mittelbarer Täter eine Straftat begeht. Teilnehmer ist, wer nicht aktiv dabei ist; also der Anstifter und derjenige der Beihilfe zur Tat leistet (Fluchtwagen besorgen, Sicherheitscode weitergeben etc.)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist ein mittelbarer Täter?","a":"Ein mittalbarer Täter ist der, der einen anderen als \"Werkzeug\" für seine Tat benutzt; (Arzt gibt der ahnungslosen Schwester eine Ampulle mit Gift)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist der Unterschied zwischen Diebstahl und Unterschlagung ?","a":"Diebstahl- „Wegnahmeabsicht“ und (rechtswidrige) „Zueignungsabsicht“ müssen vorliegen Unterschlagung- hier „fehlt die Wegnahmeabsicht“- es muss lediglich die (rechtswirdrige) „Zueignungsabsicht“ zu der fremden beweglichen Sache vorliegen- der Täter hat die Sache bereits","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Täterschaftsformen gibt es?","a":"Mittäter Alleintäter","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Voraussetzungen benötigt vorläufige Festnahme im 127 StPO ?","a":"Auf frischer Tat betroffen oder verfolgt(Tat = Straftat) Identität ist nicht sofort feststellbar\toder es besteht Fluchtverdacht = diese Voraussetzungen berechtigen zur vorläufigen Festnahme des Täters","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was wird mit der vorläufigen Festnahme gerechtfertigt ?","a":"Die Freiheitsberaubung nach § 239 StGB gegenüber dem Täter Die Körperverletzung nach § 223 StGB gegenüber dem Täter(im verhältnismäßigen Rahmen)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Erläute die Selbsthilfe des Besitzdieners §860 BGB","a":"Der Besitzdiener kann sich wie der Besitzer gegen die verbotene Eigenmacht mit Besitzwehr und Besitzkehr wehren, soweit ihm diese Rechte übertragen worden sind.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine Unerlaubte Handlung im BGB","a":"Unerlaubte Handlungen sind widerrechtliche Eingriffe in die Rechte einer Person (Freiheit, Gesundheit, Eigentum,...), die einen Anspruch auf Schadensersatz nach § 823 BGB fordern","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist ein sogenanntes Schikaneverbot?","a":"Die Ausübung eines Rechtes ist dann unzulässig, wenn sie nur den Zweck haben kann, einem anderen einen Schaden zuzufügen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Ab welchem Zeitpunkt ist der Mensch im Sinne des BGB Rechtsfähig?","a":"Ab Vollendung seiner Geburtbedeutet: ab diesem Zeitpunkt darf der Mensch die Rechte aus dem deutschen Rechtssystem (z.B.: Rechtsgüter gem. GG) in Anspruch nehmen, er hat aber auch die damit verbundenen Pflichten.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was versteht man unter einem Anspruch?","a":"Es ist das Recht, von einem anderen etwas (Handeln oder Unterlassen) zu fordern Derjenige von dem ich dies fordern kann nennt sich Verpflichteter(er ist rechtlich verpflichtet, meinen Anspruch zu erfüllen)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist eine Urkundenfälschung?","a":"Eine unechte Urkunde herstellen oder Eine echte Urkunde verfälschen (abändern) oder eine gefälschte oder unechte Urkunde nutzen um im Rechtsverkehr zu täuschen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Hat ein Sicherheitsmitarbeiter auch Verpflichtungen?","a":"Ja, er übernimmt durch seinen Bewachungsauftrag die Verpflichtung fremde Personen und fremdes Eigentum zu schützen, mit seiner Aufgabe übernimmt er eine Garantenstellung (durch Vertrag)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre den Begriff Kausalität.","a":"Kausalität ist die Beziehung zwischen Ursache und Wirkung, betrifft also die Abfolge aufeinander bezogener Ereignisse.","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[{"scenario":"Ein SMA übernimmt vertraglich die Bewachung eines Objekts. Nachts bemerkt er einen Schwelbrand, tut aber nichts, obwohl er gefahrlos hätte eingreifen können. Es entsteht Schaden.","frage":"Warum kann er sich strafbar gemacht haben, obwohl er nichts „getan“ hat?","loesung":"Durch seinen Bewachungsvertrag hat er eine Garantenstellung (§13 StGB) – er muss den Erfolg abwenden. Unterlässt er das, wird das Unterlassen wie aktives Tun bestraft (unechtes Unterlassungsdelikt). Daneben kann §323c (unterlassene Hilfeleistung) greifen."}]},{"n":5,"title":"Strafverfolgung (StPO)","subtitle":"7 Konzepte · 19 Prüfungsfragen","cards":[{"h":"Vorläufige Festnahme §127 StPO","b":"Frische Tat, betroffen/verfolgt, Identität ungeklärt oder Fluchtverdacht; nicht bei Kindern","detail":{"titel":"Vorläufige Festnahme (§ 127 StPO)","kat":"Strafverfolgung · § 127 StPO","katCls":"stpo","merksatz":"§ 127 Abs. 1 StPO ist das ‚Jedermannsrecht‘: JEDER darf einen auf frischer Tat betroffenen oder verfolgten Straftäter vorläufig festnehmen, wenn dieser fliehen könnte oder seine Identität nicht sofort feststellbar ist.","funktion":["Voraussetzung 1 – frische Tat: Der Täter wird bei einer verfolgbaren STRAFTAT auf frischer Tat betroffen oder verfolgt (am Tatort oder in dessen unmittelbarer Nähe).","Voraussetzung 2 – Festnahmegrund: Es besteht Fluchtverdacht ODER die Identität ist nicht sofort feststellbar.","Rechtsfolge: Erlaubt ist nur das vorläufige Festhalten – die Person ist unverzüglich der Polizei zu übergeben. Keine Vernehmung, keine Durchsuchung, keine Bestrafung."],"schutzziel":"Dem Bürger erlauben, einen Straftäter bis zum Eintreffen der Polizei festzuhalten – damit er sich der Strafverfolgung nicht entzieht.","kennwerte":[{"l":"Wer","v":"jedermann (auch Wachpersonal)"},{"l":"Wann","v":"frische STRAFTAT + Fluchtverdacht/ID unklar"},{"l":"Wie weit","v":"nur festhalten, dann sofort an die Polizei"}],"begriffe":["Auf frischer Tat = bei der Tat oder unmittelbar danach am Tatort oder in dessen Nähe betroffen bzw. verfolgt.","Fluchtverdacht = es ist mit hoher Wahrscheinlichkeit zu erwarten, dass sich der Täter der Verfolgung entzieht, wenn er nicht festgehalten wird."],"abgrenzung":["Nur bei STRAFTATEN – nicht bei Ordnungswidrigkeiten (z. B. Falschparken) und nicht bei bloßem Verdacht auf eine künftige Tat.","Lässt sich die Person sofort mit gültigem Ausweis identifizieren und besteht kein Fluchtverdacht, entfällt der Festnahmegrund – dann KEINE Festnahme.","Wer ohne Voraussetzungen festhält, riskiert selbst eine Freiheitsberaubung (§ 239 StGB)."],"praxis":["Klassiker Ladendiebstahl: Wird jemand beim Diebstahl betroffen und ist seine Identität unklar, darf er bis zur Polizei festgehalten werden – verhältnismäßig und nur so lange wie nötig.","Achtung Schuldunfähigkeit: Ein Kind unter 14 begeht KEINE Straftat – damit fehlt die Grundlage für § 127. Auch eine fahrlässige Sachbeschädigung ist keine Straftat (straflos) → keine Festnahme."]},"visual":null},{"h":"Offizial- vs. Antragsdelikt","b":"Strafverfolgungszwang vs. Strafantrag (3 Monate); relatives Antragsdelikt bei öff. Interesse","detail":{"titel":"Offizial- & Antragsdelikt","kat":"Strafverfolgung · Verfolgbarkeit","katCls":"stpo","merksatz":"Die meisten Straftaten sind OFFIZIALDELIKTE – der Staat verfolgt sie von Amts wegen, auch ohne dass jemand das verlangt. ANTRAGSDELIKTE (z. B. Beleidigung, Hausfriedensbruch) werden nur verfolgt, wenn der Verletzte einen Strafantrag stellt.","funktion":["Offizialdelikt: Die Staatsanwaltschaft muss von Amts wegen ermitteln, sobald sie von der Tat erfährt – z. B. Diebstahl, Raub, Körperverletzung (Regelfall).","Antragsdelikt: Verfolgung nur auf Strafantrag des Verletzten – z. B. Beleidigung (§ 185), Hausfriedensbruch (§ 123), Sachbeschädigung (§ 303).","Relatives Antragsdelikt: grundsätzlich Antrag nötig, aber die Staatsanwaltschaft kann bei ‚besonderem öffentlichem Interesse‘ trotzdem von Amts wegen verfolgen (z. B. einfache Körperverletzung, § 230)."],"schutzziel":"Bei weniger schweren oder höchstpersönlichen Taten dem Verletzten die Entscheidung überlassen, ob überhaupt verfolgt wird.","kennwerte":[{"l":"Offizialdelikt","v":"Verfolgung von Amts wegen (Regel)"},{"l":"Antragsdelikt","v":"nur auf Strafantrag des Verletzten"},{"l":"relativ","v":"Antrag ODER öffentliches Interesse"}],"begriffe":["Von Amts wegen = der Staat wird selbst tätig, ohne dass es eines Antrags bedarf.","Strafantrag = die ausdrückliche Erklärung des Verletzten, dass er die Verfolgung der Tat wünscht."],"abgrenzung":["Diebstahl und Unterschlagung sind Offizialdelikte (und Vergehen). Beleidigung und Hausfriedensbruch sind Antragsdelikte.","Ob ein Antragsdelikt vorliegt, steht im Gesetz beim jeweiligen Tatbestand (‚Die Tat wird nur auf Antrag verfolgt‘)."],"praxis":["Für die Praxis: Bei einem Diebstahl ermittelt die Polizei ohnehin (Offizialdelikt). Bei einer Beleidigung gegen dich musst du selbst Strafantrag stellen, sonst passiert nichts.","Ein Festhalten nach § 127 setzt eine verfolgbare Straftat voraus – bei reinen Antragsdelikten ist im Einzelfall Vorsicht geboten."]},"visual":null},{"h":"Strafantrag & Antragsberechtigung","b":"Opfer oder Bevollmächtigter (z.B. SMA); innerhalb 3 Monaten","detail":{"titel":"Strafantrag & Antragsberechtigung","kat":"Strafverfolgung · Strafantrag","katCls":"stpo","merksatz":"Der Strafantrag ist die Erklärung des Verletzten, dass er die Verfolgung wünscht. Er muss innerhalb von DREI MONATEN ab Kenntnis von Tat und Täter gestellt werden (§ 77b StGB) und kann zurückgenommen werden.","funktion":["Antragsberechtigt ist grundsätzlich der Verletzte der Tat (bei Minderjährigen die gesetzlichen Vertreter).","Frist: Der Antrag muss binnen drei Monaten ab Kenntnis von Tat UND Täter gestellt werden – danach ist er verfristet (§ 77b StGB).","Rücknahme: Ein Strafantrag kann zurückgenommen werden (§ 77d StGB); eine zurückgenommene Erklärung kann nicht erneut gestellt werden."],"schutzziel":"Dem Verletzten ein klares, fristgebundenes Verfahren geben, mit dem er die Verfolgung eines Antragsdelikts auslösen oder beenden kann.","kennwerte":[{"l":"Wer","v":"der Verletzte (Antragsberechtigter)"},{"l":"Frist","v":"3 Monate ab Kenntnis von Tat & Täter"},{"l":"Rücknahme","v":"möglich (§ 77d StGB)"}],"begriffe":["Verletzter = derjenige, dessen Rechtsgut durch die Tat unmittelbar betroffen ist.","Verfristung = der Ablauf der Frist, nach dem ein Antrag nicht mehr wirksam gestellt werden kann."],"abgrenzung":["Der Strafantrag (Antragsdelikt) ist nicht zu verwechseln mit der Strafanzeige: Jeder kann eine Anzeige erstatten (bloße Mitteilung); den Strafantrag kann nur der Berechtigte stellen.","Bei Offizialdelikten braucht es keinen Antrag – die Anzeige genügt, der Rest läuft von Amts wegen."],"praxis":["Praxisrelevanz: Wer beleidigt oder dessen Eigentum beschädigt wurde, sollte die Drei-Monats-Frist im Blick behalten – sonst verfällt das Antragsrecht.","Die Anzeige bei der Polizei kann zugleich den Strafantrag enthalten; im Zweifel ausdrücklich ‚Ich stelle Strafantrag‘ erklären."]},"visual":null},{"h":"Legalitätsprinzip","b":"Strafverfolgungszwang für Staatsanwaltschaft/Polizei","detail":{"titel":"Legalitätsprinzip","kat":"Strafverfolgung · Grundsatz","katCls":"stpo","merksatz":"Das Legalitätsprinzip verpflichtet Staatsanwaltschaft und Polizei, bei einem Anfangsverdacht wegen einer Straftat zu ermitteln und sie zu verfolgen – sie haben kein freies Ermessen. Das sichert eine gleichmäßige, willkürfreie Strafverfolgung.","funktion":["Verfolgungszwang: Bei zureichenden tatsächlichen Anhaltspunkten für eine verfolgbare Straftat (Anfangsverdacht) MUSS ermittelt werden (§§ 152 II, 163 StPO).","Ziel: gleiche Behandlung aller – niemand wird aus Willkür verschont oder härter verfolgt.","Gegenstück Opportunitätsprinzip: Bei Ordnungswidrigkeiten und in bestimmten gesetzlich geregelten Fällen darf nach Ermessen von der Verfolgung abgesehen werden (Ausnahme)."],"schutzziel":"Strafverfolgung an feste Regeln binden – nicht an Willkür, Beziehungen oder Stimmung.","kennwerte":[{"l":"Wer","v":"Staatsanwaltschaft & Polizei"},{"l":"Pflicht","v":"ermitteln bei Anfangsverdacht"},{"l":"Ausnahme","v":"Opportunität (v. a. bei OWi)"}],"begriffe":["Anfangsverdacht = zureichende tatsächliche Anhaltspunkte, dass eine verfolgbare Straftat begangen wurde.","Opportunitätsprinzip = das Gegenstück: Verfolgung nach pflichtgemäßem Ermessen (Ausnahmefälle)."],"abgrenzung":["Das Legalitätsprinzip gilt für die STRAFverfolgung. Im Ordnungswidrigkeitenrecht gilt überwiegend das Opportunitätsprinzip (die Behörde KANN verfolgen).","Es richtet sich an die Behörden – nicht an private Wachkräfte; diese haben keine hoheitlichen Ermittlungsbefugnisse."],"praxis":["Folge für die Praxis: Zeigst du eine Straftat an und liegt ein Anfangsverdacht vor, muss die Staatsanwaltschaft ermitteln – sie darf die Sache nicht einfach ‚liegen lassen‘.","Als private Sicherheitskraft sammelst du Hinweise und übergibst sie – die Ermittlung selbst ist Sache der Behörden."]},"visual":null},{"h":"Rechte/Pflichten des Zeugen","b":"Erscheinen, aussagen; Zeugnis-/Auskunftsverweigerungsrecht","detail":{"titel":"Rechte & Pflichten des Zeugen","kat":"Strafverfolgung · Zeuge","katCls":"stpo","merksatz":"Als Zeuge vor Gericht oder Staatsanwaltschaft gilt: erscheinen, aussagen und die Wahrheit sagen. Davon gibt es Ausnahmen – z. B. das Zeugnisverweigerungsrecht für Angehörige und das Auskunftsverweigerungsrecht bei Selbstbelastung.","funktion":["Erscheinenspflicht: Wer ordnungsgemäß als Zeuge geladen ist, muss zum Termin erscheinen (sonst drohen Ordnungsmittel).","Wahrheitspflicht: Der Zeuge muss vollständig und wahrheitsgemäß aussagen – eine Falschaussage ist strafbar (uneidlich § 153, Meineid § 154).","Verweigerungsrechte: Angehörige des Beschuldigten dürfen das Zeugnis verweigern (§ 52 StPO); zu Fragen, die einen selbst belasten würden, gibt es ein Auskunftsverweigerungsrecht (§ 55 StPO)."],"schutzziel":"Die Wahrheitsfindung sichern – aber niemanden zwingen, nahe Angehörige zu belasten oder sich selbst zu beschuldigen.","kennwerte":[{"l":"Pflichten","v":"erscheinen · aussagen · Wahrheit"},{"l":"§ 52","v":"Zeugnisverweigerung für Angehörige"},{"l":"§ 55","v":"Auskunftsverweigerung bei Selbstbelastung"}],"begriffe":["Zeugnisverweigerungsrecht (§ 52) = Angehörige des Beschuldigten dürfen die Aussage insgesamt verweigern.","Auskunftsverweigerungsrecht (§ 55) = man muss einzelne Fragen nicht beantworten, wenn die Antwort einen selbst strafrechtlich belasten würde."],"abgrenzung":["Zeuge (sagt über Wahrnehmungen aus) ist nicht gleich Beschuldigter (gegen den ermittelt wird) – der Beschuldigte muss gar nichts sagen.","Vor der POLIZEI besteht für Zeugen nicht in jedem Fall eine Erscheinens- und Aussagepflicht wie vor Gericht oder Staatsanwaltschaft – deren Ladung ist verbindlicher."],"praxis":["Sehr praxisnah: Als Wachkraft oder Ladendetektiv wirst du häufig Zeuge. Vor Gericht musst du erscheinen und wahrheitsgemäß aussagen.","Du darfst zur Auffrischung deiner Erinnerung schriftliche Unterlagen (z. B. deinen Vorfallbericht) verwenden – gute Dokumentation zahlt sich aus."]},"visual":null},{"h":"Dinglicher Arrest","b":"Bei Wegnahme von Sachen; beantragt die Polizei","detail":{"titel":"Dinglicher Arrest","kat":"Strafverfolgung · Vermögenssicherung","katCls":"stpo","merksatz":"Der dingliche Arrest (Vermögensarrest, §§ 111e ff. StPO) sichert GELDforderungen des Staates: Das Vermögen eines Beschuldigten kann vorläufig ‚eingefroren‘ werden – z. B. um spätere Einziehung oder Geldstrafen zu sichern. Er richtet sich gegen das VERMÖGEN, nicht gegen die Person.","funktion":["Zweck: Sicherung künftiger Geldforderungen des Staates (z. B. Wertersatz-Einziehung von Taterträgen, Geldstrafe, Verfahrenskosten).","Wirkung: vorläufige Sicherstellung bzw. ‚Einfrieren‘ von Vermögenswerten (Konten, Sachen), damit der Beschuldigte sie nicht beiseiteschafft.","Anordnung: grundsätzlich durch das Gericht, bei Gefahr im Verzug durch die Staatsanwaltschaft."],"schutzziel":"Verhindern, dass ein Beschuldigter sein Vermögen verschwinden lässt, bevor der Staat berechtigte Geldforderungen durchsetzen kann.","kennwerte":[{"l":"Richtet sich gegen","v":"das Vermögen (nicht die Person)"},{"l":"Zweck","v":"Sicherung von Geldforderungen"},{"l":"Anordnung","v":"Gericht (Eilfall: Staatsanwaltschaft)"}],"begriffe":["Einziehung = die Abschöpfung von Taterträgen oder Wertersatz zugunsten des Staates.","Dinglich = sich auf eine Sache oder das Vermögen beziehend (im Gegensatz zu ‚persönlich‘)."],"abgrenzung":["Dinglicher Arrest (Vermögen) ist nicht die Untersuchungshaft (Person): Der Arrest ‚verhaftet‘ Geld und Sachen, nicht den Menschen.","Er ist eine staatliche Maßnahme im Verfahren – kein Mittel, das einer privaten Wachkraft zur Verfügung steht."],"praxis":["Für die Wachpraxis vor allem zum Verständnis wichtig: Der Staat hat Werkzeuge, um nicht nur den Täter, sondern auch die ‚Beute‘ und Geldforderungen zu sichern.","Begrifflich sauber bleiben: ‚dinglich‘ = Vermögen, nicht Person – eine beliebte Prüfungsfalle."]},"visual":null},{"h":"Strafverfolgung (Staatsanwaltschaft)","b":"Aufgabe der Staatsanwaltschaft im Ermittlungsverfahren; Legalitätsprinzip","detail":{"titel":"Die Staatsanwaltschaft","kat":"Strafverfolgung · Staatsanwaltschaft","katCls":"stpo","merksatz":"Die Staatsanwaltschaft ist die ‚Herrin des Ermittlungsverfahrens‘: Sie leitet die Ermittlungen, muss objektiv auch entlastende Umstände prüfen und entscheidet am Ende, ob Anklage erhoben oder das Verfahren eingestellt wird. Das Urteil spricht aber das Gericht.","funktion":["Leitung: Die Staatsanwaltschaft führt das Ermittlungsverfahren; die Polizei ermittelt als ihr ‚verlängerter Arm‘.","Objektivität: Sie muss nicht nur belastende, sondern auch ENTLASTENDE Umstände ermitteln (§ 160 II StPO) – sie sucht die Wahrheit, nicht nur die Verurteilung.","Abschlussentscheidung: Nach den Ermittlungen erhebt sie Anklage (bei hinreichendem Tatverdacht) oder stellt das Verfahren ein."],"schutzziel":"Die Strafverfolgung in eine objektive, rechtsstaatlich gebundene Hand legen – mit klarer Trennung von Ermittlung (Staatsanwaltschaft) und Urteil (Gericht).","kennwerte":[{"l":"Rolle","v":"Herrin des Ermittlungsverfahrens"},{"l":"Pflicht","v":"objektiv – auch Entlastendes"},{"l":"Entscheidet","v":"Anklage oder Einstellung"}],"begriffe":["Ermittlungsverfahren = der erste Abschnitt des Strafverfahrens, in dem der Sachverhalt aufgeklärt wird.","Anklage = der Antrag der Staatsanwaltschaft, das Hauptverfahren gegen den Beschuldigten zu eröffnen."],"abgrenzung":["Staatsanwaltschaft (ermittelt und klagt an) ist nicht das Gericht (entscheidet und urteilt) – Gewaltenteilung im Strafprozess.","Private Sicherheitskräfte haben keine staatsanwaltlichen Befugnisse: Sie liefern Hinweise und Anzeigen, ermitteln aber nicht hoheitlich."],"praxis":["Für die Praxis: Deine Anzeige und dein Vorfallbericht landen bei der Staatsanwaltschaft – sie entscheidet über das weitere Vorgehen.","Gute, sachliche Dokumentation hilft der objektiven Aufklärung – sie ist deine wichtigste Schnittstelle zur Strafverfolgung."]},"visual":null}],"quiz":[{"q":"Wann dürfen Wachpersonen gemäß § 127 Abs. 1 StPO eine Person vorläufig festnehmen?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wenn sie Hinweise auf eine bevorstehende Straftat erhalten","c":false},{"t":"Wenn sie einen Täter bei der Verübung einer Ordnungswidrigkeit auf frischer Tat betreffen","c":false},{"t":"Wenn sie einen unbekannten Straftäter auf frischer Tat verfolgen und dessen Identität nicht sofort feststellbar ist","c":true},{"t":"Wenn sie die Vollendung einer Straftat unterbinden wollen","c":false}]},{"q":"Wer wird im Sinne der vorläufigen Festnahme gemäß § 127 Abs. 1 StPO auf frischer Tat betroffen?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wer bei der Begehung eines versuchten Hausfriedensbruchs gestellt wird","c":false},{"t":"Wer bei der Begehung einer verfolgbaren Straftat gestellt wird","c":true},{"t":"Wer bei der Begehung einer Ordnungswidrigkeit gestellt wird","c":false},{"t":"Wer nach Begehung der Straftat am Tatort oder in dessen unmittelbarer Nähe gestellt wird","c":true}]},{"q":"Welche Aussagen zum Diebstahl (§ 242 StGB) und zur Unterschlagung (§ 246 StGB) sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Bei beiden Delikten handelt es sich um Offizialdelikte","c":true},{"t":"Bei beiden Delikten handelt es sich um Vergehen","c":true},{"t":"Bei beiden Delikten ist der Versuch straflos","c":false},{"t":"Bei beiden Delikten handelt es sich um Antragsdelikte","c":false}]},{"q":"Welche Aussagen zum Strafantrag sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Bei einem Antragsdelikt darf die Tat grundsätzlich nur verfolgt werden, wenn der Berechtigte einen Strafantrag stellt","c":true},{"t":"Antragsberechtigt ist in der Regel der Verletzte der Tat","c":true},{"t":"Der Strafantrag muss innerhalb von drei Monaten ab Kenntnis von Tat und Täter gestellt werden","c":true},{"t":"Ein einmal gestellter Strafantrag kann niemals zurückgenommen werden","c":false}]},{"q":"Was besagt das Legalitätsprinzip im Strafverfahren?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Staatsanwaltschaft und Polizei sind bei einem Anfangsverdacht wegen einer Straftat grundsätzlich zur Ermittlung verpflichtet","c":true},{"t":"Es soll eine gleichmäßige Strafverfolgung sicherstellen und Willkür verhindern","c":true},{"t":"Es gilt nur für Verbrechen, nicht für Vergehen","c":false},{"t":"Es liegt im freien Ermessen der Polizei, ob sie eine bekannt gewordene Straftat verfolgt","c":false}]},{"q":"Kaufhausdetektiv K soll wegen eines Diebstahls als Zeuge aussagen. Was muss K als Zeuge gemäß StPO beachten?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"K muss zur Vernehmung nur erscheinen, wenn er schriftlich und mit einer Frist von zwei Wochen geladen wird","c":false},{"t":"K ist verpflichtet, wahrheitsgemäß auszusagen, sofern die StPO keine Ausnahme zulässt (z. B. Auskunftsverweigerungsrecht)","c":true},{"t":"K ist verpflichtet, zum festgesetzten Termin vor dem Richter zu erscheinen","c":true},{"t":"K darf zur Auffrischung seiner Erinnerung keine schriftlichen Unterlagen verwenden","c":false}]},{"q":"Welche Aussagen zum dinglichen Arrest treffen zu?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Der dingliche Arrest dient der Sicherung von Geldforderungen (z. B. Einziehung von Wertersatz oder Geldstrafen)","c":true},{"t":"Mit ihm kann das Vermögen eines Beschuldigten vorläufig sichergestellt (‚eingefroren‘) werden","c":true},{"t":"Der dingliche Arrest ist eine Maßnahme gegen die Person, mit der diese in Haft genommen wird","c":false},{"t":"Über die Anordnung entscheidet grundsätzlich das Gericht, bei Gefahr im Verzug die Staatsanwaltschaft","c":true}]},{"q":"Welche Aussagen zur Staatsanwaltschaft treffen zu?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Staatsanwaltschaft leitet das Ermittlungsverfahren (‚Herrin des Vorverfahrens‘)","c":true},{"t":"Sie ist zur Objektivität verpflichtet und muss auch entlastende Umstände ermitteln","c":true},{"t":"Sie entscheidet, ob nach den Ermittlungen Anklage erhoben oder das Verfahren eingestellt wird","c":true},{"t":"Die Staatsanwaltschaft spricht am Ende des Prozesses das Urteil","c":false}]},{"q":"Erkläre die Vorläufige Festnahme gem. §127 (1) StPO, 5 Merkmale:","a":"Grundvoraussetzung = Vorliegen einer frischen Tat (Straftat) und Betroffen oder Verfolgt und Identität nicht sofort feststellbar oder Fluchtverdacht (keine Anwendung bei Kindern möglich !)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Zu welchem Grund/Ziel macht man eine Vorläufige Festnahme?","a":"Zur Einleitung eines Strafverfahrens; (daher StPO)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Darf man bei Vorläufigen Festnahme Gewalt anwenden?","a":"Ja, Einsatz von leichter körperlicher Gewalt.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Voraussetzungen benötigt vorläufige Festnahme im 127 StPO ?","a":"Auf frischer Tat betroffen oder verfolgt(Tat = Straftat) Identität ist nicht sofort feststellbar\toder es besteht Fluchtverdacht = diese Voraussetzungen berechtigen zur vorläufigen Festnahme des Täters","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Nenne Deliktarten.","a":"- Offizialdelikte, - Antragsdelikte - Begehungsdelikte, - Unterlassungsdelikte - Vergehen, Verbrechen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist ein Offizialdelikt, Was ist ein Antragsdelikt?","a":"Grundsätzlich sind alle Straftaten Offizialdelikte. Alle Verbrechen sind Offizial- delikte, aber auch Antragsdelikte wenn ein öffentliches Interesse besteht; (sogenannte „relative“ Antragsdelikte) Antragsdelikte sind Straftaten die einen Strafantrag erfordern; sogenannte Bagatellstraftaten (Diebstahl unter 50 €, einfache Körperverletzung, Sachbeschädigung) muss vom Betroffenen innerhalb von 3 Monaten erfolgen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre den Begriff \"relatives Antragsdelikt\"","a":"Im Gegensatz zum reinen (absoluten) Antragsdelikt gibt es das „relative“ Antragsdelikt. Bei einem öffentlichen Interesse wird das eigentliche Antragsdelikt zum Offizial- delikt; dies bedeutet eigentlich wäre ein Strafantrag erforderlich, dieser entfällt aber bei einem öffentlichen Interesse.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wer stellt den Antrag auf Strafverfolgung bei einem Antragsdelikt?","a":"Der Betroffene muss einen Strafantrag stellen, innerhalb von 3 Monaten nach bekannt werden der Straftat. Der Strafantrag ist bei Antragsdelikten eine Verfahrensvoraussetzung!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §123 StGB Hausfriedensbruch, Tatbestandsmerkmale (genau)","a":"Widerrechtliches eindringen in Wohnung, Geschäftsraum, befriedetes Besitztum..., abgeschlossene Räume die zum öffentlichen Verkehr bestimmt sind (Busse, Bahn), eindringt oder darin Aufhält und sich nach Aufforderung nicht entfernt, wird bestraft; Absolutes Antragsdelikt","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §223 StGB Körperverletzung, Tatbestandmerkmale","a":"(genaue Bezeichnung) Wer einer anderen Person körperlich misshandelt oder an der Gesundheit schädigt, relatives Antragsdelikt, Vergehen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie wird eine einfache Körperverletzung zur gefährlichen","a":"Körperverletzung §224 StGB, nenne alle Tatbestandsmerkmale. Sie qualifiziert sich durch beibringen von Gift, Waffe oder gefährliches Werkzeug, gemeinschaftlich, hinterlistiger Überfall oder einer das Leben gefährdende Behandlung; Offizialdelikt, Vergehen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere §226 StGB Schwere Körperverletzung, Tatbestandsmerkmale.","a":"Sie qualifiziert sich durch Verlust des Gehörs, Motorik, Sprachvermögen, Sehvermögen, wichtiges Körperglied, Siechtum; Offizialdelikt, Verbrechen ! Eine weitere ist die Körperverletzung mit Todesfolge § 227 StGB","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist der Unterschied zwischen Antragsdelikt und Offizialdelikt ?","a":"Antragsdelikt> absolutes Antragsdelikt\t- wird ausschließlich auf Antrag des Geschädigten verfolgt> relatives Antragsdelikt\t- wird grundsätzlich auf Antrag verfolgt, außer bei öffentlichem Interesse\thier kann die Staatsanwaltschaft auch von Amts wegen tätig werden Offizialdelikt- sind Straftaten, welch stets von Amtswegen, also durch die Staatsanwaltschaft automatisch verfolgt werden","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was können Sie mir zur Beleidigung sagen ?","a":"Der Beleidigte muss sich auch beleidigt fühlen Ist ein absolutes Antragsdelikt allgemeine Beleidigungen\t- gesprochenes Wort\t- geschriebenes Wort\t- schlüssiges Verhalten (z.B.: Stinkefinger) tätliche Beleidigung\t- abwertendes Schubsen\t- anspucken\t- anurinieren Die Beleidigung muss ein herabwürdigendes Verhalten / Missachtung zum Ziel haben","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Aufbau/Element der Straftat (3 Säulen)","a":"Tatbestand, Rechtswidrigkeit, Schuld + Verfahrensvoraussetzungen (z.B. Strafantrag)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist der Unterschied zwischen einem Strafantrag und einer Strafanzeige?","a":"Strafanzeige- ein unbeteiligter Dritter teilt dem Staat mit, dass er eine Straftat beobachtet hat\t„er zeigt an, dass es eine Straftat gab“ = Strafanzeige Strafantrag- der Geschädigte (Opfer) stellt beim Staat den Antrag auf Strafverfolgung\t= Strafantrag","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was sind Rechte und Pflichte eines Zeugen gem. der StPO.","a":"Der Zeuge muss vor Gericht erscheinen, zur Sache aussagen, er kann aber die Aussage verweigern wen er sich selbst belastet oder ein Familienangehörigen. 76 Zeugnis- bzw. Auskunftsverweigerungsrecht, was besagt dieses? Wen er sich selbst oder ein Familienangehörigen dadurch belastet, hat das Recht diese zu verweigern. Fallbeispiel: a) Jemand bricht mit einem Stemmeisen den Kofferraum eines PKW auf um zu stehlen, b) Jemand bricht mit einem Stemmeisen in eine Wohnung ein um zu stehlen ? Wo ist der Unterschied ? Der Unterschied ist zum einen der Tatbestand und zum anderen das Strafmaß Bei a) liegt ein Besonders schwerer Fall des Diebstahls gem. § 243 StGB Nr. 2 vor (eine Sache stiehlt, die durch ein verschlossenes Behältnis oder eine andere Schutzvorrichtung gegen Wegnahme besonders gesichert ist). Bei b) liegt ein Wohnungseinbruchsdiebstahl gemäß § 244 StGB vor (einen Diebstahl begeht, bei dem er zur Ausführung der Tat in eine Wohnung einbricht, einsteigt, mit einem falschen Schlüssel oder einem anderen nicht zur ordnungsmäßigen Öffnung bestimmten Werkzeug eindringt oder sich in der Wohnung verborgen hält)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Definiere den Begriff \"Dinglicher Arrest\"","a":"Im Falle der Wegnahme von Sachen ist der dingliche Arrest zu beantragen; dies macht die Polizei.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist die Aufgabe der Staatsanwaltschaft im Ermittlungsverfahren?","a":"Die Staatsanwaltschaft lenkt das Ermittlungsverfahren Der RICHTER leitet das Ermittlungsverfahren","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[{"scenario":"Ein Wachmann beobachtet, wie ein Mann im Kaufhaus eine teure Uhr einsteckt und Richtung Ausgang geht. Er stellt ihn noch im Laden. Der Mann zeigt sofort bereitwillig seinen gültigen Personalausweis, bleibt ruhig und kooperativ.","frage":"Darf der Wachmann den Mann nach §127 Abs. 1 StPO vorläufig festnehmen?","loesung":"Nein. §127 verlangt zweierlei: eine verfolgbare Straftat auf frischer Tat UND einen Festnahmegrund (Fluchtverdacht oder fehlende sofortige Identitätsfeststellung). Der Diebstahlsverdacht liegt zwar nahe (Straftat, auf frischer Tat). Aber der Mann identifiziert sich sofort mit gültigem Ausweis und zeigt keinen Fluchtverdacht – damit fehlt der Festnahmegrund. Ein Festhalten wäre hier rechtswidrig und könnte selbst eine Freiheitsberaubung (§239 StGB) sein. Richtig: Personalien aufnehmen, Strafanzeige fertigen bzw. Polizei verständigen – aber kein Festhalten. Merksatz: Eine Straftat allein genügt nicht; ohne Festnahmegrund keine Festnahme."}]},{"n":6,"title":"Straftatbestände – Besonderer Teil","subtitle":"31 Konzepte · 47 Prüfungsfragen","cards":[{"h":"Vorsätzliche Körperverletzung","b":"Zwei Wege zum Ziel: am Körper misshandeln ODER die Gesundheit schädigen.","detail":{"n":"§223","titel":"Vorsätzliche Körperverletzung","art":"Vergehen","merksatz":"Zwei Wege zum Ziel: am Körper misshandeln ODER die Gesundheit schädigen.","otb":["Körperliche Misshandlung — jede üble, unangemessene Behandlung, die das körperliche Wohlbefinden mehr als nur unerheblich beeinträchtigt (Schläge, Treten, Zahn ausschlagen, Bart abschneiden).","ODER Gesundheitsschädigung — Hervorrufen oder Steigern eines krankhaften Zustands (Vergiften, absichtliches Anhusten mit Krankheitserreger, einen Schock herbeiführen)."],"stb":"Vorsatz — der Täter weiß und will die Misshandlung bzw. Schädigung. Eventualvorsatz genügt (er nimmt die Folge billigend in Kauf).","folge":{"strafe":"Freiheitsstrafe bis 5 Jahre oder Geldstrafe","versuch":"strafbar","delikt":"Relatives Antragsdelikt (§230) — Strafantrag nötig, außer besonderes öffentliches Interesse"},"begriffe":["Einwilligung: Eine KV mit Einwilligung des Opfers bleibt straffrei, solange sie nicht gegen die guten Sitten verstößt (§228) — z. B. erlaubter Körperkontakt im Kampfsport."],"abgrenzung":["Zur tätlichen Beleidigung (§185): Ein Tritt in den Hintern „aus Verachtung“ ist Beleidigung; verursacht er Schmerz/Verletzung, kommt §223 hinzu.","Zu §224/§226: §223 ist der Grundtatbestand. Kommt eine besondere Begehungsweise hinzu → §224; entsteht eine schwere Dauerfolge → §226."],"praxis":["Ein abgewiesener Diskothekenbesucher prügelt auf den Türsteher ein und schlägt ihm einen Backenzahn aus."]},"visual":null},{"h":"Gefährliche Körperverletzung","b":"Es geht NICHT um die Schwere der Verletzung, sondern um die gefährliche ART der Begehung.","detail":{"n":"§224","titel":"Gefährliche Körperverletzung","art":"Vergehen (erhöht)","merksatz":"Es geht NICHT um die Schwere der Verletzung, sondern um die gefährliche ART der Begehung.","otb":["Eine Körperverletzung (§223), begangen durch eine von fünf besonders gefährlichen Begehungsweisen:","1. mittels Gift oder anderer gesundheitsschädlicher Stoffe","2. mittels einer Waffe oder eines anderen gefährlichen Werkzeugs","3. mittels eines hinterlistigen Überfalls","4. gemeinschaftlich (mit mindestens einem weiteren Beteiligten)","5. mittels einer das Leben gefährdenden Behandlung"],"stb":"Vorsatz bezüglich der Körperverletzung UND der gefährlichen Begehungsweise.","folge":{"strafe":"Freiheitsstrafe 6 Monate bis 10 Jahre","versuch":"strafbar","delikt":"Offizialdelikt — wird von Amts wegen verfolgt"},"begriffe":["Gefährliches Werkzeug: jeder Gegenstand, der nach Art seiner Verwendung im Einzelfall geeignet ist, erhebliche Verletzungen herbeizuführen (auch ein beschuhter Fuß, eine zerbrochene Flasche, ein Schlüsselbund als Schlagwerkzeug).","Hinterlistig: planmäßiges Verdecken der wahren Absicht, um dem Opfer die Abwehr zu erschweren (Auflauern, Angriff von hinten)."],"abgrenzung":["„Gefährlich“ (§224) = besondere ART der Begehung. „Schwer“ (§226) = besonders schwere FOLGE. Beides kann zusammentreffen.","Bloße einfache KV mit der Faust ohne Hilfsmittel bleibt §223 — eine Faust ist keine Waffe/kein Werkzeug."],"praxis":["Ein abgewiesener Diskothekenbesucher attackiert den Türsteher mit einem Messer."]},"visual":null},{"h":"Schwere Körperverletzung","b":"Hier zählt die dauerhafte, schwere FOLGE für das Opfer — nicht wie zugeschlagen wurde.","detail":{"n":"§226","titel":"Schwere Körperverletzung","art":"Verbrechen","merksatz":"Hier zählt die dauerhafte, schwere FOLGE für das Opfer — nicht wie zugeschlagen wurde.","otb":["Eine Körperverletzung, die beim Opfer eine schwere dauerhafte Folge auslöst:","1. Verlust des Sehvermögens, Gehörs, Sprechvermögens oder der Fortpflanzungsfähigkeit","2. Verlust eines wichtigen Körpergliedes oder dauerhafte Gebrauchsunfähigkeit","3. erhebliche dauerhafte Entstellung","4. Siechtum, Lähmung, geistige Krankheit oder Behinderung"],"stb":"Vorsatz zur Körperverletzung; die schwere Folge muss mindestens fahrlässig verursacht sein (erfolgsqualifiziertes Delikt, §18).","folge":{"strafe":"Freiheitsstrafe ab 1 Jahr — Verbrechen","versuch":"strafbar","delikt":"Offizialdelikt"},"abgrenzung":["Verbrechen (§12): Mindeststrafe 1 Jahr → Versuch immer strafbar, grundsätzlich U-Haft möglich, Verhandlung am Landgericht.","Tritt die schwere Folge nicht ein, bleibt es bei §223/§224 (ggf. Versuch der schweren KV, wenn vom Vorsatz umfasst)."],"praxis":["Der mit dem Messer attackierte Türsteher wird durch die Verletzung dauerhaft querschnittsgelähmt und sitzt im Rollstuhl."]},"visual":null},{"h":"Fahrlässige Körperverletzung","b":"Gleicher Erfolg wie §223 — aber ohne Wollen, durch Verletzung der Sorgfaltspflicht.","detail":{"n":"§229","titel":"Fahrlässige Körperverletzung","art":"Vergehen","merksatz":"Gleicher Erfolg wie §223 — aber ohne Wollen, durch Verletzung der Sorgfaltspflicht.","otb":["Körperliche Misshandlung oder Gesundheitsschädigung wie bei §223 — jedoch ohne Vorsatz."],"stb":"Fahrlässigkeit — der Täter verwirklicht den Tatbestand, weil er die im Verkehr erforderliche Sorgfalt außer Acht lässt.","folge":{"strafe":"Freiheitsstrafe bis 3 Jahre oder Geldstrafe","versuch":"nicht möglich (Fahrlässigkeit kennt keinen Versuch)","delikt":"Relatives Antragsdelikt"},"abgrenzung":["Kein Versuch denkbar: Wer nichts will, kann nichts „versuchen“.","Gegenüber §223: Es fehlt das Wissen+Wollen. Entscheidend ist die Sorgfaltspflichtverletzung."],"praxis":["Ein Revierfahrer verpasst den Schulterblick und stößt beim Linksabbiegen mit einem Radfahrer zusammen, der sich verletzt."]},"visual":null},{"h":"Freiheitsberaubung","b":"Die Fortbewegungsfreiheit verletzen — das Recht, jeden Ort ungehindert verlassen zu können.","detail":{"n":"§239","titel":"Freiheitsberaubung","art":"Vergehen","merksatz":"Die Fortbewegungsfreiheit verletzen — das Recht, jeden Ort ungehindert verlassen zu können.","otb":["Einen Menschen einsperren ODER auf andere Weise der Freiheit berauben (Fixieren, Festbinden, den Weg dauerhaft versperren, Wegschließen des Raumschlüssels)."],"stb":"Vorsatz.","folge":{"strafe":"Freiheitsstrafe bis 5 Jahre oder Geldstrafe","versuch":"strafbar","delikt":"Offizialdelikt"},"begriffe":["Fortbewegungswille: Das Opfer muss einen Willen zur Fortbewegung bilden können. Babys, Schlafende und Komapatienten scheiden aus, solange sie diesen Willen nicht bilden können."],"abgrenzung":["WICHTIG für SMA: Die vorläufige Festnahme (§127 StPO) rechtfertigt ein KURZZEITIGES Festhalten bis zum Eintreffen der Polizei. Wer darüber hinausgeht — anketten, lange einsperren, eigenmächtig „verhören“ — begeht Freiheitsberaubung.","Das Festhalten muss verhältnismäßig und auf die Übergabe an die Polizei gerichtet sein."],"praxis":["Ein Kaufhausdetektiv kettet einen Ladendieb an einen Bürotisch, um in Ruhe Mittagspause zu machen, und will sich erst danach wieder mit ihm befassen → klare Freiheitsberaubung, weil das Festhalten nicht mehr der Übergabe an die Polizei dient."]},"visual":null},{"h":"Nötigung","b":"Mit Gewalt oder Drohung jemanden zu einem Tun, Dulden oder Unterlassen zwingen.","detail":{"n":"§240","titel":"Nötigung","art":"Vergehen","merksatz":"Mit Gewalt oder Drohung jemanden zu einem Tun, Dulden oder Unterlassen zwingen.","otb":["Einen Menschen rechtswidrig mit Gewalt oder durch Drohung mit einem empfindlichen Übel zu einer Handlung, Duldung oder Unterlassung zwingen."],"stb":"Vorsatz.","folge":{"strafe":"Freiheitsstrafe bis 3 Jahre oder Geldstrafe","versuch":"strafbar","delikt":"Offizialdelikt"},"begriffe":["Gewalt: jede Zwangsanwendung gegen das Opfer, die geleisteten oder erwarteten Widerstand brechen soll (z. B. Festhalten, Knebeln, den Weg mit dem Körper versperren).","Empfindliches Übel: eine spürbar nachteilige Folge, mit der gedroht wird (z. B. Verlust des Arbeitsplatzes, Anzeige, Bloßstellung).","Verwerflichkeit: Die Nötigung ist nur rechtswidrig, wenn Mittel-Zweck-Verhältnis verwerflich ist (§240 Abs. 2)."],"abgrenzung":["Zur Erpressung (§253): Bei der Erpressung kommt ein Vermögensschaden + Bereicherungsabsicht hinzu. Nötigung ohne Vermögensbezug bleibt §240.","Zur Drohung/Bedrohung (§241): §241 droht mit einem Verbrechen, ohne ein Verhalten erzwingen zu wollen."],"praxis":["Der Einsatzleiter droht dem SMA mit Entlassung, falls er sich weigert, in einer Krankheitswelle zusätzliche Schichten zu übernehmen."]},"visual":null},{"h":"Diebstahl","b":"Wegnahme = fremden Gewahrsam brechen und neuen begründen — mit Zueignungsabsicht.","detail":{"n":"§242","titel":"Diebstahl","art":"Vergehen","merksatz":"Wegnahme = fremden Gewahrsam brechen und neuen begründen — mit Zueignungsabsicht.","otb":["Eine fremde, bewegliche Sache wegnehmen.","Wegnahme = Bruch fremden Gewahrsams und Begründung neuen (eigenen) Gewahrsams gegen den Willen des bisherigen Inhabers."],"stb":"Vorsatz UND rechtswidrige Zueignungsabsicht (für sich oder einen Dritten). Die Sache muss sich vorher im Gewahrsam eines anderen befunden haben.","folge":{"strafe":"Freiheitsstrafe bis 5 Jahre oder Geldstrafe","versuch":"strafbar","delikt":"Offizialdelikt (bei geringwertiger Sache → §248a, relatives Antragsdelikt)"},"begriffe":["Vollendung: Bei kleinen Gegenständen ist der Diebstahl bereits mit dem Einstecken vollendet (eine „Gewahrsamsenklave“ am Körper entsteht, z. B. Ware in der Jacke). Bei großen/sperrigen Sachen erst, wenn der Täter die Kassenzone verlassen hat.","Gewahrsam: die tatsächliche Sachherrschaft, getragen von einem Herrschaftswillen."],"abgrenzung":["Zur Unterschlagung (§246): Beim Diebstahl wird Gewahrsam GEBROCHEN. Bei der Unterschlagung hat der Täter die Sache bereits — er bricht keinen Gewahrsam.","Zum Betrug (§263): Beim Diebstahl nimmt der Täter weg; beim Betrug gibt das getäuschte Opfer die Sache freiwillig (irrtumsbedingt) heraus."],"praxis":["Ein Kunde entwendet wertvolle Kosmetikartikel, steckt sie in den Rucksack und verlässt das Geschäft ohne zu bezahlen."]},"visual":null},{"h":"Besonders schwerer Fall des Diebstahls","b":"Kein eigener Tatbestand — sondern Diebstahl mit hoher krimineller Energie. Härtere Strafe.","detail":{"n":"§243","titel":"Besonders schwerer Fall des Diebstahls","art":"Strafzumessungsregel","merksatz":"Kein eigener Tatbestand — sondern Diebstahl mit hoher krimineller Energie. Härtere Strafe.","otb":["Diebstahl (§242) in einer der gesetzlichen Regelbeispiel-Konstellationen:","1. Einbruch-, Einsteige-, Nachschlüssel- oder Verweildiebstahl","2. Wegnahme besonders gesicherter Sachen (Vitrine, Tresor, Fahrradschloss, abgeschlossenes Auto)","3. gewerbsmäßiger Diebstahl (dauerhafte Einnahmequelle)","4. aus einem der Religionsausübung dienenden Gebäude (und die Sache dient der Religion)","5. aus einer öffentlich zugänglichen Sammlung/Ausstellung","6. unter Ausnutzung von Hilflosigkeit oder allgemeiner Gefahr (Plünderung)","7. erlaubnispflichtige Waffen, Munition oder Sprengstoff"],"stb":"wie §242 — Vorsatz und Zueignungsabsicht.","folge":{"strafe":"Freiheitsstrafe 3 Monate bis 10 Jahre","versuch":"strafbar","delikt":"Offizialdelikt. Geringwertigkeitsgrenze (50 €) gilt — AUSSER bei Nr. 7 (Waffen)"},"abgrenzung":["§243 ist eine Strafzumessungsregel (Regelbeispiele), kein selbstständiger Tatbestand wie §244.","Liegt das Diebesgut unter 50 €, entfällt der besonders schwere Fall in der Regel — außer bei gestohlenen Waffen/Munition/Sprengstoff."],"praxis":["Ein Täter hebelt nachts die Tür eines Lagers auf und entwendet Werkzeug → Einbruchdiebstahl."]},"visual":null},{"h":"Diebstahl mit Waffen · Bandendiebstahl · Wohnungseinbruch","b":"Eigener Tatbestand — Waffe dabei, als Bande, oder Einbruch in die Privatwohnung.","detail":{"n":"§244","titel":"Diebstahl mit Waffen · Bandendiebstahl · Wohnungseinbruch","art":"Verbrechen (Abs. 4)","merksatz":"Eigener Tatbestand — Waffe dabei, als Bande, oder Einbruch in die Privatwohnung.","otb":["1. Der Täter führt beim Diebstahl eine Waffe oder ein anderes gefährliches Werkzeug bei sich.","2. Er führt ein Mittel/Werkzeug bei sich, um den Widerstand einer Person zu überwinden.","3. Bandendiebstahl (Zusammenschluss von mind. 3 Personen).","4. Wohnungseinbruchdiebstahl in eine dauerhaft genutzte Privatwohnung."],"stb":"Vorsatz bezüglich des Diebstahls; beim Beisichführen genügt das Bewusstsein, die Waffe dabei zu haben. Bei Nr. 2 zusätzlich eine Verwendungsabsicht.","folge":{"strafe":"Freiheitsstrafe 6 Monate bis 10 Jahre; Wohnungseinbruch in Privatwohnung (Abs. 4): 1–10 Jahre — Verbrechen","versuch":"strafbar","delikt":"Offizialdelikt"},"abgrenzung":["Schon das BEISICHFÜHREN der Waffe genügt — sie muss nicht eingesetzt werden. Wird sie zur Wegnahme eingesetzt (Drohung), liegt Raub (§249) vor.","Anders als §243 ist §244 ein eigener Straftatbestand."],"praxis":["Ein festgenommener Ladendieb packt im Detektivbüro seinen Tascheninhalt aus — zum Vorschein kommt ein Einhandmesser. Schon das Mitführen während des Diebstahls erfüllt §244."]},"visual":null},{"h":"Diebstahl/Unterschlagung geringwertiger Sachen","b":"Wert unter ca. 50 € — dann nur auf Antrag (oder bei öffentlichem Interesse).","detail":{"n":"§248a","titel":"Diebstahl/Unterschlagung geringwertiger Sachen","art":"Antragsregel","merksatz":"Wert unter ca. 50 € — dann nur auf Antrag (oder bei öffentlichem Interesse).","otb":["Diebstahl oder Unterschlagung, bei der die Sache geringwertig ist (Richtwert: unter 50 €)."],"stb":"wie §242 / §246.","folge":{"strafe":"wie Grunddelikt","versuch":"strafbar","delikt":"Relatives Antragsdelikt — Verfolgung nur mit Strafantrag oder bei besonderem öffentlichen Interesse"},"abgrenzung":["Greift NICHT beim besonders schweren Fall §243 Nr. 7 (Waffen) und nicht bei §244."],"praxis":["Eine Tafel Schokolade aus dem Supermarkt oder Büroartikel aus der Firma mitgehen lassen."]},"visual":null},{"h":"Unterschlagung","b":"Zueignung OHNE Gewahrsamsbruch — der Täter HAT die Sache schon.","detail":{"n":"§246","titel":"Unterschlagung","art":"Vergehen","merksatz":"Zueignung OHNE Gewahrsamsbruch — der Täter HAT die Sache schon.","otb":["Eine fremde, bewegliche Sache, die der Täter bereits in Gewahrsam/Besitz hat, sich oder einem Dritten rechtswidrig zueignen."],"stb":"Vorsatz (eine besondere Zueignungsabsicht wie beim Diebstahl ist nicht nötig; die Zueignung selbst ist Tathandlung).","folge":{"strafe":"Freiheitsstrafe bis 3 Jahre oder Geldstrafe","versuch":"strafbar","delikt":"Offizialdelikt (subsidiär — tritt hinter schwerere Taten zurück); geringwertig → §248a"},"begriffe":["Zueignung: Der Täter nimmt die Sache erkennbar in sein eigenes Vermögen auf (verkauft sie, behält sie als seine)."],"abgrenzung":["Schlüsselfrage Diebstahl ↔ Unterschlagung: Musste der Täter fremden Gewahrsam BRECHEN? Ja → Diebstahl. Hatte er die Sache schon → Unterschlagung.","Fundunterschlagung: Wer eine gefundene Sache behält statt sie abzugeben, begeht Unterschlagung."],"praxis":["Ein Wachmann meldet seiner Firma, seine Arbeitsschuhe seien gestohlen worden — tatsächlich hat er sie selbst über Kleinanzeigen verkauft."]},"visual":null},{"h":"Raub","b":"Erst hauen, dann klauen: Gewalt/Drohung ZUERST, um dann wegzunehmen.","detail":{"n":"§249","titel":"Raub","art":"Verbrechen","merksatz":"Erst hauen, dann klauen: Gewalt/Drohung ZUERST, um dann wegzunehmen.","otb":["Der Täter wendet Gewalt gegen eine Person an oder droht mit gegenwärtiger Gefahr für Leib oder Leben — UND nimmt im Anschluss eine fremde bewegliche Sache weg.","Zwischen Nötigungsmittel und Wegnahme besteht ein finaler Zusammenhang (die Gewalt dient der Wegnahme)."],"stb":"Vorsatz und Zueignungsabsicht.","folge":{"strafe":"Freiheitsstrafe ab 1 Jahr — Verbrechen","versuch":"strafbar","delikt":"Offizialdelikt"},"abgrenzung":["Zum räuberischen Diebstahl (§252): Reihenfolge\\! Beim Raub kommt die Gewalt VOR der Wegnahme, beim räuberischen Diebstahl DANACH.","Zur räuberischen Erpressung (§255): Beim Raub nimmt der Täter selbst weg; bei §255 gibt das genötigte Opfer heraus."],"praxis":["Ein Täter betritt eine Tankstelle, bedroht den Kassierer mit einer Schusswaffe; dieser öffnet die Kasse, der Täter nimmt das Bargeld."]},"visual":null},{"h":"Räuberischer Diebstahl","b":"Erst klauen, dann hauen: nach dem Diebstahl Gewalt, um die Beute zu behalten.","detail":{"n":"§252","titel":"Räuberischer Diebstahl","art":"Verbrechen","merksatz":"Erst klauen, dann hauen: nach dem Diebstahl Gewalt, um die Beute zu behalten.","otb":["Der Täter wird bei einem bereits begangenen Diebstahl auf frischer Tat betroffen und wendet dann Gewalt an oder droht mit gegenwärtiger Gefahr für Leib/Leben."],"stb":"Vorsatz UND die Absicht, sich im Besitz des Diebesguts zu erhalten (Beutesicherungsabsicht).","folge":{"strafe":"wird wie Raub bestraft — Freiheitsstrafe ab 1 Jahr, Verbrechen","versuch":"strafbar","delikt":"Offizialdelikt"},"abgrenzung":["Spiegelbild zum Raub: hier Gewalt NACH der Wegnahme, um die Beute zu sichern."],"praxis":["Ein Ladendieb wird hinter der Kassenzone vom Detektiv angesprochen, zieht ein Messer, bedroht ihn und flüchtet mit der Beute."]},"visual":null},{"h":"Erpressung / Räuberische Erpressung","b":"Nötigung + Vermögensschaden + Bereicherungsabsicht. Mit Gewalt gegen Person → räuberisch.","detail":{"n":"§253 / §255","titel":"Erpressung / Räuberische Erpressung","art":"Vergehen / Verbrechen","merksatz":"Nötigung + Vermögensschaden + Bereicherungsabsicht. Mit Gewalt gegen Person → räuberisch.","otb":["§253: Den Geschädigten mit Gewalt oder Drohung mit empfindlichem Übel zu einer Handlung/Duldung/Unterlassung nötigen, die sein Vermögen schädigt.","§255: Geschieht die Erpressung mit Gewalt gegen eine Person oder Drohung mit gegenwärtiger Gefahr für Leib/Leben → räuberische Erpressung."],"stb":"Vorsatz und die Absicht, sich oder einen Dritten am Vermögen des Opfers zu bereichern.","folge":{"strafe":"§253: bis 5 Jahre oder Geldstrafe; §255: wie Raub, ab 1 Jahr — Verbrechen","versuch":"strafbar","delikt":"Offizialdelikt"},"abgrenzung":["Zur Nötigung (§240): Erpressung verlangt zusätzlich Vermögensschaden + Bereicherungsabsicht.","Zum Raub: Die Rechtsprechung grenzt nach dem äußeren Bild ab — nimmt der Täter selbst (Raub) oder gibt das Opfer (Erpressung)."],"praxis":["Ein Ladendetektiv nötigt einen geschnappten Dieb zur Zahlung von 500 €, andernfalls werde er ihn anzeigen — strafbare Erpressung durch den SMA selbst\\!"]},"visual":null},{"h":"Begünstigung","b":"Nach der Tat helfen, die BEUTE/Vorteile der Vortat zu sichern.","detail":{"n":"§257","titel":"Begünstigung","art":"Vergehen","merksatz":"Nach der Tat helfen, die BEUTE/Vorteile der Vortat zu sichern.","otb":["Einem anderen, der eine rechtswidrige Vortat begangen hat, Hilfe leisten, um ihm die Vorteile der Tat zu sichern."],"stb":"Vorsatz und die Absicht, dem Vortäter die Vorteile der Tat zu sichern.","folge":{"strafe":"bis 5 Jahre oder Geldstrafe — aber nicht schwerer als die Vortat","versuch":"strafbar","delikt":"richtet sich nach der Einordnung der Vortat"},"abgrenzung":["Zur Strafvereitelung (§258): Begünstigung sichert den VORTEIL der Tat; Strafvereitelung verhindert die BESTRAFUNG des Täters.","Zur Hehlerei (§259): Hehlerei betrifft das Verschaffen/Absetzen der Sache zum eigenen Vorteil; Begünstigung hilft dem Vortäter, seinen Vorteil zu behalten."],"praxis":["Ein SMA hilft einem Kumpel, ein gestohlenes Fahrzeug in der Garage zu zerlegen und die Teile für ihn zu verpacken."]},"visual":null},{"h":"Hehlerei","b":"Mit der Beute eines anderen Geschäfte machen: ankaufen, verschaffen, absetzen.","detail":{"n":"§259","titel":"Hehlerei","art":"Vergehen","merksatz":"Mit der Beute eines anderen Geschäfte machen: ankaufen, verschaffen, absetzen.","otb":["Eine Sache, die ein anderer durch ein Eigentums-/Vermögensdelikt erlangt hat:","ankaufen · sich oder einem Dritten verschaffen · absetzen · beim Absetzen helfen."],"stb":"Vorsatz und Bereicherungsabsicht; der Täter weiß um die deliktische Herkunft der Sache.","folge":{"strafe":"bis 5 Jahre oder Geldstrafe","versuch":"strafbar","delikt":"richtet sich nach der Einordnung des vorangegangenen Delikts"},"abgrenzung":["Voraussetzung ist eine VORTAT eines ANDEREN. Wer selbst gestohlen hat, kann an derselben Sache nicht Hehler sein."],"praxis":["Ein SMA kauft von einem Kumpel geklauten Schmuck für seine Freundin — im Wissen, dass es Diebesgut ist."]},"visual":null},{"h":"Betrug","b":"Vierschritt: Täuschung → Irrtum → Vermögensverfügung → Schaden (+ Bereicherung).","detail":{"n":"§263","titel":"Betrug","art":"Vergehen","merksatz":"Vierschritt: Täuschung → Irrtum → Vermögensverfügung → Schaden (+ Bereicherung).","otb":["1. Täuschungshandlung (Vorspiegeln falscher / Unterdrücken wahrer Tatsachen)","2. dadurch ein Irrtum beim Opfer","3. eine Vermögensverfügung des Irrenden","4. ein Vermögensschaden","5. (im subj. TB) angestrebter, stoffgleicher Vermögensvorteil"],"stb":"Vorsatz und die Absicht, sich oder einen Dritten rechtswidrig zu bereichern.","folge":{"strafe":"bis 5 Jahre oder Geldstrafe","versuch":"strafbar","delikt":"Offizialdelikt"},"abgrenzung":["Zum Diebstahl: Beim Betrug gibt das getäuschte Opfer freiwillig heraus (Vermögensverfügung); beim Diebstahl nimmt der Täter weg.","Trickdiebstahl bleibt Diebstahl — die Täuschung lenkt nur ab, das Opfer verfügt nicht bewusst über die Sache."],"praxis":["Ein Fahrraddieb verkauft sein Diebesgut über Kleinanzeigen an einen gutgläubigen Käufer."]},"visual":null},{"h":"Erschleichen von Leistungen","b":"Leistung nehmen, ohne zu zahlen: Automat, Beförderung, Veranstaltung, Netz.","detail":{"n":"§265a","titel":"Erschleichen von Leistungen","art":"Vergehen","merksatz":"Leistung nehmen, ohne zu zahlen: Automat, Beförderung, Veranstaltung, Netz.","otb":["Sich die Leistung erschleichen von: einem Automaten · einem öffentlichen Telekommunikationsnetz · der Beförderung durch ein Verkehrsmittel · dem Zutritt zu einer Veranstaltung oder Einrichtung."],"stb":"Vorsatz und die Absicht, das Entgelt nicht zu entrichten.","folge":{"strafe":"bis 1 Jahr oder Geldstrafe","versuch":"strafbar","delikt":"Offizialdelikt (subsidiär gegenüber §263)"},"abgrenzung":["Auffangtatbestand: greift, wo kein vollwertiger Betrug vorliegt (z. B. der unbemerkt Schwarzfahrende täuscht keinen Menschen)."],"praxis":["Ein SMA erwischt einen Jugendlichen, der sich durch ein Loch im Zaun Zutritt zu einem Festival verschafft. Auch Schwarzfahren und Pfandbetrug fallen hierunter."]},"visual":null},{"h":"Untreue","b":"Anvertrautes fremdes Vermögen schädigen — Missbrauch der Befugnis/Treuepflicht.","detail":{"n":"§266","titel":"Untreue","art":"Vergehen","merksatz":"Anvertrautes fremdes Vermögen schädigen — Missbrauch der Befugnis/Treuepflicht.","otb":["Eine eingeräumte Verfügungs-/Verpflichtungsbefugnis missbrauchen (Missbrauchstatbestand) ODER die Pflicht zur Wahrung fremder Vermögensinteressen verletzen (Treubruchtatbestand) — mit der Folge eines Vermögensschadens beim Betreuten."],"stb":"Vorsatz.","folge":{"strafe":"bis 5 Jahre oder Geldstrafe","versuch":"STRAFLOS (Besonderheit\\!)","delikt":"Offizialdelikt"},"abgrenzung":["Anders als bei Diebstahl/Betrug ist der Versuch der Untreue nicht strafbar."],"praxis":["Ein SMA verkauft Schmuck, der ihm vom Kunden nur zur Aufbewahrung während dessen Urlaub übergeben wurde."]},"visual":null},{"h":"Urkundenfälschung","b":"Unechte Urkunde herstellen, echte verfälschen oder so eine im Rechtsverkehr gebrauchen.","detail":{"n":"§267","titel":"Urkundenfälschung","art":"Vergehen","merksatz":"Unechte Urkunde herstellen, echte verfälschen oder so eine im Rechtsverkehr gebrauchen.","otb":["Eine unechte Urkunde herstellen ODER eine echte Urkunde verfälschen ODER eine unechte/verfälschte Urkunde zur Täuschung im Rechtsverkehr gebrauchen."],"stb":"Vorsatz und die Absicht, im Rechtsverkehr zu täuschen.","folge":{"strafe":"bis 5 Jahre oder Geldstrafe","versuch":"strafbar","delikt":"Offizialdelikt"},"begriffe":["Urkunde: eine verkörperte Gedankenerklärung, die zum Beweis geeignet und bestimmt ist und einen Aussteller erkennen lässt (z. B. Kassenbon, Fahrzeugschein, Eintrittskarte, KFZ mit Kennzeichen).","Rechtsverkehr: rechtlich erhebliches Handeln, z. B. ein Rechtsgeschäft wie ein Kauf."],"abgrenzung":["Persönliche Notizen sind keine Urkunde (kein Beweisbestimmung im Rechtsverkehr).","Zu §281: Bei §267 ist die Urkunde selbst unecht/verfälscht; bei §281 ist das Ausweispapier ECHT, aber der falsche Inhaber gebraucht es."],"praxis":["Ein SMA erwischt einen Kunden, der im Antiquitätengeschäft das Preisschild an einer Ware austauscht."]},"visual":null},{"h":"Missbrauch von Ausweispapieren","b":"Echtes Ausweispapier — falscher Inhaber. Fremden Perso zur Täuschung nutzen.","detail":{"n":"§281","titel":"Missbrauch von Ausweispapieren","art":"Vergehen","merksatz":"Echtes Ausweispapier — falscher Inhaber. Fremden Perso zur Täuschung nutzen.","otb":["Ein Ausweispapier eines anderen zur Täuschung im Rechtsverkehr gebrauchen ODER das eigene Ausweispapier einem anderen dazu überlassen."],"stb":"Vorsatz und die Absicht, im Rechtsverkehr zu täuschen.","folge":{"strafe":"bis 1 Jahr oder Geldstrafe","versuch":"strafbar","delikt":"Offizialdelikt"},"begriffe":["Ausweispapier: amtliche Lichtbilddokumente wie Personalausweis, Reisepass, Aufenthaltstitel, Führerschein und andere im Verkehr als Ausweis genutzte Urkunden."],"abgrenzung":["Das Papier ist ECHT — nur der Verwender ist nicht der Berechtigte. Wäre das Dokument selbst gefälscht → §267."],"praxis":["Bei der Einlasskontrolle legt ein minderjähriger Gast den echten Perso seines älteren Bruders vor, um Zutritt zu erhalten."]},"visual":null},{"h":"Sachbeschädigung","b":"Fremde Sache beschädigen, zerstören — oder ihr Erscheinungsbild verändern (Graffiti).","detail":{"n":"§303","titel":"Sachbeschädigung","art":"Vergehen","merksatz":"Fremde Sache beschädigen, zerstören — oder ihr Erscheinungsbild verändern (Graffiti).","otb":["Eine fremde Sache rechtswidrig beschädigen, zerstören ODER unbefugt nicht nur unerheblich und nicht nur vorübergehend ihr Erscheinungsbild verändern (§303 Abs. 2 — Graffiti)."],"stb":"Vorsatz.","folge":{"strafe":"bis 2 Jahre oder Geldstrafe","versuch":"strafbar","delikt":"Relatives Antragsdelikt"},"begriffe":["Beschädigen (Kratzer im Lack) · Zerstören (eingeschlagene Scheibe) · Entstellen/Erscheinungsbild verändern (Graffiti)."],"praxis":["Ein SMA im Objektschutz beobachtet auf der Kontrollrunde, wie drei Jugendliche die Wand der Lagerhalle mit Graffiti besprühen."]},"visual":null},{"h":"Brandstiftung","b":"Fremde Objekte in Brand setzen oder durch Brandlegung zerstören.","detail":{"n":"§306","titel":"Brandstiftung","art":"Verbrechen","merksatz":"Fremde Objekte in Brand setzen oder durch Brandlegung zerstören.","otb":["Fremde Objekte in Brand setzen oder durch Brandlegung ganz/teilweise zerstören: Gebäude/Hütten, Betriebsstätten/Maschinen, Warenlager/Vorräte, KFZ/Schienen-/Luft-/Wasserfahrzeuge, Wälder/Heiden/Moore, land-/forstwirtschaftliche Anlagen oder Erzeugnisse."],"stb":"Vorsatz.","folge":{"strafe":"Freiheitsstrafe 1 bis 10 Jahre — Verbrechen","versuch":"strafbar","delikt":"Offizialdelikt"},"begriffe":["In-Brand-setzen: Die Sache brennt selbstständig weiter.","Brandlegung: Die Sache brennt nicht selbst, wird aber durch die Brandhandlung beschädigt/zerstört."],"abgrenzung":["§306a (schwere Brandstiftung) schützt u. a. bewohnte Gebäude — dort drohen deutlich höhere Strafen."],"praxis":["Ein SMA erwischt einen Jugendlichen, der mit Benzinkanister und Feuerzeug eine auf dem Bahngelände abgestellte Lokomotive abfackelt."]},"visual":null},{"h":"Unterlassene Hilfeleistung","b":"Bei Unglück/Gefahr keine zumutbare Hilfe leisten — trifft JEDEN Bürger.","detail":{"n":"§323c","titel":"Unterlassene Hilfeleistung","art":"Vergehen (echtes Unterlassen)","merksatz":"Bei Unglück/Gefahr keine zumutbare Hilfe leisten — trifft JEDEN Bürger.","otb":["Bei einem Unglücksfall, gemeiner Gefahr oder Not keine Hilfe leisten, obwohl dies erforderlich und den Umständen nach zumutbar ist und andere wichtige Pflichten nicht verletzt würden.","Abs. 2: auch das Behindern einer hilfeleistenden Person ist strafbar."],"stb":"Vorsatz.","folge":{"strafe":"bis 1 Jahr oder Geldstrafe","versuch":"straflos","delikt":"Offizialdelikt · echtes Unterlassungsdelikt"},"abgrenzung":["Echtes Unterlassungsdelikt: jeden treffend, ohne Garantenstellung. Steht der SMA in einer Garantenstellung (Bewachungsvertrag), kommt zusätzlich ein unechtes Unterlassungsdelikt (§13) in Betracht.","Zumutbar heißt: ohne erhebliche eigene Gefahr — niemand muss sich selbst opfern."],"praxis":["Ein SMA sieht auf der Revierfahrt einen Mann zusammenbrechen und bewusstlos liegen bleiben, fährt aber weiter, um pünktlich Feierabend zu machen."]},"visual":null}],"quiz":[{"q":"Wann liegt gefährliche Körperverletzung gemäß §§ 223, 224 StGB vor?","a":"","multi":true,"tag":"Körperverletzungsdelikte","src":"Prüfung","options":[{"t":"Wenn jemand die Körperverletzung mittels hinterlistigen Überfalls begeht","c":true},{"t":"Wenn jemand mittels einer Waffe oder eines anderen gefährlichen Werkzeugs die Körperverletzung begeht","c":true},{"t":"Wenn jemand durch die Körperverletzung den Verlust des Sehvermögens auf einem Auge verursacht","c":false},{"t":"Wenn jemand durch die Körperverletzung, z.B. eine Ohrfeige, das körperliche Wohlbefinden für kurze Zeit beeinträchtigt","c":false}]},{"q":"Türsteher S verweigert dem leicht alkoholisierten Gast G den Zutritt zur Diskothek. Daraufhin schlägt G den S mit einem Schlagring nieder. S erleidet am Kinn eine Platzwunde. Hat sich G strafbar gemacht?","a":"","multi":true,"tag":"Körperverletzungsdelikte","src":"Prüfung","options":[{"t":"Ja, wegen versuchten Hausfriedensbruchs gemäß § 123 StGB","c":false},{"t":"Ja, wegen fahrlässiger Körperverletzung gemäß §§ 223, 229 StGB","c":false},{"t":"Ja, wegen des Führens einer nach dem WaffG verbotenen Waffe","c":true},{"t":"Ja, wegen gefährlicher Körperverletzung gemäß §§ 223, 224 StGB","c":true}]},{"q":"Erläutere §223 StGB Körperverletzung, Tatbestandmerkmale","a":"(genaue Bezeichnung) Wer einer anderen Person körperlich misshandelt oder an der Gesundheit schädigt, relatives Antragsdelikt, Vergehen","multi":false,"tag":"Körperverletzungsdelikte","src":"Skript","options":[]},{"q":"Benennen Sie die Tatbestandsmerkmale der Körperverletzung nach § 223 StGB !","a":"Einen anderen Menschen Körperlich misshandeln\toder an der Gesundheit schädigen","multi":false,"tag":"Körperverletzungsdelikte","src":"Folien","options":[]},{"q":"Was wird mit der vorläufigen Festnahme gerechtfertigt ?","a":"Die Freiheitsberaubung nach § 239 StGB gegenüber dem Täter Die Körperverletzung nach § 223 StGB gegenüber dem Täter(im verhältnismäßigen Rahmen)","multi":false,"tag":"Körperverletzungsdelikte","src":"Folien","options":[]},{"q":"Wie wird eine einfache Körperverletzung zur gefährlichen","a":"Körperverletzung §224 StGB, nenne alle Tatbestandsmerkmale. Sie qualifiziert sich durch beibringen von Gift, Waffe oder gefährliches Werkzeug, gemeinschaftlich, hinterlistiger Überfall oder einer das Leben gefährdende Behandlung; Offizialdelikt, Vergehen","multi":false,"tag":"Körperverletzungsdelikte","src":"Skript","options":[]},{"q":"Welche Körperverletzungsdelikte sind für die private Sicherheit relevant ?","a":"„einfache“ Körperverletzung Gefährliche Körperverletzung Schwere Körperverletzung Fahrlässige Körperverletzung","multi":false,"tag":"Körperverletzungsdelikte","src":"Folien","options":[]},{"q":"Was ist der Unterschied zwischen der gefährlichen und der schweren Körperverletzung?","a":"Gefährliche Körperverletzung- bezieht sich auf das „WIE?“- Gift; gesundheitsschädlicher Stoff; Waffe; gefährliches Werkzeug, hinterlistiger Überfall; gemeinschaftlich mit anderen, das leben gefährdende Behandlung Schwere Körperverletzung- bezieht sich auf die FOLGE der KV- Augenlicht (ein oder zwei Augen), Gehör; dauerhaft entstellt; Sprechvermögen verloren; Gliedmaßen verloren; Siechtum, Fortpflanzungsfähigkeit; geistige Beeinträchtigung/Behinderung","multi":false,"tag":"Körperverletzungsdelikte","src":"Folien","options":[]},{"q":"Erläutere §226 StGB Schwere Körperverletzung, Tatbestandsmerkmale.","a":"Sie qualifiziert sich durch Verlust des Gehörs, Motorik, Sprachvermögen, Sehvermögen, wichtiges Körperglied, Siechtum; Offizialdelikt, Verbrechen ! Eine weitere ist die Körperverletzung mit Todesfolge § 227 StGB","multi":false,"tag":"Körperverletzungsdelikte","src":"Skript","options":[]},{"q":"Was besagt §229 StGB fahrlässige Köperverletzung?","a":"Wenn man durch Fahrlässigkeit eine körperliche Schädigung bei einer anderen Person verursacht. Merke: Es gibt keine fahrlässige, gefährliche, schwere Körperverletzung; Entweder es ist mit Vorsatz oder Fahrlässig geschehen; (Möglichkeiten der Fahrlässigkeit: Fahrlässige KV, § 229 StGB oder Fahrlässige Tötung, § 222 StGB)","multi":false,"tag":"Körperverletzungsdelikte","src":"Skript","options":[]},{"q":"Was bedeutet fahrlässig, wann werden fahrlässige Taten bestraft?","a":"Fahrlässigkeit ist wenn man die notwendige Sorgfaltspflicht vernachlässigt, bestraft wird man nur, wenn es ausdrücklich im Gesetzt mit Strafe bedroht wird; z.B. (§ 229 StGB „fahrlässige Körperverletzung“)","multi":false,"tag":"Körperverletzungsdelikte","src":"Skript","options":[]},{"q":"Worin liegt der Kernunterschied zwischen gefährlicher (§224) und schwerer (§226) Körperverletzung?","a":"§224 stellt auf die gefährliche ART der Begehung ab (Waffe/Werkzeug, Gift, gemeinschaftlich, hinterlistig, lebensgefährdend). §226 stellt auf die schwere, dauerhafte FOLGE für das Opfer ab (Verlust von Sehkraft/Gehör/Gliedern, Lähmung, Entstellung). Beides kann gleichzeitig vorliegen.","multi":false,"tag":"Körperverletzungsdelikte","src":"Verständnis","options":[]},{"q":"Nenne die fünf Begehungsweisen der gefährlichen Körperverletzung §224.","a":"1. mittels Gift/gesundheitsschädlicher Stoffe, 2. mittels Waffe oder gefährlichem Werkzeug, 3. mittels hinterlistigen Überfalls, 4. gemeinschaftlich, 5. mittels einer das Leben gefährdenden Behandlung.","multi":false,"tag":"Körperverletzungsdelikte","src":"Verständnis","options":[]},{"q":"Warum ist die fahrlässige Körperverletzung §229 nie als Versuch strafbar?","a":"Ein Versuch setzt den Willen zur Tat (unmittelbares Ansetzen zur Verwirklichung) voraus. Bei Fahrlässigkeit fehlt gerade das Wollen — der Täter verwirklicht den Erfolg ungewollt durch Sorgfaltspflichtverletzung. Ohne Tatentschluss kann es keinen Versuch geben.","multi":false,"tag":"Körperverletzungsdelikte","src":"Verständnis","options":[]},{"q":"Wer begeht eine strafbare Freiheitsberaubung gemäß § 239 StGB?","a":"","multi":true,"tag":"Freiheitsberaubung","src":"Prüfung","options":[{"t":"Wer einen Menschen gegen dessen Willen an einen Baum ankettet","c":true},{"t":"Wer unbefugt alle Ausgänge eines Gebäudes blockiert, sodass niemand nach Hause gehen kann","c":true},{"t":"Wer einen Menschen in einen Raum einsperrt, der sich im Erdgeschoß befindet und mit leicht zu öffnenden Fenstern ausgestattet ist.","c":false},{"t":"Wer einen Menschen bei Begehung eines Diebstahls gemäß § 127 Abs. 1 StPO vorläufig festnimmt","c":false}]},{"q":"Erläutere §239 StGB Freiheitsberaubung, Tatbestandsmerkmale.","a":"Wer einen anderen Menschen einsperrt oder auf einer anderen Weise die Freiheit raubt; K.O. Tropfen etc.","multi":false,"tag":"Freiheitsberaubung","src":"Skript","options":[]},{"q":"Was wird mit der vorläufigen Festnahme gerechtfertigt ?","a":"Die Freiheitsberaubung nach § 239 StGB gegenüber dem Täter Die Körperverletzung nach § 223 StGB gegenüber dem Täter(im verhältnismäßigen Rahmen)","multi":false,"tag":"Freiheitsberaubung","src":"Folien","options":[]},{"q":"Welches Grundrecht schützt §239 und welche Voraussetzung muss das Opfer erfüllen?","a":"Geschützt ist die Fortbewegungsfreiheit — das Recht, jeden Ort ungehindert verlassen zu können. Das Opfer muss einen Fortbewegungswillen bilden können; Babys, Schlafende und Komapatienten scheiden aus, solange sie diesen Willen nicht bilden können.","multi":false,"tag":"Freiheitsberaubung","src":"Verständnis","options":[]},{"q":"Wie weit darf ein SMA einen Dieb nach §127 StPO festhalten, ohne sich nach §239 strafbar zu machen?","a":"Nur so lange und so intensiv, wie es zur Übergabe an die Polizei erforderlich und verhältnismäßig ist. Festhalten und Warten ist zulässig; Anketten, Wegsperren oder eigenmächtiges Verhören überschreitet die Rechtfertigung und wird zur Freiheitsberaubung.","multi":false,"tag":"Freiheitsberaubung","src":"Verständnis","options":[]},{"q":"Türsteher T verweigert dem 30-jährigen M den Zutritt in die Diskothek. Daraufhin spuckt M dem T ins Gesicht und droht ihm mit geballter Faust Schläge an, um so den Einlaß in die Diskothek zu erzwingen. T lässt sich aber nicht beeindrucken und setzt sich gegen M durch. Welche Aussagen zu diesem Fall sind richtig?","a":"","multi":true,"tag":"Nötigung","src":"Prüfung","options":[{"t":"M begeht einen versuchten Hausfriedensbruch","c":false},{"t":"M begeht eine versuchte Nötigung","c":true},{"t":"M begeht eine vorsätzliche tätliche Beleidigung","c":true},{"t":"M begeht eine vollendete Nötigung","c":false}]},{"q":"Erläutere §240 StGB Nötigung, Tatbestandsmerkmale.","a":"Wer einen anderen Menschen rechtswidrig mit Gewalt oder durch Drohung mit einem empfindlichen Übel zu einer Handlung, Duldung oder Unterlassen nötigt.","multi":false,"tag":"Nötigung","src":"Skript","options":[]},{"q":"Welche Tatbestandsmerkmale hat die Nötigung?","a":"Einen anderen Menschen durch Anwendung von Gewalt oder Androhung von Gewalt oder empfindliches Übel zu einem Tun, Dulden oder Unterlassen nötigen !!! Der Versuch ist strafbar !!!","multi":false,"tag":"Nötigung","src":"Folien","options":[]},{"q":"Mit welchen zwei Mitteln kann eine Nötigung begangen werden, und was bedeutet „empfindliches Übel“?","a":"Mit Gewalt oder durch Drohung mit einem empfindlichen Übel. Empfindliches Übel = eine spürbar nachteilige Folge, mit der gedroht wird (z. B. Verlust des Arbeitsplatzes, Bloßstellung). Die Nötigung ist nur strafbar, wenn das Mittel-Zweck-Verhältnis verwerflich ist (§240 Abs. 2).","multi":false,"tag":"Nötigung","src":"Verständnis","options":[]},{"q":"Wodurch unterscheidet sich die Nötigung §240 von der Erpressung §253?","a":"Die Erpressung verlangt zusätzlich, dass das genötigte Verhalten das Vermögen des Opfers schädigt und der Täter sich bereichern will. Fehlt der Vermögensbezug, bleibt es bei der Nötigung.","multi":false,"tag":"Nötigung","src":"Verständnis","options":[]},{"q":"Wann liegt der besonders schwere Fall des Diebstahls gemäß §§ 242, 243 StGB vor?","a":"","multi":true,"tag":"Diebstahlsdelikte","src":"Prüfung","options":[{"t":"Wenn der Täter die Hilflosigkeit einer anderen Person ausnutzt und ihr die Geldbörse aus der Hosentasche stiehlt","c":true},{"t":"Wenn der Täter eine Geldbörse aus einem offenen Einkaufskorb stiehlt","c":false},{"t":"Wenn der Täter in einem Kaufhaus Parfüm im Wert von 30 Euro stiehlt","c":false},{"t":"Wenn der Täter aus einem Museum ein Ausstellungsstück stiehlt","c":true}]},{"q":"Welche Aussagen zum Diebstahl gemäß § 242 StGB und zur Unterschlagung gemäß § 246 StGB sind richtig?","a":"","multi":true,"tag":"Diebstahlsdelikte","src":"Prüfung","options":[{"t":"Beim Diebstahl ist der Versuch strafbar, bei der Unterschlagung nicht","c":false},{"t":"Diebstahl ist ein Offizialdelikt, Unterschlagung ein Antragsdelikt","c":false},{"t":"Diebstahl und Unterschlagung sind Eigentumsdelikte. Aber sie unterscheiden sich in der Ausführung der Tat","c":true},{"t":"Beim Diebstahl und bei der Unterschlagung handelt es sich bei den Tatobjekten um fremde bewegliche Sachen","c":true}]},{"q":"Welche Aussagen zum Diebstahl (§ 242 StGB) und zur Unterschlagung (§ 246 StGB) sind richtig?","a":"","multi":true,"tag":"Diebstahlsdelikte","src":"Prüfung","options":[{"t":"Bei beiden Delikten handelt es sich um Offizialdelikte","c":true},{"t":"Bei beiden Delikten handelt es sich um Vergehen","c":true},{"t":"Bei beiden Delikten ist der Versuch straflos","c":false},{"t":"Bei beiden Delikten handelt es sich um Antragsdelikte","c":false}]},{"q":"Nennen Sie die 3 echten Unterlassungsdelikte und was sind unechte","a":"Unterlassungsdelikte? „Echte“ Unterlassungsdelikte stehen echt im Gesetz (Text/Tatbestand); Es sind Straftaten die auf Unterlassung beruhen; Merke: keine Garantenpflicht! (Nichtanzeige von Straftaten, unterlassene Hilfeleistung, Hausfriedensbruch (2te Begehungsart = Verweilen trotz Aufforderung) „Unechte“ Unterlassungsdelikte liegen vor wen jemand rechtlich dazu verpflichtet ist (Garantenstellung) und es unterlässt eine strafbare Handlung abzuwenden, diese werden im §13 StGB zusammengefasst; z.B. nicht Salzstreuen, keine Fahrzeugkontrolle durchführen, Unterschied liegt in der Bestrafung! Garant wird bei Unterlassen wie Täter bestraft; z.B. Ladendetektiv lässt absichtlich Bekannten mit Diebesgut flüchten (§ 242,13 StGB, Diebstahl durch Unterlassen !)","multi":false,"tag":"Diebstahlsdelikte","src":"Skript","options":[]},{"q":"Erläutere §242 Diebstahl, Tatbestandsmerkmale (genaue Bezeichnung)","a":"Wegnahme einer fremden beweglichen Sache mit rechtswidriger Zueignungsabsicht (Stehlabsicht für sich selber oder Dritten).","multi":false,"tag":"Diebstahlsdelikte","src":"Skript","options":[]},{"q":"Definition: Wegnahme beim Diebstahl (Bruch...)","a":"Bruch fremden Gewahrsam, Begründung in neuen Gewahrsam/CD in Jacke stecken","multi":false,"tag":"Diebstahlsdelikte","src":"Skript","options":[]},{"q":"Was ist der besonders schwere Fall des Diebstahls ?","a":"Ein Diebstahl gem. §242 StGB + durch einbrechen mit falschem Schlüssel oder Werkzeug in Geschäftsräume, Lagerhallen, befriedetes Besitztum aus einem verschlossenen Behältnis gewerbsmäßig Hilflose Person bestehlen Aus Religionsgebäuden (Sachen zur Religionsausübung) Aus Museen, etc. (Sachen von bedeutendem Wert für Kunst, Geschichte, etc.) das stehlen erlaubnispflichtiger Waffen (!!! Nicht verwechseln mit dem „Diebstahl mit Waffen (§244 StGB)“ !!!)","multi":false,"tag":"Diebstahlsdelikte","src":"Folien","options":[]},{"q":"Was verstehen Sie unter einem Diebstahl mit Waffe?","a":"Diebstahl im Sinne des § 242 StGB + Täter führt eine Waffe* oder gefährliches Werkzeug* mit sich * Alles, was laut Waffengesetz als Waffe definiert ist, + andere Gegenstände wie Baseballschläger etc.","multi":false,"tag":"Diebstahlsdelikte","src":"Folien","options":[]},{"q":"Wie wird ein einfacher Diebstahl zum besonders schweren","a":"Fall des Diebstahls gem. §243 StGB, Nenne alle Tatbestandsmerkmale. - In einen Geschäftsraum o.ä. einbrechen, einsteigen oder sich verborgen halten, - sich mit falschem Schlüssel Zutritt verschafft. - Eine Sache stiehlt die durch eine besondere Schutzvorrichtung gesichert ist, - Wer gewerbsmäßig stielt, Kirchendiebstahl, Museums-, Ausstellungsdiebstahl, - die Hilflosigkeit oder Unglücksfall anderer ausnutzt oder Handfeuerwaffen stehlen. In den Fällen des Absatzes 1 Satz 2 Nr. 1 bis 6 ist ein besonders schwerer Fall ausgeschlossen, wenn sich die Tat auf eine geringwertige Sache bezieht.","multi":false,"tag":"Diebstahlsdelikte","src":"Skript","options":[]},{"q":"Was sind Rechte und Pflichte eines Zeugen gem. der StPO.","a":"Der Zeuge muss vor Gericht erscheinen, zur Sache aussagen, er kann aber die Aussage verweigern wen er sich selbst belastet oder ein Familienangehörigen. 76 Zeugnis- bzw. Auskunftsverweigerungsrecht, was besagt dieses? Wen er sich selbst oder ein Familienangehörigen dadurch belastet, hat das Recht diese zu verweigern. Fallbeispiel: a) Jemand bricht mit einem Stemmeisen den Kofferraum eines PKW auf um zu stehlen, b) Jemand bricht mit einem Stemmeisen in eine Wohnung ein um zu stehlen ? Wo ist der Unterschied ? Der Unterschied ist zum einen der Tatbestand und zum anderen das Strafmaß Bei a) liegt ein Besonders schwerer Fall des Diebstahls gem. § 243 StGB Nr. 2 vor (eine Sache stiehlt, die durch ein verschlossenes Behältnis oder eine andere Schutzvorrichtung gegen Wegnahme besonders gesichert ist). Bei b) liegt ein Wohnungseinbruchsdiebstahl gemäß § 244 StGB vor (einen Diebstahl begeht, bei dem er zur Ausführung der Tat in eine Wohnung einbricht, einsteigt, mit einem falschen Schlüssel oder einem anderen nicht zur ordnungsmäßigen Öffnung bestimmten Werkzeug eindringt oder sich in der Wohnung verborgen hält)","multi":false,"tag":"Diebstahlsdelikte","src":"Skript","options":[]},{"q":"Wann liegt gem. §244 StGB ein Diebstahl mit Waffe vor?","a":"Wenn man bei der Straftat eine Waffe oder gefährliches Werkzeug mit sich führt. Sie müssen aber nicht benutzt werden, das alleinige mitführen reicht schon aus.","multi":false,"tag":"Diebstahlsdelikte","src":"Skript","options":[]},{"q":"Erkläre den Begriff Wohnungseinbruchdiebstahl","a":"Wer bei einem Diebstahl in eine Wohnung einbricht, einsteigt, mit falschen Schlüssel, Werkzeug oder sich in der Wohnung verborgen hält. Wird nach § 244 StGB bestraft; Seit 22.07.2017 VERBRECHEN!","multi":false,"tag":"Diebstahlsdelikte","src":"Skript","options":[]},{"q":"Was bedeutet Diebstahl einer geringwertigen Sache gem. §248 StGB.","a":"Wird nur auf Antrag verfolgt, es sei denn es liegt ein besonderes öffentliches Interesse vor, Geringwertigkeit von ca. 50€.","multi":false,"tag":"Diebstahlsdelikte","src":"Skript","options":[]},{"q":"Was ist Diebstahl geringwertiger Sachen?","a":"Diebstahl von Sachen bis 50,00 € Wert","multi":false,"tag":"Diebstahlsdelikte","src":"Folien","options":[]},{"q":"Erkläre den Begriff „Wegnahme“ beim Diebstahl.","a":"Wegnahme = Bruch fremden Gewahrsams und Begründung neuen (eigenen) Gewahrsams gegen den Willen des bisherigen Inhabers. Gewahrsam ist die tatsächliche Sachherrschaft, getragen von einem Herrschaftswillen.","multi":false,"tag":"Diebstahlsdelikte","src":"Verständnis","options":[]},{"q":"Was ist der Unterschied zwischen §243 und §244?","a":"§243 (besonders schwerer Fall) ist eine Strafzumessungsregel mit Regelbeispielen (Einbruch, gewerbsmäßig, besonders gesicherte Sachen …), kein eigener Tatbestand. §244 (Diebstahl mit Waffen/Bande/Wohnungseinbruch) ist ein eigenständiger Straftatbestand mit höherem Strafrahmen.","multi":false,"tag":"Diebstahlsdelikte","src":"Verständnis","options":[]},{"q":"Ab welchem Wert spricht man von geringwertigen Sachen, und welche Folge hat das?","a":"Richtwert: unter ca. 50 €. Dann ist der Diebstahl/die Unterschlagung ein relatives Antragsdelikt (§248a) — Verfolgung nur mit Strafantrag oder bei besonderem öffentlichen Interesse. Ausnahme: gestohlene Waffen/Munition (§243 Nr. 7).","multi":false,"tag":"Diebstahlsdelikte","src":"Verständnis","options":[]},{"q":"Einer Person ist auf dem Heimweg ein Buch aus der Tasche gefallen. Als die Person den Verlust des Buchs bemerkt, kann sie sich nicht erinnern, wo ihr das Buch abhandengekommen ist. Ein Passant, der das Buch auf einem Fußweg entdeckt, nimmt es an sich, um es zu behalten. Welche Aussage zu diesem Fall ist richtig?","a":"","multi":false,"tag":"Unterschlagung","src":"Prüfung","options":[{"t":"Der Passant hat sich wegen Diebstahls strafbar gemacht","c":false},{"t":"Der Passant hat sich wegen Betruges strafbar gemacht","c":false},{"t":"Der Passant hat sich wegen Unterschlagung strafbar gemacht","c":true},{"t":"Der Passant hat sich nicht strafbar gemacht","c":false}]},{"q":"Welche Aussagen zur Unterschlagung gemäß § 246 StGB sind richtig?","a":"","multi":true,"tag":"Unterschlagung","src":"Prüfung","options":[{"t":"Unterschlagung liegt z.B. vor, wenn eine Person eine auf der Straße gefundene Sache in der Absicht einsteckt, diese zu behalten","c":true},{"t":"Die Unterschlagung schützt das Rechtsgut „Eigentum“","c":true},{"t":"Bei der Unterschlagung nimmt der Täter einem anderen eine bewegliche Sache mit Gewalt weg","c":false},{"t":"Die Unterschlagung ist auch bei fahrlässiger Begehung strafbar","c":false}]},{"q":"Unterschied zwischen Diebstahl und Unterschlagung?","a":"Beim Diebstahl muss man sich erst das fremde Rechtsgut aneignen, bei der Unterschlagung ist man bereits Besitzer des fremden Rechtsgut.","multi":false,"tag":"Unterschlagung","src":"Skript","options":[]},{"q":"Was ist der Unterschied zwischen Diebstahl und Unterschlagung ?","a":"Diebstahl- „Wegnahmeabsicht“ und (rechtswidrige) „Zueignungsabsicht“ müssen vorliegen Unterschlagung- hier „fehlt die Wegnahmeabsicht“- es muss lediglich die (rechtswirdrige) „Zueignungsabsicht“ zu der fremden beweglichen Sache vorliegen- der Täter hat die Sache bereits","multi":false,"tag":"Unterschlagung","src":"Folien","options":[]},{"q":"Was versteht man unter dem Straftatbestand der Hehlerei?","a":"Ein anderer hat eine Sache durch ein Vermögensdelikt rechtswidrig erlangt (Diebstahl, Raub, Unterschlagung, etc.) Der Hehler (Täter) kauft diese Sachen, verkauft sie oder, setzt sie ab oder hilft dabei oder erwirbt sie für sich selbst oder einen Dritten ! Der Stehler (z.B.: Dieb) ist nicht der Hehler !","multi":false,"tag":"Unterschlagung","src":"Folien","options":[]},{"q":"Was bedeutet „Zueignung“ bei der Unterschlagung, und worin liegt der Hauptunterschied zum Diebstahl?","a":"Zueignung heißt, der Täter nimmt die fremde Sache erkennbar in sein eigenes Vermögen auf (behält oder verkauft sie). Hauptunterschied zum Diebstahl: Bei der Unterschlagung hat der Täter die Sache bereits in Besitz/Gewahrsam — es fehlt der Gewahrsamsbruch.","multi":false,"tag":"Unterschlagung","src":"Verständnis","options":[]},{"q":"Welche Aussagen zum Raub gemäß § 249 StGB sind richtig?","a":"","multi":true,"tag":"Raub & Räuberischer Diebstahl","src":"Prüfung","options":[{"t":"Der Täter nimmt eine fremde bewegliche Sache mit Gewalt gegen eine Person oder unter Drohung mit gegenwärtiger Gefahr für Leib oder Leben weg","c":true},{"t":"Raub ist ein Verbrechen und wird mit Freiheitsstrafe nicht unter einem Jahr bestraft","c":true},{"t":"Für einen Raub genügt es, wenn der Täter die Gewalt erst nach der Wegnahme anwendet, um die Beute zu behalten","c":false},{"t":"Ein Raub liegt auch ohne die Absicht vor, sich die Sache rechtswidrig zuzueignen","c":false}]},{"q":"Dieb D wird vom Ladendetektiv L unmittelbar nach dem Einstecken der Ware gestellt. Um die Beute zu behalten, stößt D den L kräftig zur Seite und flüchtet. Wie ist sein Verhalten einzuordnen?","a":"","multi":true,"tag":"Raub & Räuberischer Diebstahl","src":"Prüfung","options":[{"t":"Räuberischer Diebstahl gemäß § 252 StGB, weil D auf frischer Tat betroffen Gewalt anwendet, um sich im Besitz der Beute zu halten","c":true},{"t":"Der räuberische Diebstahl wird gleich einem Raub bestraft","c":true},{"t":"Nur einfacher Diebstahl, da die Gewalt nach der Wegnahme keine Rolle spielt","c":false},{"t":"Nur Nötigung, da keine Sache weggenommen wurde","c":false}]},{"q":"Was ist ein gefährliches Werkzeug Beschaffenheit und","a":"Art der Verwendung. Jeder Gegenstand kann zu einem gefährlichen Werkzeug werden. Axt, Messer, Schraubendreher,...","multi":false,"tag":"Raub & Räuberischer Diebstahl","src":"Skript","options":[]},{"q":"Erläutere §239 StGB Freiheitsberaubung, Tatbestandsmerkmale.","a":"Wer einen anderen Menschen einsperrt oder auf einer anderen Weise die Freiheit raubt; K.O. Tropfen etc.","multi":false,"tag":"Raub & Räuberischer Diebstahl","src":"Skript","options":[]},{"q":"Erläutere §249 StGB Raub, Tatbestandsmerkmale.","a":"Der Täter will einer anderen Person durch Gewalt oder Anwendung von Drohungen mit gegenwärtiger Gefahr für Leib und Leben eine fremde bewegliche Sache wegnehmen; Erst hauen, dann klauen!","multi":false,"tag":"Raub & Räuberischer Diebstahl","src":"Skript","options":[]},{"q":"Erläutere §252 StGB Räuberischer Diebstahl, Tatbestandsmerkmale.","a":"Der Täter will durch Gewaltausübung oder Anwendung von Drohungen mit gegenwärtiger Gefahr auf Leib und Leben des Besitzt des Diebesgut erhalten; Erst klauen, dann hauen!","multi":false,"tag":"Raub & Räuberischer Diebstahl","src":"Skript","options":[]},{"q":"Unterschied zwischen einem Raub und einem räuberischen Diebstahl?","a":"RaubEselsbrücke = „erst hauen – dann klauen“- Gewalt anwenden oder androhen, um in den Besitz des Diebesgutes zu kommen Räuberischer DiebstahlEselsbrücke = „erst klauen – dann hauen“- Gewalt anwenden oder androhen, um den Besitz des Diebesgutes zu erhalten","multi":false,"tag":"Raub & Räuberischer Diebstahl","src":"Folien","options":[]},{"q":"Was versteht man unter dem Straftatbestand der Begünstigung?","a":"Ein anderer hat eine rechtswidrige Tat begangen Der Täter (der Begünstigung) hilft dem Vortäter In der Absicht, die Vorteile seiner Tat zu sichern (Jens will 30.000,00 € aus einem Raub bei Pierre verstecken, Pierre weiß woher das Geldkommt und versteckt das Geld für Jens.)","multi":false,"tag":"Raub & Räuberischer Diebstahl","src":"Folien","options":[]},{"q":"Was versteht man unter dem Straftatbestand der Hehlerei?","a":"Ein anderer hat eine Sache durch ein Vermögensdelikt rechtswidrig erlangt (Diebstahl, Raub, Unterschlagung, etc.) Der Hehler (Täter) kauft diese Sachen, verkauft sie oder, setzt sie ab oder hilft dabei oder erwirbt sie für sich selbst oder einen Dritten ! Der Stehler (z.B.: Dieb) ist nicht der Hehler !","multi":false,"tag":"Raub & Räuberischer Diebstahl","src":"Folien","options":[]},{"q":"Was wird mit der vorläufigen Festnahme gerechtfertigt ?","a":"Die Freiheitsberaubung nach § 239 StGB gegenüber dem Täter Die Körperverletzung nach § 223 StGB gegenüber dem Täter(im verhältnismäßigen Rahmen)","multi":false,"tag":"Raub & Räuberischer Diebstahl","src":"Folien","options":[]},{"q":"Merke dir Raub und räuberischen Diebstahl über je einen Spruch — und erkläre den Unterschied.","a":"Raub §249: „Erst hauen, dann klauen“ — Gewalt/Drohung VOR der Wegnahme, um sie zu ermöglichen. Räuberischer Diebstahl §252: „Erst klauen, dann hauen“ — nach vollendetem Diebstahl Gewalt/Drohung, um die Beute zu sichern (Beutesicherungsabsicht). Beide werden als Verbrechen ab 1 Jahr bestraft.","multi":false,"tag":"Raub & Räuberischer Diebstahl","src":"Verständnis","options":[]},{"q":"Welche Merkmale kennzeichnen die Erpressung gemäß § 253 StGB?","a":"","multi":true,"tag":"Erpressung","src":"Prüfung","options":[{"t":"Der Täter nötigt das Opfer durch Gewalt oder Drohung zu einer Handlung, Duldung oder Unterlassung","c":true},{"t":"Dem Opfer oder einem Dritten entsteht dadurch ein Vermögensnachteil","c":true},{"t":"Der Täter handelt in der Absicht, sich oder einen Dritten zu Unrecht zu bereichern","c":true},{"t":"Die Erpressung setzt zwingend die Wegnahme einer Sache durch den Täter voraus","c":false}]},{"q":"Wodurch unterscheidet sich die räuberische Erpressung (§ 255 StGB) von der einfachen Erpressung?","a":"","multi":true,"tag":"Erpressung","src":"Prüfung","options":[{"t":"Der Täter setzt Gewalt gegen eine Person ein oder droht mit gegenwärtiger Gefahr für Leib oder Leben","c":true},{"t":"Die räuberische Erpressung wird gleich einem Raub bestraft","c":true},{"t":"Sie ist ein Vergehen mit geringer Strafandrohung","c":false},{"t":"Sie setzt keine Bereicherungsabsicht voraus","c":false}]},{"q":"Welche vier Elemente kennzeichnen die Erpressung §253?","a":"1. Nötigung mit Gewalt oder Drohung mit empfindlichem Übel, 2. zu einer Handlung/Duldung/Unterlassung, 3. die das Vermögen des Opfers schädigt, 4. mit der Absicht, sich oder einen Dritten zu bereichern. Mit Gewalt gegen eine Person oder Drohung mit gegenwärtiger Gefahr für Leib/Leben wird es zur räuberischen Erpressung §255 (Verbrechen).","multi":false,"tag":"Erpressung","src":"Verständnis","options":[]},{"q":"Zu welchem Zeitpunkt ist die Begünstigung gemäß § 257 StGB möglich?","a":"","multi":false,"tag":"Begünstigung & Hehlerei","src":"Prüfung","options":[{"t":"Während der Begehung einer rechtswidrigen Straftat eines anderen","c":false},{"t":"Vor der Begehung einer rechtswidrigen Straftat eines anderen","c":false},{"t":"Nach der Begehung einer rechtswidrigen Ordnungswidrigkeit eines anderen","c":false},{"t":"Nach der Begehung einer rechtswidrigen Straftat eines anderen","c":true}]},{"q":"Was versteht man unter dem Straftatbestand der Begünstigung?","a":"Ein anderer hat eine rechtswidrige Tat begangen Der Täter (der Begünstigung) hilft dem Vortäter In der Absicht, die Vorteile seiner Tat zu sichern (Jens will 30.000,00 € aus einem Raub bei Pierre verstecken, Pierre weiß woher das Geldkommt und versteckt das Geld für Jens.)","multi":false,"tag":"Begünstigung & Hehlerei","src":"Folien","options":[]},{"q":"Was versteht man unter dem Straftatbestand der Hehlerei?","a":"Ein anderer hat eine Sache durch ein Vermögensdelikt rechtswidrig erlangt (Diebstahl, Raub, Unterschlagung, etc.) Der Hehler (Täter) kauft diese Sachen, verkauft sie oder, setzt sie ab oder hilft dabei oder erwirbt sie für sich selbst oder einen Dritten ! Der Stehler (z.B.: Dieb) ist nicht der Hehler !","multi":false,"tag":"Begünstigung & Hehlerei","src":"Folien","options":[]},{"q":"Wodurch unterscheiden sich Begünstigung §257, Hehlerei §259 und Strafvereitelung §258?","a":"Begünstigung: dem Vortäter helfen, die VORTEILE seiner Tat zu sichern. Hehlerei: die Sache aus der Vortat zum eigenen Vorteil ankaufen/absetzen/verschaffen. Strafvereitelung: verhindern, dass der Täter BESTRAFT wird. Voraussetzung bei Hehlerei: eine Vortat eines ANDEREN — der eigene Dieb kann nicht Hehler derselben Sache sein.","multi":false,"tag":"Begünstigung & Hehlerei","src":"Verständnis","options":[]},{"q":"Welche Voraussetzungen müssen für einen Betrug gemäß § 263 StGB vorliegen?","a":"","multi":true,"tag":"Betrug & Erschleichen von Leistungen","src":"Prüfung","options":[{"t":"Eine Täuschung durch Vorspiegelung falscher oder Entstellung wahrer Tatsachen","c":true},{"t":"Ein dadurch erregter Irrtum, der zu einer Vermögensverfügung und einem Vermögensschaden führt","c":true},{"t":"Die Absicht, sich oder einen Dritten rechtswidrig zu bereichern","c":true},{"t":"Die Wegnahme einer fremden beweglichen Sache gegen den Willen des Opfers","c":false}]},{"q":"Welche Fälle sind ein Erschleichen von Leistungen gemäß § 265a StGB?","a":"","multi":true,"tag":"Betrug & Erschleichen von Leistungen","src":"Prüfung","options":[{"t":"Das Fahren mit öffentlichen Verkehrsmitteln ohne gültigen Fahrschein","c":true},{"t":"Das Betreten einer kostenpflichtigen Veranstaltung, ohne den Eintritt zu bezahlen","c":true},{"t":"Der Diebstahl des Fahrkartenautomaten am Bahnhof","c":false},{"t":"Das Fälschen einer Eintrittskarte für ein Konzert","c":false}]},{"q":"Erläutere §263 StGB Betrug, Tatbestandsmerkmale.","a":"Betrug ist die Erregung eines Irrtums durch Täuschungshandlung, mit der Absicht sich einen Vermögensvorteil zu verschaffen und ein vermögensnachteil für den anderen im Kauf nimmt.","multi":false,"tag":"Betrug & Erschleichen von Leistungen","src":"Skript","options":[]},{"q":"Erläutere $265a StGB Erschleichen von Leistungen, Tatbestandsmerkmale.","a":"Wer die Leistung eines Automaten, Telekommunikationsnetzes, Beförderung durch öffentliche Verkehrsmittel, Zutritt zu Veranstaltungen oder Einrichtungen erschleicht mit der Absicht das Entgelt nicht zu entrichten.","multi":false,"tag":"Betrug & Erschleichen von Leistungen","src":"Skript","options":[]},{"q":"Was versteht man unter dem Erschleichen von Leistungen?","a":"Die Nutzung von öffentlichen Verkehrsmitteln erschleichen Den kostenpflichtigen Zutritt zu Veranstaltungen oder Einrichtungen (Theater, Diskothek, Messe, etc.) erschleichen . . . um das Entgelt nicht zahlen zu müssen","multi":false,"tag":"Betrug & Erschleichen von Leistungen","src":"Folien","options":[]},{"q":"Nenne die vier objektiven Schritte des Betrugs §263 in der richtigen Reihenfolge.","a":"1. Täuschungshandlung (falsche Tatsachen vorspiegeln oder wahre unterdrücken), 2. dadurch ein Irrtum beim Opfer, 3. eine Vermögensverfügung des Irrenden, 4. ein Vermögensschaden. Hinzu kommt im subjektiven Tatbestand die Absicht rechtswidriger, stoffgleicher Bereicherung.","multi":false,"tag":"Betrug & Erschleichen von Leistungen","src":"Verständnis","options":[]},{"q":"Warum greift beim unbemerkten Schwarzfahren §265a statt §263?","a":"Beim Betrug muss ein Mensch getäuscht werden und einem Irrtum unterliegen. Wer unbemerkt schwarzfährt, täuscht niemanden aktiv — es fehlt das getäuschte, verfügende Opfer. Deshalb greift der Auffangtatbestand Erschleichen von Leistungen §265a (Beförderung ohne Entgelt).","multi":false,"tag":"Betrug & Erschleichen von Leistungen","src":"Verständnis","options":[]},{"q":"Welche Aussagen zur Untreue gemäß § 266 StGB sind richtig?","a":"","multi":true,"tag":"Untreue","src":"Prüfung","options":[{"t":"Der Täter missbraucht eine ihm eingeräumte Befugnis, über fremdes Vermögen zu verfügen, oder verletzt seine Pflicht, fremde Vermögensinteressen wahrzunehmen","c":true},{"t":"Dem Betreuten entsteht dadurch ein Vermögensnachteil","c":true},{"t":"Untreue kann nur begehen, wer eine besondere Vermögensbetreuungspflicht hat","c":true},{"t":"Untreue setzt voraus, dass der Täter dem Opfer eine Sache mit Gewalt wegnimmt","c":false}]},{"q":"Kassierer K eines Vereins überweist vereinbarungswidrig Vereinsgelder auf sein Privatkonto und verursacht dem Verein dadurch einen Schaden. Wie ist das einzuordnen?","a":"","multi":true,"tag":"Untreue","src":"Prüfung","options":[{"t":"Untreue gemäß § 266 StGB, da K seine Pflicht zur Betreuung fremden Vermögens verletzt und einen Vermögensnachteil verursacht","c":true},{"t":"Untreue ist hier möglich, weil K eine Vermögensbetreuungspflicht für den Verein hat","c":true},{"t":"Diebstahl, weil K dem Verein eine fremde bewegliche Sache wegnimmt","c":false},{"t":"Straflos, da K als Kassierer ohnehin über das Geld verfügen darf","c":false}]},{"q":"Was ist die auffälligste Besonderheit der Untreue §266 gegenüber Diebstahl und Betrug?","a":"Bei der Untreue ist der Versuch STRAFLOS. Bei Diebstahl §242 und Betrug §263 ist der Versuch dagegen strafbar. Außerdem setzt §266 eine besondere Vermögensbetreuungspflicht voraus, die missbraucht oder verletzt wird.","multi":false,"tag":"Untreue","src":"Verständnis","options":[]},{"q":"Wann liegt Urkundenfälschung gemäß § 267 StGB vor?","a":"","multi":false,"tag":"Urkundsdelikte","src":"Prüfung","options":[{"t":"Wenn ein Prüfungsteilnehmer in einem Brief der Industrie- und Handelskammer mitteilt, dass er wegen Krankheit nicht zur Prüfung erscheinen könne. Diese Mitteilung entspricht nicht der Wahrheit","c":false},{"t":"Wenn ein Autofahrer das Kennzeichen seines Kfz mit durchsichtiger Folie überklebt, sodass die fotografische Beweisführung bei Verkehrsverstößen verhindert wird","c":false},{"t":"Wenn ein Jugendlicher, der vor seinen Freunden als „cooler Typ“ erscheinen will, in einem Geschäft das Preisschild von einem Laptop entfernt","c":false},{"t":"Wenn ein Kunde einen Laptop bestellt. Auf dem Bestellschein verringert er den Preis durch geschicktes Überschreiben um 250 Euro. Der Kunde unterschreibt den Bestellschein und gibt ihn beim Lieferanten ab","c":true}]},{"q":"Erläutere §267 Urkundenfälschung, Tatbestandsmerkmale.","a":"Wer falsche Urkunden herstellt oder echte Urkunden verfälscht wird erst dann bestraft wenn sie in den Rechtsverkehr einbringt.","multi":false,"tag":"Urkundsdelikte","src":"Skript","options":[]},{"q":"Was ist eine Urkundenfälschung?","a":"Eine unechte Urkunde herstellen oder Eine echte Urkunde verfälschen (abändern) oder eine gefälschte oder unechte Urkunde nutzen um im Rechtsverkehr zu täuschen","multi":false,"tag":"Urkundsdelikte","src":"Folien","options":[]},{"q":"Wer kann sich einem Missbrauch von Ausweispapieren strafbar machen?","a":"Den Ausweis eines anderen zur Täuschung im Rechtsverkehr nutzen / gebrauchen Wer einem anderen zur Täuschung im Rechtsverkehr seinen Ausweis überlässt Täuschung im Rechtsverkehr = rechtlichen Vorteil verschaffen","multi":false,"tag":"Urkundsdelikte","src":"Folien","options":[]},{"q":"Was ist eine „Urkunde“ im Sinne des §267, und wie grenzt sich §267 von §281 ab?","a":"Urkunde = verkörperte Gedankenerklärung, die zum Beweis geeignet und bestimmt ist und einen Aussteller erkennen lässt (z. B. Kassenbon, Fahrzeugschein, Eintrittskarte). Abgrenzung: §267 betrifft eine unechte/verfälschte Urkunde; §281 betrifft ein ECHTES Ausweispapier, das vom falschen Inhaber zur Täuschung gebraucht wird.","multi":false,"tag":"Urkundsdelikte","src":"Verständnis","options":[]},{"q":"Wann liegt eine strafbare Sachbeschädigung gemäß § 303 StGB vor?","a":"","multi":true,"tag":"Sachbeschädigung","src":"Prüfung","options":[{"t":"Ein Kunde beschädigt bei der Eröffnungsfeier eines Einkaufszentrums aus Unachtsamkeit eine teure Haushaltsmaschine","c":false},{"t":"B reißt aus Verärgerung über die Ablehnung einer Gehaltserhöhung den Außenspiegel an einem fremden Auto ab","c":true},{"t":"Ein Spaziergänger verletzt grundlos einen fremden Hund, den ein anderer Spaziergänger frei laufen lässt","c":true},{"t":"A vernichtet im Auftrag seines Chefs einen Ordner mit nicht mehr benötigten Geschäftsunterlagen","c":false}]},{"q":"Ladendetektiv L sieht, wie eine Kundin aus Versehen eine teure Stehlampe umreißt und sich unerkannt entfernen will. Die Lampe ist zerbrochen. Darf L die Kundin gemäß § 127 Abs. 1 StPO vorläufig festnehmen?","a":"","multi":false,"tag":"Sachbeschädigung","src":"Prüfung","options":[{"t":"Ja, da die Kundin auf frischer Tat bei einer strafbaren Sachbeschädigung betroffen wurde und ihre Identität nicht sofort feststellbar ist","c":false},{"t":"Ja, aber nur wegen versuchter Sachbeschädigung, da die Kundin nicht mit Vorsatz gehandelt hat","c":false},{"t":"Ja, da die Kundin einen Schaden verursacht hat, den sie offensichtlich nicht bezahlen will","c":false},{"t":"Nein, da es sich bei dem Verhalten der Kundin um eine fahrlässige Sachbeschädigung handelt und diese straflos ist","c":true}]},{"q":"Erläutere §35 StGB Entschuldigender Notstand/Unterschiede","a":"zu §34 Rechtfertigender Notstand (Einschränkungen) Beim Entschuldigen Notstand ist die Abwendung der Gefahr nur für Leib, Leben, Freiheit oder eine nahestehende Person (z.B. Kind, Ehefrau) möglich, Beim Rechtfertigen Notstand ist die Abwehr der Gefahr für \"jedes\" Rechtsgut möglich; also auch Eigentum; Beispiel: Ihr Haus brennt (Eigentum) um dieses löschen zu können überfahren Sie den Gartenzaun Ihres Nachbarn ; (Tatbestand = Sachbeschädigung; Rechtfertigungsgrund: § 34 StGB / keine Straftat)","multi":false,"tag":"Sachbeschädigung","src":"Skript","options":[]},{"q":"Was ist ein Offizialdelikt, Was ist ein Antragsdelikt?","a":"Grundsätzlich sind alle Straftaten Offizialdelikte. Alle Verbrechen sind Offizial- delikte, aber auch Antragsdelikte wenn ein öffentliches Interesse besteht; (sogenannte „relative“ Antragsdelikte) Antragsdelikte sind Straftaten die einen Strafantrag erfordern; sogenannte Bagatellstraftaten (Diebstahl unter 50 €, einfache Körperverletzung, Sachbeschädigung) muss vom Betroffenen innerhalb von 3 Monaten erfolgen","multi":false,"tag":"Sachbeschädigung","src":"Skript","options":[]},{"q":"Erläutere §303 StGB Sachbeschädigung, Tatbestandsmerkmale.","a":"Wer rechtswidrig eine fremde Sache beschädigt, zerstört, das Erscheinungs- bild unerheblich oder vorübergehend verändert begeht Sachbeschädigung.","multi":false,"tag":"Sachbeschädigung","src":"Skript","options":[]},{"q":"Wie kann ich eine Sachbeschädigung begehen?","a":"NUR vorsätzlich !!!!!!!!! Eine Sachbeschädigung kann nicht fahrlässig begangen werden","multi":false,"tag":"Sachbeschädigung","src":"Folien","options":[]},{"q":"Welche drei Tathandlungen erfasst die Sachbeschädigung §303 — und welche Besonderheit gilt für Graffiti?","a":"Beschädigen, Zerstören und (seit §303 Abs. 2) das unbefugte, nicht nur unerhebliche und nicht nur vorübergehende Verändern des Erscheinungsbildes — damit ist Graffiti ausdrücklich erfasst, auch ohne Substanzverletzung. §303 ist ein relatives Antragsdelikt.","multi":false,"tag":"Sachbeschädigung","src":"Verständnis","options":[]},{"q":"Welche Aussagen zur Brandstiftung (§§ 306 ff. StGB) sind richtig?","a":"","multi":true,"tag":"Brandstiftung","src":"Prüfung","options":[{"t":"Wer ein fremdes Gebäude oder eine fremde Betriebsstätte in Brand setzt, macht sich strafbar","c":true},{"t":"Auch die fahrlässige Brandstiftung ist strafbar (§ 306d StGB)","c":true},{"t":"Die Brandstiftung an einem fremden Gebäude ist nur ein Vergehen mit geringer Strafe","c":false},{"t":"Eine Brandstiftung liegt nur dann vor, wenn dabei Menschen verletzt werden","c":false}]},{"q":"Was kennzeichnet die schwere Brandstiftung gemäß § 306a StGB?","a":"","multi":true,"tag":"Brandstiftung","src":"Prüfung","options":[{"t":"Das Inbrandsetzen eines Gebäudes, das Menschen zur Wohnung dient","c":true},{"t":"Das Inbrandsetzen von Räumlichkeiten, in denen sich zur Tatzeit Menschen aufhalten","c":true},{"t":"Sie wird milder bestraft als eine einfache Sachbeschädigung","c":false},{"t":"Sie ist nur strafbar, wenn das Gebäude versichert war","c":false}]},{"q":"Was ist der Unterschied zwischen „In-Brand-setzen“ und „Brandlegung“?","a":"In-Brand-setzen: Die Sache brennt selbstständig weiter. Brandlegung: Die Sache brennt nicht von selbst, wird aber durch die Brandhandlung beschädigt oder zerstört. Beide Varianten erfüllen §306 (Verbrechen, ab 1 Jahr).","multi":false,"tag":"Brandstiftung","src":"Verständnis","options":[]},{"q":"Türsteher T sieht, wie auf der anderen Straßenseite eine Person von zwei Jugendlichen verprügelt wird. Wie handelt T rechtlich korrekt?","a":"","multi":true,"tag":"Unterlassene Hilfeleistung","src":"Prüfung","options":[{"t":"T verlässt seinen Arbeitsplatz und hilft der angegriffenen Person in Nothilfe","c":true},{"t":"T erfüllt die Aufgaben gemäß seiner Dienstanweisung und übersieht mit Absicht den Vorfall. Er darf seinen Arbeitsplatz nicht verlassen","c":false},{"t":"T verständigt telefonisch die Polizei, während er sich weiter um die Einlasskontrolle kümmert","c":true},{"t":"T muss der angegriffenen Person helfen. Ansonsten verletzt er seine Garantenstellung","c":false}]},{"q":"Nennen Sie die 3 echten Unterlassungsdelikte und was sind unechte","a":"Unterlassungsdelikte? „Echte“ Unterlassungsdelikte stehen echt im Gesetz (Text/Tatbestand); Es sind Straftaten die auf Unterlassung beruhen; Merke: keine Garantenpflicht! (Nichtanzeige von Straftaten, unterlassene Hilfeleistung, Hausfriedensbruch (2te Begehungsart = Verweilen trotz Aufforderung) „Unechte“ Unterlassungsdelikte liegen vor wen jemand rechtlich dazu verpflichtet ist (Garantenstellung) und es unterlässt eine strafbare Handlung abzuwenden, diese werden im §13 StGB zusammengefasst; z.B. nicht Salzstreuen, keine Fahrzeugkontrolle durchführen, Unterschied liegt in der Bestrafung! Garant wird bei Unterlassen wie Täter bestraft; z.B. Ladendetektiv lässt absichtlich Bekannten mit Diebesgut flüchten (§ 242,13 StGB, Diebstahl durch Unterlassen !)","multi":false,"tag":"Unterlassene Hilfeleistung","src":"Skript","options":[]},{"q":"Erläutere § 323c StGB Unterlassene Hilfeleistung, Tatbestandsmerkmale.","a":"Wer bei Unglücksfällen, gemeiner Gefahr oder Not nicht Hilfe leistet, obwohl dieses erforderlich und ihm den Umständen nach zuzumuten ist ohne erhebliche eigene Gefahr und ohne Verletzung anderer wichtigen Pflichten möglich ist. (echtes Unterlassungsdelikt)","multi":false,"tag":"Unterlassene Hilfeleistung","src":"Skript","options":[]},{"q":"Wann ist die unterlassene Hilfeleistung §323c strafbar, und was bedeutet „zumutbar“?","a":"Strafbar, wer bei einem Unglücksfall, gemeiner Gefahr oder Not keine erforderliche und zumutbare Hilfe leistet, obwohl andere wichtige Pflichten nicht verletzt würden. „Zumutbar“ heißt: ohne erhebliche eigene Gefahr — niemand muss sich selbst opfern. Es ist ein echtes Unterlassungsdelikt, das jeden trifft.","multi":false,"tag":"Unterlassene Hilfeleistung","src":"Verständnis","options":[]},{"q":"Was ist der Unterschied zwischen einem echten und einem unechten Unterlassungsdelikt?","a":"Echtes Unterlassungsdelikt: trifft jeden Bürger, eine allgemeine Handlungspflicht wird verletzt (z. B. §323c, §138, §123 in der 2. Variante). Unechtes Unterlassungsdelikt: setzt eine Garantenstellung voraus (§13) — der Garant muss einen Erfolg abwenden und wird bei Untätigkeit wie ein aktiver Täter bestraft.","multi":false,"tag":"Unterlassene Hilfeleistung","src":"Verständnis","options":[]}],"cases":[{"scenario":"","frage":"Wie sind die Angreifer und wie ist der untätige Kollege Timo strafrechtlich zu bewerten?","loesung":"","thema":"Körperverletzungsdelikte"},{"scenario":"","frage":"War das gesamte Verhalten von der Notwehr gedeckt? Wie ist der Schlag auf das Knie zu bewerten?","loesung":"","thema":"Körperverletzungsdelikte"},{"scenario":"","frage":"Welche Körperverletzungsdelikte hat der Lkw-Fahrer verwirklicht?","loesung":"","thema":"Körperverletzungsdelikte"},{"scenario":"","frage":"War die Gewaltanwendung von §127 der Strafprozessordnung gedeckt? Wie ist das Verhalten des Detektivs zu bewerten?","loesung":"","thema":"Körperverletzungsdelikte"},{"scenario":"","frage":"Wann bleibt eine Körperverletzung trotz Einwilligung des Opfers strafbar?","loesung":"","thema":"Körperverletzungsdelikte"},{"scenario":"","frage":"War das Festhalten noch von §127 StPO gedeckt? Was hat der Detektiv begangen?","loesung":"","thema":"Freiheitsberaubung"},{"scenario":"","frage":"Ist hier eine Freiheitsberaubung vollendet? Was ist die Voraussetzung beim Opfer?","loesung":"","thema":"Freiheitsberaubung"},{"scenario":"","frage":"In welcher Variante liegt eine Nötigung §240 vor — und woran liegt das?","loesung":"","thema":"Nötigung"},{"scenario":"","frage":"Diebstahl §242 oder Unterschlagung §246 — und was ist das Abgrenzungskriterium?","loesung":"","thema":"Diebstahlsdelikte"},{"scenario":"","frage":"Einfacher Diebstahl §242, besonders schwerer Fall §243 oder Diebstahl mit Waffen §244?","loesung":"","thema":"Diebstahlsdelikte"},{"scenario":"","frage":"Ab welchem Moment ist der Diebstahl jeweils vollendet?","loesung":"","thema":"Diebstahlsdelikte"},{"scenario":"","frage":"Ordne beide Fälle zu und nenne das entscheidende Kriterium.","loesung":"","thema":"Unterschlagung"},{"scenario":"","frage":"Raub §249 oder räuberischer Diebstahl §252? Begründe über die Reihenfolge.","loesung":"","thema":"Raub & Räuberischer Diebstahl"},{"scenario":"","frage":"Liegt Raub §249 oder räuberische Erpressung §255 vor?","loesung":"","thema":"Raub & Räuberischer Diebstahl"},{"scenario":"","frage":"Wie macht sich der SMA selbst strafbar — und warum reicht die bloße Anzeige-Drohung dafür aus?","loesung":"","thema":"Erpressung"},{"scenario":"","frage":"Hehlerei §259 oder Begünstigung §257?","loesung":"","thema":"Begünstigung & Hehlerei"},{"scenario":"","frage":"Diebstahl §242 oder Betrug §263?","loesung":"","thema":"Betrug & Erschleichen von Leistungen"},{"scenario":"","frage":"Warum ist der Zaun-Fall §265a und nicht §263 — und was sind die anderen beiden?","loesung":"","thema":"Betrug & Erschleichen von Leistungen"},{"scenario":"","frage":"Welcher Tatbestand liegt vor — und welche Besonderheit gilt beim Versuch?","loesung":"","thema":"Untreue"},{"scenario":"","frage":"§281 oder §267 — wer begeht was, und woran erkennt man es?","loesung":"","thema":"Urkundsdelikte"},{"scenario":"","frage":"Welcher Fall ist Urkundenfälschung §267 — und warum der andere nicht?","loesung":"","thema":"Urkundsdelikte"},{"scenario":"","frage":"Liegt eine Sachbeschädigung vor, obwohl die Wand „nur“ besprüht wurde?","loesung":"","thema":"Sachbeschädigung"},{"scenario":"","frage":"Welcher Tatbestand und welche Einordnung — und was bedeutet „in Brand setzen“ hier?","loesung":"","thema":"Brandstiftung"},{"scenario":"","frage":"Zwei Situationen, zwei verschiedene Unterlassungsdelikte — welche und warum?","loesung":"","thema":"Unterlassene Hilfeleistung"}]}],"cardCount":65,"quizCount":320},{"id":"s34a-5","tg":5,"name":"Unfallverhütungsvorschriften (DGUV)","color":"var(--stack-rose)","meta":{"relevanz":"Mittel","schriftlich":"8 Fragen · 8/100 Punkte","muendlich":"—"},"merksaetze":[],"blocks":[{"n":1,"title":"Gesetzliche Grundlagen","subtitle":"5 Konzepte · 16 Prüfungsfragen","cards":[{"h":"SGB VII & Sozialstaatsprinzip","b":"Arbeitsunfälle, Berufsgenossenschaften, UVVs","detail":null,"visual":null},{"h":"Arbeits- & Wegeunfall","b":"Unfall bei versicherter Tätigkeit; direkter Weg zur Arbeit, erlaubte Umwege","detail":null,"visual":null},{"h":"Berufsgenossenschaften (VBG)","b":"Pflichtmitgliedschaft; VBG für Sicherheitsgewerbe; Aufsichtspersonen","detail":null,"visual":null},{"h":"DGUV & UVVs","b":"Dachverband; erstellt Unfallverhütungsvorschriften","detail":null,"visual":null},{"h":"Relevante Vorschriften","b":"DGUV V1 (Prävention), DGUV V23 (Wach-/Sicherungsdienst), ASR A1.3; §209 SGB VII Geldbuße bis 10.000 €","detail":null,"visual":null}],"quiz":[{"q":"Wer erlässt Unfallverhütungsvorschriften auf Grund welcher gesetzl. Bestimmung?","a":"Berufsgenossenschaft aufgrund des SGB VII","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was steht in der DGUV Vorschrift?","a":"Grundsätze der Prävention; Angabe der Ersthelfer; Keine Ausübung sicherheitswidriger Tätigkeiten; Jährliche Unterweisung in Arbeitsschutz, Persönliche Schutzkleidung (PSA), Bestellung von Sicherheitsbeauftragten etc.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was besagt §4 Dienstanweisung?","a":"- Der Unternehmer hat das Verhalten des Wach- und Sicherungspersonals einschließlich des Weitermeldens von Mängeln und besonderen Gefahren durch Dienstanweisungen zu regeln - Mitarbeiter müssen regelmäßig unterwiesen werden (vor Aufnahe der Tätigkeit und darüber hinaus) - Das sicherheitsgerechte Verhalten bei besonderen Gefahren ist soweit wie möglich zu üben - Versicherte haben die der Arbeitssicherheit dienenden Maßnahmen zu unterstützen - keine Weisungen des Auftraggebers befolgen, die dem Sicherungsauftrag entgegen- stehen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Regelungen gelten gem. DGUV-V1 für den Unternehmer und welche Regelung für den Mitarbeiter ?","a":"Der Unternehmer- hat alle erforderlichen Maßnahmen zur Verhütung von Arbeitsunfällen oder arbeitsbedingten Gesundheitsgefahren zu treffen- er darf keine sicherheitswidrigen Weisungen treffen Der Mitarbeiter- er muss die Anweisungen des Unternehmers befolgen (außer wenn sie rechtswidrig sind = also auch gegen die UVV)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was versteht man unter einen sogenannte D-Arzt?","a":"Das ist der Durchgangsarzt Es handelt sich um einen durch die Berufsgenossenschaft bestellter Arzt, welche Arbeitsunfälle einschätzt / einstuft","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Berufsgenossenschaft ist für den Wach- und Sicherheitsdienst zuständig?","a":"Die Verwaltungsberufsgenossenschaft.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie heißt die für die Bewachung zuständige Berufsgenossenschaft?","a":"Verwaltungsberufsgenossenschaft Abkürzung: VBG","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was bedeutet DGUV?","a":"Deutsche Gesetzliche Unfallversicherung","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Für wen gilt die DGUV Vorschrift \"23\"?","a":"Für den Gewerbetreibenden als auch für die Mitarbeiter privater Sicherheitsunternehmen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was steht in der DGUV §12 über Hunde, was speziell über Fütterung?","a":"Als Diensthunde dürfen nur geprüfte Hunde mit Hundeführern eingesetzt werden. Hunde, die für die Aufgabe nicht geeignet sind, die zur Bösartigkeit neigen oder deren Leistungsstand nicht mehr gegeben ist und dadurch Personen gefährden können, dürfen nicht eingesetzt werden. Nach der Fütterung muss eine Pause von 4 Stunden eigenhalten werden; (Vorbeugung einer Magendrehung)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was steht in der DGUV §13 über Hundezwinger was bedeutet in Bezug darauf","a":"dieses Schild? Werden Hunde in Zwingern oder Zwingeranlagen gehalten, hat der Unternehmer dafür zu sorgen, dass die Zwinger so beschaffen und ausgestattet sind, dass eine Einzelhaltung aller Hunde ermöglicht wird. Der Unternehmer hat dafür zu sorgen, dass an den Zwingern auf das Zutrittsverbot durch das Verbotszeichen \"Zutritt für Unbefugte verboten\" hingewiesen ist. Belegte Zwinger dürfen nur von Hundeführern oder vom Unternehmer beauftragten Personen, die mit dem jeweiligen Hund vertraut sind, betreten werden. Die Säuberung und Instandhaltung von Zwingern darf nur dann durchgeführt werden, wenn diese nicht durch Hunde belegt sind.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Benennen Sie die für die Bewachung zuständigenUnfallverhütungsvorschriften?","a":"DGUV-V 1\t= Grundsätze der Prävention DGUV-V 23\t= Wach- und Sicherungsdienste","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist gemäß DGUV-V23 für Sicherungskräfte verboten?","a":"Das Mitführen von Gas-; Schreckschuss-; & Reizstoffwaffen Der Konsum von Alkohol, Betäubungsmittel oder anderen berauschenden Mitteln (auch bewusstseinsbeeinträchtigende Medikamente) bei Dienst hat Nüchternheit zu herrschen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Dürfen ungeprüfte Hunde in der Bewachung eingesetzt werden?","a":"Ja, aber nur zum Melden und Verbellen(gem. DGUV-V23 = Wahrnehmung- und Meldeaufgaben) !! Die Hunde dürfen keinen direkten Kontakt mit Besuchern oder dergleichen haben !!!","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Zu welcher Maßnahme (gem. DGUV-V1) im Rahmen der Unfallprävention ist der Unternehmer einmal im Jahr verpflichtet?","a":"Allgemeine Unterweisung in die Unfallverhütungsvorschriften.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was steht in der ASR A1.3?","a":"Gebotszeichen, Sicherheitszeichen, Rettungszeichen, Verbotszeichen, Warnzeichen; Flucht- und Rettungswege","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[]},{"n":2,"title":"Erste Hilfe & Prävention","subtitle":"5 Konzepte · 8 Prüfungsfragen","cards":[{"h":"Unterweisung der Versicherten","b":"1x jährlich, Dokumentationspflicht","detail":null,"visual":null},{"h":"Pflichten des Unternehmers","b":"Ersthelfer, Verbandmaterial, Räume, Aushänge, Durchgangsarzt","detail":null,"visual":null},{"h":"Verbandbuch","b":"Erste-Hilfe-Vorfälle dokumentieren; 5 Jahre aufbewahren","detail":null,"visual":null},{"h":"Zahl & Ausbildung der Ersthelfer","b":"2–20: 1 Ersthelfer; >20 Verwaltung 5%, sonst 10%; Fortbildung alle 2 Jahre","detail":null,"visual":null},{"h":"Persönliche Schutzausrüstung (PSA)","b":"PSA-BV; Bereitstellung durch Unternehmer, bestimmungsgemäße Nutzung","detail":null,"visual":null}],"quiz":[{"q":"Was steht in der DGUV Vorschrift?","a":"Grundsätze der Prävention; Angabe der Ersthelfer; Keine Ausübung sicherheitswidriger Tätigkeiten; Jährliche Unterweisung in Arbeitsschutz, Persönliche Schutzkleidung (PSA), Bestellung von Sicherheitsbeauftragten etc.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was besagt der §10 Ausrüstung?","a":"Der Unternehmer hat dafür zu sorgen, dass sich die für das Wach- und Sicherungs- personal erforderlichen Einrichtung, Ausrüstungen und Hilfsmittel in ordnungsgemäßen Zustand befinden und dass das Wach- und Sicherungspersonal in deren Handhabungen unterwiesen sind. Ausrüstungen und Hilfsmittel müssen so beschaffen und angelegt sein, dass die Bewegungsfreiheit, insbesondere die der Hände, nicht mehr als nach den Umständen unvermeidbar beeinträchtigt wird. Der Unternehmer hat dafür zu sorgen, dass der jeweiligen Wach- und Sicherungsaufgabe entsprechendes Schuhwerk von den Versicherten getragen wird. Der Unternehmer hat dafür zu sorgen, dass bei Dunkelheit eingesetztes Wach- und Sicherungspersonal mit leistungsfähigen Handleichten ausgerüstet ist. Die Versichten haben die zur Verfügung gestellten Ausrüstungen und Hilfsmittel bestimmungsgemäß zu benutzen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"§16 An- und Ableinen (Hundezwinger) bei Übernahme?","a":"Die Übernahme und Abgabe des Hundes einschließlich des An- und Ableinens müssen im Zwinger bei geschlossener Tür vorgenommen werden. Bei zulässiger Anbinde Haltung kann die Übernahme und Abgabe auch an den entsprechenden Einrichtungen erfolgen. Eine Übergabe von Person zu Person ist nicht erlaubt. Vor jeder Kontaktaufnahme mit einem Hund haben sich die vom Unternehmer hierzu beauftragten Versicherten in geeigneter Weise davon zu überzeugen, dass der Hund folgsam und nicht aggressiv ist. Andernfalls ist der Direktkontakt zu unterlassen und der Hund nicht einzusetzen. Werden Hunde mit verschiedenen Hundeführern eingesetzt, so ist eine einheitliche Kommandosprache festzulegen und anzuwenden. Die Befestigung der Führleine am Körper des Hundeführers sowie am Fahrrad oder Moped ist untersagt. Eine Hundeführung ohne Führleine darf nur in Objektbereichen erfolgen, in denen eine Begegnung mit Dritten nicht zu erwarten ist. Bei einer Begegnung mit Dritten ist der angeleinte Hund fest an der kurzen Leine so zu führen, dass er Dritte nicht erreichen kann.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Zu welcher Maßnahme (gem. DGUV-V1) im Rahmen der Unfallprävention ist der Unternehmer einmal im Jahr verpflichtet?","a":"Allgemeine Unterweisung in die Unfallverhütungsvorschriften.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Regelungen gelten gem. DGUV-V1 für den Unternehmer und welche Regelung für den Mitarbeiter ?","a":"Der Unternehmer- hat alle erforderlichen Maßnahmen zur Verhütung von Arbeitsunfällen oder arbeitsbedingten Gesundheitsgefahren zu treffen- er darf keine sicherheitswidrigen Weisungen treffen Der Mitarbeiter- er muss die Anweisungen des Unternehmers befolgen (außer wenn sie rechtswidrig sind = also auch gegen die UVV)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wo werden Erste Hilfe Vorfälle festgehalten?","a":"Im Verbandbuch; Aufbewahrung: 5 Jahre","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welchen Verpflichtungen unterliegt der Unternehmer in Bezug auf","a":"Einrichtung zu Ersten Hilfe, Sachmittel und Personal? - Er muss Ersthelfer ausbilden lassen, 2 bis 20 Angestellte 1 Ersthelfer - Verbandsmaterial bereitstellen - geeigneten Raum mit erforderlicher Einrichtung schaffen - Schilder aufhängen wo sich das Verbandmaterial befinden","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wozu ist der Unternehmer verpflichtet, wenn sich Gefahren für den Körper des MA aus einer Tätigkeit ergeben (können)?","a":"Er hat den Mitarbeiter mit angemessener persönlicher Schutzausrüstung (PSA) auszustatten\tBeispiele:\t- Schutzwesten - Sicherheitsschuhe - Helm - Schutzmasken (Atemwege) - . . .","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[]},{"n":3,"title":"Sicherheitskennzeichnung (ASR A1.3)","subtitle":"2 Konzepte · 4 Prüfungsfragen","cards":[{"h":"Sicherheitszeichen","b":"Verbots-, Warn-, Gebots-, Rettungs-, Brandschutzzeichen; Piktogramme","detail":null,"visual":null},{"h":"Flucht- & Rettungspläne","b":"Verhalten im Gefahrenfall, Notausgänge, Feuerlöscher; immer aktuell","detail":null,"visual":null}],"quiz":[{"q":"Was steht in der ASR A1.3?","a":"Gebotszeichen, Sicherheitszeichen, Rettungszeichen, Verbotszeichen, Warnzeichen; Flucht- und Rettungswege","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erklären Sie die Sicherheitszeichen.","a":"- Verbotszeichen, Untersagt das Verhalten, durch das eine Gefahr entstehen kann. - Warnzeichen, Warnt vor einen Risiko oder einer Gefahr - Gebotszeichen, Schreibt ein bestimmtes Verhalten vor - Rettungszeichen, Kennzeichnet Rettungswege und Notausgänge sowie die Erste-Hilfe-Einrichtung - Brandschutzzeichen, Kennzeichnet Standort von Feuermeldern, Feuerlöscheinrichtungen (Was ist das grüne „Männchen“ auf dem Rettungszeichen ? Ein Piktogramm !)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was steht in der DGUV §13 über Hundezwinger was bedeutet in Bezug darauf","a":"dieses Schild? Werden Hunde in Zwingern oder Zwingeranlagen gehalten, hat der Unternehmer dafür zu sorgen, dass die Zwinger so beschaffen und ausgestattet sind, dass eine Einzelhaltung aller Hunde ermöglicht wird. Der Unternehmer hat dafür zu sorgen, dass an den Zwingern auf das Zutrittsverbot durch das Verbotszeichen \"Zutritt für Unbefugte verboten\" hingewiesen ist. Belegte Zwinger dürfen nur von Hundeführern oder vom Unternehmer beauftragten Personen, die mit dem jeweiligen Hund vertraut sind, betreten werden. Die Säuberung und Instandhaltung von Zwingern darf nur dann durchgeführt werden, wenn diese nicht durch Hunde belegt sind.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was wissen Sie über Flucht- und Rettungspläne?","a":"Sie müssen aufgehängt werden, damit der Versicherte weiß: - Wie verhält man sich im Gefahr- und Katastrophenfall - Wo der schnellste Notausgang ist. - Wo der nächste Feuerlöscher hängt - Müssen immer aktuell sein","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[]},{"n":4,"title":"DGUV V23 – Wach- und Sicherungsdienste","subtitle":"8 Konzepte · 18 Prüfungsfragen","cards":[{"h":"Geltungsbereich V23","b":"Objektschutz, Geld-/Werttransport, Revier-/Interventionsdienst, Veranstaltung, Personenschutz; gilt für Unternehmer & Mitarbeiter","detail":null,"visual":null},{"h":"§3 Eignung","b":"Körperlich/geistig geeignet, 18 Jahre, ausgebildet","detail":null,"visual":null},{"h":"§4 Dienstanweisung","b":"Verhalten regeln, Mängel melden, keine sicherheitswidrigen Weisungen befolgen","detail":null,"visual":null},{"h":"§5 Verbot berauschender Mittel","b":"Nüchternheit bei Dienstantritt; Alkohol/Drogen/Medikamente verboten","detail":null,"visual":null},{"h":"§7 Überwachen bei besonderen Gefahren","b":"Totmannschaltung, Kontrollanrufe, Selektivruf","detail":null,"visual":null},{"h":"§9 Objekteinweisung","b":"Einweisung ins Objekt und spezifische Gefahren, auch tagsüber bei Nachtschicht","detail":null,"visual":null},{"h":"§10 Ausrüstung","b":"Ordnungsgemäßer Zustand, Bewegungsfreiheit der Hände, Schuhwerk, Handleuchten","detail":null,"visual":null},{"h":"§11 Brillenträger","b":"Brille sichern oder Ersatzbrille mitführen","detail":null,"visual":null}],"quiz":[{"q":"Was bedeutet §3 Eignung (erforderliche Befähigungen)?","a":"Die Eignung des Sicherheitsmitarbeiter, das er Körperlich und Geistig geeignet ist, 18 Jahre alt ist und für entsprechende Tätigkeiten ausgebildet (besonders befähigt) ist; z.B. Waffensachkunde, Diensthundeführer","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Qualifikationen muss der Gewerbetreibende bei ihnen prüfen, wenn Sie bewaffneten Geldtransport durchführen sollen?","a":"18. Lebensjahr vollendet Eignung & Zuverlässigkeit für den Geld- & Werttransport Führerschein Waffensachkundenachweis mindestens Unterrichtungsnachweis gem. §34a GewO","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was besagt §4 Dienstanweisung?","a":"- Der Unternehmer hat das Verhalten des Wach- und Sicherungspersonals einschließlich des Weitermeldens von Mängeln und besonderen Gefahren durch Dienstanweisungen zu regeln - Mitarbeiter müssen regelmäßig unterwiesen werden (vor Aufnahe der Tätigkeit und darüber hinaus) - Das sicherheitsgerechte Verhalten bei besonderen Gefahren ist soweit wie möglich zu üben - Versicherte haben die der Arbeitssicherheit dienenden Maßnahmen zu unterstützen - keine Weisungen des Auftraggebers befolgen, die dem Sicherungsauftrag entgegen- stehen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was können Sie mir zu Nebentätigkeiten im Wachdienst sagen?","a":"Müssen vorher schriftlich in der Dienstanweisung niedergeschrieben werden Sie dürfen dem Sicherungsauftrag nicht entgegenstehen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Vorgaben gelten bezüglich der Ausrüstung des Wachpersonals?","a":"Gewerbetreibende legt die Ausrüstung (auch eventuelle Bewaffnung) in einer Dienstanweisung fest Der Unternehmer hat die Gefahren und die erforderliche Ausrüstung zu ermitteln (Gefährdungsbeurteilung) Eingesetzte Ausrüstung ist auf Funktionalität und Betriebssicherheit zu prüfenBeispiele:\t- Fahrzeuge müssen verkehrstauglich sein - Ausrüstung muss den Witterungsbedingungen gerecht werden - leistungsfähige Handleuchten müssen eingesetzt werden - Schuhwerk muss einsatzbezogen sein - . . .","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was bedeutet §5 Verbot berauschender Mittel?","a":"Der Genuss von alkoholischen Getränken und die Einnahme andere berauschender Mittel sind während der Dienstzeit verboten. Dies gilt auch für einen angemessenen Zeitraum vor dem Einsatz. Bei Dienstantritt muss Nüchternheit gegeben sein.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist gemäß DGUV-V23 für Sicherungskräfte verboten?","a":"Das Mitführen von Gas-; Schreckschuss-; & Reizstoffwaffen Der Konsum von Alkohol, Betäubungsmittel oder anderen berauschenden Mitteln (auch bewusstseinsbeeinträchtigende Medikamente) bei Dienst hat Nüchternheit zu herrschen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was besagt §7 Überwachen bei besonderen Gefahren?","a":"Der Unternehmer hat sicherzustellen, dass das Wach- und Sicherungspersonal überwacht wird, wenn sich bei Sicherungstätigkeiten besondere Gefahren ergeben. - Ausrüstung der Mitarbeiter mit Totmannschaltung am Funkgerät - Bewegungsmelder (z.B. in der NSL) - Regelmäßige Anrufe oder persönliche Kontrolle; z.B. durch Revierfahrer - Senden eines Selektivrufes der vom Mitarbeiter bestätigt werden muss","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet §9 Objekteinweisung?","a":"- Der Unternehmer hat dafür zu sorgen, dass das Wach- und Sicherungspersonal in das jeweilige zu sichernde Objekt und die spezifischen Gefahren eingewiesen wird. - Die Einweisungen sind zu den Zeiten vorzunehmen, zu denen die Tätigkeit des Wach- und Sicherungspersonal ausgeübt wird. - bei Dauernachtschicht ist auch am Tag einzuweisen um Gefahren vorzubeugen - Der Unternehmer hat dafür zu sorgen, dass für alle Objekte und Objektbereiche, in denen Hunde eingesetzt sind, das Wach- und Sicherungspersonal über das Verhalten bei der Begegnungen mit diesen Hunden unterwiesen wird.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was hat der Unternehmer zu machen, wenn sein Personal Tätigkeiten mit besonderen Gefahren ausübt?","a":"Das Personal muss überwacht werdenBeispiele:\t- Mitarbeiter werden durch Kameras überwacht - Mitarbeiter werden regelmäßig aufgesucht/kontrolliert - Mitarbeiter müssen sich regelmäßig melden - Kontrollgänge werden mit mindestens 02 MA besetzt - . . .","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Regelungen gelten gem. DGUV-V1 für den Unternehmer und welche Regelung für den Mitarbeiter ?","a":"Der Unternehmer- hat alle erforderlichen Maßnahmen zur Verhütung von Arbeitsunfällen oder arbeitsbedingten Gesundheitsgefahren zu treffen- er darf keine sicherheitswidrigen Weisungen treffen Der Mitarbeiter- er muss die Anweisungen des Unternehmers befolgen (außer wenn sie rechtswidrig sind = also auch gegen die UVV)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wozu ist der Unternehmer verpflichtet, wenn sich Gefahren für den Körper des MA aus einer Tätigkeit ergeben (können)?","a":"Er hat den Mitarbeiter mit angemessener persönlicher Schutzausrüstung (PSA) auszustatten\tBeispiele:\t- Schutzwesten - Sicherheitsschuhe - Helm - Schutzmasken (Atemwege) - . . .","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wann sind Sie als Mitarbeiter in ein Objekt einzuweisen ?","a":"Vor Antritt des ersten Dienstes Jeweils zu der Zeit zu der ich als Mitarbeiter auch arbeiten soll\t(Tagschicht = Einweisung am Tage)\t(Nachtschicht = Einweisung bei Nacht, wenn möglich auch bei Tag)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was besagt der §10 Ausrüstung?","a":"Der Unternehmer hat dafür zu sorgen, dass sich die für das Wach- und Sicherungs- personal erforderlichen Einrichtung, Ausrüstungen und Hilfsmittel in ordnungsgemäßen Zustand befinden und dass das Wach- und Sicherungspersonal in deren Handhabungen unterwiesen sind. Ausrüstungen und Hilfsmittel müssen so beschaffen und angelegt sein, dass die Bewegungsfreiheit, insbesondere die der Hände, nicht mehr als nach den Umständen unvermeidbar beeinträchtigt wird. Der Unternehmer hat dafür zu sorgen, dass der jeweiligen Wach- und Sicherungsaufgabe entsprechendes Schuhwerk von den Versicherten getragen wird. Der Unternehmer hat dafür zu sorgen, dass bei Dunkelheit eingesetztes Wach- und Sicherungspersonal mit leistungsfähigen Handleichten ausgerüstet ist. Die Versichten haben die zur Verfügung gestellten Ausrüstungen und Hilfsmittel bestimmungsgemäß zu benutzen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"§18 Ausrüstung mit Schusswaffen, §20 Trageeinrichtung?","a":"$18 Der Unternehmer hat unter Beachtung der waffenrechtlichen Bestimmungen sicher zu stellen, dass eine Ausrüstung des Wach- und Sicherungspersonals mit Schusswaffen nur dann erfolgt, wenn er dies ausdrücklich anordnet. Es dürfen nur Versicherte mit Schusswaffen ausgerüstet werden, die nach dem Waffenrecht zuverlässig, geeignet und sachkundig sowie an den Waffen ausgebildet sind. Der Unternehmer hat sicherzustellen, dass Versicherte, die Träger von Schusswaffen nach Absatz 1 sind, regelmäßig an Schießübungen teilnehmen und ihre Schießfertigkeit sowie Sachkunde nach dem Waffenrecht ihm oder einem Sachkundigen nachweisen. §20 Schusswaffen müssen in geeigneten Trageeinrichtungen geführt werden. Das Abgleiten oder Herausfallen der Waffe muss durch eine Sicherung verhindert sein. Munition darf nicht lose mitgeführt werden. Außer bei drohender Gefahr darf sich keine Patrone vor dem Lauf befinden. Dies gilt nicht, wenn durch konstruktive Maßnahmen sichergestellt ist, dass sich bei entspanntem Hahn kein Schuss lösen kann.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Geldtransport durch eine Person, was ist zu beachten?","a":"Der Unternehmer darf nur solche Personen einsetzten, die folgende Voraussetzungen erfüllen: - Zivilkleidung tragen - nicht als Geldbote zu identifizieren sind - neutrales Fahrzeug - der Anreiz zu Überfällen durch technische Ausrüstungen, die für Außenstehende deutlich erkennbar sind, nachhaltig verringert wird - ausschließlich Hartgeld transportiert wird und dies auch für Außenstehende durch Transportverlauf und Transportabwicklung erkennbar ist.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was besagt §11 für Brillenträger?","a":"Versicherte, die bei Wach- und Sicherungsaufgaben zur Korrektur ihres Sehvermögens eine Brille tragen müssen, haben diese gegen Verlieren zu sichern oder eine Ersatzbrille mitzuführen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was müssen Brillenträger im Dienst beachten?","a":"Sie müssen ihre Brille gegen verlieren sichern (z.B.: Brillenband) oder sie müssen eine Ersatzbrille dabei haben","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[{"scenario":"Ein Wachmann tritt seinen Nachtdienst an. Er hat „zum Aufwärmen“ zwei Bier getrunken und trägt offene Sportschuhe.","frage":"Gegen welche UVV-Pflichten verstößt er?","loesung":"Verstoß gegen DGUV V23 §5 (Verbot berauschender Mittel – Nüchternheit bei Dienstantritt) und gegen die Pflicht zu geeigneter Ausrüstung/Schuhwerk (§10). Der Unternehmer darf ihn so nicht einsetzen."}]},{"n":5,"title":"Diensthunde","subtitle":"4 Konzepte · 14 Prüfungsfragen","cards":[{"h":"§12 Hunde & Fütterung","b":"Nur geprüfte Hunde mit Führer; 4 Std. Pause nach Fütterung (Magendrehung)","detail":null,"visual":null},{"h":"Ungeprüfte Hunde","b":"Nur Wahrnehmungs-/Meldeaufgaben unter Kontrolle","detail":null,"visual":null},{"h":"§13 Hundezwinger","b":"Einzelhaltung, Zutrittsverbotszeichen, nur vertraute Personen","detail":null,"visual":null},{"h":"§15–17 Hundeführer/Transport","b":"Befähigungsnachweis, An-/Ableinen, Transport mit Abtrennung","detail":null,"visual":null}],"quiz":[{"q":"Was bedeutet §3 Eignung (erforderliche Befähigungen)?","a":"Die Eignung des Sicherheitsmitarbeiter, das er Körperlich und Geistig geeignet ist, 18 Jahre alt ist und für entsprechende Tätigkeiten ausgebildet (besonders befähigt) ist; z.B. Waffensachkunde, Diensthundeführer","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet §9 Objekteinweisung?","a":"- Der Unternehmer hat dafür zu sorgen, dass das Wach- und Sicherungspersonal in das jeweilige zu sichernde Objekt und die spezifischen Gefahren eingewiesen wird. - Die Einweisungen sind zu den Zeiten vorzunehmen, zu denen die Tätigkeit des Wach- und Sicherungspersonal ausgeübt wird. - bei Dauernachtschicht ist auch am Tag einzuweisen um Gefahren vorzubeugen - Der Unternehmer hat dafür zu sorgen, dass für alle Objekte und Objektbereiche, in denen Hunde eingesetzt sind, das Wach- und Sicherungspersonal über das Verhalten bei der Begegnungen mit diesen Hunden unterwiesen wird.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was steht in der DGUV §12 über Hunde, was speziell über Fütterung?","a":"Als Diensthunde dürfen nur geprüfte Hunde mit Hundeführern eingesetzt werden. Hunde, die für die Aufgabe nicht geeignet sind, die zur Bösartigkeit neigen oder deren Leistungsstand nicht mehr gegeben ist und dadurch Personen gefährden können, dürfen nicht eingesetzt werden. Nach der Fütterung muss eine Pause von 4 Stunden eigenhalten werden; (Vorbeugung einer Magendrehung)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Dürfen auch ungeprüfte Hunde zur Bewachungsaufgaben eingesetzt werden und wenn","a":"ja was ist zu beachten? Ja. Ungeprüfte Hunde dürfen nur zu Wahrnehmungs- und Meldeaufgaben eingesetzt werden, wenn der Hundeführer seinen Hund unter Kontrolle hat. Eine Überforderung der Hunde durch Ausbildung und Einsatz ist zu vermeiden","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was steht in der DGUV §13 über Hundezwinger was bedeutet in Bezug darauf","a":"dieses Schild? Werden Hunde in Zwingern oder Zwingeranlagen gehalten, hat der Unternehmer dafür zu sorgen, dass die Zwinger so beschaffen und ausgestattet sind, dass eine Einzelhaltung aller Hunde ermöglicht wird. Der Unternehmer hat dafür zu sorgen, dass an den Zwingern auf das Zutrittsverbot durch das Verbotszeichen \"Zutritt für Unbefugte verboten\" hingewiesen ist. Belegte Zwinger dürfen nur von Hundeführern oder vom Unternehmer beauftragten Personen, die mit dem jeweiligen Hund vertraut sind, betreten werden. Die Säuberung und Instandhaltung von Zwingern darf nur dann durchgeführt werden, wenn diese nicht durch Hunde belegt sind.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"§15 Hundeführer, Ausbildung, Inhalte?","a":"Als Hundeführer dürfen Versicherte eingesetzt werden, die entsprechend unterwiesen worden sind und dem Unternehmer Ihre Befähigung nachgewiesen haben. Der Unternehmer hat dafür zu sorgen, dass ihm die Befähigung zum Hundeführer regelmäßig nachgewiesen wird. Bei nicht mehr ausreichender Befähigung ist die Befugnis zum führen von Hunden zu entziehen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"§16 An- und Ableinen (Hundezwinger) bei Übernahme?","a":"Die Übernahme und Abgabe des Hundes einschließlich des An- und Ableinens müssen im Zwinger bei geschlossener Tür vorgenommen werden. Bei zulässiger Anbinde Haltung kann die Übernahme und Abgabe auch an den entsprechenden Einrichtungen erfolgen. Eine Übergabe von Person zu Person ist nicht erlaubt. Vor jeder Kontaktaufnahme mit einem Hund haben sich die vom Unternehmer hierzu beauftragten Versicherten in geeigneter Weise davon zu überzeugen, dass der Hund folgsam und nicht aggressiv ist. Andernfalls ist der Direktkontakt zu unterlassen und der Hund nicht einzusetzen. Werden Hunde mit verschiedenen Hundeführern eingesetzt, so ist eine einheitliche Kommandosprache festzulegen und anzuwenden. Die Befestigung der Führleine am Körper des Hundeführers sowie am Fahrrad oder Moped ist untersagt. Eine Hundeführung ohne Führleine darf nur in Objektbereichen erfolgen, in denen eine Begegnung mit Dritten nicht zu erwarten ist. Bei einer Begegnung mit Dritten ist der angeleinte Hund fest an der kurzen Leine so zu führen, dass er Dritte nicht erreichen kann.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"§17 Transport von Hunden?","a":"Der Unternehmer hat dafür zu sorgen, dass Kraftfahrzeuge für den Transport von Hunden mit einer Abtrennung zwischen Transportraum und Fahrgastbereich ausgerüstet sind. Werden mehrere Hunde gleichzeitig in einem Fahrzeug transportiert, muss zusätzlich eine Trennung der Hunde voneinander möglich sein und dann erfolgen, wenn das Verhalten der Hunde ihren Transport zusammen in einem Transportraum nicht zulässt.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Dürfen ungeprüfte Hunde in der Bewachung eingesetzt werden?","a":"Ja, aber nur zum Melden und Verbellen(gem. DGUV-V23 = Wahrnehmung- und Meldeaufgaben) !! Die Hunde dürfen keinen direkten Kontakt mit Besuchern oder dergleichen haben !!!","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Geldtransport durch eine Person, was ist zu beachten?","a":"Der Unternehmer darf nur solche Personen einsetzten, die folgende Voraussetzungen erfüllen: - Zivilkleidung tragen - nicht als Geldbote zu identifizieren sind - neutrales Fahrzeug - der Anreiz zu Überfällen durch technische Ausrüstungen, die für Außenstehende deutlich erkennbar sind, nachhaltig verringert wird - ausschließlich Hartgeld transportiert wird und dies auch für Außenstehende durch Transportverlauf und Transportabwicklung erkennbar ist.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Geld- und Werttransport welche Transportsicherungen gibt es und","a":"wie funktionieren diese? Geldkoffer ist durch ein Tintenmodul gesichert; Beim Loslassen des Koffers wird ein Tintenmodul freigesetzt und das Geld eingefärbt (unbrauchbar gemacht)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie müssen eigentlich Geldtransportfahrzeuge gekennzeichnet sein, Identifikation","a":"aus der Luft? Geldtransportfahrzeuge müssen im Dachbereich so gekennzeichnet sein, dass eine eindeutige Identifikation aus der Luft möglich ist. Eine eindeutige Identifikation ist möglich bei mindestens zwei firmenspezifischen Buchstaben in Verbindung mit mehrstelligen Ziffern, Schriftgröße von ca. 420 mm und dem \"Fliegersichtzeichen\"","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Qualifikationen muss der Gewerbetreibende bei ihnen prüfen, wenn Sie bewaffneten Geldtransport durchführen sollen?","a":"18. Lebensjahr vollendet Eignung & Zuverlässigkeit für den Geld- & Werttransport Führerschein Waffensachkundenachweis mindestens Unterrichtungsnachweis gem. §34a GewO","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Darf ein Geld- und Werttransport in zivil erfolgen?","a":"Ja. Dann darf der Transport auch durch eine Person erfolgen","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[]},{"n":6,"title":"Schusswaffen & Geldtransport (UVV)","subtitle":"5 Konzepte · 13 Prüfungsfragen","cards":[{"h":"§18 Ausrüstung mit Schusswaffen","b":"Nur auf ausdrückliche Anordnung; zuverlässig, geeignet, sachkundig","detail":null,"visual":null},{"h":"§20 Trageeinrichtung","b":"Holster, Sicherung gegen Herausfallen; Munition nicht lose","detail":null,"visual":null},{"h":"§21/§22 Übergabe & Aufbewahrung","b":"Nur entladen übergeben; Stahlblechschrank; Schießfertigkeit 4x/Jahr","detail":null,"visual":null},{"h":"Schreck-/Gasschusswaffen","b":"Verboten im Dienst – trügerisches Sicherheitsgefühl","detail":null,"visual":null},{"h":"Geldtransport","b":"2 Personen oder Ausnahmen (Zivilkleidung, neutrales Fahrzeug, Hartgeld); Dachkennzeichnung","detail":null,"visual":null}],"quiz":[{"q":"§18 Ausrüstung mit Schusswaffen, §20 Trageeinrichtung?","a":"$18 Der Unternehmer hat unter Beachtung der waffenrechtlichen Bestimmungen sicher zu stellen, dass eine Ausrüstung des Wach- und Sicherungspersonals mit Schusswaffen nur dann erfolgt, wenn er dies ausdrücklich anordnet. Es dürfen nur Versicherte mit Schusswaffen ausgerüstet werden, die nach dem Waffenrecht zuverlässig, geeignet und sachkundig sowie an den Waffen ausgebildet sind. Der Unternehmer hat sicherzustellen, dass Versicherte, die Träger von Schusswaffen nach Absatz 1 sind, regelmäßig an Schießübungen teilnehmen und ihre Schießfertigkeit sowie Sachkunde nach dem Waffenrecht ihm oder einem Sachkundigen nachweisen. §20 Schusswaffen müssen in geeigneten Trageeinrichtungen geführt werden. Das Abgleiten oder Herausfallen der Waffe muss durch eine Sicherung verhindert sein. Munition darf nicht lose mitgeführt werden. Außer bei drohender Gefahr darf sich keine Patrone vor dem Lauf befinden. Dies gilt nicht, wenn durch konstruktive Maßnahmen sichergestellt ist, dass sich bei entspanntem Hahn kein Schuss lösen kann.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wo werden Erste Hilfe Vorfälle festgehalten?","a":"Im Verbandbuch; Aufbewahrung: 5 Jahre","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"§21 Übergabe von Schusswaffen, §22 Aufbewahrung von Schusswaffen,","a":"wer ist Verantwortlich, §21: - Nachweis der Schießfertigkeit (Prüfung wie oft im Jahr)? - Schusswaffen dürfen nur in entladenem Zustand übergeben werden. - Der Übernehmende hat sich sofort vom Ladezustand der Waffe zu überzeugen und diese auf augenfällige Mängel zu kontrollieren. - Bei Feststellung von Mängeln darf die Waffe nicht geführt werden. Vor einer Wiederverwendung ist sie einer sachkundigen Instandsetzung zuzuleiten. - Beim Laden und Entladen von Schusswaffen müssen diese an sicherem Ort auf eine geeignete Kugelfangeinrichtung gerichtet sein. §22: Der Unternehmer hat dafür zu sorgen, dass für die Aufbewahrung von Schusswaffen und Munition zumindest Stahlblechschränke mit Sicherheitsschloss (lt. WaffG mind. Waffenschrank DIN 1143 - 1) oder entsprechend sichere Einrichtungen vorhanden sind, die eine getrennte Unterbringung von Waffen und Munition ermöglichen und Schutz gegen Abhandenkommen oder unbefugten Zugriff gewährleisten. Die Aufbewahrung von Schusswaffen und Munition muss in verschlossenen Einrichtungen erfolgen. Schusswaffen dürfen nur im entladenen Zustand aufbewahrt werden. Nachweis der Schießfertigkeit: Der Unternehmer hat sicherzustellen, dass Versicherte, die Träger von Schusswaffen sind, regelmäßig an Schießübungen teilnehmen und ihre Schießfertigkeit sicherzustellen. Viermal im Jahr, alle Drei Monate.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was müssen Sie als Schusswaffenträger gem. UVVregelmäßig nachweisen und wie oft?","a":"Regelmäßige Schießübungen = Quartalsweise (alle drei Monate)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Erläutere aus der BewachV, Aufbewahrung von Schusswaffen","a":"Aufbewahrung in einem geeigneten Behältnis DIN 1143-1 Grad 0 (bis zu 5 Kurzwaffen) oder Grad 1 (unbegrenzte Anzahl von Kurzwaffen). Kein Zugriff Dritter oder abhandenkommen muss gewährleistet sein. Unternehmer ist verantwortlich!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wer ist für die sichere Aufbewahrung von Waffen verantwortlich?","a":"Der Gewerbetreibende(Aufbewahrung, Ausgabe und Rücknahme)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Regelung gilt für Schreckschuss- oder Gasschusswaffen?","a":"Das Verbot des Bereithaltens und Führens von Schreck- oder Gas-Schusswaffen bei der Durchführung von Wach- und Sicherungsaufgaben betrifft auch entsprechende Reizstoff - oder Signalschusswaffen sowie sonstige schusswaffenähnliche Gegenstände, da sie ein trügerisches Sicherheitsgefühl vermitteln und ihr Einsatz bei Konfrontationen mit schusswaffentragenden Tätern zu einer extremen Gefährdung ohne ausreichende Selbstverteidigungsmöglichkeit führt.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist gemäß DGUV-V23 für Sicherungskräfte verboten?","a":"Das Mitführen von Gas-; Schreckschuss-; & Reizstoffwaffen Der Konsum von Alkohol, Betäubungsmittel oder anderen berauschenden Mitteln (auch bewusstseinsbeeinträchtigende Medikamente) bei Dienst hat Nüchternheit zu herrschen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Geldtransport durch eine Person, was ist zu beachten?","a":"Der Unternehmer darf nur solche Personen einsetzten, die folgende Voraussetzungen erfüllen: - Zivilkleidung tragen - nicht als Geldbote zu identifizieren sind - neutrales Fahrzeug - der Anreiz zu Überfällen durch technische Ausrüstungen, die für Außenstehende deutlich erkennbar sind, nachhaltig verringert wird - ausschließlich Hartgeld transportiert wird und dies auch für Außenstehende durch Transportverlauf und Transportabwicklung erkennbar ist.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Geld- und Werttransport welche Transportsicherungen gibt es und","a":"wie funktionieren diese? Geldkoffer ist durch ein Tintenmodul gesichert; Beim Loslassen des Koffers wird ein Tintenmodul freigesetzt und das Geld eingefärbt (unbrauchbar gemacht)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie müssen eigentlich Geldtransportfahrzeuge gekennzeichnet sein, Identifikation","a":"aus der Luft? Geldtransportfahrzeuge müssen im Dachbereich so gekennzeichnet sein, dass eine eindeutige Identifikation aus der Luft möglich ist. Eine eindeutige Identifikation ist möglich bei mindestens zwei firmenspezifischen Buchstaben in Verbindung mit mehrstelligen Ziffern, Schriftgröße von ca. 420 mm und dem \"Fliegersichtzeichen\"","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Qualifikationen muss der Gewerbetreibende bei ihnen prüfen, wenn Sie bewaffneten Geldtransport durchführen sollen?","a":"18. Lebensjahr vollendet Eignung & Zuverlässigkeit für den Geld- & Werttransport Führerschein Waffensachkundenachweis mindestens Unterrichtungsnachweis gem. §34a GewO","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Darf ein Geld- und Werttransport in zivil erfolgen?","a":"Ja. Dann darf der Transport auch durch eine Person erfolgen","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[]}],"cardCount":29,"quizCount":73},{"id":"s34a-6","tg":6,"name":"Sicherheitstechnik","color":"var(--stack-pink)","meta":{"relevanz":"—","schriftlich":"—","muendlich":"—","hinweis":"In den DBA-Lehrfolien nicht als eigenes Kapitel enthalten – Struktur aus den mündlichen Prüfungsfragen abgeleitet."},"merksaetze":[],"blocks":[{"n":1,"title":"Grundlagen & mechanische Sicherung","subtitle":"6 Konzepte · 16 Prüfungsfragen","cards":[{"h":"Drei Säulen der Sicherheitstechnik","b":"Mechanische Sicherung, elektronische Sicherung, Organisation","detail":{"titel":"Die drei Säulen der Sicherheitstechnik","kat":"Grundlagen","katCls":"org","merksatz":"Sicherheit entsteht erst im Zusammenspiel von Mechanik, Elektronik sowie organisatorisch-personellen Maßnahmen – keine Säule trägt allein.","funktion":["Mechanische Grundsicherung: Hindernisse, die den Täter körperlich aufhalten – Zäune, Türen, Fenster, Schlösser, Tresore.","Elektronische Überwachung: Anlagen, die ein Eindringen melden oder erschweren – Einbruch-, Brand- und Überfallmeldeanlagen, Video, Zutrittskontrolle.","Organisatorisch & personell: die Regeln UND der Mensch – Dienstanweisungen, Schließordnung, Streifenpläne, Alarmverfolgung und das Wachpersonal, das sie umsetzt und im Alarmfall eingreift."],"schutzziel":"Ein Angreifer soll an jeder Säule Zeit und Aufwand verlieren: Mechanik hält auf, Elektronik meldet, Organisation und Personal reagieren.","kennwerte":[{"l":"Säule 1","v":"Mechanische Grundsicherung"},{"l":"Säule 2","v":"Elektronische Überwachung"},{"l":"Säule 3","v":"Organisatorisch – Personell"}],"begriffe":["Detektion = das Erkennen und Melden einer Gefahr (Aufgabe der Elektronik).","Intervention = das Eingreifen nach einer Meldung (Aufgabe der organisatorisch-personellen Säule)."],"abgrenzung":["Mechanik wirkt auch ohne Strom und ohne Personal – sie ist die Grundlage, auf der die anderen Säulen aufbauen.","Die dritte Säule hat zwei Seiten: organisatorisch (die Regel – wer reagiert wann und wie?) und personell (der Mensch, der es ausführt). Der beste Alarmverfolgungsplan nützt nichts ohne jemanden, der losgeht.","Eine Meldeanlage allein verhindert keinen Einbruch; sie meldet nur. Ohne Mechanik (Verzögerung) und ohne organisatorisch-personelle Reaktion bleibt die Meldung wirkungslos."],"praxis":["Als Wachkraft bist du Teil der dritten Säule – der organisatorisch-personellen. Auch die beste Technik nützt nichts, wenn niemand auf den Alarm reagiert.","Bei der Objektbegehung prüfst du alle drei: Sind Türen und Fenster zu (Mechanik)? Sind Melder scharf (Elektronik)? Stimmen Schließordnung, Streifenplan und die Reaktion (organisatorisch & personell)?"]},"visual":null},{"h":"Widerstandszeitwert & Interventionszeit","b":"Zeit zum Überwinden der Hindernisse vs. Anfahrtszeit des Alarmfahrers","detail":{"titel":"Widerstandszeitwert & Interventionszeit","kat":"Grundprinzip","katCls":"mech","merksatz":"Die Mechanik muss länger standhalten, als die Hilfe braucht, um da zu sein – sonst war alles umsonst.","funktion":["Widerstandszeitwert: die Zeit, die ein Täter mit festgelegtem Werkzeug braucht, um eine Barriere zu überwinden (z. B. rund 3 Minuten bei RC 2).","Interventionszeit: die Zeit von der Alarmauslösung bis zum Eintreffen der Eingreifkräfte (Wachdienst, Polizei) am Objekt.","Goldene Regel: Widerstandszeit muss größer sein als die Interventionszeit – die Summe der Hindernisse muss die Anfahrt überdauern."],"schutzziel":"Der Täter soll gestellt werden, bevor er sein Ziel erreicht – die Mechanik kauft der Intervention die nötige Zeit.","kennwerte":[{"l":"Widerstandszeit","v":"Täter überwindet das Hindernis"},{"l":"Interventionszeit","v":"Alarm → Eingreifkraft vor Ort"},{"l":"Faustregel","v":"Widerstand > Intervention"}],"begriffe":["Eingreif-/Interventionskräfte = Wachdienst (NSL-Streife) oder Polizei, die nach dem Alarm anfahren.","Verzögerungswirkung = der Sinn jeder mechanischen Barriere: nicht ‚unüberwindbar‘, sondern ‚lange genug‘."],"abgrenzung":["Die Widerstandszeit ist eine Eigenschaft der Mechanik (Tür, Fenster, Tresor). Die Interventionszeit ist eine Eigenschaft der Organisation (Anfahrt).","Kein Hindernis ist absolut sicher – jedes lässt sich überwinden. Entscheidend ist allein, ob es lange genug hält."],"praxis":["Liegt das Objekt weit von Polizei oder NSL entfernt, ist die Interventionszeit lang – dann braucht es entsprechend höhere Widerstandsklassen.","Mehrere Barrieren hintereinander (Zaun + Tür + Tresorraum) addieren ihre Widerstandszeiten – das nennt man Staffelung oder Sicherheitszonen."]},"visual":null},{"h":"Zaunanlagen","b":"Zaunarten, Sicherheitskriterien, Kronensicherung, Schwachstellen","detail":{"titel":"Zaunanlagen","kat":"Mechanisch","katCls":"mech","merksatz":"Der Zaun ist die erste Linie: Er zieht eine klare Grenze, verzögert das Eindringen und lenkt Besucher zum Eingang.","funktion":["Abgrenzung: macht die Grundstücksgrenze sichtbar und rechtlich klar (Hausrecht).","Verzögerung: erschwert und verlangsamt das Überwinden – je nach Höhe, Material und Übersteigschutz.","Leitwirkung: lenkt Personen und Fahrzeuge zur kontrollierten Zufahrt oder Pforte."],"schutzziel":"Unbefugte fernhalten – oder sie zumindest aufhalten und sichtbar machen, dass hier eine Grenze überschritten wird.","kennwerte":[{"l":"Wirksame Höhe","v":"i. d. R. ≥ 2,50 m gegen Übersteigen"},{"l":"Kronensicherung","v":"Stachel-/NATO-Draht oder Spitzen oben"},{"l":"Untergrabschutz","v":"Fundament oder Bodenanker unten"}],"begriffe":["Kronensicherung = oberer Abschluss als Übersteigschutz, z. B. Y-Ausleger mit Stacheldraht oder S-Draht (NATO-Draht).","Stabmattenzaun = stabiler als Maschendraht, schwer durchzuschneiden, mit guter Durchsicht."],"abgrenzung":["Maschendraht ist billig, aber leicht aufzuschneiden – Stabmatten- oder Gittermattenzäune bieten deutlich mehr Widerstand.","Ein Zaun ist Sicht- und Hindernisbarriere, aber keine Meldeanlage – erst mit Zaundetektion (Sensorik) wird ein Übersteigen auch gemeldet."],"praxis":["Typische Schwachstellen, die du bei der Streife prüfst: untergraben, aufgeschnitten, hinterstellte Gegenstände als Steighilfe (Container, Paletten), zugewachsene Stellen.","Tore sind die schwächste Stelle des Zauns – prüfe Verschluss, Scharniere und ob das Tor wirklich abgeschlossen und nicht nur angelehnt ist."]},"visual":null},{"h":"Schranken & Barrieren","b":"Kontrolle von Personen/Fahrzeugen vs. Schutz gegen Angriffe","detail":{"titel":"Schranken & Barrieren","kat":"Mechanisch","katCls":"mech","merksatz":"Schranke heißt Kontrolle, Poller heißt Schutz: Das eine regelt den Verkehr, das andere stoppt den Angriff.","funktion":["Schranken und Drehkreuze: regeln und vereinzeln den Zu- und Abgang von Personen und Fahrzeugen an der Kontrollstelle.","Poller, Sperren und Durchfahrtssperren: halten Fahrzeuge physisch auf – bis hin zur Anschlagsabwehr (Überfahrschutz).","Vereinzelung: Schleusen und Drehsperren lassen nur eine Person pro Berechtigung durch – kein Mitschlüpfen."],"schutzziel":"Den Durchgang kontrollierbar machen (wer darf rein?) und unberechtigte oder gefährliche Durchfahrten verhindern.","kennwerte":[{"l":"Schranke","v":"Verkehrslenkung, kein Angriffsschutz"},{"l":"Poller (fest/versenkbar)","v":"Fahrzeug- und Anprallschutz"},{"l":"Drehkreuz/Schleuse","v":"Vereinzelung von Personen"}],"begriffe":["Vereinzelung = sicherstellen, dass pro Berechtigung nur eine Person passiert (Schutz gegen Tailgating bzw. Mitschlüpfen).","Überfahr-/Anprallschutz = Sperren, die ein Fahrzeug – etwa als Waffe bei Anschlägen – aufhalten."],"abgrenzung":["Eine normale Schlagbaum-Schranke hält kein Fahrzeug auf – sie zerbricht. Gegen Durchbrechen braucht es Poller oder Betonsperren.","Drehkreuz (vereinzelt Personen) ist nicht gleich Schranke (regelt Fahrzeuge) ist nicht gleich Poller (stoppt Fahrzeuge mit Gewalt)."],"praxis":["An der Pforte ist die Schranke nur so gut wie deine Kontrolle: Wer winkt durch, wer prüft Ausweise? Technik ersetzt die Sichtkontrolle nicht.","Achte auf Mitschlüpfen am Drehkreuz und auf Fahrzeuge, die dicht auffahren, um mit einem Berechtigten zusammen durchzukommen."]},"visual":null},{"h":"Türen & Schutzbeschlag","b":"Bauteile, Schwachstellen, Fluchttüren, Schutzbeschlag","detail":{"titel":"Türen & Schutzbeschlag","kat":"Mechanisch","katCls":"mech","merksatz":"Eine Tür ist nur so stark wie ihr schwächstes Teil – Blatt, Zarge, Band, Schloss und Beschlag müssen zusammenpassen.","funktion":["Türblatt und Zarge (Rahmen): tragen die Last des Angriffs; eine starke Tür in schwacher Zarge bricht trotzdem aus.","Schloss und Schließblech: der Verriegelungspunkt – bei höheren Klassen mehrfach verriegelt.","Bänder (Scharniere) und Bandseitensicherung: gegen Aushebeln auf der Bandseite.","Schutzbeschlag: schützt den Schließzylinder vor Abdrehen, Abbrechen und Ziehen (Kernziehschutz)."],"schutzziel":"Das Eindringen über die Tür verzögern und die typischen Angriffspunkte – Zylinder, Bandseite, Schloss – gezielt sichern.","kennwerte":[{"l":"Norm","v":"DIN EN 1627 (Widerstandsklassen RC)"},{"l":"Schwachpunkt 1","v":"Zylinder → Schutzbeschlag/Ziehschutz"},{"l":"Schwachpunkt 2","v":"Bandseite → Bandsicherung"}],"begriffe":["Schutzbeschlag = verstärkter Türbeschlag, oft mit Zylinderabdeckung, der den Schließzylinder vor Aufbruch schützt.","Mehrfachverriegelung = Schloss, das an mehreren Punkten (oben, Mitte, unten) gleichzeitig verriegelt.","Kernziehschutz = verhindert das gewaltsame Herausziehen des Zylinderkerns."],"abgrenzung":["Fluchttür und Sicherheitstür unterscheiden sich in der Richtung: Eine Fluchttür muss sich ohne Hilfsmittel in Fluchtrichtung öffnen lassen – Schutz gegen außen darf die Flucht nach innen nie behindern.","Ein teurer Zylinder nützt nichts ohne Schutzbeschlag – sonst wird er einfach abgedreht oder gezogen."],"praxis":["Bei der Schließrunde prüfst du: wirklich verschlossen (nicht nur zugezogen)? Beschlag fest? Bandseite intakt? Kein Keil oder Türstopper, der das Schließen verhindert?","Häufiger Realfund: eine Brandschutztür, mit einem Keil offengehalten – das hebelt Einbruch- und Brandschutz zugleich aus."]},"visual":null},{"h":"Fenster-Widerstandswerte","b":"Durchwurf-, Durchbruch-, Durchschuss-, Explosionshemmung; ESG/VSG","detail":{"titel":"Fenster-Widerstandswerte","kat":"Mechanisch","katCls":"mech","merksatz":"Beim Glas zählt nicht ‚kaputt oder nicht‘, sondern wie lange und gegen was es standhält – vom Steinwurf bis zum Beschuss.","funktion":["Angriffhemmende Verglasung wird nach der Art der Belastung eingeteilt: Durchwurf, Durchbruch, Durchschuss, Sprengwirkung.","Durchwurfhemmung (P1A–P5A): hält Steinwürfen und Schlägen eine festgelegte Anzahl Treffer stand.","Durchbruchhemmung (P6B–P8B): widersteht dem gezielten Durchschlagen mit Axt oder Beil über viele Schläge.","Durchschusshemmung (BR) und Sprengwirkungshemmung (ER/SG): gegen Beschuss bzw. Explosionsdruck."],"schutzziel":"Die Glasfläche als Schwachstelle so verzögern, dass sie zur echten Barriere wird – passend zur Bedrohung (Vandalismus, Einbruch, Beschuss).","kennwerte":[{"l":"Durchwurfhemmung","v":"P1A – P5A (Wurf/Schlag)"},{"l":"Durchbruchhemmung","v":"P6B – P8B (Axt/Beil)"},{"l":"Durchschuss/Sprengung","v":"BR (Beschuss) · ER/SG (Explosion)"}],"begriffe":["ESG (Einscheibensicherheitsglas): vorgespannt, zerfällt bei Bruch in stumpfe Krümel – Verletzungsschutz, aber kein Einbruchschutz.","VSG (Verbundsicherheitsglas): mehrere Scheiben mit reißfester Folie verklebt – bleibt nach dem Bruch zusammen und wirkt durchwurf- und durchbruchhemmend.","Sicherheitsfolie: nachträglich aufgebracht, erhöht den Widerstandswert und schützt vor Splittern."],"abgrenzung":["ESG schützt Personen vor Schnittverletzungen, ist aber leicht zu überwinden – VSG ist der eigentliche Einbruch- und Durchwurfschutz.","Die P-Klassen (A = Wurf, B = Schlag/Durchbruch) sagen, gegen welche Angriffsart das Glas geprüft ist – eine hohe Wurfklasse bedeutet nicht automatisch durchschusssicher."],"praxis":["Erdgeschoss- und Kellerfenster sind klassische Einstiegsstellen – prüfe bei der Runde, ob sie verschlossen und nicht nur gekippt sind.","Ein gekipptes Fenster gilt versicherungsrechtlich oft als ‚offen‘ – ein häufiger und teurer Fehler, den du melden solltest."]},"visual":null}],"quiz":[{"q":"Welche Aussagen zu einbruchhemmenden Türen sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Nachrüstung von Türen ist unzulässig. Die einbruchhemmende Wirkung muss werksseitig hergestellt werden","c":false},{"t":"Sie erschweren nach Widerstandsklassen Einbrüche mit Werkzeugen oder körperlicher Gewalt","c":true},{"t":"Sie können in Holz, Kunststoff oder Metall ausgeführt sein","c":true},{"t":"Sie müssen für den Einbau von Einbruchmeldetechnik vorgerüstet sein","c":false}]},{"q":"Was bewirkt die nachträgliche Montage von Sicherheitsfolien auf Glasflächen?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Schallschutz","c":false},{"t":"Erhöhung des Widerstandswertes","c":true},{"t":"Wärmeschutz","c":false},{"t":"Verringerung des Verletzungsrisikos durch Splitterschutz","c":true}]},{"q":"Welches Behältnis ist für die sichere Aufbewahrung von Dienstunterlagen ausreichend, z.B. für Dienstanweisungen, Besucherausweise und Berichte?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Geprüfter Wertschutztresor","c":false},{"t":"Stahlblechschrank mit Sicherheitsverschluss","c":true},{"t":"Feuersicherer Datensicherungsschrank","c":false},{"t":"Panzergeldschrank mit mechanischer und geistiger Verschlusseinrichtung","c":false}]},{"q":"Wie lauten die drei Säulen der Sicherheitstechnik?","a":"- Mechanische Sicherung - Elektronische Sicherung - Organisation (Personal, Dienstanweisungen etc.)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist der Widerstandszeitwert, was ist die Interventionszeit?","a":"Das ist die Zeit, die ein geübter Einbrecher mit typischem Werkzeug benötigt, um alle Hindernisse zu überwinden vom Anfang bis zum Ende. Die Interventionszeit, ist die Zeit die der Alarmfahrer benötigt um nach Auslösen des Alarmes durch die EMA, zum Objekt zu kommen (mindestens 20 Min. nach vds.)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie 4 Zaunarten?","a":"- Maschendrahtzaun - Stahlgitterzaun - Streckmetallzaun - Drahtgitterzaun","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Sicherheitskriterien einer Zaunanlage, was bedeutet Kronensicherung?","a":"- Zaunhöhe mind. 2,50m - Untergrabschutz 0,80m - Unterkriechschutz 0,30m - Maschenbreite bei Maschendraht und Drahtgitter unter 5cm Von innen verschraubt; Verwendung von gehärtetem Material; Kronensicherung ist ein Y- Ausleger, der mit Stacheldraht gegen überklettern gesichert wird.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist die Schwachstelle einer Zaunanlage?","a":"- Öffnungen wie z.B. LKW Zufahrten, Personaleingänge. Diese sind z.B. durch automatische Rolltore oder Personenvereinzelungsanlagen zu sichern","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wofür sind Schranken gut, was sind Barrieren?","a":"Schranken sind gut für die Kontrolle von Personen und Fahrzeugen. Barrieren (z.B. Zäune, Mauern) bieten einen hohen Schutz gegen Angriffe.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre die Begriffe Funkschatten und Perimeter Sicherung?","a":"Ein Funkloch/Funkschatten ist ein räumlicher Bereich, in der eine Verbindung zwischen einem Sender und einem Empfänger nicht möglich ist. Unter Perimeter Schutz (Freilandschutz) versteht man mechanische und bauliche Perimeter Sicherung, sowie organisatorische und personelle Maßnahmen zum Schutz eines Objektes. z.B. Zaunstreife, Mikrowellenrichtstrahl, Videoüberwachung","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Bauteile und Schwachstellen einer Tür?","a":"- Türblatt - Drückergarnitur - Türbänder - Türzarge - Türschloss","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie die Sicherheitsvorschriften für Fluchttüren?","a":"- müssen Ausgeschildert sein - von außen mit Knauf versehen, damit keiner reinkommen kann - müssen nach außen jederzeit geöffnet werden können (Panikschloss) - dürfen nicht zugestellt werden - können elektronisch gesichert sein (Türwächter)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie sollte ein Schutzbeschlag beschaffen sein?","a":"- Schutz gegen Bohrangriffe - Schutz gegen Abrechen des Schließzylinders - Schutz gegen Kernziehen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Drei Arten von Schließanlagen?","a":"- Hauptschlüsselanlage, ein übergeordneter Schlüssel öffnet alle Schlösser mit Schließberechtigung, jede Tür hat aber ein eigenen Schlüssel (Hotel) - Zentralschlossanlage, mehrere verschiedene Einzelschlüssel, Schließen einen Zylinder (Mehrfamilienhaus) - Generalhauptschlüsselanlage, Kombination mehrer Hauptschlüssel mit Hierarchieunterteilung, der Generalschlüssel öffnet alle Türen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Bestandteile einer BMA?","a":"- Meldezentrale - Signalgeber - Meldelinie - Melder (Rauchmelder, Wärmemelder, Flammenmelder, Druckknopfmelder) - AWAG - AWUG - Netzstrom, AKKU - Automatische auslösen von Sprinkleranlage, Klimaanlage, schliesen von Brandschutztüren,...","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie funktioniert ein Wärmemaximalmelder?","a":"Der Wärmemaximalmelder misst die Temperatur und löst bei erreichen einer bestimmten Temperatur Alarm aus.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Betriebsfunk und muss dieser angemeldet werden?","a":"Bei einen Betriebsfunk (Reichweite ca. 20 km.) hat man einen eigen Funkkanal und muss bei der Bundesnetzagentur beantragt werden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie ist der Brandschutz unterteilt?","a":"- Vorbeugender Brandschutz, Feuertüren, BMA, Brandwände, Feuerlöscher,... - Abwehrender Brandschutz, Brandentdeckung, Brandort, Menschen retten, Brand bekämpfen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Widerstandswerte von Fenstern?","a":"- Durchwurfhemmend - Durchbruchhemmend - Durchschusshemmend - Explosionshemmend ESG – Einscheibensicherheitsglas VSG - Verbundsicherheitsglas","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[{"scenario":"Bei der Objektbegehung sollst du einschätzen, ob die Streife einen Einbrecher rechtzeitig stört. Die äußeren Hindernisse halten einen geübten Täter rund 8 Minuten auf. Der Interventionsdienst braucht ab Alarm 15 Minuten bis zum Objekt.","frage":"Reicht die Sicherung – und welche zwei Kennwerte stellst du gegenüber?","loesung":"Nein, sie reicht nicht. Du vergleichst den Widerstandszeitwert (ca. 8 Min., Zeit zum Überwinden der mechanischen Hindernisse) mit der Interventionszeit (15 Min., Anfahrt des Interventionsdienstes). Sicher ist es nur, wenn der Widerstandszeitwert GRÖSSER ist als die Interventionszeit – hier ist der Täter längst drin, bevor die Streife eintrifft. Denkschlüssel: Mechanik kauft nur Zeit; sie muss länger standhalten, als die Intervention braucht. Der VdS nennt als Regelinterventionszeit max. 20 Minuten."},{"scenario":"Ein Kunde rüstet sein Lager mit einer massiven, einbruchhemmenden Tür der höchsten Widerstandsklasse auf und ist überzeugt: Da kommt keiner rein – eine Alarmanlage spare er sich.","frage":"Worauf weist du ihn hin?","loesung":"Mechanischer Grundschutz allein ist trügerisch: Eine mechanische Sicherung hält einen Täter nur eine ZEIT LANG auf, nicht dauerhaft. Ohne Detektion bemerkt niemand den Angriff, ohne Intervention wird niemand geschickt. Sicherheit entsteht erst im Zusammenspiel der drei Säulen: mechanische Grundsicherung + elektronische Überwachung + organisatorisch-personelle Maßnahmen. Denkschlüssel: Keine Säule trägt allein – die Tür kauft Zeit, der Melder meldet, die Streife greift ein."},{"scenario":"Ein Betriebsgelände ist mit einem 2,5 m hohen Zaun gesichert. Die Einfahrt schließt nur eine Schranke. Der Betreiber meint, damit sei die Zufahrt auch gegen Eindringlinge gesichert.","frage":"Stimmt das?","loesung":"Nein. Eine Schranke ist nur ein Hilfsmittel zur Personen- und Fahrzeugkontrolle – sie ist kein Schutz gegen widerrechtliches Eindringen von Personen (man geht drunter oder drumherum). Gegen gewaltsames Durchbrechen braucht es Durchfahrtsperren. Und generell sind Durchlässe wie Tore und Türen die Schwachstellen einer Zaunanlage. Denkschlüssel: Eine Schranke regelt Verkehr, sie hält niemanden auf – Verkehrsregelung und Sicherung nicht verwechseln."}]},{"n":2,"title":"Schließtechnik","subtitle":"5 Konzepte · 7 Prüfungsfragen","cards":[{"h":"Schlossarten","b":"Buntbart-, Zuhaltungs-, Zahlenkombinations-, Mechatronikschloss","detail":{"titel":"Schlossarten","kat":"Mechanisch","katCls":"mech","merksatz":"Vom simplen Buntbart bis zum elektronischen Mechatronikschloss – je mehr unterschiedliche Sperren ein Schloss hat, desto schwerer ist es zu überwinden.","funktion":["Buntbartschloss: einfachstes Schloss (Zimmertüren, Möbel); der Bart des Schlüssels umgeht wenige feste Sperren – geringe Sicherheit, leicht mit Nachschlüssel zu öffnen.","Zuhaltungsschloss (Chubb): mehrere gefederte Zuhaltungen müssen exakt angehoben werden – deutlich sicherer, früher typisch für Tresore und Haustüren.","Zahlenkombinationsschloss: Öffnung über eine eingestellte Zahlenfolge statt Schlüssel – kein Schlüssel, der verloren gehen kann; verbreitet bei Tresoren und Vorhängeschlössern.","Mechatronikschloss: kombiniert Mechanik und Elektronik (Chip, Code, Transponder) – Berechtigungen lassen sich programmieren, sperren und protokollieren."],"schutzziel":"Den unbefugten Zugang verhindern und – bei höherwertigen Schlössern – das Anfertigen von Nachschlüsseln und das Manipulieren erschweren.","kennwerte":[{"l":"Einfach","v":"Buntbartschloss (geringe Sicherheit)"},{"l":"Mechanisch hochwertig","v":"Zuhaltungs-/Zylinderschloss"},{"l":"Elektronisch","v":"Mechatronik (programmierbar)"}],"begriffe":["Zuhaltung = bewegliches Sperrelement im Schloss, das erst in der richtigen Stellung den Riegel freigibt.","Mechatronik = Verbindung von Mechanik und Elektronik in einem Bauteil."],"abgrenzung":["Schloss ist nicht gleich Zylinder: Das Schloss ist der Verriegelungsmechanismus im Türblatt, der Profilzylinder nur der austauschbare Schließkern darin.","Ein Zahlenschloss hat keinen Schlüssel – dafür kann der Code ausgespäht oder verraten werden; ein Mechatronikschloss kann beides (Code und Transponder)."],"praxis":["Für Werttüren und Außentüren niemals einfache Buntbartschlösser – die sind mit einem Sperrhaken oder Universalschlüssel in Sekunden offen.","Mechatronik ist im Objektschutz beliebt, weil verlorene Transponder gesperrt werden können, ohne die ganze Anlage auszutauschen."]},"visual":null},{"h":"Zylinderschlosse","b":"Profil-, Rund-, Ovalzylinder","detail":{"titel":"Zylinderschlösser","kat":"Mechanisch","katCls":"mech","merksatz":"Der Profilzylinder ist der austauschbare Schließkern fast jeder modernen Tür – seine Form ist genormt, damit er in jedes passende Schloss passt.","funktion":["Profilzylinder (PZ): die häufigste Bauform mit der typischen Schlüsselloch-Silhouette; lässt sich nach Lösen einer Stulpschraube schnell tauschen.","Rundzylinder: runde Bauform, u. a. bei Möbeln, Briefkästen und älteren Anlagen.","Ovalzylinder: ovale Bauform, vor allem im angelsächsischen Raum und bei bestimmten Schlosstypen.","Im Inneren heben Stifte (Kern- und Gehäusestifte) den Schließkern nur beim richtigen Schlüssel auf die Trennlinie frei."],"schutzziel":"Den Schließkern so gestalten, dass er nur mit dem passenden Schlüssel dreht und schwer zu manipulieren (picken) oder gewaltsam zu ziehen ist.","kennwerte":[{"l":"Profilzylinder (PZ)","v":"Standard moderner Türen"},{"l":"Rundzylinder","v":"Möbel, Briefkästen, Altanlagen"},{"l":"Ovalzylinder","v":"spezielle Schlosstypen"}],"begriffe":["Stiftzuhaltung = die kleinen gefederten Stifte, die den Zylinderkern sperren, bis der richtige Schlüssel sie auf die Trennlinie bringt.","Not- und Gefahrenfunktion = Zylinder, der von innen abschließbar bleibt, auch wenn außen ein Schlüssel steckt."],"abgrenzung":["Profil-, Rund- und Ovalzylinder unterscheiden sich nur in der äußeren Form – das Sicherheitsniveau hängt vom Innenleben ab (Stiftanzahl, Bohrschutz, Ziehschutz).","Der Zylinder allein schützt nicht: Ohne Schutzbeschlag steht er ungeschützt und kann abgedreht oder gezogen werden."],"praxis":["Beim Auswechseln zählt das richtige Längenmaß: Steht der Zylinder über, bietet er eine Angriffsfläche zum Abbrechen oder Ziehen – er sollte bündig mit dem Beschlag abschließen.","Hochwertige Zylinder haben Bohrschutz (gehärtete Stifte) und Ziehschutz – wichtig an allen Außentüren."]},"visual":null},{"h":"Schlüsselkarte","b":"Sicherungskarte für Nachschlüssel; Einmaligkeit der Anlage","detail":{"titel":"Schlüsselkarte (Sicherungskarte)","kat":"Organisation","katCls":"org","merksatz":"Die Sicherungskarte ist der Ausweis der Schließanlage: Ohne sie bekommt niemand legal einen Nachschlüssel.","funktion":["Nachweis der Berechtigung: Nur wer die Sicherungskarte vorlegt, darf beim Hersteller oder Fachhändler Nachschlüssel bestellen.","Schutz vor unbefugtem Nachmachen: Der Schlüssel allein reicht nicht – die Anlage ist gegen einfaches Kopieren gesperrt.","Verwaltung: Die Karte enthält die Anlagennummer und gehört sicher verwahrt – nicht am Schlüsselbund!"],"schutzziel":"Verhindern, dass Unbefugte heimlich Nachschlüssel anfertigen lassen – die Einmaligkeit und Kontrolle der Schließanlage bleibt gewahrt.","kennwerte":[{"l":"Funktion","v":"Berechtigungsnachweis für Nachschlüssel"},{"l":"Enthält","v":"Anlagennummer / Sicherungscode"},{"l":"Verwahrung","v":"getrennt vom Schlüssel, sicher"}],"begriffe":["Sicherungskarte / Sicherungsschein = Dokument, das zur Nachschlüssel-Bestellung berechtigt.","Kopierschutz = patentierter Schlüsselrohling, der nicht frei im Handel erhältlich ist."],"abgrenzung":["Die Sicherungskarte ist organisatorischer Schutz (Berechtigung), kein mechanischer – sie verhindert legales Nachmachen, nicht das gewaltsame Öffnen.","Ein gewöhnlicher Schlüssel ohne Anlage kann an jeder Ecke kopiert werden; ein gesicherter Schlüssel braucht die Karte."],"praxis":["Im Objektschutz wird die Sicherungskarte streng verwahrt – wer sie hat, kontrolliert die ganze Anlage.","Geht die Karte verloren, ist das ein Sicherheitsvorfall: Im Zweifel muss die Schließung getauscht werden."]},"visual":null},{"h":"Schließanlagen","b":"Hauptschlüssel-, Zentralschloss-, Generalhauptschlüsselanlage; Hierarchie","detail":{"titel":"Schließanlagen","kat":"Organisation","katCls":"org","merksatz":"Eine Schließanlage ordnet Schlüssel und Türen in eine Hierarchie: Wer oben steht, schließt mehr – wer unten steht, nur seine eine Tür.","funktion":["Hauptschlüsselanlage (HSA): Jeder Schlüssel sperrt seine eigene Tür, ein übergeordneter Hauptschlüssel sperrt alle.","Zentralschlossanlage (ZSA): Viele Einzelschlüssel sperren zusätzlich ein oder mehrere gemeinsame Zentralschlösser (z. B. Haustür, Waschküche).","Generalhauptschlüsselanlage (GHS): Mehrere Hauptschlüsselanlagen werden unter einem Generalhauptschlüssel zusammengefasst – die umfassendste Stufe."],"schutzziel":"Zugänge gestuft und kontrolliert vergeben – jeder kommt genau dorthin, wo er hin darf, und die Verwaltung behält den Überblick.","kennwerte":[{"l":"HSA","v":"Einzelschlüssel + 1 Hauptschlüssel"},{"l":"ZSA","v":"Einzelschlüssel + gemeinsames Zentralschloss"},{"l":"GHS","v":"mehrere HSA unter 1 Generalhauptschlüssel"}],"begriffe":["Hierarchie der GHS: Generalhauptschlüssel → Hauptschlüssel → Gruppenschlüssel → Einzelschlüssel.","Schließplan = Matrix, die festlegt, welcher Schlüssel welche Tür sperrt."],"abgrenzung":["Hauptschlüsselanlage: oben einer für alles. Zentralschlossanlage: unten viele, die zusätzlich ein gemeinsames Schloss teilen. GHS: mehrere HSA zusammengefasst.","Nicht mit der Sicherungskarte verwechseln – die regelt das Nachmachen, die Schließanlage regelt, wer wohin kommt."],"praxis":["Der Generalhauptschlüssel ist das wertvollste Stück der Anlage – sein Verlust kann den Austausch der gesamten Anlage erfordern.","Als Wachkraft führst du oft einen Hauptschlüssel für dein Revier – entsprechend sorgsam ist er zu verwahren und im Schlüsselbuch zu quittieren."]},"visual":null},{"h":"Wertbehältnisse","b":"Tresor vs. Datensicherungsschrank; Geld-/Panzerschrank","detail":{"titel":"Wertbehältnisse","kat":"Mechanisch","katCls":"mech","merksatz":"Tresor schützt gegen Einbruch, Datensicherungsschrank gegen Feuer – wer beides verwechselt, verliert im Ernstfall genau das, was er schützen wollte.","funktion":["Wertschutzschrank/Tresor: schützt Bargeld und Wertsachen gegen Aufbruch; nach Widerstandsgraden klassifiziert (VdS / EN 1143-1).","Datensicherungsschrank: schützt Datenträger und Dokumente gegen Feuer und Hitze (begrenzte Innentemperatur), oft nur mit geringem Einbruchschutz.","Geld- und Panzerschrank: umgangssprachlich für schwere, einbruchhemmende Wertbehältnisse höherer Klassen."],"schutzziel":"Den Inhalt gezielt gegen die jeweils richtige Gefahr schützen – Einbruch oder Feuer – je nach Schutzbedarf des Inhalts.","kennwerte":[{"l":"Tresor (Wertschutzschrank)","v":"Einbruchschutz (VdS-/EN-Klassen)"},{"l":"Datensicherungsschrank","v":"Feuer-/Hitzeschutz für Datenträger"},{"l":"Auswahl nach","v":"Versicherungssumme & Schutzbedarf"}],"begriffe":["Widerstandsgrad (z. B. Grad 0–VI nach EN 1143-1): gibt an, wie lange ein Wertschutzschrank dem Aufbruch widersteht – daraus leitet sich die zulässige Versicherungssumme ab.","Feuerwiderstand (z. B. S 60 P für Papier, S 120 DIS für Datenträger): begrenzt die Innentemperatur über eine festgelegte Zeit."],"abgrenzung":["Tresor = Einbruchschutz, Datensicherungsschrank = Feuerschutz – das ist NICHT dasselbe. Ein Datenschrank hält oft kaum einem Aufbruch stand.","Ein feuersicherer Schrank für Papier (höhere Temperaturgrenze) schützt empfindliche Datenträger nicht zwangsläufig – Datenträger brauchen eine niedrigere Innentemperatur."],"praxis":["Bei der Begehung prüfst du: Ist der Tresor verschlossen, ist Schlüssel oder Code nicht in der Nähe deponiert, ist ein freistehender Schrank verankert?","Für die richtige Wahl zählt der Inhalt: Bargeld → Wertschutzschrank passender Klasse; Backups und Dokumente → Datensicherungsschrank."]},"visual":null}],"quiz":[{"q":"Welche Aufgabe haben ein Schutzbeschlag bzw. ein Ziehschutz an einer Tür?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sie schützen den Schließzylinder gegen Abbrechen oder Herausziehen","c":true},{"t":"Sie schützen den Schlosskasten und die Sperreinrichtung gegen Bohrangriffe","c":true},{"t":"Sie ersetzen die Einbruchmeldeanlage","c":false},{"t":"Sie dienen nur der optischen Gestaltung der Tür","c":false}]},{"q":"Welche Aussagen zu Schlossarten in der Schließtechnik sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Zu den mechanischen Schlössern zählen u. a. Buntbart-, Zylinder- und Chubbschloss","c":true},{"t":"Ein mechatronisches Schloss verbindet mechanische mit elektronischen Komponenten","c":true},{"t":"Ein Transponderschloss wird berührungslos per Funkchip bedient","c":true},{"t":"Ein Buntbartschloss bietet den höchsten Schutz gegen Picking und Nachschließen","c":false}]},{"q":"Nennen Sie Schlossarten.","a":"- Buntbartschloss - Besatzungschloss - Zuhaltungsschloss - Zahlenkombinationschloss - Mechatronikschloss","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie sollte ein Schutzbeschlag beschaffen sein?","a":"- Schutz gegen Bohrangriffe - Schutz gegen Abrechen des Schließzylinders - Schutz gegen Kernziehen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie die 3 Formen eines Zylinderschlosses.","a":"- Profilzylinder - Rundzylinder - Ovalzylinder","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Drei Arten von Schließanlagen?","a":"- Hauptschlüsselanlage, ein übergeordneter Schlüssel öffnet alle Schlösser mit Schließberechtigung, jede Tür hat aber ein eigenen Schlüssel (Hotel) - Zentralschlossanlage, mehrere verschiedene Einzelschlüssel, Schließen einen Zylinder (Mehrfamilienhaus) - Generalhauptschlüsselanlage, Kombination mehrer Hauptschlüssel mit Hierarchieunterteilung, der Generalschlüssel öffnet alle Türen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine Schlüsselkarte?","a":"Mit einer Schlüsselkarte/Sicherungskarte bekommt nur der Inhaber der Schließanlage einen Nachschlüssel, er enthält die Codierung für die Nachfertigung, der Hersteller garantiert damit die Einmaligkeit der Anlage.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Benennen Sie die Hierarchie der Generalhauptschlüsselanlage.","a":"- Generalschlüssel - Hauptgruppenschlüssel - Obergruppenschlüssel - Gruppenschlüssel - Untergruppenschlüssel - Einzelschlüssel","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Arten von Wertbehältnissen (Unterschied Tresor/Datensicherungsschrank)","a":"- Stahl- Geldschrank - Panzergeldschrank - Datensicherungsschrank - Tresor schützt vor Diebstahl - Datensicherungsschrank schützt vor Datenverlust, bei Feuer,...","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[{"scenario":"An einer Tür ist ein hochwertiger Schließzylinder verbaut. Trotzdem hebeln Einbrecher ihn in Sekunden heraus und öffnen die Tür von innen.","frage":"Welche Schwachstelle wurde übersehen – und was hätte geschützt?","loesung":"Der beste Zylinder nützt nichts, wenn er ungeschützt vorsteht und herausgezogen oder abgebrochen werden kann. Es fehlt der Ziehschutz bzw. Schutzbeschlag, der Schließzylinder und Schlosskasten gegen Bohren, Abbrechen und Herausziehen schützt. Denkschlüssel: Eine Tür ist nur so stark wie ihr schwächstes Bauteil – Zylinder, Beschlag, Band und Rahmen sind jeweils gesondert zu bewerten."},{"scenario":"In einem Objekt mit mechanischer Schließanlage geht ein General-Hauptschlüssel verloren, der alle Türen öffnet.","frage":"Warum ist das schlimmer als ein verlorener Einzelschlüssel – und was wäre der Vorteil eines mechatronischen Systems?","loesung":"Bei einer mechanischen Schließanlage öffnet der General-Hauptschlüssel viele oder alle Türen – geht er verloren, ist praktisch die ganze Anlage kompromittiert, und oft hilft nur ein teurer Austausch der Zylinder. Mechatronische bzw. elektronische Schließsysteme haben den Vorteil, dass verlorene Berechtigungen einfach per Software gesperrt und neu vergeben werden können, ohne Zylinder zu tauschen. Denkschlüssel: Je zentraler ein Schlüssel, desto größer der Schaden bei Verlust – elektronische Rechte lassen sich sperren, mechanische nicht."}]},{"n":3,"title":"Gefahrenmeldeanlagen (GMA)","subtitle":"4 Konzepte · 11 Prüfungsfragen","cards":[{"h":"GMA-Übersicht","b":"ÜMA, BMA, EMA; Bestandteile einer GMA","detail":{"titel":"GMA-Übersicht","kat":"Elektronisch","katCls":"elektr","merksatz":"Gefahrenmeldeanlagen melden Gefahren zuverlässig über überwachte Wege an eine hilfeleistende Stelle – sie verhindern nichts, aber sie alarmieren.","funktion":["Drei Arten: EMA (Einbruchmeldeanlage), BMA (Brandmeldeanlage), ÜMA (Überfallmeldeanlage). Alle sind GMA – sie unterscheiden sich nur in der Gefahr, die sie melden.","Bestandteile: Melder (erfassen die Gefahr) → Zentrale (wertet aus) → Übertragungseinrichtung (leitet weiter) → Energieversorgung (mit Notstrom) → Alarmierungsmittel (Sirene, Blitz).","Überwachte Übertragungswege: Wird eine Leitung manipuliert oder unterbrochen, löst das selbst einen Alarm aus (Sabotageschutz)."],"schutzziel":"Eine Gefahr zuverlässig erkennen, melden und an die richtige Stelle (NSL, Polizei, Feuerwehr) weiterleiten – Detektion, nicht Verhinderung.","kennwerte":[{"l":"EMA","v":"Einbruchmeldeanlage"},{"l":"BMA","v":"Brandmeldeanlage"},{"l":"ÜMA","v":"Überfallmeldeanlage"}],"begriffe":["GMA = Gefahrenmeldeanlage, der Oberbegriff für EMA, BMA und ÜMA.","Überwachter Übertragungsweg = die Leitung wird selbst kontrolliert; eine Störung oder Sabotage erzeugt eine Meldung."],"abgrenzung":["EMA, BMA, ÜMA sind keine getrennten Geräte, sondern Ausprägungen einer GMA – benannt nach der Gefahr (Einbruch, Brand, Überfall).","Eine GMA meldet nur – sie ist die zweite Säule (Elektronik). Verhindern muss die Mechanik, reagieren die Organisation."],"praxis":["Als Wachkraft musst du wissen, welche Anlage welchen Alarm gibt – ein BMA-Alarm (Brand) erfordert ein völlig anderes Verhalten als ein ÜMA-Alarm (Überfall).","Bei der Scharf- und Unscharfschaltung der EMA bist du oft beteiligt – Fehlbedienung ist die häufigste Ursache von Fehlalarmen."]},"visual":null},{"h":"Melderarten","b":"EMA/BMA/ÜMA-Melder; Streulichtmelder, Wärmemaximalmelder","detail":{"titel":"Melderarten","kat":"Elektronisch","katCls":"elektr","merksatz":"Jeder Melder hat einen Sinn für eine bestimmte Gefahr – Bewegung, Glasbruch, Erschütterung, Rauch oder Hitze. Die Kunst ist, den richtigen am richtigen Ort einzusetzen.","funktion":["EMA-Melder: Bewegungsmelder (Infrarot/PIR, Ultraschall) für die Fallenüberwachung, Glasbruchmelder, Magnetkontakte (Tür/Fenster offen), Körperschall- und Erschütterungsmelder (an Wänden/Tresoren), Lichtschranken für die Außenhaut.","BMA-Melder: Rauchmelder (optischer Streulichtmelder, Ionisationsmelder), Wärmemelder (Wärmemaximal- und Differenzialmelder), Flammenmelder, Handfeuermelder (Druckknopfmelder).","Überwachungsarten: Außenhautüberwachung (Türen/Fenster), Fallenüberwachung (innere Wege), Schwerpunkt- bzw. Objektüberwachung (einzelne Werte)."],"schutzziel":"Die jeweilige Gefahr genau dort erfassen, wo sie auftritt – mit dem Meldertyp, der für diese Gefahr und diesen Ort geeignet ist.","kennwerte":[{"l":"Bewegung (Falle)","v":"Infrarot- (PIR) & Ultraschallmelder"},{"l":"Rauch","v":"optischer Streulichtmelder"},{"l":"Hitze","v":"Wärmemaximal- / Differenzialmelder"}],"begriffe":["Streulichtmelder = optischer Rauchmelder: Rauchpartikel lenken in der Messkammer einen Lichtstrahl ab (streuen ihn) auf eine Fotozelle → Alarm.","Wärmemaximalmelder = löst aus, wenn eine feste Höchsttemperatur (z. B. 60–70 °C) erreicht wird; der Differenzialmelder reagiert auf zu schnellen Temperaturanstieg.","Körperschallmelder = erkennt Erschütterungen und Schwingungen in Wänden, Decken, Böden – für Wertschutzräume und Tresore."],"abgrenzung":["Streulichtmelder (Rauch) reagiert auf Partikel, Wärmemelder (Hitze) auf Temperatur – in staubigen oder rauchigen Räumen (Küche, Werkstatt) nimmt man Wärmemelder, um Fehlalarme zu vermeiden.","Bewegungsmelder (Falle) detektieren Personen im Raum; Lichtschranken und Magnetkontakte (Außenhaut) detektieren das Überwinden der Hülle. Körperschallmelder gehören nicht in alle Räume, sondern an Werte (Wände/Tresore)."],"praxis":["Falscher Melder am falschen Ort = Fehlalarme: Ein optischer Rauchmelder in der staubigen Lagerhalle löst ständig aus – dort gehört ein Wärmemelder hin.","Bei der Begehung prüfst du, ob Melder verdeckt, verstellt oder verschmutzt sind – ein zugestellter Bewegungsmelder ‚sieht‘ nichts."]},"visual":null},{"h":"ÜMA / EMA / BMA Funktionsweise","b":"Scharfschaltung, Alarmauslösung, Übertragung","detail":{"titel":"ÜMA / EMA / BMA – Funktionsweise","kat":"Elektronisch","katCls":"elektr","merksatz":"Vom Melder zur Hilfe: Scharfschalten → Melder löst aus → Zentrale wertet aus → Übertragung alarmiert. Jeder Anlagentyp folgt diesem Ablauf – aber laut oder still.","funktion":["EMA (Einbruch): wird beim Verlassen scharfgeschaltet; löst ein Melder aus, geht ein (meist lauter) Alarm an die Sirene und still an die NSL. Beim Betreten zuerst unscharf schalten.","ÜMA (Überfall): ist immer aktiv (kein scharf/unscharf); wird per Hand- oder Fußtaster bewusst ausgelöst und gibt STILLEN Alarm an die Polizei – kein Sirenenalarm, um den Täter nicht zu provozieren.","BMA (Brand): ist immer aktiv; automatische Melder (Rauch/Wärme) oder Handfeuermelder lösen aus, die Brandmeldezentrale alarmiert laut (Räumung!) und leitet zur Feuerwehr weiter.","Zwangsläufigkeit: Die EMA lässt sich nur scharfschalten, wenn alle Fenster und Türen zu sind – kein versehentliches Scharfschalten bei offenem Fenster."],"schutzziel":"Den richtigen Alarm für die richtige Gefahr auslösen – laut zum Vertreiben oder Räumen (EMA/BMA) oder still zum Schutz von Menschen (ÜMA).","kennwerte":[{"l":"EMA","v":"scharf/unscharf · laut + still"},{"l":"ÜMA","v":"immer aktiv · STILLER Alarm"},{"l":"BMA","v":"immer aktiv · laut + Feuerwehr"}],"begriffe":["Scharfschaltung = die EMA aktivieren; Unscharfschaltung = vor dem Betreten deaktivieren, sonst Alarm.","Zwangsläufigkeit = die Anlage verhindert technisch das Scharfschalten, solange noch etwas offen oder ein Melder gestört ist.","Stiller Alarm = Alarm ohne hörbares oder sichtbares Signal vor Ort, damit der Täter nichts merkt (typisch ÜMA)."],"abgrenzung":["EMA wird scharf und unscharf geschaltet – ÜMA und BMA sind IMMER aktiv. Das ist der zentrale Unterschied.","ÜMA = STILL (Menschen schützen), EMA/BMA meist LAUT (vertreiben bzw. räumen). Wer laut und still verwechselt, bringt im Überfall Menschen in Gefahr."],"praxis":["Beim Betreten eines scharfgeschalteten Objekts musst du zuerst unscharf schalten – sonst löst du selbst den Alarm aus (häufigster Fehlalarm im Wachdienst).","Einen ÜMA-Taster nie testweise oder aus Versehen drücken – das löst einen echten Polizeieinsatz aus."]},"visual":null},{"h":"AWAG / AWUG / Primärleitung","b":"Ansage- vs. Übertragungsgerät; Standleitung zur Polizei/NSL","detail":{"titel":"AWAG / AWUG / Primärleitung","kat":"Elektronisch","katCls":"elektr","merksatz":"Der beste Alarm ist nutzlos, wenn er niemanden erreicht – die Übertragungseinrichtung bringt die Meldung von der Zentrale zur hilfeleistenden Stelle.","funktion":["AWAG (Automatisches Wähl- und Ansagegerät): wählt im Alarmfall festgelegte Rufnummern und spielt eine gespeicherte Sprachansage ab (‚Einbruch in Objekt X‘) – an Personen.","AWUG (Automatisches Wähl- und Übertragungsgerät): überträgt die Meldung als digitales Protokoll an eine Empfangszentrale (NSL) – Gerät zu Gerät, nicht als Sprache.","Primärleitung: eine ständig überwachte Standleitung direkt zur Polizei oder Leitstelle – höchste Sicherheit, da Sabotage sofort auffällt; nur für bestimmte Objekte (z. B. Banken) zugelassen."],"schutzziel":"Die Alarmmeldung zuverlässig und – bei überwachten Wegen – sabotagesicher an die Stelle bringen, die eingreifen kann (NSL, Polizei, Feuerwehr).","kennwerte":[{"l":"AWAG","v":"Sprachansage an Personen (Ansagegerät)"},{"l":"AWUG","v":"digitale Übertragung an NSL (Übertragungsgerät)"},{"l":"Primärleitung","v":"überwachte Standleitung zur Polizei"}],"begriffe":["NSL = Notruf- und Serviceleitstelle, die aufgeschaltete Alarme rund um die Uhr entgegennimmt und die Intervention auslöst.","Aufschaltung = ein Objekt mit seiner GMA bei einer NSL oder Leitstelle anschließen, sodass deren Alarme dort auflaufen.","Standleitung = fest geschaltete, ständig überwachte Verbindung – im Gegensatz zur normalen Wählverbindung."],"abgrenzung":["AWAG = Ansage (Sprache an Menschen), AWUG = Übertragung (Daten an ein Empfangsgerät). Eselsbrücke: das A in AWAG steht für Ansage, das U in AWUG für Übertragung.","Die Primärleitung (überwachte Standleitung, sabotagesicher) ist hochwertiger als eine normale Wählverbindung über AWAG/AWUG – aber teuer und nur für besonders gefährdete Objekte."],"praxis":["Bei aufgeschalteten Objekten läuft der Alarm über das AWUG bei deiner NSL auf – von dort wird die Streife (du) zur Alarmverfolgung losgeschickt.","Bei der Alarmverfolgung musst du wissen: echter Alarm oder Störungsmeldung? Überwachte Wege melden auch Leitungsstörungen."]},"visual":null}],"quiz":[{"q":"Welche Aussagen zu den Gefahrenmeldeanlagen sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Gefahrenmeldeanlagen erstellen Gefahrenmeldungen, die auf überwachten Übertragungswegen an Hilfe leistende Stellen weitergeleitet werden, z.B. an Notruf- und Serviceleitstellen","c":true},{"t":"Gefahrenmeldeanlagen sind Fernmeldeanlagen zum zuverlässigen Melden von Gefahren für Personen und Sachen","c":true},{"t":"Gefahrenmeldeanlagen dienen dem Zweck, Einbrüche zu verhindern und werden zur Vereinfachung der Strafverfolgung mit den örtlichen Polizeidienststellen direkt verbunden","c":false},{"t":"Gefahrenmeldeanlagen sind reine Störmeldeanlagen. Sie melden z.B. elektronische Störungen in Klima- und Telefonanlagen","c":false}]},{"q":"Wo werden Infrarot-Lichtschranken eingesetzt?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Zur Überwachung von Glastüren","c":false},{"t":"Zur Überwachung von Tresoren","c":false},{"t":"Zur Überwachung der Außenhaut","c":true},{"t":"Zur Überwachung von Innenräumen","c":true}]},{"q":"Welche Melder sind für die Fallenüberwachung, bei der die Bewegung von Personen detektiert werden soll, geeignet?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Glasbruchmelder","c":false},{"t":"Kapazitativer Feldveränderungsmelder","c":false},{"t":"Ultraschallmelder","c":true},{"t":"Infrarotmelder","c":true}]},{"q":"Für welche Arten der Überwachung sind Körperschallmelder einsetzbar?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Zur Überwachung von Wertschutzräumen und Wertschutzschränken","c":true},{"t":"Zur Überwachung von Wänden, Decken und Böden","c":true},{"t":"Zur Überwachung von allen Arten von Räumen","c":false},{"t":"Zur Überwachung einzelner Wertgegenstände","c":false}]},{"q":"Was sind Funktionen einer Brandmeldezentrale?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sie wertet die empfangenen Signale der angeschlossenen Melder aus","c":true},{"t":"Sie aktiviert automatisch am Brandherd eingerichtete nasse Sprinkleranlagen","c":false},{"t":"Sie überwacht die Brandmeldeanlage und zeigt Fehler optisch und akustisch an, z.B. Störungen der Energieversorgung","c":true},{"t":"Sie aktiviert im Brandfall vorhandene Klimaanlagen, um schädliche Rauchgase abzusaugen","c":false}]},{"q":"Was ist eine GMA und welche kennen wir?","a":"GMA sind Gefahrenmeldeanlagen - ÜMA (Überfallmeldeanlage - BMA (Brandmeldeanlage) - EMA (Einbruchmeldeanlage)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Bestandteile einer GMA?","a":"- Meldezentrale - Melder - Meldelinie - Stromversorgung - Signalgeber - AWAG - AWUG - Scharfschalteinrichtung","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie Arten von Meldern, welche sind in der EMA, BMA, ÜMA?","a":"EMA: Mikrowellenrichtstrahl, Bewegungsmelder, Glasbruchmelder,... BMA: Rauchmelder, Wärmemelder, Flammenmelder, Druckknopfmelder ÜMA: Notdrückknopf, Tretleiste, Geldscheinkontakt (Klammer), Codiereinrichtung (PC)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet EMA und BMA, Funktionsweise erklären?","a":"- EMA ist eine Einbruchsmeldeanlage; Meldet einen Einbruchsalarm und ist in der Regel nach Feierabend aktiviert; Fernmeldeanlage/Scharfgeschaltet - BMA ist eine Brandmeldeanlage; Meldet einen Brand, ist immer aktiv. Hat die Möglichkeit Systeme zu steuern, z.B. Aufzüge stoppen, Sprinkler auslösen etc. Es gibt Melder die über die Meldelinie mit der Meldezentrale verbunden sind und bei Gefahr auslösen, die Meldzentrale löst dann Alarm aus, aktiviert die Signalgeber überträgt über die AWUG den Alarm zur Polizei, Feuerwehr oder NSL oder gibt Nachrichten durch die AWAG an das Personal, Zuschauer durch. Läuft über Netzstrom und AKKU bei Stromausfall. Wird Scharfgestaltet mit Blockschloss bei der EMA, - BMA und ÜMA sind immer scharfgeschaltet.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Bestandteile einer BMA?","a":"- Meldezentrale - Signalgeber - Meldelinie - Melder (Rauchmelder, Wärmemelder, Flammenmelder, Druckknopfmelder) - AWAG - AWUG - Netzstrom, AKKU - Automatische auslösen von Sprinkleranlage, Klimaanlage, schliesen von Brandschutztüren,...","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Rauchmelder, Funktion eines Streulichtmelders?","a":"- Rauchmelder - Wärmemelder - Flammenmelder Im Inneren eines Rauchmelders befindet sich eine Leuchtdiode, die ständig einen Lichtstrahl aussendet, und eine Fotodiode. Im Ruhezustand trifft der Lichtstrahl NICHT auf die Fotodiode - und der Rauchmelder gibt keinen Alarm. Tritt Rauch in den Rauchmelder ein, wird der Lichtstrahl abgelenkt die Fotodiode empfängt den Lichtstrahl und löst den Alarm aus. (er wird \"gestreut\" - daher der Begriff \"Streulichtmelder\").","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie funktioniert ein Wärmemaximalmelder?","a":"Der Wärmemaximalmelder misst die Temperatur und löst bei erreichen einer bestimmten Temperatur Alarm aus.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist der Widerstandszeitwert, was ist die Interventionszeit?","a":"Das ist die Zeit, die ein geübter Einbrecher mit typischem Werkzeug benötigt, um alle Hindernisse zu überwinden vom Anfang bis zum Ende. Die Interventionszeit, ist die Zeit die der Alarmfahrer benötigt um nach Auslösen des Alarmes durch die EMA, zum Objekt zu kommen (mindestens 20 Min. nach vds.)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine ÜMA, welche Funktionsweise?","a":"ÜMA ist eine Überfallmeldeanlage - Immer Scharfgeschaltet - Alarmauslösung durch Notdrückknopf, Tretleiste, Geldscheinkontakt, Codiereinrichtung - Löst ein stillen Alarm aus über die AWUG an Polizei","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie ist der Brandschutz unterteilt?","a":"- Vorbeugender Brandschutz, Feuertüren, BMA, Brandwände, Feuerlöscher,... - Abwehrender Brandschutz, Brandentdeckung, Brandort, Menschen retten, Brand bekämpfen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine Primärleitung, was bedeutet AWAG und AWUG?","a":"Eine Primärleitung ist eine Standleitung zur Polizei, Feuerwehr oder NSL. - AWAG, Automatisches - Wähl - Ansagegerät - AWUG, Automatisches - Wähl - Übertragungsgerät","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[{"scenario":"Du planst die Raumüberwachung. Ziel ist die Fallenüberwachung: Bewegt sich ein eingedrungener Täter durch den Raum, soll er sicher erkannt werden. Ein Kollege schlägt Glasbruchmelder vor.","frage":"Ist das die richtige Melderart – und was passt?","loesung":"Nein. Glasbruchmelder erkennen nur das Zerstören von Glas (Öffnungs-/Außenhautüberwachung), nicht die Bewegung einer Person im Raum. Für die Fallenüberwachung (Bewegungsdetektion) eignen sich Bewegungsmelder wie Infrarot- (PIR) und Ultraschallmelder. Denkschlüssel: Erst die Überwachungsart bestimmen (Außenhaut – Falle – Objekt), dann den passenden Melder wählen. Bewegung ist nicht Glasbruch und nicht Körperschall."},{"scenario":"An einer Kasse soll bei einem Überfall Alarm ausgelöst werden, OHNE dass der Täter es bemerkt. Ein Kollege schlägt eine laute Sirene vor, damit alle gewarnt sind.","frage":"Welche Anlage und welche Alarmart sind hier richtig?","loesung":"Eine Überfallmeldeanlage (ÜMA), ausgelöst über einen unauffälligen Überfallmelder (z. B. Geldscheinkontakt, Fußtaster). Sie alarmiert STILL zur Leitstelle bzw. Polizei. Ein lauter Alarm würde den Täter in der Überfallsituation zusätzlich provozieren und Menschen gefährden. Denkschlüssel: Einbruch (EMA) – abschrecken, oft laut; Überfall (ÜMA) – still, weil Menschen unmittelbar bedroht sind."},{"scenario":"In einem Lager mit freilaufender Wachhündin kommt es nachts ständig zu Fehlalarmen der Bewegungsmelder.","frage":"Woran liegt das wahrscheinlich – und wie löst man es?","loesung":"Klassische Infrarot-Bewegungsmelder (PIR) reagieren auf Wärme und Bewegung – ein Tier löst sie aus. Lösung: tierimmune Melder oder Dual-Melder (z. B. PIR plus Ultraschall, die nur bei beiden Kriterien gemeinsam auslösen), oder die Überwachungsart wechseln (Außenhaut-/Öffnungsüberwachung statt Fallenüberwachung im Bewegungsbereich). Denkschlüssel: Fehlalarme zerstören das Vertrauen in die Anlage – die Melderart muss zur Umgebung passen, nicht nur zum Schutzziel."},{"scenario":"Für einen Tresorraum sollst du die Überwachung wählen. Es geht darum, Angriffe direkt auf Wände, Decke und Boden (Durchbruch) früh zu erkennen.","frage":"Welche Melderart passt – und welche wäre hier falsch?","loesung":"Passend sind Körperschallmelder: Sie erkennen die Erschütterungen und Geräusche beim Bohren, Sägen oder Aufbrechen von Wänden, Decken und Böden (Überwachung von Wertschutzräumen). Falsch wäre reine Bewegungsmelder-Fallenüberwachung – die meldet erst, wenn der Täter schon im Raum steht. Denkschlüssel: Beim Durchbruchschutz zählt das Erkennen am Bauteil selbst (Körperschall), nicht erst die Bewegung danach."}]},{"n":4,"title":"Zutritt, Funk & Personenschutz","subtitle":"6 Konzepte · 13 Prüfungsfragen","cards":[{"h":"Zutrittskontrollsystem (ZKS)","b":"Wer-Wann-Wohin; Drehkreuze, Schleusen","detail":{"titel":"Zutrittskontrollsystem (ZKS)","kat":"Elektronisch","katCls":"elektr","merksatz":"Ein ZKS beantwortet drei Fragen automatisch: Wer darf wann wohin? Nur wer berechtigt ist, kommt zur richtigen Zeit an die richtige Tür.","funktion":["Steuert und protokolliert Zutritte: Jede Berechtigung ist hinterlegt (Person, Zeitfenster, Bereich) – das System gibt frei oder sperrt.","Komponenten: Ausweisleser (Erkennung) → Steuerzentrale (prüft Berechtigung) → Sperrelement (Tür, Drehkreuz, Schranke) → Energieversorgung → Bedienungseinrichtung.","Protokollierung: Wer wann wo durchging, wird gespeichert – wichtig für Nachweis und Auswertung (Datenschutz beachten!)."],"schutzziel":"Nur Berechtigten den Zutritt zu bestimmten Bereichen zu bestimmten Zeiten gewähren – und jeden Zutritt nachvollziehbar machen.","kennwerte":[{"l":"Kernfrage","v":"Wer? Wann? Wohin?"},{"l":"Komponenten","v":"Leser · Zentrale · Sperrelement"},{"l":"Zusatz","v":"Protokollierung (Datenschutz!)"}],"begriffe":["Zutrittsberechtigung = die im System hinterlegte Erlaubnis einer Person für einen Bereich und ein Zeitfenster.","Vereinzelung = sicherstellen, dass pro Freigabe nur eine Person passiert (siehe nächste Karte)."],"abgrenzung":["Ein ZKS regelt, WER durchdarf (Berechtigung) – eine Vereinzelungsanlage stellt sicher, dass nur EINER pro Freigabe durchgeht. Oft arbeiten beide zusammen.","Anders als eine EMA meldet ein ZKS keinen Einbruch, sondern steuert den regulären Zutritt im Normalbetrieb."],"praxis":["Die Protokolldaten eines ZKS sind personenbezogen – sie unterliegen dem Datenschutz und dürfen nicht beliebig ausgewertet werden.","An der Pforte ergänzt deine Sichtkontrolle das System: Ein gültiger Ausweis am Leser heißt nicht, dass die richtige Person ihn trägt."]},"visual":null},{"h":"Personenvereinzelungsanlage","b":"Drehkreuz, Drehsperre, Sensor-/Personenschleuse","detail":{"titel":"Personenvereinzelungsanlage","kat":"Mechanisch","katCls":"mech","merksatz":"Eine Vereinzelungsanlage lässt pro Freigabe genau eine Person durch – sie verhindert das Mitschlüpfen hinter einem Berechtigten.","funktion":["Drehkreuz / Drehsperre: lässt nach einer Freigabe nur eine Person passieren, dann sperrt es wieder.","Personenschleuse / Sensorschleuse: ein kleiner Raum mit zwei Türen; die zweite öffnet erst, wenn die erste zu ist und nur eine Person erkannt wurde.","Erkennung: Sensoren (Lichtschranken, Bodensensoren, Gewichtskontrolle) verhindern, dass zwei Personen gleichzeitig durchgehen (Tailgating)."],"schutzziel":"Verhindern, dass Unbefugte hinter einem Berechtigten mitlaufen – jede Person muss sich einzeln ausweisen.","kennwerte":[{"l":"Drehkreuz/Drehsperre","v":"1 Person pro Freigabe"},{"l":"Personenschleuse","v":"2 Türen, einzeln erkannt"},{"l":"Verhindert","v":"Mitschlüpfen (Tailgating)"}],"begriffe":["Tailgating / Mitschlüpfen = unberechtigtes Folgen direkt hinter einer berechtigten Person durch dieselbe Öffnung.","Sensorschleuse = Schleuse, die per Sensorik erkennt und sicherstellt, dass nur eine Person im Schleusenraum ist."],"abgrenzung":["Das ZKS prüft die Berechtigung (wer darf), die Vereinzelungsanlage erzwingt die Einzelpassage (nur einer pro Freigabe). Beides ergänzt sich.","Eine Schranke regelt Fahrzeuge, ein Drehkreuz vereinzelt Personen – nicht verwechseln."],"praxis":["Auch die beste Vereinzelung wird durch Nachlässigkeit ausgehebelt – z. B. wenn ein Mitarbeiter die Tür freundlich aufhält. Sensibilisierung gehört dazu.","Bei deiner Kontrolle achtest du gezielt auf Mitschlüpfen an Drehkreuzen, gerade in Stoßzeiten."]},"visual":null},{"h":"Ausweisleser","b":"Einsteck-, Durchzug-, Einzug-, Abstandsleser","detail":{"titel":"Ausweisleser","kat":"Elektronisch","katCls":"elektr","merksatz":"Vier Lesertypen, ein Zweck: den Ausweis erkennen. Der Unterschied liegt darin, WIE die Karte zum Leser kommt – einstecken, durchziehen, einziehen oder nur danebenhalten.","funktion":["Einsteckleser: Die Karte wird eingesteckt und während des Lesens gehalten – einfacher Kontakt.","Durchzugleser (Magnetstreifen): Die Karte wird durch einen Schlitz gezogen, der Magnetstreifen wird gelesen.","Einzugleser: Die Karte wird eingezogen, geprüft und wieder ausgegeben (oder im Missbrauchsfall einbehalten).","Abstandsleser (RFID/berührungslos): Die Karte wird nur in die Nähe gehalten – kein Kontakt nötig (Transponder)."],"schutzziel":"Den Ausweis zuverlässig erkennen und an die Steuerzentrale melden – passend zum Einsatzort (Verschleiß, Komfort, Hygiene).","kennwerte":[{"l":"Einsteckleser","v":"Karte einstecken & halten"},{"l":"Durchzugleser","v":"Magnetstreifen durchziehen"},{"l":"Einzug-/Abstandsleser","v":"einziehen bzw. berührungslos (RFID)"}],"begriffe":["RFID / Transponder = berührungslose Erkennung über Funk im Nahbereich; die Karte braucht keine eigene Stromquelle.","Berührungsloser (Abstands-)Leser = liest die Karte ohne physischen Kontakt – verschleißarm und schnell."],"abgrenzung":["Kontaktbehaftet (Einsteck, Durchzug, Einzug) gegen berührungslos (Abstand/RFID): Berührungslose Leser verschleißen kaum und sind komfortabler, kontaktbehaftete oft günstiger.","Der Leser erkennt nur den Ausweis – die Berechtigungsprüfung macht die ZKS-Zentrale, nicht der Leser selbst."],"praxis":["Berührungslose Abstandsleser haben sich durchgesetzt – schnell, robust, kein Verschleiß durch Stecken oder Ziehen.","Ein defekter oder verschmutzter Leser ist eine typische Störungsmeldung – bei der Begehung mitprüfen."]},"visual":null},{"h":"Funk","b":"Handfunkgeräte-Übergabe, Funkschatten, Perimetersicherung, Betriebsfunk","detail":{"titel":"Funk","kat":"Funk & Kommunikation","katCls":"funk","merksatz":"Funk ist die Lebensader des Wachdienstes – aber nur, wenn die Geräte richtig übergeben werden, der Empfang stimmt und der Betriebsfunk angemeldet ist.","funktion":["Handfunkgeräte-Übergabe: Bei Schichtübergabe Gerät auf Funktion, Akkuladung, richtigen Kanal und Vollständigkeit (Antenne, Akku) prüfen und quittieren.","Funkschatten: Bereiche ohne Empfang (Keller, Stahlbeton, Tiefgarage, hinter dicken Wänden) – dort ist keine Verbindung möglich; vorher bekannt machen.","Perimetersicherung: Überwachung der äußeren Geländegrenze (Perimeter) – z. B. mit Zaundetektion, Lichtschranken, Bewegungsmeldern entlang der Grenze.","Betriebsfunk: betriebliche Funkanlage auf zugeteilten Frequenzen – frequenzzuteilungs- bzw. anmeldepflichtig (Bundesnetzagentur)."],"schutzziel":"Eine zuverlässige, jederzeit verfügbare Kommunikation des Wachpersonals sicherstellen – inklusive Notruf und Koordination.","kennwerte":[{"l":"Übergabe","v":"Funktion · Akku · Kanal · Vollständigkeit"},{"l":"Funkschatten","v":"Bereiche ohne Empfang"},{"l":"Betriebsfunk","v":"frequenzzuteilungs-/anmeldepflichtig"}],"begriffe":["Funkschatten = Zone, in der wegen Abschirmung (Beton, Metall, Erde) kein Funkempfang besteht.","Perimeter = die äußere Grenze bzw. der Umkreis eines Geländes; die Perimetersicherung überwacht genau diese Linie.","Simplex/Duplex = Simplex: abwechselnd senden und empfangen (eine Frequenz); Duplex: gleichzeitig in beide Richtungen."],"abgrenzung":["Betriebsfunk (eigene zugeteilte Frequenz, anmeldepflichtig) ist nicht dasselbe wie Jedermann-Funk (PMR, frei nutzbar, geringe Reichweite).","Perimetersicherung schützt die äußere Grenze (Außenhaut des Geländes) – nicht zu verwechseln mit der Fallenüberwachung im Inneren."],"praxis":["Bei der Geräteübergabe immer quittieren – ein leerer Akku oder falscher Kanal mitten in der Schicht kann im Notfall lebensgefährlich sein.","Funkschatten vor Dienstantritt kennen: In der Tiefgarage erreichst du niemanden – plane Meldepunkte außerhalb des Schattens."]},"visual":null},{"h":"Personen-Notsignal (willensunabhängig)","b":"Lage-, Ruhe-, Zeit-, Verlust-, Fluchtalarm","detail":{"titel":"Personen-Notsignal (willensunabhängig)","kat":"Personenschutz","katCls":"funk","merksatz":"Willensunabhängig heißt: Das Notsignal geht raus, OHNE dass der Verunglückte einen Knopf drücken muss – genau dann, wenn er es selbst nicht mehr kann.","funktion":["Willensabhängig: Der Träger löst bewusst aus (Notruftaste) – z. B. bei einem Überfall.","Willensunabhängig: Das Gerät löst selbst aus, wenn der Träger handlungsunfähig ist. Typen: Lagealarm (Gerät kippt in die Waagerechte = Person liegt), Ruhealarm (keine Bewegung mehr), Zeitalarm (Quittierung im festen Intervall bleibt aus), Verlustalarm (Gerät wird abgenommen/verloren), Fluchtalarm (heftige, ruckartige Bewegung).","Einsatz: Schutz von Alleinarbeitern (z. B. einzelner Nachtwächter), die im Notfall niemand sieht."],"schutzziel":"Sicherstellen, dass auch ein bewusstloser oder bewegungsunfähiger Alleinarbeiter automatisch Hilfe bekommt.","kennwerte":[{"l":"Lagealarm","v":"Gerät/Person in Waagerechte"},{"l":"Ruhe-/Zeitalarm","v":"keine Bewegung / fehlende Quittierung"},{"l":"Verlust-/Fluchtalarm","v":"Abnahme / heftige Bewegung"}],"begriffe":["Willensunabhängiger Signalgeber = löst ohne aktives Zutun des Trägers aus (im Gegensatz zum willensabhängigen Notruf).","Alleinarbeiterschutz = Maßnahmen für Personen, die ohne direkte Hilfe in Rufweite arbeiten (PNA = Personen-Notsignal-Anlage)."],"abgrenzung":["Willensabhängig (Person drückt selbst) gegen willensunabhängig (Gerät löst selbst aus) – Letzteres ist der eigentliche Schutz für den Fall der Handlungsunfähigkeit.","Eine ÜMA wird bewusst ausgelöst (willensabhängig); ein Lage- oder Ruhealarm ist willensunabhängig."],"praxis":["Für allein arbeitendes Wachpersonal (Nachtschicht im leeren Objekt) ist die PNA oft Pflicht – fällt jemand die Treppe hinunter, geht der Lagealarm automatisch raus.","Bei Schichtbeginn das Gerät anlegen und auf Funktion prüfen – ein nicht getragenes Notsignal schützt niemanden."]},"visual":null},{"h":"Wächterkontrollsystem (WKS)","b":"Erfassung von Kontrollgängen","detail":{"titel":"Wächterkontrollsystem (WKS)","kat":"Organisation","katCls":"org","merksatz":"Ein WKS belegt schwarz auf weiß, dass der Wächter seine Runde wirklich und rechtzeitig gegangen ist – Kontrolle der Kontrolle.","funktion":["Erfassung von Kontrollgängen: An festgelegten Kontrollpunkten registriert der Wächter seine Anwesenheit (Datum, Uhrzeit, Ort).","Techniken: früher mechanische Wächterkontrolluhr mit Schlüsseln an den Punkten; heute elektronische Datenpunkte (RFID/iButton), die der Wächter mit einem Lesestift abliest.","Auswertung: Das System dokumentiert lückenlos, ob alle Punkte in der vorgegebenen Reihenfolge und Zeit erreicht wurden – Nachweis gegenüber dem Auftraggeber."],"schutzziel":"Den ordnungsgemäßen Ablauf der Kontrollgänge sicherstellen und nachweisbar dokumentieren – für Qualität und Haftung.","kennwerte":[{"l":"Erfasst","v":"Punkt · Datum · Uhrzeit"},{"l":"Früher","v":"mechanische Wächterkontrolluhr"},{"l":"Heute","v":"elektronische Datenpunkte (RFID)"}],"begriffe":["Kontrollpunkt = fest definierter Ort auf dem Rundgang, der erfasst werden muss.","Wächterkontrolluhr = mechanisches Vorläufergerät, das an Kontrollpunkten mit Schlüsseln die Uhrzeit auf einen Papierstreifen prägt."],"abgrenzung":["Ein WKS dokumentiert die Kontrollgänge des eigenen Personals (Nachweis), eine EMA meldet Gefahren (Einbruch). Zwei völlig verschiedene Zwecke.","Das WKS ist Organisation (dritte Säule) – es schützt nicht direkt, sondern sichert und belegt den Ablauf."],"praxis":["Die WKS-Daten sind ein wichtiger Nachweis: Kommt es zu einem Schaden, lässt sich belegen, dass (oder ob) die Runde gegangen wurde.","Punkte nie ‚auf Verdacht‘ abhaken oder vorab ablesen – Manipulation untergräbt den ganzen Sinn und ist ein Vertrauensbruch."]},"visual":null}],"quiz":[{"q":"Was sind Systemkomponenten von Zutrittskontrollanlagen?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Videoüberwachungskamera","c":false},{"t":"Drehkreuze, Türen","c":false},{"t":"Energieversorgung","c":true},{"t":"Bedienungseinrichtung","c":true}]},{"q":"Welche Aussagen zum Digitalfunk sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Er ist störanfälliger und leistungsschwächer als der Analogfunk","c":false},{"t":"Er gewährt eine bessere Sprachqualität und unterdrückt störende Hintergrundgeräusche","c":true},{"t":"Er ist leicht abzuhören, d.h., der Datenschutz ist nicht gesichert","c":false},{"t":"Er bietet eine Notruffunktion mit Ortungsmöglichkeit","c":true}]},{"q":"Welche Bedienungsfehler können dazu führen, dass bei Funkgeräten kein Funkkontakt herzustellen ist?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Geräteantenne abgebrochen","c":false},{"t":"Funkgerät ist nicht eingeschaltet","c":true},{"t":"Akku ist wegen eines Kurzschlusses leer","c":false},{"t":"Falscher Kanal ist gewählt","c":true}]},{"q":"Was bedeutet der Duplex-Betrieb beim Funkbetrieb?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Datenübertragung ist nur abwechselnd in beiden Richtungen einer Telekommunikationsverbindung möglich","c":false},{"t":"Die Datenübertragung ist gleichzeitig in beiden Richtungen einer Telekommunikationsverbindung möglich","c":true},{"t":"Die Datenübertragung ist nur in eine Richtung möglich","c":false},{"t":"Die Datenübertragung ist nur zwischen zwei ortsfesten Funkstellen möglich","c":false}]},{"q":"Was ist ein ZKS (Zutrittkontrollsystem) und wie es aufgebaut?","a":"Zutrittskontrolle steuert den Zutritt über ein vom Betreiber festgelegtes Regelwerk \"„WER-WANN-WOHIN“, damit nur berechtigte Personen Zugang zu den für sie freigegebenen Bereichen in Gebäuden oder geschützten Arealen auf einem Gelände erhalten. Aufbau durch Drehkreuze, Schleusen wo man erst nach Kontrolle(Ausweisleser) Zutritt bekommt.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine Personenvereinzelungsanlage?","a":"Vereinzelungsanlagen sind bauliche Anlagen zur Zutrittskontrolle zu einem Raum oder Gelände. Hierbei können Personen hinsichtlich ihrer Berechtigung kontrolliert werden z.B. Drehkreuz, Drehsperre, Sensorschleuse, Personenschleuse","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist die Schwachstelle einer Zaunanlage?","a":"- Öffnungen wie z.B. LKW Zufahrten, Personaleingänge. Diese sind z.B. durch automatische Rolltore oder Personenvereinzelungsanlagen zu sichern","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie 4 Arten von Ausweislesern?","a":"- Einsteckleser - Durchzugleser - Einzugleser - Abstandsleser","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine ÜMA, welche Funktionsweise?","a":"ÜMA ist eine Überfallmeldeanlage - Immer Scharfgeschaltet - Alarmauslösung durch Notdrückknopf, Tretleiste, Geldscheinkontakt, Codiereinrichtung - Löst ein stillen Alarm aus über die AWUG an Polizei","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet EMA und BMA, Funktionsweise erklären?","a":"- EMA ist eine Einbruchsmeldeanlage; Meldet einen Einbruchsalarm und ist in der Regel nach Feierabend aktiviert; Fernmeldeanlage/Scharfgeschaltet - BMA ist eine Brandmeldeanlage; Meldet einen Brand, ist immer aktiv. Hat die Möglichkeit Systeme zu steuern, z.B. Aufzüge stoppen, Sprinkler auslösen etc. Es gibt Melder die über die Meldelinie mit der Meldezentrale verbunden sind und bei Gefahr auslösen, die Meldzentrale löst dann Alarm aus, aktiviert die Signalgeber überträgt über die AWUG den Alarm zur Polizei, Feuerwehr oder NSL oder gibt Nachrichten durch die AWAG an das Personal, Zuschauer durch. Läuft über Netzstrom und AKKU bei Stromausfall. Wird Scharfgestaltet mit Blockschloss bei der EMA, - BMA und ÜMA sind immer scharfgeschaltet.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Rauchmelder, Funktion eines Streulichtmelders?","a":"- Rauchmelder - Wärmemelder - Flammenmelder Im Inneren eines Rauchmelders befindet sich eine Leuchtdiode, die ständig einen Lichtstrahl aussendet, und eine Fotodiode. Im Ruhezustand trifft der Lichtstrahl NICHT auf die Fotodiode - und der Rauchmelder gibt keinen Alarm. Tritt Rauch in den Rauchmelder ein, wird der Lichtstrahl abgelenkt die Fotodiode empfängt den Lichtstrahl und löst den Alarm aus. (er wird \"gestreut\" - daher der Begriff \"Streulichtmelder\").","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wie funktioniert ein Wärmemaximalmelder?","a":"Der Wärmemaximalmelder misst die Temperatur und löst bei erreichen einer bestimmten Temperatur Alarm aus.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was muss man bei der Übergabe von Handfunkgeräten beachten?","a":"- Zustand des Akku - Richtige Kanal Einstellung - Beschädigungen (Gehäuse, Antenne, Bedienelemente) - Sprechprobe","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erkläre die Begriffe Funkschatten und Perimeter Sicherung?","a":"Ein Funkloch/Funkschatten ist ein räumlicher Bereich, in der eine Verbindung zwischen einem Sender und einem Empfänger nicht möglich ist. Unter Perimeter Schutz (Freilandschutz) versteht man mechanische und bauliche Perimeter Sicherung, sowie organisatorische und personelle Maßnahmen zum Schutz eines Objektes. z.B. Zaunstreife, Mikrowellenrichtstrahl, Videoüberwachung","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet Betriebsfunk und muss dieser angemeldet werden?","a":"Bei einen Betriebsfunk (Reichweite ca. 20 km.) hat man einen eigen Funkkanal und muss bei der Bundesnetzagentur beantragt werden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind willensunabhängige Signalgeber?","a":"Willensunabhängiger Personen-Alarm ist z.B. ein Alarm der im Personen- Notsignalgerät (PNG) nach einer Reaktionszeit durch eine der folgenden Einrichtungen ausgelöst wird: - Lagealarm (Totmannschalter) wird nach einer vorgegeben Zeit ausgelöst, sobald ein bestimmter Neigungswinkel des PNG überschritten wird (In der Regel 30-45 Grad) - Ruhealarm wird nach einer vorgegebenen Zeit bei Bewegungslosigkeit des PNG ausgelöst - Zeitalarm wird nach Ausbleiben einer angeforderten Quittung durch den Träger ausgelöst - Verlustalarm wird nach einer vorgegebenen Zeit bei Verlust des PNG ausgelöst - Fluchtalarm wird nach einer vorgegebenen Zeit bei hektischen Bewegungen des Trägers ausgelöst","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist ein WKS (Wächterkontrollsystem)?","a":"Ein Wächterkontrollsystem hält fest wann und wo der Sicherheitsmitarbeiter kontrolliert hat, die Daten werden z.B. über einen Deister bei den Kontrollstellen abgelesen und nachher ausgelesen.","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[{"scenario":"Mitten im Dienst bekommst du über Funk keinen Kontakt zur Leitstelle. Ein Kollege sagt sofort: Das Gerät ist kaputt, die Antenne ist hin.","frage":"Welche Ursachen prüfst du zuerst – und warum nicht gleich Defekt?","loesung":"Zuerst die typischen BEDIENFEHLER ausschließen: Ist das Gerät eingeschaltet? Stimmt der Kanal? Ist der Akku geladen und richtig eingesetzt? Lautstärke? Diese harmlosen Ursachen sind weit häufiger als ein echter Defekt. Denkschlüssel: Erst die einfachen, bedienbaren Fehlerquellen prüfen, bevor man auf Hardware-Defekt schließt – erst denken, dann tauschen. (Digitalfunk böte hier zusätzlich Notruf mit Ortung.)"},{"scenario":"Ein Objekt hat eine moderne Zutrittskontrolle mit Ausweislesern. Trotzdem gelangen Unbefugte hinein, weil Mitarbeiter höflich die Tür aufhalten.","frage":"Wie heißt dieses Problem – und was löst es technisch?","loesung":"Das ist Mitgehen bzw. Tailgating – die beste Zutrittskontrolle nützt nichts, wenn mehrere Personen mit einer Freigabe durchgehen. Technisch löst es eine Personenvereinzelung (Drehkreuz, Drehsperre, Personenschleuse), die nur eine Person je Freigabe durchlässt; organisatorisch hilft das Sensibilisieren der Mitarbeiter. Denkschlüssel: Die Zutrittskontrolle prüft die Berechtigung, die Vereinzelung erzwingt eine Person je Freigabe – beides gehört zusammen."}]},{"n":5,"title":"Brandschutz","subtitle":"4 Konzepte · 9 Prüfungsfragen","cards":[{"h":"Brandschutz-Unterteilung","b":"Vorbeugender vs. abwehrender Brandschutz","detail":{"titel":"Brandschutz-Unterteilung","kat":"Brandschutz","katCls":"brand","merksatz":"Brandschutz heißt zuerst verhindern, dann bekämpfen: Der vorbeugende Brandschutz sorgt dafür, dass es gar nicht brennt – der abwehrende, dass ein Brand gelöscht wird.","funktion":["Vorbeugender Brandschutz – verhindert Entstehung und Ausbreitung. Drei Bereiche: baulich (feuerhemmende Wände, Brandabschnitte, Fluchtwege), anlagentechnisch (BMA, Sprinkler, Rauchabzug) und organisatorisch (Brandschutzordnung, Unterweisungen, Kontrollen).","Abwehrender Brandschutz – bekämpft den bereits entstandenen Brand: Feuerwehr, Löscheinsatz, Menschenrettung.","Mitverantwortung der Wachperson: Bei Kontrollgängen wirkt sie sowohl beim vorbeugenden (Mängel erkennen, Fluchtwege prüfen) als auch beim abwehrenden Brandschutz (Entstehungsbrände melden und bekämpfen) mit."],"schutzziel":"Brände von vornherein verhindern und ihre Ausbreitung begrenzen – und im Ernstfall Menschen retten und den Brand bekämpfen.","kennwerte":[{"l":"Vorbeugend","v":"baulich · anlagentechnisch · organisatorisch"},{"l":"Abwehrend","v":"Feuerwehr, Löschen, Retten"},{"l":"Wachperson","v":"Mitverantwortung bei beiden"}],"begriffe":["Baulicher Brandschutz = feuerbeständige Bauteile, Brandabschnitte und Brandwände, die die Ausbreitung begrenzen.","Organisatorischer Brandschutz = Regeln und Maßnahmen: Brandschutzordnung, Unterweisung, Brandschutzkontrollen, Freihalten der Fluchtwege.","Anlagentechnischer Brandschutz = technische Anlagen wie BMA, Sprinkler, Rauch- und Wärmeabzug."],"abgrenzung":["Vorbeugend (verhindern, bevor es brennt) gegen abwehrend (bekämpfen, wenn es brennt). Das Erkennen und Melden von Bränden gehört zum abwehrenden Brandschutz, das Planen von Kontrollen zum organisatorisch-vorbeugenden.","Schwer entflammbares Material einzubauen ist baulicher Brandschutz – eine Brandschutzordnung aufzustellen ist organisatorischer Brandschutz."],"praxis":["Als Wachkraft bist du Teil des vorbeugenden Brandschutzes: Du hältst Fluchtwege frei, prüfst Brandschutztüren und meldest Mängel – und im Ernstfall Teil des abwehrenden (melden, Entstehungsbrand löschen).","Eine mit Keil offengehaltene Brandschutztür ist der häufigste Mangel: Sie kann ihre Funktion (Rauch- und Feuerabschluss) nicht erfüllen."]},"visual":null},{"h":"Brandklassen & Löschmittel","b":"A–F; passende Löschmittel je Klasse","detail":{"titel":"Brandklassen & Löschmittel","kat":"Brandschutz","katCls":"brand","merksatz":"Jeder Brand hat seine Klasse – und nur das passende Löschmittel löscht ihn. Das falsche Mittel kann den Brand sogar verschlimmern.","funktion":["Brandklasse A – feste, glutbildende Stoffe (Holz, Papier, Textilien): Wasser, Schaum, ABC-Pulver.","Brandklasse B – flüssige oder flüssig werdende Stoffe (Benzin, Lacke, Teer, Alkohole, Wachs): Schaum, CO2, ABC-/BC-Pulver.","Brandklasse C – Gase (Propan, Erdgas, Acetylen): nur BC-/ABC-Pulver – zuerst die Gaszufuhr absperren!","Brandklasse D – Metalle (Magnesium, Aluminium, Natrium): nur Spezial-Metallbrandpulver (D-Pulver), niemals Wasser.","Brandklasse F – Speiseöle und -fette in Frittiergeräten: nur Fettbrandlöscher (Klasse F), niemals Wasser (Fettexplosion!)."],"schutzziel":"Den Brand mit dem zur Brandklasse passenden Löschmittel sicher und vollständig löschen – ohne ihn durch ein falsches Mittel zu verschlimmern.","kennwerte":[{"l":"A (fest)","v":"Wasser, Schaum, Pulver"},{"l":"B (flüssig)","v":"Schaum, CO2, Pulver"},{"l":"C·D·F","v":"Pulver · D-Pulver · Fettbrandlöscher"}],"begriffe":["Brandkenngrößen = die Begleiterscheinungen eines Brandes: Rauch, Wärme, Flammen und Brandgase – an ihnen erkennt und meldet man Brände.","Löschwirkungen: Ersticken (Sauerstoff entziehen, z. B. CO2/Schaum), Abkühlen (Wärme entziehen, z. B. Wasser), Trennen und Inhibition (Eingriff in die Verbrennung, z. B. Pulver)."],"abgrenzung":["Es gibt keine Brandklasse E mehr – Brände in elektrischen Anlagen sind keine eigene Klasse; man löscht nach dem brennenden Stoff und beachtet die Spannung (Abstand halten, abschalten).","Wasser ist universell für Klasse A, aber gefährlich bei Fett (F), Metall (D) und unter Spannung – hier niemals Wasser."],"praxis":["Lacke, Teer und Alkohole sind Brandklasse B (flüssig) – ein klassischer Prüfungsfall. Ein Wasservollstrahl ist hier falsch.","Den Fettbrand in der Küche niemals mit Wasser löschen – das Wasser verdampft schlagartig und schleudert brennendes Fett heraus (Fettexplosion). Deckel drauf oder Fettbrandlöscher."]},"visual":null},{"h":"Brandbekämpfung","b":"Regeln mit Handfeuerlöschern; Taktik Melden-Retten-Bekämpfen","detail":{"titel":"Brandbekämpfung","kat":"Brandschutz","katCls":"brand","merksatz":"Erst Menschen, dann Feuer: Die Reihenfolge im Brandfall lautet Retten – Melden – Löschen, und gelöscht wird nur, was ohne Eigengefährdung geht.","funktion":["Taktik im Brandfall: 1. Retten (Menschen in Sicherheit), 2. Melden (Feuerwehr 112 alarmieren), 3. Löschen (nur Entstehungsbrände, ohne sich zu gefährden). Parallel: Türen schließen, Fluchtwege frei halten.","Regeln mit dem Handfeuerlöscher: mit dem Wind (Zug im Rücken); von vorn und unten in die Glut löschen; Flächenbrände vorn beginnend, Tropf- und Fließbrände von oben nach unten zur Brandstelle; genug Abstand halten.","Mehrere Löscher gleichzeitig einsetzen, nicht nacheinander – und nach dem Löschen die Brandstelle beobachten (Rückzündung)."],"schutzziel":"Einen Entstehungsbrand wirksam bekämpfen und dabei Menschen retten, ohne sich selbst in Gefahr zu bringen.","kennwerte":[{"l":"Reihenfolge","v":"Retten → Melden → Löschen"},{"l":"Richtung","v":"mit dem Wind, von vorn & unten"},{"l":"Tropf-/Fließbrand","v":"von oben nach unten zur Brandstelle"}],"begriffe":["Entstehungsbrand = ein gerade erst entstandener, noch kleiner Brand, der mit einem Handfeuerlöscher beherrschbar ist.","Rückzündung = erneutes Aufflammen nach scheinbarem Löscherfolg – deshalb die Brandstelle weiter beobachten."],"abgrenzung":["Flächenbrände löscht man vorn beginnend und arbeitet sich vor; Tropf- und Fließbrände dagegen von oben (der Austrittsstelle) nach unten – die Richtung ist je nach Brandart verschieden.","Löschen ist die LETZTE Stufe nach Retten und Melden – nie zuerst löschen und dabei Menschenrettung oder Notruf vergessen."],"praxis":["Nur löschen, solange es ohne Eigengefährdung möglich ist und der Fluchtweg im Rücken frei bleibt – im Zweifel zurückziehen und der Feuerwehr überlassen.","Beim Öffnen einer heißen Tür Vorsicht: dahinter kann eine Stichflamme schlagen. Türen zu Brandräumen möglichst geschlossen halten."]},"visual":null},{"h":"Feuerlöscher & Sprinkler","b":"Prüfintervall (2 Jahre); Dauerdruck/Auflade; Nass-/Trockensprinkler","detail":{"titel":"Feuerlöscher & Sprinkler","kat":"Brandschutz","katCls":"brand","merksatz":"Ein Feuerlöscher hilft nur, wenn er funktioniert: regelmäßig geprüft, richtig gewählt und im Notfall griffbereit – die Sprinkleranlage löscht sogar von selbst.","funktion":["Bauarten des Feuerlöschers: Dauerdrucklöscher (steht ständig unter Druck) und Aufladelöscher (Treibgas in separater Patrone; wird erst beim Auslösen unter Druck gesetzt).","Prüfung: Feuerlöscher müssen regelmäßig, mindestens alle 2 Jahre, von einem Sachkundigen geprüft werden (Prüfplakette).","Sprinkleranlage: löscht automatisch an der Brandstelle. Nasssprinkler – Rohre ständig wassergefüllt (für frostfreie Bereiche); Trockensprinkler – Rohre mit Luft/Gas gefüllt, Wasser strömt erst im Brandfall nach (für frostgefährdete Bereiche)."],"schutzziel":"Die ständige Funktionsbereitschaft der Löschmittel sicherstellen – manuell (Feuerlöscher) und automatisch (Sprinkler).","kennwerte":[{"l":"Prüfintervall","v":"mind. alle 2 Jahre (Sachkundiger)"},{"l":"Bauarten","v":"Dauerdruck- · Aufladelöscher"},{"l":"Sprinkler","v":"nass (frostfrei) · trocken (frostgefährdet)"}],"begriffe":["Aufladelöscher = Behälter und Treibmittel sind getrennt (eigene Druckpatrone); beide werden gesondert geprüft. Beim Auslösen setzt die Patrone das Löschmittel unter Druck.","Dauerdrucklöscher = Löschmittel und Treibgas stehen ständig gemeinsam unter Druck im Behälter.","Nass-/Trockensprinkler = unterscheiden sich darin, ob das Rohrnetz ständig mit Wasser (nass) oder mit Luft/Gas (trocken) gefüllt ist."],"abgrenzung":["Nasssprinkler reagieren schneller, dürfen aber nur in frostfreien Bereichen eingesetzt werden; Trockensprinkler eignen sich für frostgefährdete Bereiche (Tiefgarage, unbeheiztes Lager), reagieren aber etwas verzögert.","Beim Aufladelöscher steckt die Patrone NICHT zwingend im Behälterinneren, und das Löschmittel wird NICHT manuell, sondern durch die Patrone unter Druck gesetzt."],"praxis":["Bei der Begehung prüfst du: Ist der Feuerlöscher vorhanden, unverstellt, gut sichtbar, plombiert und die Prüfplakette gültig (Datum)? Ein abgelaufener oder verstellter Löscher ist ein Mangel.","Sprinklerköpfe nie zustellen oder überstreichen – das verhindert die Auslösung; auch das ist ein typischer Streifenfund."]},"visual":null}],"quiz":[{"q":"Wobei haben Wachpersonen im Rahmen ihrer Kontrolltätigkeit eine Mitverantwortung?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Beim baulichen betrieblichen Brandschutz","c":false},{"t":"Beim abwehrenden betrieblichen Brandschutz","c":true},{"t":"Beim organisatorischen betrieblichen Brandschutz","c":false},{"t":"Beim vorbeugenden betrieblichen Brandschutz","c":true}]},{"q":"Worauf müssen Wachpersonen bei der Kontrolle von Fluchtwegen und Fluchttüren in einem Sicherungsobjekt achten?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Dass die Schlüssel für Notausgangstüren in einem Schlüsselkasten bereitgehalten werden","c":false},{"t":"Dass sich die Notausgangstüren in Fluchtrichtung öffnen lassen","c":true},{"t":"Dass auf den Fluchtwegen abgestellte Gegenstände im Notfall schnell weggeräumt werden können","c":false},{"t":"Dass die vorhandene Sicherheitsbeleuchtung intakt ist","c":true}]},{"q":"Welche Aussagen zu Fluchtwegen und Notausgängen sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Fluchtwege und Notausgänge müssen ständig frei gehalten werden, damit sie jederzeit benutzt werden können","c":true},{"t":"Müssen Notausgangstüren mit einem Schlüssel geöffnet werden, muss sich neben der Tür ein Schlüsselkasten mit passendem Schlüssel befinden","c":false},{"t":"Aufzüge sind als Teil des Fluchtweges zulässig, damit Menschen auf dem schnellsten Weg ins Freie gelangen können","c":false},{"t":"Fluchtwege sind Verkehrswege, die der Flucht aus einem möglichen Gefährdungsbereich und zugleich der Rettung von Personen dienen","c":true}]},{"q":"Welche Löschtaktik ist zur Bekämpfung von Tropf- und Fließbränden geeignet?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Nacheinander mit mehreren Handfeuerlöschern löschen, um Löschreserven zu bilden","c":false},{"t":"Löschen von unten nach oben zur Brennstoffquelle hin","c":false},{"t":"Löschen mit einem Wasservollstrahl","c":false},{"t":"Löschen von oben nach unten zum Brandherd hin","c":true}]},{"q":"Wie wirkt das Löschmittel Kohlendioxid?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Durch Trennen","c":false},{"t":"Durch Abkühlen","c":false},{"t":"Durch Inhibition","c":false},{"t":"Durch Ersticken","c":true}]},{"q":"Welche Maßnahmen gehören zum organisatorischen vorbeugenden Brandschutz?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Der Einbau von schwer entflammbarem Material","c":false},{"t":"Das Aufstellen einer Brandschutzordnung","c":true},{"t":"Die Planung von Brandschutzkontrollen","c":true},{"t":"Die Erkennung und Bekämpfung von Bränden","c":false}]},{"q":"Welche Aussagen treffen auf einen Aufladelöscher zu?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Aufladepatrone befindet sich immer im Behälterinneren. So wird sie vor äußeren Einwirkungen geschützt","c":false},{"t":"Vor dem Löscheinsatz muss erst das Löschmittel manuell unter Druck gesetzt werden","c":false},{"t":"Behälter und Druckpatrone werden gesondert geprüft. Ihre Funktionssicherheit wird durch gesonderte Prüfsiegel nachgewiesen","c":true},{"t":"Durch das Auslösen der Aufladepatrone wird das Löschmittel unter Druck gesetzt","c":true}]},{"q":"Welcher Brandklasse sind die Stoffe Lacke, Teer und Alkohole zugeordnet?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Brandklasse B","c":true},{"t":"Brandklasse F","c":false},{"t":"Brandklasse A","c":false},{"t":"Brandklasse D","c":false},{"t":"Brandklasse C","c":false}]},{"q":"Wie ist der Brandschutz unterteilt?","a":"- Vorbeugender Brandschutz, Feuertüren, BMA, Brandwände, Feuerlöscher,... - Abwehrender Brandschutz, Brandentdeckung, Brandort, Menschen retten, Brand bekämpfen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie die Brandklassen und Brandkenngrößen.","a":"- A für Feste Stoffe - B für Flüssige Stoffe - C für Gase - D für Metalle - F für Fette","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welches Löschmittel ist für welche Brandklasse?","a":"- A Wasser, Schaum, ABC-Pulver - B Schaum, ABC-Pulver - C Kohlendioxid, ABC-Pulver - D Metallbrandpulver, trockener Sand, trockenes Salz, trockener Zement - F spezielle Fettbrandlöscher Elektrogeräte und Leitungen sind die häufigste Ursache von Bränden. Die meisten Feuerlöscher sind für Elektrobrände von unter 1000 Volt zulässig. Dabei ist aber immer ein entsprechender Sicherheitsabstand (Aufdruck Feuerlöscher) erforderlich.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Regeln bei der Brandbekämpfung mit Handfeuerlöschern.","a":"- Windrichtung beachten - Flächenbrände von vorn löschen - Tropfbrände von oben nach unten - Wandbrände von unten nach oben - Mehrere Löscher gleichzeitig einsetzten, wenn vorhanden - Nach Gebrauch austauschen oder auffüllen","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Taktik der Brandbekämpfung?","a":"Melden - Retten - Bekämpfen; Ausnahme Entstehungsbrand (z.B. Mülleimer fängt gerade an zu brennen); Hier reicht bekämpfen mit Handlöscher","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was bedeutet EMA und BMA, Funktionsweise erklären?","a":"- EMA ist eine Einbruchsmeldeanlage; Meldet einen Einbruchsalarm und ist in der Regel nach Feierabend aktiviert; Fernmeldeanlage/Scharfgeschaltet - BMA ist eine Brandmeldeanlage; Meldet einen Brand, ist immer aktiv. Hat die Möglichkeit Systeme zu steuern, z.B. Aufzüge stoppen, Sprinkler auslösen etc. Es gibt Melder die über die Meldelinie mit der Meldezentrale verbunden sind und bei Gefahr auslösen, die Meldzentrale löst dann Alarm aus, aktiviert die Signalgeber überträgt über die AWUG den Alarm zur Polizei, Feuerwehr oder NSL oder gibt Nachrichten durch die AWAG an das Personal, Zuschauer durch. Läuft über Netzstrom und AKKU bei Stromausfall. Wird Scharfgestaltet mit Blockschloss bei der EMA, - BMA und ÜMA sind immer scharfgeschaltet.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Bestandteile einer BMA?","a":"- Meldezentrale - Signalgeber - Meldelinie - Melder (Rauchmelder, Wärmemelder, Flammenmelder, Druckknopfmelder) - AWAG - AWUG - Netzstrom, AKKU - Automatische auslösen von Sprinkleranlage, Klimaanlage, schliesen von Brandschutztüren,...","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Feuerlöscher müssen in welchen Zeitraum geprüft werden und","a":"welche Feuerlöscher kennen Sie? Feuerlöscher müssen alle zwei Jahre überprüft werden. - Dauerdruck-Feuerlöscher, stehen ständig unter Druck und sind sofort einsatzbereit - Auflade-Feuerlöscher, stehen nicht unter Druck, müssen durch betätigen einer Treibmittelpatrone unter Druck gesetzt werden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Unterschied Nass- und Trockensprinkleranlage?","a":"- Nasssprinkleranlage werden im Innenräumen eingesetzt - Trockensprinkleranlagen werden außerhalb eingesetzt (friert nicht ein)","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[{"scenario":"In der Betriebsküche gerät heißes Frittierfett in Brand. Reflexartig greift ein Mitarbeiter zum Wasserlöscher.","frage":"Warum ist das hochgefährlich – und was ist richtig?","loesung":"Auf keinen Fall Wasser! Ein Fettbrand ist Brandklasse F. Wasser verdampft schlagartig im heißen Fett und schleudert brennendes Fett explosionsartig heraus (Fettexplosion). Richtig: Fettbrandlöscher (Klasse F) oder Ersticken durch Abdecken, dazu Energiezufuhr abschalten. Denkschlüssel: Erst die Brandklasse bestimmen, dann das Löschmittel – Wasser ist bei Fett (Klasse F) und an elektrischen Anlagen tabu."},{"scenario":"Bei der Kontrolle findest du eine Notausgangstür, die nur mit Schlüssel zu öffnen ist. Daneben hängt – vom Hausmeister praktisch eingerichtet – ein Schlüsselkasten mit dem passenden Schlüssel.","frage":"Ist das in Ordnung? Was forderst du?","loesung":"Nein. Flucht- und Notausgangstüren müssen sich im Notfall jederzeit OHNE Schlüssel und Hilfsmittel in Fluchtrichtung öffnen lassen (Panikschloss). Ein Schlüsselkasten daneben ist keine zulässige Lösung – bei Rauch, Panik und Hektik ist der Schlüssel oft nicht nutzbar. Zudem müssen Fluchtwege ständig frei und die Sicherheitsbeleuchtung intakt sein. Denkschlüssel: Eine Fluchttür, die man erst aufschließen muss, ist im Ernstfall eine Falle."},{"scenario":"In einem kleinen, fensterlosen Technikraum brennt es. Ein Mitarbeiter will den großen CO2-Löscher einsetzen und dabei im Raum bleiben, bis das Feuer aus ist.","frage":"Welche Gefahr übersieht er?","loesung":"CO2 löscht durch Ersticken – es verdrängt den Sauerstoff. In einem kleinen, schlecht belüfteten Raum entsteht dadurch auch für den Menschen Erstickungsgefahr. Richtig: kurz und gezielt löschen, den Rückzug sichern und nicht im gefluteten Raum verbleiben. Denkschlüssel: Was dem Feuer den Sauerstoff nimmt, nimmt ihn auch dir – CO2 in engen Räumen nur mit Vorsicht und freiem Fluchtweg."},{"scenario":"Bei deiner Streife entdeckst du in einer Lagerhalle einen bereits mannshohen, sich schnell ausbreitenden Brand mit starker Rauchentwicklung.","frage":"Greifst du mit dem Handfeuerlöscher an?","loesung":"Nein. Ein Handfeuerlöscher ist nur für Entstehungsbrände gedacht. Bei einem bereits ausgedehnten Brand mit starker Rauchentwicklung gilt: Menschen warnen und in Sicherheit bringen, Feuerwehr alarmieren (112), Türen und Brandabschnitte schließen, Selbstschutz beachten – kein aussichtsloser Löschangriff. Denkschlüssel: Handlöscher gleich Entstehungsbrand; ist der Brand größer als das, zählen Alarmieren und Retten, nicht Löschen."}]}],"cardCount":25,"quizCount":78},{"id":"s34a-7","tg":7,"name":"Waffenrecht / Umgang mit Waffen","color":"var(--stack-lavender)","meta":{"relevanz":"Niedrig","schriftlich":"4 Fragen · 4/100 Punkte","muendlich":"—"},"merksaetze":["WBK heißt: besitzen. Waffenschein heißt: führen.","Transport: ungeladen, verschlossen, nicht zugriffsbereit.","Besitz erlaubt? Führen kann trotzdem verboten sein.","Im Sicherheitsdienst gelten WaffG, DGUV V23, Auftrag und Dienstanweisung zusammen.","Verbotene Gegenstände gehören nicht in die Tasche, sondern in die Fallprüfung.","Ein guter Sicherheitsmitarbeiter kennt nicht nur Gegenstände, sondern Grenzen. Klingt banal, verhindert aber Katastrophen."],"blocks":[{"n":1,"title":"Grundbegriffe Waffenrecht","subtitle":"5 Konzepte · 21 Prüfungsfragen","cards":[{"h":"Rechtsnormen","b":"WaffG (wichtigste), BewachV, DGUV V23","detail":{"titel":"Rechtsnormen des Waffenrechts","kat":"Grundbegriffe · Rechtsquellen","katCls":"waff","merksatz":"Das Waffenrecht steht vor allem im Waffengesetz (WaffG) mit seinen Anlagen, ergänzt durch die Allgemeine Waffengesetz-Verordnung (AWaffV). Fürs Bewachungsgewerbe kommen § 28 WaffG, GewO/BewachV und die DGUV Vorschrift 23 hinzu.","funktion":["Waffengesetz (WaffG): das zentrale Gesetz – regelt Begriffe, Umgang, Erlaubnisse, Verbote. Die ANLAGEN zum WaffG enthalten die genauen Definitionen und Listen (z. B. verbotene Waffen).","AWaffV (Allgemeine Waffengesetz-Verordnung): konkretisiert das WaffG, u. a. Aufbewahrung und Sachkunde.","Für Wachkräfte zusätzlich: § 28 WaffG (Bewachungsunternehmen), GewO/BewachV (Dienstanweisung, Zustimmung zum Waffenführen) und die DGUV Vorschrift 23 (Anforderungen an Schusswaffenträger)."],"schutzziel":"Den Umgang mit Waffen lückenlos regeln – wer darf was, womit, unter welchen Voraussetzungen.","kennwerte":[{"l":"Zentrale Norm","v":"Waffengesetz (WaffG) + Anlagen"},{"l":"Verordnung","v":"AWaffV"},{"l":"Bewachung","v":"§ 28 WaffG · BewachV · DGUV V23"}],"begriffe":["Anlagen zum WaffG = die zum Gesetz gehörenden Listen und Begriffsbestimmungen (besonders Anlage 1 und 2).","AWaffV = Verordnung, die Einzelheiten zum WaffG regelt (z. B. Aufbewahrung)."],"abgrenzung":["Das WaffG regelt den UMGANG mit Waffen (Besitz, Führen …). Der EINSATZ einer Waffe zur Verteidigung richtet sich dagegen nach Notwehr/Notstand (StGB/BGB).","Fürs Bewachungsgewerbe gelten WaffG und Gewerberecht (GewO/BewachV) nebeneinander – beide müssen beachtet werden."],"praxis":["Für dich als Wachkraft sind die praktisch wichtigsten Fragen: Was ist eine Waffe? Darf ich sie führen? Brauche ich eine Erlaubnis und die Zustimmung des Arbeitgebers?","Im Zweifel gilt: Ohne ausdrückliche Erlaubnis und Zustimmung keine Waffe im Dienst."]},"visual":null},{"h":"Umgang mit Waffen","b":"Erwerben, besitzen, überlassen, führen, verbringen, herstellen…","detail":{"titel":"Umgang mit Waffen","kat":"Grundbegriffe · Umgang","katCls":"waff","merksatz":"‚Umgang‘ ist der Oberbegriff des WaffG für nahezu alles, was man mit einer Waffe tun kann: erwerben, besitzen, überlassen, führen, verbringen, mitnehmen, herstellen, bearbeiten, instand setzen und damit schießen. Fast jeder Umgang ist erlaubnispflichtig.","funktion":["Erwerb & Besitz: eine Waffe an sich nehmen bzw. die tatsächliche Gewalt darüber ausüben.","Führen: die tatsächliche Gewalt über eine Waffe AUSSERHALB der eigenen Wohnung, Geschäftsräume oder des befriedeten Besitztums ausüben (dazu eigene Karte).","Weitere Formen: Überlassen, Verbringen/Mitnehmen, Herstellen, Bearbeiten, Schießen – jede dieser Handlungen ist ‚Umgang‘ im Sinne des Gesetzes."],"schutzziel":"Alle denkbaren Handlungen mit Waffen unter einen Begriff fassen, damit das Gesetz lückenlos festlegen kann, was erlaubnispflichtig oder verboten ist.","kennwerte":[{"l":"Oberbegriff","v":"fast jede Handlung mit einer Waffe"},{"l":"Beispiele","v":"Erwerb · Besitz · Führen · Schießen"},{"l":"Grundregel","v":"Umgang ist grundsätzlich erlaubnispflichtig"}],"begriffe":["Erwerb = die tatsächliche Gewalt über eine Waffe erlangen.","Besitz = die tatsächliche Gewalt über eine Waffe ausüben (auch ohne Eigentum)."],"abgrenzung":["Besitz (zu Hause/in Geschäftsräumen) ist etwas anderes als Führen (außerhalb davon) – beide sind ‚Umgang‘, brauchen aber unterschiedliche Erlaubnisse (WBK gegen Waffenschein).","Wer keine der genannten Handlungen vornimmt, hat keinen ‚Umgang‘ – z. B. das bloße Betrachten in einem Schaufenster."],"praxis":["Praktisch wichtig: Schon das BESITZEN einer erlaubnispflichtigen Waffe braucht eine Erlaubnis (WBK). Das FÜHREN im Dienst braucht zusätzlich Waffenschein und Zustimmung.","Wer eine Waffe nur transportiert (z. B. zum Schießstand), betreibt ebenfalls ‚Umgang‘ – mit eigenen Regeln (nicht zugriffs- und nicht schussbereit)."],"visual":{"type":"chain","steps":[{"label":"Erwerben","desc":"tatsächliche Gewalt erlangen"},{"label":"Besitzen","desc":"tatsächliche Gewalt ausüben"},{"label":"Führen","desc":"außerhalb eigener Räume zugriffsbereit bei sich haben","highlight":true},{"label":"Überlassen","desc":"tatsächliche Gewalt einem anderen einräumen"},{"label":"Transport","desc":"nicht schuss- und nicht zugriffsbereit"}]}},"visual":{"type":"chain","steps":[{"label":"Erwerben","desc":"tatsächliche Gewalt erlangen"},{"label":"Besitzen","desc":"tatsächliche Gewalt ausüben"},{"label":"Führen","desc":"außerhalb eigener Räume zugriffsbereit bei sich haben","highlight":true},{"label":"Überlassen","desc":"tatsächliche Gewalt einem anderen einräumen"},{"label":"Transport","desc":"nicht schuss- und nicht zugriffsbereit"}]}},{"h":"Waffen / Schusswaffen / Feuerwaffen","b":"Definitionen; Geschosse durch Lauf; heiße Gase bei Feuerwaffen","detail":{"titel":"Waffen, Schusswaffen & Feuerwaffen","kat":"Grundbegriffe · Waffenarten","katCls":"waff","merksatz":"Das WaffG staffelt die Begriffe: WAFFEN (Oberbegriff) umfassen Schusswaffen und tragbare Gegenstände. SCHUSSWAFFEN treiben Geschosse durch einen Lauf. FEUERWAFFEN sind Schusswaffen, bei denen der Antrieb durch heiße Gase (Treibladung) erfolgt.","funktion":["Waffen (Oberbegriff): Schusswaffen UND ihnen gleichgestellte tragbare Gegenstände (Hieb-, Stoß-, Reizstoffwaffen u. a.).","Schusswaffen: Gegenstände, mit denen feste Körper (Geschosse) durch einen Lauf getrieben werden.","Feuerwaffen: Schusswaffen, bei denen das Geschoss durch heiße Gase aus einer Treibladung (Munition) angetrieben wird – die ‚scharfe‘ Schusswaffe."],"schutzziel":"Klare Begriffe schaffen, damit das Gesetz die Gefährlichkeit abstufen und passende Regeln zuordnen kann.","kennwerte":[{"l":"Waffe","v":"Oberbegriff: Schusswaffen + tragbare Gegenstände"},{"l":"Schusswaffe","v":"Geschoss durch einen Lauf"},{"l":"Feuerwaffe","v":"Antrieb durch heiße Gase (Treibladung)"}],"begriffe":["Geschoss = der feste Körper, der verschossen wird (z. B. Kugel).","Lauf = das Rohr, durch das das Geschoss getrieben wird."],"abgrenzung":["Jede Feuerwaffe ist eine Schusswaffe – aber nicht jede Schusswaffe ist eine Feuerwaffe (z. B. Druckluft-/CO₂-Waffen treiben das Geschoss ohne Treibladung).","Schreckschuss-, Reizstoff- und Signalwaffen sind gesondert geregelt (PTB-Zeichen, Kleiner Waffenschein)."],"praxis":["Für die Prüfung wichtig ist die Reihenfolge der Begriffe: Waffe → Schusswaffe → Feuerwaffe (vom Weiten zum Engen).","Im Dienst ist meist entscheidend, ob ein Gegenstand überhaupt als ‚Waffe‘ gilt – denn dann greifen die Regeln zu Führen, Erlaubnis und Aufbewahrung."],"visual":{"type":"quote","items":[{"text":"Waffen sind: 1. Schusswaffen oder ihnen gleichgestellte Gegenstände und 2. tragbare Gegenstände, die ihrem Wesen nach dazu bestimmt sind, die Angriffs- oder Abwehrfähigkeit von Menschen zu beseitigen oder herabzusetzen …","source":"§ 1 Abs. 2 WaffG, gekürzt"},{"text":"Schusswaffen sind Gegenstände, die zum Angriff oder zur Verteidigung, zur Signalgebung, zur Jagd, zur Distanzinjektion, zur Markierung, zum Sport oder zum Spiel bestimmt sind und bei denen Geschosse durch einen Lauf getrieben werden.","source":"Anlage 1 Abschnitt 1 UA 1 Nr. 1.1 WaffG"},{"text":"Feuerwaffen sind Schusswaffen oder gleichgestellte Gegenstände, bei denen zum Antrieb der Geschosse heiße Gase verwendet werden.","source":"Anlage 1 Abschnitt 1 UA 1 Nr. 2 WaffG"}]}},"visual":{"type":"quote","items":[{"text":"Waffen sind: 1. Schusswaffen oder ihnen gleichgestellte Gegenstände und 2. tragbare Gegenstände, die ihrem Wesen nach dazu bestimmt sind, die Angriffs- oder Abwehrfähigkeit von Menschen zu beseitigen oder herabzusetzen …","source":"§ 1 Abs. 2 WaffG, gekürzt"},{"text":"Schusswaffen sind Gegenstände, die zum Angriff oder zur Verteidigung, zur Signalgebung, zur Jagd, zur Distanzinjektion, zur Markierung, zum Sport oder zum Spiel bestimmt sind und bei denen Geschosse durch einen Lauf getrieben werden.","source":"Anlage 1 Abschnitt 1 UA 1 Nr. 1.1 WaffG"},{"text":"Feuerwaffen sind Schusswaffen oder gleichgestellte Gegenstände, bei denen zum Antrieb der Geschosse heiße Gase verwendet werden.","source":"Anlage 1 Abschnitt 1 UA 1 Nr. 2 WaffG"}]}},{"h":"Tragbare Gegenstände","b":"Hieb-/Stoßwaffen, Reizstoffgeräte, Schleudern u.a.","detail":{"titel":"Tragbare Gegenstände (Hieb- & Stoßwaffen)","kat":"Grundbegriffe · tragbare Gegenstände","katCls":"waff","merksatz":"Auch ohne Schusswaffe kann etwas eine WAFFE sein: tragbare Gegenstände, die ihrem Wesen nach zum Angriff oder zur Verteidigung bestimmt sind (Hieb- und Stoßwaffen) oder die die Angriffs-/Abwehrfähigkeit von Menschen herabsetzen (z. B. Reizstoffe).","funktion":["Hieb- und Stoßwaffen: Gegenstände, die ihrem Wesen nach dazu bestimmt sind, durch Hieb, Stoß oder Stich zu verletzen (z. B. Schlagstock, Schlagring, bestimmte Messer).","Reizstoff- und Elektrogeräte: Gegenstände, die durch Reizstoffe oder Elektroimpulse die Angriffs- oder Abwehrfähigkeit herabsetzen.","Bestimmung zählt: Entscheidend ist, dass der Gegenstand seinem WESEN nach als Waffe bestimmt ist – nicht jeder Gegenstand, mit dem man zufällig zuschlagen kann, ist eine Waffe im Rechtssinn."],"schutzziel":"Auch nicht-schießende, aber gefährliche Gegenstände erfassen, damit das WaffG sie regeln kann.","kennwerte":[{"l":"Hieb-/Stoßwaffen","v":"ihrem Wesen nach zum Verletzen bestimmt"},{"l":"Reizstoff/Elektro","v":"setzen Angriffs-/Abwehrfähigkeit herab"},{"l":"Maßstab","v":"die Zweckbestimmung des Gegenstands"}],"begriffe":["Hieb- und Stoßwaffe = ein Gegenstand, der nach seiner Bauart zum Verletzen durch Hieb oder Stoß bestimmt ist.","Reizstoff = ein Stoff, der vorübergehend reizt und kampfunfähig macht (z. B. Pfefferspray gegen Menschen)."],"abgrenzung":["Werkzeug gegen Waffe: Ein Hammer ist Werkzeug – auch wenn man damit zuschlagen kann. Ein Schlagring dagegen ist seinem Wesen nach Waffe (zum Verletzen bestimmt).","Pfeffersprays ‚zur Tierabwehr‘ (mit Prüfzeichen) sind anders geregelt als Reizstoffsprühgeräte, die ausdrücklich gegen Menschen bestimmt sind."],"praxis":["Für die Praxis: Ein Schlagring ist eine VERBOTENE Waffe – wer ihn führt, macht sich strafbar (und ein Schlag damit ist gefährliche Körperverletzung).","Reizstoffsprühgeräte im Dienst darfst du nur mit Zustimmung des Arbeitgebers führen (BewachV) – und nur mit dem nötigen Prüfzeichen."]},"visual":null},{"h":"Wesentliche Teile","b":"Lauf, Verschluss, Patronenlager, Griffstück (bei Revolver Trommel)","detail":{"titel":"Wesentliche Teile einer Schusswaffe","kat":"Grundbegriffe · wesentliche Teile","katCls":"waff","merksatz":"Die ‚wesentlichen Teile‘ einer Schusswaffe (z. B. Lauf, Verschluss, das den Verschluss aufnehmende Gehäuse) stehen rechtlich der ganzen Waffe GLEICH – für sie gelten dieselben Erlaubnis- und Verbotsregeln. Auch Schalldämpfer werden gleichgestellt.","funktion":["Was dazugehört: insbesondere Lauf, Verschluss und das Gehäuse, das den Verschluss aufnimmt – die funktionsbestimmenden Bauteile.","Gleichstellung: Ein wesentliches Teil wird rechtlich behandelt wie eine vollständige Schusswaffe (gleiche Erlaubnispflicht).","Schalldämpfer: werden den Schusswaffen gleichgestellt – ihr Erwerb ist erlaubnispflichtig."],"schutzziel":"Verhindern, dass man die Erlaubnispflicht umgeht, indem man eine Waffe einfach in ihre tragenden Teile zerlegt.","kennwerte":[{"l":"Typische Teile","v":"Lauf · Verschluss · Gehäuse"},{"l":"Rechtsfolge","v":"stehen der ganzen Waffe gleich"},{"l":"Gleichgestellt","v":"auch Schalldämpfer (erlaubnispflichtig)"}],"begriffe":["Verschluss = das Bauteil, das den Lauf hinten verschließt und das Abfeuern ermöglicht.","Schalldämpfer = Vorsatz zur Minderung des Mündungsknalls – rechtlich wie eine Schusswaffe behandelt."],"abgrenzung":["Nicht jedes Zubehör ist ein wesentliches Teil: Ein Holster oder ein Zielfernrohr ist in der Regel KEIN wesentliches Teil – Lauf und Verschluss dagegen schon.","Wer ein wesentliches Teil besitzt, braucht dieselbe Erlaubnis wie für die ganze Waffe – Zerlegen hilft also nicht, die Erlaubnispflicht zu umgehen."],"praxis":["Praktische Folge: Auch der Kauf eines einzelnen Laufs oder eines Schalldämpfers ist erlaubnispflichtig – nicht nur der Kauf der kompletten Pistole.","Für die Aufbewahrung heißt das: Wesentliche Teile sind genauso sicher zu verwahren wie ganze Waffen."],"visual":{"type":"diagram","parts":[{"label":"Lauf","desc":"führt das Geschoss"},{"label":"Verschluss / Schlitten","desc":"schließt und bewegt"},{"label":"Griffstück / Rahmen","desc":"trägt zentrale Teile"},{"label":"Abzug","desc":"Bedienelement"},{"label":"Magazin","desc":"nimmt Patronen auf"},{"label":"Patronenlager","desc":"Aufnahme vor Schussabgabe"}]}},"visual":{"type":"diagram","parts":[{"label":"Lauf","desc":"führt das Geschoss"},{"label":"Verschluss / Schlitten","desc":"schließt und bewegt"},{"label":"Griffstück / Rahmen","desc":"trägt zentrale Teile"},{"label":"Abzug","desc":"Bedienelement"},{"label":"Magazin","desc":"nimmt Patronen auf"},{"label":"Patronenlager","desc":"Aufnahme vor Schussabgabe"}]}}],"quiz":[{"q":"Welche Aussagen zu den Rechtsnormen des Waffenrechts sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Das zentrale Gesetz ist das Waffengesetz (WaffG) mit seinen Anlagen","c":true},{"t":"Die AWaffV (Allgemeine Waffengesetz-Verordnung) konkretisiert das WaffG, z. B. zur Aufbewahrung","c":true},{"t":"Für das Bewachungsgewerbe sind zusätzlich § 28 WaffG sowie GewO/BewachV von Bedeutung","c":true},{"t":"Der Einsatz einer Waffe zur Verteidigung richtet sich allein nach dem WaffG, nicht nach dem StGB","c":false}]},{"q":"Was zählt gemäß WaffG zum ‚Umgang‘ mit einer Waffe?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Das Erwerben und Besitzen einer Waffe","c":true},{"t":"Das Führen einer Waffe außerhalb der eigenen Wohnung oder Geschäftsräume","c":true},{"t":"Das Schießen mit einer Waffe sowie das Transportieren","c":true},{"t":"‚Umgang‘ meint ausschließlich das Schießen mit einer Waffe","c":false}]},{"q":"Welche Aussagen zu Waffen, Schusswaffen und Feuerwaffen sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"‚Waffe‘ ist der Oberbegriff und umfasst Schusswaffen sowie tragbare Gegenstände","c":true},{"t":"Schusswaffen treiben Geschosse durch einen Lauf","c":true},{"t":"Feuerwaffen sind Schusswaffen, bei denen der Antrieb durch heiße Gase (Treibladung) erfolgt","c":true},{"t":"Jede Schusswaffe ist automatisch eine Feuerwaffe","c":false}]},{"q":"Welche Aussagen zu tragbaren Gegenständen (Hieb- und Stoßwaffen) sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Hieb- und Stoßwaffen sind Gegenstände, die ihrem Wesen nach zum Verletzen bestimmt sind (z. B. Schlagring)","c":true},{"t":"Auch Reizstoff- und Elektrogeräte, die die Angriffs- oder Abwehrfähigkeit herabsetzen, können Waffen sein","c":true},{"t":"Entscheidend ist die Zweckbestimmung des Gegenstands, nicht die bloße Möglichkeit des Missbrauchs","c":true},{"t":"Jeder Gegenstand, mit dem man zuschlagen kann (z. B. ein Hammer), ist eine Waffe im Sinne des WaffG","c":false}]},{"q":"Für welche Gegenstände ist gemäß WaffG der Erwerb erlaubnispflichtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Schalldämpfer für Feuerwaffen","c":true},{"t":"Feuerwaffen, z. B. Pistolen Kal. 9 mm","c":true},{"t":"Schreckschusswaffen","c":false},{"t":"Teleskopschlagstöcke","c":false}]},{"q":"Wer hat Umgang mit Waffen?","a":"Der eine Waffe herstellt, erwirbt, führt, verbringt, besitzt, überlässt....","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind eigentlich Waffen?","a":"Schusswaffen sind Gegenstände, die zum Angriff und zur Verteidigung zur Signalgebung, Sport, Spiel, Jagd, Distanzinjektion und zur Markierung bestimmt sind und bei denen Geschosse durch einen Lauf getrieben werden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind Schusswaffen, was sind Feuerwaffen?","a":"Schusswaffen sind Gegenstände, die zum Angriff und zur Verteidigung zur Signalgebung, Sport, Spiel, Jagd, Distanzinjektion und zur Markierung bestimmt sind und bei denen Geschosse durch einen Lauf getrieben werden. Feuerwaffen sind Schusswaffen, bei denen zum Antrieb der Geschosse heiße Gase verwendet werden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind gem. WaffG tragbare Gegenstände?","a":"Tragbare Gegenstände sind unter anderen nach ihrem Wesen dazu bestimmt, unter unmittelbarer Ausnutzung der Muskelkraft (z.B. Hieb- und Stosswaffen) oder unter Ausnutzung einer anderen mechanischen Energie (z.B. Reizstoff- sprühgerät, Schleuder) Verletzungen beizubringen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Fristen gelten für die Waffenbesitzkarte, welche für den Waffenschein?","a":"Waffenbesitzkarte bis zum Erwerb einer Waffe gültig ein Jahr lang, nach dem Erwerb der Waffe unbefristet. Waffenschein benötigt man zum Führen einer Waffe und ist höchstens drei Jahre lang gültig, kann aber zweimal um je drei Jahre verlängert werden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Für was braucht man eine Waffenbesitzkarte?","a":"Für den Erwerb und Besitz einer Schusswaffe.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Für was braucht man einen Waffenschein?","a":"Für das Führen einer Schusswaffe.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wem kann man eine Waffe zur Aufbewahrung geben?","a":"- Solche Schusswaffen dürfen nur an Berechtigte (Waffenbesitzkarteninhaber) - an konzessionierte Waffenhändler, - einem Büchsenmacher zum Zwecke der Instandsetzung, - einer Person zur sicheren Aufbewahrung (Waffenschrank mind. DIN 1143 -1), sowie zum gewerbemäßigen oder nichtgewerbemäßigen Beförderung zu einem Berechtigten, überlassen werden","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Verbotene Schusswaffen und verbotene Gegenstände?","a":"Der Erwerb oder das führen von verbotnen Waffen und Gegenständen ist verboten. Verbotene Schusswaffen: - Kriegswaffen (Maschinenpistole) - vollautomatische Schusswaffen - Vorderschaftsrepetierflinten mit Austauschschaft (Pistolengriff) = Pumpgun - Waffen, die ihrer Form nach geeignet sind, einen anderen Gegenstand vorzutäuschen (Stockgewehr, Schießkugelschreiber) - Waffen, die zusammengeklappt oder verkürzt oder zerlegt werden können (Wilderergewehr) Verbotene Gegenstände: - Stahlrute - Totschläger - Schlagringe - Wurfsterne - Butterflymesser, Nunchakus Besitz erlaubt, aber Führen (Öffentlichkeit) verboten - sogenannte Anscheinswaffen (Soft Air Waffen die echten täuschend ähnlich sind) - Einhandmesser - Teleskopschlagstock (ASP)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Zeichen lassen eine freie Waffe, also Gas- und Schreckschusswaffen erkennen?","a":"In Deutschland können legale Schreckschusswaffen am Prüfsiegel der Physikalisch-Technischen Bundesanstalt (PTB) erkannt werden. Merke: Wesentliche Teile bei Herkömmlichen Schusswaffen sind: Lauf Verschluss Patronenlager Griffstück (bei Kurzwaffen) Beschusszeichen: PTB Zeichen; Gas- Schreckschusspistole:","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie Beispiele für Waffen, die nach dem Waffenrecht im Umgang verboten sind?","a":"Molotowcocktail Schießkugelschreiber Butterflymesser Springmesser Nun-Chakkus Wurfsterne Faustmesser Stahlrute Schlagring Totschläger Fallmesser Ungeprüfte Reizstoffsprühgeräte Vollautomatische Feuerwaffen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist eine Waffenbesitzkarte (WBK) ?","a":"Ist eine waffenrechtliche Erlaubnis zum . . . erlaubt den Erwerb einer Waffe erlaubt den Besitz einer Waffe Frist zum Erwerb der Waffe gilt ein Jahr Waffenbesitzkarte ist grundsätzlich unbefristet gültig Mit der Waffenbesitzkarte ist auch der Transport der Waffe, zum Beispiel zum Schießstand.(hierfür ist der Personalausweis und die WBK mitzuführen)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist ein Waffenschein ?","a":"Eine waffenrechtliche Erlaubnis zum . . . Erlaubt das Führen einer Waffe (außerhalb des eigenen befriedeten Besitztums) Ist auf drei Jahre befristet, kann bis zu zweimal um jeweils drei Jahre verlängert werden Für das Führen einer Waffe ist, der Personalausweis und der Waffenschein mitzuführen.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist ein kleiner Waffenschein ?","a":"Eine waffenrechtliche Erlaubnis zum . . . erlaubt das Führen von Schreckschuss-; Reizstoff- und Signalwaffen wird grundsätzlich unbefristet erteilt !!! Hier ist keine Haftpflichtversicherung erforderlich !!!","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was wird für die Erteilung / Beantragung einer waffenrechtlichen Erlaubnis benötigt?","a":"Mindestens 18. Jahre alt Persönliche Eignung Zuverlässigkeit Bedürfnisnachweis Sachkundenachweis (z.B. Waffensachkunde, oder andere berufliche Ausbildung) Nachweis Haftpflichtversicherung – nur bei Beantragung eines Waffenscheines","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was regelt das Waffengesetz?","a":"Das Waffengesetz regelt den privaten Umgang mit Waffen und Munition zum Schutz von Sicherheit und Ordnung in der Öffentlichkeit Verstöße können sowohl: als Straftat sowie auch als Ordnungswidrigkeit geahndet werden","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was sind Waffen?","a":"Schusswaffen oder tragbare Gegenstände die die Angriffs- oder Verteidigungsfähigkeit von Menschen beseitigen oder herabsetzen sollen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Waffen darf man besitzen, aber nicht führen?","a":"Messer mit Klingenlänge größer 12 cm Anscheinswaffen (z.B.: AirSoft, PaintBall) Schreckschuss- / Reizstoff- & Signalwaffen Armbrust Hieb- & Stoßwaffen (z.B.: Teleskopschlagstock) Druckluft- & Federdruckwaffen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Führverbote für Waffen gibt es, gem. WaffG ?","a":"Führverbot auf öffentlichen Veranstaltungen(gilt für alle Waffen) Führverbot für Anscheinswaffen und bestimmte tragbare Gegenstände(gilt für Anscheinswaffen, Einhandmesser, Klingenlänge über 12cm, Hieb- & Stoßwaffen) Führverbot im öffentlichen Personennahverkehr (neu seit 10/2024)(gilt für alle Waffen)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Ausweispflichten gelten gemäß Waffengesetz ?","a":"Waffe erwerbenPersonalausweis & Waffenbesitzkarte (Erwerbserlaubnis) Waffe transportieren / verbringenPersonalausweis & Waffenbesitzkarte Waffe führenPersonalausweis & Waffenschein","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was sind wesentliche Teile einer Schusswaffe?","a":"Lauf, Verschluss, Griffstück, Patronenlager, bei Revolver Trommel","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[]},{"n":2,"title":"Zustände & Tätigkeiten","subtitle":"4 Konzepte · 9 Prüfungsfragen","cards":[{"h":"Führen einer Waffe","b":"Zugriffsbereit außerhalb Wohnung/Geschäftsraum/befriedetem Besitztum","detail":{"titel":"Führen einer Waffe","kat":"Zustände · Führen","katCls":"waff","merksatz":"‚Führen‘ heißt, die tatsächliche Gewalt über eine Waffe AUSSERHALB der eigenen Wohnung, Geschäftsräume, des befriedeten Besitztums oder einer Schießstätte auszuüben. Wer eine Schusswaffe führt, braucht einen WAFFENSCHEIN – und im Dienst die Zustimmung des Arbeitgebers.","funktion":["Führen = tatsächliche Gewalt über eine Waffe außerhalb der eigenen vier Wände oder Geschäftsräume (also ‚draußen‘, in der Öffentlichkeit).","Erlaubnis: Das Führen erlaubnispflichtiger Schusswaffen setzt einen WAFFENSCHEIN voraus (für Schreckschuss/Reizgas/Signal genügt der Kleine Waffenschein).","Mitführpflicht: Wer führt, muss Waffenschein UND Personalausweis/Pass dabeihaben. Im Bewachungsdienst zusätzlich: Zustimmung des Arbeitgebers (BewachV)."],"schutzziel":"Das Tragen von Waffen in der Öffentlichkeit streng an eine Erlaubnis binden – dort ist die Gefahr für andere am größten.","kennwerte":[{"l":"Führen","v":"Gewalt über Waffe außerhalb Wohnung/Geschäft"},{"l":"Erlaubnis","v":"Waffenschein (Schreckschuss: Kleiner WS)"},{"l":"Mitzuführen","v":"Waffenschein + Perso/Pass"}],"begriffe":["Befriedetes Besitztum = ein umfriedetes Grundstück (z. B. eingezäunter Hof) – innerhalb gilt man nicht als ‚führend‘.","Waffenschein = Erlaubnis zum FÜHREN einer Schusswaffe (nicht zu verwechseln mit der WBK für Besitz)."],"abgrenzung":["Besitz (zu Hause, mit WBK) ist kein Führen. Erst außerhalb der eigenen Räume wird daraus Führen – mit Waffenschein.","Auch ein behördlich zugelassenes Elektroimpulsgerät darf im Dienst nur mit Erlaubnis des Arbeitgebers geführt werden – PTB-Zeichen oder Zustimmung des Auftraggebers allein genügen nicht."],"praxis":["Im Dienst gilt: Schusswaffe, Hieb-/Stoßwaffe oder Reizstoffsprühgerät nur mit Zustimmung des Gewerbetreibenden führen (so muss es in der Dienstanweisung stehen).","Beim Führen einer Schusswaffe immer Waffenschein und Personalausweis dabei – fehlt der Schein, ist das Führen unerlaubt."]},"visual":null},{"h":"Zugriffsbereit / schussbereit","b":"Mit wenigen Griffen einsatzbereit / geladen","detail":{"titel":"Zugriffsbereit & schussbereit","kat":"Zustände · Bereitschaft","katCls":"waff","merksatz":"Zwei Zustandsbegriffe sind entscheidend: SCHUSSBEREIT ist eine Waffe, die geladen ist und sofort abgefeuert werden kann. ZUGRIFFSBEREIT ist sie, wenn man sie mit wenigen Handgriffen unmittelbar in Anschlag bringen kann (griffbereit am Körper).","funktion":["Schussbereit: Die Waffe ist geladen (Patrone im Lager bzw. zugeführt) und kann ohne weitere Vorbereitung abgefeuert werden.","Zugriffsbereit: Die Waffe ist so verfügbar, dass man sie mit wenigen Handgriffen unmittelbar in Anschlag bringen kann (z. B. im Holster am Gürtel).","Bedeutung: Diese Zustände entscheiden, ob ein Verhalten ‚Führen‘ ist und ob ein Transport zulässig ist (beim Transport: NICHT zugriffsbereit und NICHT schussbereit)."],"schutzziel":"Genau bestimmen, wie ‚einsatznah‘ eine Waffe ist – davon hängen Führen, Transport und Erlaubnis ab.","kennwerte":[{"l":"Schussbereit","v":"geladen, sofort abfeuerbar"},{"l":"Zugriffsbereit","v":"mit wenigen Handgriffen in Anschlag"},{"l":"Transport","v":"weder zugriffs- noch schussbereit"}],"begriffe":["Laden = Munition in die Waffe einführen (Magazin + Patrone im Lager macht sie schussbereit).","In Anschlag bringen = die Waffe einsatzbereit auf ein Ziel richten können."],"abgrenzung":["Schussbereit (geladen) ist nicht dasselbe wie zugriffsbereit (griffbereit): Eine ungeladene Waffe im Holster ist zugriffsbereit, aber nicht schussbereit.","Beim erlaubten Transport muss beides verneint sein: die Waffe darf weder schussbereit (also entladen) noch zugriffsbereit (also getrennt/verpackt) sein."],"praxis":["Faustregel Transport: getrennt und verpackt – die Waffe nicht griffbereit am Körper und nicht geladen.","Im erlaubten Führen (mit Waffenschein) darf die Waffe dagegen zugriffsbereit getragen werden – das ist gerade der Sinn des Waffenscheins."]},"visual":null},{"h":"Transportieren","b":"Ungeladen, nicht zugriffsbereit, verschlossenes Behältnis, getrennt von Munition","detail":{"titel":"Transportieren einer Waffe","kat":"Zustände · Transport","katCls":"waff","merksatz":"Beim TRANSPORT (z. B. von zu Hause zum Schießstand) muss die Waffe NICHT zugriffsbereit und NICHT schussbereit sein – also entladen und so verpackt, dass man nicht unmittelbar drankommt. Der Transport muss zudem von einem waffenrechtlichen Zweck (Bedürfnis) gedeckt sein.","funktion":["Zustand: Die Waffe darf beim Transport weder schussbereit (entladen) noch zugriffsbereit (verpackt/getrennt) sein.","Zweck: Der Transport muss von einem waffenrechtlichen Bedürfniszweck umfasst sein oder damit zusammenhängen (z. B. Fahrt zum Schießstand oder zum Büchsenmacher).","Berechtigung: Wer transportiert, muss die nötige Erlaubnis (z. B. WBK) für die Waffe haben."],"schutzziel":"Den notwendigen Ortswechsel einer Waffe erlauben, ohne dass sie dabei einsatzbereit ‚am Mann‘ ist.","kennwerte":[{"l":"Zustand","v":"nicht zugriffsbereit, nicht schussbereit"},{"l":"Zweck","v":"waffenrechtliches Bedürfnis (z. B. Schießstand)"},{"l":"Berechtigung","v":"z. B. Inhaber einer WBK"}],"begriffe":["Transport = das Befördern der (nicht zugriffs-/schussbereiten) Waffe, meist zwischen zwei berechtigten Orten.","Bedürfnis = der anerkannte waffenrechtliche Grund (z. B. Sportschießen), der den Umgang trägt."],"abgrenzung":["Transport ist nicht Führen: Beim Führen (Waffenschein) darf die Waffe zugriffsbereit sein; beim Transport gerade nicht.","Der bloße Aufbewahrungsort ändert nichts: Auch im verschlossenen Kofferraum darf die Waffe nicht schussbereit transportiert werden."],"praxis":["Klassiker: Fahrt zum Schießtraining – Waffe entladen, im verschlossenen Behältnis, Munition getrennt; das ist zulässig.","Wer eine Waffe ohne Waffenschein ‚nur im Auto griffbereit‘ mitführt, transportiert nicht zulässig, sondern führt sie unerlaubt."]},"visual":null},{"h":"Fund einer Waffe","b":"Polizei benachrichtigen, liegen lassen (Spuren)","detail":{"titel":"Fund einer Waffe","kat":"Zustände · Fund","katCls":"waff","merksatz":"Wer eine Waffe FINDET (z. B. herrenlos auf der Streife), erlangt zwar tatsächlichen Besitz – darf sie aber nicht behalten oder führen. Richtig ist: die Waffe sichern, NICHT damit hantieren und unverzüglich die Polizei bzw. zuständige Behörde verständigen.","funktion":["Sofort melden: Den Fund einer Waffe oder von Munition unverzüglich der Polizei oder zuständigen Behörde anzeigen.","Nicht aneignen, nicht führen: Aus dem Finden entsteht KEIN Recht zum Besitz oder Führen – wer die Waffe behält oder einsteckt, kann sich strafbar machen.","Sichern, nicht hantieren: Die Fundwaffe möglichst nicht anfassen/verändern (Spuren!) und vor unbefugtem Zugriff sichern, bis die Polizei übernimmt."],"schutzziel":"Verhindern, dass herrenlose Waffen unkontrolliert in Umlauf geraten – und den Finder vor strafbarem Umgang bewahren.","kennwerte":[{"l":"Sofort","v":"Polizei/Behörde unverzüglich verständigen"},{"l":"Verboten","v":"behalten, einstecken, führen"},{"l":"Verhalten","v":"sichern, möglichst nicht anfassen"}],"begriffe":["Herrenlos = ohne erkennbaren berechtigten Besitzer.","Unverzüglich = ohne schuldhaftes Zögern (so schnell wie zumutbar)."],"abgrenzung":["Anders als beim BGB-Fund einer Alltagssache (Finderlohn, § 965 ff.) gibt es bei Waffen KEIN ‚Behaltendürfen‘ – das Waffenrecht geht vor.","Wer die Fundwaffe ‚nur zur Sicherheit‘ mit nach Hause nimmt, begeht bereits unerlaubten Umgang (Besitz/Führen ohne Erlaubnis)."],"praxis":["Auf Streife eine Waffe gefunden? Fundort merken und absichern, niemanden heranlassen, Polizei rufen – nicht selbst einsammeln und mitnehmen.","Dokumentiere den Fund (Ort, Zeit, Umstände) für den späteren Bericht – aber überlasse das Sicherstellen der Polizei."]},"visual":null}],"quiz":[{"q":"Eine Wachperson führt eine Schusswaffe. Welche gültigen Dokumente muss sie gemäß WaffG mitführen?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Waffenschein","c":true},{"t":"Personalausweis oder Pass","c":true},{"t":"Firmenausweis","c":false},{"t":"Waffenbesitzkarte","c":false},{"t":"Kopie der Dienstanweisung","c":false}]},{"q":"Eine Wachperson führt zum Eigenschutz ein behördlich zugelassenes Elektroimpulsgerät im Dienst bei sich. Ist das erlaubt?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Ja, wenn das Elektroimpulsgerät über ein PTB-Prüfzeichen verfügt","c":false},{"t":"Ja, wenn der Auftraggeber zugestimmt hat","c":false},{"t":"Nein, wenn die Wachperson keine Erlaubnis von ihrem Arbeitgeber hat","c":true},{"t":"Ja, zum Eigenschutz sind behördlich zugelassene Verteidigungsmittel immer erlaubt","c":false}]},{"q":"Welche Aussagen zu den Zuständen ‚schussbereit‘ und ‚zugriffsbereit‘ sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Schussbereit ist eine Waffe, die geladen ist und ohne weitere Vorbereitung abgefeuert werden kann","c":true},{"t":"Zugriffsbereit ist eine Waffe, die man mit wenigen Handgriffen unmittelbar in Anschlag bringen kann","c":true},{"t":"Beim erlaubten Transport darf die Waffe weder schussbereit noch zugriffsbereit sein","c":true},{"t":"Eine ungeladene Waffe im Holster am Gürtel ist schussbereit","c":false}]},{"q":"Welche Aussagen zum Transport von Schusswaffen und Munition sind gemäß WaffG richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Schusswaffen dürfen in schussbereitem Zustand transportiert werden, wenn sie sich im verschlossenen Kofferraum befinden","c":false},{"t":"Schusswaffen und Munition dürfen von Personen transportiert werden, die zuverlässig sind und das 25. Lebensjahr vollendet haben","c":false},{"t":"Schusswaffen dürfen z. B. zum Schießstand transportiert werden; sie dürfen dabei nicht zugriffsbereit und nicht schussbereit sein","c":true},{"t":"Schusswaffen und Munition dürfen vom Inhaber einer Waffenbesitzkarte transportiert werden, wenn der Transport von einem waffenrechtlichen Bedürfniszweck umfasst ist oder damit zusammenhängt","c":true}]},{"q":"Eine Wachperson findet auf ihrer Streife eine herrenlose Schusswaffe. Wie verhält sie sich richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sie verständigt unverzüglich die Polizei bzw. die zuständige Behörde","c":true},{"t":"Sie sichert die Fundstelle und lässt niemanden an die Waffe heran","c":true},{"t":"Sie nimmt die Waffe an sich und führt sie zum Eigenschutz weiter mit","c":false},{"t":"Aus dem Fund entsteht ein Recht, die Waffe zu behalten (Finderlohn nach BGB)","c":false}]},{"q":"Was bedeutet führen einer Waffe?","a":"Wenn man eine Waffe zugriffbereit außerhalb der eigenen Wohnung, Geschäftsräumen oder des eigenen befriedeten Besitztums bei sich hat, dann führt man eine Waffe.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Fristen gelten für die Waffenbesitzkarte, welche für den Waffenschein?","a":"Waffenbesitzkarte bis zum Erwerb einer Waffe gültig ein Jahr lang, nach dem Erwerb der Waffe unbefristet. Waffenschein benötigt man zum Führen einer Waffe und ist höchstens drei Jahre lang gültig, kann aber zweimal um je drei Jahre verlängert werden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist ein Waffenschein ?","a":"Eine waffenrechtliche Erlaubnis zum . . . Erlaubt das Führen einer Waffe (außerhalb des eigenen befriedeten Besitztums) Ist auf drei Jahre befristet, kann bis zu zweimal um jeweils drei Jahre verlängert werden Für das Führen einer Waffe ist, der Personalausweis und der Waffenschein mitzuführen.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was bedeutet Zugriffsbereit, was bedeutet Schussbereit?","a":"Zugriffbereit ist eine Waffe, wenn sie mit wenigen schnellen Handgriffen in Anschlag gebracht werden kann. Schussbereit ist eine Schusswaffe, wenn sie geladen ist, d.h. wenn Munition in der Trommel, im Magazin oder Patronenlager ist, auch wenn die Schusswaffe nicht gespannt oder gesichert ist. Oder wenn sich eine Patrone vor dem Lauf befindet.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wann führen Sie eine Waffe?","a":"Wenn ich über eine Waffe außerhalb meines privaten Besitztums in der Öffentlichkeit die tatsächliche Gewalt ausübe Welchen Zustand darf die Waffe haben?: Schussbereit- die Waffe ist geladen (Patronen im Magazin oder im Patronenlager) und gesichert Zugriffsbereit- die Waffe kann mit wenigen Handgriffen in den Anschlag gebracht werden","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wie transportiert man eine Waffe?","a":"Eine Waffe transportiert man in einem verschlossenen Behältnis getrennt von der Munition.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine Waffenbesitzkarte (WBK) ?","a":"Ist eine waffenrechtliche Erlaubnis zum . . . erlaubt den Erwerb einer Waffe erlaubt den Besitz einer Waffe Frist zum Erwerb der Waffe gilt ein Jahr Waffenbesitzkarte ist grundsätzlich unbefristet gültig Mit der Waffenbesitzkarte ist auch der Transport der Waffe, zum Beispiel zum Schießstand.(hierfür ist der Personalausweis und die WBK mitzuführen)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Ausweispflichten gelten gemäß Waffengesetz ?","a":"Waffe erwerbenPersonalausweis & Waffenbesitzkarte (Erwerbserlaubnis) Waffe transportieren / verbringenPersonalausweis & Waffenbesitzkarte Waffe führenPersonalausweis & Waffenschein","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was macht man beim Fund einer Waffe?","a":"Beim Fund einer Waffe benachrichtigt man unverzüglich die Polizei und lässt die Waffe dort wo sie liegt (Fingerabdrücke oder beschädigte Waffe), zur Beweissicherung und Spurensicherung","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[{"scenario":"Ein SMA trägt im Streifendienst eine geladene Schusswaffe griffbereit am Gürtel, ohne konkreten bewaffneten Auftrag.","frage":"Welche Begriffe und Erlaubnisse sind hier entscheidend?","loesung":"Er „führt“ die Waffe (zugriffsbereit außerhalb der eigenen Räume) und sie ist „schussbereit“ (geladen). Das Führen erfordert einen Waffenschein und im Bewachungsgewerbe einen konkreten, behördlich geprüften Auftrag (§28 WaffG). Ohne das ist es unzulässig."}]},{"n":3,"title":"Erlaubnisse","subtitle":"5 Konzepte · 11 Prüfungsfragen","cards":[{"h":"Waffenbesitzkarte (WBK)","b":"Erwerb/Besitz; Erwerb 1 Jahr, Besitz unbefristet","detail":{"titel":"Waffenbesitzkarte (WBK)","kat":"Erlaubnisse · Besitz","katCls":"waff","merksatz":"Die WBK erlaubt den ERWERB und BESITZ erlaubnispflichtiger Schusswaffen – nicht das Führen. In ihr werden Art, Anzahl und Kaliber der Waffen eingetragen. Der Erwerb ist binnen zwei Wochen der Behörde anzuzeigen und die WBK zur Eintragung vorzulegen.","funktion":["Erwerb & Besitz: Die WBK ist die Erlaubnis, eine bestimmte erlaubnispflichtige Schusswaffe zu kaufen und zu besitzen (zu Hause/in Geschäftsräumen).","Eintragung: In die WBK werden Art, Anzahl und Kaliber der Waffen eingetragen – sie ist also waffenbezogen.","Anzeigepflicht: Den Erwerb innerhalb von zwei Wochen der zuständigen Behörde schriftlich/elektronisch anzeigen und die WBK zur Eintragung vorlegen."],"schutzziel":"Den legalen Waffenbestand lückenlos dokumentieren – die Behörde weiß, wer welche Waffe besitzt.","kennwerte":[{"l":"Erlaubt","v":"Erwerb + Besitz (nicht Führen)"},{"l":"Eintrag","v":"Art · Anzahl · Kaliber"},{"l":"Anzeige","v":"Erwerb binnen 2 Wochen melden"}],"begriffe":["WBK = Waffenbesitzkarte, die behördliche Erlaubnis zum Erwerb und Besitz von Schusswaffen.","Bedürfnis = der anerkannte Grund (z. B. Sportschütze, Jäger), ohne den keine WBK erteilt wird."],"abgrenzung":["WBK ≠ Waffenschein: Die WBK erlaubt nur Besitz (zu Hause), der Waffenschein das Führen (draußen).","Die Erlaubnis zum Erwerb wird NICHT in einen Waffenschein eingetragen – sie steht in der WBK."],"praxis":["Wer eine Sportpistole kauft, braucht vorher die WBK – und muss den Kauf binnen zwei Wochen eintragen lassen.","Ohne Bedürfnisnachweis gibt es keine WBK; bloßes ‚Haben-Wollen‘ genügt nicht."],"visual":{"type":"trafficlight","items":[{"color":"green","label":"Grüne WBK","desc":"Einzelerlaubnis / Voreintrag, häufig Jäger, Sportschützen, Erben. Besitzen ≠ Führen."},{"color":"yellow","label":"Gelbe WBK","desc":"Sportschützen für bestimmte Waffenarten nach § 14 WaffG. Besitzen ≠ Führen."},{"color":"red","label":"Rote WBK","desc":"Waffensammler oder Waffensachverständige mit Sammel-/Forschungsgebiet. Besitzen ≠ Führen."}]}},"visual":{"type":"trafficlight","items":[{"color":"green","label":"Grüne WBK","desc":"Einzelerlaubnis / Voreintrag, häufig Jäger, Sportschützen, Erben. Besitzen ≠ Führen."},{"color":"yellow","label":"Gelbe WBK","desc":"Sportschützen für bestimmte Waffenarten nach § 14 WaffG. Besitzen ≠ Führen."},{"color":"red","label":"Rote WBK","desc":"Waffensammler oder Waffensachverständige mit Sammel-/Forschungsgebiet. Besitzen ≠ Führen."}]}},{"h":"Waffenschein","b":"Führen einer Schusswaffe; max. 3 Jahre, 2x verlängerbar","detail":{"titel":"Waffenschein","kat":"Erlaubnisse · Führen","katCls":"waff","merksatz":"Der Waffenschein erlaubt das FÜHREN erlaubnispflichtiger Schusswaffen in der Öffentlichkeit. Er ist auf DREI Jahre befristet (Verlängerung möglich) und setzt ein besonderes Bedürfnis voraus. Beim Führen sind Waffenschein und Personalausweis/Pass mitzuführen.","funktion":["Führen: Der Waffenschein erlaubt, eine Schusswaffe außerhalb der eigenen Wohnung/Geschäftsräume zu tragen.","Geltungsdauer: drei Jahre (kann um jeweils bis zu drei Jahre verlängert werden).","Voraussetzung: ein besonderes Bedürfnis (z. B. erhebliche Gefährdung); im Bewachungsgewerbe sehr restriktiv und eng auftragsbezogen."],"schutzziel":"Das besonders gefährliche Tragen scharfer Waffen in der Öffentlichkeit auf eng begründete Ausnahmefälle beschränken.","kennwerte":[{"l":"Erlaubt","v":"Führen in der Öffentlichkeit"},{"l":"Gültigkeit","v":"3 Jahre (verlängerbar)"},{"l":"Mitzuführen","v":"Waffenschein + Perso/Pass"}],"begriffe":["Waffenschein = Erlaubnis zum Führen einer Schusswaffe (im Gegensatz zur WBK für den Besitz).","Besonderes Bedürfnis = überdurchschnittliche Gefährdung, die das Führen rechtfertigt."],"abgrenzung":["Der (große) Waffenschein gilt für scharfe Schusswaffen. Für Schreckschuss-/Reizgas-/Signalwaffen genügt der Kleine Waffenschein.","Anders als die WBK (unbefristet, für Besitz) ist der Waffenschein auf drei Jahre befristet."],"praxis":["In der Praxis erhalten Wachkräfte nur selten einen Waffenschein – und wenn, dann eng auftragsbezogen und mit Zustimmung des Arbeitgebers.","Merke die Drei-Jahres-Frist: Nach Ablauf ist ohne Verlängerung das Führen wieder unerlaubt."],"visual":{"type":"compare","left":{"title":"Waffenschein","points":["Führen erlaubnispflichtiger Schusswaffen","maximal 3 Jahre, Verlängerung möglich","Sehr hohe Hürde: Bedürfnis/Gefährdung, Eignung, Zuverlässigkeit, Sachkunde, ggf. Versicherung"]},"right":{"title":"Kleiner Waffenschein","points":["Führen von SRS-Waffen mit PTB-Zeichen","grundsätzlich unbefristet","Erlaubt keine echten Schusswaffen. DGUV V23: Schreck-/Gas-Schusswaffen bei Wach- und Sicherungsaufgaben unzulässig."]}}},"visual":{"type":"compare","left":{"title":"Waffenschein","points":["Führen erlaubnispflichtiger Schusswaffen","maximal 3 Jahre, Verlängerung möglich","Sehr hohe Hürde: Bedürfnis/Gefährdung, Eignung, Zuverlässigkeit, Sachkunde, ggf. Versicherung"]},"right":{"title":"Kleiner Waffenschein","points":["Führen von SRS-Waffen mit PTB-Zeichen","grundsätzlich unbefristet","Erlaubt keine echten Schusswaffen. DGUV V23: Schreck-/Gas-Schusswaffen bei Wach- und Sicherungsaufgaben unzulässig."]}}},{"h":"Kleiner Waffenschein","b":"Führen von SRS-Waffen; unbefristet; im Bewachungsgewerbe verboten","detail":{"titel":"Kleiner Waffenschein","kat":"Erlaubnisse · Schreckschuss & Co.","katCls":"waff","merksatz":"Der Kleine Waffenschein erlaubt das FÜHREN von Schreckschuss-, Reizgas- und Signalwaffen, die ein PTB-Zeichen im Kreis tragen. Er wird UNBEFRISTET erteilt. Er erlaubt KEINE scharfen Schusswaffen.","funktion":["Erlaubt: das Führen von Schreckschuss-, Reizgas- und Signalwaffen (mit PTB-Zeichen im Kreis) in der Öffentlichkeit.","Unbefristet: Anders als der große Waffenschein wird er ohne Befristung erteilt.","Grenzen: Er gilt NICHT für scharfe Schusswaffen und nicht dort, wo das Führen verboten ist (z. B. öffentliche Veranstaltungen, § 42)."],"schutzziel":"Das Führen der vergleichsweise weniger gefährlichen Schreckschusswaffen geordnet erlauben – mit Identitäts- und Zuverlässigkeitsprüfung.","kennwerte":[{"l":"Erlaubt","v":"Schreckschuss · Reizgas · Signal (PTB-Zeichen)"},{"l":"Gültigkeit","v":"unbefristet"},{"l":"Nicht für","v":"scharfe Schusswaffen"}],"begriffe":["PTB-Zeichen im Kreis = Prüfzeichen der Physikalisch-Technischen Bundesanstalt; kennzeichnet zugelassene Schreckschuss-/Reizgas-/Signalwaffen.","Schreckschusswaffe = Waffe, die nur Knall/Reizstoff ausstößt, kein festes Geschoss durch einen Lauf treibt."],"abgrenzung":["Kleiner Waffenschein ≠ Waffenschein: Der Kleine gilt nur für Schreckschuss & Co. (unbefristet), der große für scharfe Waffen (3 Jahre).","BESITZ solcher Waffen (mit PTB-Zeichen) ist ab 18 ohne Erlaubnis möglich – nur das FÜHREN braucht den Kleinen Waffenschein."],"praxis":["Eine Schreckschusspistole darf man ab 18 zu Hause besitzen; sie in der Öffentlichkeit zu tragen, erfordert den Kleinen Waffenschein.","Im Wachdienst gilt auch hier: Führen nur mit Zustimmung des Arbeitgebers."],"visual":{"type":"compare","left":{"title":"Waffenschein","points":["Führen erlaubnispflichtiger Schusswaffen","maximal 3 Jahre, Verlängerung möglich","Sehr hohe Hürde: Bedürfnis/Gefährdung, Eignung, Zuverlässigkeit, Sachkunde, ggf. Versicherung"]},"right":{"title":"Kleiner Waffenschein","points":["Führen von SRS-Waffen mit PTB-Zeichen","grundsätzlich unbefristet","Erlaubt keine echten Schusswaffen. DGUV V23: Schreck-/Gas-Schusswaffen bei Wach- und Sicherungsaufgaben unzulässig."]}}},"visual":{"type":"compare","left":{"title":"Waffenschein","points":["Führen erlaubnispflichtiger Schusswaffen","maximal 3 Jahre, Verlängerung möglich","Sehr hohe Hürde: Bedürfnis/Gefährdung, Eignung, Zuverlässigkeit, Sachkunde, ggf. Versicherung"]},"right":{"title":"Kleiner Waffenschein","points":["Führen von SRS-Waffen mit PTB-Zeichen","grundsätzlich unbefristet","Erlaubt keine echten Schusswaffen. DGUV V23: Schreck-/Gas-Schusswaffen bei Wach- und Sicherungsaufgaben unzulässig."]}}},{"h":"§28 WaffG Bewachungsunternehmen","b":"Bedürfnis, Gefährdung, nur bei konkretem Auftrag, behördliche Prüfung","detail":{"titel":"§ 28 WaffG – Bewachungsunternehmen","kat":"Erlaubnisse · Bewachung","katCls":"waff","merksatz":"§ 28 WaffG regelt, unter welchen Voraussetzungen ein BEWACHUNGSUNTERNEHMEN Waffen erwerben, besitzen und an seine Wachpersonen überlassen darf – nämlich nur bei nachgewiesenem Bedürfnis für konkrete, gefährdete Aufträge. Die Wachperson braucht zudem Zuverlässigkeit und Sachkunde.","funktion":["Unternehmensbezug: Nicht die einzelne Wachperson, sondern das Bewachungsunternehmen erhält die waffenrechtliche Erlaubnis (für seine Bewachungsaufgaben).","Bedürfnis: Es muss ein konkretes Bedürfnis bestehen – etwa Aufträge mit erheblicher Gefährdung, die den Waffeneinsatz rechtfertigen.","Überlassen: Das Unternehmen darf die Waffe nur an zuverlässige, sachkundige Wachpersonen für den jeweiligen Auftrag überlassen."],"schutzziel":"Bewaffnung im Bewachungsgewerbe auf das Nötige beschränken und an Bedürfnis, Zuverlässigkeit und Sachkunde binden.","kennwerte":[{"l":"Erlaubnisträger","v":"das Bewachungsunternehmen"},{"l":"Voraussetzung","v":"konkretes Bedürfnis (gefährdeter Auftrag)"},{"l":"Überlassen an","v":"zuverlässige, sachkundige Wachperson"}],"begriffe":["Überlassen = einer anderen Person die tatsächliche Gewalt über die Waffe einräumen.","Bedürfnis (§ 28) = der gefährdungsbezogene Grund, der die Bewaffnung des Wachdienstes trägt."],"abgrenzung":["Die Erlaubnis nach § 28 ist auftrags-/unternehmensbezogen – sie macht nicht jede Wachperson generell zum berechtigten Waffenträger.","Sie ersetzt nicht die persönlichen Voraussetzungen (Zuverlässigkeit, Sachkunde) der Wachperson und die Zustimmung im Einzelfall."],"praxis":["Bewaffnete Bewachung ist die Ausnahme: Sie kommt nur bei besonders gefährdeten Objekten/Transporten (z. B. Geld- und Werttransporte) in Betracht.","Die Wachperson muss zuverlässig und waffensachkundig sein – sonst darf ihr keine Waffe überlassen werden."]},"visual":null},{"h":"Berufswaffenträger / Waffensachkunde","b":"§7/§28 WaffG; strengere Zuverlässigkeit; Verfassungsschutz-Abfrage","detail":{"titel":"Berufswaffenträger & Waffensachkunde","kat":"Erlaubnisse · Eignung","katCls":"waff","merksatz":"Wer im Wach- und Sicherungsdienst eine Schusswaffe führt, muss nach dem Waffenrecht ZUVERLÄSSIG, GEEIGNET und SACHKUNDIG sein, an der Waffe ausgebildet sein und regelmäßig an Schießübungen teilnehmen (DGUV Vorschrift 23). Sonst darf ihm der Umgang mit der Dienstwaffe nicht gestattet werden.","funktion":["Persönliche Voraussetzungen: zuverlässig, geeignet und sachkundig nach dem Waffenrecht (Waffensachkundeprüfung).","Ausbildung & Übung: an den Schusswaffen ausgebildet sein und regelmäßig an Schießübungen teilnehmen (DGUV V23).","Folge bei Versäumnis: Wer längere Zeit nicht übt, dem ist der Umgang mit der Dienstwaffe zu untersagen, bis er wieder regelmäßig und erfolgreich schießt."],"schutzziel":"Sicherstellen, dass nur wirklich befähigte Personen im Dienst eine Schusswaffe führen – zum Schutz aller Beteiligten.","kennwerte":[{"l":"Voraussetzung","v":"zuverlässig · geeignet · sachkundig"},{"l":"DGUV V23","v":"ausgebildet + regelmäßig Schießübungen"},{"l":"Bei Versäumnis","v":"Umgang mit Dienstwaffe untersagen"}],"begriffe":["Waffensachkunde = nachgewiesene Kenntnisse über Waffen, Munition und Recht (Sachkundeprüfung nach WaffG).","Geeignet = u. a. keine körperlichen/geistigen Mängel, die den sicheren Umgang ausschließen."],"abgrenzung":["Die allgemeine § 34a-Sachkunde ist NICHT die Waffensachkunde: Fürs Waffenführen ist die zusätzliche Waffensachkundeprüfung nötig.","Ein Mindestalter von 25 Jahren ist NICHT das Kriterium – entscheidend sind Ausbildung, Übung und Eignung."],"praxis":["Ein Schusswaffenträger, der acht Monate nicht geübt hat: Der Unternehmer muss ihm den Umgang mit der Dienstwaffe untersagen und darf ihn erst nach erneuter regelmäßiger Teilnahme wieder ausrüsten.","Reparaturen an der Waffe gehören NICHT zu den Pflichten des Trägers – defekte Waffen kommen zum Fachmann."]},"visual":null}],"quiz":[{"q":"Welche Aussagen zur Waffenbesitzkarte (WBK) sind gemäß WaffG richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die Erlaubnis zum Erwerb und Besitz von Schusswaffen wird durch Eintragung in einen Waffenschein erteilt","c":false},{"t":"Für die Erteilung einer Waffenbesitzkarte sind Art, Anzahl und Kaliber der Schusswaffen anzugeben","c":true},{"t":"Die Erlaubnis zum Erwerb gilt drei Monate, die zum Besitz wird auf ein Jahr befristet","c":false},{"t":"Der Erwerb ist binnen zwei Wochen der Behörde anzuzeigen und die WBK zur Eintragung vorzulegen","c":true}]},{"q":"Für welche Dauer wird ein Waffenschein in der Regel erteilt?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Neun Jahre","c":false},{"t":"Ein Jahr","c":false},{"t":"Sechs Jahre","c":false},{"t":"Drei Jahre","c":true}]},{"q":"Welche Aussagen zum Kleinen Waffenschein sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Er gilt nur für Schreckschuss-, Reizgas- und Signalwaffen mit PTB-Zeichen im Kreis","c":true},{"t":"Er wird unbefristet erteilt","c":true},{"t":"Er erlaubt auch das Führen scharfer Schusswaffen","c":false},{"t":"Er wird stets nur befristet auf ein Jahr erteilt","c":false}]},{"q":"Welche Aussagen zur Bewaffnung im Bewachungsgewerbe (§ 28 WaffG) sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Die waffenrechtliche Erlaubnis erhält das Bewachungsunternehmen, nicht automatisch jede einzelne Wachperson","c":true},{"t":"Voraussetzung ist ein konkretes Bedürfnis, etwa bei besonders gefährdeten Aufträgen (z. B. Geld- und Werttransporte)","c":true},{"t":"Das Unternehmen darf die Waffe nur an zuverlässige und sachkundige Wachpersonen überlassen","c":true},{"t":"Jede im Sicherheitsdienst tätige Person darf ohne weiteres eine Schusswaffe führen","c":false}]},{"q":"Welche Voraussetzungen müssen Schusswaffenträger im Wach- und Sicherungsdienst erfüllen (DGUV Vorschrift 23)?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Sie müssen an den Schusswaffen ausgebildet sein und regelmäßig an Schießübungen teilnehmen","c":true},{"t":"Sie müssen nach dem Waffenrecht zuverlässig, geeignet und sachkundig sein","c":true},{"t":"Sie müssen wegen der erforderlichen geistigen Reife das 25. Lebensjahr vollendet haben","c":false},{"t":"Sie müssen beschädigte Schusswaffen selbstständig und eigenverantwortlich reparieren können","c":false}]},{"q":"Welche Fristen gelten für die Waffenbesitzkarte, welche für den Waffenschein?","a":"Waffenbesitzkarte bis zum Erwerb einer Waffe gültig ein Jahr lang, nach dem Erwerb der Waffe unbefristet. Waffenschein benötigt man zum Führen einer Waffe und ist höchstens drei Jahre lang gültig, kann aber zweimal um je drei Jahre verlängert werden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Für was braucht man eine Waffenbesitzkarte?","a":"Für den Erwerb und Besitz einer Schusswaffe.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Wem kann man eine Waffe zur Aufbewahrung geben?","a":"- Solche Schusswaffen dürfen nur an Berechtigte (Waffenbesitzkarteninhaber) - an konzessionierte Waffenhändler, - einem Büchsenmacher zum Zwecke der Instandsetzung, - einer Person zur sicheren Aufbewahrung (Waffenschrank mind. DIN 1143 -1), sowie zum gewerbemäßigen oder nichtgewerbemäßigen Beförderung zu einem Berechtigten, überlassen werden","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist eine Waffenbesitzkarte (WBK) ?","a":"Ist eine waffenrechtliche Erlaubnis zum . . . erlaubt den Erwerb einer Waffe erlaubt den Besitz einer Waffe Frist zum Erwerb der Waffe gilt ein Jahr Waffenbesitzkarte ist grundsätzlich unbefristet gültig Mit der Waffenbesitzkarte ist auch der Transport der Waffe, zum Beispiel zum Schießstand.(hierfür ist der Personalausweis und die WBK mitzuführen)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Ausweispflichten gelten gemäß Waffengesetz ?","a":"Waffe erwerbenPersonalausweis & Waffenbesitzkarte (Erwerbserlaubnis) Waffe transportieren / verbringenPersonalausweis & Waffenbesitzkarte Waffe führenPersonalausweis & Waffenschein","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Für was braucht man einen Waffenschein?","a":"Für das Führen einer Schusswaffe.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was ist ein Waffenschein ?","a":"Eine waffenrechtliche Erlaubnis zum . . . Erlaubt das Führen einer Waffe (außerhalb des eigenen befriedeten Besitztums) Ist auf drei Jahre befristet, kann bis zu zweimal um jeweils drei Jahre verlängert werden Für das Führen einer Waffe ist, der Personalausweis und der Waffenschein mitzuführen.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was ist ein kleiner Waffenschein ?","a":"Eine waffenrechtliche Erlaubnis zum . . . erlaubt das Führen von Schreckschuss-; Reizstoff- und Signalwaffen wird grundsätzlich unbefristet erteilt !!! Hier ist keine Haftpflichtversicherung erforderlich !!!","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was wird für die Erteilung / Beantragung einer waffenrechtlichen Erlaubnis benötigt?","a":"Mindestens 18. Jahre alt Persönliche Eignung Zuverlässigkeit Bedürfnisnachweis Sachkundenachweis (z.B. Waffensachkunde, oder andere berufliche Ausbildung) Nachweis Haftpflichtversicherung – nur bei Beantragung eines Waffenscheines","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was sind gem. WaffG tragbare Gegenstände?","a":"Tragbare Gegenstände sind unter anderen nach ihrem Wesen dazu bestimmt, unter unmittelbarer Ausnutzung der Muskelkraft (z.B. Hieb- und Stosswaffen) oder unter Ausnutzung einer anderen mechanischen Energie (z.B. Reizstoff- sprühgerät, Schleuder) Verletzungen beizubringen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Führverbote für Waffen gibt es, gem. WaffG ?","a":"Führverbot auf öffentlichen Veranstaltungen(gilt für alle Waffen) Führverbot für Anscheinswaffen und bestimmte tragbare Gegenstände(gilt für Anscheinswaffen, Einhandmesser, Klingenlänge über 12cm, Hieb- & Stoßwaffen) Führverbot im öffentlichen Personennahverkehr (neu seit 10/2024)(gilt für alle Waffen)","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[{"scenario":"Ein Sicherheitsmitarbeiter möchte mit Kleinem Waffenschein eine SRS-Waffe im Objektschutz führen. Er meint: „Ist doch erlaubt.“","frage":"Reicht der Kleine Waffenschein für den Dienst?","loesung":"Der Kleine Waffenschein betrifft nur das Führen von SRS-Waffen mit PTB-Zeichen. Die DGUV Vorschrift 23 verbietet aber das Bereithalten und Führen von Schreck- oder Gas-Schusswaffen bei Wach- und Sicherungsaufgaben. Zusätzlich zählt die Dienstanweisung des Unternehmens — ohne klare Freigabe darf keine Waffe im Dienst geführt werden. Merke: Das Arbeitsschutzrecht kann enger sein als das, was privat möglich erscheint. Lösungskern: Privat erlaubt heißt beruflich noch lange nicht erlaubt."}]},{"n":4,"title":"Pflichten & Aufbewahrung","subtitle":"4 Konzepte · 15 Prüfungsfragen","cards":[{"h":"§36 Aufbewahrung","b":"Geeignetes Behältnis, getrennt von Munition, ungeladen; DIN/EN 1143-1","detail":{"titel":"§ 36 WaffG – Aufbewahrung","kat":"Pflichten · Aufbewahrung","katCls":"waff","merksatz":"Waffen und Munition sind so aufzubewahren, dass sie nicht ABHANDENKOMMEN und Unbefugte sie nicht an sich nehmen können. Erlaubnispflichtige Schusswaffen gehören in ein genormtes Sicherheitsbehältnis (mindestens Widerstandsgrad 0).","funktion":["Grundpflicht: die erforderlichen Vorkehrungen treffen, damit Waffen/Munition nicht abhandenkommen und kein Unbefugter Zugriff erlangt.","Sicherheitsbehältnis: erlaubnispflichtige Schusswaffen in einem genormten Behältnis (mind. Widerstandsgrad 0) aufbewahren.","Nachweis: Auf Verlangen der Behörde ist die sichere Aufbewahrung nachzuweisen."],"schutzziel":"Verhindern, dass legale Waffen gestohlen werden oder in falsche Hände geraten.","kennwerte":[{"l":"Ziel","v":"kein Abhandenkommen, kein Unbefugter"},{"l":"Behältnis","v":"genormt, mind. Widerstandsgrad 0"},{"l":"Nachweis","v":"auf Verlangen der Behörde"}],"begriffe":["Abhandenkommen = der unfreiwillige Verlust des Besitzes (z. B. Diebstahl).","Widerstandsgrad = genormtes Maß für die Einbruchsicherheit eines Behältnisses (0 = Mindeststandard hier)."],"abgrenzung":["Es ist NICHT vorgeschrieben, die Waffe in Einzelteile zu zerlegen oder in ‚feuerhemmenden‘ Tresoren zu lagern – maßgeblich ist das genormte Sicherheitsbehältnis.","Auch wesentliche Teile (Lauf, Verschluss) sind sicher zu verwahren – nicht nur die komplette Waffe."],"praxis":["Eine abschließbare Schreibtischschublade oder eine an der Wand verschraubte Alukiste genügt NICHT – es muss ein genormtes Sicherheitsbehältnis sein.","Munition und Waffe getrennt aufzubewahren ist sinnvoll; die zentrale Pflicht ist das normgerechte Behältnis und der Schutz vor Unbefugten."],"visual":{"type":"table","headers":["Sicherheitsbehältnis","Langwaffen","Kurzwaffen","Munition"],"rows":[["0, unter 200 kg","unbegrenzt","bis 5 Kurzwaffen","zulässig"],["0, ab 200 kg / gleichwertige Verankerung","unbegrenzt","bis 10 Kurzwaffen","zulässig"],["I oder höher","unbegrenzt","unbegrenzt","zulässig"]]}},"visual":{"type":"table","headers":["Sicherheitsbehältnis","Langwaffen","Kurzwaffen","Munition"],"rows":[["0, unter 200 kg","unbegrenzt","bis 5 Kurzwaffen","zulässig"],["0, ab 200 kg / gleichwertige Verankerung","unbegrenzt","bis 10 Kurzwaffen","zulässig"],["I oder höher","unbegrenzt","unbegrenzt","zulässig"]]}},{"h":"§37/§38 Anzeige- & Ausweispflicht","b":"Abhandenkommen melden; Transport Perso+WBK, Führen Perso+Waffenschein","detail":{"titel":"§ 37/§ 38 – Anzeige- & Ausweispflicht","kat":"Pflichten · Melden & Ausweisen","katCls":"waff","merksatz":"Der Waffenbesitzer muss bestimmte Ereignisse ANZEIGEN (§ 37) – etwa den Erwerb einer Waffe (binnen zwei Wochen) oder ihr Abhandenkommen – und beim Umgang die nötigen Papiere mitführen und auf Verlangen vorzeigen (§ 38: Ausweispflicht).","funktion":["Anzeigepflicht (§ 37): u. a. Erwerb einer erlaubnispflichtigen Waffe (binnen zwei Wochen) sowie Abhandenkommen/Verlust unverzüglich der Behörde melden.","Ausweispflicht (§ 38): beim Führen/Umgang die Erlaubnisdokumente (z. B. Waffenschein) und einen amtlichen Lichtbildausweis mitführen und auf Verlangen vorzeigen.","Form: Anzeigen i. d. R. schriftlich/elektronisch; die WBK ist zur Eintragung vorzulegen."],"schutzziel":"Den Behörden jederzeit Kontrolle ermöglichen – wer hat welche Waffe, und ist der Umgang gedeckt?","kennwerte":[{"l":"Anzeige (§ 37)","v":"Erwerb (2 Wochen), Verlust melden"},{"l":"Ausweis (§ 38)","v":"Erlaubnis + Lichtbildausweis mitführen"},{"l":"Form","v":"schriftlich/elektronisch, WBK vorlegen"}],"begriffe":["Anzeige = die Mitteilung eines waffenrechtlich relevanten Ereignisses an die Behörde.","Ausweispflicht = die Pflicht, beim Umgang die nötigen Papiere dabeizuhaben und vorzuzeigen."],"abgrenzung":["Anzeigen (Behörde informieren) ist etwas anderes als Mitführen/Vorzeigen (Kontrolle vor Ort): Beides sind eigene Pflichten.","Die Zwei-Wochen-Frist gilt für den Erwerb; das Abhandenkommen ist UNVERZÜGLICH (sofort) zu melden."],"praxis":["Beim Führen einer Schusswaffe immer Waffenschein UND Personalausweis dabei – fehlt der Ausweis, verletzt man die Ausweispflicht.","Wird eine Waffe gestohlen, muss man das sofort anzeigen – nicht erst ‚irgendwann‘."]},"visual":null},{"h":"§42 Verbote","b":"Führen bei öffentl. Veranstaltungen verboten; Waffenverbotszonen","detail":{"titel":"§ 42 WaffG – Verbote (öffentliche Veranstaltungen)","kat":"Pflichten · Verbote","katCls":"waff","merksatz":"§ 42 WaffG verbietet das FÜHREN von Waffen bei öffentlichen Veranstaltungen, Versammlungen, Aufzügen, Volksfesten, Sport- oder ähnlichen Veranstaltungen – grundsätzlich auch von Schreckschuss- und Hieb-/Stoßwaffen. Verstöße sind mit Strafe oder Bußgeld bewehrt.","funktion":["Verbotszonen: Bei öffentlichen Veranstaltungen, Versammlungen und Ansammlungen ist das Führen von Waffen grundsätzlich verboten.","Weite Reichweite: Das Verbot erfasst nicht nur scharfe Waffen, sondern z. B. auch Schreckschuss-, Reizgas- und Hieb-/Stoßwaffen.","Folgen: Ein Verstoß kann als Straftat oder Ordnungswidrigkeit geahndet werden."],"schutzziel":"Menschenansammlungen vor der besonderen Gefahr durch Waffen schützen.","kennwerte":[{"l":"Verbot","v":"Führen bei öffentlichen Veranstaltungen"},{"l":"Umfasst","v":"auch Schreckschuss-/Hieb-/Stoßwaffen"},{"l":"Verstoß","v":"Straftat oder Ordnungswidrigkeit"}],"begriffe":["Öffentliche Veranstaltung = ein für einen unbestimmten Personenkreis zugängliches Ereignis (Volksfest, Konzert, Sportevent).","Versammlung/Aufzug = Zusammenkunft mehrerer Personen, oft zur Meinungsäußerung."],"abgrenzung":["Auch wer eine Erlaubnis (z. B. Kleinen Waffenschein) hat, darf bei solchen Veranstaltungen die Waffe grundsätzlich NICHT führen – das Verbot geht vor.","Vom Verbot ausgenommen sind eng begrenzte Fälle (z. B. dienstlich Befugte im rechtlichen Rahmen)."],"praxis":["Türsteher/Ordner auf einem Volksfest dürfen sich nicht ‚zur Sicherheit‘ mit Schreckschusswaffe oder Schlagstock ausstatten – das Führen ist dort verboten.","Im Zweifel: Bei Veranstaltungen Waffen zu Hause lassen; der Kleine Waffenschein hilft hier nicht weiter."]},"visual":null},{"h":"Aufbewahrung nach BewachV","b":"DIN 1143-1 Grad 0/1; Unternehmer verantwortlich","detail":{"titel":"Aufbewahrung nach BewachV","kat":"Pflichten · Bewachung","katCls":"waff","merksatz":"Auch im Bewachungsgewerbe gelten die Aufbewahrungsregeln des WaffG: Dienstwaffen und Munition sind sicher und vor unbefugtem Zugriff geschützt zu verwahren – erlaubnispflichtige Schusswaffen in einem genormten Sicherheitsbehältnis (mindestens Widerstandsgrad 0). Die Dienstanweisung regelt den Umgang.","funktion":["Sichere Verwahrung: Dienstwaffen sind so aufzubewahren, dass Unbefugte (auch andere Mitarbeiter) keinen Zugriff haben.","Genormtes Behältnis: erlaubnispflichtige Schusswaffen in einem genormten Sicherheitsbehältnis (mind. Widerstandsgrad 0) – nicht in einfachen abschließbaren Möbeln.","Dienstanweisung: Der Gewerbetreibende regelt per Dienstanweisung u. a., dass Waffen nur mit seiner Zustimmung geführt werden dürfen."],"schutzziel":"Verhindern, dass Dienstwaffen im Betrieb verloren gehen oder von Unbefugten genutzt werden.","kennwerte":[{"l":"Behältnis","v":"genormt, mind. Widerstandsgrad 0"},{"l":"Zugriff","v":"nur Berechtigte, nicht Unbefugte"},{"l":"Dienstanweisung","v":"Waffen nur mit Zustimmung führen"}],"begriffe":["BewachV = Bewachungsverordnung; regelt Pflichten des Bewachungsgewerbes (u. a. Dienstanweisung).","Dienstanweisung = verbindliche Anweisung des Gewerbetreibenden an die Wachpersonen."],"abgrenzung":["Die BewachV ersetzt nicht das WaffG, sondern ergänzt es um betriebliche Pflichten (Dienstanweisung, Dokumentation).","Das genormte Sicherheitsbehältnis bleibt Pflicht – ein an die Wand geschraubter Stahlblechschrank oder eine Alukiste reichen nicht."],"praxis":["Dienstwaffen werden zwischen den Einsätzen im genormten Tresor verwahrt; die Ausgabe wird dokumentiert.","Die Dienstanweisung muss u. a. festhalten, dass Schuss-, Hieb-/Stoß- und Reizstoffwaffen nur mit Zustimmung des Gewerbetreibenden geführt werden dürfen."]},"visual":null}],"quiz":[{"q":"Welche Aussagen zur Aufbewahrung von Waffen und Munition (§ 36 WaffG) sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Es muss durch geeignete Maßnahmen unterbunden werden, dass Waffen oder Munition abhandenkommen","c":true},{"t":"Schusswaffen und Munition müssen in feuerhemmenden Tresoren aufbewahrt werden","c":false},{"t":"Es müssen Vorkehrungen getroffen werden, damit unbefugte Dritte die Waffe oder Munition nicht an sich nehmen können","c":true},{"t":"Schusswaffen müssen in ihre Einzelteile zerlegt und getrennt von der Munition aufbewahrt werden","c":false}]},{"q":"Welche Pflichten treffen den Waffenbesitzer nach Anzeige- und Ausweispflicht (§ 37/§ 38 WaffG)?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Den Erwerb einer erlaubnispflichtigen Waffe muss er innerhalb von zwei Wochen der Behörde anzeigen","c":true},{"t":"Das Abhandenkommen einer Waffe muss er unverzüglich anzeigen","c":true},{"t":"Beim Führen muss er die Erlaubnis (z. B. Waffenschein) und einen amtlichen Lichtbildausweis mitführen und auf Verlangen vorzeigen","c":true},{"t":"Beim Führen genügt es, die Waffe dabeizuhaben; Dokumente sind nicht erforderlich","c":false}]},{"q":"Welche Aussagen zum Waffenverbot bei öffentlichen Veranstaltungen (§ 42 WaffG) sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Das Führen von Waffen bei öffentlichen Veranstaltungen, Versammlungen und Volksfesten ist grundsätzlich verboten","c":true},{"t":"Das Verbot erfasst auch Schreckschuss-, Reizgas- und Hieb-/Stoßwaffen","c":true},{"t":"Ein Verstoß kann als Straftat oder Ordnungswidrigkeit geahndet werden","c":true},{"t":"Mit einem Kleinen Waffenschein darf man die Schreckschusswaffe trotzdem auf ein Volksfest mitführen","c":false}]},{"q":"In welchen Behältnissen sind erlaubnispflichtige Schusswaffen sicher aufzubewahren?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"In genormten Sicherheitsbehältnissen mindestens mit dem Widerstandsgrad 0","c":true},{"t":"In allen verschließbaren Behältnissen, z. B. abschließbaren Schubladen von Schreibtischen","c":false},{"t":"In fest verschraubten, abschließbaren Aluminiumkisten in Schränken","c":false},{"t":"In an der Wand befestigten Stahlblechschränken mit Sicherheitsschloss","c":false}]},{"q":"Wem kann man eine Waffe zur Aufbewahrung geben?","a":"- Solche Schusswaffen dürfen nur an Berechtigte (Waffenbesitzkarteninhaber) - an konzessionierte Waffenhändler, - einem Büchsenmacher zum Zwecke der Instandsetzung, - einer Person zur sicheren Aufbewahrung (Waffenschrank mind. DIN 1143 -1), sowie zum gewerbemäßigen oder nichtgewerbemäßigen Beförderung zu einem Berechtigten, überlassen werden","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Ausweispflichten gelten gemäß Waffengesetz ?","a":"Waffe erwerbenPersonalausweis & Waffenbesitzkarte (Erwerbserlaubnis) Waffe transportieren / verbringenPersonalausweis & Waffenbesitzkarte Waffe führenPersonalausweis & Waffenschein","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Verbotene Schusswaffen und verbotene Gegenstände?","a":"Der Erwerb oder das führen von verbotnen Waffen und Gegenständen ist verboten. Verbotene Schusswaffen: - Kriegswaffen (Maschinenpistole) - vollautomatische Schusswaffen - Vorderschaftsrepetierflinten mit Austauschschaft (Pistolengriff) = Pumpgun - Waffen, die ihrer Form nach geeignet sind, einen anderen Gegenstand vorzutäuschen (Stockgewehr, Schießkugelschreiber) - Waffen, die zusammengeklappt oder verkürzt oder zerlegt werden können (Wilderergewehr) Verbotene Gegenstände: - Stahlrute - Totschläger - Schlagringe - Wurfsterne - Butterflymesser, Nunchakus Besitz erlaubt, aber Führen (Öffentlichkeit) verboten - sogenannte Anscheinswaffen (Soft Air Waffen die echten täuschend ähnlich sind) - Einhandmesser - Teleskopschlagstock (ASP)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie Beispiele für Waffen, die nach dem Waffenrecht im Umgang verboten sind?","a":"Molotowcocktail Schießkugelschreiber Butterflymesser Springmesser Nun-Chakkus Wurfsterne Faustmesser Stahlrute Schlagring Totschläger Fallmesser Ungeprüfte Reizstoffsprühgeräte Vollautomatische Feuerwaffen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Führverbote für Waffen gibt es, gem. WaffG ?","a":"Führverbot auf öffentlichen Veranstaltungen(gilt für alle Waffen) Führverbot für Anscheinswaffen und bestimmte tragbare Gegenstände(gilt für Anscheinswaffen, Einhandmesser, Klingenlänge über 12cm, Hieb- & Stoßwaffen) Führverbot im öffentlichen Personennahverkehr (neu seit 10/2024)(gilt für alle Waffen)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wer ist von der Unterrichtung, wer von der Sachkundeprüfung befreit?","a":"- Personen die am 31.03.1996 in einem Bewachungsgewerbe tätig waren. (Stichtag: 01.04.1996/Unterrichtung) - Personen die am 01.01.2003 mindestens 3 Jahre ohne Unterbrechungen, befugt in einem Bewachungsgewerbe tätig waren/Sachkunde, Meister -, Fachkraft -, Servicekraft für Schutz und Sicherheit, Feldjäger Bundeswehr mittlerer Polizei- und Justizvollzugsdienstdienst (Befreiung von Unterrichtung und Sachkundeprüfung gemäß BewachV)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere aus der BewachV, Haftungssummen","a":"Personenschäden: 1.000.000,00 € Sachschäden: 250.000,00 € Abhandenkommen bewachter Sachen: 15.000,00 € Vermögensschäden: 12.500,00 € Bei Waffengebrauch: pauschal 1.000.000,00 für Personen- und Sachschäden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere aus der BewachV , Datenschutz","a":"Die in der Ausübung des Dienstes bekannt gewordenen Geschäfts- und Betriebs- geheimnisse Dritter, auch nach ihrem Ausscheiden nicht unbefugt zu offenbaren.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere aus der BewachV , Dienstanweisung","a":"- Führen von Schuss- Hieb- und Stosswaffen Reizstoffsprühgeräte nur in Absprache mit dem Gewerbetreibenden, - Rechte und Befugnisse (keine hoheitlichen Befugnisse) - Anzeigepflicht bei Gebrauch von Waffen o.ä. an Gewerbetreibenden und Polizei Der Gewerbetreibende hat der Wachperson einen Abdruck der Dienstanweisung sowie der DGUV Vorschrift 23 gegen Empfangsbescheinigung auszuhändigen.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere aus der BewachV , Dienstausweis","a":"Im Dienstausweis muss der Firmenname, Firmenanschrift, Name und Vorname des Mitarbeiters, Bewacherregister-Identifikationsnummer von Gewerbetreibenden und Mitarbeiter sowie Unterschriften des Gewerbetreibende und des Mitarbeiters vermerkt sein. Der Ausweis muss so beschaffen sein, dass er sich von amtlichen Ausweisen deutlich unterscheidet.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere aus der BewachV, Dienstkleidung","a":"Dienstkleidung muss beim Betreten des eingefriedeten Besitztums getragen werden. Sie darf nicht mit Uniformen der behördlichen Vollzugorgane verwechselt werden.","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Erläutere aus der BewachV, Aufbewahrung von Schusswaffen","a":"Aufbewahrung in einem geeigneten Behältnis DIN 1143-1 Grad 0 (bis zu 5 Kurzwaffen) oder Grad 1 (unbegrenzte Anzahl von Kurzwaffen). Kein Zugriff Dritter oder abhandenkommen muss gewährleistet sein. Unternehmer ist verantwortlich!","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was muss der Gewerbetreibende gem. BewachV mindestens in die Dienstanweisung aufnehmen?","a":"Wachpersonen haben nicht die Befugnisse von Polizeibeamten oder anderen Behörden Schusswaffen, Hieb- & Stoßwaffen sowie Reizstoffsprühgeräte dürfen nur mit Genehmigung des Gewerbetreibenden im Dienst geführt werden Gebrauch von Waffen ist unverzüglich der zuständigen Polizeidienststelle und dem Gewerbetreibenden zu melden Die Regelung zur Wahrung von Geschäftsgeheimnissen wird separat getroffen.","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Was müssen Wachpersonen beim Tragen von Dienstkleidung gem. BewachV beachten?","a":"Dienstkleidung muss sich von Uniformen der Vollzugsorgane (Polizei, Ordnungsamt, etc.) und Streitkräften (Bundeswehr) unterscheiden.(betrifft auch das Verwendungsverbot von Amtsabzeichen, wie Landeswappen, etc.) Beim Betreten von befriedetem Besitztum, im Dienst, ist Dienstkleidung zu tragen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Wer ist für die sichere Aufbewahrung von Waffen verantwortlich?","a":"Der Gewerbetreibende(Aufbewahrung, Ausgabe und Rücknahme)","multi":false,"tag":"Folien","src":"Folien","options":[]}],"cases":[]},{"n":5,"title":"Verbotene Waffen & Kennzeichnung","subtitle":"6 Konzepte · 7 Prüfungsfragen","cards":[{"h":"Verbotene Schusswaffen","b":"Kriegswaffen, vollautomatische, Pumpgun mit Pistolengriff, Stockgewehr, Schießkugelschreiber","detail":{"titel":"Verbotene Schusswaffen","kat":"Verbote · Schusswaffen","katCls":"waff","merksatz":"Bestimmte Schusswaffen sind GANZ VERBOTEN – Erwerb, Besitz und Führen sind untersagt. Dazu zählen u. a. vollautomatische (Kriegs-)Waffen, als andere Gegenstände getarnte Waffen und solche, die ohne weiteres in vollautomatische umgebaut werden können.","funktion":["Verbotene Schusswaffen: z. B. vollautomatische Schusswaffen sowie als Gebrauchsgegenstand getarnte Waffen (Schießkugelschreiber u. Ä.).","Umfang des Verbots: Erwerb, Besitz UND Führen sind untersagt – nicht nur das Tragen.","Rechtsgrundlage: Die Anlage 2 zum WaffG listet die verbotenen Waffen und Gegenstände auf."],"schutzziel":"Besonders gefährliche oder heimtückische Waffen vollständig aus dem Verkehr ziehen.","kennwerte":[{"l":"Beispiele","v":"Vollautomaten · getarnte Waffen"},{"l":"Verbot","v":"Erwerb + Besitz + Führen"},{"l":"Quelle","v":"Anlage 2 zum WaffG"}],"begriffe":["Vollautomatische Waffe = feuert bei einmaligem Abzug Dauerfeuer (mehrere Schuss).","Getarnte Waffe = Schusswaffe in Form eines harmlosen Gegenstands (z. B. Schießkugelschreiber)."],"abgrenzung":["Verbotene Waffen (gar nicht erlaubt) sind zu unterscheiden von erlaubnispflichtigen Waffen (mit Erlaubnis erlaubt) und von ‚Besitz erlaubt/Führen verboten‘-Fällen.","Halbautomatische Sportwaffen sind nicht per se verboten – verboten ist u. a. das Vollautomatische."],"praxis":["Wer eine verbotene Waffe besitzt, macht sich strafbar – hier hilft keine WBK und kein Waffenschein.","Im Dienst: Solche Gegenstände sind tabu; ein Fund ist wie jeder Waffenfund der Polizei zu übergeben."]},"visual":null},{"h":"Verbotene Gegenstände","b":"Stahlrute, Totschläger, Schlagring, Wurfstern, Butterflymesser, Nunchaku","detail":{"titel":"Verbotene Gegenstände (z. B. Schlagring)","kat":"Verbote · Gegenstände","katCls":"waff","merksatz":"Auch bestimmte tragbare Gegenstände sind VERBOTEN – etwa Schlagringe, Butterfly-(Spring-)Messer, Faustmesser oder Wurfsterne. Wer eine solche verbotene Waffe führt, macht sich strafbar; ein Schlag damit ist zugleich gefährliche Körperverletzung.","funktion":["Verbotene Gegenstände: u. a. Schlagringe, Totschläger, Stahlruten, Butterflymesser, Faustmesser, Wurfsterne (Anlage 2 zum WaffG).","Rechtsfolge: Erwerb, Besitz und Führen sind verboten und strafbar.","Zusammentreffen mit StGB: Wird ein solcher Gegenstand zum Verletzen eingesetzt, liegt regelmäßig gefährliche Körperverletzung (§ 224 StGB) vor."],"schutzziel":"Typische ‚Angriffswerkzeuge‘ ohne legitimen Zweck vollständig untersagen.","kennwerte":[{"l":"Beispiele","v":"Schlagring · Butterflymesser · Wurfstern"},{"l":"Verbot","v":"Erwerb + Besitz + Führen"},{"l":"Einsatz","v":"zugleich gefährliche KV (§ 224 StGB)"}],"begriffe":["Schlagring = um die Faust gelegtes Metallstück zur Verstärkung von Schlägen (verbotene Waffe).","Gefährliche Körperverletzung = KV u. a. mittels einer Waffe oder eines gefährlichen Werkzeugs (§ 224 StGB)."],"abgrenzung":["Verbotener Gegenstand (Schlagring) ≠ erlaubnispflichtige Waffe: Beim Schlagring gibt es keine Erlaubnis – er ist schlicht verboten.","Der waffenrechtliche Verstoß (Führen einer verbotenen Waffe) und die Körperverletzung sind zwei getrennte Vorwürfe, die zusammentreffen können."],"praxis":["Schlägt jemand mit einem Schlagring zu, macht er sich doppelt strafbar: wegen Führens einer verbotenen Waffe UND wegen gefährlicher Körperverletzung.","Findest du im Dienst einen solchen Gegenstand, behandelst du ihn wie eine Waffe: nicht aneignen, Polizei verständigen."]},"visual":null},{"h":"Besitz erlaubt, Führen verboten","b":"Anscheinswaffen (Softair), Einhandmesser, Teleskopschlagstock","detail":{"titel":"Besitz erlaubt – Führen verboten","kat":"Verbote · Mittelgruppe","katCls":"waff","merksatz":"Bei einigen Gegenständen ist der BESITZ erlaubt, das FÜHREN in der Öffentlichkeit aber grundsätzlich VERBOTEN – z. B. Einhandmesser und Anscheinswaffen. Man darf sie also zu Hause haben, aber nicht draußen mit sich tragen.","funktion":["Typische Fälle: Einhandmesser (mit einer Hand zu öffnen) und feststehende Messer mit Klinge über 12 cm sowie Anscheinswaffen.","Regel: Besitz erlaubt, aber Führen in der Öffentlichkeit grundsätzlich verboten (§ 42a WaffG).","Ausnahmen: Führen ausnahmsweise zulässig bei berechtigtem Interesse (z. B. Berufsausübung, Brauchtum, Sport)."],"schutzziel":"Gefährliche, aber nicht generell verbotene Gegenstände aus dem öffentlichen Raum heraushalten.","kennwerte":[{"l":"Erlaubt","v":"Besitz (z. B. zu Hause)"},{"l":"Verboten","v":"Führen in der Öffentlichkeit"},{"l":"Beispiele","v":"Einhandmesser · Anscheinswaffen"}],"begriffe":["Einhandmesser = Messer, dessen Klinge mit einer Hand geöffnet und festgestellt werden kann.","Anscheinswaffe = täuschend echt aussehende Nachbildung einer Feuerwaffe (verschießt keine Geschosse wie eine echte)."],"abgrenzung":["‚Besitz erlaubt/Führen verboten‘ ist die Mittelstufe zwischen verbotenen Waffen (gar nicht) und frei führbaren Gegenständen.","Faustfeuerwaffen sind erlaubnispflichtig (nicht bloß ‚führverboten‘); Schreckschusswaffen darf man mit Kleinem Waffenschein führen – sie gehören nicht in diese Gruppe."],"praxis":["Ein Einhandmesser darf man zu Hause besitzen, aber nicht ‚mal eben‘ in der Stadt mit sich führen – außer es liegt ein berechtigtes Interesse vor.","Anscheinswaffen (z. B. Soft-Air im Echtlook) gehören nicht in die Öffentlichkeit – das Führen ist verboten."]},"visual":null},{"h":"§42a Führverbot","b":"Anscheinswaffen, Hieb-/Stoßwaffen, Einhandmesser, feststehende Klinge >12 cm","detail":{"titel":"§ 42a WaffG – Führverbot in der Öffentlichkeit","kat":"Verbote · § 42a","katCls":"waff","merksatz":"§ 42a verbietet das FÜHREN bestimmter Gegenstände in der Öffentlichkeit: Anscheinswaffen, Hieb-/Stoßwaffen sowie Messer mit einhändig feststellbarer Klinge (Einhandmesser) und feststehende Messer mit Klinge über 12 cm. Ausnahme: berechtigtes Interesse.","funktion":["Erfasste Gegenstände: Anscheinswaffen, Hieb- und Stoßwaffen, Einhandmesser sowie feststehende Messer mit einer Klingenlänge über 12 cm.","Verbot: Das FÜHREN dieser Gegenstände in der Öffentlichkeit ist untersagt (der Besitz bleibt erlaubt).","Ausnahme: zulässig bei berechtigtem Interesse – etwa Berufsausübung, anerkanntem Brauchtum, Sport oder allgemein anerkanntem Zweck."],"schutzziel":"Das Mitführen gefährlich wirkender oder gefährlicher Gegenstände im öffentlichen Raum eindämmen.","kennwerte":[{"l":"Verbot","v":"Führen in der Öffentlichkeit"},{"l":"Erfasst","v":"Anscheinswaffen, Messer >12 cm, Einhandmesser"},{"l":"Ausnahme","v":"berechtigtes Interesse"}],"begriffe":["Anscheinswaffe = Nachbildung, die den Anschein einer echten Feuerwaffe erweckt.","Berechtigtes Interesse = anerkannter Grund (Beruf, Brauchtum, Sport), der das Führen ausnahmsweise erlaubt."],"abgrenzung":["§ 42a verbietet das FÜHREN (nicht den Besitz). Verbotene Waffen (z. B. Schlagring) sind dagegen ganz verboten – auch der Besitz.","Ein Küchenmesser auf dem Weg vom Geschäft nach Hause ist vom berechtigten Interesse gedeckt – das ‚griffbereite‘ Tragen ohne Grund nicht."],"praxis":["Ein großes feststehendes Messer (Klinge über 12 cm) darf man nicht grundlos in der Stadt tragen – beim Angeln oder Handwerk dagegen schon.","Anscheinswaffen gehören nie in die Öffentlichkeit – sie sind in Konfliktlagen besonders gefährlich (Verwechslung mit echter Waffe)."]},"visual":null},{"h":"Kennzeichnungen & Prüfzeichen","b":"Beschusszeichen, PTB-Zeichen für Schreckschusswaffen, BKA-Prüfsiegel","detail":{"titel":"Kennzeichnungen & Prüfzeichen","kat":"Verbote · Kennzeichen","katCls":"waff","merksatz":"Zugelassene Waffen tragen amtliche KENNZEICHEN: Schusswaffen müssen amtlich beschossen sein und ein anerkanntes BESCHUSSZEICHEN tragen; Schreckschuss-/Reizgas-/Signalwaffen ein PTB-Zeichen (im Kreis). Diese Zeichen belegen Prüfung und Zulassung.","funktion":["Beschusszeichen: Schusswaffen müssen amtlich geprüft (beschossen) sein und ein in Deutschland anerkanntes Beschusszeichen tragen.","PTB-Zeichen: Schreckschuss-, Reizgas- und Signalwaffen tragen das Zeichen der Physikalisch-Technischen Bundesanstalt (PTB) – beim Kleinen Waffenschein das ‚PTB im Kreis‘.","Anscheinswaffen: sind Nachbildungen, die den Anschein echter Feuerwaffen erwecken – sie verschießen keine Geschosse wie echte Waffen."],"schutzziel":"Sichtbar machen, dass eine Waffe amtlich geprüft und zugelassen ist – und ungeprüfte Waffen erkennbar machen.","kennwerte":[{"l":"Schusswaffen","v":"amtliches Beschusszeichen"},{"l":"Schreckschuss & Co.","v":"PTB-Zeichen (im Kreis)"},{"l":"Anscheinswaffe","v":"echt aussehende Nachbildung"}],"begriffe":["Beschusszeichen = amtliches Prüfzeichen, das die sichere Verwendbarkeit einer Schusswaffe bestätigt.","PTB = Physikalisch-Technische Bundesanstalt, die u. a. Schreckschusswaffen zulässt."],"abgrenzung":["Ein Hersteller- oder Herkunftszeichen ist KEIN Beschusszeichen – maßgeblich ist die amtliche Prüfung (anerkanntes Beschusszeichen).","Anscheinswaffen sehen aus wie Feuerwaffen, sind es aber nicht – sie ‚treiben keine Geschosse durch einen Lauf‘ wie echte Waffen."],"praxis":["Im Dienst geführte Schusswaffen müssen amtlich geprüft sein und ein anerkanntes Beschusszeichen tragen (DGUV V23).","Am PTB-Zeichen im Kreis erkennst du eine zugelassene Schreckschuss-/Reizgas-/Signalwaffe, die mit Kleinem Waffenschein geführt werden darf."]},"visual":null},{"h":"Rechtsfolgen WaffG","b":"OWi §53 (bis 10.000 €), Verbrechen §51, Vergehen §52","detail":{"titel":"Rechtsfolgen bei Verstößen (WaffG)","kat":"Verbote · Rechtsfolgen","katCls":"waff","merksatz":"Verstöße gegen das Waffenrecht haben Folgen: Sie reichen von Ordnungswidrigkeiten (Bußgeld) bis zu Straftaten (Geld- oder Freiheitsstrafe). Eine waffenrechtliche Verurteilung kann zudem die ZUVERLÄSSIGKEIT nach § 34a GewO entfallen lassen – und damit den Job kosten.","funktion":["Ordnungswidrigkeit: leichtere Verstöße (z. B. Verletzung von Anzeige-/Mitführpflichten) werden mit Bußgeld geahndet.","Straftat: z. B. Führen/Besitz verbotener Waffen oder Umgang ohne Erlaubnis – Geld- oder Freiheitsstrafe.","Gewerberechtliche Folge: Wer wegen eines Vergehens gegen das WaffG rechtskräftig zu einer Freiheitsstrafe verurteilt wurde, gilt i. d. R. fünf Jahre lang als unzuverlässig (§ 34a GewO)."],"schutzziel":"Verstöße wirksam ahnden und Unzuverlässige aus dem Bewachungsgewerbe fernhalten.","kennwerte":[{"l":"Leicht","v":"Ordnungswidrigkeit (Bußgeld)"},{"l":"Schwer","v":"Straftat (Geld-/Freiheitsstrafe)"},{"l":"§ 34a-Folge","v":"Unzuverlässigkeit (i. d. R. 5 Jahre)"}],"begriffe":["Ordnungswidrigkeit = rechtswidrige Handlung, die mit Geldbuße geahndet wird (keine Vorstrafe im engeren Sinn).","Zuverlässigkeit (§ 34a) = persönliche Voraussetzung für die Tätigkeit im Bewachungsgewerbe."],"abgrenzung":["Nicht jeder Verstoß ist eine Straftat: Anzeige-/Mitführpflichtverletzungen sind meist Ordnungswidrigkeiten; Umgang mit verbotenen Waffen ist Straftat.","Eine Geldstrafe wegen fahrlässiger Körperverletzung (90 Tagessätze) lässt die Zuverlässigkeit nicht automatisch entfallen – eine WaffG-Verurteilung zu Freiheitsstrafe dagegen regelmäßig schon."],"praxis":["Wer im Dienst eine verbotene Waffe führt, riskiert nicht nur Strafe, sondern auch den Verlust der Zuverlässigkeit – und damit die Tätigkeit im Wachgewerbe.","Schon das ‚nur dabeihaben‘ verbotener Gegenstände kann strafbar sein – im Zweifel: Finger weg, Polizei verständigen."]},"visual":null}],"quiz":[{"q":"Welche Aussagen zu verbotenen Schusswaffen sind richtig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Vollautomatische Schusswaffen sind grundsätzlich verboten","c":true},{"t":"Als Gebrauchsgegenstand getarnte Schusswaffen (z. B. Schießkugelschreiber) sind verboten","c":true},{"t":"Bei verbotenen Waffen sind Erwerb, Besitz und Führen untersagt","c":true},{"t":"Für verbotene Schusswaffen kann man mit entsprechendem Bedürfnis eine WBK erhalten","c":false}]},{"q":"Ein Türsteher wird von einem abgewiesenen Gast mit einem Schlagring niedergeschlagen. Macht sich der Gast strafbar?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Ja, wegen versuchten Hausfriedensbruchs gemäß § 123 StGB","c":false},{"t":"Ja, wegen des Führens einer nach dem WaffG verbotenen Waffe","c":true},{"t":"Ja, wegen gefährlicher Körperverletzung gemäß §§ 223, 224 StGB","c":true},{"t":"Ja, wegen fahrlässiger Körperverletzung gemäß §§ 223, 229 StGB","c":false}]},{"q":"Bei welchen Gegenständen ist der Besitz erlaubt, das Führen in der Öffentlichkeit aber grundsätzlich verboten?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Faustfeuerwaffen","c":false},{"t":"Schreckschusswaffen","c":false},{"t":"Einhandmesser","c":true},{"t":"Anscheinswaffen","c":true}]},{"q":"Was versteht man unter Anscheinswaffen?","a":"","multi":false,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Nachbildungen von Schusswaffen, die äußerlich den Anschein von Feuerwaffen hervorrufen","c":true},{"t":"Sie dürfen in der Öffentlichkeit geführt werden, da sie keine Gefahr für andere darstellen","c":false},{"t":"Gegenstände, die mit gebräuchlichen Werkzeugen so umgebaut werden können, dass mit ihnen Geschosse verschossen werden","c":false},{"t":"Waffen, mit denen Geschosse durch einen Lauf getrieben werden (Funktion echter Schusswaffen)","c":false}]},{"q":"Welche Schusswaffen dürfen im Wach- und Sicherungsdienst geführt werden?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Schusswaffen, die ein europäisches Herstellerzeichen tragen","c":false},{"t":"Schusswaffen, die von einem Sachkundigen eines Schützenvereins geprüft wurden","c":false},{"t":"Schusswaffen, die mindestens einmal jährlich durch Sachkundige hinsichtlich ihrer Handhabungssicherheit geprüft werden","c":true},{"t":"Schusswaffen, die amtlich geprüft sind und ein in der Bundesrepublik Deutschland anerkanntes Beschusszeichen tragen","c":true}]},{"q":"Wann ist eine Wachperson im Sinne des § 34a GewO in der Regel unzuverlässig?","a":"","multi":true,"tag":"Prüfung","src":"Prüfung","options":[{"t":"Wenn sie Mitglied in einer verfassungsfeindlichen Partei war und seit Beendigung der Mitgliedschaft noch keine zehn Jahre verstrichen sind","c":true},{"t":"Wenn sie wegen eines Vergehens gegen das WaffG rechtskräftig zu einer Freiheitsstrafe verurteilt wurde und seitdem noch keine fünf Jahre verstrichen sind","c":true},{"t":"Wenn sie wegen fahrlässiger Körperverletzung zu einer Geldstrafe von 90 Tagessätzen rechtskräftig verurteilt wurde","c":false},{"t":"Wenn sie Mitglied in einer zugelassenen politischen Partei ist und deren Ziele aktiv unterstützt","c":false}]},{"q":"Verbotene Schusswaffen und verbotene Gegenstände?","a":"Der Erwerb oder das führen von verbotnen Waffen und Gegenständen ist verboten. Verbotene Schusswaffen: - Kriegswaffen (Maschinenpistole) - vollautomatische Schusswaffen - Vorderschaftsrepetierflinten mit Austauschschaft (Pistolengriff) = Pumpgun - Waffen, die ihrer Form nach geeignet sind, einen anderen Gegenstand vorzutäuschen (Stockgewehr, Schießkugelschreiber) - Waffen, die zusammengeklappt oder verkürzt oder zerlegt werden können (Wilderergewehr) Verbotene Gegenstände: - Stahlrute - Totschläger - Schlagringe - Wurfsterne - Butterflymesser, Nunchakus Besitz erlaubt, aber Führen (Öffentlichkeit) verboten - sogenannte Anscheinswaffen (Soft Air Waffen die echten täuschend ähnlich sind) - Einhandmesser - Teleskopschlagstock (ASP)","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Nennen Sie Beispiele für Waffen, die nach dem Waffenrecht im Umgang verboten sind?","a":"Molotowcocktail Schießkugelschreiber Butterflymesser Springmesser Nun-Chakkus Wurfsterne Faustmesser Stahlrute Schlagring Totschläger Fallmesser Ungeprüfte Reizstoffsprühgeräte Vollautomatische Feuerwaffen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Waffen darf man besitzen, aber nicht führen?","a":"Messer mit Klingenlänge größer 12 cm Anscheinswaffen (z.B.: AirSoft, PaintBall) Schreckschuss- / Reizstoff- & Signalwaffen Armbrust Hieb- & Stoßwaffen (z.B.: Teleskopschlagstock) Druckluft- & Federdruckwaffen","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Führverbote für Waffen gibt es, gem. WaffG ?","a":"Führverbot auf öffentlichen Veranstaltungen(gilt für alle Waffen) Führverbot für Anscheinswaffen und bestimmte tragbare Gegenstände(gilt für Anscheinswaffen, Einhandmesser, Klingenlänge über 12cm, Hieb- & Stoßwaffen) Führverbot im öffentlichen Personennahverkehr (neu seit 10/2024)(gilt für alle Waffen)","multi":false,"tag":"Folien","src":"Folien","options":[]},{"q":"Welche Kennzeichnungen findet man auf der Waffe?","a":"Landeskürzel, Firmenname oder Markenname, Beschusszeichen, Ortszeichen des Beschussamtes","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Welche Zeichen lassen eine freie Waffe, also Gas- und Schreckschusswaffen erkennen?","a":"In Deutschland können legale Schreckschusswaffen am Prüfsiegel der Physikalisch-Technischen Bundesanstalt (PTB) erkannt werden. Merke: Wesentliche Teile bei Herkömmlichen Schusswaffen sind: Lauf Verschluss Patronenlager Griffstück (bei Kurzwaffen) Beschusszeichen: PTB Zeichen; Gas- Schreckschusspistole:","multi":false,"tag":"Skript","src":"Skript","options":[]},{"q":"Was sind gem. WaffG tragbare Gegenstände?","a":"Tragbare Gegenstände sind unter anderen nach ihrem Wesen dazu bestimmt, unter unmittelbarer Ausnutzung der Muskelkraft (z.B. Hieb- und Stosswaffen) oder unter Ausnutzung einer anderen mechanischen Energie (z.B. Reizstoff- sprühgerät, Schleuder) Verletzungen beizubringen.","multi":false,"tag":"Skript","src":"Skript","options":[]}],"cases":[{"scenario":"Ein Gast kommt zur Veranstaltung. In seiner Jackentasche befindet sich ein Einhandmesser. Er sagt: „Ist meins, darf ich besitzen.“","frage":"Welche Begriffe prüfst du, und welche Maßnahme ist sauber?","loesung":"Besitz kann erlaubt sein, Führen kann trotzdem verboten sein (§42a WaffG). Auf der Veranstaltung kommen zusätzlich Hausrecht und Einlassbedingungen dazu. Eine eigenmächtige Sicherstellung ist nicht erlaubt — richtig ist, den Zutritt zu verweigern oder eine freiwillige Abgabe nach einem klaren Verfahren anzubieten. Bei aggressivem Verhalten oder einer Straftat: Polizei rufen, auf den eigenen Schutz achten, alles dokumentieren. Lösungskern: Besitz ≠ Führen ≠ Zutrittsanspruch."}]}],"cardCount":24,"quizCount":88}];
